"""Recursive hierarchy walk: all reports under a manager, like a recursive CTE."""

node Employee {
    has name: str = "";
    has role: str = "";
}

edge ReportsTo { }

walker OrgQuery {
    has found_root: bool = False;
    has reports: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can seed with Employee entry {
        if not self.found_root {
            self.found_root = True;
            print(f"Root manager: {here.name} ({here.role})");
            visit [->:ReportsTo:->] else { disengage; }
        } else {
            visit [->:ReportsTo:->] else { disengage; }
        }
    }

    can collect with Employee exit {
        if here.name != "" and self.found_root and here.role != "Root" {
            self.reports.append(here.name);
        }
    }
}

walker ReportCollector {
    has depth: int = 0;
    has names: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can descend with Employee entry {
        indent = "--" * self.depth;
        print(f"{indent}{here.name} ({here.role}) at depth {self.depth}");
        self.depth += 1;
        visit [->:ReportsTo:->] else {
            self.depth -= 1;
            disengage;
        }
        self.depth -= 1;
    }
}

with entry {
    ada = Employee(name="Ada", role="CTO");
    root ++> ada;
    ada +>:ReportsTo:+> Employee(name="Bob", role="Team Lead");
    ada +>:ReportsTo:+> Employee(name="Cara", role="Team Lead");
    root spawn OrgQuery();
    root spawn ReportCollector();
}

