"""Dependency cycle check: hand-rolled UNION ALL path enumeration vs visited-set walk.

The issue: a recursive CTE with UNION ALL enumerates every distinct path on
fan-in/diamond graphs (exponential), patched by a depth cap. The Jac walker
below carries an explicit visited set (the UNION fix), so reachability is
O(V+E), terminates naturally on cycles, and needs no arbitrary depth cap.
"""

node Issue {
    has title: str = "";
    has status: str = "open";
}

edge Blocks {
    # 'blocks' direction: self blocking -> blocked
}

edge VerifiedBlocks {
    # dedup-flavored variant used after a visited-set pass (UNION semantics)
}

# Compatibility façade mirroring the original Go API surface.
def creates_cycle(check_root: Issue, target: Issue) -> bool {
    return check_root +>:Blocks:-> target;
}

walker CycleCheck {
    has visited: dict = {};
    has found_cycle: bool = False;
    has edges_walked: int = 0;

    can start with Root entry {
        visit [->:Blocks:->];
    }

    can probe with Issue entry {
        # Explicit visited set = the UNION fix: each node is walked once,
        # so diamond fan-in cannot re-enumerate duplicate paths.
        key = f"{here.title}";
        if key in self.visited {
            print(f"skip (already visited, UNION dedup): {here.title}");
            disengage;
        }
        self.visited[key] = True;
        print(f"scanning dependencies of: {here.title}");
        visit [->:Blocks:->] else {
            disengage;
        }
    }

    can report with Issue exit {
        self.edges_walked += 1;
    }
}

walker DetachVerified {
    can start with Root entry {
        visit [-->];
    }

    can strip with Issue exit {
        # After the check passes, upgrade edges to their verified flavor.
        targets = [t for t in [here ->:Blocks:->]];
        for t in targets {
            here +>:VerifiedBlocks:+> t;
            here del ->:Blocks:-> t;
        }
    }
}

with entry {
    # Diamond fan-in: 17-way style is reduced to 4 sources feeding one sink,
    # plus a diamond so a UNION ALL walk would visit the sink repeatedly.
    sink = Issue(title="deploy");
    a = Issue(title="build-a");
    b = Issue(title="build-b");
    c = Issue(title="build-c");
    d = Issue(title="build-d");
    root ++> sink;
    sink +>:Blocks:+> a +>:Blocks:+> d;
    sink +>:Blocks:+> b +>:Blocks:+> d;
    sink +>:Blocks:+> c +>:Blocks:+> d;
    # Genuine injected cycle: d blocks a again.
    d +>:Blocks:+> a;

    root spawn CycleCheck();

    # Behavior preserved: forward DAG direction stays clean.
    print(f"forward edge check creates_cycle(a->d): "
          f"{creates_cycle(a, d) and 'edge exists (valid dep)' or 'none'}");
}

