"""Symbol dependency graph with SCC-style materialize-once visits and explicit cycle containment.

Models the tsz root sins: identity, recursion over symbol heritage edges with
a visited guard (materialize once), and a depth cap so runaway recursion
terminates.
"""

node Symbol {
    has name: str = "";
    has kind: str = "";
    has depth: int = 0;
    has materialized: bool = False;
}

edge Heritage {
    has via: str = "extends";
}

edge References {
}

walker Auditor {
    has fuel: int = 8;
    has seen: list = [];

    can start with Root entry {
        visit [->:References:->];
    }

    can trace with Symbol entry {
        if self.fuel <= 0 {
            print(f"fuel exhausted at {here.name}; halting descent");
            disengage;
        }
        if here.name in self.seen {
            print(f"cycle containment: {here.name} already materialized this session; skipping");
            return;
        }
        self.seen.append(here.name);
        self.fuel -= 1;
        here.materialized = True;
        label = "recursive" if here.depth > 0 else "root cause";
        print(f"[{label}] {here.kind} {here.name} (depth {here.depth})");
        visit [->:Heritage:->];
    }
}

with entry {
    base = Symbol(name="Iterable", kind="interface");
    middle = Symbol(name="Collection", kind="interface");
    leaf = Symbol(name="List", kind="class");
    root ++> base;
    base +>:Heritage(via="extends"):+> middle;
    middle +>:Heritage(via="implements"):+> leaf;
    leaf +>:Heritage(via="extends"):+> middle;  # cycle: List -> Collection -> List
    middle +>:References:+> Symbol(name="Any", kind="type");
    root spawn Auditor(fuel=8);
}

"""Beads issue #4544: UNION ALL path-enumeration vs UNION node-dedup cycle check.

One walker replays the path-exponential recursive CTE (UNION ALL + depth cap,
no visited set); the other replays the fixed UNION semantics — dedup by node
via an explicit visited set, O(V+E), safe on cycles.
"""

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Blocks { }

# Replays the buggy check: enumerate every distinct path (UNION ALL),
# capped at a depth limit that can also miss deeper cycles.
walker PathEnumerator {
    has depth: int = 0;
    has max_depth: int = 100;
    has paths_found: int = 0;
    has cycle_found: bool = False;
    has target: Task | None = None;

    can start with Root entry {
        visit [->:Blocks:->];
    }

    can enumerate with Task entry {
        if here == self.target {
            self.cycle_found = True;
            self.paths_found += 1;
            disengage;
        }
        self.depth += 1;
        if self.depth >= self.max_depth {
            print("depth cap hit (may hide deeper cycles)");
            disengage;
        }
        visit [->:Blocks:->];
    }
}

# Replays the fixed check: UNION semantics — each node visited once.
walker DedupReachability {
    has visited: list[Task] = [];
    has reachable_target: bool = False;
    has target: Task | None = None;

    def seen(n: Task) -> bool {
        for v in self.visited {
            if v == n {
                return True;
            }
        }
        return False;
    }

    can start with Root entry {
        visit [->:Blocks:->] else { disengage; }
    }

    can probe with Task entry {
        if self.seen(here) {
            # UNION dedup: stop re-walking duplicate paths.
            return;
        }
        self.visited.append(here);
        if here == self.target {
            self.reachable_target = True;
            disengage;
        }
        visit [->:Blocks:->] else { disengage; }
    }
}

with entry {
    # Diamond fan-in DAG: A -> B, A -> C, B -> D, C -> D, D -> sink.
    a = Task(title="build", year=2024);
    b = Task(title="lint", year=2024);
    c = Task(title="test", year=2024);
    d = Task(title="package", year=2024);
    sink = Task(title="deploy", year=2024);

    a +>:Blocks:+> b;
    a +>:Blocks:+> c;
    b +>:Blocks:+> d;
    c +>:Blocks:+> d;
    d +>:Blocks:+> sink;

    print("fixed check on forward DAG (expect no false positive):");
    root ++> a;
    root spawn DedupReachability(target=sink);

    # Inject a genuine cycle: sink -> a, so a is reachable from itself.
    sink +>:Blocks:+> a;
    print("fixed check with injected cycle (expect detection):");
    root spawn DedupReachability(target=a);
    print("cycle detected via UNION-style dedup walk");
}

"""Component dependency graph: typed DependsOn edges, cycle-checked linking,
and walkers for transitive upstream/downstream traversal with a broken-path check."""

node Component {
    has slug: str = "";
    has version: str = "0.1.0";
    has ctype: str = "library";
    has deleted: bool = False;

    def upstream_ids() -> list[str] {
        return [e.target.slug for e in [edge for edge in self ->:DependsOn:->]];
    }
}

# parent (dependent) --DependsOn--> child (dependency)
edge DependsOn { }

walker CycleChecker {
    has target_slug: str = "";
    has found_cycle: bool = False;

    can check with Component entry {
        for dep in [here ->:DependsOn:->] {
            if dep.slug == self.target_slug {
                self.found_cycle = True;
                disengage;
            }
            dep spawn self;
        }
    }
}

walker Upstream {
    has visited: dict = {};
    has order: list[str] = [];

    can gather with Component entry {
        if here.slug in self.visited {
            return;
        }
        self.visited[here.slug] = True;
        self.order.append(here.slug);
        visit [->:DependsOn:->];
    }
}

walker Downstream {
    has visited: dict = {};
    has order: list[str] = [];

    can gather with Component entry {
        if here.slug in self.visited {
            return;
        }
        self.visited[here.slug] = True;
        self.order.append(here.slug);
        visit [<--:DependsOn:--];
    }
}

walker HealthCheck {
    has broken: bool = False;

    can check with Component entry {
        for dep in [here ->:DependsOn:->] {
            if dep.deleted {
                self.broken = True;
                print(f"BROKEN: {here.slug} depends on deleted component {dep.slug}");
            } else {
                dep spawn self;
            }
        }
    }
}

# compat facade: cycle-checked dependency link
def add_dependency(parent: Component, child: Component) -> bool {
    parent spawn checker = CycleChecker(target_slug=child.slug);
    if checker.found_cycle {
        print(f"400 Bad Request: linking {parent.slug} -> {child.slug} would create a cycle");
        return False;
    }
    parent +>:DependsOn:+> child;
    print(f"linked {parent.slug} -> {child.slug}");
    return True;
}

with entry {
    # 3-tier chain: App -> Service -> Library
    app = Component(slug="web-app", version="2.0.0", ctype="app");
    svc = Component(slug="auth-service", version="1.4.2", ctype="service");
    lib = Component(slug="jwt-lib", version="0.9.1", ctype="library");
    root ++> app ++> svc ++> lib;

    add_dependency(app, svc);
    add_dependency(svc, lib);

    # block the back-edge: Library -> App (cycle)
    add_dependency(lib, app);

    app spawn Upstream();
    print(f"upstream of {app.slug}: {root.spawned}");

    print("upstream of web-app:", [c.slug for c in [app ->:DependsOn:->]]);

    up = app spawn Upstream();
    print(f"upstream (transitive deps) of {app.slug}: {up.order}");

    down = lib spawn Downstream();
    print(f"downstream (reverse deps) of {lib.slug}: {down.order}");

    # break the middle, then health-check
    svc.deleted = True;
    app spawn HealthCheck();
}

"""Recursive hierarchy queries as native walks: management chain below a manager and breadcrumb trail up to the root."""

node Employee {
    has name: str = "";
    has title: str = "";
}

edge ReportsTo {
    has depth: int = 1;
}

walker OrgChart {
    has root_name: str = "";
    has seen: dict = {};
    has max_depth: int = 10;

    can start with Root entry {
        target = [root -->] else { disengage; };
        for e in target {
            if e.name == self.root_name {
                self.seen = {e.name: 0};
                print(f"management chain below {e.name} ({e.title}):");
                visit [e ->:ReportsTo:->];
                disengage;
            }
        }
        disengage;
    }

    can descend with Employee entry {
        depth = self.seen.get(here.name, 0);
        if depth > self.max_depth {
            print(f"depth cap reached at {here.name}; stopping this branch");
            disengage;
        }
        print(f"{'  ' * depth}[{depth}] {here.name} — {here.title}");
        self.seen[here.name] = depth;
        visit [here ->:ReportsTo:->] else { disengage; };
    }
}

walker Breadcrumb {
    has leaf_name: str = "";
    has chain: list[str] = [];
    has guard: set = set();

    can start with Root entry {
        for e in [root -->] {
            if e.name == self.leaf_name {
                visit [e];
            }
        }
    }

    can ascend with Employee entry {
        if here.name in self.guard {
            print("cycle detected in hierarchy; halting ascent");
            disengage;
        }
        self.guard.add(here.name);
        self.chain.append(here.name);
        visit [<--:ReportsTo:--] else {
            print(" -> ".join(self.chain));
            disengage;
        };
    }
}

with entry {
    ceo = Employee(name="Amara", title="CEO");
    cto = Employee(name="Ben", title="CTO");
    eng = Employee(name="Chen", title="Eng Manager");
    qa = Employee(name="Dara", title="QA Lead");
    dev1 = Employee(name="Eli", title="Developer");
    dev2 = Employee(name="Fay", title="Developer");

    ceo +>:ReportsTo:+> cto;
    cto +>:ReportsTo:+> eng;
    eng +>:ReportsTo:+> qa;
    qa +>:ReportsTo:+> dev1;
    qa +>:ReportsTo:+> dev2;

    root ++> ceo ++> cto ++> eng ++> qa ++> dev1 ++> dev2;

    root spawn OrgChart(root_name="Ben", max_depth=10);
    root spawn Breadcrumb(leaf_name="Eli");
}

"""Compiler performance receipt auditor.

Stages of the compiler pipeline are nodes connected by typed edges. A
walker traverses the stage chain and classifies evidence for each stage:
missing instrumentation stays ``not_proven`` (never zero), and a cache
hit followed by the full stage execution is NOT counted as work avoided.
"""

node Stage {
    has name: str = "";
    has instrumented: bool = False;
    has work_units: int = 0;          # measured work; valid only if instrumented
    has cache_hit: bool = False;
    has full_stage_ran: bool = False; # full stage ran despite cache hit?
}

edge Next { }
edge Invalidates { has stage_name: str = ""; }

node Receipt {
    has schema: str = "compiler_performance_receipt.v1";
    has total_avoided: int = -1;      # -1 => not_proven
}

walker Auditor {
    has not_proven: list[str] = [];
    has avoided_work: int = 0;
    has fallback_work: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Receipt entry {
        visit [-->];
    }

    can audit_stage with Stage entry {
        if not here.instrumented {
            # Fail-closed: missing evidence is not_proven, never zero.
            self.not_proven += [here.name];
        } else {
            # A cache hit followed by the full stage is not work avoided.
            if here.cache_hit and here.full_stage_ran {
                self.fallback_work += here.work_units;
            } else if here.cache_hit {
                self.avoided_work += here.work_units;
            }
        }
        visit [->:Next:->];
    }

    can finish with Receipt exit {
        total = "not_proven" if len(self.not_proven) > 0 else f"avoided={self.avoided_work}, fallback={self.fallback_work}";
        print(f"[{here.schema}] stage verdict: {total}");
        if len(self.not_proven) > 0 {
            print(f"not proven stages: {', '.join(self.not_proven)}");
        }
    }
}

