"""Beads issue #4544: UNION ALL path-enumeration vs UNION node-dedup cycle check.

One walker replays the path-exponential recursive CTE (UNION ALL + depth cap,
no visited set); the other replays the fixed UNION semantics — dedup by node
via an explicit visited set, O(V+E), safe on cycles.
"""

edge Blocks { }

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

# Replays the buggy check: enumerate every distinct path (UNION ALL),
# capped at a depth limit that can also miss deeper cycles.
walker PathEnumerator {
    has depth: int = 0;
    has max_depth: int = 100;
    has paths_found: int = 0;
    has cycle_found: bool = False;
    has target: Task | None = None;

    can start with Root entry {
        visit [->:Blocks:->];
    }

    can enumerate with Task entry {
        if here == self.target {
            self.cycle_found = True;
            self.paths_found += 1;
            disengage;
        }
        self.depth += 1;
        if self.depth >= self.max_depth {
            print("depth cap hit (may hide deeper cycles)");
            disengage;
        }
        visit [->:Blocks:->];
    }
}

# Replays the fixed check: UNION semantics — each node visited once.
walker DedupReachability {
    has visited: list[Task] = [];
    has reachable_target: bool = False;
    has target: Task | None = None;

    def seen(n: Task) -> bool {
        for v in self.visited {
            if v == n {
                return True;
            }
        }
        return False;
    }

    can start with Root entry {
        visit [->:Blocks:->] else { disengage; }
    }

    can probe with Task entry {
        if self.seen(here) {
            # UNION dedup: stop re-walking duplicate paths.
            return;
        }
        self.visited.append(here);
        if here == self.target {
            self.reachable_target = True;
            disengage;
        }
        visit [->:Blocks:->] else { disengage; }
    }
}

with entry {
    # Diamond fan-in DAG: A -> B, A -> C, B -> D, C -> D, D -> sink.
    a = Task(title="build", year=2024);
    b = Task(title="lint", year=2024);
    c = Task(title="test", year=2024);
    d = Task(title="package", year=2024);
    sink = Task(title="deploy", year=2024);

    a +>:Blocks:+> b;
    a +>:Blocks:+> c;
    b +>:Blocks:+> d;
    c +>:Blocks:+> d;
    d +>:Blocks:+> sink;

    print("fixed check on forward DAG (expect no false positive):");
    root ++> a;
    root spawn DedupReachability(target=sink);

    # Inject a genuine cycle: sink -> a, so a is reachable from itself.
    sink +>:Blocks:+> a;
    print("fixed check with injected cycle (expect detection):");
    root spawn DedupReachability(target=a);
    print("cycle detected via UNION-style dedup walk");
}

"""Safe archive/delete demo: live dependency scan over typed reference edges with cycle guard."""

node FieldDef {
    has key: str = "";
    has state: str = "ACTIVE";  # ACTIVE | ARCHIVED | PENDING_PURGE | TOMBSTONE
}

edge ReferencedBy {
    has usage: str = "";
}

node Artifact {
    has name: str = "";
    has kind: str = "";  # layout | view | report | workflow | import
}

edge DependsOn { }

walker Archive {
    has field_key: str = "";
    has refs: list = [];

    can start with Root entry {
        visit [->:ReferencedBy:->];
    }

    can scan with FieldDef entry {
        if here.key != self.field_key {
            disengage;
        }
        here.state = "ARCHIVED";
        print(f"archived field {here.key}");
        visit [->:ReferencedBy:->] else { disengage; }
    }

    can check_blocker with Artifact entry {
        self.refs.append(f"{here.kind}:{here.name}");
        print(f"  used by {here.kind} '{here.name}'");
    }
}

walker Purge {
    has field_key: str = "";
    has blockers: list = [];

    can start with Root entry {
        visit [->:ReferencedBy:->];
    }

    can live_scan with FieldDef entry {
        if here.key != self.field_key {
            disengage;
        }
        if here.state != "ARCHIVED" {
            print(f"{here.key}: gate refuses - field not in ARCHIVED state");
            disengage;
        }
        visit [->:ReferencedBy:->];
    }

    can trace with Artifact entry {
        # transitive live traversal with explicit visited guard (no builtin dedupe)
        visited: list = [here.name];
        frontier: list = [here];
        depth: int = 0;
        while frontier and depth < 10 {
            nxt: list = [];
            for art in frontier {
                self.blockers.append(f"{art.kind}:{art.name}");
                for dep in [art -->] {
                    skip = False;
                    for seen in visited {
                        if seen == dep.name { skip = True; }
                    }
                    if skip { continue; }
                    visited.append(dep.name);
                    nxt.append(dep);
                }
            }
            frontier = nxt;
            depth += 1;
        }
        if depth >= 10 {
            self.blockers.append("DEPTH_CAP: fail-closed, assume referenced");
        }
        if len(self.blockers) > 0 {
            print(f"{self.field_key}: HARD STOP, purge blocked by {len(self.blockers)} live dependency path(s)");
            for b in self.blockers {
                print(f"  - {b}");
            }
        } else {
            print(f"{self.field_key}: no live references, safe to purge");
        }
    }
}

walker Restore {
    has field_key: str = "";

    can start with Root entry {
        visit [-->];
    }

    can flip with FieldDef entry {
        if here.key == self.field_key and here.state == "ARCHIVED" {
            here.state = "ACTIVE";
            print(f"restored {here.key} back to ACTIVE");
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    field = FieldDef(key="visa_status");
    layout = Artifact(name="Mission Page", kind="layout");
    report = Artifact(name="Field Leader Rollup", kind="report");
    view = Artifact(name="My Missions", kind="view");
    workflow = Artifact(name="Onboarding Flow", kind="workflow");

    root +>:ReferencedBy(usage="tenant-1"):+> field;
    field +>:ReferencedBy:+> layout;
    field +>:ReferencedBy:+> report;
    layout +>:DependsOn:+> view;
    view +>:DependsOn:+> workflow;
    workflow +>:DependsOn:+> layout;  # cycle among artifacts, capped traversal fails closed

    root spawn Archive(field_key="visa_status");
    root spawn Purge(field_key="visa_status");
    root spawn Restore(field_key="visa_status");
}

"""Compiler performance receipt auditor.

Stages of the compiler pipeline are nodes connected by typed edges. A
walker traverses the stage chain and classifies evidence for each stage:
missing instrumentation stays ``not_proven`` (never zero), and a cache
hit followed by the full stage execution is NOT counted as work avoided.
"""

node Stage {
    has name: str = "";
    has instrumented: bool = False;
    has work_units: int = 0;          # measured work; valid only if instrumented
    has cache_hit: bool = False;
    has full_stage_ran: bool = False; # full stage ran despite cache hit?
}

edge Next { }
edge Invalidates { has stage_name: str = ""; }

node Receipt {
    has schema_name: str = "compiler_performance_receipt.v1";
    has total_avoided: int = -1;      # -1 => not_proven
}

walker Auditor {
    has missing_stages: list[str] = [];
    has avoided_work: int = 0;
    has fallback_work: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Receipt entry {
        visit [-->];
    }

    can audit_stage with Stage entry {
        if here.instrumented {
            # A cache hit followed by the full stage is not work avoided.
            if here.cache_hit and here.full_stage_ran {
                self.fallback_work += here.work_units;
            } else if here.cache_hit {
                self.avoided_work += here.work_units;
            }
        } else {
            # Fail-closed: missing evidence is not_proven, never zero.
            self.missing_stages += [here.name];
        }
        visit [->:Next:->];
    }

    can finish with Receipt exit {
        verdict = "not_proven" if len(self.missing_stages) > 0 else f"avoided={self.avoided_work}, fallback={self.fallback_work}";
        print(f"[{here.schema_name}] stage verdict: {verdict}");
        if len(self.missing_stages) > 0 {
            print(f"not proven stages: {', '.join(self.missing_stages)}");
        }
    }
}

with entry {
    rcpt = Receipt();
    parse = Stage(name="lex/parse", instrumented=True, work_units=40, cache_hit=True, full_stage_ran=True);
    hir = Stage(name="HIR", instrumented=True, work_units=30, cache_hit=True, full_stage_ran=False);
    pir = Stage(name="PIR lowering", instrumented=True, work_units=25, cache_hit=False);
    inv = Stage(name="interface invalidation", instrumented=False);  # missing instrumentation
    prov = Stage(name="provider projection", instrumented=True, work_units=10, cache_hit=False);

    rcpt ++> parse ++> hir ++> pir ++> inv ++> prov;
    pir +>:Invalidates(stage_name="PIR lowering"):+> inv;

    root ++> rcpt;
