"""Beads issue #4544: path-exponential UNION ALL cycle check vs O(V+E) UNION dedup.

PathEnumerator replays the buggy check: enumerate every distinct path
(UNION ALL) under an arbitrary depth cap. DedupReachability replays the
fixed UNION semantics: dedup by node via an explicit visited set, so
reachability is O(V+E) and terminates naturally on cycles.
"""

edge Blocks {
    has kind: str = "blocks";
}

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

walker PathEnumerator {
    has depth: int = 0;
    has max_depth: int = 100;
    has paths_found: int = 0;
    has cycle_found: bool = False;

    can start with Root entry {
        visit [->:Blocks:->];
    }

    can enumerate with Task entry {
        if here.year == 9999 {
            self.cycle_found = True;
            self.paths_found += 1;
            disengage;
        }
        self.depth += 1;
        if self.depth >= self.max_depth {
            print("depth cap hit; cycles deeper than the cap may be missed");
            disengage;
        }
        visit [->:Blocks:->];
    }
}

walker DedupReachability {
    has visited: list = [];
    has reachable: bool = False;

    def seen(n: Task) -> bool {
        for v in self.visited {
            if v is n {
                return True;
            }
        }
        return False;
    }

    can start with Root entry {
        visit [->:Blocks:->] else { disengage; }
    }

    can probe with Task entry {
        if self.seen(here) {
            return;
        }
        self.visited.append(here);
        if here.year == 9999 {
            self.reachable = True;
            disengage;
        }
        visit [->:Blocks:->] else { disengage; }
    }
}

with entry {
    # Diamond fan-in DAG: a -> b, a -> c, b -> d, c -> d, d -> sink.
    a = Task(title="build", year=2024);
    b = Task(title="lint", year=2024);
    c = Task(title="test", year=2024);
