"""Symbol dependency graph with materialize-once visits and explicit cycle containment.

Models the tsz root sins: identity, recursion over symbol heritage edges with
a visited guard (materialize once), and a fuel cap so runaway recursion
terminates.
"""

node Symbol {
    has name: str = "";
    has kind: str = "";
    has depth: int = 0;
    has materialized: bool = False;
}

edge Heritage {
    has via: str = "extends";
}

edge References {
}

walker Auditor {
    has fuel: int = 8;
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can trace with Symbol entry {
        if self.fuel <= 0 {
            print(f"fuel exhausted at {here.name}; halting descent");
            disengage;
        } else {
            if here.name in self.seen {
                print(f"cycle containment: {here.name} already materialized this session; skipping");
            } else {
                self.seen.append(here.name);
                self.fuel -= 1;
                here.materialized = True;
                label = "recursive" if here.depth > 0 else "root cause";
                print(f"[{label}] {here.kind} {here.name} (depth {here.depth})");
            }
            visit [->:Heritage:->];
        }
    }
}

with entry {
    base = Symbol(name="Iterable", kind="interface");
    middle = Symbol(name="Collection", kind="interface");
    leaf = Symbol(name="List", kind="class");
    root ++> base;
    base +>:Heritage(via="extends"):+> middle;
    middle +>:Heritage(via="implements"):+> leaf;
    leaf +>:Heritage(via="extends"):+> middle;  # cycle: List -> Collection -> List
    middle +>:References:+> Symbol(name="Any", kind="type");
    root spawn Auditor(fuel=8);
}

