"""Symbol dependency graph with materialize-once visits and explicit cycle containment.

Models the tsz root sins: identity, recursion over symbol heritage edges with
a visited guard (materialize once), and a fuel cap so runaway recursion
terminates. Re-visitations are fully cut off: on a cycle hit the walker
neither re-materializes nor re-descends, so traversal terminates.
"""

node Symbol {
    has name: str = "";
    has kind: str = "";
    has depth: int = 0;
    has materialized: bool = False;
}

edge Heritage {
    has via: str = "extends";
}

edge References {
}

walker Auditor {
    has fuel: int = 8;
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can trace with Symbol entry {
        if here.name in self.seen {
            print(f"cycle containment: {here.name} already materialized this session; cutting descent");
            disengage;
        }
        if self.fuel <= 0 {
            print(f"fuel exhausted at {here.name}; halting descent");
            disengage;
        }
        self.seen.append(here.name);
        self.fuel -= 1;
        here.materialized = True;
        label = "recursive" if here.depth > 0 else "root cause";
        print(f"[{label}] {here.kind} {here.name} (depth {here.depth})");
        visit [->:Heritage:->];
    }
}

with entry {
    base = Symbol(name="Iterable", kind="interface");
    middle = Symbol(name="Collection", kind="interface", depth=1);
    leaf = Symbol(name="List", kind="class", depth=2);
    root ++> base;
    base +>:Heritage(via="extends"):+> middle;
    middle +>:Heritage(via="implements"):+> leaf;
    leaf +>:Heritage(via="extends"):+> middle;  # cycle: List -> Collection -> List
    middle +>:References:+> Symbol(name="Any", kind="type");
    root spawn Auditor(fuel=8);
}

"""Gas City Reaper: recursive workflow-root sweep that outlives a 15s read timeout.

Models the essential scenario from issue #5383: the Dolt listener's
read_timeout bounds the gap between result rows, killing the Reaper's
recursive workflow-root query. Here the recursion is done natively in
process with walkers and typed edges — no per-row timer can fire — and
the legacy cycle guard (visited set + depth cap) is preserved explicitly
since jac walkers do not dedupe visitation on cyclic graphs.
"""

node Workflow {
    has wf_id: str = "";
    has depth: int = 0;
}

node ReaperQuery {
    has name: str = "";
    has read_timeout_millis: int = 0;
}

edge ParentOf {
    has via: str = "";
}

edge SweepTarget {
}

walker ReaperSweep {
    has visited: list[str] = [];
    has max_depth: int = 10;
    has candidates: list[str] = [];
    has killed_by_timeout: bool = False;

    def seen(node_id: str) -> bool {
        for v in self.visited {
            if v == node_id {
                return True;
            }
        }
        return False;
    }

    can start with Root entry {
        # The managed Dolt default (15s) would abort this sweep if it
        # were a row-producing SQL query; in-process it cannot be killed.
        timeout_label = "15s listener cap" if self.timeout_source() == 15000 else "custom cap";
        print(f"Reaper sweep starting (listener read timeout: {timeout_label})");
        visit [->:SweepTarget:->] else { disengage; }
    }

    def timeout_source() -> int {
        return 15000;
    }

    can descend with Workflow entry {
        # Cycle guard and depth cap are domain logic and must survive.
        if self.seen(here.wf_id) or here.depth > self.max_depth {
            disengage;
        }
        self.visited.append(here.wf_id);
        self.candidates.append(here.wf_id);
        print(f"candidate root: {here.wf_id} (depth {here.depth})");
        visit [->:ParentOf:->] else { disengage; }
    }

    can report with ReaperQuery entry {
        # In go-mysql-server this row would only arrive if produced
        # within read_timeout_millis of the previous row; natively the
        # full result always lands.
        here.read_timeout_millis = 15000;
        print(f"query '{here.name}' returned {len(self.candidates)} roots before timeout could fire");
        self.killed_by_timeout = False;
    }
}

with entry {
    alpha = Workflow(wf_id="wf-alpha", depth=1);
    beta = Workflow(wf_id="wf-beta", depth=2);
    gamma = Workflow(wf_id="wf-gamma", depth=3);
    # A cycle: gamma points back through the graph — the legacy guard
    # must prevent the sweep from looping forever.
    alpha +>:ParentOf(via="parent"):+> beta;
    beta +>:ParentOf(via="parent"):+> gamma;
    gamma +>:ParentOf(via="parent"):+> beta;

    q = ReaperQuery(name="workflow_root_candidates_cte");
    root +>:SweepTarget:+> alpha;
    root +>:SweepTarget:+> q;
    root spawn ReaperSweep(max_depth=10);
}

