"""SBOM dependency tree: lift parallel-array relationships into typed edges
and render the hierarchy with a tree walker that detects cycles and caps depth."""

node Package {
    has name: str = "";
    has version: str = "";
    has purl: str = "";
    has license: str = "";
    has vulnerability_count: int = 0;
}

node Sbom {
    has sbom_id: str = "";
}

edge Describes { }
edge DependsOn {
    has rel_type: str = "DEPENDS_ON";
}

walker TreeBuilder {
    has max_depth: int = 10;
    has visited: dict = {};
    has total_nodes: int = 0;
    has max_depth_seen: int = 0;

    can start with Sbom entry {
        print(f"Building dependency tree for SBOM {here.sbom_id}");
        visit [->:Describes:->];
    }

    def status(pkg: Package) -> str {
        if pkg.vulnerability_count > 0 { return "red"; }
        if pkg.license == "" { return "orange"; }
        return "green";
    }

    def render(pkg: Package, depth: int) -> str {
        indent = "  " * depth;
        flag = " [cycle]" if self.visited.get(pkg.purl, False) else "";
        return f"{indent}{pkg.name}@{pkg.version} ({self.status(pkg)}){flag}";
    }

    can build with Package entry {
        depth = 0;
        if here.purl in self.visited {
            print(f"{self.render(here, depth)} -- cycle pruned");
            disengage;
        }
        self.visited[here.purl] = True;
        self.total_nodes += 1;
        print(self.render(here, depth));
        self.walk_children(depth + 1);
        visit [-->] else { disengage; }
    }

    def walk_children(depth: int) {
        if depth > self.max_depth {
            print(f"  depth limit {self.max_depth} reached, pruning subtree");
            return;
        }
        if depth > self.max_depth_seen { self.max_depth_seen = depth; }
        for child in [here->:DependsOn:->] {
            if child.purl in self.visited {
                print(f"{'  ' * depth}{child.name}@{child.version} -- cycle detected, not expanded");
                continue;
            }
            self.visited[child.purl] = True;
            self.total_nodes += 1;
            print(f"{'  ' * depth}{child.name}@{child.version} ({self.status(child)})");
            child.spawn self;
        }
    }
}

walker FlatLister {
    can list with Sbom entry {
        print("No relationship data fallback: flat package list");
        for pkg in [-->] {
            print(f"  {pkg.name}@{pkg.version}");
        }
    }
}

