"""Component dependency graph: typed DependsOn edges, cycle-checked linking,
and walkers for transitive upstream/downstream traversal with a broken-path check."""

node Component {
    has slug: str = "";
    has version: str = "0.1.0";
    has ctype: str = "library";
    has deleted: bool = False;
}

# parent (dependent) --DependsOn--> child (dependency)
edge DependsOn { }

walker CycleChecker {
    has target_slug: str = "";
    has found_cycle: bool = False;
    has seen: dict[str, bool] = {};

    can check with Component entry {
        if here.slug in self.seen {
            disengage;
        }
        self.seen[here.slug] = True;
        if here.slug == self.target_slug {
            self.found_cycle = True;
            disengage;
        }
        visit [->:DependsOn:->] else { disengage; }
    }
}

walker Upstream {
    has seen: dict[str, bool] = {};
    has order: list[str] = [];

    can gather with Component entry {
        if here.slug in self.seen {
            disengage;
        }
        self.seen[here.slug] = True;
        self.order.append(here.slug);
        visit [->:DependsOn:->] else { disengage; }
    }
}

walker Downstream {
    has seen: dict[str, bool] = {};
    has order: list[str] = [];

    can gather with Component entry {
        if here.slug in self.seen {
            disengage;
        }
        self.seen[here.slug] = True;
        self.order.append(here.slug);
        visit [<--:DependsOn:--] else { disengage; }
    }
}

walker HealthCheck {
    has broken: bool = False;
    has seen: dict[str, bool] = {};

    can check with Component entry {
        if here.slug in self.seen {
            disengage;
        }
        self.seen[here.slug] = True;
        if here.deleted {
            self.broken = True;
            print(f"BROKEN: path reaches deleted component {here.slug}");
        }
        visit [->:DependsOn:->] else { disengage; }
    }
}

# compat facade: cycle-checked dependency link
def add_dependency(parent: Component, child: Component) -> bool {
    chk = CycleChecker(target_slug=parent.slug);
    child spawn chk;
    if chk.found_cycle {
        print(f"400 Bad Request: linking {parent.slug} -> {child.slug} would create a cycle");
        return False;
    }
    parent +>:DependsOn:+> child;
    print(f"linked {parent.slug} -> {child.slug}");
    return True;
}

with entry {
    # 3-tier chain: App -> Service -> Library
    app = Component(slug="web-app", version="2.0.0", ctype="app");
    svc = Component(slug="auth-service", version="1.4.2", ctype="service");
    lib = Component(slug="jwt-lib", version="0.9.1", ctype="library");
    root ++> app;
    root ++> svc;
    root ++> lib;

    add_dependency(app, svc);
    add_dependency(svc, lib);

    # block the back-edge: Library -> App (cycle)
    add_dependency(lib, app);

    up = Upstream();
    app spawn up;
    print(f"upstream (transitive deps) of {app.slug}: {up.order}");

    down = Downstream();
    lib spawn down;
    print(f"downstream (reverse deps) of {lib.slug}: {down.order}");

    # break the middle, then health-check the path from the app
    svc.deleted = True;
    hc = HealthCheck();
    app spawn hc;
    status = "BROKEN" if hc.broken else "HEALTHY";
    print(f"health check of {app.slug} dependency paths: {status}");
}

"""Evidence-summary producer: walks requirement -> test -> oracle fact graph
and emits a bounded TestEvidenceSummaryV1-style projection per test, keeping
cycle safety explicit (jac walkers have no built-in dedupe)."""

node Requirement {
    has req_id: str = "";
    has needs_variant: str = "";   # e.g. "Error::Boundary"
}

node RustTest {
    has package: str = "";
    has test_name: str = "";
    has source_file: str = "";
}

edge Asserts {
    has oracle_kind: str = "unknown";       # variant_equality | is_err | smoke
    has oracle_text: str = "";
    has strength: str = "broad";            # exact | broad
}

edge Covers {
    has relation: str = "name_proximity";
    has confidence: float = 0.5;
}

edge MissingDiscriminator {
    has kind: str = "";   # exact_error_variant | boundary_input | effect_observer
}

walker EvidenceProducer {
    has visited: dict = {};
    has summaries: list = [];

    can start with Root entry {
        visit [->:Covers:->];
    }

    can project with Requirement entry {
        if here.req_id in self.visited {
            print(f"cycle guard: already summarized {here.req_id}");
            disengage;
        }
        self.visited[here.req_id] = True;
        visit [->:Asserts:->];
    }

    can summarize with RustTest entry {
        strength = "exact" if any(
            [e for e in here.edges_to_parent if e.strength == "exact"]
        ) else "broad";
        gaps = [m.kind for m in here.edges_from_parent if isinstance(m, MissingDiscriminator)];
        status = "bounded" if strength == "exact" and not gaps else "insufficient";
        summary = {
            "test": here.test_name,
            "package": here.package,
            "strength": strength,
            "missing": gaps,
            "status": status,
        };
