"""Gas City Reaper: recursive workflow-root sweep that outlives a 15s read timeout.

Models the essential scenario from issue #5383: the Dolt listener's
read_timeout bounds the gap between result rows, killing the Reaper's
recursive workflow-root query. Here the recursion is done natively in
process with walkers and typed edges — no per-row timer can fire — and
the legacy cycle guard (visited set + depth cap) is preserved explicitly
since jac walkers do not dedupe visitation on cyclic graphs.
"""

node Workflow {
    has wf_id: str = "";
    has depth: int = 0;
}

node ReaperQuery {
    has name: str = "";
    has read_timeout_millis: int = 15000;
}

edge ParentOf {
    has via: str = "";
}

edge SweepTarget { }

walker ReaperSweep {
    has visited: list[str] = [];
    has max_depth: int = 10;
    has candidates: list[str] = [];

    def seen(node_id: str) -> bool {
        for v in self.visited {
            if v == node_id {
                return True;
            }
        }
        return False;
    }

    can start with Root entry {
        # The managed Dolt default (15s) would abort this sweep if it were
        # a row-producing SQL query; in-process it cannot be killed.
        print(f"Reaper sweep starting under managed listener config");
        visit [->:SweepTarget:->] else { disengage; }
    }

    can descend with Workflow entry {
        # Cycle guard and depth cap are domain logic and must survive.
        if not (self.seen(here.wf_id) or here.depth > self.max_depth) {
            self.visited.append(here.wf_id);
            self.candidates.append(here.wf_id);
            print(f"candidate root: {here.wf_id} (depth {here.depth})");
            visit [->:ParentOf:->] else { disengage; }
        } else {
            disengage;
        }
    }

    can report with ReaperQuery entry {
        # In go-mysql-server this row would only arrive if produced within
        # read_timeout_millis of the previous row; natively the full result
        # always lands.
        label = "15s listener cap" if here.read_timeout_millis == 15000 else "custom cap";
        print(f"query '{here.name}' ({label}) returned {len(self.candidates)} roots before any timeout could fire");
        visit [-->] else { disengage; }
    }
}

with entry {
    alpha = Workflow(wf_id="wf-alpha", depth=1);
    beta = Workflow(wf_id="wf-beta", depth=2);
    gamma = Workflow(wf_id="wf-gamma", depth=3);
    # A cycle: gamma points back to beta — the legacy guard must prevent
    # the sweep from looping forever.
    alpha +>:ParentOf(via="parent"):+> beta;
    beta +>:ParentOf(via="parent"):+> gamma;
    gamma +>:ParentOf(via="parent"):+> beta;

    q = ReaperQuery(name="workflow_root_candidates_cte");
    root +>:SweepTarget:+> alpha;
    root +>:SweepTarget:+> q;
    root spawn ReaperSweep(max_depth=10);
}

"""Safe archive/delete demo: live dependency scan over typed reference edges with cycle guard."""

node FieldDef {
    has key: str = "";
    has state: str = "ACTIVE";  # ACTIVE | ARCHIVED | PENDING_PURGE | TOMBSTONE
}

edge ReferencedBy {
    has usage: str = "";
}

node Artifact {
    has name: str = "";
    has kind: str = "";  # layout | view | report | workflow | import

    def neighbors() -> list[Artifact] {
        return [->:DependsOn:->];
    }
}

edge DependsOn { }

walker Archive {
    has field_key: str = "";
    has refs: list[str] = [];

    can start with Root entry {
        visit [->:ReferencedBy:->];
    }

    can scan with FieldDef entry {
        if here.key != self.field_key {
            disengage;
        }
        here.state = "ARCHIVED";
        print(f"archived field {here.key}");
        visit [->:ReferencedBy:->] else { disengage; }
    }

    can check_blocker with Artifact entry {
        self.refs.append(f"{here.kind}:{here.name}");
        print(f"  used by {here.kind} '{here.name}'");
    }
}

walker Purge {
    has field_key: str = "";
    has blockers: list[str] = [];

    can start with Root entry {
        visit [->:ReferencedBy:->];
    }

    can live_scan with FieldDef entry {
        if here.key != self.field_key {
            disengage;
        }
        if here.state != "ARCHIVED" {
            print(f"{here.key}: gate refuses - field not in ARCHIVED state");
            disengage;
        }
        visit [->:ReferencedBy:->];
    }

    can trace with Artifact entry {
        # transitive live traversal with explicit visited guard (no builtin dedupe)
        visited = [here.name];
        frontier = [here];
        depth = 0;
        while frontier and depth < 10 {
            nxt = [];
            for art in frontier {
                self.blockers.append(f"{art.kind}:{art.name}");
                for dep in art.neighbors() {
                    skip = False;
                    for seen in visited {
                        if seen == dep.name {
                            skip = True;
                        }
                    }
                    if skip {
                        continue;
                    }
                    visited.append(dep.name);
                    nxt.append(dep);
                }
            }
            frontier = nxt;
            depth += 1;
        }
        if depth >= 10 {
            self.blockers.append("DEPTH_CAP: fail-closed, assume referenced");
        }
        if len(self.blockers) > 0 {
            print(f"{self.field_key}: HARD STOP, purge blocked by {len(self.blockers)} live dependency path(s)");
            for b in self.blockers {
                print(f"  - {b}");
            }
        } else {
            print(f"{self.field_key}: no live references, safe to purge");
        }
    }
}

walker Restore {
    has field_key: str = "";

    can start with Root entry {
        visit [-->];
    }

    can flip with FieldDef entry {
        if here.key == self.field_key and here.state == "ARCHIVED" {
            here.state = "ACTIVE";
            print(f"restored {here.key} back to ACTIVE");
        }
        visit [-->] else { disengage; }
    }
}

