"""Compiler artifact cache: generation-aware reuse with reverse-dependency invalidation.

Source edits invalidate their module's artifacts; interface (public signature)
changes additionally cascade invalidation through typed DependsOn edges to
importers and their descendants, bumping generation counters. Depth cap and
visited set guard cycles.
"""

node SourceFile {
    has path: str = "";
    has content_digest: str = "";
}

node Module {
    has name: str = "";
    has generation: int = 1;
    has artifact: str = "";
    has artifact_valid: bool = False;
}

node Interface {
    has fingerprint: str = "";
}

edge Owns { }
edge DependsOn {
    has via_interface: bool = False;
}
edge Declares { }

walker Invalidator {
    has generation: int = 1;
    has reason: str = "";
    has depth_cap: int = 16;
    has invalidated: int = 0;

    can start with SourceFile entry {
        print(f"invalidating artifacts of source {here.path} ({self.reason})");
        visit [->:Owns:->];
    }

    can bump_module with Module entry {
        here.generation += 1;
        here.artifact_valid = False;
        here.artifact = "";
        self.invalidated += 1;
        print(f"  invalidated {here.name} (gen {here.generation})");
        if self.depth_cap > 0 {
            self.depth_cap -= 1;
            visit [->:DependsOn:->] else { disengage; }
        } else {
            print("  depth cap reached; refusing deeper cascade");
            disengage;
        }
    }

    can bump_interface with Interface entry {
        print(f"  interface fingerprint {here.fingerprint} changed; cascading to importers");
        visit [->:DependsOn:<--];
    }
}

walker Consumer {
    has requested_digest: str = "";

    can start with SourceFile entry {
        if here.content_digest == self.requested_digest {
            visit [->:Owns:->];
        } else {
            print(f"key inputs incomplete for {here.path}: cache miss");
            disengage;
        }
    }

    can lookup with Module entry {
        if here.artifact_valid {
            print(f"  HIT: reuse {here.artifact} for {here.name} (gen {here.generation})");
        } else {
            print(f"  STALE_REJECTED: recompute {here.name} at gen {here.generation}");
        }
    }
}

