    root spawn Consumer(requested_digest="abc123");
}

"""Evidence-summary producer: walks the requirement -> test -> oracle fact
graph and emits a bounded TestEvidenceSummaryV1-style projection per test,
keeping the cycle guard explicit (jac walkers do not dedupe visits)."""

node Requirement {
    has req_id: str = "";
    has needs_variant: str = "";
}

node RustTest {
    has package: str = "";
    has test_name: str = "";
    has source_file: str = "";
}

node OracleFact {
    has oracle_kind: str = "unknown";   # variant_equality | is_err | smoke
    has oracle_text: str = "";
    has strength: str = "broad";        # exact | broad
}

node Gap {
    has kind: str = "";                 # exact_error_variant | boundary_input | effect_observer
}

edge Covers {
    has relation: str = "name_proximity";
    has confidence: float = 0.5;
}

edge Asserts { }

edge HasGap { }

walker EvidenceProducer {
    has visited: dict = {};
    has summaries: list = [];
    has cur_strength: str = "broad";
    has cur_oracle: str = "";
    has cur_gaps: list = [];

    can start with Root entry {
        visit [->:Covers:->];
    }

    can enter_req with Requirement entry {
        if here.req_id in self.visited {
            print(f"cycle guard: already summarized {here.req_id}");
            disengage;
        }
        self.visited[here.req_id] = True;
        visit [->:Covers:->];
    }

    can enter_test with RustTest entry {
        if here.test_name in self.visited {
            disengage;
        }
        self.visited[here.test_name] = True;
        self.cur_strength = "broad";
        self.cur_oracle = "";
        self.cur_gaps = [];
        visit [->:Asserts:->];
        visit [->:HasGap:->] else {
            print(f"no gaps recorded for {here.test_name}");
        }
    }

    can collect_oracle with OracleFact entry {
        self.cur_oracle = here.oracle_text;
        if here.strength == "exact" {
            self.cur_strength = "exact";
        }
    }

    can collect_gap with Gap entry {
        self.cur_gaps.append(here.kind);
    }

    can summarize with RustTest exit {
        bounded = self.cur_strength == "exact" and not self.cur_gaps;
        status = "bounded" if bounded else "insufficient";
        self.summaries.append({
            "test": here.test_name,
            "package": here.package,
            "strength": self.cur_strength,
            "missing": self.cur_gaps,
            "status": status,
        });
        for gap in self.cur_gaps {
            print(f"[GAP] {here.test_name}: missing {gap}");
        }
        print(f"[{status.upper()}] {here.package}::{here.test_name} "
              f"asserts {self.cur_strength} ({self.cur_oracle})");
    }
}

