"""SBOM dependency tree: parallel-array relationships become typed edges;
a walker renders the hierarchy with a path-based cycle guard and depth cap."""

node Sbom {
    has sbom_id: str = "";
}

node Package {
    has name: str = "";
    has version: str = "";
    has purl: str = "";
    has license: str = "";
    has vulnerability_count: int = 0;
}

edge Describes { }
edge DependsOn { }

walker TreeBuilder {
    has max_depth: int = 10;
    has path: list = [];
    has total_nodes: int = 0;

    def status(pkg: Package) -> str {
        if pkg.vulnerability_count > 0 { return "red"; }
        if pkg.license == "" { return "orange"; }
        return "green";
    }

    def render(pkg: Package) -> str {
        indent = "  " * len(self.path);
        return f"{indent}{pkg.name}@{pkg.version} ({self.status(pkg)})";
    }

    can start with Sbom entry {
        print(f"Dependency tree for SBOM {here.sbom_id}");
        visit [->:Describes:->];
    }

    can build with Package entry {
        if here.purl in self.path {
            print(f"{self.render(here)} [cycle -- not expanded]");
            disengage;
        }
        if len(self.path) >= self.max_depth {
            print(f"{'  ' * self.max_depth}{here.name}@{here.version} [depth limit {self.max_depth} reached, pruned]");
            disengage;
        }
        self.total_nodes += 1;
        print(self.render(here));
        self.path.append(here.purl);
        visit [->:DependsOn:->];
    }
}

walker FlatLister {
    can list with Sbom entry {
        print(f"SBOM {here.sbom_id} has no relationship data; flat list fallback:");
        visit [-->];
    }

    can show with Package entry {
        print(f"  {here.name}@{here.version}");
        visit [-->] else { disengage; }
    }
}

