walker Remover {
    has visited: dict = {};
    has levels: dict = {};
    has cycles: list = [];

    can start with Root entry {
        visit [->:Support:->];
    }

    can order with Object entry {
        # Cycle policy (the fix from the issue): never reprocess a node.
        if here.name in self.visited {
            self.cycles.append(here.name);
            return;
        }
        self.visited[here.name] = True;
        level = self.levels.get(here.name, 0);
        self.levels[here.name] = level;
        print(f"remove {here.name} at support level {level}");
        for below in [here->:Support:->] {
            new_level = level + 1;
            old = self.levels.get(below.name, 0);
            if below.name not in self.visited and new_level > old {
                self.levels[below.name] = new_level;
            }
            visit [below];
        }
        visit [-->] else { disengage; }
    }
}

