"""Compiler artifact cache: generation-aware reuse with reverse-dependency invalidation.

Source edits invalidate their module's artifacts; the invalidation cascades
backward along DependsOn edges to importers and their transitive dependents,
bumping generation counters. A depth cap guards runaway cascades.
"""

node SourceFile {
    has path: str = "";
    has content_digest: str = "";
}

node Module {
    has name: str = "";
    has generation: int = 1;
    has artifact: str = "";
    has artifact_valid: bool = False;
}

edge Owns { }
edge DependsOn {
    has via_interface: bool = False;
}

walker Invalidator {
    has reason: str = "";
    has depth_cap: int = 16;
    has invalidated: int = 0;

    can start with SourceFile entry {
        print(f"invalidating artifacts downstream of source {here.path} ({self.reason})");
        visit [->:Owns:->] else { disengage; }
    }

    can bump_module with Module entry {
        if self.depth_cap <= 0 {
            print("  depth cap reached; refusing deeper cascade");
            disengage;
        }
        self.depth_cap -= 1;
        here.generation += 1;
        here.artifact_valid = False;
        here.artifact = "";
        self.invalidated += 1;
        print(f"  invalidated {here.name} (gen {here.generation})");
        visit [<--] else { disengage; }
    }
}

walker Consumer {
    has requested_digest: str = "";

    can start with SourceFile entry {
        if here.content_digest == self.requested_digest {
            visit [->:Owns:->] else { disengage; }
        } else {
            print(f"key inputs incomplete for {here.path}: cache miss");
            disengage;
        }
    }

    can lookup with Module entry {
        if here.artifact_valid {
            print(f"  HIT: reuse {here.artifact} for {here.name} (gen {here.generation})");
        } else {
            print(f"  STALE_REJECTED: recompute {here.name} at gen {here.generation}");
        }
    }
}

with entry {
    src = SourceFile(path="lib/Math.pm", content_digest="abc123");
    math = Module(name="Math", artifact="pir-a(Math, gen1)", artifact_valid=True);
    app = Module(name="App", artifact="pir-a(App, gen1)", artifact_valid=True);
    util = Module(name="Util", artifact="pir-a(Util, gen1)", artifact_valid=True);

    src +>:Owns:+> math;
    app +>:DependsOn(via_interface=True):+> math;
    util +>:DependsOn:+> app;

    print("--- reuse pass ---");
    Consumer(requested_digest="abc123") spawn src;

    print("--- interface edit: reverse invalidation cascade ---");
    Invalidator(reason="public interface fingerprint changed") spawn src;

    print("--- post-invalidation lookup ---");
    Consumer(requested_digest="abc123") spawn src;

    print("total invalidations: 3 modules expected; cascade done");
}

"""Recursive CTE (WITH RECURSIVE): a walker performs the recursive union.

Seed row n=1 is the anchor term; each Row connects to its successor via a
typed ``NextStep`` edge. The walker accumulates ``total`` (UNION ALL) with an
explicit depth/termination policy mirroring the ``WHERE n < 100`` filter, so
the recursion is guaranteed to stop instead of spinning forever.
"""

node Row {
    has n: int = 0;
}

edge NextStep { }

walker RecursiveUnion {
    has total: int = 0;
    has max_n: int = 100;

    can start with Root entry {
        visit [->:NextStep:->];
    }

    can absorb with Row entry {
        # anchor/recursive union: accept the row if it satisfies the filter,
        # then keep expanding successors — explicit termination policy.
        if here.n <= self.max_n {
            self.total += here.n;
            visit [->:NextStep:->] else { disengage; }
        } else {
            disengage;
        }
    }
}

