    # Build chain 1 -> 2 -> ... -> 101 (101 proves the WHERE n < 100 cutoff).
    prev = Row(n=1);
    root ++> prev;
    for i in range(2, 102) {
        cur = Row(n=i);
        prev +>:NextStep:+> cur;
        prev = cur;
    }
    w = RecursiveUnion();
    root spawn w;
    print(f"WITH RECURSIVE t(n) sum = {w.total} (expected 5050)");
}

