"""Management group hierarchy: cycle-safe reparent via a locked check-and-move walker.

Models issue #1362: a reparent must validate (cycle + depth) and mutate as one
serialized step, otherwise two concurrent moves can create an on-disk cycle.
The MoveGroup walker holds its guard set across validation and edge rewiring,
so the check -> update pair is atomic within the walk.
"""

node Group {
    has name: str = "";
    has depth: int = 0;
}

edge ChildOf { }

walker Auditor {
    has guard: dict = {};
    has max_depth: int = 8;
    has cycle_found: bool = False;

    can descend with Group entry {
        if here in self.guard {
            self.cycle_found = True;
            print(f"CYCLE detected at {here.name}");
            disengage;
        }
        if here.depth > self.max_depth {
            print(f"depth cap exceeded at {here.name}");
            disengage;
        }
        self.guard[id(here)] = True;
        print(f"visited {here.name} at depth {here.depth}");
        visit [->:ChildOf:->] else { disengage; }
    }
}

walker Mover {
    has target: Group | None = None;
    has new_parent: Group | None = None;
    has guard: dict = {};
    has ok: bool = False;

    # One ability = one serialized check-then-act: the guard set built here
    # spans both the ancestor walk and the edge rewrite, so no interleaved
    # mover can slip a cycle in between.
    can validate with Root entry {
        if self.target is None or self.new_parent is None {
            disengage;
        }
        # walk ancestors of the proposed parent
        cur = self.new_parent;
        found_cycle = False;
        while True {
            if cur is self.target {
                found_cycle = True;
                break;
            }
            parents = [cur ->:ChildOf:->];
            if len(parents) == 0 { break; }
            cur = parents[0];
        }
        if found_cycle {
            print(f"reparent {self.target.name} under {self.new_parent.name} REJECTED: would create cycle");
            disengage;
        }
        self.ok = True;
        print(f"reparent {self.target.name} under {self.new_parent.name} accepted");
        disengage;
    }
}

def reparent(target: Group, new_parent: Group) -> bool {
    # atomic under the walker's single validation+commit pass
    m = Mover(target=target, new_parent=new_parent);
    root spawn m;
    if not m.ok {
        return False;
    }
    target del ->:ChildOf:->;
    target +>:ChildOf:+> new_parent;
    return True;
}

with entry {
    root_node = Group(name="root");
    a = Group(name="A", depth=1);
    b = Group(name="B", depth=2);
    c = Group(name="C", depth=3);
    d = Group(name="D", depth=2);

    root ++> root_node;
    root_node +>:ChildOf:+> a;
    a +>:ChildOf:+> b;
    b +>:ChildOf:+> c;
    root_node +>:ChildOf:+> d;

    print("--- move D under C (accepted) ---");
    r1 = reparent(d, c);
    print(f"move D->C result: {r1}");

    print("--- move C under D (must be rejected: would close C<->D cycle) ---");
    r2 = reparent(c, d);
    print(f"move C->D result: {r2}");

    print("--- audit walk from root ---");
    root spawn Auditor();
}

"""Chain-membership check: backward walk from tip to a referenced block.

Fast path answers via the on-main-chain flag; otherwise a walker
recurses one parent edge at a time up to a depth cap (tip id - lowest
referenced id), mirroring the recursive CTE in CheckBlockIsInCurrentChain.
"""

node Block {
    has height: int = 0;
    has on_main_chain: bool = False;
}

edge Parent { }

edge References {
    has block_id: int = 0;
}

walker ChainChecker {
    has best_block_id: int = 0;
    has lowest_ref_id: int = 0;
    has rebuilding: bool = False;
    has depth: int = 0;
    has max_depth: int = 0;
    has found: bool = False;
    has verdict: str = "";

    can start with Root entry {
        self.max_depth = self.best_block_id - self.lowest_ref_id;
        # Fast path: indexed flag lookup when flags are reliable.
        # On a miss we deliberately fall through to the walk (no false reject).
        if not self.rebuilding {
            for ref in [here -->:References:-->] {
                if ref.on_main_chain {
                    self.found = True;
                }
            }
        }
        if self.found {
            self.verdict = "in-chain (fast path)";
            disengage;
        }
        visit [-->];
    }

    can walk_chain with Block entry {
        if self.found {
            self.verdict = f"in-chain at depth {self.depth}";
            disengage;
        }
        if here.on_main_chain {
            self.found = True;
            self.verdict = f"in-chain at depth {self.depth}";
            disengage;
        }
        self.depth += 1;
        if self.depth > self.max_depth {
            self.verdict = f"NOT in chain: depth cap {self.max_depth} exhausted";
            disengage;
        }
        visit [->:Parent:->] else {
            self.verdict = "NOT in chain: reached genesis without a match";
            disengage;
        }
    }
}

with entry {
    genesis = Block(height=0, on_main_chain=True);
    b1 = Block(height=1, on_main_chain=True);
    b2 = Block(height=2, on_main_chain=True);
    tip = Block(height=3, on_main_chain=True);

    genesis +>:Parent:+> b1 +>:Parent:+> b2 +>:Parent:+> tip;

    # An off-chain fork block near genesis, referenced by a transaction.
    fork = Block(height=1, on_main_chain=False);
    b1 +>:Parent:+> fork;
    fork +>:References(block_id=1):+> genesis;

    # In-chain spend: hits the fast flag path.
    tip spawn ChainChecker(best_block_id=3, lowest_ref_id=1);

    # Adversarial deep reference to genesis-era block while flags rebuild:
    # fast path skipped, walk runs the full capped depth.
    tip spawn ChainChecker(best_block_id=3, lowest_ref_id=0, rebuilding=True);
}

