"""Bounded dependency-cycle detection: the safe Go-side DFS from `bd dep cycles`,
replacing the runaway recursive-CTE path expansion from `bd doctor`'s check.

A doctor walker performs a depth-capped, visited-guarded traversal over typed
DependsOn edges; when it walks back into the issue it started from, a cycle
is reported. No path strings grow through recursion — the guard set and the
depth cap bound the walk strictly."""

edge DependsOn { }

node Issue {
    has title: str = "";
    has issue_id: str = "";
    has depth_seen: int = -1;  # depth at which the current probe arrived here
}

walker CycleDoctor {
    has start_id: str = "";
    has max_depth: int = 100;
    has cur_depth: int = 0;

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    # Depth-capped DFS: revisit a node only at a strictly greater depth,
    # mirroring the guard the runaway CTE carried in its path string.
    can probe with Issue entry {
        if here.depth_seen >= self.cur_depth {
            # Already explored at an equal or cheaper depth: prune branch.
            visit [->:DependsOn:->] else { disengage; }
        }
        here.depth_seen = self.cur_depth;
        if here.issue_id == self.start_id {
            print(f"CYCLE detected through {here.issue_id} ({here.title}) at depth {self.cur_depth}");
            disengage;
        }
        if self.cur_depth >= self.max_depth {
            print(f"depth cap {self.max_depth} reached at {here.issue_id}; aborting branch");
            disengage;
        }
        self.cur_depth += 1;
        visit [->:DependsOn:->] else { disengage; }
    }
}

# Launcher walker: seeds one bounded DFS per issue, like the Go-side loop
# that runs DetectCycles from every node instead of one giant path expansion.
walker CycleSweep {
    has max_depth: int = 100;

    can start with Root entry {
        visit [-->];
    }

    can seed with Issue entry {
        print(f"probing cycles from {here.issue_id} (depth cap {self.max_depth})");
        CycleDoctor(start_id=here.issue_id, max_depth=self.max_depth) spawn here;
    }
}

