"""Data-structure pack demo: a graph structure with BFS/DFS walkers over typed edges.

Models the core scenario from issue #11: a graph structure pack whose
adjacency is represented natively as typed edges, with traversal walkers
that carry an explicit visited set (jac walkers have no built-in
once-per-node visitation, so the cycle guard is domain logic).
"""

node Vertex {
    has name: str = "";
    has visited: bool = False;
}

edge Neighbor { }

walker GraphBuilder {
    can start with Root entry {
        visit [-->];
    }

    can build with Vertex entry {
        visit [->:Neighbor:->];
    }
}

walker BfsExplorer {
    has frontier: list[str] = [];
    has order: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can explore with Vertex entry {
        """BFS over typed Neighbor edges with an explicit visited guard."""
        if here.visited {
            print(f"skip {here.name} (already visited, cycle guard)");
            return;
        }
        here.visited = True;
        self.order.append(here.name);
        neighbors = [v.name for v in [here->:Neighbor:->]];
        self.frontier = neighbors;
        print(f"visit {here.name}; frontier = {self.frontier}; "
              f"invariant: order preserves BFS layering");
        visit [->:Neighbor:->];
    }

    can finish with Root exit {
        report self.order;
    }
}

walker Resetter {
    can start with Root entry {
        visit [-->];
    }

    can reset with Vertex entry {
        here.visited = False;
        visit [-->];
    }
}

with entry {
