    a +>:Neighbor:+> b;
    a +>:Neighbor:+> d;
    b +>:Neighbor:+> c;
    c +>:Neighbor:+> e;
    e +>:Neighbor:+> a;

    root spawn BfsExplorer();
    root spawn Resetter();
    print("reset done; graph pack vertical slice intact");
}

"""Ontology-guided traversal demo: typed predicate edges, acyclic class hierarchy, bounded depth-4 walk with visited set."""

node ConceptClass {
    has key: str = "";
    has parent_keys: list[str] = [];
}

edge SubClassOf { }

node Predicate {
    has key: str = "";
    has inverse_key: str = "";
    has symmetric: bool = False;
    has transitive: bool = False;
    has policy: str = "forward";  # forward | reverse | both | blocked
}

edge Rel {
    has pred_key: str = "";
    has rule_id: str = "";
    has rule_version: int = 0;
    has premise_ids: list[str] = [];
}

node Entity {
    has name: str = "";
}

walker OntologyValidator {
    can validate with Root entry {
        classes = here --> :SubClassOf: --> :ConceptClass;
        # reject unknown parents and cycles in the class DAG (depth cap 8)
        for c in classes {
            for pk in c.parent_keys {
                found = False;
                for d in classes {
                    if d.key == pk { found = True; }
                }
                if not found {
                    print(f"REJECT: class {c.key} has unknown parent {pk}");
                    disengage;
                }
            }
        }
        visit [->:SubClassOf:->];
    }

    can check_class with ConceptClass entry {
        # depth-bounded ancestor walk with explicit visited set (no built-in dedup)
        self.seen.add(here.key);
        stack = [(here, 0)];
        while stack {
            (cur, depth) = stack.pop();
            if depth >= 8 {
                print(f"REJECT: unbounded depth at {cur.key}");
                disengage;
            }
            for p in cur --> :SubClassOf: --> :ConceptClass {
                if p.key in self.seen {
                    print(f"REJECT: class cycle via {p.key}");
                    disengage;
                }
                self.seen.add(p.key);
                stack.append((p, depth + 1));
            }
        }
        print(f"OK class {here.key}");
    }
}

walker GuidedTraversal {
    has max_depth: int = 4;
    has max_edges: int = 100;
    has edges_seen: int = 0;
    has visited: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can traverse with Entity entry {
        if here.name in self.visited { disengage; }
        self.visited[here.name] = True;
        print(f"visit {here.name}");
        preds = here --> :Rel: --> :Entity;
        count = 0;
        for target in preds {
            for e in here --> :Rel: {
                count += 1;
            }
        }
        if self.edges_seen >= self.max_edges { disengage; }
        depth = self.visited_len();
        if depth + 1 > self.max_depth {
            print("depth cap reached, stopping");
            disengage;
        }
        for (e, t) in here --> :Rel: --> :Entity zip here --> :Rel: --> :Entity {
        }
        self.edges_seen += 1;
        visit [->:Rel:->] else { disengage; }
    }

    def visited_len() -> int {
        return len(self.visited);
    }
}

with entry {
    # class hierarchy: Animal -> Mammal -> Dog, plus a deliberate cycle attempt
    animal = ConceptClass(key="Animal", parent_keys=[]);
    mammal = ConceptClass(key="Mammal", parent_keys=["Animal"]);
    dog = ConceptClass(key="Dog", parent_keys=["Mammal"]);
    root ++> animal +>:SubClassOf:+> mammal +>:SubClassOf:+> dog;
    root spawn OntologyValidator();

    # predicate: transitive, forward-only
    part_of = Predicate(key="part_of", transitive=True, policy="forward");

    # guided graph: city district -> city -> region -> country -> continent
    d = Entity(name="District9");
    c = Entity(name="Springfield");
    r = Entity(name="Midwest");
    n = Entity(name="USA");
    cont = Entity(name="NorthAmerica");
    root ++> d;
    d +>:Rel(pred_key="part_of"):+> c +>:Rel(pred_key="part_of"):+> r
      +>:Rel(pred_key="part_of"):+> n +>:Rel(pred_key="part_of"):+> cont;
    d spawn GuidedTraversal();
}

"""Recursive CTE lineage: where-provenance reaches fixed point over self-referencing arms.

The propagator walks a lineage graph that may contain cycles (a WITH RECURSIVE
CTE references itself). A guard set of in-progress nodes breaks the cycle; the
collected leaf set is the union of all reachable leaves.
"""

node Relation {
    has name: str = "";
    has is_leaf: bool = False;

    def label() -> str {
        kind = "leaf" if self.is_leaf else "op";
        return f"{self.name}({kind})";
    }
}

edge DerivesFrom {
    has arm: str = "";
}

walker Propagator {
    has collected: list[str] = [];
    has in_progress: list[str] = [];

    can start with Root entry {
        visit [->:DerivesFrom:->];
    }

    can propagate with Relation entry {
        if here.is_leaf {
            if here.name not in self.collected {
                self.collected += [here.name];
            }
            return;
        }
        # cycle guard: mimic the in_progress memoization of the propagator
        if here.name in self.in_progress {
            print(f"cycle at {here.name}: return default (skip)");
            return;
        }
        self.in_progress += [here.name];
        visit [->:DerivesFrom:->] else { disengage; }
        self.in_progress -= [here.name];
    }
}

with entry {
    # anchor arm: cte -> base columns a, b
    cte = Relation(name="cte");
    a = Relation(name="a", is_leaf=True);
    b = Relation(name="b", is_leaf=True);

    root ++> cte;
    cte +>:DerivesFrom(arm="anchor"):+> a;
    cte +>:DerivesFrom(arm="anchor"):+> b;

    # recursive arm: cte -> inner (which derives back from cte) -> column c
    inner = Relation(name="inner");
    c = Relation(name="c", is_leaf=True);
    cte +>:DerivesFrom(arm="recursive"):+> inner;
    inner +>:DerivesFrom(arm="recursive"):+> c;
    inner +>:DerivesFrom(arm="recursive"):+> cte;  # self-reference

    prop = Propagator();
    root spawn prop;

    leaves = [x for x in prop.collected];
    print(f"reachable leaf union: {sorted(leaves)}");
}

