"""Hierarchical Manager delegation: typed-edge delegation lineage with an
authority-containment and cycle audit walker."""

node Stream {
    has name: str = "";
    has role: str = "";          # "owner" | "manager" | "executor" | "reviewer"
    has authority: list[str] = [];  # permitted capabilities
    has resolved: bool = False;  # return expectation satisfied?
}

edge Delegates { }               # delegation lineage: parent stream -> child stream

walker Audit {
    has chain: list[str] = [];
    has failures: int = 0;

    can start with Root entry {
        visit [->:Delegates:->] else { disengage; }
    }

    can audit with Stream entry {
        # cycle policy: explicit visited chain, no dedupe built into visit
        if here.name in self.chain {
            self.failures += 1;
            print(f"CYCLE detected at {here.name}: {self.chain}");
            disengage;
        }
        containment = "ok";
        if self.chain {
            # authority(child) must be subset of authority(parent)
            parent_auth = [];
            for p in [here <-:Delegates:-] {
                parent_auth = p.authority;
            }
            missing = [cap for cap in here.authority if cap not in parent_auth];
            if missing {
                containment = "VIOLATED: " + ", ".join(missing);
                self.failures += 1;
            }
        }
        unresolved = "unresolved" if not here.resolved else "resolved";
        print(f"{here.role}:{here.name} [{containment}] ({unresolved})");
        self.chain = self.chain + [here.name];
        visit [->:Delegates:->];
        self.chain = self.chain[:-1];
    }
}

walker ReconcileReturns {
    can start with Root entry {
        visit [->:Delegates:->] else { disengage; }
    }

    can settle with Stream entry {
        if here.role == "executor" and here.resolved {
            # executor return consumed by parent manager context
            for parent in [here <-:Delegates:-] {
                print(f"return from {here.name} consumed by {parent.name}");
            }
        }
        visit [->:Delegates:->];
    }
}

with entry {
    owner = Stream(name="Owner", role="owner",
                   authority=["deploy", "investigate"]);
    mgr_a = Stream(name="ManagerA", role="manager",
                   authority=["investigate", "prepare"]);
    mgr_b = Stream(name="ManagerB", role="manager",
                   authority=["investigate"]);            # narrowed, legal
    exec_b = Stream(name="ExecB", role="executor",
                   authority=["investigate"], resolved=True);
    rogue = Stream(name="ManagerC", role="manager",
                   authority=["deploy"]);                  # VIOLATION: deploy not in A
    exec_c = Stream(name="ExecC", role="executor",
                   authority=["investigate"], resolved=False);

    root ++> owner;
    owner +>:Delegates:+> mgr_a;
    mgr_a +>:Delegates:+> mgr_b;
    mgr_b +>:Delegates:+> exec_b;
    mgr_a +>:Delegates:+> rogue;
    rogue +>:Delegates:+> exec_c;

    root spawn Audit();
    root spawn ReconcileReturns();
}

