walker Propagator {
    has collected: list[str] = [];
    has in_progress: list[str] = [];

    def enter(name: str) {
        self.in_progress += [name];
    }

    def leave(name: str) {
        self.in_progress = [n for n in self.in_progress if n != name];
    }

    can start with Root entry {
        visit [->:DerivesFrom:->];
