"""CI cache auditor: model Gradle CI jobs and walk workflows to find cold dependency resolution, mirroring issue #253's risk of uncached 429-prone jobs and caches hiding broken declarations."""

node Workflow {
    has name: str = "";
}

node Job {
    has name: str = "";
    has cached: bool = False;
    has publishes: bool = False;
}

edge Contains { }

walker CacheAuditor {
    has cold_jobs: int = 0;
    has risky_publish_jobs: int = 0;

    can start with Root entry {
        visit [->:Contains:->];
    }

    can audit with Workflow entry {
        print(f"=== workflow {here.name} ===");
        visit [->:Contains:->];
    }

    can audit with Job entry {
        if not here.cached and here.publishes {
            self.risky_publish_jobs += 1;
            print(f"  [PUBLISH-COLD] {here.name}: signs artifacts against unverified deps");
        } else if not here.cached {
            self.cold_jobs += 1;
            print(f"  [COLD] {here.name}: re-resolves from Central every push (429 risk)");
        } else {
            print(f"  [OK] {here.name}: setup-gradle cache present");
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    build = Workflow(name="arm-build-test.yaml");
    build +>:Contains:+> Job(name="arm-build", cached=False)
        +>:Contains:+> Job(name="arm-test", cached=False)
        +>:Contains:+> Job(name="arm-runtime-tests", cached=False)
        +>:Contains:+> Job(name="arm-lint", cached=False);

    stress = Workflow(name="stress-matrix.yaml");
    stress +>:Contains:+> Job(name="stress-a", cached=False)
        +>:Contains:+> Job(name="stress-b", cached=False)
        +>:Contains:+> Job(name="stress-c", cached=False);

    pages = Workflow(name="pages.yaml");
    pages +>:Contains:+> Job(name="docs", cached=True);

    publish = Workflow(name="publish.yaml");
    publish +>:Contains:+> Job(name="publish-central", cached=False, publishes=True);

    root ++> build ++> stress ++> pages ++> publish;
    root spawn CacheAuditor();
}

