"""PWA hardening audit: model tracks/tasks and audit them with a cycle-safe walker."""

node Track {
    has title: str = "";
    has done: bool = False;
}

node Task {
    has title: str = "";
    has offline_safe: bool = True;
}

node CacheRoute {
    has path: str = "";
    has network_only: bool = False;
}

edge Contains { }
edge Requires {
    has depth: int = 0;
}
edge Serves { }

walker Auditor {
    has visited: dict = {};
    has failures: list = [];
    has depth_cap: int = 10;

    can start with Root entry {
        visit [-->];
    }

    can audit with Track entry {
        if self.visited.get(here.title) {
            disengage;
        }
        self.visited[here.title] = True;
        status = "OK" if here.done else "OPEN";
        print(f"[{status}] track: {here.title}");
        if not here.done {
            self.failures.append(here.title);
        }
        visit [->:Contains:->];
    }

    can audit_task with Task entry {
        verdict = "offline-safe" if here.offline_safe else "NEEDS NETWORK";
        print(f"    task: {here.title} ({verdict})");
        if not here.offline_safe {
            self.failures.append(here.title);
        }
        visit [->:Requires:->] else { disengage; }
    }

    can audit_route with CacheRoute entry {
        if self.depth_cap <= 0 {
            print(f"    depth cap reached at {here.path}; stopping");
            disengage;
        }
        self.depth_cap -= 1;
        policy = "network-only" if here.network_only else "cacheable";
        print(f"    route {here.path}: {policy}");
        if here.network_only and "sw.js" not in here.path {
            print(f"    WARNING: sensitive route {here.path} must stay network-only");
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    a = Track(title="Track A: Offline-first", done=False);
    b = Track(title="Track B: Storage durability", done=True);
    c = Track(title="Track C: SW/update safety", done=False);
    root ++> a ++> b ++> c;
    a +>:Contains:+> Task(title="cold offline launch", offline_safe=True);
    a +>:Contains:+> Task(title="inference endpoint routing", offline_safe=False);
    c +>:Contains:+> Task(title="cache policy CI assertion", offline_safe=True);
    c +>:Serves:+> CacheRoute(path="/api/ai/chat", network_only=True);
    c +>:Serves:+> CacheRoute(path="/app/shell.js", network_only=False);
    c +>:Requires(depth=1):+> CacheRoute(path="/sw.js", network_only=False);
    root spawn Auditor();
}

