    # Derived edge carrying rule provenance (one rule layer, no chaining).
    r +>:Rel(pred_key="part_of", rule_id="geo-up", rule_version=1, premise_ids=["rel-1", "rel-2"]):+> n;
    n spawn InverseTraversal();
}

