"""Hierarchical Manager delegation: typed-edge delegation lineage with an
authority-containment and cycle audit walker."""

node Stream {
    has name: str = "";
    has role: str = "";             # "owner" | "manager" | "executor" | "reviewer"
    has authority: list[str] = [];  # permitted capabilities
    has resolved: bool = False;     # return expectation satisfied?
}

edge Delegates { }  # delegation lineage: parent stream -> child stream

walker Audit {
    has chain: list[str] = [];
    has auth_chain: list[list[str]] = [];
    has failures: int = 0;

    can start with Root entry {
        visit [->:Delegates:->] else { disengage; }
    }

    can audit with Stream entry {
        # Cycle policy: explicit visited chain (visit does not dedupe).
        if here.name in self.chain {
            self.failures += 1;
            print(f"CYCLE detected at {here.name}");
            disengage;
        }
        containment = "ok";
        if len(self.auth_chain) > 0 {
            parent_auth = self.auth_chain[-1];
            missing = [];
            for cap in here.authority {
                if cap not in parent_auth {
                    missing = missing + [cap];
                }
            }
            if len(missing) > 0 {
                containment = "VIOLATED";
                self.failures += 1;
                print(f"{here.role}:{here.name} exceeds delegated authority: {missing}");
            }
        }
        if containment == "ok" {
            state = "resolved" if here.resolved else "unresolved";
            print(f"{here.role}:{here.name} [{containment}] ({state})");
        }
        self.chain = self.chain + [here.name];
        self.auth_chain = self.auth_chain + [here.authority];
        visit [->:Delegates:->] else {
            self.chain = self.chain[:-1];
            self.auth_chain = self.auth_chain[:-1];
        }
    }
}

walker ReconcileReturns {
    has open_streams: list[str] = [];

    can start with Root entry {
        visit [->:Delegates:->] else { disengage; }
    }

    can settle with Stream entry {
        if here.role == "executor" and here.resolved {
            print(f"executor return from {here.name} consumed by manager context");
        } else {
            if not here.resolved and here.role != "owner" {
                self.open_streams = self.open_streams + [here.name];
            }
        }
        visit [->:Delegates:->] else { disengage; }
    }
}

