"""Graph traversal demo: BFS and DFS over a course prerequisite graph.

Nodes are courses, typed Prereq edges carry dependencies, and two
walkers replace hand-rolled BFS (queue loop) and DFS (recursion) with
native visits. An explicit guard set stands in for the missing built-in
visited machinery, and a cycle check preserves domain semantics.
"""

node Course {
    has title: str = "";
    has visited_bfs: bool = False;
    has visited_dfs: bool = False;
}

edge Prereq {
    has required_first: bool = True;
}

walker BfsExplorer {
    has order: list[str] = [];

    can start with Root entry {
        visit [->:Prereq:->];
    }

    can explore with Course entry {
        # Explicit guard set: visit does not dedupe on cyclic graphs.
        if not here.visited_bfs {
            here.visited_bfs = True;
            self.order.append(here.title);
            visit [->:Prereq:->];
        }
    }
}

walker DfsExplorer {
    has order: list[str] = [];
    has on_stack: set = {};
    has cyclic: bool = False;

    can start with Root entry {
        visit [->:Prereq:->];
    }

    can explore with Course entry {
        # Cycle guard preserved from the source pattern.
        if here in self.on_stack {
            self.cyclic = True;
            disengage;
        }
        if not here.visited_dfs {
            here.visited_dfs = True;
            self.on_stack.add(here);
            self.order.append(here.title);
            visit [->:Prereq:->];
        }
        # Dead-end exit: pop before backtracking.
        if here in self.on_stack {
            self.on_stack.remove(here);
        }
    }

    can report with Root exit {
        print(f"DFS order: {self.order}");
        status = "CYCLE DETECTED" if self.cyclic else "acyclic";
        print(f"DFS finished: {status}");
    }
}

