"""Ontology-guided traversal demo: acyclic class hierarchy, bounded depth-4 walk with visited set, and inverse predicate traversal."""

node ConceptClass {
    has key: str = "";
    has parent_keys: list[str] = [];
}

edge SubClassOf { }

node Predicate {
    has key: str = "";
    has inverse_key: str = "";
    has symmetric: bool = False;
    has transitive: bool = False;
    has policy: str = "forward";  # forward | reverse | both | blocked
}

edge Rel {
    has pred_key: str = "";
    has rule_id: str = "";
    has rule_version: int = 0;
    has premise_ids: list[str] = [];
}

node Entity {
    has name: str = "";
}

walker OntologyValidator {
    has depth_cap: int = 8;
    has pack: list[ConceptClass] = [];

    can validate with Root entry {
        # Collect all declared class keys and reject duplicate definitions.
        classes = {};
        for c in self.pack {
            if c.key in classes {
                print(f"REJECT: duplicate class definition {c.key}");
                disengage;
            }
            classes[c.key] = c.parent_keys;
        }
        # Reject unknown parents.
        for ck in classes.keys() {
            for pk in classes[ck] {
                if pk not in classes {
                    print(f"REJECT: class {ck} has unknown parent {pk}");
                    disengage;
                }
            }
        }
        # Reject cycles and unbounded depth in the class DAG.
        for ck in classes.keys() {
            status = self.check_ancestors(ck, classes, [], 0);
            if status != "ok" {
                print(f"REJECT: class {ck}: {status}");
                disengage;
            }
        }
        print("ontology pack accepted: class graph is a DAG within depth cap");
        visit [->:SubClassOf:->];
    }

    def check_ancestors(key: str, classes: dict, seen: list, depth: int) -> str {
        if depth > self.depth_cap {
            return "unbounded hierarchy depth";
        }
        if key in seen {
            return f"class cycle via {key}";
        }
        grown = seen + [key];
        for pk in classes[key] {
            result = self.check_ancestors(pk, classes, grown, depth + 1);
            if result != "ok" {
                return result;
            }
        }
        return "ok";
    }

    can check_class with ConceptClass entry {
        parents = "(root)";
        if len(here.parent_keys) > 0 {
            parents = ", ".join(here.parent_keys);
        }
        print(f"OK class {here.key} parents={parents}");
        visit [->:SubClassOf:->] else { disengage; }
    }
}

walker GuidedTraversal {
    has max_depth: int = 4;
    has max_edges: int = 100;
    has edges_seen: int = 0;
    has visited: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can traverse with Entity entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited[here.name] = True;
        hops = len(self.visited);
        if hops > self.max_depth or self.edges_seen >= self.max_edges {
            print(f"bounded read stopped after {self.edges_seen} edges (depth cap {self.max_depth})");
            disengage;
        }
        print(f"hop {hops}: reached {here.name}");
        self.edges_seen += 1;
        visit [->:Rel:->] else { disengage; }
    }
}

walker InverseTraversal {
    has visited: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can walk_back with Entity entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited[here.name] = True;
        print(f"inverse (reverse policy) reach: {here.name}");
        visit [<--:Rel:--] else { disengage; }
    }
}

with entry {
    # Class hierarchy: Animal -> Mammal -> Dog, plus a rejected unknown-parent class.
    animal = ConceptClass(key="Animal", parent_keys=[]);
    mammal = ConceptClass(key="Mammal", parent_keys=["Animal"]);
    dog = ConceptClass(key="Dog", parent_keys=["Mammal"]);
