walker BackendAuditor {
    has built: dict = {};
    has rebuilds_avoided: int = 0;

    can start with Root entry {
        visit [->:RunsOn:->];
    }

    can audit_executor with Executor entry {
        backend = "github-hosted" if here.hosted else "organization";
        print(f"executor [{here.label}] backend={backend}");
        visit [->:RunsOn:->];
