"""Read-only hierarchical Roadmap projection over Kanban scopes.

Walks the scope hierarchy (company -> portfolio -> workstream -> project)
via typed ChildOf edges, aggregates only authorized boards, detects
dependency cycles on task DependsOn edges with an explicit guard set,
and fails closed (marks the scope blocked) when a cycle is found.
"""

node Scope {
    has name: str = "";
    has kind: str = "";           # company | portfolio | workstream | project
    has authorized: bool = True;
    has blocked: bool = False;    # fail-closed flag
}

node Board {
    has name: str = "";
    has done_cards: int = 0;
}

node Task {
    has title: str = "";
    has done: bool = False;
    has has_cycle: bool = False;
}

edge ChildOf { }                # scope -> child scope / board / task container
edge DependsOn { }              # task -> prerequisite task

walker Roadmapper {
    has visited_scopes: dict = {};
    has total_done: int = 0;

    can start with Root entry {
        visit [->:ChildOf:->];
    }

    can roll_up with Scope entry {
        # Cycle guard: walkers do not dedupe visits on jac 0.36.1.
        if here.blocked {
            disengage;
        }
        key = here.name + ":" + here.kind;
        if key in self.visited_scopes {
            disengage;
        }
        self.visited_scopes[key] = True;

        if here.authorized {
            visit [->:ChildOf:->];
        } else {
            # Unauthorized scopes fail closed and hide their subtree.
            print(f"[HIDDEN] {here.kind} {here.name} (unauthorized)");
            disengage;
        }
    }

    can tally with Board entry {
        self.total_done += here.done_cards;
        print(f"board {here.name}: {here.done_cards} done (total {self.total_done})");
        visit [-->] else { disengage; }
    }

    can check_tasks with Task entry {
        # Cycle detection over DependsOn edges via a guard-set walker.
        checker = CycleChecker(seen={});
        here spawn checker;
        if checker.found_cycle {
            here.has_cycle = True;
            print(f"[FAIL-CLOSED] dependency cycle at task {here.title}");
        } else {
            status = "done" if here.done else "open";
            print(f"task {here.title}: {status}");
        }
        visit [-->] else { disengage; }
    }
}

walker CycleChecker {
    has seen: dict = {};
    has found_cycle: bool = False;

    can chase with Task entry {
        if self.found_cycle {
            disengage;
        }
        key = here.title;
        if key in self.seen {
            self.found_cycle = True;
            disengage;
        }
        self.seen[key] = True;
        visit [->:DependsOn:->];
    }
}

