"""DKG transitive traversal demo: decisions superseding decisions.

The event store can answer one-hop `supersededBy` filters but not
"this decision and every decision that it superseded" — a chain of
unknown length. Here relationships are typed `Supersedes` edges and the
transitive question is a walker. Because jac walkers have no built-in
once-per-node visitation, the source's cycle guard is kept explicitly,
and a depth cap survives as domain logic. The accumulated fold is
recomputed a second way (an independent oracle) and compared.
"""

node Decision {
    has title: str = "";
    has year: int = 0;
}

edge Supersedes { }

walker Oracle {
    """Independent reimplementation: iterative fold over typed edges
    used to cross-check the walker's recursive fold."""
    can check with Root entry {
        start = [root -->][0];
        seen: dict = {};
        stack: list = [(start, 0)];
        total = 0;
        while stack {
            (node, depth) = stack.pop();
            if node in seen { continue; }
            seen[node] = True;
            total += depth;
            for child in [node ->:Supersedes:->] {
                stack.append((child, depth + 1));
            }
        }
        self.oracle_weighted_depth = total;
        self.oracle_count = len(seen);
    }
    has oracle_weighted_depth: int = 0;
    has oracle_count: int = 0;
}

walker TraceSupersession {
    """Walk 'this decision and everything it superseded' over typed edges.

    Cycle policy: explicit guard set (source behavior — never revisit a
    node). Depth cap: 10, a domain limit that must survive the lift.
    Folds accumulate here and are reported once on the exit hook.
    """
    has visited: dict = {};
    has chain: list = [];
    has weighted_depth: int = 0;
    has max_depth: int = 10;
    has depth: int = 0;
    has truncated: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can trace with Decision entry {
        if here in self.visited {
            print(f"cycle guard: already saw '{here.title}', stopping this branch");
            return;
        }
        if self.depth >= self.max_depth {
            self.truncated = True;
            print(f"depth cap {self.max_depth} hit at '{here.title}'");
            return;
        }
        self.visited[here] = True;
        self.chain.append(here.title);
        self.weighted_depth += self.depth;
        self.depth += 1;
        visit [->:Supersedes:->];
        self.depth -= 1;
    }

    can finish with Decision exit {
        oracle = root spawn Oracle();
        agree = (oracle.oracle_weighted_depth == self.weighted_depth)
            and (oracle.oracle_count == len(self.chain));
        verdict = "MATCH" if agree else "MISMATCH";
        print(f"chain (oldest -> newest): {self.chain}");
        print(f"decisions: {len(self.chain)}, weighted depth: {self.weighted_depth}, truncated: {self.truncated}");
        print(f"oracle fold: decisions {oracle.oracle_count}, weighted depth {oracle.oracle_weighted_depth} -> {verdict}");
    }
}

with entry {
    rfc7 = Decision(title="RFC 7: shard the event store", year=2025);
    rfc11 = Decision(title="RFC 11: adopt DKG", year=2026);
    rfc14 = Decision(title="RFC 14: materialized path projection", year=2026);
    rfc19 = Decision(title="RFC 19: retire causationId label", year=2027);

    # Newest decision supersedes older ones (chain of unknown length).
    root ++> rfc19;
