"""Beta hardening tracker: issues as nodes, blocking relations as typed edges,
and a walker that performs dependency-ordered traversal with release-blocker
reporting (including risk-accepted P0s) and a cycle guard."""

node Issue {
    has number: int = 0;
    has title: str = "";
    has priority: str = "";          # "P0" | "P1" | "P2"
    has done: bool = False;
    has risk_accepted: bool = False;
    has owner: str = "";
    has review_date: str = "";

    def is_release_blocker() -> bool {
        return self.priority == "P0" and not self.done;
    }
}

edge Blocks { }                      # this issue blocks the target

edge DependsOn {
    has rationale: str = "";
}

edge Wave {
    has wave: int = 0;
}

walker ReleaseAuditor {
    has visited: dict = {};
    has blockers: list = [];
    has accepted: list = [];
    has order: list = [];
    has max_depth: int = 64;

    can start with Root entry {
        visit [->:Wave:->];
    }

    """Wave-ordered dependency walk: visit a P0 only after its
    DependsOn prerequisites, with an explicit depth cap so a
    dependency cycle terminates instead of hanging."""
    can audit with Issue entry {
        if here.number in self.visited {
            return;
        }
        if len(self.order) >= self.max_depth {
            print("dependency chain exceeds depth cap; stopping");
            disengage;
        }
        self.visited[here.number] = True;
        self.order.append(here.number);

        if here.is_release_blocker() {
            if here.risk_accepted {
                self.accepted.append(
                    f"#{here.number} (owner={here.owner}, review={here.review_date})"
                );
            } else {
                self.blockers.append(f"#{here.number} {here.title}");
            }
        }
        visit [->:DependsOn:->];
    }

    can report with Root exit {
        print(f"execution order: {self.order}");
        if len(self.blockers) > 0 {
            print(f"release blockers: {self.blockers}");
        } else {
            print("no unmitigated P0 blockers");
        }
        print(f"risk-accepted P0s: {self.accepted}");
    }
}

walker BlockerFinder {
    has blocked_count: int = 0;

    can start with Root entry {
        visit [->:Wave:->];
    }

    """Count open issues downstream of this one via Blocks edges."""
    can scan with Issue entry {
        visit [->:Blocks:->];
    }

    can note with Issue entry {
        if not here.done {
            self.blocked_count += 1;
        }
        visit [-->] else { disengage; }
    }
}

