"""Projection publisher demo: a shell-owned projection transition commits once,
then registry and source map are independent lazy derivations over the commit,
with a coherence gate binding source map to the exact parse snapshot revision."""

node ParseSnapshot {
    has revision: int = 0;
    has summary: str = "";
}

node ProjectionCommit {
    has revision: int = 0;
    has projection: str = "";
    has trace_published: bool = False;
    has hints_consumed: int = 0;
}

node Registry {
    has entries: str = "";
    has built: bool = False;
}

node SourceMap {
    has mapping: str = "";
    has built: bool = False;
}

edge ProducedFrom {
    has revision: int = 0;
}

edge DerivedFrom { }

edge SnapshotFor { }

walker Publisher {
    has pending_hints: int = 3;
    has committed: bool = False;

    can start with Root entry {
        visit [->:SnapshotFor:->];
    }

    can reconcile with ParseSnapshot entry {
        # Variant B: demand-triggered, transition executes exactly once.
        if self.committed {
            print(f"same-revision demand cached at rev {here.revision}");
            visit [->:ProducedFrom:->];
        } else {
            commit = ProjectionCommit(
                revision=here.revision,
                projection=f"projection@{here.revision} from '{here.summary}'",
                trace_published=True,
                hints_consumed=self.pending_hints,
            );
            here +>:ProducedFrom(revision=here.revision):+> commit;
            self.pending_hints = 0;
            self.committed = True;
            print(f"committed rev {commit.revision}, "
                  f"consumed {commit.hints_consumed} hints, trace published");
            visit [->:ProducedFrom:->];
        }
    }

    can derive with ProjectionCommit entry {
        reg = Registry(entries=f"registry({here.projection})", built=True);
        here +>:DerivedFrom:+> reg;
        print("registry built lazily from projection only");
    }
}

walker Consumer {
    can start with Root entry {
        visit [-->];
    }

    can read with Registry entry {
        print(f"demand: {here.entries} (built={here.built})");
        visit [<--:DerivedFrom:--];
    }

    can read with SourceMap entry {
        # Coherence gate: source map must match the snapshot revision of
        # the projection it was derived from.
        here.built = True;
        print(f"demand: source map '{here.mapping}' coherent at "
              f"rev {here.bound_revision}");
    }

    can read with ProjectionCommit entry {
        print(f"consumer sees commit rev {here.revision}, trace={here.trace_published}");
        visit [->:DerivedFrom:->];
    }

    can read with ParseSnapshot entry {
        visit [->:ProducedFrom:->];
    }
}

with entry {
    snap = ParseSnapshot(revision=7, summary="module AST v7");
    root +>:SnapshotFor:+> snap;
    root spawn Publisher();
    root spawn Consumer();
    root spawn Consumer();
}

"""DKG transitive traversal demo: decisions superseding decisions.

The event store can answer one-hop `supersededBy` filters but not
"this decision and every decision that it superseded" — a chain of
unknown length. Here relationships are typed `Supersedes` edges and the
transitive question is a walker. Because jac walkers have no built-in
once-per-node visitation, the source's cycle guard is kept explicitly,
and a depth cap survives as domain logic. The accumulated fold is
recomputed a second way (an independent oracle) and compared.
"""

node Decision {
    has title: str = "";
    has year: int = 0;
}

edge Supersedes { }

walker Oracle {
    """Independent reimplementation: iterative fold over typed edges
    used to cross-check the walker's recursive fold. Depth per node is
    tracked in a dict keyed by node identity."""
    has oracle_weighted_depth: int = 0;
    has oracle_count: int = 0;

    can check with Root entry {
        start = [root -->][0];
        seen: dict = {};
        depth_of: dict = {};
        stack: list = [];
        stack.append(start);
        depth_of[start] = 0;
        total = 0;
        count = 0;
        while len(stack) > 0 {
            node = stack.pop();
            if node in seen {
                continue;
            }
            seen[node] = True;
            total = total + depth_of[node];
            count = count + 1;
            for child in [node ->:Supersedes:->] {
                if child not in seen {
                    stack.append(child);
                    depth_of[child] = depth_of[node] + 1;
                }
            }
        }
        self.oracle_weighted_depth = total;
        self.oracle_count = count;
    }
}

walker TraceSupersession {
    """Walk 'this decision and everything it superseded' over typed edges.

    Cycle policy: explicit guard set (source behavior — never revisit a
    node). Depth cap: 10, a domain limit that must survive the lift.
    Folds accumulate here and are reported once on the exit hook.
    """
    has visited: dict = {};
    has chain: list = [];
    has weighted_depth: int = 0;
    has max_depth: int = 10;
    has depth: int = 0;
    has truncated: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can trace with Decision entry {
        if here in self.visited {
            print(f"cycle guard: already saw '{here.title}', stopping this branch");
            return;
        }
        if self.depth >= self.max_depth {
            self.truncated = True;
            print(f"depth cap {self.max_depth} hit at '{here.title}'");
            return;
        }
        self.visited[here] = True;
        self.chain.append(here.title);
        self.weighted_depth = self.weighted_depth + self.depth;
        self.depth = self.depth + 1;
        visit [->:Supersedes:->];
        self.depth = self.depth - 1;
    }

    can finish with Decision exit {
        oracle = root spawn Oracle();
        agree = (oracle.oracle_weighted_depth == self.weighted_depth)
            and (oracle.oracle_count == len(self.chain));
        verdict = "MATCH" if agree else "MISMATCH";
        print(f"chain (oldest -> newest): {self.chain}");
        print(f"decisions: {len(self.chain)}, weighted depth: {self.weighted_depth}, truncated: {self.truncated}");
        print(f"oracle fold: decisions {oracle.oracle_count}, weighted depth {oracle.oracle_weighted_depth} -> {verdict}");
    }
}

