"""Ecosystem digest: backport chains modeled as typed edges, walked by an auditor.

The issue complains about hand-rolled parent/backport recursion (PR -> stable
branch backport chains). Here each PR is a node, backport relationships are
typed edges, and a walker traverses the chain with an explicit depth cap and
cycle guard (jac walkers do not dedupe visits on their own).
"""

node Project {
    has name: str = "";
}

node PullRequest {
    has title: str = "";
    has number: int = 0;
    has merged: bool = True;
}

node Branch {
    has name: str = "";
    has stable: bool = False;
}

edge Targets { has branch: str = ""; }
edge BackportOf { }

walker BackportAuditor {
    has depth: int = 0;
    has max_depth: int = 8;
    has seen: dict = dict();
    has audited: int = 0;

    can start with Project entry {
        print(f"Auditing backport chains for {here.name}");
        visit [->:Targets:->];
    }

    can enter_branch with Branch entry {
        print(f"Branch {here.name} (stable={here.stable})");
        visit [->:BackportOf:->] else { disengage; }
    }

    can audit with PullRequest entry {
        if here.number in self.seen {
            print(f"cycle guard: PR #{here.number} already audited");
            disengage;
        }
        if self.depth >= self.max_depth {
            print(f"depth cap reached at PR #{here.number}");
            disengage;
        }
        self.seen[here.number] = True;
        self.depth += 1;
        self.audited += 1;
        status = "merged" if here.merged else "open";
        print(f"[{status}] PR #{here.number}: {here.title}");
        visit [->:BackportOf:->] else { self.depth -= 1; }
    }
}

