"""Minimal recursive CTE: a RecursiveUnion feeds rows to downstream and
loops feedback through a CteRef edge, bounded at 16 iterations with an
explicit termination barrier — the cycle policy from the issue survives."""

const MAX_RECURSIVE_ITERATION = 16;

node PlanRow {
    has payload: str = "";
    has iteration: int = 0;
}

node RecursiveUnion {
    has iteration: int = 0;
    has stopped: bool = False;

    def bump() -> bool {
        # Returns True if another iteration may run.
        if self.iteration >= MAX_RECURSIVE_ITERATION {
            self.stopped = True;
            return False;
        }
        return True;
    }
}

node CteRef {
    has label: str = "";
}

edge Feeds { }
edge BackRef { }

walker Epoch {
    has collected: list[str] = [];

    can start with Root entry {
        visit [->:Feeds:->];
    }

    can run with RecursiveUnion entry {
        # Base rows flow downstream; each lap bumps the iteration.
        while here.bump() {
            self.collected.append(f"iter={here.iteration}");
            visit [here->:BackRef:->] else { disengage; }
        }
        if here.stopped {
            print(f"barrier(iteration=0) sent back; halted at {here.iteration}");
            disengage;
        }
    }

    can consume with CteRef entry {
        print(f"{here.label} replayed feedback rows");
        visit [-->];
    }

    can record with PlanRow entry {
        print(f"row '{here.payload}' tagged iteration={here.iteration}");
    }
}

with entry {
    u = RecursiveUnion();
    c = CteRef(label="cte");
    root +>:Feeds:+> u;
    u +>:BackRef:+> c;
    c ++> PlanRow(payload="r1") ++> PlanRow(payload="r2");
    root spawn Epoch();
}

"""BIOMASS lineage: OGC sourceProduct edges lifted to typed edges with a
cycle-safe lineage walker that reports ancestor/descendant chains and depth."""

node StacItem {
    has stac_id: str = "";
    has product_type: str = "";
    has baseline: str = "";
    has resolved: bool = True;
}

edge SourceProduct {
    has relation: str = "sourceProduct";
    has metadata_profile: str = "ogc_17_003r2";
}

node MetadataDoc {
    has profile: str = "ogc_17_003r2";
    has href: str = "";
    has fetched: bool = True;
}

edge Documents {
    has source: str = "metadata_ogc_17_003r2";
}

edge HasEdge { }

walker LineageTracer {
    has direction: str = "ancestors";
    has max_depth: int = 8;
    has visited: dict = {};
    has lines: list = [];

    can start with Root entry {
        visit [->:HasEdge:->];
    }

    can begin_at_item with StacItem entry {
        self.visited = {};
        self.lines = [];
        self.trace(here, 0, "");
        for line in self.lines {
            print(line);
        }
        disengage;
    }

    def trace(cur: StacItem, depth: int, path: str) {
        if depth > self.max_depth {
            self.lines.append(f"depth cap reached at {cur.stac_id}");
            return;
        }
        key = f"{cur.stac_id}:{depth}";
        if key in self.visited {
            self.lines.append(f"[cycle guarded] {cur.stac_id} at depth {depth}");
            return;
        }
        self.visited[key] = True;
        tag = "unresolved" if not cur.resolved else cur.product_type;
        label = path + cur.stac_id;
        self.lines.append(f"{'  ' * depth}d{depth} {cur.stac_id} ({tag}, baseline {cur.baseline})");
        if self.direction == "ancestors" {
            for src in cur(-->(:SourceProduct)) {
                nxt = [src];
                if len(nxt) {
                    self.trace(nxt[0], depth + 1, label + " <- ");
                } else {
                    self.lines.append(f"{'  ' * (depth + 1)}d{depth + 1} unresolved source id at {label}");
                }
            }
        }
    }
}

walker DescendantTracer {
    has visited: dict = {};
    has lines: list = [];
    has max_depth: int = 8;

    can start with Root entry {
        visit [->:HasEdge:->];
    }

    can begin_at_item with StacItem entry {
        self.visited = {};
        self.lines = [];
        self.trace(here, 0);
        for line in self.lines {
            print(line);
        }
        disengage;
    }

    def trace(cur: StacItem, depth: int) {
        if depth > self.max_depth {
            self.lines.append(f"depth cap reached at {cur.stac_id}");
            return;
        }
        key = f"{cur.stac_id}:{depth}";
        if key in self.visited {
            self.lines.append(f"[cycle guarded] {cur.stac_id} at depth {depth}");
            return;
        }
        self.visited[key] = True;
        self.lines.append(f"{'  ' * depth}d{depth} {cur.stac_id} ({cur.product_type})");
        for derived in [<--:SourceProduct:--] cur {
            self.trace(derived, depth + 1);
        }
    }
}

