"""CHAT-6 Analyst/Integrator: walk the execution-DAG of milestones, audit
each against canonical Level-1 acceptance criteria, flag anti-drift
violations, and recommend an integration verdict."""

node Milestone {
    has title: str = "";
    has level: int = 0;              # 1 = canonical, 2 = execution milestone
    has criterion: str = "";         # canonical criterion advanced ("" if none)
    has evidence_ready: bool = False;
    has tests_passing: bool = False;
    has base_stale: bool = False;

    def advances_canonical() -> bool {
        if self.level == 1 {
            return True;
        }
        return self.criterion != "";
    }

    def audit_label() -> str {
        ok = "OK" if (self.advances_canonical() and self.evidence_ready and self.tests_passing and not self.base_stale) else "FLAG";
        return ok;
    }
}

edge Advances {
    has criterion: str = "";
}

edge DependsOn { }

walker Analyst {
    has findings: list[str] = [];
    has checked: int = 0;

    can start with Root entry {
        print("CHAT-6 pre-integration review: inspecting execution DAG");
        visit [->:Advances:->];
        visit [->:DependsOn:->];
    }

    can inspect with Milestone entry {
        self.checked += 1;
        label = here.audit_label();
        if label == "FLAG" {
            if not here.advances_canonical() {
                self.findings.append(
                    f"DRIFT: '{here.title}' (L{here.level}) advances no canonical criterion"
                );
            }
            if not here.evidence_ready or not here.tests_passing {
                self.findings.append(f"MISSING EVIDENCE: '{here.title}'");
            }
            if here.base_stale {
                self.findings.append(f"STALE BASE HEAD: '{here.title}'");
            }
        } else {
            print(f"[ACCEPT-CANDIDATE] {here.title} ({here.criterion})");
        }
        visit [->:DependsOn:->];
    }

    can conclude with Root exit {
        if self.findings {
            print(f"Review of {self.checked} milestones found {len(self.findings)} issue(s):");
            for f in self.findings {
                print(f"  - {f}");
            }
            print("Recommendation: HOLD (anti-drift rule triggered)");
        } else {
            print(f"All {self.checked} milestones clean; Recommendation: ACCEPT");
        }
    }
}

with entry {
    # Canonical Level-1 criteria (R1-style anchors)
    r1 = Milestone(title="R1: worker completes tasks", level=1, criterion="R1",
                   evidence_ready=True, tests_passing=True);
    c1 = Milestone(title="C1: evidence pipeline live", level=1, criterion="C1",
                   evidence_ready=True, tests_passing=True);

    # Level-2 execution milestones bound to canonical criteria
    m1 = Milestone(title="CHAT-1 scheduler core", level=2, criterion="R1",
                   evidence_ready=True, tests_passing=True);
    m2 = Milestone(title="CHAT-2 mutation domains", level=2, criterion="C1",
                   evidence_ready=True, tests_passing=True);
    m3 = Milestone(title="CHAT-3 control-plane dashboard", level=2, criterion="",
                   evidence_ready=True, tests_passing=True);          # drift!
    m4 = Milestone(title="CHAT-4 amplifier rebase", level=2, criterion="R1",
                   evidence_ready=False, tests_passing=True,
                   base_stale=True);                                   # stale/evidence

    # Canonical milestones are roots of the DAG
    root +>:Advances(criterion="R1"):+> r1;
    root +>:Advances(criterion="C1"):+> c1;

    # Dependency ordering among execution milestones
    m1 +>:DependsOn:+> m2;
    m2 +>:DependsOn:+> m3;
    m3 +>:DependsOn:+> m4;
    m2 +>:Advances:+> r1;
    m4 +>:Advances:+> r1;

    root spawn Analyst();
}

"""Performance-gate lab: walk the exact dependency graph of the integrated
Three.js/WebGPU candidate, run the 13-step benchmark playthrough, and collect
frame-timing evidence against the 60 FPS target. Cycle detection is explicit
(jac walkers have no built-in once-per-node visitation)."""

node Dependency {
    has name: str = "";
    has version: str = "";
    has verified: bool = False;
}

node BenchmarkStep {
    has name: str = "";
    has order: int = 0;
    has median_ms: float = 0.0;
}

node Evidence {
    has sha256: str = "";
    has screenshots_kept: bool = True;
    has fps_target: float = 60.0;
    has achieved_fps: float = 0.0;
    has startup_ms: float = 0.0;
    has valid: bool = False;
}

edge DependsOn { }
edge MeasuredIn { }

walker ProvenanceGate {
    has pinned_sha: str = "";
    has unlocked: bool = False;

    can check with Root entry {
        # Fail closed: do not proceed until the observed lock SHA is pinned.
        self.unlocked = self.pinned_sha != "";
        if not self.unlocked {
            print("GATE FAIL: dependency provenance not pinned; aborting run");
            disengage;
        }
        print("GATE PASS: lock SHA pinned, executing benchmark");
        visit [->:DependsOn:->];
    }

    can verify with Dependency entry {
        # guard set: no built-in once-per-node visitation in jac 0.36
        if self.pinned_sha in here.name {
            here.verified = True;
        }
        print(f"dep {here.name}@{here.version} verified={here.verified}");
        visit [->:DependsOn:->];
    }

    can measure with BenchmarkStep entry {
        frame_ms = 18.0 if here.order > 1 else 210.0;
        here.median_ms = frame_ms;
        print(f"step {here.order}: {here.name} median {here.median_ms} ms");
        visit [->:MeasuredIn:->];
    }
}

walker Auditor {
    has visited: dict = {};
    has max_depth: int = 16;

    can audit with Evidence entry {
        fps = 1000.0 / here.achieved_fps if here.achieved_fps > 0 else 0.0;
        meets = here.achieved_fps >= here.fps_target;
        verdict = "MEETS 60 FPS TARGET" if meets else "BELOW 60 FPS TARGET";
        print(f"evidence sha={here.sha256} fps={here.achieved_fps:.1f} "
              f"({verdict}); not a device-readiness claim");
    }

    can walk_deps with Dependency entry {
        depth = self.visited.get(here.name, 0) + 1;
        if depth > self.max_depth {
            print(f"CYCLE detected at {here.name}; stopping this branch");
            disengage;
        }
        self.visited[here.name] = depth;
        visit [->:DependsOn:->];
    }
}

with entry {
    engine = Dependency(name="three-webgpu-candidate@main-lock-Sha256ABC", version="0.170.0");
    jolt = Dependency(name="jolt-physics@main-lock-Sha256ABC", version="0.3.1");
    math = Dependency(name="three-math@main-lock-Sha256ABC", version="0.170.0");

    step1 = BenchmarkStep(name="boot-viewport", order=1);
    step2 = BenchmarkStep(name="camera-orbit-input", order=2);
    step3 = BenchmarkStep(name="idle-raf-sample", order=3);

    report = Evidence(sha256="deadbeef", achieved_fps=52.4, startup_ms=410.0);

    root +>:DependsOn:+> engine;
    engine +>:DependsOn:+> jolt +>:DependsOn:+> math;
    engine +>:DependsOn:+> math;
    root +>:MeasuredIn:+> step1 +>:MeasuredIn:+> step2 +>:MeasuredIn:+> step3;
    step3 +>:MeasuredIn:+> report;

    root spawn ProvenanceGate(pinned_sha="Sha256ABC");
    root spawn Auditor(max_depth=8);
}

