"""Episodic-memory triggered_by cycle detection: DFS with a visited set over typed causal edges."""

node Episode {
    has ref_id: str = "";
    has status: str = "active";
    has category: str = "";
}

edge TriggeredBy { }

walker CycleDetector {
    has path: list[str] = [];
    has visited: set[str] = set();
    has cycle_found: bool = False;
    has cycle_path: list[str] = [];

    can start with Root entry {
        visit [->:TriggeredBy:->];
    }

    can inspect with Episode entry {
        if here.ref_id in self.visited {
            idx = 0;
            for (i, r) in enumerate(self.path) {
                if r == here.ref_id {
                    idx = i;
                }
            }
            self.cycle_path = self.path[idx:] + [here.ref_id];
            self.cycle_found = True;
            disengage;
        }
        self.visited.add(here.ref_id);
        self.path.append(here.ref_id);
        visit [->:TriggeredBy:->] else { disengage; }
    }
}

def detect_cycle(start: Episode) -> list[str] {
    d = CycleDetector();
    start spawn d;
    if d.cycle_found {
        return d.cycle_path;
    }
    return [];
}

with entry {
    a = Episode(ref_id="A");
    b = Episode(ref_id="B", category="review");
    c = Episode(ref_id="C");
