    b +>:TriggeredBy:+> c;
    c +>:TriggeredBy:+> a;

    cyc = detect_cycle(a);
    if cyc {
        print(f"REJECT: triggered_by cycle detected: {' -> '.join(cyc)}");
    } else {
        print("OK: no triggered_by cycle");
    }

    # linear chain: no cycle expected
    x = Episode(ref_id="X");
    y = Episode(ref_id="Y");
    z = Episode(ref_id="Z");
    x +>:TriggeredBy:+> y;
    y +>:TriggeredBy:+> z;

    lin = detect_cycle(x);
    if lin {
        print(f"REJECT: triggered_by cycle detected: {' -> '.join(lin)}");
    } else {
        print("OK: no triggered_by cycle");
    }
}

"""Minimal recursive CTE: a RecursiveUnion feeds rows downstream and loops
feedback through a typed BackRef edge, bounded at 16 iterations with an
explicit termination barrier — the cycle policy from the issue survives."""

node PlanRow {
    has payload: str = "";
    has iteration: int = 0;
}

node RecursiveUnion {
    has iteration: int = 0;
    has max_iteration: int = 16;

    def can_continue() -> bool {
        return self.iteration < self.max_iteration;
    }
}

node CteRef {
    has label: str = "";
}

edge Feeds {
    has channel: str = "base";
}

edge BackRef {
    has channel: str = "feedback";
}

walker Epoch {
    can start with Root entry {
        visit [->:Feeds:->];
    }

    can run with RecursiveUnion entry {
        # Base rows flow downstream; each lap bumps the iteration.
        while here.can_continue() {
            print(f"barrier(iteration={here.iteration}) sent back to cte");
            here.iteration += 1;
        }
        print(f"barrier(iteration=0) sent; halted after {here.iteration} iterations");
        here.iteration = 0;
        visit [->:BackRef:->] else { disengage; }
    }

    can consume with CteRef entry {
        print(f"{here.label} replayed feedback rows");
        visit [-->];
    }

    can record with PlanRow entry {
        print(f"row '{here.payload}' tagged iteration={here.iteration}");
    }
}

with entry {
    u = RecursiveUnion();
    c = CteRef(label="cte");
    root +>:Feeds:+> u;
    u +>:BackRef:+> c;
    c ++> PlanRow(payload="r1") ++> PlanRow(payload="r2");
    root spawn Epoch();
}

"""Performance-gate lab: walk the exact dependency graph of the integrated
Three.js/WebGPU candidate, run the 13-step benchmark playthrough, and collect
frame-timing evidence against the 60 FPS target. Cycle detection is explicit
(jac walkers have no built-in once-per-node visitation)."""

node Dependency {
    has name: str = "";
    has version: str = "";
    has verified: bool = False;
}

node BenchmarkStep {
    has name: str = "";
    has order: int = 0;
    has median_ms: float = 0.0;
}

node Evidence {
    has sha256: str = "";
    has screenshots_kept: bool = True;
    has fps_target: float = 60.0;
    has achieved_fps: float = 0.0;
    has startup_ms: float = 0.0;
    has valid: bool = False;
}

edge DependsOn { }
edge MeasuredIn { }

walker ProvenanceGate {
    has pinned_sha: str = "";
    has unlocked: bool = False;

    can check with Root entry {
        # Fail closed: do not proceed until the observed lock SHA is pinned.
        if self.pinned_sha == "" {
            print("GATE FAIL: dependency provenance not pinned; aborting run");
            disengage;
        }
        self.unlocked = True;
        print("GATE PASS: lock SHA pinned, executing benchmark");
        visit [->:DependsOn:->];
    }

    can verify with Dependency entry {
        if self.pinned_sha in here.name {
            here.verified = True;
        }
        print(f"dep {here.name}@{here.version} verified={here.verified}");
        visit [->:DependsOn:->];
    }

    can measure with BenchmarkStep entry {
        frame_ms = 18.0;
        if here.order == 1 {
            frame_ms = 210.0;
        }
        here.median_ms = frame_ms;
        print(f"step {here.order}: {here.name} median {here.median_ms} ms");
        visit [->:MeasuredIn:->];
    }
}

