    has visited_names: list = [];
    has max_depth: int = 16;

    can audit with Evidence entry {
        meets = here.achieved_fps >= here.fps_target;
        verdict = "MEETS 60 FPS TARGET";
        if not meets {
            verdict = "BELOW 60 FPS TARGET";
        }
        print(f"evidence sha={here.sha256} fps={here.achieved_fps} ({verdict}); "
              f"not a device-readiness claim");
    }

    can walk_deps with Dependency entry {
        # guard set: no built-in once-per-node visitation in jac 0.36
        if here.name in self.visited_names {
            print(f"CYCLE detected at {here.name}; stopping this branch");
            disengage;
        }
        if len(self.visited_names) > self.max_depth {
            print(f"depth limit {self.max_depth} exceeded at {here.name}");
            disengage;
        }
        self.visited_names.append(here.name);
        visit [->:DependsOn:->];
    }
}

