    has source: str = "metadata_ogc_17_003r2";
}

walker LineageTracer {
    has direction: str = "ancestors";
    has max_depth: int = 8;
    has visited: list[str] = [];
    has depth: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can trace with StacItem entry {
        if here.stac_id in self.visited {
            print(f"[cycle guarded] {here.stac_id} at depth {self.depth}");
        } else {
            self.visited.append(here.stac_id);
