"""IronTraffic bundle validation: resolve refs, degrade dangles, detect cycles, enforce budgets."""

node Upstream {
    has name: str = "";
    has anchor_ok: bool = True;  # trust anchor (CA/client cert) present
}

node Route {
    has name: str = "";
    has path: str = "";
    has degraded: bool = False;
    has degraded_reason: str = "";
}

node Bundle {
    has name: str = "";
}

edge References {  # Route -> Upstream ref, resolved in referrer's namespace
    has ns: str = "";
    has resolved: bool = True;
}

edge Contains { }

edge NextRoute { has host: str = ""; }

walker Validator {
    has max_upstreams: int = 100;
    has max_routes: int = 100;
    has seen: dict = {};
    has cyclic: list = [];
    has danglings: int = 0;

    can start with Root entry {
        b = [here for here in [root --> ][0:1]];
        visit [->:Bundle:->] else { disengage; }
    }

    can check_budget with Bundle entry {
        ups = [here->:Contains:->];
        rts = [u for u in ups];
        n_up = len([u for u in ups if u is Upstream]);
        n_rt = len([u for u in ups if u is Route]);
        if n_up > self.max_upstreams or n_rt > self.max_routes {
            print(f"BUDGET BREACH: {n_up} upstreams / {n_rt} routes");
        } else {
            print(f"budget ok: {n_up}/{self.max_upstreams} upstreams, {n_rt}/{self.max_routes} routes");
        }
        visit [->:Contains:->];
    }

    can resolve_ref with Route entry {
        # degrade if any reference is dangling or its upstream lost its anchor
        for e in here --> {
            if e is References and not e.resolved {
                self.danglings += 1;
                here.degraded = True;
                here.degraded_reason = "dangling reference fails closed (503)";
            } elif e is References {
                tgt = [e --> ][0];
                if not tgt.anchor_ok {
                    here.degraded = True;
                    here.degraded_reason = "dangling trust anchor: never dial unverified";
                }
            }
        }
        if here.degraded {
            print(f"[Degraded] route {here.name}: {here.degraded_reason}");
        } else {
            print(f"[OK] route {here.name} {here.path}");
        }
        visit [->:NextRoute:->];
    }

    can probe with Upstream entry {
        # upstream endpoints are leaves of this walk
    }

    can walk_chain with Route exit {
        # cycle detection along NextRoute chain
        if here.name in self.seen {
            if here.name not in self.cyclic {
                self.cyclic.append(here.name);
                print(f"CYCLE detected at route {here.name}");
            }
            disengage;
        }
    }

    can mark with Route entry {
        if here.name not in self.seen {
            self.seen[here.name] = True;
        }
    }
}

with entry {
    b = Bundle(name="prod");
    root +>:Contains:+> b;

    good_up = Upstream(name="payments-svc");
    bad_up = Upstream(name="tenant-b/backend", anchor_ok=False);

    r1 = Route(name="pay-exact", path="/pay");
    r2 = Route(name="pay-catch", path="/pay/");
    r3 = Route(name="orphan", path="/legacy");

    b +>:Contains:+> good_up;
    b +>:Contains:+> bad_up;
    b +>:Contains:+> r1;
    b +>:Contains:+> r2;
    b +>:Contains:+> r3;

    # r1 resolves to a healthy upstream
    r1 +>:References(ns="tenant-a"):+> good_up;
    # r2 points at an upstream with a missing trust anchor
    r2 +>:References(ns="tenant-a"):+> bad_up;
    # r3's reference dangles: target was deleted
    r3 +>:References(ns="tenant-a", resolved=False):+> good_up;

    # attachment chain r1 -> r2 -> r3 -> r1 forms a cycle
    r1 +>:NextRoute(host="a.example"):+> r2;
    r2 +>:NextRoute(host="b.example"):+> r3;
    r3 +>:NextRoute(host="c.example"):+> r1;

    root spawn Validator();
}

