"""Kanban durable plumbing demo: idempotent task creation, system-only block kinds, and a ledger-clearing audit walk.

Tasks own goals via typed GoalFor edges; blocked-by relations use BlockedBy
edges carrying the block kind. The Auditor walker replays lineage over typed
edges with an explicit visited-set cycle policy (no built-in dedupe), and an
IdempotentCreator walker resolves same-key retries to the original task
before any duplicate-title rejection, mirroring SL1-R2-001 precedence.
"""

node Task {
    has title: str = "";
    has idempotency_key: str = "";
    has status: str = "open";
    has is_system_block: bool = False;

    def open() -> bool {
        return self.status == "open";
    }
}

node Goal {
    has label: str = "";
    has budget_epoch: int = 1;
}

node Charge {
    has run_id: str = "";
    has turn_seq: int = 0;
    has amount: int = 0;
}

edge GoalFor { }
edge ChargeOn {
    has task_id: str = "";
}
edge BlockedBy {
    has kind: str = "no_progress";
    has system_only: bool = False;
}

walker IdempotentCreator {
    has key: str = "";
    has title: str = "";
    has rejected: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can resolve with Task entry {
        # idempotency precedence: same-key retry wins over duplicate-title rejection
        if here.idempotency_key == self.key and here.open() {
            print(f"idempotent retry: returning existing task '{here.title}'");
            disengage;
        }
        if here.title == self.title and here.open() {
            self.rejected = True;
            print(f"duplicate active title '{self.title}' rejected (new key)");
            disengage;
        }
    }
}

with entry {
    t1 = Task(title="implement schema", idempotency_key="k-001");
    t2 = Task(title="add block kinds", idempotency_key="k-002");
    g = Goal(label="watch + charges");
    c1 = Charge(run_id="r1", turn_seq=1, amount=3);
    c2 = Charge(run_id="r1", turn_seq=2, amount=5);
    root ++> t1;
    t1 +>:GoalFor:+> g;
    g +>:ChargeOn(task_id="k-001"):+> c1;
    g +>:ChargeOn(task_id="k-001"):+> c2;
    t1 +>:BlockedBy(kind="no_progress", system_only=True):+> t2;
    t2 +>:GoalFor:+> Goal(label="entry guards");

    # idempotent retry: same key, matching active title -> returns original
    root spawn IdempotentCreator(key="k-001", title="implement schema v2");
    # new key but duplicate active title -> rejected
    root spawn IdempotentCreator(key="k-003", title="add block kinds");
    # audit walk over the lineage graph
    root spawn Auditor();
    print("audit complete");
}

"""Episodic-memory triggered_by cycle detection: DFS with a visited set over typed causal edges."""

edge TriggeredBy {
    has note: str = "";
}

node Episode {
    has ref_id: str = "";
    has status: str = "active";
    has category: str = "";
}

walker CycleDetector {
    has path: list[str] = [];
    has visited: list[str] = [];
    has cycle_found: bool = False;
    has cycle_path: list[str] = [];

    can begin with Root entry {
        visit [->:TriggeredBy:->];
    }

    can inspect with Episode entry {
        if here.ref_id in self.visited {
            idx = 0;
            for (i, r) in enumerate(self.path) {
                if r == here.ref_id {
                    idx = i;
                }
            }
            self.cycle_path = self.path[idx:] + [here.ref_id];
            self.cycle_found = True;
            disengage;
        }
        self.visited.append(here.ref_id);
        self.path.append(here.ref_id);
        visit [->:TriggeredBy:->] else { disengage; }
    }
}

def detect_cycle(src: Episode) -> list[str] {
    detector = CycleDetector();
    detector spawn src;
    if detector.cycle_found {
        return detector.cycle_path;
    }
    return [];
}

with entry {
    a = Episode(ref_id="A");
    b = Episode(ref_id="B", category="review");
    c = Episode(ref_id="C");
    a +>:TriggeredBy(note="a->b"):+> b;
    b +>:TriggeredBy(note="b->c"):+> c;
    c +>:TriggeredBy(note="c->a"):+> a;

    cyc = detect_cycle(a);
    if cyc {
        print(f"REJECT: triggered_by cycle detected: {' -> '.join(cyc)}");
    } else {
        print("OK: no triggered_by cycle");
    }

    # linear chain: no cycle expected
    x = Episode(ref_id="X");
    y = Episode(ref_id="Y");
    z = Episode(ref_id="Z");
