"""Ptah canonical schema core: schema objects with typed dependency edges,
a walker that derives a topologically ordered migration plan, and explicit
cycle detection (the safety guard the issue demands must survive)."""

node SchemaObject {
    has name: str = "";
    has kind: str = "";          # "table" | "function" | "view"
    has coverage: str = "PRESENT";  # PRESENT | AUTHORITATIVELY_ABSENT | NOT_DESCRIBED
}

edge DependsOn { }   # a -> b means `a` depends on `b`

walker MigrationPlanner {
    has visited: dict = {};
    has plan: list = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can plan with SchemaObject entry {
        # Explicit cycle policy: no built-in dedupe in jac, and dependency
        # cycles are a domain error that must surface, not be swallowed.
        if here.name in self.visited.keys() {
            print(f"CYCLE detected at {here.name}; aborting plan");
            self.cycle_found = True;
            disengage;
        }
        self.visited[here.name] = True;
        print(f"planned: {here.kind} {here.name} [{here.coverage}]");
        self.plan.append(here.name);
        visit [->:DependsOn:->] else { disengage; }
    }
}

with entry {
