    # orders depends on users; order_items on orders and users;
    # audit_view on orders; trigger function on orders.
    orders +>:DependsOn:+> users;
    order_items +>:DependsOn:+> orders;
    order_items +>:DependsOn:+> users;
    audit_view +>:DependsOn:+> orders;
    trg +>:DependsOn:+> orders;

    root ++> order_items;
