"""Issue tracker: child issues linked by blocking edges; a walker executes the ready frontier in dependency order, with an explicit cycle guard."""

node Issue {
    has title: str = "";
    has number: int = 0;
    has done: bool = False;
    has executed: bool = False;
}

edge Blocks {
    has hard: bool = True;
}

walker Frontier {
    has ready_count: int = 0;
    has executed_titles: list[str] = [];
    has guard: dict = {};
    has depth: int = 0;
    has max_depth: int = 64;

    can start with Root entry {
        visit [->:Blocks:->];
    }

    can schedule with Issue entry {
        # Cycle guard: no built-in dedupe in visit, so track explicitly.
        if here.number in self.guard {
            print(f"cycle detected at #{here.number}, skipping");
            disengage;
        }
        self.guard[here.number] = True;
        self.depth += 1;
        if self.depth > self.max_depth {
            print("depth cap exceeded, aborting walk");
            disengage;
        }
        if here.done {
            print(f"#{here.number} {here.title}: already closed");
            visit [->:Blocks:->];
            self.depth -= 1;
            disengage;
        }
        # Ready only when every blocker is closed.
        blocked = False;
        for b in [here ->:Blocks:->] {
            if not b.done {
                blocked = True;
            }
        }
        if blocked {
            print(f"#{here.number} {here.title}: waiting on open blockers");
            visit [->:Blocks:->];
            self.depth -= 1;
            disengage;
        }
        here.executed = True;
        self.ready_count += 1;
        self.executed_titles += [f"#{here.number} {here.title}"];
        print(f"executing tracer bullet: #{here.number} {here.title}");
        here.done = True;
        visit [->:Blocks:->];
        self.depth -= 1;
    }
}

with entry {
    # 23 tickets, but demo the frontier with a few key slices.
    prov = Issue(number=22, title="Provenance evidence", done=True);
