"""IronTraffic bundle validation: resolve refs, degrade dangles, detect cycles, enforce budgets."""

node Upstream {
    has name: str = "";
    has anchor_ok: bool = True;  # trust anchor (CA/client cert) present
}

node Route {
    has name: str = "";
    has path: str = "";
    has degraded: bool = False;
    has degraded_reason: str = "";
    has dangling_ref: bool = False;  # reference target was deleted
}

node Bundle {
    has name: str = "";
}

edge References { has ns: str = ""; }
edge Contains { }
edge NextRoute { has host: str = ""; }

walker Validator {
    has max_upstreams: int = 100;
    has max_routes: int = 100;
    has seen: dict = {};

    can start with Root entry {
        visit [->:Bundle:->] else { disengage; }
    }

    can check_budget with Bundle entry {
        ups = [here->:Contains:->];
        n_up = len([u for u in ups if u is Upstream]);
        n_rt = len([u for u in ups if u is Route]);
        if n_up > self.max_upstreams or n_rt > self.max_routes {
            print(f"BUDGET BREACH: {n_up} upstreams / {n_rt} routes");
        } else {
            print(f"budget ok: {n_up}/{self.max_upstreams} upstreams, {n_rt}/{self.max_routes} routes");
        }
        visit [->:Contains:->];
    }

    can resolve_ref with Route entry {
        # cycle policy: explicit guard set, a repeat visit means a cycle
        if here.name in self.seen {
            print(f"CYCLE detected at route {here.name}");
            disengage;
        }
        self.seen[here.name] = True;

        # resolve references; a dangling ref degrades instead of removing the route
        refs = [here->:References:->];
        if here.dangling_ref {
            here.degraded = True;
            here.degraded_reason = "dangling reference fails closed (503)";
        } else {
            for up in refs {
                if not up.anchor_ok {
                    here.degraded = True;
                    here.degraded_reason = "dangling trust anchor: never dial unverified";
                }
            }
        }
        if here.degraded {
            print(f"[Degraded] route {here.name}: {here.degraded_reason}");
        } else {
            print(f"[OK] route {here.name} {here.path}");
        }
        visit [->:NextRoute:->] else { disengage; }
    }

    can probe with Upstream entry {
        # upstream endpoints are leaves of this walk
    }
}

