"""Zed package install vs. recursive Git submodules: detect nested submodule
topology and fail closed when the same upstream identity is materialized
both as a Zed package and as a user-managed submodule."""

node ZedPackage {
    has name: str = "";
    has upstream: str = "";
    has pinned_commit: str = "";
}

node Submodule {
    has path: str = "";
    has url: str = "";
    has pinned_commit: str = "";
    has initialized: bool = False;
}

# A repository (or nested submodule worktree) contains packages and submodules.
edge Contains { }
# A submodule nests further submodules (recursive .gitmodules topology).
edge Nests { }

walker SubmoduleAuditor {
    has visited: dict = {};
    has conflicts: list = [];
    has depth: int = 0;
    has max_depth: int = 16;

    can start with Root entry {
        visit [->:Contains:->];
    }

    # Domain logic that must survive: explicit cycle/depth guard, because
    # visit does NOT dedupe on recursive graphs.
    can audit_repo with ZedPackage entry {
        self.visited[here] = True;
        self.depth += 1;
        if self.depth > self.max_depth {
            print(f"[ERROR] submodule recursion exceeded depth {self.max_depth}; aborting");
            disengage;
        }
        visit [->:Contains:->];
        visit [->:Nests:->];
        self.depth -= 1;
    }

    can audit_repo with Submodule entry {
        status = "init" if here.initialized else "uninit";
        print(f"[{status}] submodule {here.path} -> {here.url} @ {here.pinned_commit}");
        self.visited[here] = True;
        self.depth += 1;
        if self.depth > self.max_depth {
            print(f"[ERROR] submodule recursion exceeded depth {self.max_depth}; aborting");
            disengage;
        }
        visit [->:Nests:->];
        self.depth -= 1;
        visit [-->] else { disengage; }
    }

    can exit with ZedPackage | Submodule exit {
        # Fail closed: same upstream materialized in both systems.
        twin = None;
        for k in self.visited.keys() {
            if k isa ZedPackage {
                for s in self.visited.keys() {
                    if s isa Submodule and s.url == k.upstream and s.pinned_commit == k.pinned_commit {
                        twin = s;
                    }
                }
            }
        }
        if twin != None {
            print(f"[CONFLICT] {twin.url} @ {twin.pinned_commit} is both a Zed package and a submodule; refusing duplicate materialization");
        } else {
            print("[OK] no duplicate upstream representation detected");
        }
    }
}

