walker MigrationPlanner {
    has visited: list[str] = [];
    has plan: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can plan with SchemaObject entry {
        # Explicit cycle policy: jac walkers do not dedupe visits, and a
        # dependency cycle is a domain error that must surface, not loop.
        already_seen = False;
        for nm in self.visited {
            if nm == here.name {
                already_seen = True;
            }
        }
        if already_seen {
            print(f"CYCLE detected at {here.name}; aborting plan");
            self.cycle_found = True;
            disengage;
        }
        self.visited.append(here.name);
        print(f"planned: {here.kind} {here.name} [{here.coverage}]");
        self.plan.append(here.name);
        visit [->:DependsOn:->] else { disengage; }
    }

    can finish with Root exit {
        print(f"plan ({len(self.plan)} objects): {', '.join(self.plan)}");
        if self.cycle_found {
            print("status: ABORTED (cycle)");
        } else {
            print("status: OK");
        }
    }
}

