"""GraphVisualizer: turns a graph into per-step BFS/DFS traversal frames.

Nodes are graph vertices connected by typed AdjacentTo edges. The walker
maintains visited set + frontier (queue semantics for BFS, stack for DFS)
and prints one VisualizationFrame per step, replacing the hand-rolled
adjacency-dict plumbing complained about in issue #6.
"""

node Vertex {
    has label: str = "";
}

edge AdjacentTo { }

node VisualizationFrame {
    has visited: list[str] = [];
    has frontier: list[str] = [];
    has current: str = "";
    has edge_used: str = "";
}

walker GraphVisualizer {
    has mode: str = "bfs";
    has visited: list[str] = [];
    has frontier: list[Vertex] = [];
    has steps: list[VisualizationFrame] = [];

    def was_seen(v: Vertex) -> bool {
        for seen in self.visited {
            if seen == v.label { return True; }
        }
        return False;
    }

    def in_frontier(v: Vertex) -> bool {
        for f in self.frontier {
            if f.label == v.label { return True; }
        }
        return False;
    }

    can start with Root entry {
        if self.mode == "bfs" {
            self.frontier.append(here);
        } else {
            self.frontier.insert(0, here);
        }
        visit [->:AdjacentTo:->];
    }

    def emit_frame(cur: Vertex, edge_used: str) {
        labels = [v.label for v in self.frontier];
        frame = VisualizationFrame(
            visited=self.visited,
            frontier=labels,
            current=cur.label,
            edge_used=edge_used
        );
        self.steps.append(frame);
        frame.report();
    }

    def enqueue(v: Vertex) {
        # cycle guard: never enqueue a seen node
        if self.was_seen(v) or self.in_frontier(v) { return; }
        if self.mode == "bfs" {
            self.frontier.append(v);      # queue: popleft side
        } else {
            self.frontier.insert(0, v);   # stack: pop side
        }
    }

    def next_node() -> Vertex | None {
        if len(self.frontier) == 0 { return None; }
        if self.mode == "bfs" {
            return self.frontier.pop(0);   # popleft
        }
        return self.frontier.pop(0);       # pop from stack top (front)
    }

    can traverse with Vertex entry {
        if self.was_seen(here) {
            return;
        }
        edge_used = "";
        for e in here->:AdjacentTo:-> { }
        # record traversal of this vertex, mark visited
        self.visited.append(here.label);
        self.emit_frame(here, edge_used="->" + here.label);

        # expand neighbors: watch add/append on frontier (mutation tracking)
        for neighbor in [here->:AdjacentTo:->] {
            self.enqueue(neighbor);
        }
        nxt = self.next_node();
        if nxt is None {
            visit [-->] else { disengage; }
            disengage;
        }
        # walk directly to the chosen next vertex via its outgoing edges
        visit [nxt->:AdjacentTo:->] else {
            self.emit_frame(cur=nxt, edge_used="dead-end");
            disengage;
        }
    }
}

