walker Validator {
    has max_upstreams: int = 100;
    has max_routes: int = 100;
    has route_count: int = 0;
    has upstream_count: int = 0;
    has seen: dict = {};

    can start with Root entry {
        visit [->:Contains:->] else { disengage; }
    }

    can check_budget with Bundle entry {
        n_up = here.count_upstreams();
        if n_up > self.max_upstreams or self.route_count > self.max_routes {
            print(f"BUDGET BREACH: {n_up} upstreams / {self.route_count} routes");
        } else {
            print(f"budget ok: {n_up}/{self.max_upstreams} upstreams, {self.route_count}/{self.max_routes} routes");
        }
    }

    can resolve_ref with Route entry {
        # cycle policy: explicit guard set, a repeat visit means a cycle
        if here.name in self.seen {
            print(f"CYCLE detected at route {here.name}");
            return;
        }
        self.seen[here.name] = True;
        self.route_count += 1;

        # a dangling ref degrades the route instead of removing it (fails closed)
        if here.dangling_ref {
            here.degraded = True;
            here.degraded_reason = "dangling reference fails closed (503)";
        } else {
            # resolve references; a missing trust anchor is never a downgrade
            for up in [here ->:References:->] {
                if not up.anchor_ok {
                    here.degraded = True;
                    here.degraded_reason = "dangling trust anchor: never dial unverified";
