        if here.degraded {
            print(f"[Degraded] route {here.name}: {here.degraded_reason}");
        } else {
            print(f"[OK] route {here.name} {here.path}");
        }
        visit [->:NextRoute:->] else { disengage; }
    }

    can probe with Upstream entry {
        self.upstream_count += 1;
    }
}

