"""Zed package install vs. recursive Git submodules: walk nested submodule
topology with explicit depth guards and fail closed when the same upstream
identity is materialized both as a Zed package and as a user submodule."""

edge Contains {
    has since: str = "";
}
edge Nests {
    has since: str = "";
}

