walker SubmoduleAuditor {
    has seen_pkgs: list = [];
    has seen_subs: list = [];
    has depth: int = 0;
    has max_depth: int = 16;

    can start with Root entry {
        visit [->:Contains:->] else { disengage; }
    }

    can audit_pkg with ZedPackage entry {
        print(f"[ZED-PKG] {here.name} -> {here.upstream} @ {here.pinned_commit}");
        self.seen_pkgs.append(here);
        self.depth += 1;
        if self.depth > self.max_depth {
            print(f"[ERROR] recursion exceeded depth {self.max_depth}; aborting");
            disengage;
        }
        visit [->:Contains:->] else { disengage; }
        self.depth -= 1;
    }

    can audit_sub with Submodule entry {
        status = "init" if here.initialized else "uninit";
        print(f"[{status}] submodule {here.path} -> {here.url} @ {here.pinned_commit}");
        self.seen_subs.append(here);
        self.depth += 1;
        if self.depth > self.max_depth {
            print(f"[ERROR] recursion exceeded depth {self.max_depth}; aborting");
            disengage;
        }
        visit [->:Nests:->] else { disengage; }
        self.depth -= 1;
    }

    can exit with Root exit {
        conflict = False;
        for s in self.seen_subs {
            for k in self.seen_pkgs {
                if s.url == k.upstream and s.pinned_commit == k.pinned_commit {
                    conflict = True;
                    print(f"[CONFLICT] {s.url} @ {s.pinned_commit} is both a Zed "
                          f"package ({k.name}) and a submodule ({s.path}); "
                          f"refusing duplicate materialization");
                }
            }
        }
        if not conflict {
            print("[OK] no duplicate upstream representation detected");
        }
    }
}

