    can start with Root entry {
        # Ordinary install: touch only Zed-owned materialization, never submodules.
        visit [->:Contains:->] else { disengage; }
    }

    can install with ZedPackage entry {
        print(f"[ZED] materializing package {here.name} @ {here.pinned_commit} into .vendor/.zed");
    }

    can skip with Submodule entry {
        print(f"[SKIP] leaving user-managed submodule {here.path} untouched");
    }
}

