"""Blast radius: reverse dependency traversal computing depth and bottleneck tier.

The in-memory BFS from the issue: walk reverse DependsOn edges from a broken
service, tracking per-node depth (maxDepth capped) and the minimum edge tier
along the best guaranteed path (max-min bottleneck). Cycle guards are explicit
domain logic; traversal is a walker over typed edges.
"""

node Service {
    has name: str = "";
    has broken: bool = False;
}

edge DependsOn {
    has tier: int = 0;  # 0 = critical, 1 = strong, 2 = weak
}

walker BlastRadius {
    has max_depth: int = 3;
    has min_tier_allowed: int = 0;
    has visited: dict = {};
    has radius: dict = {};      # name -> depth
    has tiers: dict = {};       # name -> minTierAlongPath

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can seed with Service entry {
        if here.broken {
            self.visited[here.name] = True;
            self.radius[here.name] = 0;
            self.tiers[here.name] = 99;
            visit [<--:DependsOn:--];
        } else {
            visit [-->] else { disengage; }
        }
    }

    can propagate with Service entry {
        if here.name in self.visited {
            disengage;
        }
        depth = visitor.radius[visitor.from_name];
        tier_in = visitor.from_tier;
        if depth >= self.max_depth {
            disengage;
        }
        if tier_in > self.min_tier_allowed {
            disengage;
        }
        prev_min = visitor.tiers[visitor.from_name];
        min_along = tier_in if tier_in < prev_min else prev_min;
        if (here.name in self.tiers) and (self.tiers[here.name] >= min_along) and (self.radius[here.name] <= depth + 1) {
            disengage;  # already reached by an equal-or-better path
        }
        self.visited[here.name] = True;
        self.radius[here.name] = depth + 1;
        self.tiers[here.name] = min_along;
        visitor.from_name = here.name;
        visit [<--:DependsOn:--];
    }

    can relay_tier with DependsOn entry {
        visitor.from_name = here.name;
    }

    can report_radius with Service exit {
        if here.broken {
            report {"blast_radius": self.radius, "min_tiers": self.tiers};
        }
    }
}

walker AttachDeps {
    can build with Service entry {
        visit [-->];
    }
}

with entry {
    api = Service(name="api", broken=True);
    auth = Service(name="auth");
    billing = Service(name="billing");
    db = Service(name="db");
    cache = Service(name="cache");
    reports = Service(name="reports");

    # X depends on Y  =>  X +>:DependsOn:+> Y ; reverse traversal goes Y <- X
    auth +>:DependsOn(tier=0):+> api;
    billing +>:DependsOn(tier=1):+> api;
    reports +>:DependsOn(tier=2):+> api;
    api +>:DependsOn(tier=0):+> db;
    api +>:DependsOn(tier=0):+> cache;
    reports +>:DependsOn(tier=1):+> db;   # second path to db via weaker tier

    root ++> api ++> auth ++> billing ++> reports;

    root spawn BlastRadius(max_depth=3, min_tier_allowed=1);
}

