    has seen: dict = {};
    has errors: list[str] = [];
    has on_path: set = {};
    has resource_holders: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can audit_stage with Stage entry {
        if here.sid in self.seen {
            self.errors += [f"duplicate stage id {here.sid}"];
            disengage;
        }
        self.seen[here.sid] = True;
        if here.is_evidence and here.closure_authority == "" {
            self.errors += [f"evidence stage {here.sid} lacks closure authority"];
        }
        if here.external_write and here.owner != "maintainer" {
            self.errors += [f"stage {here.sid} external write not maintainer-owned"];
        }
        self.on_path.add(here.sid);
        visit [->:DependsOn:->] else {
            self.on_path.discard(here.sid);
            disengage;
        }
        self.on_path.discard(here.sid);
    }

    can check_dep with Stage exit {
        for (n) in [here ->:DependsOn:->] {
            if n.sid not in self.seen {
                self.errors += [f"stage {here.sid} depends on unknown {n.sid}"];
            } else if n.sid in self.on_path {
                self.errors += [f"dependency cycle via {here.sid} -> {n.sid}"];
            }
        }
        for (r) in [here ->:Excludes:->] {
            key = f"{r.sid}@{here.wave}";
            if key in self.resource_holders {
                self.errors += [f"same-wave exclusive collision on {r.sid} wave {here.wave}: {self.resource_holders[key]} vs {here.sid}"];
            } else {
                self.resource_holders[key] = here.sid;
            }
        }
    }

    can audit_decision with Decision entry {
        if here.did in self.seen {
            self.errors += [f"duplicate decision id {here.did}"];
            disengage;
        }
        self.seen[here.did] = True;
        if here.state == "open" {
            self.errors += [f"open decision {here.did} cannot render ready architecture"];
        }
        visit [-->];
    }
}

