        roots = [e for e in [-->] if isinstance(e, Task)];
        if roots {
            for r in roots {
                # schedule everything reachable below each root
            }
        }
        # find all tasks reachable from here with zero incoming unscheduled deps:
        # simplest native policy: repeatedly schedule ready tasks (Kahn layers).
        all_tasks = here -->;
        pending = list(all_tasks);
        self.done = {};
        while pending {
            ready = [t for t in pending
                     if all(p in self.done
                            for p in [t <-:DependsOn:-])];
            if not ready {
                print("cycle detected — cannot schedule remaining tasks");
                disengage;
