        } else {
            visit [-->] else { disengage; }
        }
    }

    can propagate with Service entry {
        if here.name in self.seen {
            depth_here = 0;
            if here.name in self.radius {
                depth_here = self.radius[here.name];
            }
            if self.tiers[here.name] >= self.carry_tier and depth_here <= self.radius[self.carry_name] + 1 {
                disengage;  # already reached by an equal-or-better path
            }
        }
        if self.radius[self.carry_name] >= self.max_depth {
            disengage;
        }
        if self.carry_tier > self.min_tier_allowed {
            disengage;
        }
        prev_min = self.tiers[self.carry_name];
        min_along = self.carry_tier if self.carry_tier < prev_min else prev_min;
        self.seen[here.name] = True;
        self.radius[here.name] = self.radius[self.carry_name] + 1;
        self.tiers[here.name] = min_along;
        self.carry_name = here.name;
        visit [->:DependsOn:->] else { disengage; }
    }

    can relay_tier with DependsOn entry {
        visitor.carry_tier = here.tier;
    }

    can finish with Service exit {
        if here.broken {
            report {"blast_radius": self.radius, "min_tiers": self.tiers};
        }
    }
}

