"""Stable Zed agent train contract: stages and decisions as a typed graph.

Falsifier walker visits hard-dependency edges, detects cycles and unknown
dependencies, checks evidence stages carry closure authority, and flags
same-wave exclusive resource collisions.
"""

node Stage {
    has sid: str = "";
    has phase: str = "core";
    has kind: str = "implementation";
    has owner: str = "";
    has wave: int = 0;
    has closure_authority: str = "";
    has is_evidence: bool = False;
    has external_write: bool = False;
}

node Decision {
    has did: str = "";
    has state: str = "open";
    has statement: str = "";
    has authority: str = "";
}

edge DependsOn { }
edge GovernedBy { }
edge Claims { }
edge Excludes { }

walker ContractAuditor {
    has seen: dict = None;
    has errors: list = None;
    has on_path: list = None;
    has resource_holders: dict = None;

    def note(msg: str) {
        self.errors.append(msg);
    }

    can start with Root entry {
        self.seen = {};
        self.errors = [];
        self.on_path = [];
        self.resource_holders = {};
        visit [-->];
    }

    can audit_stage with Stage entry {
        if here.sid in self.seen {
            self.note(f"duplicate stage id {here.sid}");
            disengage;
        }
        self.seen[here.sid] = True;
        if here.is_evidence and here.closure_authority == "" {
            self.note(f"evidence stage {here.sid} lacks closure authority");
        }
        if here.external_write and here.owner != "maintainer" {
            self.note(f"stage {here.sid} external write not maintainer-owned");
        }
        self.on_path.append(here.sid);
        visit [->:DependsOn:->] else {
            self.on_path.pop();
            disengage;
        }
        self.on_path.pop();
    }

    can check_dep with Stage exit {
        for (n) in [here ->:DependsOn:->] {
            if n.sid not in self.seen {
                self.note(f"stage {here.sid} depends on unknown {n.sid}");
            } else if n.sid in self.on_path {
                self.note(f"dependency cycle via {here.sid} -> {n.sid}");
            }
        }
        for (r) in [here ->:Excludes:->] {
            key = f"{r.sid}@{here.wave}";
            if key in self.resource_holders {
                self.note(f"same-wave exclusive collision on {r.sid} wave {here.wave}: {self.resource_holders[key]} vs {here.sid}");
            } else {
                self.resource_holders[key] = here.sid;
            }
        }
    }

    can audit_decision with Decision entry {
        if here.did in self.seen {
            self.note(f"duplicate decision id {here.did}");
            disengage;
        }
        self.seen[here.did] = True;
        if here.state == "open" {
            self.note(f"open decision {here.did} cannot render ready architecture");
        }
        visit [-->];
    }

    can finish with Root exit {
        if len(self.errors) == 0 {
            print("contract audit: PASS");
        } else {
            for (e) in self.errors {
                print(f"FALSIFIER: {e}");
            }
        }
    }
}

walker Explainer {
    can start with Root entry {
        visit [-->];
    }
    can explain with Stage entry {
        deps = [d.sid for (d) in [here ->:DependsOn:->]];
        print(f"stage {here.sid} ({here.phase}/{here.kind}, owner={here.owner}, wave={here.wave}) depends on {deps}");
        visit [->:DependsOn:->];
    }
    can explain_decision with Decision entry {
        print(f"decision {here.did} [{here.state}]: {here.statement}");
    }
}

