"""Discovered parallelism: infer parallel execution groups from the dependency graph.

Each prerequisite is a typed DependsOn edge (task -> its prerequisite).
The Planner walker collects every reachable task and layers them Kahn-style:
a task is ready once all of its prerequisites are done, so independent
tasks land in the same parallel group.
"""

node Task {
    has name: str = "";

    def deps() -> list[Task] {
        return [self ->:DependsOn:->];
    }
}

edge DependsOn { }

walker Planner {
    has tasks: list[Task] = [];
    has done_names: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can collect with Task entry {
        seen = False;
        for t in self.tasks {
            if t.name == here.name {
                seen = True;
            }
        }
        if not seen {
            self.tasks.append(here);
        }
        visit [-->] else { disengage; }
    }

    can plan with Root exit {
        remaining = list(self.tasks);
        while remaining {
            ready = [];
            for t in remaining {
                ok = True;
                for d in t.deps() {
                    ddone = False;
                    for dn in self.done_names {
                        if dn == d.name {
                            ddone = True;
                        }
                    }
                    if not ddone {
                        ok = False;
                    }
                }
                if ok {
                    ready.append(t);
                }
            }
            if not ready {
                print("cycle detected — cannot schedule remaining tasks");
                disengage;
            }
            names = [];
            for t in ready {
                names.append(t.name);
                self.done_names.append(t.name);
            }
            print("parallel group: " + ", ".join(names));
            nxt = [];
            for x in remaining {
                drop = False;
                for r in ready {
                    if r.name == x.name {
                        drop = True;
                    }
                }
                if not drop {
                    nxt.append(x);
                }
            }
            remaining = nxt;
        }
    }
}

