"""GraphVisualizer: BFS and DFS walkers emit per-step traversal frames.

Adjacency is modeled with typed Adjacent edges instead of adjacency dicts;
each traversal step records the visited set, frontier (queue or stack),
current node and the edge just traversed, as the issue demands.
"""

node GraphNode {
    has name: str = "";
}

edge Adjacent { }

node Frame {
    has kind: str = "";
    has step: int = 0;
    has visited: str = "";
    has frontier: str = "";
    has current: str = "";
    has via: str = "";
}

walker GraphVisualizer {
    has mode: str = "BFS";
    has visited: list[str] = [];
    has frontier: list[str] = [];
    has step: int = 0;
    has last_edge: str = "";

    def mark(name: str) -> None {
        if name not in self.visited {
            self.visited.append(name);
        }
    }

    def emit(current: str) -> None {
        self.step += 1;
        here +>:HasFrame:+> Frame(
            kind=self.mode,
            step=self.step,
            visited=", ".join(self.visited),
            frontier=", ".join(self.frontier),
            current=current,
            via=self.last_edge,
        );
    }

    def seen(name: str) -> bool {
        return name in self.visited;
    }

    def neighbor_names() -> list[str] {
        result = [];
        for n in [here ->:Adjacent:->] {
            result.append(n.name);
        }
        return result;
    }

    can start with Root entry {
        visit [->:Start:->];
    }

    can traverse with GraphNode entry {
        # Cycle policy: explicit visited set (no built-in dedupe in jac 0.36).
        if self.seen(here.name) {
            disengage;
        }
        self.mark(here.name);
        self.emit(here.name);
        for nbr in self.neighbor_names() {
            self.last_edge = f"{here.name}->{nbr}";
            if self.mode == "BFS" {
                self.frontier.append(nbr);
            } else {
                self.frontier.insert(0, nbr);
            }
        }
        while len(self.frontier) > 0 {
            nxt = self.frontier.pop(0) if self.mode == "BFS" else self.frontier.pop(0);
            target = None;
            for n in [here ->:Adjacent:->] {
                if n.name == nxt {
                    target = n;
                }
            }
            if target is None {
                continue;
            }
            if not self.seen(target.name) {
                visit [here ->:Adjacent:->] else { continue; }
            }
        }
    }
}

edge Start { }
edge HasFrame { }

