    a = GraphNode(name="A");
    b = GraphNode(name="B");
    c = GraphNode(name="C");
    d = GraphNode(name="D");
    root +>:Start:+> a;
    a +>:Adjacent:+> b;
    a +>:Adjacent:+> c;
    b +>:Adjacent:+> d;
