    }

    can audit_stage with Stage entry {
        if here.sid in self.seen {
            self.note(f"duplicate stage id {here.sid}");
            disengage;
        }
        self.seen[here.sid] = True;
        if here.is_evidence and here.closure_authority == "" {
            self.note(f"evidence stage {here.sid} lacks closure authority");
        }
        if here.external_write and here.owner != "maintainer" {
            self.note(f"stage {here.sid} external write not maintainer-owned");
        }
        for (n) in [here ->:DependsOn:->] {
            if n.sid not in self.seen and n.sid not in self.on_path {
                # unknown deps reported after walk completes if never visited
                self.note(f"stage {here.sid} depends on stage {n.sid}");
            } else if n.sid in self.on_path {
                self.note(f"dependency cycle via {here.sid} -> {n.sid}");
            }
        }
        for (r) in [here ->:Excludes:->] {
            key = f"{r.sid}@{here.wave}";
            if key in self.resource_holders {
                self.note(f"same-wave exclusive collision on {r.sid} wave {here.wave}: {self.resource_holders[key]} vs {here.sid}");
            } else {
                self.resource_holders[key] = here.sid;
            }
        }
        self.on_path.append(here.sid);
        visit [->:DependsOn:->] else {
            self.on_path.pop();
            disengage;
        }
        self.on_path.pop();
    }

    can audit_decision with Decision entry {
        if here.did in self.seen {
            disengage;
        }
        self.seen[here.did] = True;
        if here.state == "open" {
            self.note(f"open decision {here.did} cannot render ready architecture");
        }
        visit [-->] else { disengage; }
    }

    can finish with Root exit {
        if len(self.errors) == 0 {
            print("contract audit: PASS");
        } else {
            for (e) in self.errors {
                print(f"FALSIFIER: {e}");
            }
        }
    }
}

walker Explainer {
    can start with Root entry {
        visit [-->];
    }
    can explain with Stage entry {
        visit [->:DependsOn:->] else {
            print(f"stage {here.sid} ({here.phase}/{here.kind}, owner={here.owner}, wave={here.wave}) has no unresolved hard dependencies");
            disengage;
        }
    }
    can explain_decision with Decision entry {
        print(f"decision {here.did} [{here.state}]: {here.statement}");
    }
}

