"""Blast radius: reverse dependency traversal computing depth and bottleneck tier.

The in-memory BFS from the issue: walk reverse dependency edges from a broken
service, tracking per-node depth (maxDepth capped) and the minimum edge tier
along the best guaranteed path (max-min bottleneck). Each dependency is a Dep
node carrying its tier, so the walker relays the tier across the node without
edge-payload plumbing. Cycle guards and tier pruning are explicit domain logic.
"""

node Service {
    has name: str = "";
    has broken: bool = False;
}

node Dep {
    has tier: int = 0;  # 0 = critical, 1 = strong, 2 = weak
}

walker BlastRadius {
    has max_depth: int = 3;
    has min_tier_allowed: int = 0;
    has active: bool = False;    # traversal armed once the broken service is found
    has seen: dict = {};
    has radius: dict = {};       # name -> depth from broken service
    has tiers: dict = {};        # name -> minTierAlongPath
    has carry_name: str = "";
    has carry_tier: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can visit_service with Service entry {
        if not self.active {
            if here.broken {
                self.active = True;
                self.seen[here.name] = True;
                self.radius[here.name] = 0;
                self.tiers[here.name] = 99;
                self.carry_name = here.name;
                self.carry_tier = 99;
                visit [-->] else { disengage; }
            } else {
                visit [-->] else { disengage; }
            }
        } else {
            if here.name in self.seen {
                cur_depth = self.radius[here.name];
                cur_min = self.tiers[here.name];
                new_depth = self.radius[self.carry_name] + 1;
                prev_min = self.tiers[self.carry_name];
                new_min = self.carry_tier if self.carry_tier < prev_min else prev_min;
                better = (new_min > cur_min) or (new_min == cur_min and new_depth < cur_depth);
                if not better {
                    disengage;
                }
            }
            if self.radius[self.carry_name] >= self.max_depth {
                disengage;
            }
            if self.carry_tier > self.min_tier_allowed {
                disengage;
            }
            prev_min = self.tiers[self.carry_name];
            new_min = self.carry_tier if self.carry_tier < prev_min else prev_min;
            self.seen[here.name] = True;
            self.radius[here.name] = self.radius[self.carry_name] + 1;
            self.tiers[here.name] = new_min;
            self.carry_name = here.name;
            visit [-->] else { disengage; }
        }
    }

    can cross_dep with Dep entry {
        self.carry_tier = here.tier;
        visit [-->] else { disengage; }
    }

    can finish with Service exit {
        if here.broken and self.active {
            report {"blast_radius": self.radius, "min_tiers": self.tiers};
        }
    }
}

with entry {
    api = Service(name="api", broken=True);
    auth = Service(name="auth");
    billing = Service(name="billing");
    db = Service(name="db");
    cache = Service(name="cache");
    reports = Service(name="reports");

    # provider +> Dep(tier) +> dependent: provider depends on dependent
    api +> Dep(tier=0) +> auth;
    api +> Dep(tier=1) +> billing;
    api +> Dep(tier=2) +> reports;
    db +> Dep(tier=0) +> api;
    cache +> Dep(tier=0) +> api;
    db +> Dep(tier=1) +> reports;   # second path to reports via weaker tier

    root ++> api ++> db ++> cache;
    root spawn BlastRadius(max_depth=3, min_tier_allowed=1);
}

