"""Recursive SKILL.md discovery: walk the skills tree over typed edges,
recording every directory containing a SKILL.md as an unresolved package
root, under an entry budget, without a fixed-depth assumption."""

node Dir {
    has name: str = "";
}

node SkillMd {
    has label: str = "SKILL.md";
}

node PackageRef {
    has reference: str = "";
    has status: str = "unresolved";
}

edge Contains {
    has weight: int = 1;
}

edge RootedAt {
    has kind: str = "package_root";
}

walker Discovery {
    has budget: int = 100;
    has max_refs: int = 10;
    has max_ref_len: int = 120;
    has found: int = 0;
    has scanned: int = 0;
    has path: list[str] = [];

    can start with Root entry {
        visit [->:Contains:->] else { disengage; }
    }

    can descend with Dir entry {
        self.scanned += 1;
        if self.scanned > self.budget {
            print("[FAIL-CLOSED] traversal budget exceeded; scan aborted");
            disengage;
        }
        if here.name != "skills" {
            self.path = self.path + [here.name];
        } else {
            self.path = [];
        }
        visit [->:Contains:->] else { self.path = self.path[:-1]; }
    }

    can found_skill with SkillMd entry {
        reference = "/".join(self.path);
        if len(reference) > self.max_ref_len {
            print(f"[FAIL-CLOSED] reference too long: {reference}");
        } else {
            if self.found >= self.max_refs {
                print("[FAIL-CLOSED] max packages reached; ignoring extra package");
            } else {
                self.found += 1;
                root_ref = PackageRef(reference=reference);
                here +>:RootedAt:+> root_ref;
                print(f"discovered unresolved package: {reference}");
            }
        }
    }
}

