"""Discovered parallelism: infer parallel execution groups from the dependency graph.

Each prerequisite is a typed DependsOn edge (task -> its prerequisite).
The Planner walker collects every reachable task and layers them Kahn-style:
a task is ready once all of its prerequisites are done, so independent
tasks land in the same parallel group.
"""

node Task {
    has name: str = "";

    def deps() -> list[Task] {
        out: list[Task] = [];
        for d in [self ->:DependsOn:->] {
            out.append(d);
        }
        return out;
    }
}

edge DependsOn { }

walker Planner {
    has tasks: list[Task] = [];
    has done_names: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can collect with Task entry {
        seen: bool = False;
        for t: Task in self.tasks {
            if t.name == here.name {
                seen = True;
            }
        }
        if not seen {
            self.tasks.append(here);
        }
        visit [-->] else { disengage; }
    }

    can plan with Root exit {
        remaining: list[Task] = list(self.tasks);
        while len(remaining) > 0 {
            ready: list[Task] = [];
            for t: Task in remaining {
                ok: bool = True;
                for d: Task in t.deps() {
                    ddone: bool = False;
                    for dn: str in self.done_names {
                        if dn == d.name {
                            ddone = True;
                        }
                    }
                    if not ddone {
                        ok = False;
                    }
                }
                if ok {
                    ready.append(t);
                }
            }
            if len(ready) == 0 {
                print("cycle detected - cannot schedule remaining tasks");
                disengage;
            }
            names: list[str] = [];
            for t: Task in ready {
                names.append(t.name);
                self.done_names.append(t.name);
            }
            print("parallel group: " + ", ".join(names));
            nxt: list[Task] = [];
            for x: Task in remaining {
                drop: bool = False;
                for r: Task in ready {
                    if r.name == x.name {
                        drop = True;
                    }
                }
                if not drop {
                    nxt.append(x);
                }
            }
            remaining = nxt;
        }
    }
}

with entry {
    setup = Task(name="setup");
    build = Task(name="build");
    lint = Task(name="lint");
    typecheck = Task(name="typecheck");
