    test +>:DependsOn:+> typecheck;
    release +>:DependsOn:+> test;

    root ++> release;
    root spawn Planner();
}

"""Workflow DAG orchestration: workflow nodes as archetypes, dependency
edges, and a Scheduler walker that resolves topology with a cycle guard."""

node FlowNode {
    has name: str = "";
    has node_type: str = "";
    has done: bool = False;
    has approved: bool = False;
    has value: int = 0;

    def ready() -> bool {
        if self.node_type == "human" {
            return self.approved;
        }
        return True;
    }
}

edge DependsOn {
    has kind: str = "sequential";
}

edge RoutesTo {
    has label: str = "";
}

edge FanOut { }
edge FanIn { }

walker Scheduler {
    has visited: dict = {};
    has order: list[str] = [];
    has cycle_found: bool = False;

    def mark_seen(n: FlowNode) -> str {
        key = f"{n.node_type}:{n.name}";
        if key in self.visited {
            self.cycle_found = True;
            print(f"[CYCLE] detected at {key}");
            return "skip";
        }
        self.visited[key] = True;
        return "new";
    }

    can start with Root entry {
        print("Scheduler: resolving workflow DAG");
        visit [-->];
    }

    can dispatch with FlowNode entry {
        state = self.mark_seen(here);
        if state == "skip" {
            disengage;
        }
        if not here.ready() {
            print(f"[BLOCKED] {here.name} waits for human approval");
            disengage;
        }
        here.done = True;
        self.order.append(here.name);
        print(f"[RUN {here.node_type}] {here.name}");
        if here.node_type == "join" {
            visit [-->] else { disengage; }
            disengage;
        }
        if here.node_type == "branch" {
            label = "urgent" if here.value > 5 else "digest";
            print(f"[BRANCH] routing via {label}");
            visit [here->:RoutesTo:->] else { disengage; }
            disengage;
        }
        if here.node_type == "parallel" {
            visit [here->:FanOut:->];
            disengage;
        }
        visit [-->] else { disengage; }
    }

    can report with Root exit {
        print(f"Order: {self.order}");
        print(f"Cycle detected: {self.cycle_found}");
    }
}

with entry {
    trigger = FlowNode(name="monday_cron", node_type="trigger");
    fetch = FlowNode(name="fetch_prs", node_type="agent", value=8);
    branch = FlowNode(name="pr_router", node_type="branch", value=8);
    urgent = FlowNode(name="urgent_review", node_type="agent");
