node Field {
    has field_id: str = "";              # DVT stable FieldId
    has substrait_ref: int = 0;          # positional Substrait reference
    has label: str = "";                 # editable user-facing name
}

edge FlowsTo { }                          # card pipeline ordering
edge BindsTo { has direction: str = ""; } # identity sidecar binding
edge Produces { }                         # card -> field

walker PlanAuditor {
    has visited: list[str] = [];          # explicit cycle guard (no built-in dedupe)
    has card_count: int = 0;
    has unsupported: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can audit with RelationCard entry {
        # Cycle policy: skip already-audited cards explicitly.
        if here.relation_id in self.visited {
            disengage;
        }
        self.visited.append(here.relation_id);
        self.card_count += 1;
        if not here.supported {
            self.unsupported.append(f"{here.name}:{here.substrait_op}");
            disengage;
        }
        print(f"card {here.relation_id} = {here.substrait_op} ({here.name})");
        visit [->:FlowsTo:->] else { disengage; }
    }

    can check_fields with Field entry {
        status = "renamed" if here.label != here.field_id else "original";
        print(f"field {here.field_id} -> substrait ref {here.substrait_ref} ({status})");
        visit [-->];
