}

walker IdentityProbe {
    can start with Root entry {
        visit [->:BindsTo:->];
    }

    can probe with Field entry {
        print(f"binding: {here.field_id} stable across substrait ref {here.substrait_ref}");
        visit [-->];
    }

    can probe_card with RelationCard entry {
        print(f"card identity {here.relation_id} bound to pinned substrait op {here.substrait_op}");
