"""Workflow DAG orchestration: workflow nodes as archetypes, dependency
edges, and a Scheduler walker that resolves topology with a cycle guard."""

node FlowNode {
    has name: str = "";
    has node_type: str = "";
    has done: bool = False;
    has approved: bool = False;
    has value: int = 0;

    def ready() -> bool {
        if self.node_type == "human" {
            return self.approved;
        }
        return True;
    }
}

edge DependsOn {
    has kind: str = "sequential";
}

edge RoutesTo {
    has label: str = "";
}

edge FanOut { }
edge FanIn { }

walker Scheduler {
    has visited: dict = {};
    has order: list[str] = [];
    has cycle_found: bool = False;

    def mark_seen(n: FlowNode) -> str {
        key = f"{n.node_type}:{n.name}";
        if key in self.visited {
            self.cycle_found = True;
            print(f"[CYCLE] detected at {key}");
            return "skip";
        }
        self.visited[key] = True;
        return "new";
    }

    can start with Root entry {
        print("Scheduler: resolving workflow DAG");
        visit [-->];
    }

    can dispatch with FlowNode entry {
        state = self.mark_seen(here);
        if state == "skip" {
            disengage;
        }
        if not here.ready() {
            print(f"[BLOCKED] {here.name} waits for human approval");
            disengage;
        }
        here.done = True;
        self.order.append(here.name);
        print(f"[RUN {here.node_type}] {here.name}");
        if here.node_type == "branch" {
            label = "urgent" if here.value > 5 else "digest";
            print(f"[BRANCH] routing via {label}");
            visit [->:RoutesTo:->] else { disengage; }
            disengage;
        }
        if here.node_type == "parallel" {
            visit [->:FanOut:->];
            disengage;
        }
        visit [-->] else { disengage; }
    }

    can report with Root exit {
        print(f"Order: {self.order}");
        print(f"Cycle detected: {self.cycle_found}");
    }
}

with entry {
    trigger = FlowNode(name="monday_cron", node_type="trigger");
    fetch = FlowNode(name="fetch_prs", node_type="agent", value=8);
    branch = FlowNode(name="pr_router", node_type="branch", value=8);
    urgent = FlowNode(name="urgent_review", node_type="agent");
    digest = FlowNode(name="weekly_digest", node_type="agent");
    audit = FlowNode(name="security_audit", node_type="agent");
    perf = FlowNode(name="perf_analysis", node_type="agent");
    join = FlowNode(name="join_gate", node_type="join");
    human = FlowNode(name="human_signoff", node_type="human", approved=False);
    out = FlowNode(name="telegram_send", node_type="output");

    root ++> trigger;
    trigger +>:DependsOn(kind="sequential"):+> fetch;
    fetch +>:DependsOn(kind="sequential"):+> branch;
    branch +>:RoutesTo(label="urgent"):+> urgent;
    branch +>:RoutesTo(label="digest"):+> digest;
    urgent +>:FanIn:+> join;
    digest +>:FanIn:+> join;
    join +>:FanOut:+> audit;
    join +>:FanOut:+> perf;
    audit +>:DependsOn:+> human;
    perf +>:DependsOn:+> human;
    human +>:DependsOn(kind="sequential"):+> out;

    root spawn Scheduler();
}

"""Recursive media folder import: walk a dropped directory tree and recreate
the nested folder hierarchy in the media workspace, uploading each file into
its corresponding folder (issue #12)."""

edge Contains { has rel_path: str = ""; }
edge Child { has name: str = ""; }
edge ImportedInto { }

node MediaFolder {
    has name: str = "";
    has path: str = "";

    def child_folder(child_name: str) -> MediaFolder | None {
        for k in [here->:Contains:->] {
            if k.name == child_name {
                return k;
            }
        }
        return None;
    }
}

node MediaFile {
    has name: str = "";
    has size_bytes: int = 0;
}

node DirEntry {
    has name: str = "";
    has is_file: bool = False;
    has size_bytes: int = 0;
}

walker FolderImporter {
    has dest: MediaFolder | None = None;
    has visited: dict = static();
    has files_found: int = 0;
    has folders_created: int = 0;
    has total_bytes: int = 0;
    has summary: list[str] = [];

    can start with Root entry {
        # Preflight destination: default to the workspace root folder.
        if self.dest is None {
            self.dest = MediaFolder(name="All files", path="");
            root +>:ImportedInto:+> self.dest;
        }
        visit [->:Child:->];
    }

    can import_entry with DirEntry entry {
        # Cycle policy: explicit visited guard — walkers do not dedupe.
        key = here.name + str(id(here));
        if self.visited.get(key, False) {
            disengage;
        }
        self.visited[key] = True;

        if here.is_file {
            # Upload the file straight into the destination folder.
            f = MediaFile(name=here.name, size_bytes=here.size_bytes);
            self.dest +>:Contains(rel_path=here.name):+> f;
            self.files_found += 1;
            self.total_bytes += here.size_bytes;
            self.summary.append(f"file {here.name} -> {self.dest.path}");
        } else {
            # Create or reuse the nested media folder, then descend.
            nxt = self.dest.child_folder(here.name);
            created = "reused";
            if nxt is None {
                nxt = MediaFolder(
                    name=here.name,
                    path=self.dest.path + "/" + here.name if self.dest.path != "" else here.name
                );
                self.dest +>:Contains(rel_path=here.name):+> nxt;
                created = "created";
                self.folders_created += 1;
            }
            self.summary.append(f"{created} folder {nxt.path}");

            # Recurse into this folder with the walker's own state carried.
            sub = FolderImporter(
                dest=nxt,
                visited=self.visited,
                files_found=self.files_found,
                folders_created=self.folders_created,
                total_bytes=self.total_bytes,
                summary=self.summary
            );
            here spawn sub;
            self.files_found = sub.files_found;
            self.folders_created = sub.folders_created;
            self.total_bytes = sub.total_bytes;
            self.summary = sub.summary;
        }
        visit [->:Child:->] else { disengage; }
    }
}

with entry {
    # A dropped directory tree: Campaign assets/{Logos, Photography}.
    campaign = DirEntry(name="Campaign assets");
    logos = DirEntry(name="Logos");
    photo = DirEntry(name="Photography");
    campaign +>:Child:+> logos;
    campaign +>:Child:+> photo;
    logos +>:Child:+> DirEntry(name="primary.svg", is_file=True, size_bytes=2048);
    logos +>:Child:+> DirEntry(name="reversed.svg", is_file=True, size_bytes=1980);
    photo +>:Child:+> DirEntry(name="hero.jpg", is_file=True, size_bytes=940320);

    brand = MediaFolder(name="Brand", path="Brand");
    root +>:ImportedInto:+> brand;

    root +>:Child:+> campaign;

    imp = FolderImporter(dest=brand);
    root spawn imp;

    print(f"Import into '{brand.name}': {imp.folders_created} folders created, "
          f"{imp.files_found} files, {imp.total_bytes} bytes");
    for line in imp.summary {
        print(f"  - {line}");
    }
}

"""Typed upgrade patch slice 1: validate term identity and compute the
complete semantic frontier by walking typed DependsOn edges with an
explicit cycle guard (no built-in visitation dedupe in jac 0.36.1)."""

node Term {
    has term_id: str = "";
    has validated: bool = False;
}

node Module {
    has name: str = "";
}

edge DependsOn {
    has relation: str = "";  # type, effect, import, re-export, ...
}

edge BelongsTo { }

walker SchemaValidator {
    can start with Root entry {
        visit [->:BelongsTo:->] else { disengage; };
    }

    can check_term with Term entry {
        ok = here.term_id != "";
        here.validated = ok;
        label = "valid" if ok else "INVALID";
        print(f"schema check: {here.term_id} -> {label}");
        visit [-->] else { disengage; };
    }

    can enter_module with Module entry {
        print(f"entering module {here.name}");
        visit [-->] else { disengage; };
    }
}

walker FrontierCalculator {
    has visited: dict = {};
    has frontier: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can collect_module with Module entry {
        visit [-->] else { disengage; };
    }

    can collect_term with Term entry {
        # explicit cycle policy: each term enters the frontier at most once
        if here.term_id in self.visited {
            print(f"cycle/skip guard: {here.term_id} already on frontier");
            disengage;
        }
        if not here.validated {
            print(f"refuse: {here.term_id} failed schema validation");
            disengage;
        }
        self.visited[here.term_id] = True;
        self.frontier.append(here.term_id);
        print(f"frontier += {here.term_id}");
        visit [->:DependsOn:->] else { disengage; };
    }
}

with entry {
    m = Module(name="core");
    root +>:BelongsTo:+> m;

    t_id = Term(term_id="term::add");
    t_int = Term(term_id="term::int_ctor");
    t_eff = Term(term_id="term::io_effect");
    t_rec = Term(term_id="term::recursive_fix");

    m +>:DependsOn(relation="member"):+> t_id;
    m +>:DependsOn(relation="constructor"):+> t_int;
    t_id +>:DependsOn(relation="effect"):+> t_eff;
    t_eff +>:DependsOn(relation="recursive"):+> t_rec;
    t_rec +>:DependsOn(relation="recursive"):+> t_eff;  # cycle

    m +>:DependsOn(relation="unvalidated_import"):+> Term(term_id="");

    root spawn SchemaValidator();
    root spawn FrontierCalculator();
}

"""Lazy hash cache with mutator self-invalidation: nodes cache hash on request;
mutators reset the cache so it is either empty or valid, never stale."""

node Expression {
    has label: str = "";
    has cached_hash: int = 0;

    # Lazy compute-on-request (0 sentinel = empty cache).
    def hash_value() -> int {
        if self.cached_hash == 0 {
            child_sum = 0;
            for c in self --> {
                child_sum += c.hash_value();
            }
            self.cached_hash = (len(self.label) * 31 + child_sum) % 1000003;
        }
        return self.cached_hash;
    }

    # Mutators self-invalidate: cache is either empty or valid, never stale.
    def set_label(new_label: str) {
        self.label = new_label;
        self.cached_hash = 0;
    }

    def attach(child: Expression) {
        self +>:ChildOf:+> child;
        self.cached_hash = 0;
    }

    def detach(child: Expression) {
        self del ->:ChildOf:-> child;
        self.cached_hash = 0;
    }

    # Fresh recompute without touching the cache (debug tripwire helper).
    def fresh_hash() -> int {
        child_sum = 0;
        for c in self ->:ChildOf:-> {
            child_sum += c.fresh_hash();
        }
        return (len(self.label) * 31 + child_sum) % 1000003;
    }
}

edge ChildOf { }

walker HashAuditor {
    has checked: int = 0;

    can start with Root entry {
        visit [->:ChildOf:->];
    }

    # Debug tripwire, folded into the audit: a cached (nonzero) hash must
    # equal a fresh recompute; an empty cache must be lazily fillable.
    can audit with Expression entry {
        fresh = here.fresh_hash();
        if here.cached_hash != 0 and here.cached_hash != fresh {
            print(f"[STALE] {here.label}: cached {here.cached_hash} != fresh {fresh}");
            disengage;
        }
        print(f"[OK] {here.label} hash={here.hash_value()}");
        self.checked += 1;
        visit [->:ChildOf:->];
    }
}

with entry {
    # Build a + (b * c) style tree.
    mul = Expression(label="mul");
    a = Expression(label="a");
    b = Expression(label="b");
    c = Expression(label="c");
    mul.attach(a);
    mul.attach(b);
    mul.attach(c);

    # Warm the caches.
    a.hash_value();
    b.hash_value();
    c.hash_value();
    mul.hash_value();

    # Mutate a copy-shaped node through a mutator: cache self-invalidates.
    mul.set_label("MUL");
    mul.detach(b);

    root ++> mul;
    root spawn HashAuditor();
}

