"""Category hierarchy: recursive tree build over typed child edges with cycle guard."""

node Category {
    has name: str = "";
    has sort_order: int = 0;
    has deleted: bool = False;

    def sort_key() -> int {
        return self.sort_order;
    }
}

edge ChildOf { }

walker TreeBuilder {
    has visited: dict = {};
    has depth: int = 0;
    has max_depth: int = 50;

    can start with Root entry {
        visit [->:ChildOf:->];
    }

    can build with Category entry {
        if here.deleted {
            return;
        }
        if self.depth > self.max_depth {
            print(f"[ERROR] depth limit {self.max_depth} exceeded at {here.name}");
            disengage;
        }
        if here in self.visited {
            print(f"[CYCLE] already visited {here.name}, skipping");
            return;
        }
        self.visited[here] = self.depth;
        pad = "-" * (self.depth + 1);
        print(f"{pad}{here.name} (sort {here.sort_order})");
        kids = [k for k in [here -->:ChildOf:-->] if not k.deleted];
        kids.sort(key=Category.sort_key, reverse=False);
        self.depth += 1;
        visit kids;
    }
}

