"""Cycle-safe lexical environment arena: trace from roots, mark reachable
environments/closures, then sweep out unreachable cyclic subgraphs —
the runtime fix proposed in issue #183."""

node Environment {
    has scope_name: str = "";
    has generation: int = 0;
    has reachable: bool = False;

    def describe() -> str {
        return self.scope_name;
    }
}

node Closure {
    has fn_name: str = "";
    has reachable: bool = False;
}

# Strong ownership: a closure owns its defining environment.
edge DefinesEnvironment { }
# Strong ownership: an environment owns its parent environment.
edge OwnsParent { }
# A function-local array/map stores closures created in a loop body.
edge Stores { }

edge ArenaMember { }

"""Traces the ownership graph from live roots, following closure-owned
environments and parent chains; guards against cycles with an explicit
visited set because visit has no built-in dedupe."""
walker Tracer {
    has visited: dict = {};

    def seen(n: object) -> bool {
        return n in self.visited;
    }

    def mark(n: object) {
        self.visited[n] = True;
    }

    can start with Root entry {
        visit [->:ArenaMember:->];
    }

    can trace_env with Environment entry {
        if self.seen(here) {
            return;
        }
        self.mark(here);
        here.reachable = True;
        print(f"root-reachable env: {here.describe()} (gen {here.generation})");
        visit [->:OwnsParent:->] | [->:Stores:->];
    }

    can trace_closure with Closure entry {
        if self.seen(here) {
            return;
        }
        self.mark(here);
        here.reachable = True;
        print(f"root-reachable closure: {here.fn_name}");
        visit [->:DefinesEnvironment:->];
    }
}

"""Sweeps the arena: any arena member left unmarked is unreachable —
including cyclic subgraphs — and is collected (deleted nodes have their
edges purged automatically)."""
walker Sweeper {
    has collected: int = 0;

    can start with Root entry {
        visit [->:ArenaMember:->];
    }

    can sweep_env with Environment entry {
        if here.reachable {
            here.reachable = False;
            visit [-->];
        } else {
            print(f"collected unreachable env: {here.describe()}");
            self.collected += 1;
            del here;
        }
    }

    can sweep_closure with Closure entry {
        if here.reachable {
            here.reachable = False;
        } else {
            print(f"collected unreachable closure: {here.fn_name}");
            self.collected += 1;
            del here;
        }
    }
}

with entry {
    # Live function scope (a root): owns a local array storing a loop closure.
    fn_env = Environment(scope_name="vibePinger", generation=1);
    loop_env = Environment(scope_name="batch_loop", generation=2);
    closure = Closure(fn_name="dns_probe");
    root +>:ArenaMember:+> fn_env;
    fn_env +>:Stores:+> closure;
    closure +>:DefinesEnvironment:+> loop_env;
    loop_env +>:OwnsParent:+> fn_env;

    # A retired subgraph: the function returned, so nothing reachable
    # holds it — but its internal cycle keeps every Rc non-zero.
    dead_fn = Environment(scope_name="retired_fn", generation=0);
    dead_loop = Environment(scope_name="retired_loop", generation=0);
    dead_closure = Closure(fn_name="orphan");
    root +>:ArenaMember:+> dead_fn;
    dead_fn +>:Stores:+> dead_closure;
    dead_closure +>:DefinesEnvironment:+> dead_loop;
    dead_loop +>:OwnsParent:+> dead_fn;

    root spawn Tracer();
    root spawn Sweeper();
}

"""Lazy hash cache with mutator self-invalidation: nodes cache hash on request;
mutators reset the cache so it is either empty or valid, never stale."""

node Expression {
    has label: str = "";
    has cached_hash: int = 0;

    # Lazy compute-on-request (0 sentinel = empty cache).
    def hash_value() -> int {
        if self.cached_hash == 0 {
            child_sum = 0;
            for c in [self ->:ChildOf:->] {
                child_sum += c.hash_value();
            }
            self.cached_hash = (len(self.label) * 31 + child_sum) % 1000003;
        }
        return self.cached_hash;
    }

    # Mutators self-invalidate: cache is either empty or valid, never stale.
    def set_label(new_label: str) {
        self.label = new_label;
        self.cached_hash = 0;
    }

    def attach(child: Expression) {
        self +>:ChildOf:+> child;
        self.cached_hash = 0;
    }

    def detach(child: Expression) {
        self del ->:ChildOf:-> child;
        self.cached_hash = 0;
    }

    # Fresh recompute without touching the cache (debug tripwire helper).
    def fresh_hash() -> int {
        child_sum = 0;
        for c in [self ->:ChildOf:->] {
            child_sum += c.fresh_hash();
        }
        return (len(self.label) * 31 + child_sum) % 1000003;
    }
}

edge ChildOf { }

walker HashAuditor {
    has checked: int = 0;

    can start with Root entry {
        visit [->:ChildOf:->];
    }

    # Debug tripwire, folded into the audit: a cached (nonzero) hash must
    # equal a fresh recompute; an empty cache must be lazily fillable.
    can audit with Expression entry {
        fresh = here.fresh_hash();
        if here.cached_hash != 0 and here.cached_hash != fresh {
            print(f"[STALE] {here.label}: cached {here.cached_hash} != fresh {fresh}");
            disengage;
        }
        print(f"[OK] {here.label} hash={here.hash_value()}");
        self.checked += 1;
        visit [->:ChildOf:->];
    }
}

with entry {
    # Build a + (b * c) style tree.
    mul = Expression(label="mul");
    a = Expression(label="a");
    b = Expression(label="b");
    c = Expression(label="c");
    mul.attach(a);
    mul.attach(b);
    mul.attach(c);

    # Warm the caches.
    a.hash_value();
    b.hash_value();
    c.hash_value();
    mul.hash_value();

    # Mutate a copy-shaped node through a mutator: cache self-invalidates.
    mul.set_label("MUL");
    mul.detach(b);

    root ++> mul;
    root spawn HashAuditor();
}

