"""Rosetta DocID registry: ROCK-* docs with dependency edges, validated by a walker that checks duplicate DocIDs, broken dependency targets, and canonical filename/URI consistency."""

node Doc {
    has doc_id: str = "";
    has title: str = "";
    has path: str = "";
    has normative: bool = True;
    has ledger_source: str = "doc-ledger.json";

    def canonical_name() -> str {
        parts = self.doc_id.lower().split("-");
        expected = "";
        for p in parts {
            expected = expected + p;
        }
        return expected + ".md";
    }

    def uri_ok() -> bool {
        return ("docs/" in self.path) and (self.path.endswith(self.canonical_name()));
    }
}

edge DependsOn { }

edge OwnedBy { }

walker RegistryAuditor {
    has seen: dict = {};
    has broken_deps: list = [];
    has duplicates: list = [];
    has bad_meta: list = [];

    can start with Root entry {
        visit [->:OwnedBy:->];
    }

    can audit with Doc entry {
        if here.doc_id in self.seen {
            self.duplicates.append(here.doc_id);
        } else {
            self.seen[here.doc_id] = here;
        }
        if not here.uri_ok() {
            self.bad_meta.append(f"{here.doc_id}: {here.path} (expected {here.canonical_name()})");
        }
        if (not here.normative) and (here.doc_id.endswith("3001")) {
            self.bad_meta.append(f"{here.doc_id}: ROCK-3001 must be normative");
        }
        visit [->:DependsOn:->];
    }

    can verify_deps with Doc exit {
        for target in [here -->:DependsOn:-->] {
            tid = target.doc_id;
            if tid not in self.seen {
                self.broken_deps.append(f"{here.doc_id} -> {tid}");
            }
        }
    }

    can report with Root exit {
        status = "VALID" if (not self.duplicates and not self.broken_deps and not self.bad_meta) else "INVALID";
        print(f"registry audit: {status}, {len(self.seen)} docs registered");
        for d in self.duplicates { print(f"  duplicate doc_id: {d}"); }
        for b in self.broken_deps { print(f"  broken dependency: {b}"); }
        for m in self.bad_meta { print(f"  metadata violation: {m}"); }
    }
}

with entry {
    rock3001 = Doc(doc_id="ROCK-3001", title="Rosetta Doc Governance", path="docs/ROCK-3001.md", normative=True);
    rock3010 = Doc(doc_id="ROCK-3010", title="Pack Schema", path="docs/ROCK-3010.md", normative=True);
    rock3111 = Doc(doc_id="ROCK-3111", title="RRP Pack Filesystem Contract", path="docs/ROCK-3111-C-RRP-Pack-Filesystem-Contract.md", normative=False);

