    root spawn RegistryAuditor();
}

"""Recursive media folder import: walk a dropped directory tree and recreate
the nested folder hierarchy in the media workspace, uploading each file into
its corresponding folder (issue #12)."""

edge Contains { has rel_path: str = ""; }
edge Child { has name: str = ""; }
edge ImportedInto { }

node MediaFolder {
    has name: str = "";
    has path: str = "";

    def child_folder(child_name: str) -> MediaFolder | None {
        for k in [here->:Contains:->] {
            if k.name == child_name {
                return k;
            }
        }
        return None;
    }
}

node MediaFile {
    has name: str = "";
    has size_bytes: int = 0;
}

node DirEntry {
    has name: str = "";
    has is_file: bool = False;
    has size_bytes: int = 0;
}

walker FolderImporter {
    has dest: MediaFolder | None = None;
    has visited: list[str] = [];
    has files_found: int = 0;
    has folders_created: int = 0;
    has total_bytes: int = 0;
    has summary: list[str] = [];

    can start with Root entry {
        # Preflight destination: default to the workspace root folder.
        dest_folder = self.dest;
        if dest_folder is None {
            dest_folder = MediaFolder(name="All files", path="");
            root +>:ImportedInto:+> dest_folder;
            self.dest = dest_folder;
        }
        visit [->:Child:->];
    }

    can import_entry with DirEntry entry {
        # Narrow the optional destination before touching its fields.
        dest_folder = self.dest;
        if dest_folder is None {
            disengage;
        }

        # Cycle policy: explicit visited guard — walkers do not dedupe.
        key = dest_folder.path + "/" + here.name;
        if key in self.visited {
            disengage;
        }
        self.visited.append(key);

        if here.is_file {
            # Upload the file straight into the destination folder.
            f = MediaFile(name=here.name, size_bytes=here.size_bytes);
            dest_folder +>:Contains(rel_path=here.name):+> f;
            self.files_found += 1;
            self.total_bytes += here.size_bytes;
            self.summary.append(f"file {here.name} -> {dest_folder.path}");
        } else {
            # Create or reuse the nested media folder, then descend.
            nxt = dest_folder.child_folder(here.name);
            created = "reused";
            if nxt is None {
                parent_path = dest_folder.path;
                if parent_path == "" {
                    nxt = MediaFolder(name=here.name, path=here.name);
                } else {
                    nxt = MediaFolder(name=here.name, path=parent_path + "/" + here.name);
                }
                dest_folder +>:Contains(rel_path=here.name):+> nxt;
                created = "created";
                self.folders_created += 1;
            }

            # Recurse into this folder, carrying and then pulling back state.
            sub = FolderImporter(
                dest=nxt,
                visited=self.visited,
                files_found=self.files_found,
                folders_created=self.folders_created,
                total_bytes=self.total_bytes,
                summary=self.summary
            );
            here spawn sub;
            self.files_found = sub.files_found;
            self.folders_created = sub.folders_created;
            self.total_bytes = sub.total_bytes;
            self.summary = sub.summary;
            self.summary.append(f"{created} folder {nxt.path}");
        }
        visit [->:Child:->] else { disengage; }
    }
}

with entry {
    # A dropped directory tree: Campaign assets/{Logos, Photography}.
    campaign = DirEntry(name="Campaign assets");
    logos = DirEntry(name="Logos");
    photo = DirEntry(name="Photography");
    campaign +>:Child:+> logos;
    campaign +>:Child:+> photo;
    logos +>:Child:+> DirEntry(name="primary.svg", is_file=True, size_bytes=2048);
    logos +>:Child:+> DirEntry(name="reversed.svg", is_file=True, size_bytes=1980);
    photo +>:Child:+> DirEntry(name="hero.jpg", is_file=True, size_bytes=940320);

    brand = MediaFolder(name="Brand", path="Brand");
    root +>:ImportedInto:+> brand;

    root +>:Child:+> campaign;

    imp = FolderImporter(dest=brand);
    root spawn imp;

    print(f"Import into '{brand.name}': {imp.folders_created} folders created, "
          f"{imp.files_found} files, {imp.total_bytes} bytes");
    for line in imp.summary {
        print(f"  - {line}");
    }
}

"""DVT VTX2 demo: relation cards bound to a pinned Substrait plan profile.

Walkers traverse the card pipeline via typed edges, verify the stable
identity sidecar (RelationId/FieldId survive rename/reorder), and fail
closed on unsupported cardinality-changing operators like UNNEST.
"""

node RelationCard {
    has name: str = "";
    has substrait_op: str = "";
    has supported: bool = True;
    has relation_id: str = "";
}

node Field {
    has field_id: str = "";
    has substrait_ref: int = 0;
    has label: str = "";
}

edge FlowsTo { }
edge BindsTo { has direction: str = ""; }
edge Produces { }

walker PlanAuditor {
    has visited: list[str] = [];
    has card_count: int = 0;
    has unsupported: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can audit with RelationCard entry {
        # Cycle policy: skip already-audited cards explicitly.
        if here.relation_id in self.visited {
            disengage;
        }
        self.visited.append(here.relation_id);
        self.card_count += 1;
        if not here.supported {
            self.unsupported.append(f"{here.name}:{here.substrait_op}");
            print(f"FAIL-CLOSED: {here.relation_id} uses unsupported op {here.substrait_op}");
            disengage;
        }
        print(f"card {here.relation_id} = {here.substrait_op} ({here.name})");
        visit [->:FlowsTo:->] else { disengage; }
    }

    can check_fields with Field entry {
        status = "renamed" if here.label != here.field_id else "original";
        print(f"field {here.field_id} -> substrait ref {here.substrait_ref} ({status})");
        visit [-->] else { disengage; }
    }
}

walker IdentityProbe {
    can start with Root entry {
        visit [->:BindsTo:->] else { disengage; }
    }

    can probe with Field entry {
        print(f"binding: {here.field_id} stable across substrait ref {here.substrait_ref}");
        visit [-->] else { disengage; }
    }

    can probe_card with RelationCard entry {
        print(f"card identity {here.relation_id} bound to pinned substrait op {here.substrait_op}");
    }
}

with entry {
    # Pipeline: Read -> Project -> Filter -> Aggregate (Substrait bounded core)
    read_c = RelationCard(name="orders_source", substrait_op="Read", relation_id="rel-1");
    proj_c = RelationCard(name="pick_columns", substrait_op="Project", relation_id="rel-2");
    filt_c = RelationCard(name="big_orders", substrait_op="Filter", relation_id="rel-3");
    agg_c = RelationCard(name="by_customer", substrait_op="Aggregate", relation_id="rel-4");
    bad_c = RelationCard(name="flatten_tags", substrait_op="UNNEST", relation_id="rel-5", supported=False);

    root ++> read_c;
    read_c +>:FlowsTo:+> proj_c;
    proj_c +>:FlowsTo:+> filt_c;
    filt_c +>:FlowsTo:+> agg_c;
    agg_c +>:FlowsTo:+> bad_c;

    # Fields with stable DVT FieldIds bound to positional Substrait refs,
    # with renamed labels that must not break identity.
    f1 = Field(field_id="fld-order-id", substrait_ref=0, label="order_id");
    f2 = Field(field_id="fld-cust-id", substrait_ref=1, label="customer");
    f3 = Field(field_id="fld-amount", substrait_ref=2, label="total_amount");
    agg_c +>:Produces:+> f1;
    agg_c +>:Produces:+> f2;
    agg_c +>:Produces:+> f3;

    read_c +>:BindsTo(direction="card->substrait"):+> f2;
    proj_c +>:BindsTo(direction="card->substrait"):+> f3;

    auditor = PlanAuditor();
    root spawn auditor;
    root spawn IdentityProbe();

    # Invariant: Substrait operator count != canvas card count != runtime steps.
    print(f"audited {auditor.card_count} cards; unsupported: {auditor.unsupported}");
}

