"""Dependency gates on a dev board: cards, prerequisite edges, and a gate walker.

Dependency edges carry a condition; the GateCheck walker evaluates each
card's gates with AND semantics, rejects self-edges and cycles (fail closed
as ``invalid``), and treats unknown prerequisites as unsatisfied.
"""

enum Condition { card_done, card_ready, merged_to_base, spec_materialized, hil_approved }

node Card {
    has title: str = "";
    has done: bool = False;
    has ready: bool = False;
    has archived: bool = False;
    has spec_ok: bool = False;
    has evidence: str = "";
    has gate_status: str = "unknown";
    has gate_reason: str = "";
    has blocked_by: list[str] = [];

    def satisfies(cond: Condition) -> bool {
        if cond == Condition.card_done { return self.done; }
        if cond == Condition.card_ready { return self.ready and self.spec_ok; }
        if cond == Condition.merged_to_base { return self.evidence != "" and self.done; }
        if cond == Condition.spec_materialized { return self.spec_ok; }
        if cond == Condition.hil_approved { return self.evidence == "hil:human-signed"; }
        return False;
    }
}

edge DependsOn {
    has condition: Condition = Condition.card_done;
}

node Board {
    has name: str = "";
}

walker GateCheck {
    has depth_cap: int = 32;

    can start with Root entry {
        visit [-->];
    }

    can inspect_board with Board entry {
        visit [-->];
    }

    can inspect with Card entry {
        """Evaluate all active dependency gates with AND semantics, fail closed."""
        self.gate(here, 0, []);
        visit [-->];
    }

    def gate(card: Card, depth: int, seen: list[Card]) -> None {
        if card.archived {
            card.gate_status = "invalid";
            card.gate_reason = "archived card";
            return;
        }
        if depth > self.depth_cap {
            card.gate_status = "invalid";
            card.gate_reason = "depth cap exceeded";
            return;
        }
        if card in seen {
            card.gate_status = "invalid";
            card.gate_reason = "dependency cycle";
            return;
        }
        status = "eligible";
        reason = "all gates satisfied";
        blockers: list[str] = [];
        for edge in [card ->:DependsOn:->] {
            targets = [edge ->];
            if not targets or len(targets) != 1 {
                card.gate_status = "invalid";
                card.gate_reason = "malformed dependency edge";
                return;
            }
            dep = targets[0];
            if dep is card {
                card.gate_status = "invalid";
                card.gate_reason = "self-dependency";
                return;
            }
            self.gate(dep, depth + 1, seen + [card]);
            if dep.gate_status != "eligible" {
                status = dep.gate_status if dep.gate_status in ("invalid", "unknown") else "blocked";
                reason = dep.gate_reason;
                blockers.append(dep.title);
            } else if not dep.satisfies(edge.condition) {
                status = "blocked";
                reason = f"prerequisite not satisfied: {edge.condition}";
                blockers.append(dep.title);
            }
        }
        card.gate_status = status;
        card.gate_reason = reason;
        card.blocked_by = blockers;
    }

    can dispatch with Card exit {
        verdict = "DISPATCH" if here.gate_status == "eligible" else f"HOLD ({here.gate_status})";
        print(f"{here.title}: {verdict} reason={here.gate_reason} blockedBy={here.blocked_by}");
    }
}

walker ClaimCard {
    has target: str = "";

    can start with Root entry {
        visit [-->];
    }

    can scan_board with Board entry {
        visit [-->];
    }

    can try_claim with Card entry {
        if here.title == self.target {
            # Re-evaluate immediately before the claim mutation.
            GateCheck().gate(here, 0, []);
            if here.gate_status == "eligible" {
                here.done = True;
                print(f"CLAIMED {here.title}");
            } else {
                print(f"CLAIM REJECTED {here.title}: {here.gate_status} ({here.gate_reason})");
            }
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    b = Board(name="Dev Board");
    root ++> b;

    spec = Card(title="Spec", done=True, ready=True, spec_ok=True);
    infra = Card(title="Infra", done=True, evidence="pr:123");
    hil = Card(title="HIL", evidence="hil:human-signed");
    feature = Card(title="Feature");
    b ++> spec ++> infra ++> hil;

    # Feature gates on all three (AND semantics).
    feature +>:DependsOn(condition=Condition.card_ready):+> spec;
    feature +>:DependsOn(condition=Condition.merged_to_base):+> infra;
    feature +>:DependsOn(condition=Condition.hil_approved):+> hil;
    b ++> feature;

    bad = Card(title="Cyclic");
    other = Card(title="Other");
    bad +>:DependsOn:+> other;
    other +>:DependsOn:+> bad;  # cycle -> fail closed
    b ++> bad ++> other;

    root spawn GateCheck();
    root spawn ClaimCard(target="Feature");
}

"""Topological sort over a DAG of tasks: DFS-based and Kahn's (BFS-based) walkers.

Dependencies are typed ``Prereq`` edges (u +>:Prereq:+> v means u must come
before v).  Both walkers carry explicit cycle guards since jac walkers have no
built-in once-per-node visitation; on a cycle they report an error like the
visualizer's "Cycle detected" step.
"""

node Task {
    has name: str = "";
    has indegree: int = 0;
    has finished: bool = False;
    has visited: bool = False;
    has on_stack: bool = False;
}

edge Prereq { }

walker TopoSortDfs {
    has ordering: list[str] = list();
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can dfs with Task entry {
        if self.cycle_found { disengage; }
        if here.finished { disengage; }
        if here.on_stack {
            self.cycle_found = True;
            print("Cycle detected — topological sort is not possible");
            disengage;
        }
        here.on_stack = True;
        print(f"DFS from node {here.name}" if not self.ordering and not here.visited else f"Visiting {here.name} (neighbor)");
        here.visited = True;
        visit [->:Prereq:->];
        here.on_stack = False;
        here.finished = True;
        self.ordering.insert(0, here.name);
        print(f"{here.name} finished, adding to front of ordering: {self.ordering}");
    }

    can report_order with Task exit {
        if here.name == self.ordering[-1] and not self.cycle_found {
            print(f"Topological order (DFS): {self.ordering}");
        }
    }
}

walker TopoSortKahn {
    has frontier: list[str] = list();
    has result: list[str] = list();
    has processed: int = 0;
    has total: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can count with Task entry {
        self.total += 1;
        for n in [here->:Prereq:->] {
            n.indegree += 1;
        }
        visit [-->] else {
            for t in [root -->] {
                if t.indegree == 0 {
                    self.frontier.append(t.name);
                }
            }
            print(f"Initial zero in-degree nodes: {self.frontier}");
            while self.frontier.length() > 0 {
                current_name = self.frontier.pop(0);
                self.result.append(current_name);
                self.processed += 1;
                reduced = list();
                for t in [root -->] {
                    if t.name == current_name {
                        for n in [t->:Prereq:->] {
                            n.indegree -= 1;
                            reduced.append(f"{n.name}({n.indegree + 1}->{n.indegree})");
                            if n.indegree == 0 {
                                self.frontier.append(n.name);
                                print(f"{n.name} now has in-degree 0, adding to queue");
                            }
                        }
                    }
                }
                if reduced.length() > 0 {
                    print(f"Processing {current_name}, reducing in-degree of {', '.join(reduced)}");
                }
            }
            if self.processed < self.total {
                print("Cycle detected — topological sort is not possible");
            } else {
                print(f"Topological order (Kahn): {self.result}");
            }
            disengage;
        }
    }
}

with entry {
    # simple-dag preset: layered left-to-right dependency DAG
    a = Task(name="A");
    b = Task(name="B");
    c = Task(name="C");
    d = Task(name="D");
    e = Task(name="E");
    root ++> a;
    a +>:Prereq:+> b;
    a +>:Prereq:+> c;
    b +>:Prereq:+> d;
    c +>:Prereq:+> d;
    d +>:Prereq:+> e;

    root spawn TopoSortDfs();
    root spawn TopoSortKahn();

    # introduce a cycle: E -> A makes topological sort impossible
    e +>:Prereq:+> a;
    print("--- rerun on cyclic graph ---");
    root spawn TopoSortDfs();
    root spawn TopoSortKahn();
}

