"""Braze dunning endpoints: materialized cache serving with lineage-contention detection.

Two materialized endpoints sharing one source view contend for the refresh
job; affected endpoints are forced onto the inline path (timeout), and they
recover once the contender is removed.
"""

node SourceView {
    has name: str = "";
}

node Endpoint {
    has name: str = "";
    has source_name: str = "";
    has version: int = 0;
    has is_materialized: bool = True;
    has cache_rows: int = 0;
    has cache_current: bool = True;
    has retry_count: int = 0;
    has last_error: str = "";
}

edge Materializes {
    has table: str = "";
}

walker MaterializationScheduler {
    # Per-source-view load: jac walkers have no built-in visitation
    # dedupe, so we track what we have seen explicitly.
    has seen: dict = {};
    has view_load: dict = {};
    has pass: str = "count";

    can start with Root entry {
        visit [->:Materializes:->] else { disengage; }
    }

    can audit with Endpoint entry {
        if self.seen.get(here.name) {
            disengage;
        }
        self.seen[here.name] = True;

        if self.pass == "count" {
            prior = self.view_load.get(here.source_name, 0);
            self.view_load[here.source_name] = prior + 1;
            visit [->:Materializes:->] else { disengage; }
        } else {
            load = self.view_load.get(here.source_name, 0);
            if here.is_materialized and load > 1 {
                here.retry_count += 1;
                here.last_error = "ClickHouseQueryTimeOut";
                print(f"[contention] {here.name}: {load} jobs on "
                      f"{here.source_name} -> forced to path=inline "
                      f"(retry={here.retry_count})");
            } else {
                here.last_error = "";
                here.retry_count = 0;
                cache_state = "hit" if here.cache_rows > 0 else "miss";
                print(f"[serve] {here.name}: path=materialized "
                      f"cache={cache_state} ({here.cache_rows} rows)");
            }
        }
    }
}

walker SchedulePass {
    can start with Root entry {
        s = MaterializationScheduler(pass="count");
        root spawn s;
        s2 = MaterializationScheduler(pass="serve",
                                      view_load=s.view_load);
        root spawn s2;
        disengage;
    }
}

with entry {
    view = SourceView(name="braze_dunning_attributes_source");
    healthy = Endpoint(name="braze-dunning-attributes-wip", source_name=view.name,
                       version=3, cache_rows=8429, cache_current=True);
    root ++> view;
    view +>:Materializes(table="wip_braze_dunning_v3"):+> healthy;
    root spawn SchedulePass();

    print("--- second materialization job added on the same view ---");
    broken = Endpoint(name="braze-dunning-attributes", source_name=view.name,
                      version=2, cache_rows=8429, cache_current=True);
    view +>:Materializes(table="__wip_braze_dunning_v2"):+> broken;
    root spawn SchedulePass();

    print("--- contender endpoint deleted ---");
    del broken;
    root spawn SchedulePass();
}

"""Dependency gates on a dev board: cards, prerequisite edges, and a gate walker.

Dependency edges carry a condition; the GateCheck walker evaluates each
card's gates with AND semantics, rejects self-edges and cycles (fail closed
as ``invalid``), and treats unknown prerequisites as unsatisfied.
"""

enum Condition { card_done, card_ready, merged_to_base, spec_materialized, hil_approved }

node Card {
    has title: str = "";
    has done: bool = False;
    has ready: bool = False;
    has archived: bool = False;
    has spec_ok: bool = False;
    has evidence: str = "";
    has gate_status: str = "unknown";
    has gate_reason: str = "";
    has blocked_by: list[str] = [];

    def satisfies(cond: Condition) -> bool {
        if cond == Condition.card_done { return self.done; }
        if cond == Condition.card_ready { return self.ready and self.spec_ok; }
        if cond == Condition.merged_to_base { return self.evidence != "" and self.done; }
        if cond == Condition.spec_materialized { return self.spec_ok; }
        if cond == Condition.hil_approved { return self.evidence == "hil:human-signed"; }
        return False;
    }
}

edge DependsOn {
    has condition: Condition = Condition.card_done;
}

node Board {
    has name: str = "";
}

walker GateCheck {
    has depth_cap: int = 32;

    can start with Root entry {
        visit [-->];
    }

    can inspect_board with Board entry {
        visit [-->];
    }

    can inspect with Card entry {
        """Evaluate all active dependency gates with AND semantics, fail closed."""
        self.gate(here, 0, []);
        visit [-->];
    }

    def gate(card: Card, depth: int, seen: list[Card]) {
        if card.archived {
            card.gate_status = "invalid";
            card.gate_reason = "archived card";
            return;
        }
        if depth > self.depth_cap {
            card.gate_status = "invalid";
            card.gate_reason = "depth cap exceeded";
            return;
        }
        if card in seen {
            card.gate_status = "invalid";
            card.gate_reason = "dependency cycle";
            return;
        }
        status = "eligible";
        reason = "all gates satisfied";
        blockers: list[str] = [];
        deps = [card ->:DependsOn:->];
        for edge in deps {
            targets = [edge ->];
            if len(targets) != 1 {
                card.gate_status = "invalid";
                card.gate_reason = "malformed dependency edge";
                return;
            }
            dep = targets[0];
            if dep is card {
                card.gate_status = "invalid";
                card.gate_reason = "self-dependency";
                return;
            }
            self.gate(dep, depth + 1, seen + [card]);
            if dep.gate_status == "invalid" or dep.gate_status == "unknown" {
                status = dep.gate_status;
                reason = dep.gate_reason;
                blockers.append(dep.title);
            } else if dep.gate_status != "eligible" or not dep.satisfies(edge.condition) {
                status = "blocked";
                reason = f"prerequisite not satisfied: {edge.condition}";
                blockers.append(dep.title);
            }
        }
        card.gate_status = status;
        card.gate_reason = reason;
        card.blocked_by = blockers;
    }

    can dispatch with Card exit {
        verdict = "DISPATCH" if here.gate_status == "eligible" else f"HOLD ({here.gate_status})";
        print(f"{here.title}: {verdict} reason={here.gate_reason} blockedBy={here.blocked_by}");
    }
}

walker ClaimCard {
    has target: str = "";

    can start with Root entry {
        visit [-->];
    }

    can scan_board with Board entry {
        visit [-->];
    }

    can try_claim with Card entry {
        if here.title == self.target {
            # Re-evaluate immediately before the claim mutation.
            checker = GateCheck();
            checker.gate(here, 0, []);
            if here.gate_status == "eligible" {
                here.done = True;
                print(f"CLAIMED {here.title}");
            } else {
                print(f"CLAIM REJECTED {here.title}: {here.gate_status} ({here.gate_reason})");
            }
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    b = Board(name="Dev Board");
    root ++> b;

    spec = Card(title="Spec", done=True, ready=True, spec_ok=True);
    infra = Card(title="Infra", done=True, evidence="pr:123");
    hil = Card(title="HIL", evidence="hil:human-signed");
    feature = Card(title="Feature");
    b ++> spec ++> infra ++> hil;

    # Feature gates on all three (AND semantics).
    feature +>:DependsOn(condition=Condition.card_ready):+> spec;
    feature +>:DependsOn(condition=Condition.merged_to_base):+> infra;
    feature +>:DependsOn(condition=Condition.hil_approved):+> hil;
    b ++> feature;

    bad = Card(title="Cyclic");
    other = Card(title="Other");
    bad +>:DependsOn:+> other;
    other +>:DependsOn:+> bad;  # cycle -> fail closed
    b ++> bad ++> other;

    root spawn GateCheck();
    root spawn ClaimCard(target="Feature");
}

"""Keyed recursive CTE demo: settled-set shortest path over a weighted cyclic graph.

Instead of append-only path enumeration, the walker keeps a settled map
(one best row per key) and propagates only the delta of changed rows,
terminating on cyclic graphs without path tracking.
"""

node Vertex {
    has name: str = "";
}

edge Weighted {
    has weight: float = 0.0;
}

edge Seeded { }

walker ShortestPath {
    has source: str = "";
    has settled: dict = {};
    has delta: dict = {};
    has iterations: int = 0;

    def relax(node: Vertex, cost: float) -> bool {
        best = self.settled.get(node.name);
        if best is None or cost < best {
            self.settled[node.name] = cost;
            self.delta[node.name] = cost;
            return True;
        }
        return False;
    }

    can start with Root entry {
        seed = here -->[?:Vertex];
        for v in seed {
            if v.name == self.source {
                self.relax(v, 0.0);
            }
        }
        self.converge();
        report self.settled;
    }

    def converge() {
        # Semi-naive evaluation: the working table is only the changed
        # rows (delta); a row identical to the settled row is a no-op
        # and is never propagated, so cycles terminate.
        while self.delta {
            self.iterations += 1;
            work = self.delta;
            self.delta = {};
            for key in work.keys() {
                cost = work[key];
                v = here;
                for target in v -->:Weighted:-> {
                    self.relax(target, cost + 1.0);
                }
            }
        }
    }

    can traverse with Vertex entry {
        # Hand control to the imperative fixpoint loop once, then stop.
        disengage;
    }
}

with entry {
    a = Vertex(name="a");
    b = Vertex(name="b");
    c = Vertex(name="c");
    d = Vertex(name="d");

    # Cyclic weighted graph: a -> b -> c -> a, plus a -> d -> c.
    a +>:Weighted(weight=4.0):+> b;
    b +>:Weighted(weight=1.0):+> c;
    c +>:Weighted(weight=2.0):+> a;
    a +>:Weighted(weight=7.0):+> d;
    d +>:Weighted(weight=1.0):+> c;

    root ++> a ++> b ++> c ++> d;

    finder = ShortestPath(source="a");
    root spawn finder;

    print(f"settled distances: {finder.settled}");
    print(f"converged in {finder.iterations} iterations despite cycle a->b->c->a");
}

