"""Connected components on a hub graph: correct visited-set traversal vs. a
depth-carrying traversal that re-enqueues a node once per reachable depth
(the SQLite CTE trap, re-derived natively)."""

node HubNode {
    has name: str = "";
    has depth: int = 0;
}

edge Link {
    has weight: int = 0;
