# Correct traversal: dedupe by node identity (UNION on the node column alone).
walker ComponentCounter {
    has seen: dict = {};
    has component_size: int = 0;

    can start with Root entry {
        visit [->:Link:->] else { disengage; }
    }

    can traverse with HubNode entry {
        if here.name in self.seen {
            # already enqueued via the node column alone: skip, keep walking
        } else {
            self.seen[here.name] = True;
            self.component_size += 1;
            visit [->:Link:->];
        }
    }
}

# Depth-carrying traversal: node key is (name, depth), so a hub node with
# many short paths re-enters once per distinct depth — the 975,800 bug.
walker DepthCarryingCounter {
    has seen: dict = {};
    has row_count: int = 0;

    can start with Root entry {
        visit [->:Link:->] else { disengage; }
    }

    can traverse with HubNode entry {
        key = f"{here.name}@{here.depth}";
        if key in self.seen {
            # duplicate (node, depth) row: drop it from the queue
        } else {
            self.seen[key] = True;
            self.row_count += 1;
            next_depth = here.depth + 1;
            for (n) in [here->:Link:->] {
                n.depth = next_depth;
            }
            visit [->:Link:->];
        }
    }
}

