"""Topological sort over a DAG of tasks: DFS-based and Kahn's (BFS-based) walkers.

Dependencies are typed ``Prereq`` edges (u +>:Prereq:+> v means u must come
before v).  Both walkers carry explicit cycle guards since jac walkers have no
built-in once-per-node visitation; on a cycle they report the visualizer's
"Cycle detected" error.
"""

node Task {
    has name: str = "";
    has indegree: int = 0;
    has finished: bool = False;
    has visited: bool = False;
    has on_stack: bool = False;
}

edge Prereq { }

walker ResetFlags {
    can start with Root entry {
        visit [-->];
    }

    can clear with Task entry {
        here.finished = False;
        here.visited = False;
        here.on_stack = False;
        here.indegree = 0;
        visit [-->];
    }
}

walker TopoSortDfs {
    has postorder: list[str] = list();
    has cycle_found: bool = False;
    has started: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can dfs with Task entry {
        if self.cycle_found { disengage; }
        if here.finished { return; }
        if here.on_stack {
            self.cycle_found = True;
            print("Cycle detected — topological sort is not possible");
            disengage;
        }
        if not self.started {
            self.started = True;
            print(f"DFS from node {here.name}");
        } else {
            print(f"Visiting {here.name} (neighbor)");
        }
        here.on_stack = True;
        here.visited = True;
        visit [->:Prereq:->];
        here.on_stack = False;
        here.finished = True;
        self.postorder.append(here.name);
        print(f"{here.name} finished, adding to ordering: {self.postorder}");
    }

    can finish with Root exit {
        if not self.cycle_found {
            ordering = self.postorder[::-1];
            print(f"Topological order (DFS): {ordering}");
        }
    }
}

walker TopoSortKahn {
    has nodes: list[Task] = list();
    has frontier: list[str] = list();
    has result: list[str] = list();

    can start with Root entry {
        visit [-->];
    }

    can collect with Task entry {
        self.nodes.append(here);
        for n in [here->:Prereq:->] {
            n.indegree += 1;
        }
        visit [-->] else {
            for t in self.nodes {
                if t.indegree == 0 {
                    self.frontier.append(t.name);
                }
            }
            print(f"Initial zero in-degree nodes: {self.frontier}");
            while len(self.frontier) > 0 {
                current = self.frontier.pop(0);
                self.result.append(current);
                reduced = list();
                source = None;
                for t in self.nodes {
                    if t.name == current {
                        source = t;
                    }
                }
                if source is not None {
                    for n in [source->:Prereq:->] {
                        old = n.indegree;
                        n.indegree -= 1;
                        reduced.append(f"{n.name} ({old}->{n.indegree})");
                        if n.indegree == 0 {
                            self.frontier.append(n.name);
                            print(f"{n.name} now has in-degree 0, adding to queue");
                        }
                    }
                }
                if len(reduced) > 0 {
                    print(f"Processing {current}, reducing in-degree of {', '.join(reduced)}");
                }
            }
            if len(self.result) < len(self.nodes) {
                print("Cycle detected — topological sort is not possible");
            } else {
                print(f"Topological order (Kahn): {self.result}");
            }
        }
    }
}

with entry {
    # simple-dag preset: layered left-to-right dependency DAG
    a = Task(name="A");
    b = Task(name="B");
    c = Task(name="C");
    d = Task(name="D");
    e = Task(name="E");
    root ++> a;
    a +>:Prereq:+> b;
    a +>:Prereq:+> c;
    b +>:Prereq:+> d;
    c +>:Prereq:+> d;
    d +>:Prereq:+> e;

    root spawn TopoSortDfs();
    root spawn TopoSortKahn();

    # introduce a cycle: E -> A makes topological sort impossible
    e +>:Prereq:+> a;
    print("--- rerun on cyclic graph ---");
    root spawn ResetFlags();
    root spawn TopoSortDfs();
    root spawn ResetFlags();
    root spawn TopoSortKahn();
}

