walker GetDescendants {
    has include_self: bool = False;
    has origin_id: int = 0;
    has seen: list[int] = [];
    has found: list[str] = [];

    def mark_seen(cid: int) -> bool {
        if cid in self.seen {
            return False;
        }
        self.seen.append(cid);
        return True;
    }

    can start with Root entry {
        visit [-->] else { disengage; }
