"""Connected components on a hub graph: a correct visited-set traversal
(UNION over the node column alone) versus a depth-carrying traversal that
re-enqueues a node once per distinct reachable depth — the SQLite CTE trap
re-derived natively in Jac."""

node HubNode {
    has name: str = "";
    has depth: int = 0;
}

edge Link {
    has weight: int = 0;
}

# Correct traversal: dedupe by node identity, exactly once per node.
walker ComponentCounter {
    has seen: dict = {};
    has component_size: int = 0;

    can start with Root entry {
        visit [->:Link:->] else { disengage; }
    }

    can traverse with HubNode entry {
        if here.name not in self.seen {
            self.seen[here.name] = True;
            self.component_size += 1;
            visit [->:Link:->];
        }
    }
}

# Depth-carrying traversal: the queue key is (name, depth), so the same
# node re-enters once per distinct depth at which it is reachable — the
# 975,800-rows bug. Depth cap mirrors the "obvious safety instinct".
walker DepthCarryingCounter {
    has seen: dict = {};
    has row_count: int = 0;
    has depth: int = 0;
    has ok: bool = False;
    has cap: int = 8;

    can start with Root entry {
        visit [->:Link:->] else { disengage; }
    }

    can traverse with HubNode entry {
        self.ok = False;
        if self.depth >= self.cap {
            return;
        }
        key = f"{here.name}@{self.depth}";
        if key in self.seen {
            # duplicate (node, depth) row: dropped from the queue, but it
            # still cost a queue slot — this is the inflation being shown
            return;
        }
        self.seen[key] = True;
        self.row_count += 1;
        self.ok = True;
        self.depth += 1;
        visit [->:Link:->] else {
            self.depth -= 1;
        }
    }

    can traverse with HubNode exit {
        if self.ok {
            self.ok = False;
            self.depth -= 1;
        }
    }
}

with entry {
    # Hub graph: one hub node with many spokes, cross-linked in ring
    # fashion and one back edge to the hub, so many distinct-depth paths
    # reach the same nodes.
    hub = HubNode(name="hub");
    root ++> hub;
    spokes = [];
    for (i) in range(6) {
        s = HubNode(name=f"s{i}");
        hub +>:Link:+> s;
        spokes.append(s);
    }
    for (i) in range(6) {
        t = HubNode(name=f"t{i}");
        spokes[i] +>:Link:+> t;
        spokes[i] +>:Link:+> spokes[(i + 1) % 6];
        t +>:Link:+> hub;
    }

    counter = ComponentCounter();
    root spawn counter;
    print(f"correct component size: {counter.component_size}");

    depth_counter = DepthCarryingCounter();
    root spawn depth_counter;
    print(f"depth-carrying row count (inflated): {depth_counter.row_count}");
}

