node PullRequest {
    has number: int = 0;
    has head: str = "";
    has is_draft: bool = True;
    has approvals: int = 0;
    has review_state: str = "";

    def merge_ready() -> bool {
        return not self.is_draft and self.approvals >= 2 and self.review_state == "APPROVED";
    }
}

