            print(f"RULESET DEFECT: {here.name} approvals={here.required_approvals} "
                  f"last_push={here.require_last_push_approval} bypass={here.bypass_mode}");
        } else {
            print(f"ruleset {here.name} compliant");
        }
        visit [->:ProtectedBy:->];
    }

    can audit_pr with PullRequest entry {
        if not here.merge_ready() {
