"""Dependency gates on a dev board: cards, prerequisite edges, and a gate walker.

Dependency edges carry a condition; the GateCheck walker evaluates each
card's gates with AND semantics, rejects self-edges and cycles (fail closed
as ``invalid``), and treats unknown prerequisites as unsatisfied.
"""

node Card {
    has title: str = "";
    has done: bool = False;
    has ready: bool = False;
    has archived: bool = False;
    has spec_ok: bool = False;
    has evidence: str = "";
    has gate_status: str = "unknown";
    has gate_reason: str = "";
    has blocked_by: list[str] = [];

    def satisfies(cond: str) -> bool {
        if cond == "card_done" { return self.done; }
        if cond == "card_ready" { return self.ready and self.spec_ok; }
        if cond == "merged_to_base" { return self.evidence != "" and self.done; }
        if cond == "spec_materialized" { return self.spec_ok; }
        if cond == "hil_approved" { return self.evidence == "hil:human-signed"; }
        return False;
    }
}

edge DependsOn {
    has condition: str = "card_done";
}

node Board {
    has name: str = "";
}

walker GateCheck {
    has depth_cap: int = 32;

    can start with Root entry {
        visit [-->];
    }

    can inspect_board with Board entry {
        visit [-->];
    }

    can inspect with Card entry {
        """Evaluate all active dependency gates with AND semantics, fail closed."""
        self.gate(here, 0, []);
        visit [-->];
    }

    def gate(card: Card, depth: int, seen: list[Card]) {
        if card.archived {
            card.gate_status = "invalid";
            card.gate_reason = "archived card";
            return;
        }
        if depth > self.depth_cap {
            card.gate_status = "invalid";
            card.gate_reason = "depth cap exceeded";
            return;
        }
        if card in seen {
            card.gate_status = "invalid";
            card.gate_reason = "dependency cycle";
            return;
        }
        status = "eligible";
        reason = "all gates satisfied";
        blockers: list[str] = [];
        all_edges = card -->;
        dep_edges = [e for e in all_edges if isinstance(e, DependsOn)];
        for e in dep_edges {
            targets = [e ->];
            if len(targets) != 1 {
                card.gate_status = "invalid";
                card.gate_reason = "malformed dependency edge";
                return;
            }
            dep = targets[0];
            if dep is card {
                card.gate_status = "invalid";
                card.gate_reason = "self-dependency";
                return;
            }
            self.gate(dep, depth + 1, seen + [card]);
            if dep.gate_status == "invalid" or dep.gate_status == "unknown" {
                status = dep.gate_status;
                reason = dep.gate_reason;
                blockers.append(dep.title);
            } else if dep.gate_status != "eligible" or not dep.satisfies(e.condition) {
                status = "blocked";
                reason = "prerequisite not satisfied: " + e.condition;
                blockers.append(dep.title);
            }
        }
        card.gate_status = status;
        card.gate_reason = reason;
        card.blocked_by = blockers;
    }

    can dispatch with Card exit {
        verdict = "DISPATCH" if here.gate_status == "eligible" else "HOLD (" + here.gate_status + ")";
        print(f"{here.title}: {verdict} reason={here.gate_reason} blockedBy={here.blocked_by}");
    }
}

walker ClaimCard {
    has target: str = "";

    can start with Root entry {
        visit [-->];
    }

    can scan_board with Board entry {
        visit [-->];
    }

    can try_claim with Card entry {
        if here.title == self.target {
            # Re-evaluate immediately before the claim mutation.
            checker = GateCheck();
            checker.gate(here, 0, []);
            if here.gate_status == "eligible" {
                here.done = True;
                print(f"CLAIMED {here.title}");
            } else {
                print(f"CLAIM REJECTED {here.title}: {here.gate_status} ({here.gate_reason})");
            }
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    b = Board(name="Dev Board");
