"""Tree-structured folders: nested to unlimited depth with cycle-safe reparenting.

Models the core of the Folder map: folders form a tree via typed Contains
edges, a sidebar walker renders depth with an explicit visited guard (no
built-in dedup in walkers), and "Move to..." refuses any reparent that
would make the destination a descendant of the folder being moved.
"""

node Folder {
    has name: str = "";
}

node Note {
    has title: str = "";
}

node Client {
    has client_name: str = "";
}

edge Contains {
    has order: int = 0;
}

edge FiledIn { }

walker Sidebar {
    has visited: dict = {};
    has depth: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can render_folder with Folder entry {
        if here in self.visited {
            print(f"cycle detected at {here.name}; skipping");
        } else {
            self.visited[here] = True;
            indent = "  " * self.depth;
            print(f"{indent}[folder] {here.name}");
            self.depth += 1;
            visit [-->];
            self.depth -= 1;
        }
    }

    can render_note with Note entry {
        indent = "  " * self.depth;
        print(f"{indent}- {here.title}");
    }

    can skip_client with Client entry {
        # Clients stay flat and untouched; nothing to descend into.
    }
}

walker MoveTo {
    has target_name: str = "";
    has moving_name: str = "";

    can find_moving with Root entry {
        found: Folder | None = None;
        for f in [-->] {
            if f is Folder {
                if f.name == self.moving_name {
                    found = f;
                }
            }
        }
        if found is None {
            print(f"folder '{self.moving_name}' not found at root");
        } else {
            self.attempt(found);
        }
    }

    def attempt(moving: Folder) {
        dest: Folder | None = None;
        for f in [-->(?:Folder)] {
            if f.name == self.target_name {
                dest = f;
            }
        }
        if dest is None {
            print(f"destination '{self.target_name}' not found");
            return;
        }
        if self.descends_from(dest, moving) {
            print(f"refused: '{self.target_name}' is inside '{self.moving_name}'");
            return;
        }
        moving del --> dest;
        dest +>:Contains:+> moving;
        print(f"moved '{moving.name}' into '{dest.name}'");
    }

    def descends_from(candidate: Folder, ancestor: Folder) -> bool {
        # Is ancestor reachable from candidate via Contains? Cycle-safe DFS.
        seen = {};
        stack = [candidate];
        while stack.length() > 0 {
            cur = stack.pop();
            if cur in seen {
                continue;
            }
            seen[cur] = True;
            if cur == ancestor {
                return True;
            }
            for child in [cur -->] {
                stack.append(child);
            }
        }
        return False;
    }
}

