"""Filtered graph traversal primitives: BFS neighborhood, shortest path, component check.

Lifts issue #6's hand-rolled adjacency-list BFS into typed edges
(``Rel`` carries ``predicate`` and ``read_level`` for classification
filtering) and walkers with explicit visited sets and depth caps.
"""

node Entity {
    has name: str = "";
    has classification: int = 0;  # 0 public .. 3 restricted
}

edge Rel {
    has predicate: str = "";
    has read_level: int = 0;  # min clearance needed to traverse this edge
}

walker NeighborhoodBFS {
    has max_depth: int = 2;
    has clearance: int = 2;
    has visited: dict = {};
    has frontier: list = [];
    has depth: int = 0;
    has found: str = "";       # optional target name for shortest-path mode
    has path_len: int = -1;

    can start with Root entry {
        self.report("spawn NeighborhoodBFS on an Entity");
        disengage;
    }

    can bfs with Entity entry {
        # Cycle guard: jac walkers have no built-in dedupe.
        if here.name in self.visited { disengage; }
        self.visited[here.name] = True;
        print(f"depth {self.depth}: {here.name} "
              f"(cls={here.classification})");
        if self.found != "" and here.name == self.found {
            self.path_len = self.depth;
            print(f"target {here.name} reached in {self.depth} hops");
            disengage;
        }
        if self.depth >= self.max_depth { disengage; }
        # Filtered expansion: only edges the clearance may read,
        # fan-out capped per hub-node policy.
        next_frontier = [];
        cap = 0;
        for e in here.edges(Rel) {
            if cap >= 3 { break; }
            if e.read_level > self.clearance { continue; }
            next_frontier += [e target];
            cap += 1;
        }
        self.frontier = next_frontier;
        self.depth += 1;
        if len(self.frontier) == 0 { disengage; }
        visit [->:Rel:->];
    }
}

walker ComponentCheck {
    has target_name: str = "";
    has clearance: int = 2;
    has visited: dict = {};
    has connected: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can probe with Entity entry {
        if here.name in self.visited { disengage; }
        self.visited[here.name] = True;
        if here.name == self.target_name {
            self.connected = True;
            disengage;
        }
        visit [->:Rel:->] else { disengage; }
    }
}

def filter_nodes(nodes: list[Entity], max_cls: int) -> list[Entity] {
    """Primitive 2: property lookup on a node set."""
    out = [];
    for n in nodes {
        if n.classification <= max_cls {
            out += [n];
        }
    }
    return out;
}

