    #   alice --owns--> repo --depends_on--> lib --references--> spec
    #        \--contrib--> lib ; spec --mentions--> secret (RESTRICTED)
    alice = Entity(name="alice", classification=0);
    repo = Entity(name="repo", classification=1);
    lib = Entity(name="lib", classification=2);
    spec = Entity(name="spec", classification=2);
    secret = Entity(name="secret", classification=3);

    alice +>:Rel(predicate="owns", read_level=0):+> repo;
    repo +>:Rel(predicate="depends_on", read_level=1):+> lib;
    lib +>:Rel(predicate="references", read_level=1):+> spec;
    alice +>:Rel(predicate="contributes", read_level=2):+> lib;
    spec +>:Rel(predicate="mentions", read_level=3):+> secret;

    root ++> alice;

    # 1. Filtered neighborhood traversal (depth 2, TEAM clearance 2).
    print("--- neighborhood BFS from alice, depth 2, clearance 2 ---");
    alice spawn NeighborhoodBFS(max_depth=2, clearance=2);

    # 2. Shortest path (early termination on target).
