"""Keyed recursive CTE demo: settled-set shortest path over a weighted cyclic graph.

Instead of append-only path enumeration, the walker keeps a settled map
(one best row per key) and propagates only the delta of changed rows,
terminating on cyclic graphs without path tracking.
"""

node Vertex {
    has name: str = "";
}

edge Weighted {
    has weight: float = 0.0;
}

walker ShortestPath {
    has source: str = "";
    has settled: dict = {};
    has delta: dict = {};
    has index: dict = {};
    has weights: dict = {};
    has iterations: int = 0;

    def relax(v: Vertex, cost: float) -> bool {
        best = self.settled.get(v.name);
        if best is None or cost < best {
            self.settled[v.name] = cost;
            self.delta[v.name] = cost;
            return True;
        }
        return False;
    }

    def edge_weight(src: str, dst: str) -> float {
        return self.weights[f"{src}->{dst}"];
    }

    can start with Root entry {
        # Seed phase: find the source among the vertices.
        for v in [-->] {
            self.index[v.name] = v;
            if v.name == self.source {
                self.relax(v, 0.0);
            }
        }
        self.converge();
        report self.settled;
    }

    def converge() {
        # Semi-naive evaluation: the working table holds only the changed
        # rows (delta); a row identical to the settled row is a no-op and
        # is never propagated, so cycles terminate without path tracking.
        while self.delta {
            self.iterations += 1;
            work = self.delta;
            self.delta = {};
            for key in work.keys() {
                cost = work[key];
                v = self.index[key];
                for n in [v ->:Weighted:->] {
                    w = self.edge_weight(v.name, n.name);
                    self.relax(n, cost + w);
                }
            }
        }
    }
}

with entry {
    a = Vertex(name="a");
    b = Vertex(name="b");
    c = Vertex(name="c");
    d = Vertex(name="d");

    # Cyclic weighted graph: a -> b -> c -> a, plus a -> d -> c.
    a +>:Weighted(weight=4.0):+> b;
    b +>:Weighted(weight=1.0):+> c;
    c +>:Weighted(weight=2.0):+> a;
    a +>:Weighted(weight=7.0):+> d;
    d +>:Weighted(weight=1.0):+> c;

    root ++> a ++> b ++> c ++> d;

    finder = ShortestPath(
        source="a",
        weights={
            "a->b": 4.0,
            "b->c": 1.0,
            "c->a": 2.0,
            "a->d": 7.0,
            "d->c": 1.0,
        },
    );
    root spawn finder;

    print(f"settled distances: {finder.settled}");
    print(f"converged in {finder.iterations} iterations despite cycle a->b->c->a");
}

