"""NetBox topology: typed-edge graph with a constrained BFS trace walker.

A patch path from an access port to a gateway is traced over Cabled
edges; the walker reports an ordered path, or an explicit break reason
when documentation (a cable termination) is missing or the depth cap
is hit.
"""

node Device {
    has name: str = "";
    has role: str = "";          # "gateway" | "switch" | "patch" | "host"
}

node Interface {
    has name: str = "";
    has documented: bool = True;  # False = missing cable documentation
}

edge Cabled {
    has label: str = "";          # patch panel / trunk annotation
}

edge Hosts { }                    # device -> interface

edge LogsTo { }                   # logical view shortcut (collapsed patch path)

walker TopologyTrace {
    has target_role: str = "gateway";
    has max_depth: int = 8;
    has visited: dict = {};
    has path: list = [];
    has done: bool = False;

    def trace_report() -> str {
        hops = [f"{h}" for h in self.path];
        return " -> ".join(hops);
    }

    can start with Root entry {
        visit [-->];
    }

    can begin with Device entry {
        if here.role == "gateway" {
            print(f"already at gateway {here.name}");
            self.done = True;
            disengage;
        }
        self.path.append(f"{here.name}:{here.role}");
        self.visited[here.name] = True;
        visit [->:Hosts:->];
    }

    can hop with Interface entry {
        if self.done { disengage; }
        if here.name in self.visited {
            disengage;  # cycle guard: jac walkers do not dedupe visits
        }
        self.visited[here.name] = True;
        if not here.documented {
            print(f"BROKEN TRACE: unterminated cable at {here.name} "
                  f"(missing documentation)");
            disengage;
        }
        if self.path.__len__() >= self.max_depth {
            print(f"BROKEN TRACE: depth cap {self.max_depth} reached at {here.name}");
            disengage;
        }
        # constrained BFS over cable terminations
        front = [here];
        depth = 0;
        while depth < self.max_depth and front.__len__() > 0 and not self.done {
            nxt = [];
            for cand in front {
                for (peer, via) in cand -->:Cabled:--> :Interface {
                    if peer.name in self.visited { continue; }
                    self.visited[peer.name] = True;
                    self.path.append(f"--[{via.label}]--> {peer.name}");
                    owner = [<--:Hosts:--] else { continue; };
                    if owner.role == self.target_role {
                        self.path.append(f"{owner.name}:{owner.role}");
                        print(f"WIRED PATH: {self.trace_report()}");
                        self.done = True;
                        disengage;
                    }
                    nxt.append(peer);
                }
            }
            front = nxt;
            depth += 1;
        }
        if not self.done and front.__len__() == 0 and depth == 0 {
            print(f"BROKEN TRACE: dead end at {here.name}");
            disengage;
        }
    }
}

walker LogicalView {
    can start with Root entry {
        visit [-->];
    }

    can collapse with Device entry {
        visit [->:LogsTo:->];
    }

    can show with Interface entry {
        print(f"logical hop: {here.name}");
    }
}

