"""Management hierarchy: unlimited-depth org chart driven by typed ReportsTo edges.

Employees are nodes; supervisor-subordinate relationships are typed edges.
A walker replaces hand-rolled parent_id recursion: SubordinateScan collects
direct and indirect reports, and Reassigner moves an employee (with their
whole subtree) under a new parent by re-linking typed edges.
"""

node Employee {
    has name: str = "";
    has role_level: int = 0;  # 5 = admin+, lower = regular staff
}

edge ReportsTo { }

walker OrgBuilder {
    can start with Root entry {
        visit [-->];
    }
    can wire with Employee entry {
        visit [-->];
    }
}

walker SubordinateScan {
    has direct_only: bool = False;
    has reports: list[str] = [];

    can start with Root entry {
        visit [->:ReportsTo:->];
    }

    can scan with Employee entry {
        self.reports.append(here.name);
        if not self.direct_only {
            visit [->:ReportsTo:->];
        }
    }

    can finish with Employee exit {
        if self.reports {
            print(f"Subordinates of chain walk: {self.reports}");
            self.reports = [];
        }
    }
}

walker Reassigner {
    has actor_level: int = 0;
    has target: Employee | None = None;
    has new_parent: Employee | None = None;
    has moved: list[str] = [];

    can start with Root entry {
        if self.actor_level < 4 {
            print("PermissionDenied: only admins can modify org chart");
            disengage;
        }
        if self.target is None or self.new_parent is None {
            print("Reassigner requires target and new_parent");
            disengage;
        }
        # Move the target's subtree: collect target + descendants first.
        self.moved.append(self.target.name);
        subtree = self.collect_subtree(self.target);
        for (emp) in subtree {
            print(f"moved: {emp.name} -> under {self.new_parent.name}");
        }
        self.new_parent +>:ReportsTo:+> self.target;
        report f"Reassignment complete: subtree of {self.target.name} now under {self.new_parent.name}";
    }

    def collect_subtree(start: Employee) -> list[Employee] {
        found = [start];
        frontier = [start];
        while frontier {
            current = frontier.pop();
            for (child) in current -->:ReportsTo:--> {
                found.append(child);
                frontier.append(child);
            }
        }
        return found;
    }
}

walker ApprovalCheck {
    has potential_ancestor: Employee | None = None;
    has found: bool = False;

    can start with Root entry {
        if self.potential_ancestor is None {
            disengage;
        }
        visit [->:ReportsTo:->];
    }

    can climb with Employee entry {
        if here == self.potential_ancestor {
            self.found = True;
            disengage;
        }
        visit [->:ReportsTo:->];
    }
}

