"""Project model: replace string-keyed relations with typed semantic edges.

Demonstrates source-anchored relationship facts (semantic_relationship.v1)
as typed edges between canonical subjects, with a walker that traces
re-export lineage back to the original definition and detects dynamic
boundaries — the machinery the issue complains was hand-rolled over
string maps.
"""

node File {
    has title: str = "";
    has path: str = "";
    has revision: str = "";
    has available: bool = True;
}

node Symbol {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Boundary {
    has title: str = "";
    has year: int = 0;
    has available: bool = False;
}

edge Declares {
    has ordinal: int = 0;
    has phase: str = "compile";
}

edge Exports {
    has reexport: bool = False;
    has confidence: float = 1.0;
}

edge Inherits {
    has dynamic: bool = False;
    has confidence: float = 1.0;
}

edge Resolves {
    has phase: str = "compile";
}

walker ReexportAuditor {
    has checked: int = 0;
    has dynamic_edges: int = 0;
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_file with File entry {
        self.checked += 1;
        visit [->:Declares:->];
    }

    can audit_symbol with Symbol | Boundary entry {
        self.checked += 1;
        visit [->:Exports:->];
        visit [->:Inherits:->];
    }

    can follow with File entry {
        visit [->:Declares:->];
    }

    can trace with Symbol entry {
        visit [->:Exports:->] else {
            visit [->:Inherits:->] else {
                disengage;
            }
        }
    }

    can inspect_inherit with Symbol entry {
        visit [->:Inherits:->];
    }

    can note with Boundary entry {
        self.dynamic_edges += 1;
        self.findings.append(f"unresolved boundary: {here.title}");
    }
}

walker MROChecker {
    has chain: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can walk_class with Symbol entry {
        self.chain.append(here.title);
        visit [->:Inherits:->] else {
            disengage;
        }
    }
}

with entry {
    # lib/util.jac declares the original definition.
    util_file = File(title="util.jac", path="lib/util.jac", revision="gen-42");
    # app/main.jac re-exports it — the re-export site is NOT the origin.
    main_file = File(title="main.jac", path="app/main.jac", revision="gen-43");
    helper = File(title="helper.jac", path="app/helper.jac", revision="gen-43");

    # Canonical subjects.
    base = Symbol(title="BaseCache");
    derived = Symbol(title="LruCache");
    origin = Symbol(title="make_cache");
    reexport_site = Symbol(title="make_cache (re-export)");
    missing = Boundary(title="dynamic://unknown-module");

    # File declares its symbols with source order.
    util_file +>:Declares(ordinal=0):+> origin;
    main_file +>:Declares(ordinal=0):+> reexport_site;
    helper +>:Declares(ordinal=1):+> base;

    # Re-export lineage: the re-export site points at the origin.
    reexport_site +>:Exports(reexport=True, confidence=0.95):+> origin;
    origin +>:Exports(reexport=False):+> util_file;

    # Dynamic inheritance: derived inherits from an unavailable boundary.
    derived +>:Inherits(dynamic=True, confidence=0.4):+> missing;

    # Resolved module requests between files.
    main_file +>:Resolves:+> util_file;

    root ++> main_file ++> helper ++> util_file
        ++> derived ++> reexport_site ++> origin ++> missing;

    root spawn ReexportAuditor();
    root spawn MROChecker();
}

