    has failures: int = 0;

    can start with Preset entry {
        label = "warm" if here.warm_models else "cold";
        print(f"Running preset '{here.name}' ({label}), budget {here.budget_ms} ms");
        visit [->:Feeds:->] else { disengage; }
    }

    can measure with Stage entry {
        latency = here.warm_ms;
        if self.stage_count == 0 {
            print(f"cold run of {here.name}: {here.cold_ms} ms (discarded)");
        }
        self.total_ms += latency;
        self.stage_count += 1;
        if latency > 1000.0 {
            self.failures += 1;
            print(f"[FAIL] {here.name}: {latency} ms exceeds 1000 ms budget");
        } else {
            print(f"[ok] {here.name}: {latency} ms");
        }
        visit [->:Feeds:->];
    }
}

with entry {
    bench = Preset(name="light", warm_models=True, budget_ms=2500.0);
    cap = Stage(name="AudioCaptureCore-conversion", cold_ms=620.0, warm_ms=180.0);
    asr = Stage(name="ASRService", cold_ms=2400.0, warm_ms=760.0);
    fmt = Stage(name="FormattingService", cold_ms=510.0, warm_ms=140.0);

    bench +>:RunsOn:+> cap;
    cap +>:Feeds(order=1):+> asr;
    asr +>:Feeds(order=2):+> fmt;

    bench spawn BenchRunner();

    total = bench.total_ms;
    stages = bench.stage_count;
