}

"""Management hierarchy: unlimited-depth org chart driven by typed ReportsTo edges.

Employees are nodes; supervisor-subordinate relationships are typed edges.
Walkers replace hand-rolled parent_id recursion: SubordinateScan collects
direct and indirect reports, SubtreeCollect gathers a whole subtree, and
Reassigner moves an employee (with their whole subtree) under a new parent
by re-linking typed edges. RBAC and ancestor checks (approval chains) are
preserved as domain logic.
"""

node Employee {
    has name: str = "";
    has role_level: int = 0;  # 5 = admin+, lower = regular staff
}

edge ReportsTo { }

walker SubordinateScan {
    has direct_only: bool = False;
    has reports: list[str] = [];

    can start with Root entry {
        visit [->:ReportsTo:->];
    }

    can scan with Employee entry {
        self.reports.append(here.name);
        if not self.direct_only {
            visit [->:ReportsTo:->];
        }
    }
}

walker SubtreeCollect {
    has names: list[str] = [];

    can gather with Employee entry {
        self.names.append(here.name);
        visit [->:ReportsTo:->];
    }
}

walker Reassigner {
    has actor_level: int = 0;
    has target: Employee | None = None;
    has new_parent: Employee | None = None;

    can start with Root entry {
        if self.actor_level < 4 {
            print("PermissionDenied: only admins can modify org chart");
            disengage;
        }
        if self.target is None or self.new_parent is None {
            print("Reassigner requires target and new_parent");
            disengage;
        }
        target_node = self.target;
        parent_node = self.new_parent;
        # Move the target AND their entire subtree: collect names first.
        collector = SubtreeCollect();
        target_node spawn collector;
        for (nm) in collector.names {
            print(f"moved: {nm} -> under {parent_node.name}");
        }
        parent_node +>:ReportsTo:+> target_node;
        print(f"Reassignment complete: subtree of {target_node.name} now under {parent_node.name}");
    }
}

walker ApprovalCheck {
    has potential_ancestor: Employee | None = None;
    has found: bool = False;

    can start with Root entry {
        if self.potential_ancestor is None {
            disengage;
        }
        visit [->:ReportsTo:->];
    }

    can climb with Employee entry {
        if self.potential_ancestor is not None and here == self.potential_ancestor {
            self.found = True;
            disengage;
        }
        visit [->:ReportsTo:->];
    }
}

with entry {
    owner = Employee(name="Ora Owner", role_level=5);
    director = Employee(name="Dana Director", role_level=4);
    manager = Employee(name="Milo Manager", role_level=3);
    supervisor = Employee(name="Sara Supervisor", role_level=2);
    worker = Employee(name="Wes Worker", role_level=1);

    root ++> owner;
    owner +>:ReportsTo:+> director;
    director +>:ReportsTo:+> manager;
    manager +>:ReportsTo:+> supervisor;
    supervisor +>:ReportsTo:+> worker;

    print("--- direct reports of Sara Supervisor ---");
    supervisor spawn SubordinateScan(direct_only=True);

    print("--- reassign Wes Worker under Dana Director (admin actor) ---");
    root spawn Reassigner(actor_level=5, target=worker, new_parent=director);

    print("--- verify: Dana Director is ancestor of Wes Worker ---");
    check = ApprovalCheck(potential_ancestor=director);
    worker spawn check;
    print(f"ancestor check: {check.found}");

    print("--- non-admin reassignment attempt ---");
    root spawn Reassigner(actor_level=2, target=worker, new_parent=manager);

    print("--- full indirect reports of Dana Director after move ---");
    director spawn SubordinateScan(direct_only=False);
}

"""Filtered graph traversal primitives: BFS neighborhood, shortest path, component check.

Lifts issue #6's hand-rolled adjacency-list BFS into typed edges and
walkers with explicit visited sets, depth caps, fan-out limits, and a
classification-based filter (an actor at TEAM clearance cannot see
RESTRICTED nodes, so those branches of the graph are pruned).
"""

node Entity {
    has name: str = "";
    has classification: int = 0;  # 0 public .. 3 restricted

    def visible_neighbors(clearance: int, cap: int) -> list[Entity] {
        """Filtered, fan-out-capped expansion of outgoing Rel edges."""
        out: list[Entity] = [];
        for tgt in [self->:Rel:->] {
            if len(out) >= cap {
                break;
            }
            if tgt.classification > clearance {
                continue;
            }
            out += [tgt];
        }
        return out;
    }
}

edge Rel {
    has predicate: str = "";
    has read_level: int = 0;  # min clearance needed to traverse this edge
}

walker NeighborhoodBFS {
    has max_depth: int = 2;
    has clearance: int = 2;
    has fanout_cap: int = 3;
    has visited: dict = dict();
    has depth: int = 0;
    has target_name: str = "";   # non-empty enables shortest-path mode

    can start with Root entry {
        visit [-->];
    }

    can explore with Entity entry {
        # Cycle guard: jac walkers have no built-in once-only visitation.
        if here.name in self.visited {
            disengage;
        }
        self.visited[here.name] = self.depth;
        print(f"depth {self.depth}: {here.name} (cls={here.classification})");

        if self.target_name != "" and here.name == self.target_name {
            print(f"shortest path to {here.name}: {self.depth} hops");
            disengage;
        }
        if self.depth >= self.max_depth {
            disengage;
        }

        # Filtered expansion: classification prunes the effective graph,
        # fan-out cap protects against hub nodes.
        frontier = here.visible_neighbors(self.clearance, self.fanout_cap);
        self.depth += 1;
        if len(frontier) == 0 {
            disengage;
        }
        visit frontier;
    }
}

walker ComponentCheck {
    has target_name: str = "";
    has clearance: int = 2;
    has visited: dict = dict();
    has connected: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can probe with Entity entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited[here.name] = True;
        if here.name == self.target_name {
            self.connected = True;
            disengage;
        }
        nxt = here.visible_neighbors(self.clearance, 99);
        if len(nxt) == 0 {
            disengage;
        }
        visit nxt;
    }
}

def filter_nodes(nodes: list[Entity], max_cls: int) -> list[Entity] {
    """Primitive 2: property lookup on a node set."""
    out: list[Entity] = [];
    for n in nodes {
        if n.classification <= max_cls {
            out += [n];
        }
    }
    return out;
}

with entry {
    #   alice --owns--> repo --depends_on--> lib --references--> spec
    #        \--contributes--> lib ; spec --mentions--> secret (RESTRICTED)
    alice = Entity(name="alice", classification=0);
    repo = Entity(name="repo", classification=1);
    lib = Entity(name="lib", classification=2);
    spec = Entity(name="spec", classification=2);
    secret = Entity(name="secret", classification=3);

    alice +>:Rel(predicate="owns", read_level=0):+> repo;
    repo +>:Rel(predicate="depends_on", read_level=1):+> lib;
    lib +>:Rel(predicate="references", read_level=1):+> spec;
    alice +>:Rel(predicate="contributes", read_level=2):+> lib;
    spec +>:Rel(predicate="mentions", read_level=3):+> secret;

    root ++> alice;

    # 1. Filtered neighborhood traversal (depth 2, TEAM clearance 2).
    print("--- neighborhood BFS from alice, depth 2, clearance 2 ---");
    alice spawn NeighborhoodBFS(max_depth=2, clearance=2);

    # 2. Shortest path (early termination on target).
    print("--- shortest path alice -> spec ---");
    alice spawn NeighborhoodBFS(max_depth=5, clearance=2, target_name="spec");

    # 3. Component membership: is alice connected to secret at clearance 2?
    #    The RESTRICTED node is pruned, so the walk cannot reach it.
    probe = ComponentCheck(target_name="secret", clearance=2);
    alice spawn probe;
    verdict = "connected" if probe.connected else "NOT connected";
    print(f"alice is {verdict} to secret at clearance 2");

    # 4. Set intersection over traversal results.
    seen = [alice, repo, lib, spec, secret];
    visible = filter_nodes(seen, max_cls=2);
    names = [];
    for n in visible {
        names += [n.name];
    }
    print("visible nodes: " + ", ".join(names));
}

"""NetBox topology: typed-edge graph with a constrained BFS-style trace walker.

A patch path from an access port to a gateway is traced over Cabled
edges; the walker reports an ordered path, or an explicit break reason
when documentation (a cable termination) is missing or the depth cap
is hit.
"""

node Device {
    has name: str = "";
    has role: str = "";          # "gateway" | "switch" | "patch" | "host"
}

node Interface {
    has name: str = "";
    has documented: bool = True;   # False = missing cable documentation
    has owner_name: str = "";      # owning device label (denormalized)
    has owner_role: str = "";
}

edge Cabled {
    has label: str = "";           # patch panel / trunk annotation
}

edge Hosts { }                     # device -> interface

edge LogsTo { }                    # logical view shortcut (collapsed patch path)

walker TopologyTrace {
    has target_role: str = "gateway";
    has max_depth: int = 8;
    has visited: dict = {};
    has path: list = [];
    has done: bool = False;

    def trace_report() -> str {
        hops = [f"{h}" for h in self.path];
        return " -> ".join(hops);
    }

    can start with Root entry {
        visit [-->];
    }

    can begin with Device entry {
        if here.role == self.target_role {
            print(f"already at {self.target_role} {here.name}");
            self.done = True;
            disengage;
        }
        self.path.append(f"{here.name}:{here.role}");
        self.visited[here.name] = True;
        visit [->:Hosts:->];
    }

    can hop with Interface entry {
        if self.done { disengage; }
        if here.name in self.visited {
            disengage;  # cycle guard: jac walkers do not dedupe visits
        }
        self.visited[here.name] = True;
        if not here.documented {
            print(f"BROKEN TRACE: unterminated cable at {here.name} (missing documentation)");
            self.done = True;
            disengage;
        }
        if len(self.path) >= self.max_depth {
            print(f"BROKEN TRACE: depth cap {self.max_depth} reached at {here.name}");
            self.done = True;
            disengage;
        }
        if here.owner_name == "" {
            print(f"BROKEN TRACE: interface {here.name} has no owning device");
            self.done = True;
            disengage;
        }
        self.path.append(f"{here.name} @ {here.owner_name}:{here.owner_role}");
        if here.owner_role == self.target_role {
            print(f"WIRED PATH: {self.trace_report()}");
            self.done = True;
            disengage;
        }
        # continue the constrained walk across cable terminations
        visit [->:Cabled:->] else {
            print(f"BROKEN TRACE: dead end at {here.name}");
            self.done = True;
            disengage;
        }
    }
}

walker LogicalView {
    has done: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can collapse with Device entry {
        visit [->:Hosts:->];
    }

    can show with Interface entry {
        if self.done { disengage; }
        print(f"logical hop: {here.name}");
        visit [->:LogsTo:->] else { self.done = True; disengage; }
    }
}

with entry {
    gw = Device(name="core-gw", role="gateway");
    sw = Device(name="access-sw", role="switch");
    host = Device(name="ws-1", role="host");

    root ++> host ++> sw ++> gw;

    gw_i = Interface(name="eth0/1", owner_name="core-gw", owner_role="gateway");
