"""Leave-namespace cascade: upfront validation across the whole subtree, then per-scope mutation.

Models the calimero leave_namespace cascade: gather direct-row scopes by
walking child group edges, run owner/last-admin checks for ALL of them
upfront (fail before any mutation), then mutate and notify per scope.
Cross-peer atomicity stays eventual-consistent by design (Option A);
this demo shows the single-peer atomic window.
"""

node Member {
    has name: str = "";
}

node Group {
    has name: str = "";
    has last_admin_ok: bool = True;
}

edge ChildOf {
    has depth: int = 0;
}

edge Membership {
    has is_admin: bool = False;
}

walker LeaveNamespace {
    has leaver: str = "";
    has validated_scopes: list[Group] = [];
    has notifications: list[str] = [];

    can start with Root entry {
        visit [->:Membership:->];
    }

    can find_root_scope with Group entry {
        # Gather every descendant scope where the leaver holds a direct row.
        if any((m.name == self.leaver) for m in [here->:Membership:->]) {
            self.validated_scopes.append(here);
        }
        visit [->:ChildOf:->];
    }

    can validate_scope with Group entry {
        # Phase 1: upfront checks across ALL gathered scopes — fail before
        # any mutation if anything is wrong.
        if here not in self.validated_scopes {
            return;
        }
        ok = True;
        for m in [here->:Membership:->] {
            if m.name != self.leaver and here.last_admin_ok is False {
                ok = False;
            }
        }
        if not ok {
            print(f"ABORT: last-admin check failed in {here.name}; no rows removed");
            self.validated_scopes = [];
            disengage;
        }
    }

    can mutate_scope with Group exit {
        # Phase 2: mutate per-scope sequentially and notify. Locally atomic.
        for m in [here->:Membership:->] {
            if m.name == self.leaver {
                here del ->:Membership:-> m;
            }
        }
        self.notifications.append(f"MemberLeft notified for {here.name}");
        visit [->:ChildOf:->];
    }

    can report_done with Root exit {
        report self.notifications;
    }
}

with entry {
    root ++> Member(name="Alice") ++> Member(name="Bob") ++> Member(name="Carol");

    ns = Group(name="namespace");
    sub_a = Group(name="subgroup-a");
    sub_b = Group(name="subgroup-b", last_admin_ok=False);
    root ++> ns;
    ns +>:ChildOf(depth=1):+> sub_a;
    ns +>:ChildOf(depth=1):+> sub_b;

    ns +>:Membership(is_admin=True):+> root-->[0];
    ns +>:Membership:+> root-->[1];
    sub_a +>:Membership:+> root-->[0];
    sub_a +>:Membership:+> root-->[1];
    sub_b +>:Membership:+> root-->[0];
    sub_b +>:Membership(is_admin=True):+> root-->[2];

    root spawn LeaveNamespace(leaver="Alice");
}

"""Receiver-flow RCV-A: exact direct-assignment receiver transition at program points.

Bindings are nodes, direct `=` writes are typed Assignment edges, and program
points are chained in source order. A query walker walks the point sequence,
tracking the current receiver type of each binding exactly at the dominating
point — never from final whole-file state or traversal-order last-writer wins.
An inner same-named binding shadows the outer one inside its scope block.
"""

node Binding {
    has name: str = "";
    has scope: str = "main";
}

node Scope {
    has name: str = "";
}

edge DeclaredIn { }

edge Assignment {
    has rhs_type: str = "";
    has generation: int = 0;
}

node ProgramPoint {
    has label: str = "";
    has binding_name: str = "";
    has scope: str = "main";
    has expected: str = "";
}

edge Next { }
edge Queries { }

walker ReceiverQuery {
    has current: dict = {};
    has generation: int = 1;
    has results: list = [];
    has visited: list = [];

    can start with Root entry {
        visit [->:Next:->];
    }

    can step with ProgramPoint entry {
        # cycle guard: jac walkers do not dedupe visits on their own
        if here in self.visited {
            print(f"recurrence protection engaged at {here.label}");
            disengage;
        }
        self.visited.append(here);

        # stale/mixed-generation input stays typed bounded evidence, not a guess
        asn = [here ->:Assignment:->];
        if asn {
            for e in asn {
                if e.generation == self.generation {
                    key = (here.binding_name, here.scope);
                    self.current[key] = e.rhs_type;
                }
            }
        }

        # shadowing: innermost scope wins over main for the same name
        inner_key = (here.binding_name, here.scope);
        outer_key = (here.binding_name, "main");
        resolved = "";
        if inner_key in self.current.keys() {
            resolved = self.current[inner_key];
        } else if outer_key in self.current.keys() {
            resolved = self.current[outer_key];
        } else {
            resolved = "Unknown";
        }
        self.results.append((here.label, resolved));
        visit [->:Next:->] else { disengage; }
    }
}

with entry {
    main = Scope(name="main");
    inner = Scope(name="block");
    x_outer = Binding(name="$x", scope="main");
    x_inner = Binding(name="$x", scope="block");

    root +>:DeclaredIn:+> main;
    main +>:DeclaredIn:+> inner;
    main +>:DeclaredIn:+> x_outer;
    inner +>:DeclaredIn:+> x_inner;

    # canonical point sequence, source-ordered
    p1 = ProgramPoint(label="init", binding_name="$x", scope="main");
    p2 = ProgramPoint(label="call foo_only", binding_name="$x", scope="main");
    p3 = ProgramPoint(label="reassign", binding_name="$x", scope="main");
    p4 = ProgramPoint(label="call bar_only", binding_name="$x", scope="main");
    p5 = ProgramPoint(label="inner shadow init", binding_name="$x", scope="block");
    p6 = ProgramPoint(label="call baz_only", binding_name="$x", scope="block");
    p7 = ProgramPoint(label="call outer again", binding_name="$x", scope="main");

    root ++> p1 ++> p2 ++> p3 ++> p4 ++> p5 ++> p6 ++> p7;

    p1 +>:Assignment(rhs_type="Foo", generation=1):+> x_outer;
    p3 +>:Assignment(rhs_type="Bar", generation=1):+> x_outer;
    p5 +>:Assignment(rhs_type="Baz", generation=1):+> x_inner;

    for p in [p2, p4, p6, p7] {
        p +>:Queries:+> x_outer;
    }

    root spawn ReceiverQuery();
}

"""Reference occurrence extraction with explicit execution-owner stack.

Each callable/lifecycle/file unit owns the reference occurrences lexically
inside it; nested callables push a fresh owner instead of borrowing the
parent. Owner identity is a typed node, never a name/range/index.
"""

edge Contains { }

edge Produces {
    has generation: int = 0;
}

node ExecUnit {
    has kind: str = "";          # file | named | anonymous | lifecycle | unknown
    has identity: str = "";      # canonical identity, not display name
    has confidence: str = "exact";
    has generation: int = 0;     # accepted generation; newer replaces stale
}

node Occurrence {
    has symbol: str = "";
    has generation: int = 0;
}

walker OwnerStacker {
    has owners: list = [];       # explicit execution-owner stack
    has visited: dict = {};      # cycle guard: no built-in dedupe
    has stale_gen: int = 0;      # occurrences older than this are stale

    can start with Root entry {
        visit [->:Contains:->];
    }

    can enter_unit with ExecUnit entry {
        key = f"{here.identity}@{here.generation}";
        if self.visited.get(key, False) {
            disengage;           # mutually recursive units terminate
        }
        self.visited[key] = True;
        if here.generation < self.stale_gen {
            print(f"[stale] unit {here.identity} superseded; skipped");
            disengage;
        }
        conf = "partial" if here.kind == "unknown" else here.confidence;
        self.owners.append(f"{here.identity}:{here.kind}:{conf}");
        visit [->:Contains:->];
        self.owners.pop();
    }

    can record with Occurrence entry {
        owner = self.owners[-1] if len(self.owners) > 0 else "NONE";
        # negative control 10: missing ownership is never silently exact
        status = "UNOWNED!" if owner == "NONE" else "owned";
        stale = here.generation < self.stale_gen;
        tag = " (stale)" if stale else "";
        print(f"{status}: {here.symbol} -> owner {owner}{tag}");
    }
}

with entry {
    file = ExecUnit(kind="file", identity="doc:pkg:Main@1", generation=1);

    _a = ExecUnit(kind="named", identity="sub:Main::_a@1", generation=1);
    _b = ExecUnit(kind="named", identity="sub:Main::_b@1", generation=1);
    mut_a = ExecUnit(kind="named", identity="sub:Other::_a@1", generation=1);
    anon = ExecUnit(kind="anonymous", identity="anon:Main#7@1", generation=1);
    begin = ExecUnit(kind="lifecycle", identity="phase:Main:BEGIN@1", generation=1);
    bad = ExecUnit(kind="unknown", identity="recovered:Main#12@1", generation=1, confidence="partial");

    other = ExecUnit(kind="file", identity="doc:pkg:Other@1", generation=1);
    other_anon = ExecUnit(kind="anonymous", identity="anon:Other#3@1", generation=1);

    root +>:Contains:+> file;
    file +>:Contains:+> _a;
    file +>:Contains:+> begin;
    file +>:Contains:+> anon;
    file +>:Contains:+> bad;
    file +>:Contains:+> Occurrence(symbol="toplevel_call", generation=1);
    _a +>:Contains:+> _b;                      # _a owns the _b call
    _b +>:Contains:+> _a;                      # mutual recursion: distinct owners
    anon +>:Contains:+> Occurrence(symbol="inner_call", generation=1);
    begin +>:Contains:+> Occurrence(symbol="init_call", generation=1);
    bad +>:Contains:+> Occurrence(symbol="recovered_call", generation=1);
    other +>:Contains:+> other_anon;
    other_anon +>:Contains:+> Occurrence(symbol="inner_call", generation=1);  # same name, distinct owner

    root spawn OwnerStacker(stale_gen=2);
}

"""CompilerWorld demo: typed dependency graph with cycle-guarded invalidation.

Modules carry public/private interface state and staleness; compile-time
dependencies are typed DependsOn edges. One walker computes a deterministic
SCC-ish compile order (deepest dependencies first), another performs targeted
invalidation across the reverse-dependency closure with an explicit visited
guard (walkers have no built-in once-per-node visitation).
"""

node Module {
    has name: str = "";
    has version: str = "0";
    has is_public_interface: bool = True;
    has stale: bool = False;
    has compile_order: int = 0;
}

edge DependsOn {
    has conditional: bool = False;
}

walker CompileScheduler {
    has counter: int = 0;

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can schedule with Module entry {
        # Depth-first: emit dependencies before the dependent.
        visit [->:DependsOn:->];
        self.counter += 1;
        here.compile_order = self.counter;
        print(f"compile #{here.compile_order}: {here.name} v{here.version}"
              f" ({'public' if here.is_public_interface else 'private'})");
    }
}

walker Invalidator {
    has reason: str = "source change";
    has visited: dict = {};

    can start with Root entry {
        visit [->:DependsOn:->] else { disengage; }
    }

    can spread with Module entry {
        # Explicit cycle policy: no built-in dedupe, so guard by name.
        if here.name in self.visited {
            disengage;
        }
        self.visited[here.name] = True;
        here.stale = True;
        print(f"invalidated {here.name}: {self.reason}");
        visit [->:DependsOn:->];
    }
}

with entry {
    util = Module(name="Utils", version="1.2");
    config = Module(name="Config", version="3.0");
    core = Module(name="Core", version="0.9", is_public_interface=False);
    app = Module(name="App", version="5.1");

    app +>:DependsOn:+> core;
    core +>:DependsOn:+> util;
    core +>:DependsOn:+> config;
    util +>:DependsOn:+> config;

    root ++> app;
    root spawn CompileScheduler();

    # Touch a leaf module and invalidate its reverse... actually forward
    # dependents via the dependency closure from the changed module.
    root ++> util;
    root spawn Invalidator(reason="Utils.pm source edit");
}

"""Project model: replace string-keyed relations with typed semantic edges.

Demonstrates source-anchored relationship facts (semantic_relationship.v1)
as typed edges between canonical subjects. A ReexportAuditor traces
re-export lineage back to the original definition and flags dynamic
boundaries; an MROChecker walks inheritance chains with an explicit
cycle guard and depth cap — semantics the issue says were hand-rolled
over string maps.
"""

node File {
    has title: str = "";
    has path: str = "";
    has revision: str = "";
    has available: bool = True;
}

node Symbol {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has is_reexport: bool = False;
}

node Boundary {
    has title: str = "";
    has year: int = 0;
    has available: bool = False;
}

edge Declares {
    has ordinal: int = 0;
    has phase: str = "compile";
}

edge Exports {
    has reexport: bool = False;
    has confidence: float = 1.0;
}

edge Inherits {
    has dynamic: bool = False;
    has confidence: float = 1.0;
}

edge Resolves {
    has phase: str = "compile";
}

walker ReexportAuditor {
    has checked: int = 0;
    has dynamic_edges: int = 0;
    has findings: list[str] = [];

    can start with Root entry {
        visit [->:Resolves:->] else { disengage; }
    }

    can audit_file with File entry {
        self.checked += 1;
        print(f"auditing {here.title} @ rev {here.revision}");
        visit [->:Declares:->];
    }

    can audit_symbol with Symbol entry {
        self.checked += 1;
        origin = "re-export site" if here.is_reexport else "definition";
        print(f"subject {here.title} ({origin})");
        visit [->:Exports:->];
    }

    can audit_boundary with Boundary entry {
        self.checked += 1;
        self.dynamic_edges += 1;
        self.findings.append(f"unresolved dynamic boundary: {here.title}");
    }

    can trace_origin with Symbol entry {
        # Arrived at the true origin of a re-export chain; do NOT follow
        # further Exports edges back toward files (that would cycle).
        self.findings.append(f"re-export resolves to original: {here.title}");
        disengage;
    }

    can trace_file with File entry {
        self.findings.append(f"export anchored back to declaring file: {here.title}");
        disengage;
    }
}

walker MROChecker {
    has chain: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 8;
    has seen: list[str] = [];

    can start with Root entry {
        visit [->:Declares:->] else { disengage; }
    }

    can walk_class with Symbol entry {
        if here.title in self.seen or self.depth > self.max_depth {
            print("MRO walk stopped: cycle guard or depth cap hit");
            disengage;
        }
        self.seen.append(here.title);
        self.chain.append(here.title);
        self.depth += 1;
        visit [->:Inherits:->] else {
            report self.chain;
            disengage;
        }
    }

    can hit_boundary with Boundary entry {
        print(f"MRO ends at dynamic boundary {here.title} (limitation, not a miss)");
        report self.chain;
        disengage;
    }
}

with entry {
    # Source files with content revisions.
    util_file = File(title="util.jac", path="lib/util.jac", revision="gen-42");
    main_file = File(title="main.jac", path="app/main.jac", revision="gen-43");

    # Canonical subjects.
    origin = Symbol(title="make_cache");
    reexport_site = Symbol(title="make_cache (re-export)", is_reexport=True);
    base = Symbol(title="BaseCache");
    derived = Symbol(title="LruCache");
    missing = Boundary(title="dynamic://unknown-module");

    # Files declare their subjects with source order.
    util_file +>:Declares(ordinal=0):+> origin;
    main_file +>:Declares(ordinal=1):+> base;

    # Re-export lineage: the re-export site points at the origin,
    # which anchors back to its declaring file.
    reexport_site +>:Exports(reexport=True, confidence=0.95):+> origin;
    origin +>:Exports(reexport=False):+> util_file;

    # Dynamic inheritance: derived inherits from an unavailable boundary.
    base +>:Inherits:+> derived;
    derived +>:Inherits(dynamic=True, confidence=0.4):+> missing;

    # Resolved module request between files.
    main_file +>:Resolves:+> util_file;

    root ++> main_file ++> base ++> derived;

    root spawn ReexportAuditor();
    root spawn MROChecker();
}

"""Static agent-graph workflow: plan -> fan-out investigation -> synthesize -> write -> check -> bounded repair -> evidence gate.

Nodes are workflow phases; walkers play the agent roles. The graph topology is
static (the model may not rewrite it), the repair loop is host-bounded, and the
final evidence gate refuses completion without deterministic proof.
"""

node Phase {
    has name: str = "";
    has done: bool = False;
}

node Investigator {
    has label: str = "";
    has findings: str = "";
}

node CheckResult {
    has check_name: str = "";
    has passed: bool = False;
}

