Each callable/lifecycle/file unit owns the reference occurrences lexically
inside it; nested callables push a fresh owner instead of borrowing the
parent. Owner identity is a typed node, never a name/range/index.
"""

edge Contains { }

node ExecUnit {
    has kind: str = "";          # file | named | anonymous | lifecycle | unknown
    has identity: str = "";      # canonical identity, not display name
    has confidence: str = "exact";
    has generation: int = 0;     # accepted generation; newer replaces stale
}

node Occurrence {
    has symbol: str = "";
    has generation: int = 0;
}

walker OwnerStacker {
    has owners: list[str] = [];     # explicit execution-owner stack
    has visited: list[str] = [];    # cycle guard: no built-in dedupe
    has stale_gen: int = 0;         # occurrences older than this are stale

    can start with Root entry {
        visit [->:Contains:->];
    }

    can enter_unit with ExecUnit entry {
        key = f"{here.identity}@{here.generation}";
        if key in self.visited {
            disengage;              # mutually recursive units terminate
        }
        self.visited.append(key);
        if here.generation < self.stale_gen {
            print(f"[stale] unit {here.identity} superseded; skipped");
            disengage;
        }
        conf = "partial" if here.kind == "unknown" else here.confidence;
        self.owners.append(f"{here.identity}:{here.kind}:{conf}");
        visit [->:Contains:->];
        self.owners.pop();
    }

    can record with Occurrence entry {
        owner = self.owners[-1] if len(self.owners) > 0 else "NONE";
        # negative control 10: missing ownership is never silently exact
        status = "UNOWNED!" if owner == "NONE" else "owned";
        stale = here.generation < self.stale_gen;
        tag = " (stale)" if stale else "";
        print(f"{status}: {here.symbol} -> owner {owner}{tag}");
    }
}

with entry {
    file = ExecUnit(kind="file", identity="doc:pkg:Main@1", generation=1);

    _a = ExecUnit(kind="named", identity="sub:Main::_a@1", generation=1);
    _b = ExecUnit(kind="named", identity="sub:Main::_b@1", generation=1);
    anon = ExecUnit(kind="anonymous", identity="anon:Main#7@1", generation=1);
    begin = ExecUnit(kind="lifecycle", identity="phase:Main:BEGIN@1", generation=1);
    bad = ExecUnit(kind="unknown", identity="recovered:Main#12@1", generation=1, confidence="partial");

    other = ExecUnit(kind="file", identity="doc:pkg:Other@1", generation=1);
    other_anon = ExecUnit(kind="anonymous", identity="anon:Other#3@1", generation=1);

    root +>:Contains:+> file;
    file +>:Contains:+> _a;
    file +>:Contains:+> begin;
    file +>:Contains:+> anon;
    file +>:Contains:+> bad;
    file +>:Contains:+> Occurrence(symbol="toplevel_call", generation=1);
    _a +>:Contains:+> _b;                      # _a owns the _b call
    _b +>:Contains:+> _a;                      # mutual recursion: distinct owners
    anon +>:Contains:+> Occurrence(symbol="inner_call", generation=1);
    begin +>:Contains:+> Occurrence(symbol="init_call", generation=1);
    bad +>:Contains:+> Occurrence(symbol="recovered_call", generation=1);
    other +>:Contains:+> other_anon;
    other_anon +>:Contains:+> Occurrence(symbol="inner_call", generation=1);  # same spelling, distinct owner

    root spawn OwnerStacker(stale_gen=2);
}

"""Receiver-flow RCV-A: exact direct-assignment receiver transition at program points.

Bindings are nodes, direct `=` writes are typed Assignment edges to the exact
binding, and program points are chained in source order. A query walker walks
the point sequence, tracking the current receiver type of each binding exactly
at the dominating point — never from final whole-file state or traversal-order
last-writer wins. An inner same-named binding shadows the outer one inside its
scope block, and the outer binding is unchanged after the inner scope.
"""

node Binding {
    has name: str = "";
    has scope: str = "main";
}

node Scope {
    has name: str = "";
}

node ProgramPoint {
    has label: str = "";
    has binding_name: str = "";
    has scope: str = "main";
    has rhs_type: str = "";
    has generation: int = 1;
    has is_assignment: bool = False;
}

edge Next { }
edge DeclaredIn { }
edge Queries { }
edge Assignment { }

walker ReceiverQuery {
    has current: dict = {};
    has generation: int = 1;
    has visited: list = [];

    can start with Root entry {
        visit [->:Next:->];
    }

    can step with ProgramPoint entry {
        # cycle/recurrence protection: walkers do not dedupe visits themselves
        if here.label in self.visited {
            print(f"recurrence protection engaged at {here.label}");
            disengage;
        }
        self.visited.append(here.label);

        # apply only same-generation admitted direct assignments at this point
        if here.is_assignment and here.generation == self.generation {
            key = here.binding_name + "@" + here.scope;
            targets = [here->:Assignment:->];
            for b in targets {
                self.current[b.name + "@" + b.scope] = here.rhs_type;
            }
        }

        # shadowing: innermost scope wins over main for the same name
        inner_key = here.binding_name + "@" + here.scope;
        outer_key = here.binding_name + "@main";
        resolved = "Unknown";
        if inner_key in self.current.keys() {
            resolved = self.current[inner_key];
        } else if outer_key in self.current.keys() {
            resolved = self.current[outer_key];
        }
        print(f"point {here.label}: receiver is {resolved}");
        visit [->:Next:->] else { disengage; }
    }
}

with entry {
    main = Scope(name="main");
    inner = Scope(name="block");
    x_outer = Binding(name="$x", scope="main");
    x_inner = Binding(name="$x", scope="block");

    root +>:DeclaredIn:+> main;
    main +>:DeclaredIn:+> inner;
    main +>:DeclaredIn:+> x_outer;
    inner +>:DeclaredIn:+> x_inner;

    # canonical point sequence, source-ordered
    p1 = ProgramPoint(label="init", binding_name="$x", scope="main", rhs_type="Foo", is_assignment=True);
    p2 = ProgramPoint(label="call_foo_only", binding_name="$x", scope="main");
    p3 = ProgramPoint(label="reassign", binding_name="$x", scope="main", rhs_type="Bar", is_assignment=True);
    p4 = ProgramPoint(label="call_bar_only", binding_name="$x", scope="main");
    p5 = ProgramPoint(label="inner_shadow_init", binding_name="$x", scope="block", rhs_type="Baz", is_assignment=True);
    p6 = ProgramPoint(label="call_baz_only", binding_name="$x", scope="block");
    p7 = ProgramPoint(label="call_outer_again", binding_name="$x", scope="main");

    root ++> p1 ++> p2 ++> p3 ++> p4 ++> p5 ++> p6 ++> p7;

    p1 +>:Assignment:+> x_outer;
    p3 +>:Assignment:+> x_outer;
    p5 +>:Assignment:+> x_inner;

    for p in [p2, p4, p6, p7] {
        p +>:Queries:+> x_outer;
    }

    root spawn ReceiverQuery();
}

"""CompilerWorld demo: typed dependency graph with cycle-guarded invalidation.

Modules carry public/private interface state and staleness; compile-time
dependencies are typed DependsOn edges. One walker computes a deterministic
compile order (deepest dependencies first), another performs targeted
invalidation across the reverse-dependency closure with an explicit visited
guard (walkers have no built-in once-per-node visitation).
"""

node Module {
    has name: str = "";
    has version: str = "0";
    has is_public_interface: bool = True;
    has stale: bool = False;
    has compile_order: int = 0;
}

edge DependsOn {
    has conditional: bool = False;
}

walker CompileScheduler {
    has counter: int = 0;
    has visited: dict = {};

    can start with Root entry {
        visit [->:DependsOn:->] else { disengage; }
    }

    can schedule with Module entry {
        # Depth-first: emit dependencies before the dependent.
        if here.name in self.visited {
            disengage;
        }
        self.visited[here.name] = True;
        visit [->:DependsOn:->];
        self.counter += 1;
        here.compile_order = self.counter;
        label = "public" if here.is_public_interface else "private";
        print(f"compile #{here.compile_order}: {here.name} v{here.version} ({label})");
    }
}

walker Invalidator {
    has reason: str = "source change";
    has visited: dict = {};

    can start with Module entry {
        visit [<-:DependsOn:<-] else { disengage; }
    }

    can spread with Module entry {
        # Explicit cycle policy: guard by name on the reverse closure.
        if here.name in self.visited {
            disengage;
        }
        self.visited[here.name] = True;
        here.stale = True;
        print(f"invalidated {here.name}: {self.reason}");
        visit [<-:DependsOn:<-];
    }
}

with entry {
    util = Module(name="Utils", version="1.2");
    config = Module(name="Config", version="3.0");
    core = Module(name="Core", version="0.9", is_public_interface=False);
    app = Module(name="App", version="5.1");

    app +>:DependsOn:+> core;
    core +>:DependsOn:+> util;
    core +>:DependsOn:+> config;
    util +>:DependsOn:+> config;

    root ++> app;
    root spawn CompileScheduler();

    # Edit a leaf module and invalidate its reverse-dependency closure.
    util spawn Invalidator(reason="Utils.pm source edit");

    for m in [app, core, util, config] {
        status = "STALE" if m.stale else "current";
        print(f"{m.name}: {status}");
    }
}

"""Static agent-graph workflow: plan -> fan-out investigation -> synthesize -> write -> check -> bounded repair -> evidence gate.

Nodes are workflow phases, read-only investigators, and deterministic checks;
walkers play the agent roles. The graph topology is static (the model may not
rewrite it), the repair loop is host-bounded, and the final evidence gate
refuses completion without deterministic proof.
"""

node Phase {
    has name: str = "";
    has done: bool = False;
}

node Investigator {
    has label: str = "";
    has findings: str = "";
}

node CheckResult {
    has check_name: str = "";
    has passed: bool = False;
}

edge Next { }

walker Planner {
    can start with Root entry {
        print("Planner: fixed topology, no graph rewrites allowed");
        visit [->:Next:->];
    }

    can move_on with Phase entry {
        print(f"planned phase: {here.name}");
        visit [->:Next:->];
    }

    can fan_out with Investigator entry {
        print(f"investigator {here.label} reports: {here.findings}");
        visit [->:Next:->];
    }
}

walker Writer {
    has repair_budget: int = 2;
    has attempts: int = 0;

    can start with Root entry {
        visit [->:Next:->];
    }

    can write with Phase entry {
        if here.name == "write" {
            print("writer: applied change to canonical workspace");
        }
        if here.name == "gate" {
            print(f"evidence gate reached at {here.name}: checks and budgets satisfied");
            here.done = True;
            disengage;
        }
        visit [->:Next:->];
    }

    can gather with Investigator entry {
        print(f"writer ingests finding from {here.label}");
        visit [->:Next:->];
    }

    can run_check with CheckResult entry {
        if here.passed {
            print(f"check {here.check_name}: PASS, gate opens");
            visit [->:Next:->];
            disengage;
        }
        self.attempts += 1;
        if self.attempts > self.repair_budget {
            print(f"check {here.check_name}: FAIL — repair budget exhausted, disengaging");
            disengage;
        }
        print(f"check {here.check_name}: FAIL — repair attempt {self.attempts}/{self.repair_budget}");
        here.passed = True;
        visit [<--:Next:--];
    }
}

with entry {
    plan = Phase(name="plan");
    synth = Phase(name="synthesize");
    write = Phase(name="write");
    gate = Phase(name="gate");

    inv1 = Investigator(label="files", findings="parser.rs owns the loop");
    inv2 = Investigator(label="tests", findings="resume_test.rs covers --resume");

    chk_fail = CheckResult(check_name="cargo build", passed=False);

    root ++> plan;
    plan +>:Next:+> inv1;
    inv1 +>:Next:+> inv2;
    inv2 +>:Next:+> synth;
    synth +>:Next:+> write;
    write +>:Next:+> chk_fail;
    chk_fail +>:Next:+> gate;

    root spawn Planner();
    root spawn Writer(repair_budget=2);

    print(f"gate done: {gate.done}, writer repair attempts: bounded");
}

"""Topological sort of a dependency graph via Kahn's algorithm and DFS-based ordering."""

node Task {
    has name: str = "";
    has in_degree: int = 0;
    has visited: bool = False;
}

edge Prereq { }

walker KahnSort {
    has queue: list[Task] = list();
    has order: list[str] = list();
    has total: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can seed with Task entry {
        self.total += 1;
        for dep in [here -->] {
            dep.in_degree += 1;
        }
        visit [-->] else { disengage; }
    }

    can process with Task entry {
        # re-entrant ability: seed already computed in-degrees via a first pass
        if here.in_degree == 0 and here not in self.queue {
            self.queue.append(here);
        }
        if self.queue {
            ready = self.queue.pop(0);
            self.order.append(ready.name);
            for dep in [ready -->] {
                dep.in_degree -= 1;
                if dep.in_degree == 0 {
                    self.queue.append(dep);
                }
            }
            visit [-->] else {
                if len(self.order) < self.total {
                    print("CYCLE DETECTED — topological sort not possible");
                } else {
                    print(f"Kahn order: {self.order}");
                }
                disengage;
            }
        } else {
            print("CYCLE DETECTED — topological sort not possible");
            disengage;
        }
    }
}

walker DfsSort {
    has stack: list[str] = list();
    has order: list[str] = list();

    can start with Root entry {
        visit [-->];
    }

    can explore with Task entry {
        if not here.visited {
            here.visited = True;
            for dep in [here -->] {
                if not dep.visited {
                    dep.visited = True;
                    dep.explore_local(self);
                }
            }
            self.stack.append(here.name);
        }
        visit [-->] else {
            self.order = list(reversed(self.stack));
            print(f"DFS order: {self.order}");
            disengage;
        }
    }
}

impl Task.explore_local(w: DfsSort) {
    for dep in [here -->] {
        if not dep.visited {
            dep.visited = True;
            dep.explore_local(w);
        }
    }
    w.stack.append(here.name);
}

with entry {
    cs101 = Task(name="CS101");
    cs201 = Task(name="CS201");
    cs301 = Task(name="CS301");
    capstone = Task(name="Capstone");
    cs101 +>:Prereq:+> cs201;
    cs201 +>:Prereq:+> cs301;
    cs301 +>:Prereq:+> capstone;
    math = Task(name="LinearAlgebra");
    math +>:Prereq:+> cs301;
    root ++> cs101 ++> math;

    root spawn DfsSort();
}

"""Leave-namespace cascade: upfront validation across the whole subtree, then per-scope mutation.

Models the calimero leave_namespace cascade: gather descendant scopes where
the leaver holds a direct membership row, run last-admin checks for ALL of
them upfront (fail before any mutation), then mutate and notify per scope.
Cross-peer atomicity stays eventual-consistent by design (Option A); this
demo shows the single-peer atomic window.
"""

node Member {
    has name: str = "";
}

node Group {
    has name: str = "";
    has last_admin_ok: bool = True;

    def has_member(name: str) -> bool {
        for m in [self->:Membership:->] {
            if m.name == name {
                return True;
            }
        }
        return False;
    }

    def remove_member(name: str) -> bool {
        for m in [self->:Membership:->] {
            if m.name == name {
                self del ->:Membership:-> m;
                return True;
            }
        }
        return False;
    }
}

edge ChildOf {
    has depth: int = 0;
}

edge Membership {
    has is_admin: bool = False;
}

walker LeaveNamespace {
    has leaver: str = "";
    has scopes: list[Group] = [];
    has failed: bool = False;
    has notifications: list[str] = [];

    can start with Root entry {
        visit [->:ChildOf:->] else { disengage; }
    }

    can gather_and_validate with Group entry {
        # Phase 1: gather direct-row scopes across the subtree and validate
        # ALL of them upfront before any mutation.
        if here.has_member(self.leaver) {
            self.scopes.append(here);
            if here.last_admin_ok == False {
                self.failed = True;
            }
        }
        visit [->:ChildOf:->];
    }

    can mutate_scope with Group exit {
        if self.failed {
            print("ABORT: last-admin check failed in subtree; no rows removed");
            disengage;
        }
        if here in self.scopes {
            here.remove_member(self.leaver);
            self.notifications.append(f"MemberLeft notified for {here.name}");
        }
    }

    can report_done with Root exit {
        if self.failed == False {
            for note in self.notifications {
                print(note);
            }
        }
    }
}

with entry {
    alice = Member(name="Alice");
    bob = Member(name="Bob");
    carol = Member(name="Carol");
    root ++> alice;
    root ++> bob;
    root ++> carol;

    ns = Group(name="namespace");
    sub_a = Group(name="subgroup-a");
    sub_b = Group(name="subgroup-b", last_admin_ok=False);
    root +>:ChildOf(depth=0):+> ns;
    ns +>:ChildOf(depth=1):+> sub_a;
    ns +>:ChildOf(depth=1):+> sub_b;

    ns +>:Membership(is_admin=True):+> alice;
    ns +>:Membership:+> bob;
    sub_a +>:Membership:+> alice;
    sub_a +>:Membership:+> bob;
    sub_b +>:Membership:+> alice;
    sub_b +>:Membership(is_admin=True):+> carol;

    root spawn LeaveNamespace(leaver="Alice");
}

"""Project model: string-keyed relations become typed, source-anchored edges.

Files declare symbols (Declares), re-export sites point at their true origins
(Exports), module requests resolve (Resolves), and inheritance (Inherits) can
carry dynamic/unsupported links. An Auditor walks the whole graph with a
visited-guard; an MROChecker climbs inheritance chains with an explicit cycle
guard and depth cap — the semantics the issue says were hand-rolled.
"""

node Subject {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;

    def describe() -> str {
        return self.title;
    }
}

node File(Subject) {
    has path: str = "";
    has revision: str = "";

    override def describe() -> str {
        return f"{self.title}@{self.revision}";
    }
}

node Symbol(Subject) {
    has is_reexport: bool = False;

    override def describe() -> str {
        kind = "re-export site" if self.is_reexport else "definition";
        return f"{self.title} ({kind})";
    }
}

node Boundary(Subject) {
    has available: bool = False;

    override def describe() -> str {
        return f"dynamic boundary {self.title} (unavailable target)";
    }
}

edge Declares {
    has ordinal: int = 0;
}

edge Exports {
    has reexport: bool = False;
    has confidence: float = 1.0;
}

edge Inherits {
    has dynamic: bool = False;
}

edge Resolves { }

walker Auditor {
    has seen: list[str] = [];
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can audit with File | Symbol | Boundary entry {
        if here.title in self.seen {
            disengage;
        }
        self.seen.append(here.title);
        print(f"auditing {here.describe()}");
        if here is Boundary {
            self.findings.append(f"unresolved dynamic boundary: {here.title}");
        }
        visit [-->] else { disengage; }
    }
}

walker MROChecker {
    has chain: list[str] = [];
    has seen: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 8;

    can start with Symbol entry {
        self.climb();
    }

    def climb() {
        if here.title in self.seen {
            print(f"MRO cycle guard hit at {here.title}");
            report self.chain;
            disengage;
        }
        if self.depth > self.max_depth {
            print("MRO depth cap exceeded");
            report self.chain;
            disengage;
        }
        self.seen.append(here.title);
        self.chain.append(here.title);
        self.depth += 1;
        print(f"MRO: {here.title}");
        visit [->:Inherits:->] else {
            report self.chain;
            disengage;
        }
    }
}

with entry {
    # Source files with content revisions.
    util_file = File(title="util.jac", path="lib/util.jac", revision="gen-42");
    main_file = File(title="main.jac", path="app/main.jac", revision="gen-43");

    # Canonical subjects, not strings.
    origin = Symbol(title="make_cache");
    reexport_site = Symbol(title="make_cache_alias", is_reexport=True);
    base = Symbol(title="BaseCache");
    derived = Symbol(title="LruCache");
    dyn_parent = Symbol(title="DynamicParent");

    # Files declare subjects in source order.
    util_file +>:Declares(ordinal=0):+> origin;
    main_file +>:Declares(ordinal=1):+> base;

    # Re-export lineage: alias points at the origin, never the reverse.
    reexport_site +>:Exports(reexport=True, confidence=0.95):+> origin;

    # Module request resolution between files.
    main_file +>:Resolves:+> util_file;

    # Inheritance chain with a deliberate cycle through a dynamic link.
    derived +>:Inherits:+> base;
    base +>:Inherits(dynamic=True):+> dyn_parent;
    dyn_parent +>:Inherits:+> base;

    # Wire the demo graph and spawn the walkers.
    root ++> main_file ++> reexport_site ++> derived;
    root spawn Auditor();
    derived spawn MROChecker();
}

"""Lazy workspace instruction discovery: no eager full-tree walk on open.

open_workspace loads only root-level instruction files (AGENTS.md /
CLAUDE.md). Path-aware tools probe only the ancestors of their target
up to the workspace root, caching newly found instruction files so
they are never returned twice.
"""

node Workspace {
    has name: str = "";
}

node Directory {
    has name: str = "";
}

node File {
    has name: str = "";
    has is_instruction: bool = False;

    def instruction_label() -> str {
        return self.name;
    }
}

edge Contains { }
edge Root { }
edge Parent { }

walker WorkspaceOpener {
    has instructions: list[str] = list();

    can start with Root entry {
        visit [->:Root:->];
    }

    # Only root-level setup work: read instruction files at the root
    # and descend one level into the workspace — never the whole tree.
    can open with Workspace entry {
        print(f"open_workspace({here.name}) — bounded setup, no deep scan");
        visit [->:Contains:->];
    }

    can collect_root_instructions with Directory entry {
        visit [->:Contains:->];
    }

    can note_instruction with File entry {
        if here.is_instruction and here.instruction_label() not in self.instructions {
            self.instructions.append(here.instruction_label());
        }
    }
}

walker ToolTargetProbe {
    has instructions: list[str] = list();

    can start with Root entry {
        visit [->:Root:->];
    }

    # Emulates a path-aware tool: instead of scanning every descendant,
    # start at the target and inspect only its ancestors up to the root.
    can probe with Directory entry {
        print(f"tool targets directory {here.name}; probing ancestors");
        visit [<--:Parent:--];
    }

    can note_ancestor_instruction with File entry {
        if here.is_instruction and here.instruction_label() not in self.instructions {
            self.instructions.append(here.instruction_label());
            print(f"newly discovered instruction: {here.instruction_label()}");
        } else if here.is_instruction {
            print(f"cached, not repeated: {here.instruction_label()}");
        }
    }
}

with entry {
    ws = Workspace(name="devspace-root");
    root +>:Root:+> ws;

    # Two project subtrees under the root (a "large" collection).
    proj_a = Directory(name="project-a");
    proj_b = Directory(name="project-b");
    proj_a_src = Directory(name="src");
    ws +>:Contains:+> proj_a;
    ws +>:Contains:+> proj_b;
    proj_a +>:Contains:+> proj_a_src;

    # Instruction files: one at the root, one nested inside project-a/src.
    root_agents = File(name="AGENTS.md", is_instruction=True);
    ws +>:Contains:+> root_agents;
    nested_agents = File(name="CLAUDE.md", is_instruction=True);
    nested_agents +>:Parent:+> proj_a_src;

    # Bounded open: only root-level instructions are returned.
