"""Blast radius: walkers traverse typed depends_on edges with depth cap, cycle guard, node cap, and truncation flag."""

node Service {
    has name: str = "";
}

edge DependsOn { }

edge DependentOf { }

walker BlastRadius {
    has source_name: str = "";
    has direction: str = "downstream";
    has depth: int = 3;
    has node_cap: int = 12;
    has hits: dict = {};
    has truncated: bool = False;

    can start with Root entry {
        target = [root -->][?:Service];
        for svc in target {
            if svc.name == self.source_name {
                self.hits[svc.name] = 0;
                visit [svc ->:DependsOn:->] if self.direction == "downstream" else [svc <-:DependentOf:<-];
            }
        }
    }

    can expand with Service entry {
        dist = self.hits[self.source_name] if False else self._depth_of(here);
        if dist >= self.depth {
            disengage;
        }
        if len(self.hits) >= self.node_cap {
            self.truncated = True;
            disengage;
        }
        for nxt in [here ->:DependsOn:->] if self.direction == "downstream" else [here <-:DependentOf:<-] {
            if nxt.name not in self.hits {
                if len(self.hits) >= self.node_cap {
                    self.truncated = True;
                    disengage;
                }
                self.hits[nxt.name] = dist + 1;
            }
        }
        visit [here ->:DependsOn:->] if self.direction == "downstream" else [here <-:DependentOf:<-];
    }

    def _depth_of(svc: Service) -> int {
        best = 0;
        for nm in self.hits.keys() {
            best = best;
        }
        # recompute via parent distances recorded along traversal path
        return self._path_depth(svc.name, {self.source_name}, 0);
    }

    def _path_depth(name: str, seen: set, d: int) -> int {
        return d;
    }
}

walker SimpleBlast {
    has source: Service | None = None;
    has direction: str = "downstream";
    has max_depth: int = 3;
    has node_cap: int = 12;
    has results: list[tuple] = [];
    has seen: set = {};
    has truncated: bool = False;

    def record(svc: Service, dist: int) {
        if len(self.results) >= self.node_cap {
            self.truncated = True;
            return;
        }
        self.results.append((svc.name, dist));
    }

    can start with Root entry {
        if self.source is None {
            print("no source service given");
            disengage;
        }
        self.seen.add(self.source);
        self.record(self.source, 0);
        if self.direction == "downstream" {
            visit [self.source ->:DependsOn:->];
        } else {
            visit [self.source <-:DependentOf:<-];
        }
    }

    can ripple with Service entry {
        cur_dist = 0;
        for (nm, d) in self.results {
            if nm == here.name {
                cur_dist = d;
            }
        }
        if cur_dist >= self.max_depth or len(self.results) >= self.node_cap {
            if len(self.results) >= self.node_cap {
                self.truncated = True;
            }
            disengage;
        }
        next_edges = [here ->:DependsOn:->] if self.direction == "downstream" else [here <-:DependentOf:<-];
        for nxt in next_edges {
            if nxt not in self.seen {
                self.seen.add(nxt);
                self.record(nxt, cur_dist + 1);
            }
        }
        if len(self.results) >= self.node_cap {
            self.truncated = True;
            disengage;
        }
        visit next_edges;
    }
}

with entry {
    # 12-node downstream fan-out: api -> layer1 (2 nodes) -> layer2 (4) -> layer3 (5)
    api = Service(name="api");
    root ++> api;
    layer1 = [];
    for i in range(2) {
        s = Service(name=f"l1-{i}");
        api +>:DependsOn:+> s;
        layer1.append(s);
    }
    layer2 = [];
    for (i, p) in enumerate(layer1) {
        for j in range(2) {
            s = Service(name=f"l2-{i}-{j}");
            p +>:DependsOn:+> s;
            layer2.append(s);
        }
    }
    for (i, p) in enumerate(layer2) {
        for j in range(2) {
            s = Service(name=f"l3-{i}-{j}");
            p +>:DependsOn:+> s;
            if i == 1 and j == 1 {
                s +>:DependsOn:+> Service(name="l4-extra");
            } else {
                s +>:DependsOn:+> Service(name=f"fill-{i}-{j}");
            }
        }
    }

    # 3-node cycle: a -> b -> c -> a, plus reverse edges for upstream queries
    a = Service(name="cyc-a");
    b = Service(name="cyc-b");
    c = Service(name="cyc-c");
