"""Opt-in ontology layer over Collections: entities linked across documents.

Models the proposed corpus_entities/corpus_relations repos as a typed graph.
A walker performs cross-document entity linking with an explicit cycle guard
(jac walkers do not dedupe visits) and an adaptive-routing flag mirroring the
issue's LazyGraphRAG idea: only thematic/relational walks hit the graph.
"""

node Document {
    has title: str = "";
    has deleted: bool = False;
}

node Entity {
    has name: str = "";
    has kind: str = "";          # e.g. "company", "person"
    has resolved: bool = False;  # invalidation flag: re-extract when source changes
}

edge Mention {
    has source: str = "";        # "pdf" | "crm_row" | "contract"
}

edge RelatedTo {
    has relation: str = "";      # e.g. "subsidiary_of", "mentions"
}

walker EntityLinker {
    has target_name: str = "Acme";
    has found: list = [];        # list[Entity] linked to the target
    has visited: dict = {};      # explicit cycle guard (node.id -> True)

    can start with Root entry {
        visit [-->];
    }

    can find_seeds with Document entry {
        if here.deleted { disengage; }
        visit [->:Mention:->];
    }

    can seed with Entity entry {
        if here.name == self.target_name {
            here.resolved = True;
            self.found.append(here);
            self.visited[here.name + str(id(here))] = True;
        }
        visit [->:Mention:->];
    }

    can traverse with Entity entry {
        # Cycle policy: skip already-visited entities, explicit guard set.
        key = here.name + str(id(here));
        if key in self.visited { return; }
        self.visited[key] = True;
        if here.resolved is False and here.name == self.target_name {
            here.resolved = True;
            self.found.append(here);
        }
        visit [->:RelatedTo:->] else { disengage; }
    }

    can report with Root exit {
        print(f"cross-document links for '{self.target_name}': "
              f"{len(self.found)} entity instance(s)");
    }
}

walker GraphInvalidator {
    # Cascade invalidation: when a document changes, every entity it mentions
    # must be marked unresolved so the extraction pass re-runs.
    can start with Root entry {
        visit [-->];
    }

    can invalidate with Document entry {
        if here.deleted {
            visit [->:Mention:->] else { disengage; }
        }
    }

    can touch with Entity entry {
        here.resolved = False;
        print(f"invalidated entity '{here.name}' (re-extraction queued)");
        visit [->:Mention:->] else { disengage; }
    }
}

with entry {
    contract = Document(title="Acme master contract");
    crm = Document(title="crm_export.csv");
    acme_contract = Entity(name="Acme", kind="company");
    acme_crm = Entity(name="Acme", kind="company");
    acme_sub = Entity(name="AcmeEU", kind="company");

    contract +>:Mention(source="pdf"):+> acme_contract;
    crm +>:Mention(source="crm_row"):+> acme_crm;
    acme_sub +>:RelatedTo(relation="subsidiary_of"):+> acme_contract;
    acme_sub +>:RelatedTo(relation="mentions"):+> acme_crm;
    acme_contract +>:RelatedTo(relation="mentions"):+> acme_sub;  # cycle back

    root ++> contract ++> crm;

    root spawn EntityLinker(target_name="Acme");
    contract.deleted = True;
    root spawn GraphInvalidator();
}

