"""Blast radius: typed-edge walk with depth cap, cycle guard, node cap, truncation flag."""

node Service {
    has name: str = "";
}

edge DependsOn { }

edge DependentOf { }

walker BlastRadius {
    has direction: str = "downstream";
    has max_depth: int = 3;
    has node_cap: int = 12;
    has results: list[tuple] = [];
    has dist_map: dict = {};
    has seen: set = set();
    has truncated: bool = False;

    def record(svc: Service, dist: int) -> None {
        if len(self.results) >= self.node_cap {
            self.truncated = True;
            return;
        }
        self.results.append((svc.name, dist));
        self.dist_map[svc.name] = dist;
        self.seen.add(svc.name);
    }

    def next_of(svc: Service) -> list[Service] {
        if self.direction == "downstream" {
            return [svc ->:DependsOn:->];
        }
        return [svc <-:DependentOf:<-];
    }

    can start with Root entry {
        src = [root -->][0];
        self.record(src, 0);
        visit self.next_of(src);
    }

    can ripple with Service entry {
        if here.name not in self.dist_map {
            disengage;
        }
        cur_dist = self.dist_map[here.name];
        if len(self.results) >= self.node_cap {
            self.truncated = True;
            disengage;
        }
        if cur_dist >= self.max_depth {
            disengage;
        }
        frontier = [];
        for nxt in self.next_of(here) {
            if nxt.name not in self.seen {
                self.record(nxt, cur_dist + 1);
                if len(self.results) < self.node_cap {
                    frontier.append(nxt);
                } else {
                    self.truncated = True;
                }
            }
        }
        if len(frontier) == 0 {
            disengage;
        }
        visit frontier;
    }
}

