"""Shared immutable kinematic traversal for FK and obstacle query points.

One robot tree (Link nodes joined by Joint edges) is compiled once; two
walkers replay the same deterministic parent-to-child traversal without
rebuilding any topology: ForwardKinematics computes poses/twists, while
QueryPoints computes only the poses it needs plus query-point positions.
"""

node Link {
    has name: str = "";
    has fixed: bool = False;             # fixed base link receives no propagation
    has pose: float = 0.0;               # world-frame pose scalar (demo stand-in)
    has twist: float | None = None;      # only ForwardKinematics fills this
    has query_points: list[float] = [];  # local offsets for obstacle queries

    def joint_angle() -> float {
        joints = [here<-:Joint:-];
        if len(joints) > 0 {
            return joints[0].angle;
        }
        return 0.0;
    }

    def has_joint() -> bool {
        return len([here<-:Joint:-]) > 0;
    }
}

edge Joint {
    has axis: str = "";
    has angle: float = 0.0;              # selected joint configuration
}

walker CompileTraversal {
    """Validate root/parent structure once at construction time."""
    can start with Root entry {
        visit [-->];
    }

    can check with Link entry {
        children = [here-->];
        if len(children) > 0 and here.fixed {
            print(f"ERROR: fixed link {here.name} cannot have children");
            disengage;
        }
        visit [-->];
    }
}

walker ForwardKinematics {
    """Replays the shared traversal computing poses AND twists."""
    can start with Root entry {
        visit [-->];
    }

    can propagate with Link entry {
        if here.fixed {
            print(f"[base] {here.name} pose={here.pose} (fixed)");
        } else {
            delta = here.joint_angle();
            here.pose = here.pose + delta;
            here.twist = delta;
            print(f"[fk] {here.name} pose={here.pose} twist={here.twist}");
        }
        visit [-->];
    }
}

walker QueryPoints {
    """Obstacle-factor hot path: poses and query points only, no twists."""
    has jacobian: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can propagate with Link entry {
        if here.fixed {
            world = [q + here.pose for q in here.query_points];
        } else {
            offset = here.joint_angle();
            world = [q + here.pose + offset for q in here.query_points];
        }
        jac_tag = " +jac" if self.jacobian else "";
        print(f"[query{jac_tag}] {here.name} points={world}");
        visit [-->];
    }
}

with entry {
    # Compile the tree once: base -> upper -> lower, branched gripper.
    base = Link(name="base", fixed=True, pose=0.0);
    upper = Link(name="upper_arm", pose=0.0, query_points=[0.5, 1.0]);
    lower = Link(name="forearm", pose=0.0, query_points=[1.5]);
    gripper = Link(name="gripper", pose=0.0, query_points=[2.0]);

    root ++> base;
    base +>:Joint(axis="z", angle=0.3):+> upper;
    upper +>:Joint(axis="z", angle=0.6):+> lower;
    lower +>:Joint(axis="y", angle=0.1):+> gripper;

    # Structural validation is part of construction, not of evaluation.
    root spawn CompileTraversal();

    # Same immutable traversal replayed by two different clients.
    root spawn ForwardKinematics();
    root spawn QueryPoints(jacobian=True);
}

