"""Blast radius: typed-edge walk with depth cap, cycle guard, node cap, truncation flag."""

node Service {
    has name: str = "";
}

edge DependsOn { }

edge DependentOf { }

walker BlastRadius {
    has direction: str = "downstream";
    has max_depth: int = 3;
    has node_cap: int = 12;
    has results: list[tuple[str, int]] = [];
    has dist_map: dict[str, int] = {};
    has seen: set[str] = set();
    has truncated: bool = False;

    def record(svc: Service, dist: int) -> None {
        if len(self.results) >= self.node_cap {
            self.truncated = True;
            return;
        }
        self.results.append((svc.name, dist));
        self.dist_map[svc.name] = dist;
        self.seen.add(svc.name);
    }

    def next_of(svc: Service) -> list[Service] {
        neighbors: list[Service] = [];
        if self.direction == "downstream" {
            for n in [svc ->:DependsOn:->] {
                nxt: Service = n;
                neighbors.append(nxt);
            }
        } else {
            for n in [svc <-:DependentOf:<-] {
                prv: Service = n;
                neighbors.append(prv);
            }
        }
        return neighbors;
    }

    can start with Root entry {
        srcs = [root -->];
        if len(srcs) == 0 {
            disengage;
        }
        src: Service = srcs[0];
        self.record(src, 0);
        frontier: list[Service] = [];
        for n in self.next_of(src) {
            if n.name not in self.seen {
                self.record(n, 1);
                frontier.append(n);
            }
        }
        if len(frontier) == 0 {
            disengage;
        }
        visit frontier;
    }

    can ripple with Service entry {
        if here.name not in self.dist_map {
            disengage;
        }
        cur_dist: int = self.dist_map[here.name];
        if cur_dist >= self.max_depth {
            disengage;
        }
        frontier: list[Service] = [];
        for n in self.next_of(here) {
            if n.name not in self.seen {
                if len(self.results) >= self.node_cap {
                    self.truncated = True;
                    continue;
                }
                self.record(n, cur_dist + 1);
                frontier.append(n);
            }
        }
        if len(frontier) == 0 {
            disengage;
        }
        visit frontier;
    }
}

with entry {
    # 12-node downstream fan-out from api: depth 3, capped at 12
    api = Service(name="api");
    root ++> api;
    layer1 = [];
    for i in range(2) {
        s = Service(name=f"l1-{i}");
        api +>:DependsOn:+> s;
        layer1.append(s);
    }
    layer2 = [];
    for (i, p) in enumerate(layer1) {
        for j in range(2) {
            s = Service(name=f"l2-{i}-{j}");
            p +>:DependsOn:+> s;
            layer2.append(s);
        }
    }
    for (i, p) in enumerate(layer2) {
        for j in range(2) {
            s = Service(name=f"l3-{i}-{j}");
            p +>:DependsOn:+> s;
        }
    }

    # 3-node cycle: a -> b -> c -> a (guard must terminate the walk)
    a = Service(name="cyc-a");
    b = Service(name="cyc-b");
    c = Service(name="cyc-c");
    a +>:DependsOn:+> b;
    b +>:DependsOn:+> c;
    c +>:DependsOn:+> a;
    a +>:DependentOf:+> b;

    downstream = BlastRadius(max_depth=3, node_cap=12);
    api spawn downstream;
    names = sorted([nm for (nm, d) in downstream.results]);
    print(f"downstream of api ({len(names)} nodes, truncated={downstream.truncated}): {names}");

    cyclic = BlastRadius(max_depth=6, node_cap=50);
    a spawn cyclic;
    print(f"cycle walk terminated: {sorted([nm for (nm, d) in cyclic.results])}");

    upstream = BlastRadius(direction="upstream", max_depth=3, node_cap=50);
    a spawn upstream;
    print(f"upstream of cyc-a: {sorted([nm for (nm, d) in upstream.results])}");
}

"""Category tree descendant finder: edges replace the N+1 parent_id scan."""

