"""Bounded extraction over an attacker-supplied action graph.

Models the deputy issue: composite actions reference shared manifests and
naive re-parsing gives fanout^depth work. The idiomatic walker memoizes
per node (visited set), carries a global work budget, a depth cap, and
stops with a partial result instead of running unbounded.
"""

node Workflow {
    has name: str = "";
    has steps: int = 0;
}

node ActionManifest {
    has name: str = "";
    has steps: int = 0;
}

edge References { }

walker Extractor {
    has visited: dict = {};
    has work_budget: int = 10;
    has work_done: int = 0;
    has max_depth: int = 8;
    has warned: bool = False;

    def too_much_work() -> bool {
        return self.work_done >= self.work_budget;
    }

    def claim(node_name: str) -> bool {
        if node_name in self.visited {
            return False;
        }
        self.visited[node_name] = True;
        return True;
    }

    can start with Root entry {
        visit [->:References:->];
    }

    can parse_workflow with Workflow entry {
        if self.too_much_work() {
            if not self.warned {
                print("WARNING: work budget exhausted, returning partial result");
                self.warned = True;
            }
            disengage;
        }
        if self.claim(here.name) {
            self.work_done += 1;
            print(f"parsed workflow {here.name} ({here.steps} steps)");
            visit [->:References:->];
        }
    }

    can parse_manifest with ActionManifest entry {
        if self.too_much_work() {
            if not self.warned {
                print("WARNING: work budget exhausted, returning partial result");
                self.warned = True;
            }
            disengage;
        }
        # Memoization: shared manifests are parsed once, regardless of
        # how many steps reference them.
        if self.claim(here.name) {
            self.work_done += 1;
            print(f"parsed action manifest {here.name} ({here.steps} steps)");
            visit [->:References:->];
        } else {
            print(f"skipped {here.name} (already visited)");
        }
    }
}

with entry {
    # Shared leaves: referenced by many steps, must parse exactly once.
    shared_a = ActionManifest(name="actions/checkout", steps=2);
    shared_b = ActionManifest(name="actions/setup-node", steps=3);

    # A depth-3 chain whose every level references both shared manifests
    # plus the next level: exponential if un-memoized, linear here.
    w = Workflow(name="ci.yml", steps=3);
    root ++> w;
    top = ActionManifest(name="composite-top", steps=3);
    w +>:References:+> top;
    mid = ActionManifest(name="composite-mid", steps=3);
    top +>:References:+> mid;
    leaf = ActionManifest(name="composite-leaf", steps=2);
    mid +>:References:+> leaf;
    for level in [top, mid, leaf] {
        level +>:References:+> shared_a;
        level +>:References:+> shared_b;
    }

    root spawn Extractor(work_budget=10);
    print(f"extraction visited {len(Extractor.visited)} resources, work={Extractor.work_done}");
}

"""Beads-style tree renderer with an explicit visited set so a single
dependency cycle (epic blocked by its own child) renders as a marked leaf
instead of recursing without bound."""

node Issue {
    has title: str = "";
    has status: str = "open";
}

edge ParentChild { }
edge Blocks { }

walker TreeRenderer {
    has visited: dict = {};
    has depth: int = 0;
    has max_depth: int = 64;

    can start with Root entry {
        visit [->:ParentChild:->] | [->:Blocks:->];
    }

    can render with Issue entry {
        if here in self.visited {
            print(f"{'  ' * self.depth}↺ {here.title} (already rendered)");
            visit [-->] else { disengage; }
            return;
        }
        if self.depth > self.max_depth {
            print(f"{'  ' * self.depth}! depth cap hit at {here.title}");
            disengage;
        }
        marker = "open" if here.status == "open" else "done";
        print(f"{'  ' * self.depth}- {here.title} [{marker}]");
        self.visited[here] = True;
        child_depth = self.depth + 1;
        sub = TreeRenderer(visited=self.visited, depth=child_depth, max_depth=self.max_depth);
        here spawn sub;
        visit [-->] else { disengage; }
    }
}

walker CycleAuditor {
    has seen: dict = {};
    has found_cycle: bool = False;

    can start with Root entry {
        visit [-->];
    }

