"""Tag catalog with materialised-path hierarchy: tags are nodes linked by
AncestorOf edges, files get exactly one TaggedWith edge per applied leaf,
and a walker cascades subtree renames down the hierarchy."""

node Tag {
    has name: str = "";
    has name_fold: str = "";
    has depth: int = 0;

    def is_ancestor_of(other: Tag) -> bool {
        return other.name_fold.startswith(self.name_fold + "/") or other.name_fold == self.name_fold;
    }
}

node File {
    has path: str = "";
}

edge AncestorOf {
    # child Tag -> parent Tag
}

edge TaggedWith {
    # File -> leaf Tag only; ancestors matched by prefix at query time
}

def normalize(raw: str) -> str | None {
    if raw.startswith("/") or raw.endswith("/") {
        return None;
    }
    segs = raw.split("/");
    out = [];
    for seg in segs {
        trimmed = seg.strip();
        collapsed = " ".join(trimmed.split());
        if collapsed == "" {
            return None;
        }
        for ch in collapsed {
            if ord(ch) < 32 {
                return None;
            }
        }
        if len(collapsed) > 64 {
            return None;
        }
        out.append(collapsed);
    }
    if len(out) > 6 {
        return None;
    }
    full = "/".join(out);
    if len(full) > 255 {
        return None;
    }
    return full;
}

walker Cataloguer {
    has created: list[str] = list();

    def ensure_path(here_root: Tag, full: str) -> Tag | None {
        norm = normalize(full);
        if norm is None {
            return None;
        }
        segs = norm.split("/");
        cur = here_root;
        for i in range(len(segs)) {
            path = "/".join(segs[: i + 1]);
            found: Tag | None = None;
            for t in [cur->:AncestorOf:->] {
                if t.name_fold == path.lower() {
                    found = t;
                    break;
                }
            }
            if found is None {
                found = Tag(name=path, name_fold=path.lower(), depth=i + 1);
                cur +>:AncestorOf:+> found;
                self.created.append(path);
            }
            cur = found;
        }
        return cur;
    }

    can build with Root entry {
        trips = self.ensure_path(here_root=root, full="Trips/Iceland/Reykjavik");
        self.ensure_path(here_root=root, full="Trips/Iceland");
        cam = self.ensure_path(here_root=root, full="Camera/RAW");
        if trips is None or cam is None {
            disengage;
        }
        f1 = File(path="a.jpg");
        f2 = File(path="b.jpg");
        root ++> f1 ++> f2;
        # applying a leaf attaches ONLY the leaf, not its ancestors
        f1 +>:TaggedWith:+> trips;
        f1 +>:TaggedWith:+> cam;
        f2 +>:TaggedWith:+> cam;
        visit [-->];
    }

    can count_files with Tag entry {
        n = 0;
        for f in [<-:TaggedWith:-] {
            n += 1;
        }
        desc = 0;
        for d in [->:AncestorOf:->] {
            for f in [d<-:TaggedWith:-] {
                desc += 1;
            }
        }
        print(f"tag {here.name}: count={n} descendant_count={desc}");
        visit [->:AncestorOf:->];
    }
}

walker SubtreeRenamer {
    has old_fold: str = "";
    has new_name: str = "";
    has renamed: int = 0;

    can start with Tag entry {
        if here.name_fold == self.old_fold {
            here.name = self.new_name;
            here.name_fold = self.new_name.lower();
            self.renamed += 1;
        } elif here.name_fold.startswith(self.old_fold + "/") {
            suffix = here.name_fold[len(self.old_fold) + 1 :];
            here.name = self.new_name + "/" + suffix;
            here.name_fold = here.name.lower();
            self.renamed += 1;
        } else {
            disengage;
        }
        visit [->:AncestorOf:->];
    }
}

