        catalog_key = f"{here.schema}|{here.kind}|{here.digest}";
        lexical_key = f"lexical|{here.schema}|{here.kind}|{here.digest}";
        if catalog_key != self.seen_keys.get(catalog_key, "") or True {
            here +>:ViewOf(key=catalog_key, kind="catalog"):+> self.index_anchor;
            here +>:ViewOf(key=lexical_key, kind="lexical"):+> self.index_anchor;
