"""Tag catalog: materialised-path tags as nodes, AncestorOf edges for the
hierarchy, TaggedWith edges from files to applied leaf tags only, and a
walker that cascades a subtree rename down the AncestorOf edges."""

node Tag {
    has name: str = "";
    has name_fold: str = "";
    has depth: int = 0;
    has uses: int = 0;
}

node File {
    has path: str = "";
}

edge AncestorOf {
    # child Tag -> parent Tag
}

edge TaggedWith {
    # File -> applied leaf Tag; ancestors matched by prefix at query time
}

edge InCatalog {
    # root -> every tag row, so the catalog is enumerable
}

def normalize(raw: str) -> str | None {
    if raw.startswith("/") or raw.endswith("/") {
        return None;
    }
    segs = raw.split("/");
    out = list();
    for seg in segs {
        trimmed = seg.strip();
        collapsed = " ".join(trimmed.split());
        if collapsed == "" {
            return None;
        }
        for ch in collapsed {
            if ord(ch) < 32 {
                return None;
            }
        }
        if len(collapsed) > 64 {
            return None;
        }
        out.append(collapsed);
    }
    if len(out) > 6 {
        return None;
    }
    full = "/".join(out);
    if len(full) > 255 {
        return None;
    }
    return full;
}

walker Cataloguer {
    has created: list[str] = list();
    has known: list[Tag] = list();
    has trips_ref: Tag | None = None;

    def lookup(fold: str) -> Tag | None {
        for t in self.known {
            if t.name_fold == fold {
                return t;
            }
        }
        return None;
    }

    def ensure_path(base: Tag, full: str) -> Tag | None {
        norm = normalize(full);
        if norm is None {
            print(f"rejected invalid tag name: {full}");
            return None;
        }
        segs = norm.split("/");
        cur = base;
        for i in range(len(segs)) {
            path = "/".join(segs[: i + 1]);
            fold = path.lower();
            found = self.lookup(fold);
            if found is None {
                found = Tag(name=path, name_fold=fold, depth=i + 1);
                cur +>:AncestorOf:+> found;
                root +>:InCatalog:+> found;
                self.known.append(found);
                self.created.append(path);
            }
            cur = found;
        }
        return cur;
    }

    can build with Root entry {
        trips = self.ensure_path(here, "Trips/Iceland/Reykjavik");
        self.ensure_path(here, "Trips/Iceland");
        cam = self.ensure_path(here, "Camera/RAW");
        if trips is None or cam is None {
            disengage;
        }
        self.trips_ref = trips;
        f1 = File(path="a.jpg");
        f2 = File(path="b.jpg");
        root ++> f1 ++> f2;
        # applying a leaf attaches ONLY the leaf, never its ancestors
        f1 +>:TaggedWith:+> trips;
        f1 +>:TaggedWith:+> cam;
        f2 +>:TaggedWith:+> cam;
        trips.uses += 1;
        cam.uses += 2;
        for name in self.created {
            print(f"created tag: {name}");
        }
        visit [->:InCatalog:->];
    }

    can tally with Tag entry {
        print(f"tag {here.name}: count={here.uses}");
    }
}

walker SubtreeRenamer {
    has old_fold: str = "";
    has new_name: str = "";
    has renamed: int = 0;

    can start with Root entry {
        visit [->:InCatalog:->];
    }

    can rename with Tag entry {
        if here.name_fold == self.old_fold {
            here.name = self.new_name;
            here.name_fold = self.new_name.lower();
            self.renamed += 1;
            print(f"renamed subtree root to {here.name}");
            visit [->:AncestorOf:->];
        } elif here.name_fold.startswith(self.old_fold + "/") {
            suffix = here.name_fold[len(self.old_fold) + 1 :];
            here.name = self.new_name + "/" + suffix;
            here.name_fold = here.name.lower();
            self.renamed += 1;
            print(f"renamed descendant to {here.name}");
            visit [->:AncestorOf:->];
        } else {
            disengage;
        }
    }
}

with entry {
    cat = Cataloguer();
    root spawn cat;
    renamer = SubtreeRenamer(old_fold="trips/iceland", new_name="Trips/Norway");
    root spawn renamer;
    print(f"subtree rename touched {renamer.renamed} nodes");
}

"""Service dependency graph: blast radius and upstream impact analysis.

Dependency edges carry source, confidence, and evidence; each node mirrors
its weakest inbound dependency confidence for auditability. An ImpactTracer
walker traverses dependency edges backwards from a failed CI, computing
blast radius with an explicit cycle guard (visit has no dedupe) and
prioritizing business services by criticality. A GraphAuditor validates
confidence and detects cycles/low-confidence edges.
"""

node CIBase {
    has name: str = "";
    has criticality: int = 1;
    has stale: bool = False;
    has min_dep_confidence: float = 1.0;
    has low_conf_deps: int = 0;

    def impact_priority() -> int {
        return self.criticality;
    }
}

node ServiceCI(CIBase) {
    has kind: str = "service";          # service | workload | data | external
    override def impact_priority() -> int {
        return self.criticality * 10;
    }
}

node BusinessCI(CIBase) {
    has tier: str = "bronze";           # gold | silver | bronze
    override def impact_priority() -> int {
        boosted = self.criticality * 20;
        return boosted if self.tier == "gold" else self.criticality * 10;
    }
}

edge DependsOn {
    has source: str = "";               # telemetry | annotation | declared
    has confidence: float = 0.0;
    has evidence: str = "";
}

# helper: connect with normalization of confidence bookkeeping
def wire(src: CIBase, dst: CIBase, dep_source: str, confidence: float, evidence: str) {
    src +>:DependsOn(source=dep_source, confidence=confidence, evidence=evidence):+> dst;
    if confidence < dst.min_dep_confidence {
        dst.min_dep_confidence = confidence;
    }
    if confidence < 0.5 {
        dst.low_conf_deps += 1;
    }
}

walker ImpactTracer {
    has correlation_id: str = "";
    has visited: dict[str, bool] = dict();
    has blast_radius: int = 0;
    has paths: list[str] = list();

    # one union ability handles any CI type; failure propagates backwards
    can trace with ServiceCI | BusinessCI entry {
        if here.name in self.visited.keys() {
            print(f"[cycle guard] {here.name} already assessed, stopping");
            disengage;
        }
        self.visited[here.name] = True;
        status = "STALE" if here.stale else "OK";
        pri = here.impact_priority();
        print(f"[{self.correlation_id}] impact: {here.name} "
              f"priority={pri} min_confidence={here.min_dep_confidence} "
              f"health={status}");
        self.blast_radius += 1;
        self.paths.append(here.name);
        visit [<--:DependsOn:--] else { disengage; }
    }
}

walker GraphAuditor {
    has visited: dict[str, bool] = dict();
    has cycles: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with ServiceCI | BusinessCI entry {
        if here.name in self.visited.keys() {
            self.cycles += 1;
            print(f"[audit] cycle/conflict detected at {here.name}");
            disengage;
        }
        self.visited[here.name] = True;
        if here.low_conf_deps > 0 {
            print(f"[audit] {here.name}: {here.low_conf_deps} low-confidence "
                  f"deps, marking topology unsafe for automation");
        } else {
            print(f"[audit] {here.name}: dependencies healthy "
                  f"(min_confidence={here.min_dep_confidence})");
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    # end-to-end: business svc -> frontend -> backend -> DB, plus external API
    orders = BusinessCI(name="Orders", tier="gold", criticality=5);
    web = ServiceCI(name="web-frontend", criticality=3);
    api = ServiceCI(name="orders-api", criticality=4);
    db = ServiceCI(name="pg-main", kind="data", criticality=5);
    ext = ServiceCI(name="payments-external", kind="external", criticality=2, stale=True);

    root ++> orders;
    wire(orders, web, "annotation", 0.9, "label app=orders");
    wire(web, api, "telemetry", 0.98, "istio mesh trace");
    wire(api, db, "telemetry", 0.95, "sql driver span");
    wire(api, ext, "telemetry", 0.4, "stale dns log");

    print("--- audit pass: confidence and cycle validation ---");
    root spawn GraphAuditor();

    print("--- failure injected: pg-main down ---");
    tracer = ImpactTracer(correlation_id="INC-108-001");
    db spawn tracer;
    print(f"blast radius of pg-main failure: {tracer.blast_radius} "
          f"CIs impacted, path={tracer.paths}");
}

