"""Effect-completeness validation via reviewed `invokes` reachability.

Walks typed Invokes edges from a caller, unions callee effects into the
caller's reviewed-reachable set, records a canonical invocation witness per
effect, propagates `effects unknown` conservatively, and terminates on
self/mutual recursion via an explicit visited guard.
"""

node Fn {
    has name: str = "";
    has effects: list[str] = [];
    has complete: bool = False;
    has unknown: bool = False;
    has forbidden: list[str] = [];
}

edge Invokes { }

walker EffectAudit {
    has path: list[str] = [];
    has reachable: dict = {};
    has visited: list[str] = [];
    has unknown_reached: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can trace with Fn entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        for eff in here.effects {
            if eff not in self.reachable {
                self.reachable[eff] = " -> ".join(self.path + [here.name]);
            }
        }
        if here.unknown {
            self.unknown_reached = True;
        }
        self.path.append(here.name);
        visit [->:Invokes:->] else { disengage; }
        self.path.pop();
    }
}

with entry {
    fs = Fn(name="fs.write", effects=["io", "net"]);
    db = Fn(name="db.log", effects=["log"]);
    mystery = Fn(name="legacy.plugin", effects=[], unknown=True);

    # Diamond: two paths to fs.write plus an unknown callee.
    wrapper = Fn(name="app.wrapper", effects=["log"]);
    wrapper +>:Invokes:+> fs;
    wrapper +>:Invokes:+> db;
    wrapper +>:Invokes:+> mystery;

    # Self-recursion: must terminate.
    main = Fn(name="app.main", effects=["log"], complete=True, forbidden=["net"]);
    main +>:Invokes:+> main;
    main +>:Invokes:+> wrapper;

    root ++> main;

    audit = EffectAudit();
    root spawn audit;

    print(f"caller {main.name} declares complete={main.complete}");
    for (eff, witness) in audit.reachable.items() {
        print(f"  reachable effect '{eff}' via {witness}");
    }
    if audit.unknown_reached {
        print("  UNKNOWN reachable: caller cannot truthfully pass as effects complete");
    }
    missing = [e for e in audit.reachable if e not in main.effects];
    for eff in missing {
        print(f"  MISSING '{eff}' in complete summary (witness: {audit.reachable[eff]})");
    }
    for eff in main.forbidden {
        if eff in audit.reachable {
            print(f"  FORBIDDEN '{eff}' reached behind wrapper (witness: {audit.reachable[eff]}) — violation persists");
        }
    }
    verdict = "FAIL" if (missing or audit.unknown_reached) else "PASS";
    print(f"completeness check for {main.name}: {verdict}");
}

"""Tag catalog: materialised-path tags as nodes, AncestorOf edges for the
hierarchy, TaggedWith edges from files to applied leaf tags only, and a
walker that cascades a subtree rename down the AncestorOf edges."""

node Tag {
    has name: str = "";
    has name_fold: str = "";
    has depth: int = 0;
    has uses: int = 0;
}

node File {
    has path: str = "";
}

edge AncestorOf {
    # child Tag -> parent Tag
}

edge TaggedWith {
    # File -> applied leaf Tag; ancestors matched by prefix at query time
}

edge InCatalog {
    # root -> every tag row, so the catalog is enumerable
}

def normalize(raw: str) -> str | None {
    if raw.startswith("/") or raw.endswith("/") {
        return None;
    }
    segs = raw.split("/");
    out = list();
    for seg in segs {
        trimmed = seg.strip();
        collapsed = " ".join(trimmed.split());
        if collapsed == "" {
            return None;
        }
        for ch in collapsed {
            if ord(ch) < 32 {
                return None;
            }
        }
        if len(collapsed) > 64 {
            return None;
        }
        out.append(collapsed);
    }
    if len(out) > 6 {
        return None;
    }
    full = "/".join(out);
    if len(full) > 255 {
        return None;
    }
    return full;
}

walker Cataloguer {
    has created: list[str] = list();
    has known: list[Tag] = list();

    def lookup(fold: str) -> Tag | None {
        for t in self.known {
            if t.name_fold == fold {
                return t;
            }
        }
        return None;
    }

    def ensure_path(full: str) -> Tag | None {
        norm = normalize(full);
        if norm is None {
            print(f"rejected invalid tag name: {full}");
            return None;
        }
        segs = norm.split("/");
        cur_root = True;
        cur = Tag();
        result = Tag();
        for i in range(len(segs)) {
            path = "/".join(segs[: i + 1]);
            fold = path.lower();
            found = self.lookup(fold);
            if found is None {
                found = Tag(name=path, name_fold=fold, depth=i + 1);
                if cur_root {
                    root +>:InCatalog:+> found;
                } else {
                    cur +>:AncestorOf:+> found;
                    root +>:InCatalog:+> found;
                }
                self.known.append(found);
                self.created.append(path);
            }
            cur = found;
            cur_root = False;
            if i == len(segs) - 1 {
                result = found;
            }
        }
        return result;
    }

    can build with Root entry {
        trips = self.ensure_path("Trips/Iceland/Reykjavik");
        self.ensure_path("Trips/Iceland");
        cam = self.ensure_path("Camera/RAW");
        if trips is None or cam is None {
            disengage;
        }
        f1 = File(path="a.jpg");
        f2 = File(path="b.jpg");
        root ++> f1 ++> f2;
        # applying a leaf attaches ONLY the leaf, never its ancestors
        f1 +>:TaggedWith:+> trips;
        f1 +>:TaggedWith:+> cam;
        f2 +>:TaggedWith:+> cam;
        trips.uses += 1;
        cam.uses += 2;
        for name in self.created {
            print(f"created tag: {name}");
        }
        visit [->:InCatalog:->];
    }

    can tally with Tag entry {
        print(f"tag {here.name}: count={here.uses}");
    }
}

walker SubtreeRenamer {
    has old_fold: str = "";
    has new_name: str = "";
    has renamed: int = 0;

    can start with Root entry {
        visit [->:InCatalog:->];
    }

    can rename with Tag entry {
        if here.name_fold == self.old_fold {
            here.name = self.new_name;
            here.name_fold = self.new_name.lower();
            self.renamed += 1;
            print(f"renamed subtree root to {here.name}");
            visit [->:AncestorOf:->];
        } elif here.name_fold.startswith(self.old_fold + "/") {
            suffix = here.name_fold[len(self.old_fold) + 1 :];
            here.name = self.new_name + "/" + suffix;
            here.name_fold = here.name.lower();
            self.renamed += 1;
            print(f"renamed descendant to {here.name}");
            visit [->:AncestorOf:->];
        } else {
            disengage;
        }
    }
}

with entry {
    cat = Cataloguer();
    root spawn cat;
    renamer = SubtreeRenamer(old_fold="trips/iceland", new_name="Trips/Norway");
    root spawn renamer;
    print(f"subtree rename touched {renamer.renamed} nodes");
}

"""Snapshot-bound multi-view query index over verified committed artifacts."""

node ArtifactRef {
    has schema: str = "";
    has kind: str = "";
    has digest: str = "";
    has identity: str = "";

    def view_key(view_version: str, view_kind: str, cfg: str) -> str {
        return f"{view_kind}|{view_version}|{self.identity}|{self.schema}/{self.kind}/{self.digest}|cfg={cfg}";
    }
}

node Snapshot {
    has identity: str = "";
    has status: str = "completed";
    has view_version: str = "v1";
    has config_digest: str = "";

    def admissible() -> bool {
        return self.status == "completed";
    }
}

node ViewKey {
    has key: str = "";
    has kind: str = "";
}

edge Contains {
}

edge ViewOf {
}

walker SnapshotCatalog {
    has admitted: int = 0;
    has materialized: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can audit with Snapshot entry {
        # A08 authority: only fully validated completed snapshots are admitted.
        if here.admissible() {
            self.admitted += 1;
            print(f"admitted snapshot {here.identity}");
            visit [->:Contains:->];
        } else {
            print(f"excluded publication {here.identity} (status={here.status})");
        }
    }

    can verify with ArtifactRef entry {
        # Re-verify committed evidence, then materialize deterministic keyed views.
        for vk in ["catalog", "lexical"] {
            k = here.view_key("v1", vk, "cfg-a");
            anchor = ViewKey(key=k, kind=vk);
            here +>:ViewOf:+> anchor;
            self.materialized += 1;
        }
        print(f"reverified artifact {here.kind}:{here.digest}, views materialized");
    }
}

walker QueryIndex {
    has intent: str = "catalog";
    has answers: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can answer with ArtifactRef entry {
        # Cache entries are disposable hints; evidence was reverified before use.
        hits = 0;
        for target in [here->:ViewOf:->] {
            if target.kind == self.intent {
                hits += 1;
                print(f"intent={self.intent} cache-hit key={target.key}");
            }
        }
        if hits == 0 {
            print(f"intent={self.intent} rebuild required for {here.digest}");
        } else {
            self.answers += 1;
        }
    }
}

