}

"""Governed Neptune graph-query evidence: a Mission walks a provider's scoped,
bounded query results, classifying evidence status while never exposing raw
node properties (digest-only projections)."""

node Mission {
    has mission_id: str = "";
    has revision_digest: str = "";
}

node Provider {
    has provider_name: str = "";
    has registration_digest: str = "";
    has revoked: bool = False;
}

node QueryResult {
    has status: str = "PRESENT";  # PRESENT|EMPTY|PARTIAL|TIMEOUT|ACCESS_LOST|TAMPERED|REVOKED
    has node_count: int = 0;
    has edge_count: int = 0;
    has result_digest: str = "";
    has row_cap: int = 1000;
    has elapsed_ms: int = 0;
    has time_cap_ms: int = 5000;
    has digest_verified: bool = True;
}

edge ScopedQuery {
    has query_template_digest: str = "";
    has parameter_digest: str = "";
    has permission_scope: str = "read-only";
}

edge EvidenceProposal { }

walker GovernedQueryAuditor {
    has mission_revision: str = "";
    has visited: dict = {};
    has proposals: list = [];
    has failures: int = 0;

    can start with Root entry {
        self.visited = {};
        visit [->:ScopedQuery:->] else { disengage; }
    }

    # Cycle guard is explicit: jac walkers have no once-per-node visitation,
    # so a revocation loop must not hang the audit.
    can audit_provider with Provider entry {
        if here in self.visited {
            print(f"[CYCLE] provider {here.provider_name} already audited; disengaging");
            disengage;
        }
        self.visited[here] = True;
        if here.revoked {
            status = "REVOKED";
            print(f"[{status}] provider {here.provider_name} registration lost; fail-closed");
            self.failures += 1;
            disengage;
        }
        print(f"[AUDIT] provider {here.provider_name} reg-digest {here.registration_digest}");
        visit [->:EvidenceProposal:->];
    }

    can classify with QueryResult entry {
        verdict = "OK";
        if not here.digest_verified {
            verdict = "TAMPERED";
        } else if here.elapsed_ms > here.time_cap_ms {
            verdict = "TIMEOUT";
        } else if here.node_count > here.row_cap {
            verdict = "PARTIAL";
        } else if here.node_count == 0 {
            verdict = "EMPTY";
        }
        # Digest-only projection: raw identifiers and properties stay redacted.
        projection = f"{verdict}:nodes={here.node_count}:edges={here.edge_count}:digest={here.result_digest[:8]}";
        if verdict in {"TAMPERED", "TIMEOUT"} {
            self.failures += 1;
        }
        self.proposals.append(projection);
        print(f"[EVIDENCE] {projection} (raw payloads redacted)");
    }
}

