"""SQL parser demo: WITH queries produce a CTE AST and a resolver walker
traverses CTE definitions plus the final SELECT to hardcode column ordinals."""

node SqlSelect {
    has label: str = "";
    has is_final: bool = False;
    has referenced_cte: str = "";
}

node CteDefinition {
    has name: str = "";
    has recursive: bool = False;
}

edge DefinesCte {
    has syntax_ok: bool = True;
}

edge ResolvesFrom {
    has via: str = "cte_body";
}

walker Parser {
    has cte_names: list[str] = [];
    has ordinals: dict[str, int] = {};

    can start with Root entry {
        visit [->:DefinesCte:->];
    }

    can parse_cte with CteDefinition entry {
        print(f"parsed CTE {here.name} (recursive={here.recursive})");
        self.cte_names.append(here.name);
        visit [->:ResolvesFrom:->] else { visit [-->] else { disengage; } }
    }

    can parse_select with SqlSelect entry {
        status = "final" if here.is_final else "nested";
        print(f"parsed {status} select: {here.label}");
        if here.is_final {
            for (i, c) in enumerate(here.label.split(",")) {
                col = c.strip();
                if col != "" {
