        self.ctes_seen.append(here.name);
        print(f"resolving columns against CTE {here.name}");
        visit [->:ResolvesFrom:->] else { visit [-->] else { disengage; } }
    }

    can resolve_select with SqlSelect entry {
        self.resolved += 1;
        print(f"resolved select '{here.label}' against known CTEs "
              f"(ctes_seen={self.ctes_seen})");
        visit [->:ResolvesFrom:->] else { visit [-->] else { disengage; } }
    }
}

