"""Regex VM recursive subpattern calls: bounded call frames over a typed call graph.

Subpatterns are nodes; calls are typed edges; a CallExplorer walker performs
the recursive descent with an explicit depth budget and a visited set, so
direct and mutual recursion terminate through budget exhaustion instead of
spinning forever.
"""

node Subpattern {
    has name: str = "";
    has pid: int = 0;
    has is_define_only: bool = False;
    has is_dynamic: bool = False;
}

edge Calls {
    has kind: str = "named";  # "whole" | "numbered" | "named" | "relative"
}

walker CallExplorer {
    has max_depth: int = 8;
    has total_calls: int = 0;
    has call_budget: int = 20;
    has visited: dict = {};
    has exhausted: bool = False;

    can start with Root entry {
        visit [->:Calls:->];
    }

    can enter_subpattern with Subpattern entry {
        depth = 0;
        if here.is_dynamic {
            print(f"[REJECT] dynamic target {here.name} is unsupported");
            disengage;
        }
        if here.is_define_only {
            print(f"[SKIP] (DEFINE) block {here.name} is not directly callable");
            visit [-->] else { disengage; }
        }
        key = here.name;
        if key in self.visited {
            print(f"[CYCLE] {key} already on path; guard engages");
            disengage;
        }
        self.visited[key] = True;
        self.total_calls += 1;
        if self.total_calls > self.call_budget {
            print("[BUDGET] total-call budget exhausted");
            self.exhausted = True;
            disengage;
        }
        depth = self.visited.keys().len();
        if depth > self.max_depth {
            print(f"[BUDGET] recursion depth {depth} exceeds {self.max_depth} at {here.name}");
            self.exhausted = True;
            disengage;
        }
        print(f"[CALL] frame depth={depth} callee={here.name} (pid={here.pid})");
        visit [->:Calls:->] else {
            print(f"[RET] {here.name} returns (captures restored/published)");
        }
        del self.visited[key];
    }
}

walker Verifier {
    can start with Root entry {
        visit [-->];
    }

    can check with Subpattern entry {
        verdict = "ok" if not here.is_dynamic else "unresolved/dynamic";
        print(f"[VERIFY] {here.name}: call target {verdict}");
        visit [-->];
    }
}

with entry {
    whole = Subpattern(name="^", pid=0);
    balanced = Subpattern(name="balanced", pid=1);
    inner = Subpattern(name="inner", pid=2);
    define_block = Subpattern(name="DEFINE", pid=3, is_define_only=True);
    dyn = Subpattern(name="dyn_code", pid=4, is_dynamic=True);

    root ++> whole;
    whole +>:Calls(kind="whole"):+> balanced;
    balanced +>:Calls(kind="named"):+> inner;
    inner +>:Calls(kind="relative"):+> balanced;
    inner +>:Calls(kind="named"):+> dyn;
    define_block +>:Calls(kind="named"):+> inner;

    root spawn Verifier();
    root spawn CallExplorer(max_depth=4, call_budget=12);
    print("done: bounded recursion with cycle guard and dynamic rejection");
}

"""Native SVG painting: instead of serializing the <svg> subtree out to usvg,
a painter walker traverses the live SVG DOM directly, computing style and
geometry per element, with an explicit visited guard (no built-in dedupe)."""

node SvgElement {
    has tag: str = "";
    has fill: str = "black";
    has stroke: str = "none";
    has cx: float = 0.0;
    has cy: float = 0.0;
    has r: float = 0.0;

    def describe_style() -> str {
        return f"fill={self.fill}, stroke={self.stroke}";
    }
}

node SvgRoot {
    has width: float = 0.0;
    has height: float = 0.0;
}

edge ChildOf { }

walker SvgPainter {
    has visited: dict = {};
    has painted: int = 0;

    can start with Root entry {
        visit [->:ChildOf:->];
    }

    can paint_root with SvgRoot entry {
        print(f"<svg width={here.width} height={here.height}>");
        visit [->:ChildOf:->];
    }

    can paint with SvgElement entry {
        # explicit cycle guard: jac walkers do not dedupe on cyclic graphs
        if here.tag in self.visited {
            print(f"cycle detected at <{here.tag}>, skipping");
            disengage;
        }
        self.visited[here.tag] = True;
        self.painted += 1;
        print(f"  <{here.tag} {here.describe_style()} "
              f"cx={here.cx} cy={here.cy} r={here.r}/>");
        visit [->:ChildOf:->] else { disengage; }
    }

    can finish with SvgRoot exit {
        print(f"</svg> painted {self.painted} elements natively, "
              f"no re-serialization");
    }
}

with entry {
    root_node = SvgRoot(width=200.0, height=100.0);
    circle = SvgElement(tag="circle", fill="red", stroke="none", cx=50.0, cy=50.0, r=25.0);
    rect = SvgElement(tag="rect", fill="none", stroke="blue");
    text = SvgElement(tag="text", fill="green");
    root_node +>:ChildOf:+> circle;
    root_node +>:ChildOf:+> rect;
    rect +>:ChildOf:+> text;
    # mutation inside the SVG is live: no re-parse needed
    circle.fill = "orange";
    root ++> root_node;
    root spawn SvgPainter();
}

