"""Widget Lab blueprint: widget dependency graph with topological recompute and cycle detection.

Widgets form a declarative dependency graph. Changing a widget invalidates
its dependents, which a walker recomputes via typed DependsOn edges while
guarding against dependency cycles (explicit domain logic kept from the
hand-rolled adjacency-dict implementation).
"""

node Widget {
    has name: str = "";
    has value: float = 0.0;
    has stale: bool = True;
    has in_stack: bool = False;

    def recompute() -> float {
        return self.value;
    }
}

node Question(Widget) {
    override def recompute() -> float {
        # source answers are always fresh; they anchor the graph
        self.stale = False;
        return self.value;
    }
}

node Derived(Widget) {
    has expr: str = "sum";

    override def recompute() -> float {
        # recomputes from upstream values arriving via DependsOn edges
        total = 0.0;
        for upstream in [self ->:DependsOn:->] {
            total += upstream.value;
        }
        self.value = total;
        self.stale = False;
        return self.value;
    }
}

edge DependsOn { }
edge BelongsTo {
    has section: str = "";
}

walker InvalidationRecalculator {
    has visited: dict = {};
    has has_cycle: bool = False;
    has order: list[str] = [];

    can start with Root entry {
        visit [->:BelongsTo:->];
    }

    can enter_section with Widget entry {
        visit [-->];
    }

    # recomputes the invalidated widget and cascades to its dependents
    can recompute with Question | Derived entry {
        key = here.name;
        if key in self.visited {
            if here.in_stack {
                print(f"[CYCLE] dependency cycle detected at {key}");
                self.has_cycle = True;
            }
            disengage;
        }
        self.visited[key] = True;
        here.in_stack = True;
        val = here.recompute();
        self.order.append(key);
        print(f"[OK] {here.name} = {val}");
        here.in_stack = False;
        visit [<-:DependsOn:-] else { disengage; }
    }
}

walker DependencyAuditor {
    has seen: dict = {};
    has cycles: int = 0;

    can start with Root entry {
        visit [->:BelongsTo:->];
    }

    can audit with Widget entry {
        visit [->:DependsOn:->] else { disengage; }
    }

    can check with Question | Derived entry {
        if here.name in self.seen {
            print(f"[CYCLE] {here.name} reachable from itself");
            self.cycles += 1;
            disengage;
        }
        self.seen[here.name] = True;
        visit [->:DependsOn:->] else { disengage; }
    }
}

with entry {
    survey = Widget(name="Trip Survey");

    departure = Question(name="departure", value=1.0);
    ret = Question(name="return", value=2.0);
    adults = Question(name="adults", value=2.0);
    children = Question(name="children", value=1.0);

    duration = Derived(name="trip_duration", expr="return - departure");
    travelers = Derived(name="traveler_count", expr="adults + children");
    budget = Derived(name="budget_per_day", expr="sum of inputs");

    survey +>:BelongsTo(section="travel"):+> departure
        +>:BelongsTo(section="travel"):+> ret
        +>:BelongsTo(section="people"):+> adults
        +>:BelongsTo(section="people"):+> children;

    # DependsOn points from dependency to dependent; the invalidation
    # walker traverses it backwards to cascade recompute.
    departure +>:DependsOn:+> duration;
    ret +>:DependsOn:+> duration;
    adults +>:DependsOn:+> travelers;
    children +>:DependsOn:+> travelers;
    duration +>:DependsOn:+> budget;
    travelers +>:DependsOn:+> budget;

    print("--- dependency audit ---");
    root spawn DependencyAuditor();

    print("--- invalidate departure: cascade recompute ---");
    calc = InvalidationRecalculator();
    departure spawn calc;
    print(f"recomputed in order: {calc.order}; cycles: {calc.has_cycle}");
}

