"""Governed Neptune graph-query evidence: a Mission walks a provider's scoped,
bounded query results, classifying evidence status while never exposing raw
node properties (digest-only projections)."""

node Mission {
    has mission_id: str = "";
    has revision_digest: str = "";
}

node Provider {
    has provider_name: str = "";
    has registration_digest: str = "";
    has revoked: bool = False;
}

node QueryResult {
    has status: str = "PRESENT";  # PRESENT|EMPTY|PARTIAL|TIMEOUT|ACCESS_LOST|TAMPERED|REVOKED
    has node_count: int = 0;
    has edge_count: int = 0;
    has result_digest: str = "";
    has row_cap: int = 1000;
    has elapsed_ms: int = 0;
    has time_cap_ms: int = 5000;
    has digest_verified: bool = True;
}

edge ScopedQuery {
    has query_template_digest: str = "";
    has parameter_digest: str = "";
    has permission_scope: str = "read-only";
}

edge EvidenceProposal { }

walker GovernedQueryAuditor {
    has mission_revision: str = "";
    has visited: dict = {};
    has proposals: list = [];
    has failures: int = 0;

    can start with Root entry {
        self.visited = {};
        visit [->:ScopedQuery:->] else { disengage; }
    }

    # Cycle guard is explicit: jac walkers have no once-per-node visitation,
    # so a revocation loop must not hang the audit.
    can audit_provider with Provider entry {
        if here in self.visited {
            print(f"[CYCLE] provider {here.provider_name} already audited; disengaging");
            disengage;
        }
        self.visited[here] = True;
        if here.revoked {
            status = "REVOKED";
            print(f"[{status}] provider {here.provider_name} registration lost; fail-closed");
            self.failures += 1;
            disengage;
        }
        print(f"[AUDIT] provider {here.provider_name} reg-digest {here.registration_digest}");
        visit [->:EvidenceProposal:->] else { disengage; }
    }

    can classify with QueryResult entry {
        verdict = "OK";
        if not here.digest_verified {
            verdict = "TAMPERED";
        }
        elif here.elapsed_ms > here.time_cap_ms {
            verdict = "TIMEOUT";
        }
        elif here.node_count > here.row_cap {
            verdict = "PARTIAL";
        }
        elif here.node_count == 0 {
            verdict = "EMPTY";
        }
        # Digest-only projection: raw identifiers and properties stay redacted.
        projection = f"{verdict}:nodes={here.node_count}:edges={here.edge_count}:digest={here.result_digest[:8]}";
        if verdict in {"TAMPERED", "TIMEOUT"} {
            self.failures += 1;
        }
        self.proposals.append(projection);
        print(f"[EVIDENCE] {projection} (raw payloads redacted)");
        visit [-->] else { report self.proposals; disengage; }
    }
}

with entry {
    m = Mission(mission_id="M-7", revision_digest="rev-9f2c");
    provider = Provider(provider_name="neptune-cluster-1", registration_digest="reg-4b1d");
    root +>:ScopedQuery(query_template_digest="tmpl-a1", parameter_digest="parm-77"):+> provider;
    provider +>:EvidenceProposal:+> QueryResult(status="PRESENT", node_count=12, edge_count=7, result_digest="d41d8cd9ff10ab23", elapsed_ms=340);
    provider +>:EvidenceProposal:+> QueryResult(status="PARTIAL", node_count=1500, edge_count=980, result_digest="ef21ab99cd001234", elapsed_ms=1200, digest_verified=False);
    m ++> provider;
    root spawn GovernedQueryAuditor(mission_revision=m.revision_digest);
}

"""Nested L1-L5 control integration: planner, run, phase, Andon and audit-fix converge in one nested control graph.

Models R0037's core scenario: five lifecycle stages (L1..L5) form a
strictly nested control chain. An interrupting L4 Andon signal may
route once through the governed governor child (L4 -> audit-andon ->
L4/governor) and its bounded cognition must not re-enter L2. A
walker descends the chain with an explicit depth cap and a cycle
guard, marking each stage's verdict; the audit-fix stage only closes
when every upstream stage resolved.
"""

node Stage {
    has name: str = "";
    has level: int = 0;
    has resolved: bool = False;
    has verdict: str = "";
}

node Governor {
    has name: str = "audit-andon";
    has cognition_granted: bool = False;
}

edge Nested { }
edge Governed { }

walker Controller {
    has depth: int = 0;
    has max_depth: int = 5;
    has visited: list[str] = [];
    has andon_routed: bool = False;
    has all_resolved: bool = True;
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can descend with Stage entry {
        # Cycle guard (no built-in once-per-node visitation in Jac).
        if here.name in self.visited {
            self.findings += [f"cycle guard rejected re-entry to {here.name}"];
            disengage;
        }
        # Depth cap is preserved domain logic from the source.
        if self.depth > self.max_depth {
            self.findings += ["depth cap exceeded; halting descent"];
            disengage;
        }
        self.visited += [here.name];
        self.depth += 1;
        stage_label = f"L{here.level}:{here.name}";
        state = "resolved" if here.resolved else "unresolved";
        self.findings += [f"audited {stage_label} -> {state}"];
        # Interrupting Andon may route to governor once, but its
        # bounded cognition never re-enters the L2 run chain.
        if here.level == 4 and not self.andon_routed {
            self.andon_routed = True;
            here.resolved = True;
            here.verdict = "andon routed once (governed)";
            self.findings += ["L4 routed audit-andon: bounded cognition granted, L2 blocked"];
        } else {
            here.resolved = True;
            here.verdict = "converged";
        }
        # Governed L4 route: descend to the governor child only.
        if here.level == 4 {
            visit [->:Governed:->] else {
                visit [->:Nested:->] else { disengage; }
            }
        } else {
            visit [->:Nested:->] else { disengage; }
        }
    }

    can govern with Governor entry {
        if self.andon_routed {
            here.cognition_granted = True;
            self.findings += ["governor returned bounded cognition to L4 only"];
        }
        disengage;
    }

    can close with Stage exit {
        if here.level == 5 {
            upstream = [v for v in self.visited if v != here.name];
            self.findings += [f"audit-fix at {here.name}: obligations checked across {len(upstream)} upstream stages"];
            if self.all_resolved {
                here.verdict = "closed: no unresolved obligations";
            } else {
                here.verdict = "open obligations";
            }
            self.findings += [f"L5 verdict: {here.verdict}"];
        }
    }
