"""Regex VM recursive subpattern calls: bounded call frames over a typed call graph.

Subpatterns are nodes; calls are typed edges; a CallExplorer walker performs
the recursive descent with an explicit depth budget and a visited set, so
direct and mutual recursion terminate through budget exhaustion instead of
spinning forever.
"""

node Subpattern {
    has name: str = "";
    has pid: int = 0;
    has is_define_only: bool = False;
    has is_dynamic: bool = False;
}

edge Calls {
    has kind: str = "named";  # "whole" | "numbered" | "named" | "relative"
}

walker CallExplorer {
    has max_depth: int = 8;
    has total_calls: int = 0;
    has call_budget: int = 20;
    has depth: int = 0;
    has visited: list = [];
    has exhausted: bool = False;

    can start with Root entry {
        visit [->:Calls:->];
    }

    can enter_subpattern with Subpattern entry {
        if here.is_dynamic {
            print(f"[REJECT] dynamic target {here.name} is unsupported");
            disengage;
        }
        if here.is_define_only {
            print(f"[SKIP] (DEFINE) block {here.name} is not directly callable");
            visit [-->] else { disengage; }
        }
        key = here.name;
        if key in self.visited {
            print(f"[CYCLE] {key} already on path; guard engages");
            disengage;
        }
        self.visited.append(key);
        self.depth += 1;
        self.total_calls += 1;
        if self.total_calls > self.call_budget {
            print("[BUDGET] total-call budget exhausted");
            self.exhausted = True;
            disengage;
        }
        if self.depth > self.max_depth {
            print(f"[BUDGET] recursion depth {self.depth} exceeds {self.max_depth} at {here.name}");
            self.exhausted = True;
            disengage;
        }
        print(f"[CALL] frame depth={self.depth} callee={here.name} (pid={here.pid})");
        visit [->:Calls:->] else {
            print(f"[RET] {here.name} returns (captures restored/published)");
        }
        self.visited.pop();
        self.depth -= 1;
    }
}

walker Verifier {
    can start with Root entry {
        visit [-->];
    }

    can check with Subpattern entry {
        verdict = "ok" if not here.is_dynamic else "unresolved/dynamic";
        print(f"[VERIFY] {here.name}: call target {verdict}");
        visit [-->];
    }
}

with entry {
    whole = Subpattern(name="^", pid=0);
    balanced = Subpattern(name="balanced", pid=1);
    inner = Subpattern(name="inner", pid=2);
    define_block = Subpattern(name="DEFINE", pid=3, is_define_only=True);
    dyn = Subpattern(name="dyn_code", pid=4, is_dynamic=True);

    root ++> whole;
    whole +>:Calls(kind="whole"):+> balanced;
    balanced +>:Calls(kind="named"):+> inner;
    inner +>:Calls(kind="relative"):+> balanced;
    inner +>:Calls(kind="named"):+> dyn;
    define_block +>:Calls(kind="named"):+> inner;

    root spawn Verifier();
    root spawn CallExplorer(max_depth=4, call_budget=12);
    print("done: bounded recursion with cycle guard and dynamic rejection");
}

