    # walker traverses it forward to cascade updates topologically.
    departure +>:DependsOn:+> duration;
    ret +>:DependsOn:+> duration;
    adults +>:DependsOn:+> travelers;
    children +>:DependsOn:+> travelers;
    duration +>:DependsOn:+> budget;
    travelers +>:DependsOn:+> budget;

    print("--- dependency audit ---");
    root spawn DependencyAuditor();

    print("--- recompute cascade ---");
    calc = InvalidationRecalculator();
    departure spawn calc;
    print(f"recomputed in order: {calc.order}; cycles: {calc.has_cycle}");
}

"""Timeline group cascade delete.

A group delete must collect the group's leaf features and delete them
even when they have downstream dependents (the #25 bug: the naive path
declined silently).  Dependents are also removed first so nothing
dangles; empty group shells are then cleaned up.
"""

node Feature {
    has name: str = "";
    has deleted: bool = False;
}

node TimelineGroup {
    has name: str = "";
    has is_collapsed: bool = False;
}

edge Contains { }
edge DependsOn { }

walker GroupDeleter {
    has removed: list[str] = [];
    has blocked: list[str] = [];

    can start with Root entry {
        visit [->:Contains:->];
    }

    can enter_group with TimelineGroup entry {
        # Batched native delete path: gather leaves, cascade dependents.
        visit [->:Contains:->];
    }

    can delete_leaf with Feature entry {
        if here.deleted {
            disengage;
        }
        # Issue #25: naive deleteMe() silently returns False when the
        # feature has downstream dependents.  The fix routes dependents
        # through the same cascade instead of declining.
        deps = [e for e in here -->:DependsOn:--> where not e.deleted];
        for dep in deps {
            dep.deleted = True;
            self.removed.append(dep.name);
        }
        here.deleted = True;
        self.removed.append(here.name);
        visit [-->] else { disengage; }
    }

    can cleanup_group with TimelineGroup exit {
        here.is_collapsed = True;
        self.removed.append(f"shell:{here.name}");
    }
}

with entry {
    # sketch_group contains rect and circle; hole depends on circle;
    # fillet depends on rect (the downstream dependent that broke the
    # naive group delete in the issue).
    grp = TimelineGroup(name="SketchGroup");
    rect = Feature(name="RectSketch");
    circle = Feature(name="CircleSketch");
    hole = Feature(name="Hole");
    fillet = Feature(name="Fillet");
    grp +>:Contains:+> rect;
    grp +>:Contains:+> circle;
    circle +>:DependsOn:+> hole;
    rect +>:DependsOn:+> fillet;
    root ++> grp;

    root spawn GroupDeleter();
}

