"""Metadata dependency graph: entities, fields, and actions as nodes, with
typed edges so agents can reason about blast radius before destructive changes."""

node MetadataNode {
    has key: str = "";
    has entity_name: str = "";
    has kind: str = "";
}

node Entity(MetadataNode) {
    override has kind: str = "entity";
}

node Field(MetadataNode) {
    override has kind: str = "field";
}

node Action(MetadataNode) {
    override has kind: str = "action";
}

edge HasField { }
edge HasAction { }
edge DependsOn {
    has rel: str = "";
}

walker BlastRadius {
    has visited: list[str] = [];
    has broken: list[str] = [];
    has max_depth: int = 5;
    has root_name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can trace with Entity entry {
        visit [->:HasField:->];
        visit [->:HasAction:->];
    }

    can trace with Field | Action entry {
        if here.key in self.visited {
            print(f"[cycle guard] already traced {here.key}, skipping");
            disengage;
        }
        if len(self.visited) > self.max_depth {
            print(f"[depth cap] stopping at {here.key}");
            disengage;
        }
        self.visited.append(here.key);
        self.broken.append(here.key);
        print(f"  would break: {here.key}");
        visit [->:DependsOn:->] else { disengage; }
    }
}

walker Dependent {
    has target: str = "";

    can start with Root entry {
        visit [-->];
    }

    can inspect with Entity entry {
        visit [->:HasField:->];
        visit [->:HasAction:->];
    }

    can inspect with Field | Action entry {
        if here.key == self.target {
            print(f"[dependents of {self.target}]");
        }
        visit [<--:DependsOn:--] else { disengage; }
        if here.key != self.target {
            print(f"  dependent: {here.key}");
        }
    }
}

with entry {
    users = Entity(key="User", entity_name="User");
    orders = Entity(key="Order", entity_name="Order");
    email_f = Field(key="User.Email", entity_name="User");
    total_f = Field(key="Order.Total", entity_name="Order");
    greet_a = Action(key="User.GreetUser", entity_name="User");
    total_a = Action(key="Order.RecomputeTotal", entity_name="Order");

    users +>:HasField:+> email_f;
    orders +>:HasField:+> total_f;
    users +>:HasAction:+> greet_a;
    orders +>:HasAction:+> total_a;

    total_f +>:DependsOn(rel="field"):+> email_f;
    total_a +>:DependsOn(rel="action"):+> total_f;
    total_a +>:DependsOn(rel="action"):+> email_f;
    greet_a +>:DependsOn(rel="action"):+> email_f;

    root ++> users ++> orders;

    print("=== blast radius of deleting User.Email ===");
    root spawn BlastRadius(root_name="User.Email");

    print("=== dependents via dependency edges ===");
    root spawn Dependent(target="User.Email");
}

