"""Container/reference graph validation: bounded traversal, cycle detection via a visited set, and stable typed errors instead of tracebacks."""

node Container {
    has name: str = "";
    has depth: int = 0;
}

edge Contains { }

edge References { has path: str = ""; }

node CharacterRef {
    has char_id: str = "";
    has resolved: bool = False;
}

"""Stable, typed failure — no KeyError, no traceback escapes."""
enum CheckError {
    MISSING_PATH,
    INVALID_PATH,
    CYCLE_DETECTED,
    DEPTH_EXCEEDED,
}

const MAX_DEPTH: int = 5;

walker Validator {
    has visited: dict = {};
    has errors: list = [];
    has depth: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    """Bounded descent over containers and references with explicit cycle policy."""
    can inspect with Container entry {
        if here in self.visited {
            self.errors.append(f"{CheckError.CYCLE_DETECTED}:{here.name}");
            disengage;
        }
        if self.depth >= MAX_DEPTH {
            self.errors.append(f"{CheckError.DEPTH_EXCEEDED}:{here.name}");
            disengage;
        }
        self.visited[here] = True;
        nxt = self.depth + 1;
        for child in [here->:References:->] {
            if not child.resolved {
                self.errors.append(f"{CheckError.MISSING_PATH}:{child.char_id}");
            }
        }
        self.depth = nxt;
        visit [->:Contains:->] else { disengage; }
    }

    """A character reference is a leaf: never reinterpreted as a traversal target."""
    can inspect with CharacterRef entry {
        if here in self.visited { disengage; }
        self.visited[here] = True;
        if not here.resolved {
            self.errors.append(f"{CheckError.MISSING_PATH}:{here.char_id}");
        }
    }

    can done with Root exit {
        if self.errors {
            for e in self.errors {
                print(f"[{CheckError.MISSING_PATH.__class__.__name__ if False else 'error'}] {e}");
            }
        } else {
            print("validation ok: no cycles, no missing paths, depth bounded");
        }
    }
}

with entry {
    root_area = Container(name="root");
    gear = Container(name="gear");
    bag = Container(name="bag");
    root ++> root_area;
    root_area +>:Contains:+> gear +>:Contains:+> bag;
    # deliberate cycle: bag references gear (references carry paths, not traversal)
    bag +>:References(path="gear.backpack"):+> gear;
    bag +>:References(path="missing.1st"):+> CharacterRef(char_id="missing.1st");
    root spawn Validator();
}

