"""Dependency graph serialization demo: cells as nodes, formula deps as typed edges, walkers that traverse with explicit cycle guards (the machinery issue #353 hand-rolls)."""

node Cell {
    has key: str = "";
    has sheet: str = "";
    has formula: str | None = None;
    has value: int = 0;
    has is_target: bool = False;
}

node NamedRange {
    has name: str = "";
}

edge DependsOn {
    has guard: str = "";
}

walker CacheInvalidator {
    has visited: dict = {};
    has order: list = [];
    has cycle_found: bool = False;

    def mark_seen(c: Cell) -> bool {
        # returns True if this cell was newly seen (cycle policy: skip repeats)
        if c.key in self.visited {
            return False;
        }
        self.visited[c.key] = True;
        return True;
    }

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can invalidate with Cell entry {
        # depth-first dependency walk; explicit visited set is the cycle
        # guard (Jac 0.36 walkers do not dedupe on their own)
        if not self.mark_seen(here) {
            return;
        }
        status = "target" if here.is_target else "dep";
        tag = f"~{here.formula}" if here.formula is not None else f"={here.value}";
        print(f"invalidate [{status}] {here.key} {tag}");
        self.order.append(here.key);
        visit [->:DependsOn:->] else { return; }
    }

    can sweep_range with NamedRange entry {
        print(f"named range '{here.name}' touches its span; invalidating members");
        visit [->:DependsOn:->];
    }
}

walker SerializerAudit {
    has covered: dict = {};
    has missing: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Cell entry {
        # field manifest check: every serialized node must carry is_target
        if here.key not in self.covered {
            self.covered[here.key] = True;
            if not here.is_target and here.formula is not None {
                self.missing += 1;
            }
        }
        visit [-->] else { return; }
    }

    can audit_range with NamedRange entry {
        print(f"manifest: named range '{here.name}' recorded in payload");
        visit [-->];
    }

    can finish with Root exit {
        verdict = "pickle parity OK" if self.missing == 0 else "fidelity gap";
        print(f"audit: {len(self.covered)} nodes, {self.missing} gaps -> {verdict}");
    }
}

with entry {
    a1 = Cell(key="Sheet1!A1", sheet="Sheet1", value=1, is_target=True);
    b1 = Cell(key="Sheet1!B1", sheet="Sheet1", formula="A1*2", value=2);
    c1 = Cell(key="Sheet1!C1", sheet="Sheet1", formula="B1+A1", value=3);
    span = NamedRange(name="Inputs");

