    span +>:DependsOn(guard="always"):+> a1;
    b1 +>:DependsOn(guard="if_int"):+> a1;
    c1 +>:DependsOn:+> b1;
    c1 +>:DependsOn:+> a1;  # diamond: cycle guard must prevent re-walk

    root spawn CacheInvalidator();
    root spawn SerializerAudit();
}

"""Container/reference graph validation: bounded traversal, cycle detection via a visited set, and stable typed errors instead of tracebacks."""

node Container {
    has name: str = "";
}

node CharacterRef {
    has char_id: str = "";
    has resolved: bool = False;
}

edge Contains { }

edge References {
    has path: str = "";
}

walker Validator {
    has visited: list = [];
    has errors: list = [];
    has depth: int = 0;
    has max_depth: int = 5;
    has err_cycle: str = "CYCLE_DETECTED";
    has err_depth: str = "DEPTH_EXCEEDED";
    has err_missing: str = "MISSING_PATH";

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    """Bounded descent over containers with explicit cycle policy."""
    can inspect with Container entry {
        if here in self.visited {
            self.errors.append(f"{self.err_cycle}:{here.name}");
            disengage;
        }
        if self.depth >= self.max_depth {
            self.errors.append(f"{self.err_depth}:{here.name}");
            disengage;
        }
        self.visited.append(here);
        self.depth += 1;
        for ref in [here->:References:->] {
            if not ref.resolved {
                self.errors.append(f"{self.err_missing}:{ref.path}");
            }
        }
        visit [->:Contains:->] else { disengage; }
    }

    """A character reference is a leaf: never reinterpreted as a traversal target."""
    can inspect with CharacterRef entry {
        if here in self.visited { disengage; }
        self.visited.append(here);
        if not here.resolved {
            self.errors.append(f"{self.err_missing}:{here.char_id}");
        }
    }

    can done with Root exit {
        if self.errors {
            for e in self.errors {
                print(f"[error] {e}");
            }
        } else {
            print("validation ok: no cycles, no missing paths, depth bounded");
        }
    }
}

with entry {
    root_area = Container(name="root");
    gear = Container(name="gear");
    bag = Container(name="bag");
    root ++> root_area;
    root_area +>:Contains:+> gear +>:Contains:+> bag;
    # deliberate cycle: bag references gear (references carry paths, not traversal)
    bag +>:References(path="gear.backpack"):+> gear;
    bag +>:References(path="missing.1st"):+> CharacterRef(char_id="missing.1st");
    root spawn Validator();
}

"""Timeline group cascade delete (issue #25).

A group delete must collect the group's leaf features and delete them
even when they have downstream dependents. The naive path calls
deleteMe() directly and silently declines for such features; the fixed
path cascades through DependOn edges first (deleting dependents before
dependees), then removes the feature itself. Empty group shells are
collapsed and cleaned up afterwards.
"""

node Feature {
    has name: str = "";
    has deleted: bool = False;
}

node TimelineGroup {
    has name: str = "";
    has is_collapsed: bool = False;
}

edge Contains { }
edge DependsOn { }

walker GroupDeleter {
    has removed: list[str] = [];
    has visited: list[str] = [];

    can start with Root entry {
        visit [->:Contains:->] else { disengage; }
    }

    can enter_group with TimelineGroup entry {
        if here.name in self.visited {
            visit [-->];
        } else {
            self.visited.append(here.name);
            visit [->:Contains:->] else { disengage; }
        }
    }

    # Native-delete path: cascade to downstream dependents BEFORE
    # attempting removal of this feature, so nothing dangles and
    # deleteMe() never silently declines.
    can delete_leaf with Feature entry {
        if here.deleted or here.name in self.visited {
            return;
        }
        self.visited.append(here.name);
        visit [->:DependsOn:->];
        here.deleted = True;
        self.removed.append(here.name);
    }

    can cleanup_group with TimelineGroup exit {
        here.is_collapsed = True;
        self.removed.append(f"shell:{here.name}");
    }
}

with entry {
    grp = TimelineGroup(name="SketchGroup");
    rect = Feature(name="RectSketch");
    circle = Feature(name="CircleSketch");
    hole = Feature(name="Hole");
    fillet = Feature(name="Fillet");
    grp +>:Contains:+> rect;
    grp +>:Contains:+> circle;
    circle +>:DependsOn:+> hole;
    rect +>:DependsOn:+> fillet;
    root ++> grp;

    deleter = GroupDeleter();
    root spawn deleter;

    for name in deleter.removed {
        print(f"removed: {name}");
    }
}

