    has seen: dict = {};
    has changed_count: int = 0;

    def recompute(node: MediaNode) -> list[str] {
        langs = list(node.variant_languages());
        for child in [node ->:ChildOf:->] {
            langs += child.available_languages;
        }
        uniq: list[str] = [];
        for lang in langs {
