"""Chroxy session-query demo: live-preferred search over a session corpus.

Messages are nodes on a typed ``Next`` chain; sessions connect to fork
parents and subagent children via typed edges. A CorpusSearch walker does
a live-preferred read (current session turns answered in-memory first),
collects ranked hits, and a LineageTracer walks fork/subagent edges.
"""

node Project {
    has name: str = "";
}

node Session {
    has session_id: str = "";
    has provider: str = "";
    is_live: bool = False;
    has is_live: bool = False;
}

node Message {
    has role: str = "";
    has content: str = "";
    has ts: int = 0;
}

node IndexEntry {
    has session_id: str = "";
    has content: str = "";
}

edge Has { }
edge Next { }
edge ForkParent { }
edge Subagent { }

node Corpus {
    has query: str = "";
    has role_filter: str = "";
}

walker CorpusSearch {
    has query: str = "";
    has role_filter: str = "";
    has hits: list[tuple[int, str, str, str]] = [];

    can start with Corpus entry {
        self.query = here.query;
        self.role_filter = here.role_filter;
        visit [->:Has:->];
    }

    # Live-preferred: score each message directly from the live corpus
    # (the just-appended turn is always visible, no index lag).
    can score with Message entry {
        if self.role_filter != "" and here.role != self.role_filter {
            visit [-->] else { disengage; }
        }
        lower_content = here.content.lower();
        lower_query = self.query.lower();
        rank = 0;
        if lower_query in lower_content {
            idx = lower_content.find(lower_query);
            while idx != -1 {
                rank += 1;
                idx = lower_content.find(lower_query, idx + 1);
            }
        }
        if rank > 0 {
            self.hits.append((rank, here.role, here.content, here.session_label));
        }
        visit [-->] else { disengage; }
