    c1 +>:DependsOn:+> b1;
    c1 +>:DependsOn:+> a1;  # diamond: cycle guard must prevent re-walk

    root spawn CacheInvalidator();
    root spawn SerializerAudit();
}

"""Native syntax artifact builder: one iterative bounded walk over a ParseSnapshot
assigns deterministic local IDs to native nodes, keeping source_backing and
recovery_role as independent provenance axes and traversing children via typed
ChildOf edges in canonical field order (no parent_id duplication, no recursion)."""

node ParseSnapshot {
    has generation: str = "";
    has accepted: bool = True;
}

edge RootOf { }
edge ChildOf {
    has field_name: str = "";
    has order: int = 0;
}

node NativeNode {
    has kind: str = "";
    has start_byte: int = 0;
    has end_byte: int = 0;
    has source_backing: str = "source";   # source | synthetic | mixed | none
    has recovery_role: str = "ordinary";  # ordinary | recovered | missing | error | partial
    has local_id: int = -1;
    has visited: bool = False;
    has label: str = "";
}

walker ArtifactBuilder {
    has next_id: int = 0;
    has node_count: int = 0;
    has node_cap: int = 16;
    has root_id: int = -1;
    has cap_hit: bool = False;

    can start with Root entry {
        visit [->:RootOf:->] else { disengage; }
    }

    can build with NativeNode entry {
        # cycle guard: node-keyed via visited flag (no cross-reparse promise)
        if here.visited {
            print(f"cycle guard: {here.label} already assigned, skipping");
            disengage;
        }
        if self.node_count >= self.node_cap {
            self.cap_hit = True;
        }
        if self.cap_hit {
            print("bounded construction: cap reached, stopping descent");
            disengage;
        }
        here.visited = True;
        here.local_id = self.next_id;
        if self.root_id == -1 {
            self.root_id = self.next_id;
        }
        self.next_id += 1;
        self.node_count += 1;
        print(f"id={here.local_id} kind={here.kind} "
              f"bytes=[{here.start_byte},{here.end_byte}) "
              f"backing={here.source_backing} recovery={here.recovery_role} "
              f"label={here.label}");
        visit [->:ChildOf:->] else { disengage; }
    }
}

with entry {
    snap = ParseSnapshot(generation="gen-42", accepted=True);

    # arena-shaped syntax tree: root -> stmt -> expr -> scalar, plus a recovered node
    root_n = NativeNode(kind="program", start_byte=0, end_byte=42,
                        label="program");
    stmt = NativeNode(kind="expression_statement", start_byte=0, end_byte=20,
                      label="echo_stmt");
    call = NativeNode(kind="import_call", start_byte=0, end_byte=20,
                      label="import_args", source_backing="mixed",
