    arglist = NativeNode(kind="arg_list_record", start_byte=6, end_byte=19,
                         label="arg_list", source_backing="synthetic",
                         recovery_role="partial");
    scalar = NativeNode(kind="string_scalar", start_byte=12, end_byte=18,
                        label="value");

    snap +>:RootOf:+> root_n;
    root ++> snap;
    root_n +>:ChildOf(field_name="body", order=0):+> stmt;
    stmt +>:ChildOf(field_name="expression", order=0):+> call;
    call +>:ChildOf(field_name="arguments", order=0):+> arglist;
    arglist +>:ChildOf(field_name="value", order=0):+> scalar;

    root spawn ArtifactBuilder(node_cap=8);
    print(f"built {root_n.local_id}-rooted artifact: deterministic, bounded, "
          f"source_backing and recovery_role kept as independent axes");
}

"""Linter walk that recursively visits Callback Objects' operations and schemas.

Cycle guard: an identity-based visited set on the walker so nested or
mutually recursive callbacks terminate without duplicate diagnostics.
"""

edge HasOperation { }
edge HasSchema { }
edge CallbackRef { }

node Operation {
    has op_id: str = "";
    has method: str = "";
    has has_success_response: bool = True;
}

node Schema {
    has name: str = "";
    has uses_nullable: bool = False;
}

node Callback {
    has name: str = "";
}

walker Linter {
    has seen: list = [];
    has diagnostics: list = [];

    def mark(n: object) -> bool {
        for s in self.seen {
            if s is n { return False; }
        }
        self.seen.append(n);
        return True;
    }

    def note(msg: str) {
        self.diagnostics.append(msg);
    }

    can start with Root entry {
        visit [->:HasOperation:->];
        visit [->:CallbackRef:->];
    }

    can lint_operation with Operation entry {
        if self.mark(here) {
            label = here.op_id if here.op_id else f"anonymous {here.method} callback op";
            if here.op_id == "" {
                self.note(f"{label}: missing operationId");
            }
            if not here.has_success_response {
                self.note(f"{label}: missing success response");
            }
            visit [->:HasSchema:->];
            visit [->:CallbackRef:->];
        }
    }

    can lint_schema with Schema entry {
        if self.mark(here) {
            if here.uses_nullable {
                self.note(f"schema {here.name}: 3.0-only 'nullable' used in 3.1 document");
            }
            visit [->:HasSchema:->];
            visit [->:CallbackRef:->];
        }
    }

    can lint_callback with Callback entry {
        if self.mark(here) {
            print(f"entering callback '{here.name}'");
            visit [->:HasOperation:->];
            visit [->:CallbackRef:->];
        }
    }

    can finish with Root exit {
        print(f"collected {len(self.diagnostics)} diagnostics:");
        for d in self.diagnostics {
            print(f"  - {d}");
        }
    }
}

with entry {
    # a normal root operation (clean)
    root +>:HasOperation:+> Operation(op_id="listPets", method="get");

    # the callback from the issue: nested, missing op-level pieces,
    # with an invalid nullable schema, and a cyclic self-reference
    cb = Callback(name="changed");
    root +>:CallbackRef:+> cb;
    bad = Operation(op_id="", method="post", has_success_response=False);
    cb +>:HasOperation:+> bad;
    bad +>:HasSchema:+> Schema(name="callbackBody", uses_nullable=True);
    # nested callback referencing back to the same callback object: cycle
    bad +>:CallbackRef:+> cb;

    root spawn Linter();
}

"""BatchSetSoftwareInstallers refactor: read-diff-write over typed edges.

Current installers live as nodes connected to the root via Deployed edges.
A planner walker READS them, DIFFs against the desired catalog, and classifies
each package as inserted / updated / deleted before the plan is applied,
mirroring the declarative GitOps pattern from the issue.
"""

node SoftwareInstaller {
    has title: str = "";
    has version: str = "";
    has labels: list[str] = list[str]();
}

edge Deployed { }

walker Planner {
    has desired: dict[str, str] = dict[str, str]();
    has to_insert: list[SoftwareInstaller] = list[SoftwareInstaller]();
    has to_update: list[SoftwareInstaller] = list[SoftwareInstaller]();
    has to_delete: list[SoftwareInstaller] = list[SoftwareInstaller]();
    has seen_titles: list[str] = list[str]();
    has dry_run: bool = False;

    can read with Root entry {
        visit [->:Deployed:->];
    }

    can diff with SoftwareInstaller entry {
        self.seen_titles.append(here.title);
        if here.title in self.desired {
            wanted_version = self.desired[here.title];
            if wanted_version == here.version {
                print(f"[keep]    {here.title} @ {here.version}");
            } else {
                print(f"[update]  {here.title}: {here.version} -> {wanted_version}");
                if not self.dry_run {
                    here.version = wanted_version;
                }
                self.to_update.append(here);
            }
        } else {
            print(f"[delete]  {here.title} @ {here.version}");
            self.to_delete.append(here);
        }
        visit [->:Deployed:->];
    }

    can plan_inserts with Root exit {
        for (title, version) in self.desired.items() {
            found = False;
            for seen in self.seen_titles {
                if seen == title {
                    found = True;
                    break;
                }
            }
            if not found {
                inst = SoftwareInstaller(title=title, version=version);
                self.to_insert.append(inst);
                print(f"[insert]  {title} @ {version}");
                if not self.dry_run {
                    root +>:Deployed:+> inst;
                }
            }
        }
        print(f"plan: {len(self.to_insert)} insert(s), "
              f"{len(self.to_update)} update(s), "
              f"{len(self.to_delete)} delete(s), dry_run={self.dry_run}");
    }
}

