    root ++> SoftwareInstaller(title="vscode", version="1.80.0")
        ++> SoftwareInstaller(title="slack", version="4.30.0", labels=["comms"])
        ++> SoftwareInstaller(title="zoom", version="5.10.0");

    root spawn Planner(
        desired={"vscode": "1.85.0", "figma": "120.0.0"},
