    );

    print("--- applying for real ---");
    root spawn Planner(
        desired={"vscode": "1.85.0", "figma": "120.0.0"},
        dry_run=False,
    );
}

"""Chroxy session-query demo: live-preferred ranked search over a session corpus.

Messages hang off sessions on a typed ``Next`` chain; sessions carry
``ForkParent`` and ``Subagent`` edges. A CorpusSearch walker spawned on a
session walks its messages live (the just-appended turn is always visible),
while a LineageTracer walks fork/subagent edges with an explicit visited
guard and depth cap as cycle policy.
"""

node Session {
    has session_id: str = "";
    has provider: str = "";
    has is_live: bool = False;
}

node Message {
    has role: str = "";
    has content: str = "";
    has ts: int = 0;
}

node IndexEntry {
    has session_id: str = "";
    has content: str = "";
    has rank: int = 0;
}

edge Next { }
edge ForkParent { }
edge Subagent { }
edge Owns { }

walker CorpusSearch {
    has query: str = "";
    has role_filter: str = "";
    has hits: list[tuple[int, str, str]] = [];

    can start with Session entry {
        visit [->:Next:->];
    }

    # Live-preferred read: score messages straight from the live chain,
    # so a turn appended one second ago is findable immediately.
    can score with Message entry {
        if self.role_filter == "" or here.role == self.role_filter {
            lower_content = here.content.lower();
            lower_query = self.query.lower();
            rank = 0;
            idx = lower_content.find(lower_query);
            while idx != -1 {
                rank += 1;
                idx = lower_content.find(lower_query, idx + 1);
            }
            if rank > 0 {
                self.hits.append((rank, here.role, here.content));
            }
        }
        visit [->:Next:->] else { disengage; }
    }

    can report with Session exit {
        for h in self.hits {
            print(f"[rank {h[0]}] ({h[1]}) {h[2]}");
        }
    }
}

walker LineageTracer {
    has depth: int = 0;
    has max_depth: int = 8;
    has visited: list[str] = [];

    # Cycle policy: explicit visited guard + depth cap (domain logic).
    can trace with Session entry {
        if here.session_id in self.visited {
            print(f"cycle detected at {here.session_id}");
            disengage;
        }
        self.visited.append(here.session_id);
        if self.depth > self.max_depth {
            print(f"depth cap reached at {here.session_id}");
            disengage;
        }
        self.depth += 1;
        print(f"session {here.session_id} (provider={here.provider}, live={here.is_live})");
        visit [->:ForkParent:->] else {
            visit [->:Subagent:->] else { disengage; }
        }
    }
}

