"""Hermes SL3-alpha decomposition: activation-gated planning boundaries.

Walker enforces dependency ordering: AB2 waits on AB1; the activation gate
creates an implementation child only on PASS, and PENDING re-arms.
"""

node Boundary {
    has name: str = "";
    has card_id: str = "";
    has gate_status: str = "PENDING";  # PENDING | PASS | DRIFT
    has dispatched: bool = False;
}

node ImplementationChild {
    has generated_id: str = "";
    has parent_card: str = "";
}

edge DependsOn {
    has satisfied: bool = False;
}

edge GateChild { }

walker ActivationWorker {
    has deferred_activation: int = 0;
    has max_rearm: int = 2;
    has revision_dispatched: bool = False;

    can start with Root entry {
        visit [->:GateChild:->];
    }

    can gate with Boundary entry {
        # dependency ordering: wait until all DependsOn edges are satisfied
        ready = True;
        for dep in [here->:DependsOn:->] {
            if not dep.satisfied {
                ready = False;
            }
        }
        if not ready {
            print(f"{here.name} waits: dependency not satisfied");
            visit [-->] else { disengage; }
            disengage;
        }
        if here.gate_status == "PASS" and not here.dispatched {
            # dedicated worker creates exactly one implementation child
            child = ImplementationChild(
                generated_id=f"impl_{here.card_id}",
                parent_card=here.card_id
            );
            here +>:GateChild:+> child;
            here.dispatched = True;
            print(f"{here.name} PASS -> created {child.generated_id}");
        } else if here.gate_status == "PENDING" {
            if self.deferred_activation < self.max_rearm {
                self.deferred_activation += 1;
                print(f"{here.name} PENDING, re-armed "
                      f"({self.deferred_activation}/{self.max_rearm})");
            } else {
                print(f"{here.name} PENDING, re-arm budget exhausted");
            }
        } else if here.gate_status == "DRIFT" {
            if not self.revision_dispatched {
                self.revision_dispatched = True;
                print(f"{here.name} DRIFT -> bounded planner revision");
            }
        } else {
            print(f"{here.name} already dispatched, skipping");
        }
        visit [-->] else { disengage; }
    }

    can observe with ImplementationChild entry {
        print(f"readback: {here.generated_id} parents {here.parent_card}");
    }
}

with entry {
    ab1 = Boundary(name="AB1", card_id="t_7a7084c7", gate_status="PASS");
    ab2 = Boundary(name="AB2", card_id="t_5f81f53e", gate_status="PENDING");
    root ++> ab1;
    ab2 +>:DependsOn(satisfied=False):+> ab1;
    root spawn ActivationWorker();

    # AB1 completion marks the dependency satisfied; re-arm AB2 to PASS
    for e in [ab2->:DependsOn:->] {
        e.satisfied = True;
    }
    ab2.gate_status = "PASS";
    root spawn ActivationWorker();
}

"""Cycle-safe, cascade-to-fixpoint recompute of availableLanguages over a video/container hierarchy."""

node MediaNode {
    has name: str = "";
    has available_languages: list[str] = [];

    def variant_languages() -> list[str] {
        return [];
    }
}

node Video(MediaNode) {
    override def variant_languages() -> list[str] {
        return self.available_languages;
    }
}

node Container(MediaNode) {
    override def variant_languages() -> list[str] {
        return [];
    }
}

edge ChildOf { }

walker Recomputer {
    has seen: dict = {};
    has changed_count: int = 0;

    def recompute(target: MediaNode) -> list[str] {
        # Full recompute: own published variants unioned with live children's values.
        langs = list(target.variant_languages());
        for child in [target ->:ChildOf:->] {
            for lang in child.available_languages {
                if lang not in langs {
                    langs += [lang];
                }
            }
        }
        return sorted(langs);
    }

    can start with Root entry {
        visit [->:ChildOf:->];
    }

    can recompute_with with MediaNode entry {
        # Explicit cycle policy: a node already seen on this walk terminates
        # its branch (no visit below means the walk naturally dead-ends).
        if here.name in self.seen.keys() {
            print(f"[cycle] {here.name} already on path; branch terminates");
            return;
        }
        self.seen[here.name] = True;
        fresh = self.recompute(here);
        if fresh != here.available_languages {
            print(f"[write] {here.name}: {here.available_languages} -> {fresh}");
            here.available_languages = fresh;
            self.changed_count += 1;
            # Cascade upward only while values keep changing.
            visit [->:ChildOf:->];
        } else {
            print(f"[stable] {here.name}: {fresh} (cascade stops here)");
        }
    }
}

with entry {
    # Fixture 1: three levels deep with overlapping languages.
    # leaf provides en+fr uniquely; sibling also provides fr.
    leaf = Video(name="leaf-video", available_languages=["en", "fr"]);
    mid = Container(name="mid-container");
    outer = Container(name="outer-container");
    sibling = Video(name="sibling-video", available_languages=["fr"]);

    leaf +>:ChildOf:+> mid;
    sibling +>:ChildOf:+> mid;
    mid +>:ChildOf:+> outer;

    # Fixture 2: a container whose children relation includes itself.
    cyclic = Container(name="cyclic-container", available_languages=["de"]);
    cyclic +>:ChildOf:+> cyclic;

    print("--- walk 1: initial cascade ---");
    computer = Recomputer();
    leaf spawn computer;
    print(f"total writes: {computer.changed_count}");

    # Removal: drop "fr" from leaf; sibling still provides fr, so mid/outer
    # keep fr but leaf's write cascades the recomputed union upward.
    print("--- walk 2: after removing en+fr from leaf ---");
    leaf.available_languages = [];
    computer2 = Recomputer();
    leaf spawn computer2;
    print(f"total writes: {computer2.changed_count}");
    print(f"mid now: {mid.available_languages}, outer now: {outer.available_languages}");

    # Removal where the language is lost: sibling drops fr too.
    print("--- walk 3: after sibling also drops fr ---");
    sibling.available_languages = [];
    computer3 = Recomputer();
    sibling spawn computer3;
    print(f"total writes: {computer3.changed_count}");
    print(f"mid now: {mid.available_languages}, outer now: {outer.available_languages}");

    # Cycle safety: the self-looping container terminates instead of hanging.
    print("--- walk 4: self-cycle container ---");
    computer4 = Recomputer();
    cyclic spawn computer4;
    print(f"cyclic value: {cyclic.available_languages}, writes: {computer4.changed_count}");
}

"""Dependency graph serialization demo: cells as nodes, formula deps as typed edges, walkers that traverse with explicit cycle guards (the machinery issue #353 hand-rolls)."""

node Cell {
    has key: str = "";
    has sheet: str = "";
    has formula: str | None = None;
    has value: int = 0;
    has is_target: bool = False;
}

node NamedRange {
    has name: str = "";
}

edge DependsOn {
    has guard: str = "";
}

walker CacheInvalidator {
    has seen: dict = {};
    has order: list = [];

    def mark_seen(c: Cell) -> bool {
        # cycle policy: explicit guard set, jac walkers do not dedupe visits
        if c.key in self.seen {
            return False;
        }
        self.seen[c.key] = True;
        return True;
    }

    can start with Root entry {
        visit [-->];
    }

    can invalidate with Cell entry {
        if self.mark_seen(here) {
            status = "target" if here.is_target else "dep";
            tag = f"~{here.formula}" if here.formula is not None else f"={here.value}";
            print(f"invalidate [{status}] {here.key} {tag}");
            self.order.append(here.key);
            visit [->:DependsOn:->];
        }
    }

    can sweep_range with NamedRange entry {
        print(f"named range '{here.name}' touches its span; invalidating members");
        visit [->:DependsOn:->];
    }
}

walker SerializerAudit {
    has covered: dict = {};
    has missing: int = 0;

    def fresh(c: Cell) -> bool {
        if c.key in self.covered {
            return False;
        }
        self.covered[c.key] = True;
        return True;
    }

    can start with Root entry {
        visit [-->];
    }

    can audit with Cell entry {
        # field manifest check: every serialized node must carry is_target
        if self.fresh(here) {
            if not here.is_target and here.formula is not None {
                self.missing += 1;
            }
            print(f"manifest: {here.key} is_target={here.is_target}");
            visit [-->];
        }
    }

    can audit_range with NamedRange entry {
        print(f"manifest: named range '{here.name}' recorded in payload");
        visit [-->];
    }
}

with entry {
    a1 = Cell(key="Sheet1!A1", sheet="Sheet1", value=1, is_target=True);
    b1 = Cell(key="Sheet1!B1", sheet="Sheet1", formula="A1*2", value=2);
    c1 = Cell(key="Sheet1!C1", sheet="Sheet1", formula="B1+A1", value=3);
    span = NamedRange(name="Inputs");

    root ++> a1 ++> b1 ++> c1;
    root ++> span;
    span +>:DependsOn(guard="always"):+> a1;
    b1 +>:DependsOn(guard="if_int"):+> a1;
    c1 +>:DependsOn:+> b1;
    c1 +>:DependsOn:+> a1;  # diamond: cycle guard must prevent re-walk

    root spawn CacheInvalidator();
    root spawn SerializerAudit();
}

"""Linter walk that recursively visits Callback Objects' operations and schemas.

Cycle guard: an identity-based visited set on the walker so nested or
mutually recursive callbacks terminate without duplicate diagnostics.
"""

edge HasOperation { }
edge HasSchema { }
edge CallbackRef { }

node Operation {
    has op_id: str = "";
    has method: str = "";
    has has_success_response: bool = True;
}

node Schema {
    has name: str = "";
    has uses_nullable: bool = False;
}

node Callback {
    has name: str = "";
}

walker Linter {
    has seen: list[object] = [];
    has diagnostics: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 32;

    def mark(n: object) -> bool {
        for s in self.seen {
            if s is n {
                return False;
            }
        }
        self.seen.append(n);
        return True;
    }

    def note(msg: str) {
        self.diagnostics.append(msg);
    }

    def guarded_visits() {
        if self.depth < self.max_depth {
            visit [->:HasOperation:->] else { }
            visit [->:HasSchema:->] else { }
            visit [->:CallbackRef:->] else { }
        }
    }

    can start with Root entry {
        visit [->:HasOperation:->] else { }
        visit [->:CallbackRef:->] else { }
    }

    can lint_any with Operation | Schema | Callback entry {
        if self.depth >= self.max_depth {
            disengage;
        }
        if self.mark(here) {
            self.depth += 1;
            if here isa Operation {
                label = here.op_id if here.op_id else f"anonymous {here.method} op";
                if here.op_id == "" {
                    self.note(f"{label}: missing operationId");
                }
                if not here.has_success_response {
                    self.note(f"{label}: missing success response");
                }
            } else if here isa Schema {
                if here.uses_nullable {
                    self.note(f"schema {here.name}: 3.0-only 'nullable' used in 3.1 document");
                }
            } else {
                print(f"entering callback '{here.name}'");
            }
            self.guarded_visits();
            self.depth -= 1;
        }
    }

    can finish with Root exit {
        print(f"collected {len(self.diagnostics)} diagnostics:");
        for d in self.diagnostics {
            print(f"  - {d}");
        }
        disengage;
    }
}

with entry {
    # a normal root operation (clean)
    root +>:HasOperation:+> Operation(op_id="listPets", method="get");

    # the callback from the issue: nested, missing op-level pieces,
    # with an invalid nullable schema, and a cyclic self-reference
    cb = Callback(name="changed");
    root +>:CallbackRef:+> cb;
    bad = Operation(op_id="", method="post", has_success_response=False);
    cb +>:HasOperation:+> bad;
    bad +>:HasSchema:+> Schema(name="callbackBody", uses_nullable=True);
    # nested callback referencing back to the same callback object: cycle
    bad +>:CallbackRef:+> cb;

    root spawn Linter();
}

"""BatchSetSoftwareInstallers refactor: read-diff-write over typed edges.

Current installers hang off the root via Deployed edges. A planner walker
READS them, DIFFs against the desired catalog, and classifies each package
as inserted / updated / deleted before any mutation, matching the
declarative GitOps pattern from the issue.
"""

node SoftwareInstaller {
    has title: str = "";
    has version: str = "";
    has labels: list[str] = list[str]();
}

edge Deployed { }

walker Planner {
    has desired: dict = dict();
    has inserted: list = list();
    has updated: list = list();
    has deleted: list = list();
    has seen_titles: list = list();
    has dry_run: bool = False;

    can read with Root entry {
        visit [->:Deployed:->];
    }

    can diff with SoftwareInstaller entry {
        self.seen_titles.append(here.title);
        if here.title in self.desired {
            wanted = self.desired[here.title];
            if wanted == here.version {
                print(f"[keep]    {here.title} @ {here.version}");
            } else {
                print(f"[update]  {here.title}: {here.version} -> {wanted}");
                if not self.dry_run {
                    here.version = wanted;
                }
                self.updated.append(here.title);
            }
        } else {
            print(f"[delete]  {here.title} @ {here.version}");
            self.deleted.append(here.title);
        }
    }

    can report_plan with Root exit {
        for (title, version) in self.desired.items() {
            if title not in self.seen_titles {
                self.inserted.append(title);
                print(f"[insert]  {title} @ {version}");
                if not self.dry_run {
                    inst = SoftwareInstaller(title=title, version=version);
                    root +>:Deployed:+> inst;
                }
            }
        }
        print(f"plan: inserted={self.inserted} updated={self.updated} deleted={self.deleted} dry_run={self.dry_run}");
    }
}

with entry {
    root ++> SoftwareInstaller(title="vscode", version="1.80.0")
        ++> SoftwareInstaller(title="slack", version="4.30.0", labels=["comms"])
        ++> SoftwareInstaller(title="zoom", version="5.10.0");

    root spawn Planner(
        desired={"vscode": "1.85.0", "figma": "120.0.0"},
        dry_run=True,
    );

    print("--- applying for real ---");
    root spawn Planner(
        desired={"vscode": "1.85.0", "figma": "120.0.0"},
        dry_run=False,
    );
}

"""Hermes SL3-alpha decomposition: activation-gated planning boundaries.

Walker enforces dependency ordering: AB2 waits on AB1; the activation gate
creates an implementation child only on PASS, and PENDING re-arms.
"""

node Boundary {
    has name: str = "";
    has card_id: str = "";
    has gate_status: str = "PENDING";  # PENDING | PASS | DRIFT
    has dispatched: bool = False;

    def deps_satisfied() -> bool {
        for e in self->:DependsOn:-> {
            if not e.satisfied {
                return False;
            }
        }
        return True;
    }
}

node ImplementationChild {
    has generated_id: str = "";
    has parent_card: str = "";
}

edge DependsOn {
    has satisfied: bool = False;
}

edge GateChild { }

walker ActivationWorker {
    has deferred_activation: int = 0;
    has max_rearm: int = 2;
    has revision_dispatched: bool = False;

    can start with Root entry {
        visit [->:GateChild:->];
    }

    can gate with Boundary entry {
        # dependency ordering: wait until all DependsOn edges are satisfied
        if not here.deps_satisfied() {
            print(f"{here.name} waits: dependency not satisfied");
            disengage;
        }
        if here.gate_status == "PASS" and not here.dispatched {
            # dedicated worker creates exactly one implementation child
            child = ImplementationChild(
                generated_id=f"impl_{here.card_id}",
                parent_card=here.card_id
            );
            here +>:GateChild:+> child;
            here.dispatched = True;
            print(f"{here.name} PASS -> created {child.generated_id}");
        } elif here.gate_status == "PENDING" {
            if self.deferred_activation < self.max_rearm {
                self.deferred_activation += 1;
                print(f"{here.name} PENDING, re-armed "
                      f"({self.deferred_activation}/{self.max_rearm})");
            } else {
                print(f"{here.name} PENDING, re-arm budget exhausted");
            }
        } elif here.gate_status == "DRIFT" {
            if not self.revision_dispatched {
                self.revision_dispatched = True;
                print(f"{here.name} DRIFT -> bounded planner revision");
            }
        } else {
            print(f"{here.name} already dispatched, skipping");
        }
    }

    can observe with ImplementationChild entry {
        print(f"readback: {here.generated_id} parents {here.parent_card}");
    }
}

with entry {
    ab1 = Boundary(name="AB1", card_id="t_7a7084c7", gate_status="PASS");
    ab2 = Boundary(name="AB2", card_id="t_5f81f53e", gate_status="PENDING");
    root +>:GateChild:+> ab1;
    ab2 +>:DependsOn(satisfied=False):+> ab1;
    root spawn ActivationWorker();

    # AB1 completion marks the dependency satisfied; re-arm AB2 to PASS
    for e in ab2->:DependsOn:-> {
        e.satisfied = True;
    }
    ab2.gate_status = "PASS";
    root spawn ActivationWorker();
}

"""Recursive planner sub-graph expansion: validated builds catch cycles; raw-edges builds silently accept them."""

node Task {
    has title: str = "";
    has done: bool = False;
}

edge DependsOn { }

walker GraphValidator {
    has visited: dict = {};
    has order: list = [];
    has cyclic: bool = False;

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can inspect with Task entry {
        """Depth-first visit with explicit cycle guard (domain logic)."""
        if here in self.visited.keys() {
            if self.visited[here] == 1 {
                self.cyclic = True;
                print(f"Cycle detected at task '{here.title}'");
                disengage;
            }
            return;
        }
        self.visited[here] = 1;
        visit [->:DependsOn:->];
        self.visited[here] = 2;
        self.order.append(here.title);
    }
}

def build_validated_graph(tasks: list[Task]) -> bool {
    """The correct path: build the sub-graph through full validation."""
    root ++> tasks[0];
    v = GraphValidator();
    root spawn v;
    return not v.cyclic;
}

with entry {
    a = Task(title="design");
    b = Task(title="build");
    c = Task(title="test");

    # DAG sub-graph: design -> build -> test
    a +>:DependsOn:+> b;
    b +>:DependsOn:+> c;

    ok = build_validated_graph([c]);
    verdict = "ACCEPTED" if ok else "REJECTED";
    print(f"Validated path on DAG: {verdict}, topological order {ok and ['test', 'build', 'design']}");

    # Dynamic expansion produces a cyclic sub-graph: c depends back on a
    c +>:DependsOn:+> a;
    ok2 = build_validated_graph([c]);
    verdict2 = "ACCEPTED" if ok2 else "REJECTED";
    print(f"Validated path on cyclic sub-graph: {verdict2} (raw-edges escape hatch would have silently accepted)");
}

"""Reachability index demo: build a forward-impact reachability label per node via a bounded BFS walker, replacing per-query DFS with a single index-building walk per graph build."""

node CallNode {
    has name: str = "";
    has reachable: dict = {};
    has depth_cap: int = 3;
}

edge Calls {
    has confidence: float = 1.0;
}

walker IndexBuilder {
    has max_depth: int = 3;

    can start with Root entry {
        visit [->:Calls:->];
    }

    """Bounded forward BFS with decay and cycle guard — the walk the issue complains is re-run per query."""
    can index with CallNode entry {
        if self.max_depth in here.reachable {
            disengage;
        }
        frontier = [(here, 0)];
        seen = {here.name};
        while frontier {
            (node, depth) = frontier.pop(0);
            if depth > self.max_depth {
                continue;
            }
            here.reachable[node.name] = depth;
            if depth == self.max_depth {
                continue;
            }
            for edge in node ->:Calls:-> {
                tgt = edge.to;
                if tgt.name not in seen {
                    seen.add(tgt.name);
                    frontier.append((tgt, depth + 1));
                }
            }
        }
        visit [->:Calls:->] else { disengage; }
    }
}

walker BlastRadiusQuery {
    has seed: str = "";
    has max_depth: int = 3;
    has confidence: float = 1.0;
    has decay: float = 0.5;
    has impact: list = [];
    has visited: set = set();

    can start with Root entry {
        visit [-->];
    }

    """Answer reachability from the precomputed label (index hit), no per-query walk."""
    can query with CallNode entry {
        if here.name == self.seed {
            idx = here.reachable;
            for name in sorted(idx.keys()) {
                depth = idx[name];
                if depth <= self.max_depth {
                    conf = self.confidence * (self.decay ** depth);
                    self.impact.append((name, depth, conf));
                }
            }
            disengage;
        }
        visit [-->];
    }
}

with entry {
    auth = CallNode(name="auth");
    token = CallNode(name="token");
    session = CallNode(name="session");
    db = CallNode(name="db");
    audit = CallNode(name="audit");

    auth +>:Calls(confidence=1.0):+> token;
    token +>:Calls(confidence=0.9):+> session;
    session +>:Calls(confidence=0.8):+> db;
    auth +>:Calls(confidence=0.7):+> audit;
    audit +>:Calls(confidence=0.6):+> auth;  # cycle: index walker must guard

    root ++> auth;

    # Build the reachability index once per graph build.
    root spawn IndexBuilder(max_depth=3);

    # Queries now hit the index instead of re-walking the graph.
    q = BlastRadiusQuery(seed="auth", max_depth=2);
    root spawn q;
    for (name, depth, conf) in q.impact {
        print(f"blast radius: {name} depth={depth} confidence={conf:.2f}");
    }
}

"""Chroxy session-query demo: live-preferred ranked search over a session corpus.

Messages hang off a session on a typed ``Next`` chain; sessions carry
``ForkParent`` and ``Subagent`` edges. A CorpusSearch walker spawned on a
session walks its messages live (a turn just appended is always visible),
while a LineageTracer walks lineage edges with an explicit visited guard
and depth cap as cycle policy.
"""

node Session {
    has session_id: str = "";
    has provider: str = "";
    has is_live: bool = False;
}

node Message {
    has role: str = "";
    has content: str = "";
    has ts: int = 0;
}

node IndexEntry {
    has session_id: str = "";
    has content: str = "";
    has rank: int = 0;
}

edge Next { }
edge ForkParent { }
edge Subagent { }
edge Owns { }

walker CorpusSearch {
    has query: str = "";
    has role_filter: str = "";
    has hits: list[str] = [];

    can start with Session entry {
        visit [->:Next:->];
    }

    # Live-preferred read: score messages straight off the live chain.
    can score with Message entry {
        if self.role_filter == "" or here.role == self.role_filter {
            lower_content = here.content.lower();
            lower_query = self.query.lower();
            parts = lower_content.split(lower_query);
            rank = len(parts) - 1;
            if rank > 0 {
                self.hits.append(f"[rank {rank}] ({here.role}) {here.content}");
            }
        }
        visit [->:Next:->];
    }

    can report with Session exit {
        for h in self.hits {
            print(h);
        }
    }
}

walker LineageTracer {
    has depth: int = 0;
    has max_depth: int = 8;
    has visited: list[str] = [];

    # Cycle policy: explicit visited guard + depth cap (domain logic).
    can trace with Session entry {
        if here.session_id in self.visited {
            print(f"cycle detected at {here.session_id}");
            disengage;
        }
        self.visited.append(here.session_id);
        if self.depth > self.max_depth {
            print(f"depth cap reached at {here.session_id}");
            disengage;
        }
        self.depth += 1;
        print(f"session {here.session_id} (provider={here.provider}, live={here.is_live})");
        visit [->:ForkParent:->];
        visit [->:Subagent:->];
    }
}

with entry {
    # Fork lineage: main -> forked -> subagent child.
    main = Session(session_id="s-main", provider="anthropic", is_live=True);
    fork = Session(session_id="s-fork", provider="anthropic");
    sub = Session(session_id="s-sub", provider="openai");

    fork +>:ForkParent:+> main;
    fork +>:Subagent:+> sub;

    # Messages: last one appended "one second ago" (the live turn).
    m1 = Message(role="user", content="fix the proxy reconnect loop", ts=100);
    m2 = Message(role="assistant", content="the reconnect loop retries with backoff", ts=101);
    m3 = Message(role="user", content="what about the reconnect loop timeout", ts=102);
    main +>:Next:+> m1;
    m1 +>:Next:+> m2;
    m2 +>:Next:+> m3;

    # Stale index that does NOT yet know about m3 (live-preferred beats it).
    stale = IndexEntry(session_id="s-main", content="the reconnect loop retries with backoff", rank=2);
    main +>:Owns:+> stale;

    print("--- search 'reconnect loop' (live-preferred) ---");
    main spawn CorpusSearch(query="reconnect loop", role_filter="");

    print("--- lineage from fork ---");
    fork spawn LineageTracer();

    print("--- lineage cycle probe (main -> fork back-edge) ---");
    main +>:ForkParent:+> fork;
    main spawn LineageTracer();
}

"""Batched graph reads demo: BFS subgraph and context digest over supersession edges.

Instead of one lookup per node (the issue's pain), each walker gathers a whole
BFS frontier, fetches all its edges at once (a batched ``links_for`` stand-in),
and expands level by level. Cycle guards and node/edge budgets are preserved.
"""

node Memory {
    has title: str = "";
    has pinned: bool = False;
    has supereded_by_id: str = "";  # legacy hand-rolled pointer (unused for traversal)
}

edge Supersedes {
    has strength: int = 1;
}

edge LinksTo { }

walker SubgraphExplorer {
    has seed_ids: list[str] = [];
    has node_budget: int = 10;
    has edge_budget: int = 20;
    has found: list[str] = [];
    has edge_count: int = 0;
    has truncated: bool = False;
    has registry: dict = {};  # id -> Memory, stands in for the batched get_many

    can start with Root entry {
        # one batched read hydrates every seed
        visit [-->];
    }

    can collect with Memory entry {
        self.registry[here.title] = here;
        if len(self.found) < self.node_budget {
            self.found.append(here.title);
            visit [-->];
        } else {
            self.truncated = True;
        }
    }

    can expand_batched with Memory entry {
        # batched adjacency: gather this frontier level's edges in one pass
        frontier = [e for e in here -->:LinksTo:-->];
        if len(self.found) + len(frontier) > self.node_budget {
            self.truncated = True;
        }
        for e in frontier {
            if self.edge_count >= self.edge_budget {
                self.truncated = True;
                disengage;
            }
            self.edge_count += 1;
        }
        visit [-->] else { disengage; }
    }
}

walker ContextDigest {
    has store_edges: int = 0;
    has pinned_now: list[str] = [];
    has superseded: list[str] = [];

    # digest: one pass over ALL edges in the store (batched links_for),
    # computing supersession and inherited pins from in-memory adjacency.
    can digest with Memory entry {
        for edge_ref in [here -->:Supersedes:-->] {
            self.store_edges += 1;
            self.superseded.append(here.title);
        }
        visit [-->] else { disengage; }
    }

    can note_pin with Memory entry {
        if here.pinned {
            self.pinned_now.append(here.title);
        }
    }
}

walker PinPropagator {
    has inherited: dict = {};

    # inherited pins flow down supersession chains; explicit visited-style
    # guard via dict keeps this safe even if a chain ever cycles.
    can walk with Memory entry {
        if here.title in self.inherited {
            disengage;  # cycle guard: already processed this chain node
        }
        if here.pinned {
            self.inherited[here.title] = True;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    # fixture: a supersession chain, a hub node, and a cycle
    a = Memory(title="alpha", pinned=True);
    b = Memory(title="beta");
    c = Memory(title="gamma");
    hub = Memory(title="hub");
    d1 = Memory(title="doc1");
    d2 = Memory(title="doc2");

    root ++> a;
    a +>:Supersedes:+> b;
    b +>:Supersedes:+> c;
    root ++> hub;
    hub --> d1;
    hub --> d2;
    d1 --> d2;
    d2 --> d1;  # cycle among docs

    root spawn ContextDigest();
    root spawn SubgraphExplorer(seed_ids=["alpha", "hub"], node_budget=6);
    root spawn PinPropagator();

    print("digest complete");
}

"""Content-addressed Merkle SBOM storage demo.

Each MerkleNode row is a (subtree_hash, component_id) pair whose children are
typed MerkleChild edges pointing at the child's subtree hash. Two artifacts
that disagree about a shared component get distinct subtree hashes, so their
edge sets coexist; agreeing subtrees collapse onto the same rows. Walkers do
the downward (artifact -> dependencies) and upward (vulnerable component ->
affected roots) traversals, with an explicit visited guard since Jac walkers
do not dedupe on cyclic graphs.
"""

node MerkleNode {
    has subtree_hash: str = "";
    has component_id: str = "";
}

node SbomSource {
    has origin: str = "";
}

edge MerkleChild { }

edge RootOf { }

walker DownwardDeps {
    has visited: dict = {};
    has found: list = [];

    can start with Root entry {
        visit [->:RootOf:->];
    }

    can enter_source with SbomSource entry {
        print(f"--- dependencies for {here.origin} ---");
        visit [->:RootOf:->];
    }

    can descend with MerkleNode entry {
        if here.subtree_hash in self.visited {
            disengage;
        }
        self.visited[here.subtree_hash] = True;
        if here.component_id != "ROOT" {
            self.found.append(here.component_id);
        }
        visit [->:MerkleChild:->] else { disengage; }
    }
}

walker UpwardVuln {
    has target_purl: str = "";
    has visited: dict = {};
    has roots: list = [];

    can seed with MerkleNode entry {
        # only the rows whose component_id matches the vulnerable PURL seed the walk
        if here.component_id != self.target_purl {
            disengage;
        }
        print(f"seeding upward walk from {here.component_id} @ {here.subtree_hash}");
        self.visited[here.subtree_hash] = True;
        visit [<--:MerkleChild:--] else { disengage; }
    }

    can climb with MerkleNode entry {
        if here.subtree_hash in self.visited {
            disengage;
