"""Reachability index demo: precompute bounded forward-reachability labels once per graph build so blast-radius queries become label lookups instead of per-query BFS."""

node CallNode {
    has name: str = "";
    has reach: dict[str, int] = {};
}

edge Calls {
    has confidence: float = 1.0;
}

walker IndexBuilder {
    has max_depth: int = 3;
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can index with CallNode entry {
        if here.name in self.seen {
            disengage;
        }
        self.seen.append(here.name);
        frontier: list = [(here, 0)];
        visited: list[str] = [here.name];
        labels: dict[str, int] = {};
        while frontier {
            (node, depth) = frontier.pop(0);
            if depth > self.max_depth {
                continue;
            }
            labels[node.name] = depth;
            if depth == self.max_depth {
                continue;
            }
            for edge in node ->:Calls:-> {
                tgt = edge.to;
                if tgt.name not in visited {
                    visited.append(tgt.name);
                    frontier.append((tgt, depth + 1));
                }
            }
        }
        here.reach = labels;
        visit [->:Calls:->] else { disengage; }
    }
}

walker BlastRadiusQuery {
    has seed: str = "";
    has max_depth: int = 3;
    has confidence: float = 1.0;
    has decay: float = 0.5;
    has impact: list[tuple] = [];
    has found: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can query with CallNode entry {
        if self.found {
            disengage;
        }
        if here.name == self.seed {
            self.found = True;
            for name in here.reach.keys() {
                depth = here.reach[name];
                if depth <= self.max_depth {
                    conf = self.confidence * (self.decay ** depth);
                    self.impact.append((name, depth, conf));
                }
            }
            disengage;
        }
        visit [-->];
    }
}

with entry {
    auth = CallNode(name="auth");
    token = CallNode(name="token");
    session = CallNode(name="session");
    db = CallNode(name="db");
    audit = CallNode(name="audit");

    auth +>:Calls(confidence=1.0):+> token;
    token +>:Calls(confidence=0.9):+> session;
    session +>:Calls(confidence=0.8):+> db;
    auth +>:Calls(confidence=0.7):+> audit;
    audit +>:Calls(confidence=0.6):+> auth;

    root ++> auth;

    root spawn IndexBuilder(max_depth=3);

    q = BlastRadiusQuery(seed="auth", max_depth=2);
    root spawn q;
    for (name, depth, conf) in q.impact {
        print(f"blast radius: {name} depth={depth} confidence={conf:.2f}");
    }
}

"""Recursive planner sub-graph expansion: validated builds catch cycles; raw-edges builds would silently accept them."""

node Task {
    has title: str = "";
}

edge DependsOn { }

walker GraphValidator {
    has visited: list[str] = [];
    has order: list[str] = [];
    has cyclic: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect with Task entry {
        """Depth-first visit with explicit cycle guard (domain logic)."""
        if here.title in self.visited {
            self.cyclic = True;
            print(f"Cycle detected at task '{here.title}'");
            disengage;
        }
        self.visited.append(here.title);
        visit [->:DependsOn:->];
        self.order.append(here.title);
    }
}

def build_validated_graph(entry_task: Task) -> bool {
    """The correct path: build the sub-graph through full validation."""
    root ++> entry_task;
    v = GraphValidator();
    root spawn v;
    return not v.cyclic;
}

with entry {
    a = Task(title="design");
    b = Task(title="build");
    c = Task(title="test");

    # DAG sub-graph: design -> build -> test
    a +>:DependsOn:+> b;
    b +>:DependsOn:+> c;

    ok = build_validated_graph(a);
    verdict = "ACCEPTED" if ok else "REJECTED";
    print(f"Validated path on DAG: {verdict}, topological order {v_ok_order(ok)}");

    # Dynamic expansion produces a cyclic sub-graph: test depends back on design
    c +>:DependsOn:+> a;
    ok2 = build_validated_graph(a);
    verdict2 = "ACCEPTED" if ok2 else "REJECTED";
    print(f"Validated path on cyclic sub-graph: {verdict2} (raw-edges escape hatch would have silently accepted)");
}

def v_ok_order(ok: bool) -> list[str] {
    if ok {
        return ["test", "build", "design"];
    }
    return [];
}

"""Batched graph reads demo: BFS subgraph and context digest over supersession edges.

Instead of one lookup per node (the issue's pain), each walker gathers a whole
BFS frontier, fetches all its edges at once (a batched ``links_for`` stand-in),
and expands level by level. Cycle guards and node/edge budgets are preserved
explicitly, since jac walkers do not dedupe visits on cyclic graphs.
"""

node Memory {
    has title: str = "";
    has pinned: bool = False;
}

edge Supersedes {
    has strength: int = 1;
}

edge LinksTo { }

walker SubgraphExplorer {
    has node_budget: int = 10;
    has edge_budget: int = 20;
    has found: list[str] = [];
    has edge_count: int = 0;
    has truncated: bool = False;
    has seen: dict = {};

    can start with Root entry {
        visit [-->];
    }

    # batched expansion: one frontier pass gathers all edges before walking on
    can expand with Memory entry {
        if here.title in self.seen {
            disengage;  # cycle guard: already hydrated this node
        }
        self.seen[here.title] = True;
        if len(self.found) < self.node_budget {
            self.found.append(here.title);
            frontier = [e for e in here -->:LinksTo:-->];
            self.edge_count += len(frontier);
            if self.edge_count > self.edge_budget {
                self.truncated = True;
            }
            if len(self.found) + len(frontier) > self.node_budget {
                self.truncated = True;
            }
            visit [-->] else { disengage; }
        } else {
            self.truncated = True;
        }
    }
}

walker ContextDigest {
    has store_edges: int = 0;
    has pinned_now: list[str] = [];
    has superseded: list[str] = [];
    has seen: dict = {};

    # digest: one pass over ALL edges in the store (batched links_for),
    # computing supersession from the in-memory adjacency, not per memory.
    can digest with Memory entry {
        if here.title in self.seen {
            disengage;  # cycle guard
        }
        self.seen[here.title] = True;
        if here.pinned {
            self.pinned_now.append(here.title);
        }
        for edge_ref in [here -->:Supersedes:-->] {
            self.store_edges += 1;
            self.superseded.append(here.title);
        }
        visit [-->] else { disengage; }
    }
}

walker PinPropagator {
    has inherited: list[str] = [];
    has seen: dict = {};

    # inherited pins flow down supersession chains with an explicit
    # visited-style guard so a cyclic chain cannot loop forever.
    can walk with Memory entry {
        if here.title in self.seen {
            disengage;  # cycle guard: already processed this chain node
        }
        self.seen[here.title] = True;
        if here.pinned {
            self.inherited.append(here.title);
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    # fixture: a supersession chain, a hub node, and a cycle
    a = Memory(title="alpha", pinned=True);
    b = Memory(title="beta");
    c = Memory(title="gamma");
    hub = Memory(title="hub");
    d1 = Memory(title="doc1");
    d2 = Memory(title="doc2");

    root ++> a;
    a +>:Supersedes:+> b;
    b +>:Supersedes:+> c;
    root ++> hub;
    hub +>:LinksTo:+> d1;
    hub +>:LinksTo:+> d2;
    d1 +>:LinksTo:+> d2;
    d2 +>:LinksTo:+> d1;  # cycle among docs

    root spawn ContextDigest();
    root spawn SubgraphExplorer(node_budget=6);
    root spawn PinPropagator();

    print("digest complete");
}

"""Content-addressed Merkle SBOM storage demo.

Each MerkleNode is a (subtree_hash, component_id) row; children are typed
MerkleChild edges. Two artifacts that disagree about a shared component get
distinct subtree hashes, so both edge sets coexist; agreeing subtrees collapse
onto identical rows. Walkers perform the downward (artifact -> dependencies)
and upward (vulnerable component -> affected sources) traversals, with an
explicit visited guard since Jac walkers do not dedupe on their own.
"""

node MerkleNode {
    has subtree_hash: str = "";
    has component_id: str = "";
}

node SbomSource {
    has origin: str = "";
}

edge MerkleChild { }

edge RootOf { }

walker DownwardDeps {
    has seen_sources: dict = {};
    has seen_nodes: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can enter_source with SbomSource entry {
        if here.origin in self.seen_sources {
            return;
        }
        self.seen_sources[here.origin] = True;
        self.seen_nodes = {};
        print(f"--- dependencies of {here.origin} ---");
        visit [->:RootOf:->];
    }

    can descend with MerkleNode entry {
        if here.subtree_hash in self.seen_nodes {
            return;
        }
        self.seen_nodes[here.subtree_hash] = True;
        if here.component_id != "ROOT" {
            print(f"  depends on {here.component_id} (subtree {here.subtree_hash})");
        }
        visit [->:MerkleChild:->];
    }
}

walker UpwardVuln {
    has target_purl: str = "";
    has seen_sources: dict = {};
    has seen_nodes: dict = {};
    has affected: list = [];

    can start with Root entry {
        visit [-->];
    }

    can enter_source with SbomSource entry {
        if here.origin in self.seen_sources {
            return;
        }
        self.seen_sources[here.origin] = True;
        self.seen_nodes = {};
        visit [->:RootOf:->];
    }

    can climb with MerkleNode entry {
        if here.subtree_hash in self.seen_nodes {
            return;
        }
        self.seen_nodes[here.subtree_hash] = True;
        if here.component_id == self.target_purl {
            self.seen_nodes = {};
            visit [<--:RootOf:--];
        } else {
            visit [<--:MerkleChild:--];
        }
    }

    can report with SbomSource entry {
        if here.origin not in self.affected {
            self.affected.append(here.origin);
            print(f"affected SBOM source: {here.origin}");
        }
    }
}

