"""Architecture metrics over a dependency graph: cycles, treasure (fan-in), shortest path.

Edges carry resolution confidence; metrics only trust resolved edges.
"""

node File {
    has path: str = "";
    has loc: int = 0;
    has unresolved_refs: int = 0;
}

edge DependsOn {
    has resolved: bool = True;
    has confidence: float = 1.0;
}

walker CycleDetector {
    has seen: dict = {};
    has stack: list = [];
    has cycles: list = [];

    def dfs(node: File) -> bool {
        if node.path in self.stack {
            idx = 0;
            for (i, p) in enumerate(self.stack) {
                if p == node.path { idx = i; }
            }
            self.cycles += [" <-> ".join(self.stack[idx:] + [node.path])];
            return True;
        }
        if node.path in self.seen { return False; }
        self.seen[node.path] = True;
        self.stack += [node.path];
        for conn in [here for here in node --> :DependsOn: if here.resolved] {
            _ = self.dfs(conn);
        }
        self.stack.pop();
        return False;
    }

    can start with File entry {
        _ = self.dfs(here);
        visit [->:DependsOn:->] else { disengage; }
    }

    can done with Root exit {
        report f"cycles found: {len(self.cycles)}";
        for c in self.cycles { print(f"CYCLE: {c}"); }
    }
}

walker TreasureHunter {
    has fan_in: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can tally with File entry {
        parents = [src for src in <--:DependsOn:-- here if src.resolved];
        self.fan_in[here.path] = len(parents);
        visit [-->] else { disengage; }
    }

    can report_treasure with Root exit {
        ranked = sorted(self.fan_in.items(), key=lambda kv: -kv[1]);
        print("TREASURE (most depended-on, resolved edges only):");
        for (path, n) in ranked {
            print(f"  {path}: fan_in={n}");
        }
    }
}

walker Adventure {
    has target: str = "";
    has best: dict = {};
    has queue: list = [];
    has found: int = -1;

    can start with File entry {
        self.best[here.path] = 0;
        self.queue += [(here, 0)];
        while self.queue {
            (cur, d) = self.queue.pop(0);
            if cur.path == self.target {
                self.found = d;
                disengage;
            }
            for nxt in [h for h in cur --> :DependsOn: if h.resolved] {
                if nxt.path not in self.best {
                    self.best[nxt.path] = d + 1;
                    self.queue += [(nxt, d + 1)];
                }
            }
        }
        disengage;
    }

    can done with Root exit {
        verdict = f"{self.found} hops" if self.found >= 0 else "unreachable (resolved edges)";
        print(f"shortest path to {self.target}: {verdict}");
    }
}

