"""Recursive planner sub-graph: validated builds catch cycles; raw-edges builds would silently accept them."""

node Task {
    has title: str = "";
}

edge DependsOn { }

walker GraphValidator {
    has visited: list[str] = [];
    has cyclic: bool = False;

    can inspect with Task entry {
        """Depth-first visit with explicit cycle guard (domain logic)."""
        if here.title in self.visited {
            self.cyclic = True;
            print(f"Cycle detected at task '{here.title}'");
            disengage;
        }
        self.visited.append(here.title);
        visit [->:DependsOn:->] else {
            self.visited.append("done:" + here.title);
            disengage;
        }
    }
}

def build_validated_graph(entry_task: Task) -> bool {
    """The correct path: validate the sub-graph through full traversal."""
    v = GraphValidator();
    entry_task spawn v;
    return not v.cyclic;
}

with entry {
    a = Task(title="design");
    b = Task(title="build");
    c = Task(title="test");

    # DAG sub-graph: design -> build -> test
    a +>:DependsOn:+> b;
    b +>:DependsOn:+> c;

    ok = build_validated_graph(a);
    verdict = "ACCEPTED" if ok else "REJECTED";
    print(f"Validated path on DAG: {verdict}, visit order {GraphValidator().visited}");

    # Dynamic expansion produces a cyclic sub-graph: test depends back on design
    c +>:DependsOn:+> a;
    v2 = GraphValidator();
    a spawn v2;
    verdict2 = "ACCEPTED" if not v2.cyclic else "REJECTED";
    print(f"Validated path on cyclic sub-graph: {verdict2} "
          f"(raw-edges escape hatch would have silently accepted)");
}

"""Reachability index demo: precompute bounded forward-reachability labels once per graph build so blast-radius queries become label lookups instead of per-query BFS."""

node CallNode {
    has name: str = "";
    has reach: dict[str, int] = {};
}

edge Calls {
    has confidence: float = 1.0;
}

walker DepthMarker {
    has depth: int = 0;
    has max_depth: int = 3;

    can measure with CallNode entry {
        if self.depth > self.max_depth {
            disengage;
        }
        known = here.reach.get(here.name, self.max_depth + 1);
        if known <= self.depth {
            disengage;
        }
        here.reach[here.name] = self.depth;
        if self.depth < self.max_depth {
            here spawn DepthMarker(depth=self.depth + 1, max_depth=self.max_depth);
        }
    }
}

walker IndexBuilder {
    has max_depth: int = 3;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can index with CallNode entry {
        here.reach = {};
        here spawn DepthMarker(max_depth=self.max_depth);
        visit [-->] else { disengage; }
    }
}

walker BlastRadiusQuery {
    has seed: str = "";
    has max_depth: int = 3;
    has confidence: float = 1.0;
    has decay: float = 0.5;
    has impact: list[tuple] = [];
    has found: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can query with CallNode entry {
        if self.found {
            disengage;
        }
        if here.name == self.seed {
            self.found = True;
            for name in here.reach.keys() {
                depth = here.reach[name];
                if depth <= self.max_depth {
                    conf = self.confidence * (self.decay ** depth);
                    self.impact.append((name, depth, conf));
                }
            }
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

