"""Batched graph reads demo: BFS subgraph and context digest over supersession edges.

Each walker gathers a whole BFS frontier per level (the batched ``links_for``
stand-in from the issue) instead of one lookup per node. Cycle guards, node
and edge budgets, and inherited-pin semantics are preserved explicitly, since
jac walkers do not dedupe visits on cyclic graphs.
"""

node Memory {
    has title: str = "";
    has pinned: bool = False;
}

edge Supersedes {
    has strength: int = 1;
}

edge LinksTo { }

walker SubgraphExplorer {
    has node_budget: int = 10;
    has edge_budget: int = 20;
    has found: list[str] = [];
    has edge_count: int = 0;
    has truncated: bool = False;
    has seen: dict = {};

    can start with Root entry {
        visit [-->];
    }

    # batched expansion: hydrate the node once, then expand its whole
    # frontier in a single pass; already-seen nodes are skipped, never
    # re-visited, so the cyclic fixture terminates.
    can expand with Memory entry {
        if here.title in self.seen {
            return;
        }
        self.seen[here.title] = True;
        if len(self.found) >= self.node_budget {
            self.truncated = True;
            return;
        }
        self.found.append(here.title);
        frontier = [n for n in [here -->]];
        self.edge_count += len(frontier);
        if self.edge_count > self.edge_budget {
            self.truncated = True;
        }
        if len(self.found) + len(frontier) > self.node_budget {
            self.truncated = True;
        }
        visit [-->] else { disengage; }
    }
}

walker ContextDigest {
    has superseded: list[str] = [];
    has pinned_effective: list[str] = [];
    has seen: dict = {};

    # digest: one pass over the supersession adjacency (batched read),
    # computing superseded memories and inherited pins in memory.
    can digest with Memory entry {
        if here.title in self.seen {
            return;
        }
        self.seen[here.title] = True;
        if here.pinned {
            self.pinned_effective.append(here.title);
        }
        newer = [n for n in [here ->:Supersedes:->]];
        for target in newer {
            self.superseded.append(target.title);
            if here.pinned and not target.pinned {
                self.pinned_effective.append(target.title);
            }
        }
        visit [->:Supersedes:->] else { disengage; }
    }
}

with entry {
    # fixture: a supersession chain with an inherited pin, a hub node,
    # and a cycle among the docs
    a = Memory(title="alpha", pinned=True);
    b = Memory(title="beta");
    c = Memory(title="gamma");
    hub = Memory(title="hub");
    d1 = Memory(title="doc1");
    d2 = Memory(title="doc2");

    root ++> a;
    a +>:Supersedes:+> b;
    b +>:Supersedes:+> c;
    root ++> hub;
    hub +>:LinksTo:+> d1;
    hub +>:LinksTo:+> d2;
    d1 +>:LinksTo:+> d2;
    d2 +>:LinksTo:+> d1;  # cycle among docs

    digest = ContextDigest();
    root spawn digest;
    explorer = SubgraphExplorer(node_budget=6);
    root spawn explorer;

    print(f"superseded: {digest.superseded}");
    print(f"effective pins (incl. inherited): {digest.pinned_effective}");
    print(f"subgraph nodes: {explorer.found}, truncated: {explorer.truncated}, edges: {explorer.edge_count}");
}

"""Content-addressed Merkle SBOM storage demo.

Each MerkleNode is a (subtree_hash, component_id) row; children are typed
MerkleChild edges. Two artifacts that disagree about a shared component get
distinct subtree hashes, so both edge sets coexist; agreeing subtrees collapse
onto identical rows. Walkers perform the downward (artifact -> dependencies)
traversal and the upward query (vulnerable component -> affected sources) by
descending each source's tree looking for the vulnerable PURL, with an
explicit visited guard since Jac walkers do not dedupe on their own.
"""

node MerkleNode {
    has subtree_hash: str = "";
    has component_id: str = "";
}

node SbomSource {
    has origin: str = "";
}

edge MerkleChild { }

edge RootOf { }

walker DownwardDeps {
    has seen_sources: dict[str, bool] = {};
    has seen_nodes: dict[str, bool] = {};

    can start with Root entry {
        visit [-->];
    }

    can enter_source with SbomSource entry {
        if here.origin in self.seen_sources {
            disengage;
        }
        self.seen_sources[here.origin] = True;
        self.seen_nodes = {};
        print(f"--- dependencies of {here.origin} ---");
        visit [->:RootOf:->];
    }

    can descend with MerkleNode entry {
        if here.subtree_hash in self.seen_nodes {
            disengage;
        }
        self.seen_nodes[here.subtree_hash] = True;
        if here.component_id != "ROOT" {
            print(f"  depends on {here.component_id} (subtree {here.subtree_hash})");
        }
        visit [->:MerkleChild:->] else { disengage; }
    }
}

walker VulnScan {
    has target_purl: str = "";
    has seen_sources: dict[str, bool] = {};
    has seen_nodes: dict[str, bool] = {};
    has hit_here: bool = False;
    has affected: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can enter_source with SbomSource entry {
        if here.origin in self.seen_sources {
            disengage;
        }
        self.seen_sources[here.origin] = True;
        self.seen_nodes = {};
        self.hit_here = False;
        visit [->:RootOf:->];
    }

    can descend with MerkleNode entry {
        if here.subtree_hash in self.seen_nodes {
            disengage;
        }
        self.seen_nodes[here.subtree_hash] = True;
        if here.component_id == self.target_purl {
            self.hit_here = True;
        }
        visit [->:MerkleChild:->] else {
            if self.hit_here and here.origin == "" {
                pass;
            }
            disengage;
        }
    }

    can finish_source with SbomSource exit {
        if self.hit_here {
            self.affected.append(here.origin);
            print(f"affected SBOM source: {here.origin}");
        }
    }
}

with entry {
    # Shared component: both artifacts reference circl@v1.6.3, but they
    # disagree about its children, so two distinct subtree rows coexist.
    circl_a = MerkleNode(subtree_hash="h-circl-A", component_id="pkg:npm/circl@v1.6.3");
    circl_b = MerkleNode(subtree_hash="h-circl-B", component_id="pkg:npm/circl@v1.6.3");

    # Source 1: ROOT -> circl -> lodash@4.17.20
    lodash = MerkleNode(subtree_hash="h-lodash", component_id="pkg:npm/lodash@4.17.20");
    root1 = MerkleNode(subtree_hash="h-root1", component_id="ROOT");
    root1 +>:MerkleChild:+> circl_a;
    circl_a +>:MerkleChild:+> lodash;

    # Source 2 disagrees: ROOT -> circl (no further children)
    root2 = MerkleNode(subtree_hash="h-root2", component_id="ROOT");
    root2 +>:MerkleChild:+> circl_b;

    src1 = SbomSource(origin="sbom:package-lock.json");
