"""Session cost rollup: walk the session tree so subagent spend is counted, not dropped."""

node Session {
    has session_id: str = "";
    has parent_id: str | None = None;
}

edge Spawned { }

node Message {
    has role: str = "";
    has cost: float = 0.0;
    has created_at: int = 0;
}

edge Posted { }

walker CostAuditor {
    has cutoff: int = 0;
    has total_cost: float = 0.0;
    has calls: int = 0;
    has include_subagents: bool = True;
    has seen: dict = {};

    can start with Root entry {
        visit [->:Spawned:->] else { disengage; }
    }

    can tally with Session entry {
        if here.session_id in self.seen {
            disengage;
        }
        self.seen[here.session_id] = True;
        visit [->:Posted:->];
        if self.include_subagents {
            visit [->:Spawned:->] else { disengage; }
        }
    }

    can charge with Message entry {
        if here.role == "assistant" and here.created_at >= self.cutoff {
            self.total_cost += here.cost;
            self.calls += 1;
        }
    }
}

