"""Cycle-safe deep copy: walkers mirror the rewriter's visited set so cyclic documents copy without infinite recursion."""

node Schema {
    has type_name: str = "object";
    can copy_into(dst: Schema) {
        dst.type_name = self.type_name;
    }
}

node Encoding {
    can copy_into(dst: Encoding) {
    }
}

node MediaType {
    can copy_into(dst: MediaType) {
    }
}

edge HasProperty {
    has name: str = "";
}

edge HasEncoding { }

edge HasPart {
    has name: str = "";
}

edge CopiedTo { }

walker DeepCopy {
    has visited: dict = {};
    has copied: list = [];

    can start with Root entry {
        visit [-->];
    }

    can copy_schema with Schema entry {
        if here in self.visited.keys() {
            print(f"cycle hit at schema {here.type_name}; reusing existing copy");
            visit [-->] else { disengage; }
        }
        copy = Schema(type_name=here.type_name);
        here +>:CopiedTo:+> copy;
        self.visited[here] = copy;
        self.copied += [copy];
        print(f"copied schema {here.type_name}");
        visit [->:HasProperty:->] else { disengage; }
    }

    can copy_encoding with Encoding entry {
        if here in self.visited.keys() {
            print("cycle hit at encoding; reusing existing copy");
            visit [-->] else { disengage; }
        }
        copy = Encoding();
        here +>:CopiedTo:+> copy;
        self.visited[here] = copy;
        self.copied += [copy];
        print("copied encoding");
        visit [->:HasEncoding:->] else { disengage; }
    }

    can copy_media with MediaType entry {
        copy = MediaType();
        here +>:CopiedTo:+> copy;
        self.visited[here] = copy;
        self.copied += [copy];
        print("copied media type");
        visit [->:HasPart:->] else { disengage; }
    }

    can rejoin with HasProperty exit {
        src = here.from;
        dst_schema = self.visited.get(src, None);
        dst_child = self.visited.get(here.to, None);
        if dst_schema is not None and dst_child is not None {
            dst_schema +>:HasProperty(name=here.name):+> dst_child;
        }
    }

    can rejoin_enc with HasEncoding exit {
        src = here.from;
        dst_enc = self.visited.get(src, None);
        dst_child = self.visited.get(here.to, None);
        if dst_enc is not None and dst_child is not None {
            dst_enc +>:HasEncoding:+> dst_child;
        }
    }

    can rejoin_part with HasPart exit {
        src = here.from;
        dst_mt = self.visited.get(src, None);
        dst_child = self.visited.get(here.to, None);
        if dst_mt is not None and dst_child is not None {
            dst_mt +>:HasPart(name=here.name):+> dst_child;
        }
    }
}

with entry {
    # Schema that contains itself (issue reproduction 1)
    s = Schema(type_name="object");
    s +>:HasProperty(name="self"):+> s;

    # Encoding nested under itself (reproduction 2)
    e = Encoding();
    e +>:HasEncoding:+> e;

    # Media type that reaches the cyclic encoding (reproduction 3)
    mt = MediaType();
    mt +>:HasPart(name="part"):+> e;

