"""Architecture metrics over a dependency graph: cycles, treasure/fan-in, lost code, shortest path.

Resolved dependencies are typed DependsOn edges; unresolved references are
separate UnresolvedRef edges so metrics only ever traverse resolved edges.
No walker relies on visitation over cyclic parts of the graph, so the
A <-> B cycle cannot hang traversal.
"""

node File {
    has path: str = "";
    has loc: int = 0;
    has unresolved_refs: int = 0;
}

edge DependsOn { }
edge UnresolvedRef { has confidence: float = 0.3; }

walker CycleDetector {
    has seen: dict = {};
    has stack: list = [];
    has cycles: list = [];

    def dfs(node: File) -> None {
        if node.path in self.stack {
            idx = 0;
            for (i, p) in enumerate(self.stack) {
                if p == node.path { idx = i; }
            }
            self.cycles += [" <-> ".join(self.stack[idx:] + [node.path])];
            return;
        }
        if node.path in self.seen { return; }
        self.seen[node.path] = True;
        self.stack += [node.path];
        for nxt in [t for t in node --> :DependsOn:] {
            self.dfs(nxt);
        }
        self.stack.pop();
        return;
    }

    can start with Root entry {
        visit [-->];
    }

    can scan with File entry {
        self.dfs(here);
    }

    can done with Root exit {
        print(f"CYCLES (resolved edges only): {len(self.cycles)}");
        for c in self.cycles {
            print(f"  CYCLE: {c}");
        }
    }
}

