    has fan_in: dict = {};
    has unresolved_in: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can tally with File entry {
        if here.path not in self.fan_in {
            self.fan_in[here.path] = 0;
            self.unresolved_in[here.path] = here.unresolved_refs;
        }
        for nxt in [t for t in here --> :DependsOn:] {
            self.fan_in[nxt.path] = self.fan_in.get(nxt.path, 0) + 1;
        }
        visit [-->] else { disengage; }
    }

    can report with Root exit {
        ranked = sorted(self.fan_in.items(), key=lambda kv: -kv[1]);
        print("TREASURE (most depended-on, resolved fan-in):");
        for (path, n) in ranked {
            print(f"  {path}: fan_in={n}");
        }
        print("LOST (zero resolved and zero unresolved in-corpus references):");
        for path in self.fan_in {
            if self.fan_in[path] == 0 and self.unresolved_in[path] == 0 {
                print(f"  {path} (dead-ish code candidate)");
            }
        }
    }
}

walker Adventure {
    has target: str = "";
    has best: dict = {};
    has queue: list = [];
    has found: int = -1;

    can start with File entry {
        self.best[here.path] = 0;
        self.queue += [(here, 0)];
        while self.queue {
            (cur, d) = self.queue.pop(0);
            if cur.path == self.target {
                self.found = d;
                disengage;
