"""Cycle-safe deep copy: a visited set (mirrored by CopiedTo edges) lets the copy walker preserve cycles instead of recursing forever."""

node Schema {
    has type_name: str = "object";
}

node Encoding { }

node MediaType { }

edge HasProperty {
    has name: str = "";
}

edge HasEncoding { }

edge HasPart {
    has name: str = "";
}

edge CopiedTo { }

walker DeepCopy {
    has copied: int = 0;
    has cycles: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    def has_copy(n: Schema | Encoding | MediaType) -> bool {
        return len([n->:CopiedTo:->]) > 0;
    }

    def snapshot(n: Schema | Encoding | MediaType) {
        if self.has_copy(n) {
            self.cycles += 1;
            print("cycle detected; reusing existing copy instead of recursing");
            return;
        }
        if n isa Schema {
            n +>:CopiedTo:+> Schema(type_name=n.type_name);
        } else if n isa Encoding {
            n +>:CopiedTo:+> Encoding();
        } else {
            n +>:CopiedTo:+> MediaType();
        }
        self.copied += 1;
    }

    can copy_schema with Schema entry {
        self.snapshot(here);
        visit [->:HasProperty:->] else { disengage; }
    }

    can copy_encoding with Encoding entry {
        self.snapshot(here);
        visit [->:HasEncoding:->] else { disengage; }
    }

    can copy_media with MediaType entry {
        self.snapshot(here);
        visit [->:HasPart:->] else { disengage; }
    }
}

walker RebuildCopy {
    has edges: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can relink_schema with Schema entry {
        src = [here->:CopiedTo:->][0];
        for prop in [here->:HasProperty:->] {
            tgt = [prop->:CopiedTo:->][0];
            src +>:HasProperty(name=prop.name):+> tgt;
            self.edges += 1;
        }
        visit [-->] else { disengage; }
    }

    can relink_media with MediaType entry {
        src = [here->:CopiedTo:->][0];
        for part in [here->:HasPart:->] {
            tgt = [part->:CopiedTo:->][0];
            src +>:HasPart(name=part.name):+> tgt;
            self.edges += 1;
        }
        visit [-->] else { disengage; }
    }

    can relink_encoding with Encoding entry {
        src = [here->:CopiedTo:->][0];
        for enc in [here->:HasEncoding:->] {
            tgt = [enc->:CopiedTo:->][0];
            src +>:HasEncoding:+> tgt;
            self.edges += 1;
        }
    }
}

with entry {
    # Schema that contains itself (issue reproduction 1)
    s = Schema(type_name="object");
    s +>:HasProperty(name="self"):+> s;

    # Encoding nested under itself (reproduction 2)
    e = Encoding();
    e +>:HasEncoding:+> e;

    # Media type that reaches the cyclic encoding (reproduction 3)
    mt = MediaType();
    mt +>:HasPart(name="part"):+> e;

    root ++> s ++> mt;

    copier = DeepCopy();
    root spawn copier;
    print(f"copy pass: {copier.copied} nodes copied, {copier.cycles} cycles preserved");

