"""Cycle-safe deep copy: a visited set lets the copy walker preserve cycles instead of recursing forever."""

node Schema {
    has type_name: str = "object";
}

node Encoding {
    has part_name: str = "";
}

node MediaType { }

edge HasProperty {
    has name: str = "";
}

edge HasEncoding { }

edge HasPart {
    has name: str = "";
}

edge CopiedTo { }

walker DeepCopy {
    has seen: list = [];
    has copied: int = 0;
    has cycles: int = 0;

    def is_new(n: Schema | Encoding | MediaType) -> bool {
        if n in self.seen {
            return False;
        }
        self.seen.append(n);
        return True;
    }

    can start with Root entry {
        visit [-->] else { }
    }

    can copy_schema with Schema entry {
        if not self.is_new(here) {
            self.cycles += 1;
            print("cycle detected at schema; reusing existing copy");
        } else {
            here +>:CopiedTo:+> Schema(type_name=here.type_name);
            self.copied += 1;
            if len([here->:HasProperty:->]) > 0 {
                visit [->:HasProperty:->];
            }
        }
    }

    can copy_encoding with Encoding entry {
        if not self.is_new(here) {
            self.cycles += 1;
            print("cycle detected at encoding; reusing existing copy");
        } else {
            here +>:CopiedTo:+> Encoding(part_name=here.part_name);
            self.copied += 1;
            if len([here->:HasEncoding:->]) > 0 {
                visit [->:HasEncoding:->];
            }
        }
    }

    can copy_media with MediaType entry {
        if not self.is_new(here) {
            self.cycles += 1;
        } else {
            here +>:CopiedTo:+> MediaType();
            self.copied += 1;
            if len([here->:HasPart:->]) > 0 {
                visit [->:HasPart:->];
            }
        }
    }
}

walker RebuildCopy {
    has seen: list = [];
    has edges: int = 0;

    def is_new(n: Schema | Encoding | MediaType) -> bool {
        if n in self.seen {
            return False;
        }
        self.seen.append(n);
        return True;
    }

    def relink(src: Schema | Encoding | MediaType, tgt: Schema | Encoding | MediaType) {
        src->:CopiedTo:->[0] +>:CopiedTo:+> tgt->:CopiedTo:->[0];
        self.edges += 1;
    }

    can start with Root entry {
        visit [-->] else { }
    }

    can relink_schema with Schema entry {
        if self.is_new(here) {
            for prop in [here->:HasProperty:->] {
                self.relink(here, prop);
                prop +>:HasProperty(name=prop.name):+> prop->:CopiedTo:->[0];
            }
            if len([here->:HasProperty:->]) > 0 {
                visit [->:HasProperty:->];
            }
        }
    }

    can relink_encoding with Encoding entry {
        if self.is_new(here) {
            for enc in [here->:HasEncoding:->] {
                self.relink(here, enc);
                here->:CopiedTo:->[0] +>:HasEncoding:+> enc->:CopiedTo:->[0];
            }
            if len([here->:HasEncoding:->]) > 0 {
                visit [->:HasEncoding:->];
            }
        }
    }

    can relink_media with MediaType entry {
        if self.is_new(here) {
            for part in [here->:HasPart:->] {
                here->:CopiedTo:->[0] +>:HasPart(name=part.name):+> part->:CopiedTo:->[0];
                if len([part->:HasEncoding:->]) > 0 {
                    visit [->:HasPart:->];
                }
            }
        }
    }
}

with entry {
    # Schema that contains itself (issue reproduction 1)
    s = Schema(type_name="object");
    s +>:HasProperty(name="self"):+> s;

    # Encoding nested under itself (reproduction 2)
    e = Encoding(part_name="self");
    e +>:HasEncoding:+> e;

    # Media type that reaches the cyclic encoding (reproduction 3)
    mt = MediaType();
    mt +>:HasPart(name="part"):+> e;

    root ++> s;
    root ++> mt;

    copier = DeepCopy();
    root spawn copier;
    print(f"copy pass: {copier.copied} nodes copied, {copier.cycles} cycles preserved");

    rebuilder = RebuildCopy();
    root spawn rebuilder;
    print(f"rebuild pass: {rebuilder.edges} edges linked in the copies");

    copied_s = s->:CopiedTo:->[0];
    back = copied_s->:HasProperty(name="self"):->;
    print(f"copy of schema links back to itself: {len(back) == 1}");

    copied_mt = mt->:CopiedTo:->[0];
    copied_e = copied_mt->:HasPart(name="part"):->[0]->:CopiedTo:->[0];
    inner = copied_e->:HasEncoding:->;
    print(f"copy of encoding nested in media type links back to itself: {inner[0] == copied_e}");
}

