walker DeleteCmd {
    has budget_ms: int = 30000;
    has elapsed_ms: int = 0;
    has deleted_count: int = 0;
    has halted_reason: str = "";
    has seen: list[str] = [];

    def mark(nm: str) -> bool {
        for existing in self.seen {
            if existing == nm {
                return False;
            }
        }
        self.seen.append(nm);
        return True;
    }

    can start with Root entry {
        visit [->:Child:->] else { disengage; }
    }

    can sweep with ProfileRoot entry {
