    can delete with FileNode entry {
        if not self.mark(here.name) {
            disengage;
        }
        self.elapsed_ms += 500;
        if self.elapsed_ms >= self.budget_ms {
            self.halted_reason = "tool timeout";
            disengage;
        }
        self.deleted_count += 1;
        visit [->:Child:->] else { disengage; }
    }
}

