"""Architecture metrics over a dependency graph: cycles, treasure/fan-in, lost code, shortest path.

Resolved dependencies are typed DependsOn edges; unresolved references are
separate UnresolvedRef edges so metrics only ever traverse resolved edges.
Walkers reach files only over Contains edges (an acyclic spine); cyclic
DependsOn edges are explored solely by an explicit DFS with a seen-set, so
the A <-> B cycle cannot hang visitation.
"""

node File {
    has path: str = "";
    has loc: int = 0;
    has unresolved_refs: int = 0;
}

edge Contains { }
edge DependsOn { }
edge UnresolvedRef { has confidence: float = 0.3; }

walker CycleDetector {
    has seen: dict = {};
    has stack: list = [];
    has cycles: list = [];

    def dfs(node: File) -> None {
        if node.path in self.stack {
            idx = 0;
            for (i, p) in enumerate(self.stack) {
                if p == node.path { idx = i; }
            }
            self.cycles += [" <-> ".join(self.stack[idx:] + [node.path])];
            return;
        }
        if node.path in self.seen { return; }
        self.seen[node.path] = True;
        self.stack += [node.path];
        for nxt in [t for t in node --> :DependsOn:] {
            self.dfs(nxt);
        }
        self.stack.pop();
        return;
    }

    can start with Root entry {
        visit [->:Contains:->];
    }

    can scan with File entry {
        self.dfs(here);
        visit [->:Contains:->] else { disengage; }
    }

    can done with Root exit {
        print(f"CYCLES (resolved edges only): {len(self.cycles)}");
        for c in self.cycles {
            print(f"  CYCLE: {c}");
        }
    }
}

walker TreasureHunter {
    has fan_in: dict = {};
    has unresolved_in: dict = {};

    can start with Root entry {
        visit [->:Contains:->];
    }

    can tally with File entry {
        if here.path not in self.fan_in {
            self.fan_in[here.path] = 0;
            self.unresolved_in[here.path] = here.unresolved_refs;
        }
        for nxt in [t for t in here --> :DependsOn:] {
            self.fan_in[nxt.path] = self.fan_in.get(nxt.path, 0) + 1;
        }
        visit [->:Contains:->] else { disengage; }
    }

    can report with Root exit {
        ranked = sorted(self.fan_in.items(), key=lambda kv: -kv[1]);
        print("TREASURE (most depended-on, resolved fan-in):");
        for (path, n) in ranked {
            print(f"  {path}: fan_in={n}");
        }
        print("LOST (zero resolved and zero unresolved in-corpus references):");
        for path in self.fan_in {
            if self.fan_in[path] == 0 and self.unresolved_in[path] == 0 {
                print(f"  {path} (dead-ish code candidate)");
            }
        }
    }
}

walker Adventure {
    has target: str = "";
    has best: dict = {};
    has queue: list = [];
    has found: int = -1;

    can start with File entry {
        self.best[here.path] = 0;
        self.queue += [(here, 0)];
        while self.queue {
            (cur, d) = self.queue.pop(0);
            if cur.path == self.target {
                self.found = d;
                disengage;
            }
            for nxt in [t for t in cur --> :DependsOn:] {
                if nxt.path not in self.best {
                    self.best[nxt.path] = d + 1;
                    self.queue += [(nxt, d + 1)];
                }
            }
        }
        disengage;
    }
}

with entry {
    # Spine root -> A -> B -> C via Contains; a resolved A <-> B cycle and an
    # unresolved external reference from C back to A (excluded from metrics).
    a = File(path="src/ingest.rs", loc=320, unresolved_refs=0);
    b = File(path="src/index.rs", loc=540, unresolved_refs=0);
    c = File(path="src/cli.rs", loc=180, unresolved_refs=0);
    root +>:Contains:+> a;
    a +>:Contains:+> b;
    b +>:Contains:+> c;
    a +>:DependsOn:+> b;
    b +>:DependsOn:+> a;   # the cycle back-edge
    b +>:DependsOn:+> c;
    c +>:UnresolvedRef(confidence=0.4):+> a;   # unresolved: excluded from metrics

    root spawn CycleDetector();
    root spawn TreasureHunter();
    a spawn Adventure(target="src/cli.rs");
}

"""Cartography canonical map: typed topology with bounded traversal and authority-preserving reconciliation.

Demonstrates BTN-98's core scenario: a MapRevision connects Domains and Symbols
via typed Relationship edges. A Reconciler walker walks bounded dependency
topology with an explicit cycle guard (no built-in once-per-node visitation),
while human-authored InstitutionalConstraints survive traversal untouched:
the walker inspects but never overwrites them, and ambiguous reconciliation
leaves a PossibleSuccessor edge for later inspection instead of merging.
"""

node MapRevision {
    has title: str = "";
    has schema_version: int = 1;
    has published: bool = False;
}

node Domain {
    has name: str = "";
    has authority: str = "generated";
    has fresh: bool = True;
}

node Symbol {
    has name: str = "";
    has revision_evidence: str = "";
    has available: bool = True;
}

edge RelatedTo { }
edge Contains { }
edge PossibleSuccessor { has reason: str = ""; }

walker Reconciler {
    has visited: dict = {};
    has depth_limit: int = 4;
    has depth: int = 0;
    has found: list = [];

    can start with MapRevision entry {
        if self.depth >= self.depth_limit {
            print("depth limit reached, ending revision walk");
            disengage;
        }
        self.visited[here] = True;
        print(f"reconciling revision '{here.title}' (schema v{here.schema_version})");
        visit [->:Contains:->];
        visit [->:RelatedTo:->];
    }

    can inspect_domain with Domain entry {
        if here in self.visited {
            disengage;
        }
        self.visited[here] = True;
        self.depth += 1;
        state = "HUMAN" if here.authority == "actor" else "generated";
        self.found += [f"{state}:{here.name}"];
        print(f"[{state}] domain {here.name} fresh={here.fresh}");
        # Human-authored records are inspected, never rewritten.
        if here.authority != "actor" {
            here.fresh = True;
        }
        visit [->:Contains:->];
        visit [->:RelatedTo:->];
    }

    can inspect_symbol with Symbol entry {
        if here in self.visited {
            disengage;
        }
        self.visited[here] = True;
        status = "OK" if here.available else "MISSING";
        self.found += [f"symbol:{here.name}:{status}"];
        print(f"[{status}] symbol {here.name} (evidence {here.revision_evidence})");
        visit [->:PossibleSuccessor:->] else {
            disengage;
        }
    }

    can report with Symbol exit {
        print(f"reconciler exit at symbol {here.name}");
    }
}

with entry {
    rev = MapRevision(title="BTN-98 canonical map", schema_version=1, published=True);

    core = Domain(name="core", authority="generated");
    human = Domain(name="conventions", authority="actor");
    sym_a = Symbol(name="battalion.cartography", revision_evidence="path:cart.py@rev1");
    sym_b = Symbol(name="cartography_core", revision_evidence="path:cart/core.py@rev2");

    rev +>:Contains:+> core;
    rev +>:Contains:+> human;
    core +>:Contains:+> sym_a;
    core +>:RelatedTo:+> human;
    # Ambiguous rename: do NOT merge identities; keep inspectable successor edge.
    sym_a +>:PossibleSuccessor(reason="rename ambiguous, identity not merged"):+> sym_b;

    root ++> rev;
    root spawn Reconciler(depth_limit=4);
    print(f"reconciler observed {len(re.found)} records: {re.found}");
}

"""Recursive CTE dialect adapter: a planner walker visits dialect nodes,
emits each engine's WITH spelling, then walks a bounded recursive term
chain with an explicit depth cap (the engines' recursion limit)."""

node Dialect {
    has name: str = "";
    has recursive_keyword: str = "WITH RECURSIVE";
    has needs_column_list: bool = False;
    has max_recursion: int = 100;
}

