    has name: str = "";
    has depth: int = 0;
}

edge NextTerm { }

walker DialectPlanner {
    has columns: str = "";
    has cte_name: str = "org_tree";
    has max_depth: int = 5;

    can start with Root entry {
        visit [->:Supports:->];
    }

    can compile with Dialect entry {
        cols = f"({self.columns}) " if self.columns else "";
        print(f"[{here.name}] {here.recursive_keyword} {cols}{self.cte_name} AS (...); "
              f"engine recursion cap {here.max_recursion}");
        visit [->:SeedsTerm:->] else { disengage; }
    }

    can walk_terms with CteTerm entry {
        if here.depth > self.max_depth {
            print(f"recursion depth cap {self.max_depth} hit at term "
                  f"'{here.name}' — stop condition enforced");
            disengage;
        }
        print(f"  term '{here.name}' (depth {here.depth})");
        visit [->:NextTerm:->] else { disengage; }
    }
}

with entry {
