    oracle = Dialect(name="Oracle", recursive_keyword="WITH",
                     needs_column_list=True, max_recursion=0);
    root +>:Supports:+> pg;
    root +>:Supports:+> mssql;
    root +>:Supports:+> oracle;

    anchor = CteTerm(name="anchor", depth=0);
