"""Cycle-safe traversal: a walker that carries its own visited set of node
anchors so a cyclic graph (even a self-loop) terminates after one visit
per node, instead of spinning forever as in issue #8562."""

node GraphNode {
    has tag: str = "";
}

edge Link {
    has weight: int = 0;
}

walker CycleAwareWalker {
    has visited: dict = {};

    can start with Root entry {
        print("beginning traversal");
        visit [->:Link:->];
    }

    can go with GraphNode entry {
        if here in self.visited {
            print(f"cycle detected at {here.tag}, skipping re-visit");
            disengage;
        }
        self.visited[here] = True;
        print(f"visited {here.tag}");
        visit [->:Link:->] else {
            print("dead end");
            disengage;
        }
    }
}

walker ParallelEdgeCounter {
    has seen: dict = {};
    has count: int = 0;

    can start with Root entry {
        visit [->:Link:->];
    }

    can tally with GraphNode entry {
        if here in self.seen {
            disengage;
        }
        self.seen[here] = True;
        for edge_ref in [here->:Link:<-] {
            self.count += 1;
        }
        print(f"{here.tag} reached; incoming parallel edges so far: {self.count}");
        visit [->:Link:->] else { disengage; }
    }
}

with entry {
    # a self-loop: a -> a, plus a longer cycle a -> b -> a
    a = GraphNode(tag="A");
    b = GraphNode(tag="B");
    a +>:Link(weight=1):+> a;
    a +>:Link(weight=2):+> b;
    b +>:Link(weight=3):+> a;
    root ++> a;

    root spawn CycleAwareWalker();
    root spawn ParallelEdgeCounter();
}

"""TreeDB row-asset writer: pad fixed-width spans to natural alignment and certify the layout.

Old/non-certified layouts fail closed; padding bytes are accounted per span.
"""

node RowAsset {
    has name: str = "";
    has format_version: int = 2;      # versioned pre-alpha contract
    has certified: bool = False;      # fail-closed until writer certifies
    has row_count: int = 0;
    has total_bytes: int = 0;
    has pad_bytes: int = 0;

    def is_direct_view_eligible() -> bool {
        return self.certified and self.format_version >= 2;
    }
}

node FieldSpan {
    has ftype: str = "";              # int64 | float32 | float64 | float32_vector | adjacency_list
    has width: int = 0;               # bytes of payload
    has align: int = 1;               # required alignment
    has offset: int = 0;              # assigned by writer
    has padded: bool = False;

    def natural_align() -> int {
        if self.ftype == "int64" { return 8; }
        if self.ftype == "float64" { return 8; }
        if self.ftype == "float32" { return 4; }
        if self.ftype == "float32_vector" { return 4; }
        if self.ftype == "adjacency_list" { return 4; }
        return 1;                      # bool/string/variable-width excluded
    }

    def natural_width() -> int {
        if self.ftype == "int64" { return 8; }
        if self.ftype == "float64" { return 8; }
        if self.ftype == "float32" { return 4; }
        if self.ftype == "float32_vector" { return self.width; }
        if self.ftype == "adjacency_list" { return self.width; }
        return self.width;
    }

    def is_fixed_width() -> bool {
        return self.ftype in ["int64", "float32", "float64", "float32_vector", "adjacency_list"];
    }
}

edge ContainsSpan { }
edge NextSpan { }

walker RowAssetWriter {
    has cursor: int = 0;
    has pad_total: int = 0;

    can start with Root entry {
        visit [->:ContainsSpan:->];
    }

    can write_asset with RowAsset entry {
        """Begin layout: row offset 0, fail-closed until certified."""
        self.cursor = 0;
        self.pad_total = 0;
        here.certified = False;
        visit [->:ContainsSpan:->] else {
            here.total_bytes = self.cursor;
            here.pad_bytes = self.pad_total;
