"""Cartography canonical map: typed topology with bounded, cycle-guarded reconciliation.

Demonstrates BTN-98's core scenario: a MapRevision connects Domains and Symbols
via typed Contains/RelatedTo edges. A Reconciler walker walks bounded topology
with an explicit cycle guard and depth limit (jac walkers do not dedupe
visits), while human-authored InstitutionalConstraints are inspected but never
overwritten. Ambiguous reconciliation keeps a PossibleSuccessor edge instead
of merging identities.
"""

node MapRevision {
    has title: str = "";
    has schema_version: int = 1;
    has published: bool = False;
}

node Domain {
    has name: str = "";
    has authority: str = "generated";
    has fresh: bool = True;
}

node Symbol {
    has name: str = "";
    has revision_evidence: str = "";
    has available: bool = True;
}

edge Contains { }
edge RelatedTo { }
edge PossibleSuccessor { has reason: str = ""; }

walker Reconciler {
    has depth_limit: int = 4;
    has depth: int = 0;
    has seen_names: list[str] = [];
    has found: list[str] = [];

    can start with MapRevision entry {
        print(f"reconciling revision '{here.title}' (schema v{here.schema_version})");
        visit [->:Contains:->];
    }

    can inspect_domain with Domain entry {
        if self.depth >= self.depth_limit {
            print("depth limit reached, ending domain walk");
            disengage;
        }
        if here.name in self.seen_names {
            disengage;
        }
        self.seen_names += [here.name];
        self.depth += 1;
        state = "HUMAN" if here.authority == "actor" else "generated";
        self.found += [f"{state}:{here.name}"];
        print(f"[{state}] domain {here.name} fresh={here.fresh}");
        # Human-authored records are inspected, never rewritten.
        if here.authority != "actor" {
            here.fresh = True;
        }
        visit [->:Contains:->];
        visit [->:RelatedTo:->];
    }

    can inspect_symbol with Symbol entry {
        status = "OK" if here.available else "MISSING";
        self.found += [f"symbol:{here.name}:{status}"];
        print(f"[{status}] symbol {here.name} (evidence {here.revision_evidence})");
        visit [->:PossibleSuccessor:->] else {
            print(f"no successors for symbol {here.name}, dead end");
        }
    }
}

with entry {
    rev = MapRevision(title="BTN-98 canonical map", schema_version=1, published=True);

    core = Domain(name="core", authority="generated");
    human = Domain(name="conventions", authority="actor");
    sym_a = Symbol(name="battalion.cartography", revision_evidence="path:cart.py@rev1");
    sym_b = Symbol(name="cartography_core", revision_evidence="path:cart/core.py@rev2");

