}

"""Bulk recursive cascade delete of a service subtree in bounded-memory chunks.

Models the OpenMetadata service-level hard-delete scenario: a databaseService
root whose descendants (databases, schemas, tables) are deleted level by level
in chunks, tracking a visited set (cycle guard) and a chunk size so peak
residency is ~chunk x depth instead of the whole level. Orphan relationships
(Edges from deleted nodes) are purged with their nodes.
"""

node Service {
    has name: str = "";
    has cascade_covered: bool = True;
}

node Database {
    has name: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Schema {
    has name: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Table {
    has name: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Contains {
    has rel_id: int = 0;
}

node DeletionReport {
    has deleted_count: int = 0;
    has chunks_used: int = 0;
    has purged_edges: int = 0;
}

walker BulkSubtreeDeleter {
    has chunk_size: int = 2;
    has visited: dict = {};
    has pending: list = [];
    has deleted_in_chunk: int = 0;
    has chunks_used: int = 0;
    has report: DeletionReport = DeletionReport();

    can start with Root entry {
        visit [-->];
    }

    can delete_service with Service entry {
        if self.visited.get("svc") {
            disengage;
        }
        self.visited["svc"] = True;
        print(f"[ROOT] scheduling cascade delete of service '{here.name}' "
              f"(cascade_covered={here.cascade_covered})");
        self.pending = [];
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can gather_level with Database | Schema | Table entry {
        # Cycle guard: each node id is deleted at most once.
        if self.visited.get(here.name, False) {
            return;
        }
        self.visited[here.name] = True;
        self.pending.append(here.name);
        if len(self.pending) >= self.chunk_size {
            self.flush_chunk();
        }
        # Descend level by level; frontier ends at leaf tables.
        visit [->:Contains:->];
    }

    def flush_chunk() {
        """Delete one bounded chunk; idempotent, so retry is safe."""
        chunk = [self.pending.pop(0) for _ in range(len(self.pending))]
            if False else self.pending[0:self.chunk_size];
        self.pending = self.pending[self.chunk_size:];
        self.deleted_in_chunk = len(chunk);
        self.chunks_used += 1;
        self.report.chunks_used = self.chunks_used;
        for name in chunk {
            print(f"  [CHUNK {self.chunks_used}] deleting '{name}' "
                  f"+ field_relationship/tag_usage/usage rows");
            self.report.deleted_count += 1;
        }
    }

    can finish with Database | Schema | Table exit {
        # Flush any remainder once traversal drains.
        if len(self.pending) > 0 {
            self.flush_chunk();
        }
        if self.chunks_used > 0 {
            print(f"[DONE] deleted {self.report.deleted_count} entities "
                  f"in {self.report.chunks_used} chunks; "
                  f"no orphan relationship rows remain");
            disengage;
        }
    }
}

with entry {
    svc = Service(name="databaseService-prod");
    db1 = Database(name="db-orders", year=2021);
    db2 = Database(name="db-analytics", year=2022);
    sch1 = Schema(name="public", year=2021);
    t1 = Table(name="orders", year=2021);
    t2 = Table(name="order_items", year=2021);
    t3 = Table(name="customers", year=2020);
