"""Cycle-safe traversal demo (issue #8562).

Walkers carry their own per-traversal visited set of node anchors so a
cyclic graph (even a self-loop) terminates after one visit per node,
instead of spinning forever as the unguarded ``visit [-->]`` does.
A second walker counts parallel typed edges between the same pair,
showing the guard set is per-traversal state, not per-graph.
"""

node GraphNode {
    has tag: str = "";
}

edge Link {
    has weight: int = 0;
}

walker CycleAwareWalker {
    has visited: dict = {};
    has visit_count: int = 0;

    can start with Root entry {
        print("beginning cycle-safe traversal");
        visit [-->] else { disengage; }
    }

    can go with GraphNode entry {
        if here in self.visited {
            print(f"cycle detected at {here.tag}, skipping re-visit");
        } else {
            self.visited[here] = True;
            self.visit_count += 1;
            print(f"visited {here.tag} ({self.visit_count} unique so far)");
            visit [-->] else { disengage; }
        }
    }
}

walker ParallelEdgeCounter {
    has seen: dict = {};
    has seen_pairs: dict = {};
    has parallel_count: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can tally with GraphNode entry {
        if here in self.seen {
            print(f"{here.tag} already tallied, moving on");
        } else {
            self.seen[here] = True;
            outgoing = [here->:Link:->];
            for link in outgoing {
                pair = f"{here.tag}->{link.tag}";
                if pair in self.seen_pairs {
                    self.parallel_count += 1;
                    print(f"parallel edge found: {pair}");
                } else {
                    self.seen_pairs[pair] = True;
                }
            }
            print(f"{here.tag} tallied; parallel edges so far: {self.parallel_count}");
            visit [-->] else { disengage; }
        }
    }
}

