"""Bulk recursive cascade delete of a service subtree in bounded-memory chunks.

Models the OpenMetadata service-level hard-delete scenario: a databaseService
root whose descendants (databases, schemas, tables) are deleted in bounded
chunks, tracking a visited set (cycle guard) and a chunk size so peak
residency is ~chunk x depth instead of a whole hydrated level. Chunked deletes
are idempotent, so a retry after a crash is safe.
"""

node Service {
    has name: str = "";
    has cascade_covered: bool = True;
}

node Database {
    has name: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Schema {
    has name: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Table {
    has name: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Contains {
    has rel_id: int = 0;
}

walker BulkSubtreeDeleter {
    has chunk_size: int = 2;
    has visited: dict = {};
    has pending: list[str] = [];
    has chunks_used: int = 0;
    has deleted_count: int = 0;

    def flush_chunk() {
        """Delete one bounded chunk; idempotent, so retry is safe."""
        take = self.chunk_size;
        if len(self.pending) < take {
            take = len(self.pending);
        }
        chunk = self.pending[0:take];
        self.pending = self.pending[take:];
        if len(chunk) == 0 {
            return;
        }
        self.chunks_used += 1;
        self.deleted_count += len(chunk);
        for name in chunk {
            print(f"  [CHUNK {self.chunks_used}] deleting '{name}' "
                  f"+ field_relationship/tag_usage/usage rows");
        }
    }

    can start with Root entry {
        visit [-->];
    }

    can delete_service with Service entry {
        if self.visited.get(here.name, False) {
            disengage;
        }
        self.visited[here.name] = True;
        print(f"[ROOT] cascade delete of service '{here.name}' "
              f"(cascade_covered={here.cascade_covered})");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can gather_level with Database | Schema | Table entry {
        # Cycle guard: each node is deleted at most once.
        if self.visited.get(here.name, False) {
            return;
        }
        self.visited[here.name] = True;
        self.pending.append(here.name);
        if len(self.pending) >= self.chunk_size {
            self.flush_chunk();
        }
        visit [->:Contains:->];
    }

    can finish with Database | Schema | Table exit {
        # Flush any remainder once the traversal drains.
        if len(self.pending) > 0 {
            self.flush_chunk();
        }
        print(f"[DONE] deleted {self.deleted_count} entities "
              f"in {self.chunks_used} chunks; no orphan relationship rows");
        disengage;
    }
}

