}

"""Cartography canonical map: bounded, cycle-guarded reconciliation over typed topology.

BTN-98 demo: a MapRevision links Domains and Symbols via Contains/RelatedTo
edges. A Reconciler walker traverses with an explicit depth limit and visited
guard (jac walkers do not dedupe visits). Human-authored institutional records
are inspected but never overwritten. Ambiguous rename keeps a PossibleSuccessor
edge instead of merging identities.
"""

node MapRevision {
    has title: str = "";
    has schema_version: int = 1;
    has published: bool = False;
}

node Domain {
    has name: str = "";
    has authority: str = "generated";
    has fresh: bool = True;
}

node Symbol {
    has name: str = "";
    has revision_evidence: str = "";
    has available: bool = True;
}

edge Contains { }
edge RelatedTo { }
edge PossibleSuccessor { has reason: str = ""; }

walker Reconciler {
    has depth_limit: int = 4;
    has depth: int = 0;
    has seen_names: list[str] = [];
    has found: list[str] = [];

    can start with MapRevision entry {
        print(f"reconciling revision '{here.title}' (schema v{here.schema_version})");
        visit [->:Contains:->];
    }

    can inspect_domain with Domain entry {
        if self.depth >= self.depth_limit {
            print("depth limit reached, ending walk");
            disengage;
        }
        if here.name in self.seen_names {
            return;
        }
        self.seen_names += [here.name];
        self.depth += 1;
        label = "HUMAN" if here.authority == "actor" else "generated";
        self.found += [f"{label}:{here.name}"];
        print(f"[{label}] domain {here.name} fresh={here.fresh}");
        # Human-authored records are inspected, never rewritten.
        if here.authority != "actor" {
            here.fresh = True;
        }
        visit [->:Contains:->];
        visit [->:RelatedTo:->];
    }

    can inspect_symbol with Symbol entry {
        if here.name in self.seen_names {
            return;
        }
        self.seen_names += [here.name];
        status = "OK" if here.available else "MISSING";
        self.found += [f"symbol:{here.name}:{status}"];
        print(f"[{status}] symbol {here.name} (evidence {here.revision_evidence})");
        visit [->:PossibleSuccessor:->] else {
            print(f"no successors for symbol {here.name}, dead end");
        }
    }
}

with entry {
    rev = MapRevision(title="BTN-98 canonical map", schema_version=1, published=True);

    core = Domain(name="core", authority="generated");
    human = Domain(name="conventions", authority="actor");
    sym_a = Symbol(name="battalion.cartography", revision_evidence="path:cart.py@rev1");
    sym_b = Symbol(name="cartography_core", revision_evidence="path:cart/core.py@rev2");

    rev +>:Contains:+> core;
    rev +>:Contains:+> human;
    core +>:Contains:+> sym_a;
    core +>:Contains:+> sym_b;
    core +>:RelatedTo:+> human;
    # Ambiguous rename: do NOT merge identities; keep inspectable successor edge.
    sym_a +>:PossibleSuccessor(reason="rename ambiguous, identity not merged"):+> sym_b;

    root ++> rev;
    r = Reconciler(depth_limit=4);
    rev spawn r;
    print(f"reconciler observed {len(r.found)} records: {r.found}");
}

"""Campaign platform demo: data-authored specs form a dependency graph;
a walker traverses typed DependsOn edges to audit readiness, detect cycles,
and compute the PoC campaign's blockers, mirroring the epic's dependency
machinery."""

node Spec {
    has title: str = "";
    has status: str = "todo";
}

edge DependsOn {
    has required: bool = True;
}

edge Unblocks {
}

walker DepChecker {
    has done_count: int = 0;
    has reachable: int = 0;
    has missing_required: int = 0;
    has seen: list[Spec] = [];

    can start with Root entry {
        visit [->:Unblocks:->] else { disengage; }
    }

    can inspect with Spec entry {
        if here in self.seen {
            print(f"CYCLE detected at {here.title}; stopping this branch");
            disengage;
        }
        self.seen += [here];
        self.reachable += 1;
        if here.status == "done" {
            self.done_count += 1;
        } else {
            missing = [e for e in here.edges_toDependsOn if e.required];
            for e in missing {
                if not (e.to.status == "done") {
                    self.missing_required += 1;
                }
            }
        }
        visit [->:DependsOn:->] else { disengage; }
    }
}

walker ReadinessAuditor {
    has ready_count: int = 0;
    has pending_count: int = 0;

    can start with Root entry {
        visit [->:Unblocks:->] else { disengage; }
    }

    can audit with Spec entry {
        checker = root spawn DepChecker();
        if here.status == "done" {
            self.ready_count += 1;
        } else {
            self.pending_count += 1;
        }
        verdict = "READY" if here.status == "done" else f"BLOCKED ({checker.missing_required} unmet)";
        print(f"SPEC {here.title} [{here.status}] "
              f"reach={checker.reachable} done_deps={checker.done_count} -> {verdict}");
    }
}

