"""Cycle-safe traversal demo (issue #8562).

``visit [-->]`` has no built-in visited set in jac, so a cyclic graph
(even a self-loop) makes an unguarded walker spin forever. These walkers
carry explicit per-traversal visited sets so each node is visited once,
while a parallel-edge counter shows duplicate edges between the same
pair are still distinguishable from revisits.
"""

node GraphNode {
    has tag: str = "";
}

edge Link {
    has weight: int = 0;
}

walker CycleAwareWalker {
    has visited: list[str] = [];
    has visit_count: int = 0;

    can start with Root entry {
        print("beginning cycle-safe traversal");
        visit [-->] else { disengage; }
    }

    can go with GraphNode entry {
        if here.tag in self.visited {
            print(f"cycle detected at {here.tag}, skipping re-visit");
        } else {
            self.visited.append(here.tag);
            self.visit_count += 1;
            print(f"visited {here.tag} ({self.visit_count} unique so far)");
            visit [-->] else { disengage; }
        }
    }
}

walker ParallelEdgeCounter {
    has tallied: list[str] = [];
    has seen_pairs: list[str] = [];
    has parallel_count: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can tally with GraphNode entry {
        if here.tag in self.tallied {
            print(f"{here.tag} already tallied, moving on");
        } else {
            self.tallied.append(here.tag);
            for link in [here->:Link:->] {
                pair = f"{here.tag}->{link.tag}";
                if pair in self.seen_pairs {
                    self.parallel_count += 1;
                    print(f"parallel edge found: {pair}");
                } else {
                    self.seen_pairs.append(pair);
                }
            }
            print(f"{here.tag} tallied; parallel edges so far: {self.parallel_count}");
            visit [-->] else { disengage; }
        }
    }
}

with entry {
    # Build the issue's repro shape: a self-loop on A plus a longer cycle A -> B -> A.
    a = GraphNode(tag="A");
    b = GraphNode(tag="B");
    root ++> a;
    a +>:Link(weight=1):+> a;
    a +>:Link(weight=2):+> b;
    b +>:Link(weight=3):+> a;

    root spawn CycleAwareWalker();
    root spawn ParallelEdgeCounter();
}

"""Bead-leak reaper: walk wisp dependency graphs and reap stale isolated beads.

The invariant from issue #2903: an idle city must keep bounded open bead
counts. A stale bead is reapable only when no OPEN bead depends on it via
parent-child, tracks, or blocks edges; open work is protected. The walker
carries an explicit guard set because visit does not dedupe cycles.
"""

node IssueBead {
    has title: str = "";
    has open: bool = True;
    has stale: bool = False;
}

node Wisp {
    has title: str = "";
    has open: bool = True;
    has stale: bool = False;
    has generated_step_spec: bool = False;
}

edge ParentChild { }
edge Tracks { }
edge Blocks { }

walker Reaper {
    has visited: dict = {};
    has reaped: list = [];
    has skipped_protected: int = 0;

    can start with Root entry {
        visit [-->];
    }

    """One ability serves both bead tiers via a union trigger."""
    can sweep with IssueBead | Wisp entry {
        if here.title in self.visited {
            disengage;
        }
        self.visited[here.title] = True;

        if here.open and here.stale {
            open_dependents = 0;
            for dep in [here<--:ParentChild:--] {
                if dep.open {
                    open_dependents += 1;
                }
            }
            for dep in [here<--:Tracks:--] {
                if dep.open {
                    open_dependents += 1;
                }
            }
            for dep in [here<--:Blocks:--] {
                if dep.open {
                    open_dependents += 1;
                }
            }
            if open_dependents == 0 {
                self.reaped.append(here.title);
                print(f"reaped stale bead: {here.title}");
                here.open = False;
            } else {
                self.skipped_protected += 1;
                print(f"protected {here.title}: {open_dependents} open dependent(s)");
            }
        } else {
            print(f"keeping {here.title} (open={here.open}, stale={here.stale})");
        }

        visit [->:ParentChild:->];
        visit [->:Tracks:->];
        visit [->:Blocks:->];
    }
}

walker AlertBoundary {
    """Stale-only alert: fresh active load must never page (PR #2909)."""
    has stale_alerts: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can check with IssueBead | Wisp entry {
        if here.open and here.stale {
            self.stale_alerts += 1;
            print(f"[ALERT] stale open bead: {here.title}");
        }
        visit [-->];
    }
}

