    live_step = Wisp(title="step-implement", open=True, stale=False);
    stale_debris = Wisp(title="step-spec-gen-7", open=True, stale=True, generated_step_spec=True);
    stale_mail = Wisp(title="mail-wisp-42", open=True, stale=True);
    stale_child = Wisp(title="mail-wisp-43", open=True, stale=True);

    root ++> order;
    order +>:Tracks:+> live_step;
    order +>:Tracks:+> stale_debris;
    root ++> stale_mail;
    stale_mail +>:ParentChild:+> stale_child;

    scanner = AlertBoundary();
    root spawn scanner;
    reaper = Reaper();
    root spawn reaper;

    print(f"alert boundary reported {scanner.stale_alerts} stale open bead(s) before reaping");
    print(f"reaper closed {len(reaper.reaped)} bead(s), protected {reaper.skipped_protected} bead(s)");
}

"""TreeDB row-asset writer: pad fixed-width spans to natural alignment and certify the layout.

Old/non-certified layouts fail closed; padding bytes are accounted per span.
"""

node RowAsset {
    has name: str = "";
    has format_version: int = 2;
    has certified: bool = False;
    has row_count: int = 0;
    has total_bytes: int = 0;
    has pad_bytes: int = 0;

    def is_direct_view_eligible() -> bool {
        return self.certified and self.format_version >= 2;
    }
}

node FieldSpan {
    has ftype: str = "";
    has width: int = 0;
    has offset: int = 0;
    has padded: bool = False;

    def natural_align() -> int {
        if self.ftype == "int64" { return 8; }
        if self.ftype == "float64" { return 8; }
        if self.ftype == "float32" { return 4; }
        if self.ftype == "float32_vector" { return 4; }
        if self.ftype == "adjacency_list" { return 4; }
        return 1;
    }

    def natural_width() -> int {
        if self.ftype == "int64" { return 8; }
        if self.ftype == "float64" { return 8; }
        if self.ftype == "float32" { return 4; }
        return self.width;
    }

    def is_fixed_width() -> bool {
        return self.ftype in ["int64", "float32", "float64", "float32_vector", "adjacency_list"];
    }
}

edge ContainsSpan { }
edge NextSpan { }

walker RowAssetWriter {
    has cursor: int = 0;
    has pad_total: int = 0;
    has span_count: int = 0;

    can start with Root entry {
        visit [->:ContainsSpan:->];
    }

    can write_asset with RowAsset entry {
        self.cursor = 0;
        self.pad_total = 0;
        self.span_count = 0;
        here.certified = False;
        visit [->:ContainsSpan:->];
    }

    can place_span with FieldSpan entry {
        if not here.is_fixed_width() {
            print(f"span {here.ftype}: excluded (variable-width), fallback copy-decode only");
            self.cursor = self.cursor + here.width;
            visit [->:NextSpan:->];
            disengage;
        }
        align = here.natural_align();
        aligned = (self.cursor + align - 1) // align * align;
        pad = aligned - self.cursor;
        if pad > 0 {
            self.pad_total += pad;
        }
        here.offset = aligned;
        here.padded = pad > 0;
        self.cursor = aligned + here.natural_width();
        self.span_count += 1;
        print(f"span {here.ftype}: offset {here.offset}, width {here.natural_width()}, pad {pad}");
        visit [->:NextSpan:->];
    }

    can certify with FieldSpan exit {
        if self.span_count > 0 {
            return;
        }
    }

    can finish with RowAsset exit {
        here.total_bytes = self.cursor;
        here.pad_bytes = self.pad_total;
        here.certified = True;
        print(f"asset {here.name}: certified v{here.format_version}, "
              f"{here.row_count} rows, {here.total_bytes} bytes "
              f"({here.pad_bytes} padding)");
    }
}

with entry {
    asset = RowAsset(name="float32_vector_rows", format_version=2, row_count=64);
    f0 = FieldSpan(ftype="float32_vector", width=12);
    f1 = FieldSpan(ftype="float32", width=4);
    f2 = FieldSpan(ftype="adjacency_list", width=8);
    f3 = FieldSpan(ftype="float64", width=8);
    f4 = FieldSpan(ftype="string_blob", width=7);
    asset +>:ContainsSpan:+> f0;
    f0 +>:NextSpan:+> f1;
    f1 +>:NextSpan:+> f2;
    f2 +>:NextSpan:+> f3;
    f3 +>:NextSpan:+> f4;
    root +>:ContainsSpan:+> asset;
    root spawn RowAssetWriter();

    print(f"direct-view eligible: {asset.is_direct_view_eligible()}");
}

