"""Campaign path audit: generated proposals enrich the path but never mutate Game Truth; every failure class falls back deterministically."""

node CampaignStep {
    has name: str = "";
    has canonical: bool = True;  # Game Truth: authoritative mechanics
}

node Proposal {
    has kind: str = "";            # interpretation | director | narration
    has wellformed: bool = True;
    has committed: bool = False;   # must stay False: never crosses barrier
}

edge Enriches {
    has fallback_reason: str = "";  # empty means accepted cleanly
}

walker Auditor {
    has fallbacks: int = 0;
    has checked: int = 0;
    has reasons: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_step with CampaignStep entry {
        self.checked += 1;
        visit [-->];
    }

    can audit_proposal with Proposal entry {
        ok = here.wellformed and not here.committed;
        here.committed = False if ok else False;  # barrier: proposals never commit mechanics
        if not ok {
            self.fallbacks += 1;
            reason = "malformed output" if not here.wellformed else "unauthorized commit attempt";
            self.reasons.append(reason);
