"""Adapton-style demand-driven incremental computation demo.

Changing a function marks its dependents DIRTY (lazy, bounded-depth BFS).
At query time dirty packs recompute; if the structural input hash is
unchanged (early cutoff) the dirty mark does not propagate downstream.
"""

node FuncNode {
    has name: str = "";
    has body: str = "";
    has content_hash: str = "";
    has pack_hash: str = "";
    has dirty: bool = True;
    has depth_limit: int = 8;

    def structural_hash() -> str {
        return f"fn:{self.name}:{self.body.strip()}";
    }

    def recompute() -> bool {
        """Recompute the pack if dirty; return True if dirty was cleared."""
        if not self.dirty {
            return False;
        }
        new_hash = self.structural_hash();
        cutoff = new_hash == self.content_hash and self.pack_hash != "";
        self.content_hash = new_hash;
        self.pack_hash = f"pack[{new_hash}]";
        self.dirty = False;
        if cutoff {
            print(f"[GREEN] {self.name}: recompute hit early cutoff, no propagation");
        } else {
            print(f"[RED->GREEN] {self.name}: pack rebuilt ({self.pack_hash})");
        }
        return not cutoff;
    }
}

