# Dirty-marker: BFS over reverse edges (dependents) with bounded depth.
walker DirtyMarker {
    has depth: int = 0;
    has max_depth: int = 8;

    can seed with FuncNode entry {
        if here.depth_limit < self.max_depth {
            self.max_depth = here.depth_limit;
        }
        print(f"dirtying {here.name} and its dependents (depth cap {self.max_depth})");
        here.dirty = True;
        self.depth = 1;
        visit [<--:Calls:--];
    }

    can mark with FuncNode entry {
        if here.dirty {
            print(f"  {here.name} already dirty, stopping branch");
            disengage;
        }
        here.dirty = True;
        print(f"  marked {here.name} dirty (depth {self.depth})");
        if self.depth >= self.max_depth {
            print(f"  depth bound reached at {here.name}, not propagating further");
            disengage;
        }
        next_depth = self.depth + 1;
        spawn_mark(next_depth);
        visit [<--:Calls:--];
    }

    def spawn_mark(d: int) {
        self.depth = d;
    }
}

