"""Campaign path audit: generated proposals enrich the path but never mutate Game Truth; every failure class falls back deterministically."""

node CampaignStep {
    has name: str = "";
    has canonical: bool = True;  # Game Truth: authoritative mechanics
}

node Proposal {
    has kind: str = "";            # interpretation | director | narration | fallback
    has wellformed: bool = True;
    has committed: bool = False;   # must stay False: never crosses the barrier
}

edge Enriches {
    has fallback_reason: str = "";  # empty means accepted cleanly
}

edge FallbackTo {
    has reason: str = "";
}

walker FallbackAuditor {
    has fallbacks: int = 0;
    has accepted: int = 0;
    has reasons: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can audit_step with CampaignStep entry {
        visit [->:Enriches:->] else { disengage; }
    }

    can audit_proposal with Proposal entry {
        if not here.wellformed {
            self.fallbacks += 1;
            self.reasons.append("malformed output");
            here +>:FallbackTo(reason="malformed output"):+> Proposal(kind="fallback", wellformed=True);
        } else if here.committed {
            self.fallbacks += 1;
            self.reasons.append("unauthorized commit attempt blocked at barrier");
            here.committed = False;  # barrier: mechanics remain unchanged
            here +>:FallbackTo(reason="commit denied"):+> Proposal(kind="fallback", wellformed=True);
        } else {
            self.accepted += 1;
        }
        disengage;
    }
}

