    start +>:Enriches:+> Proposal(kind="interpretation", wellformed=True);
    # malformed Director proposal: must fall back deterministically
    mid +>:Enriches:+> Proposal(kind="director", wellformed=False);
    # narration proposal that tried to commit: blocked at the barrier
    end +>:Enriches:+> Proposal(kind="narration", wellformed=True, committed=True);

    auditor = FallbackAuditor();
    root spawn auditor;

    report({
        "fallbacks": auditor.fallbacks,
        "accepted": auditor.accepted,
