"""Adapton-style demand-driven incremental computation demo.

Changing a function marks its dependents DIRTY (lazy, bounded-depth walk
over reverse ``Calls`` edges). At query time dirty packs recompute; if the
structural input hash is unchanged (early cutoff) the dirty mark does not
propagate downstream.
"""

node FuncNode {
    has name: str = "";
    has body: str = "";
    has content_hash: str = "";
    has pack_hash: str = "";
    has dirty: bool = True;
    has depth_limit: int = 8;

    def structural_hash() -> str {
        return f"fn:{self.name}:{self.body.strip()}";
    }

    # Recompute the pack if dirty; return True if dirty must propagate.
    def recompute() -> bool {
        if not self.dirty {
            return False;
        }
        new_hash = self.structural_hash();
        cutoff = new_hash == self.content_hash and self.pack_hash != "";
        self.content_hash = new_hash;
        self.pack_hash = f"pack[{new_hash}]";
        self.dirty = False;
        if cutoff {
            print(f"[GREEN] {self.name}: early cutoff, no downstream dirtying");
        } else {
            print(f"[RED] {self.name}: pack rebuilt ({self.pack_hash})");
        }
        return not cutoff;
    }
}

# caller --Calls--> callee (dependency direction); dependents are upstream.
edge Calls { }

# Dirty-marker: bounded walk over reverse edges (dependents) from the
# changed node. Explicit depth bound stands in for the issue's risk about
# highly connected graphs.
walker DirtyMarker {
    has depth: int = 0;
    has max_depth: int = 8;

    can start with FuncNode entry {
        if self.depth > here.depth_limit {
            self.max_depth = here.depth_limit;
        }
        if here.dirty {
            print(f"  {here.name} already dirty, stopping branch");
            disengage;
        }
        here.dirty = True;
        print(f"  marked {here.name} dirty (depth {self.depth})");
        if self.depth >= self.max_depth {
            print(f"  depth bound reached at {here.name}, not propagating");
            disengage;
        }
        self.depth = self.depth + 1;
        visit [<--:Calls:--];
    }
}

# Demander: walks the query path; recomputes only dirty nodes.
walker Querier {
    can start with Root entry {
        visit [-->];
    }

    can demand with FuncNode entry {
        if here.dirty {
            here.recompute();
            visit [-->];
        } else {
            print(f"[clean] {here.name}: served from cache ({here.pack_hash})");
        }
    }
}

with entry {
    # app -> api -> core -> util ; util is a leaf with no dependents.
    util = FuncNode(name="util.parse", body="def parse(s): return s.split()");
    core = FuncNode(name="core.index", body="index = build(parse(x))");
    api = FuncNode(name="api.serve", body="serve(index)");
