    # Scenario 1: reformat util's body - semantically identical after strip.
    util.body = "def parse(s):    return s.split()  ";
    print("=== dirty mark: whitespace-only edit of util ===");
    util spawn DirtyMarker();
    print("=== query after whitespace-only edit ===");
