    print("=== query after semantic edit ===");
    root spawn Querier();
}

"""Cycle-safe recursive parent-chain lookup.

Models the issue's visited-array pattern natively: a walker descends
ChildOf edges carrying a visited list (the analog of ARRAY[s.id] /
visited || s.id / id != ALL(visited)), stopping on cycles and honoring
the max depth cap instead of relying on hand-rolled SQL ARRAY guards.
"""

node Symbol {
    has name: str = "";
    has id: int = 0;
}

edge ChildOf { }

walker ChildSymbolFinder {
    has parent_name: str = "";
    has max_depth: int = 10;
    has visited: list[int] = [];
    has found_id: int = -1;
    has cycle_hit: bool = False;

    def seen(node_id: int) -> bool {
        for v in self.visited {
            if v == node_id {
                return True;
            }
        }
        return False;
    }

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can descend with Symbol entry {
        if self.found_id != -1 {
            disengage;
        }
        if self.seen(here.id) {
            print(f"cycle detected at symbol {here.id}, stopping");
            self.cycle_hit = True;
            disengage;
        }
        if len(self.visited) >= self.max_depth {
            print(f"depth cap {self.max_depth} reached, stopping");
            disengage;
        }
        if here.name == self.parent_name {
            self.found_id = here.id;
            print(f"found symbol {here.id} named '{here.name}'");
            disengage;
        }
        self.visited.append(here.id);
        visit [->:ChildOf:->] else { disengage; }
    }
}

