"""Change Controller: blast-radius analysis over artifact dependency graphs.

Nodes are artifacts and candidate changes; typed edges carry dependencies.
A BlastRadius walker traverses reverse-dependency edges to compute direct and
transitive dependents, keeps an explicit visited set (Jac walkers do not dedupe,
so cycles like shared-model lineage must be guarded here), and reports coupled
companions it discovers along the way.
"""

node Artifact {
    has name: str = "";
    has kind: str = "";          # "model" | "tokenizer" | "schema" | ...
    has active: bool = True;     # actively referenced by fleet inventory?
    has domain: str = "";        # data / locality domain touched
}

node Change {
    has title: str = "";
    has change_id: str = "";
}

edge Touches { }                 # change modifies artifact
edge DependsOn { has required: bool = True; }   # artifact dependency (forward)
edge CompanionWith { has reason: str = ""; }    # required companion coupling

walker BlastRadius {
    has visited: dict = {};
    has dependents: list = [];
    has unresolved: list = [];
    has companions: list = [];
    has depth: int = 0;
    has max_depth: int = 32;

    can start with Root entry {
        visit [->:Touches:->];
    }

    can analyze with Artifact entry {
        # Cycle policy: explicit guard set + depth cap (domain logic kept).
        if here.name in self.visited {
            print(f"cycle guarded at {here.name}");
            disengage;
        }
        if self.depth > self.max_depth {
            print("depth cap exceeded");
            disengage;
        }
        self.visited[here.name] = True;
        self.depth += 1;
        if here.active {
            self.dependents.append(here.name);
        } else {
            self.unresolved.append(f"{here.name} (stale inventory)");
        }
        # Companion couplings are required changes, not optional suggestions.
        for comp in [here->:CompanionWith:->] {
            self.companions.append(f"{here.name} <-> {comp.name}: {here->:CompanionWith:->.reason}");
        }
        # Traverse forward dependents; else-branch ends dead-end walks.
        visit [->:DependsOn:->] else { disengage; }
    }

    can summarize with Change exit {
        print(f"ImpactReport for {here.change_id}:");
        print(f"  dependents: {self.dependents}");
        print(f"  companions required: {self.companions}");
        print(f"  unresolved/stale: {self.unresolved}");
        risk = "elevated" if len(self.unresolved) > 0 else "normal";
        print(f"  conservative risk: {risk}");
        report self.dependents;
    }
}

