"""Dependency-graph engine: derived fields recompute downstream, overridden fields go stale."""

node Field {
    has name: str = "";
    has value: float = 0.0;
    has source: str = "auto";  # "auto" | "user_override"
    has stale: bool = False;

    def present_value() -> float {
        # An override presents its old (possibly stale) value.
        return self.value;
    }
}

# Typed edge: this field's value is derived from the source field.
edge DerivedFrom {
    has op: str = "sum";  # how inputs combine
}

walker ChangeField {
    has target: str = "";
    has new_value: float = 0.0;
    has visited: list[str] = [];
    has stale_fields: list[str] = [];

    can start with Root entry {
        # Find the changed field on the graph.
        found = False;
        for f in [-->] {
            if f.name == self.target {
                found = True;
                f.value = self.new_value;
                print(f"changed {f.name} -> {f.value}");
            }
        }
        if found {
            visit [-->];
        } else {
            print(f"no such field: {self.target}");
            disengage;
        }
    }

    can invalidate with Field entry {
        # Cycle guard: explicit visited set (jac walkers do not dedupe).
        if here.name in self.visited {
            raise RuntimeError(f"cycle detected at {here.name}");
        }
        self.visited.append(here.name);

        if here.source == "user_override" {
            # Preserve the user's value; mark stale, record for presentation.
            here.stale = True;
            self.stale_fields.append(here.name);
            fresh = 0.0;
            for upstream in [here->:DerivedFrom:->] {
                fresh += upstream.value;
            }
            print(f"OVERRIDE kept: {here.name}={here.present_value()} "
                  f"(newly derived would be {fresh}); choice required");
        } else {
            # Auto: recompute silently from declared inputs.
            total = 0.0;
            for upstream in [here->:DerivedFrom:->] {
                total += upstream.value;
            }
            here.value = total;
            here.stale = False;
            print(f"auto recomputed {here.name} = {here.value}");
        }
        visit [here->:DerivedFrom:->];
    }
}

walker Audit {
    can sweep with Field entry {
        flag = "STALE" if here.stale else "ok";
        print(f"[{flag}] {here.name} = {here.value} ({here.source})");
        visit [-->];
    }

    can none with Root entry {
        visit [-->];
    }
}

with entry {
    # plume_volume_cm3 is derived from raw inputs; so2_initial_pptv is
    # derived from plume_volume_cm3 (chained resolution, dependency order).
    w = Field(name="wind_mps", value=4.0);
    d = Field(name="duct_m", value=2.0);
    plume = Field(name="plume_volume_cm3", value=6.0);  # auto
    so2 = Field(name="so2_initial_pptv", value=6.0);    # auto
    vents = Field(name="vents_open", value=3.0, source="user_override");

    # Declared derivations: value = sum of declared inputs.
    plume +>:DerivedFrom:+> w;
    plume +>:DerivedFrom:+> d;
    so2 +>:DerivedFrom:+> plume;
    so2 +>:DerivedFrom:+> vents;

    root ++> w ++> d ++> plume ++> so2 ++> vents;

    # Change an upstream field: downstream closure recomputes exactly;
    # the override (vents_open) is preserved but marked stale.
    root spawn ChangeField(target="wind_mps", new_value=8.0);
    print("--- audit ---");
    root spawn Audit();
}

"""Scene-graph flat-scene build: the per-render traversal the issue complains about.

Groups, lights, and renderables form a scene graph via typed ChildOf edges.
A Render walker rebuilds the flat scene buckets (lights, shadow casters,
renderables) and propagates effective visibility down the hierarchy —
the O(N) walk pygfx does on every frame. An explicit visited set is the
cycle policy; a dirty flag on nodes stands in for incremental caching.
"""

node WorldObject {
    has name: str = "";
    has visible: bool = True;
    has dirty: bool = True;
    def show() -> bool {
        return self.visible;
    }
}

node Group(WorldObject) {
    has group_order: int = 0;
}

node Light(WorldObject) {
    has intensity: float = 0.0;
    has cast_shadow: bool = False;
}

node Mesh(WorldObject) {
    has cast_shadow: bool = True;
}

edge ChildOf {
    has order: int = 0;
}

walker Render {
    has depth: int = 0;
    has max_depth: int = 64;
    has visited: dict = {};
    has lights: list = [];
    has shadow_casters: list = [];
    has renderables: list = [];
    has hidden_subtrees: int = 0;

    can start with Root entry {
        visit [->:ChildOf:->];
    }

    can traverse with Group entry {
        if self.depth >= self.max_depth {
            print(f"[capped] depth limit {self.max_depth} reached at {here.name}");
            disengage;
        }
        if self.visited.get(here.name, False) {
            print(f"[cycle] revisiting {here.name}, skipping");
            disengage;
        }
        self.visited[here.name] = True;
        self.depth += 1;
        if here.dirty {
            print(f"[rebuild] group {here.name} (order={here.group_order}) was dirty");
            here.dirty = False;
        } else {
            print(f"[cache] group {here.name} already indexed");
        }
        if here.show() {
            visit [->:ChildOf:->];
        } else {
            self.hidden_subtrees += 1;
        }
        self.depth -= 1;
    }

    can collect with Light | Mesh entry {
        if not here.show() {
            self.hidden_subtrees += 1;
            return;
        }
        kind = "light" if here.cast_shadow else "shadowless-light";
        if isinstance(here, Light) {
            self.lights.append(here.name);
            if here.cast_shadow {
                self.shadow_casters.append(here.name);
            }
        } else {
            self.renderables.append(here.name);
            if here.cast_shadow {
                self.shadow_casters.append(here.name);
            }
            kind = "renderable";
        }
        print(f"[flat] {kind}: {here.name}");
    }
}

