    world = Group(name="world", group_order=0);
    rig = Group(name="rig", group_order=1);
    deep = Group(name="deep", group_order=2);
    world +>:ChildOf(order=0):+> rig;
    world +>:ChildOf(order=1):+> deep;
    rig +>:ChildOf:+> Light(name="sun", intensity=10.0, cast_shadow=True);
    rig +>:ChildOf:+> Mesh(name="line-plot");
    deep +>:ChildOf:+> Mesh(name="hidden-image", visible=False);
    deep +>:ChildOf:+> Mesh(name="cube");
    root ++> world;
    root spawn Render();

    print(f"lights={world_flat1 := Render.lights if False else []}");
}

"""Content-addressed nominal type identity: digest invalidation over the
semantic dependency graph, with cycle-safe traversal as the domain logic."""

node Decl {
    has name: str = "";
    has kind: str = "struct";       # "struct" | "method" | "helper"
    has digest: str = "";           # content-addressed identity digest
    has invalidated: bool = False;

    def label() -> str {
        return f"{self.kind}:{self.name}";
    }
}

edge DependsOn { }   # decl depends on decl (semantic dependency)
edge ImplementedBy { }   # struct -> its methods

walker DigestValidator {
    has depth: int = 0;
    has max_depth: int = 64;
    has visited: dict = {};
    has invalidations: int = 0;

    can start with Root entry {
        visit [->:ImplementedBy:->];
        visit [->:DependsOn:->];
    }

    # Cycle policy: explicit guard set + depth cap, since walkers do not
    # dedupe visitation on their own. A changed helper invalidates its
    # dependents transitively; recursion through an already-invalidated
    # node stops (fixed point reached).
    can propagate with Decl entry {
        if here.name in self.visited {
            return;
        }
        if self.depth > self.max_depth {
            print(f"[ERROR] dependency cycle exceeded depth limit at {here.label()}");
            disengage;
        }
        self.visited[here.name] = True;
        self.depth += 1;

        if not here.invalidated {
            new_digest = f"sha256:v1:{here.label()}:{self.depth}";
            if new_digest != here.digest {
                here.digest = new_digest;
                here.invalidated = True;
                self.invalidations += 1;
                print(f"[INVALIDATED] {here.label()} -> {here.digest}");
            } else {
                print(f"[stable] {here.label()} digest unchanged");
            }
        } else {
            print(f"[already-invalid] {here.label()}, pruning branch");
            return;
        }

        visit [->:ImplementedBy:->];
        visit [->:DependsOn:->] else { self.depth -= 1; return; };
        self.depth -= 1;
    }
}

walker DependencyAuditor {
    has seen: dict = {};
    has order: list = [];

    # Post-order accumulation of dependency order (leaves first) for
    # hashing components in dependency order.
    can audit with Decl entry {
        if here.name in self.seen {
            return;
        }
        self.seen[here.name] = True;
        visit [->:DependsOn:->] else { self.order.append(here.label()); return; };
        self.order.append(here.label());
    }

    can report_summary with Root exit {
        print(f"hash order (dependents last): {self.order}");
    }
}

with entry {
    # Two independently declared copies of an identical `Config` struct:
    # identical content digests, i.e. same identity despite separate nodes.
    config_a = Decl(name="Config", kind="struct", digest="sha256:v1:struct:Config:0");
    config_b = Decl(name="Config", kind="struct", digest="sha256:v1:struct:Config:0");

    # Distinct names => distinct identity even with identical shape.
    metres = Decl(name="Metres", kind="struct", digest="sha256:v1:struct:Metres:0");
    seconds = Decl(name="Seconds", kind="struct", digest="sha256:v1:struct:Seconds:0");

    # A helper whose body changed: transitive invalidation starts here.
    helper = Decl(name="scaleHelper", kind="helper", digest="stale");
    method_get = Decl(name="getScale", kind="method", digest="sha256:v1:method:getScale:0");

    root ++> config_a ++> config_b;
    metres +>:DependsOn:+> helper;
    helper +>:DependsOn:+> method_get;
    metres +>:ImplementedBy:+> method_get;
    seconds +>:DependsOn:+> helper;

    root spawn DigestValidator();
    root spawn DependencyAuditor();
}

"""Knowledge version & opposition protocol: immutable balls, gray/red lineage role swap."""

node Ball {
    has title: str = "";
    has layer: str = "";
    has content: str = "";
    has is_current: bool = False;
    # visual role is contextual: recomputed on swaps, never rewriting content
    has stable_gray: bool = False;
    has stable_red: bool = False;

    def snapshot() -> str {
        return f"{self.title}({self.layer})";
    }
}

edge VersionOf { }          # next-version link within a lineage (linear history)
edge Opposes { }            # opposing lineage anchored at a current node

walker VerdictAuditor {
    has verdict: str = "";
    has seen: dict = {};
    has depth: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Ball entry {
        # explicit visited guard: visit does NOT dedupe on cyclic graphs
        if here in self.seen {
            print(f"cycle guard: {here.snapshot()} already audited");
            disengage;
        }
        self.seen[here] = True;
        role = "CURRENT" if here.is_current else ("gray" if here.stable_gray else ("red" if here.stable_red else "pending"));
        print(f"[{role}] {here.snapshot()}");
        visit [->:VersionOf:->] else {
            visit [->:Opposes:->] else {
                if here.is_current and self.verdict == "oppose-wins" {
                    # full lineage role swap: old current side turns red
                    self.swAP(old_current=here);
                }
                disengage;
            }
        }
    }

    def swap_lineage(old_current: Ball) {
        old_current.is_current = False;
        old_current.stable_red = True;
        old_current.stable_gray = False;
        prev: Ball | None = old_current;
        while prev is not None {
            prev.stable_red = True;
            prev.stable_gray = False;
            nxts = [e for e in prev.edges ->:VersionOf:->];
            prev = nxts[0] if len(nxts) > 0 else None;
        }
    }

    def swAP(old_current: Ball) {
        self.swap_lineage(old_current);
    }
}

with entry {
    # gray history A1 -> A2 -> A3 (current), red opposition B1 -> B2 -> B3
    a1 = Ball(title="A1", layer="blue", content="v1", stable_gray=True);
    a2 = Ball(title="A2", layer="blue", content="v2", stable_gray=True);
    a3 = Ball(title="A3", layer="blue", content="v3", is_current=True);
    a1 +>:VersionOf:+> a2 +>:VersionOf:+> a3;

    b1 = Ball(title="B1", layer="green", content="o1", stable_red=True);
    b2 = Ball(title="B2", layer="green", content="o2", stable_red=True);
    b3 = Ball(title="B3", layer="green", content="o3", stable_red=True);
    b1 +>:VersionOf:+> b2 +>:VersionOf:+> b3;
    a3 +>:Opposes:+> b1;

    root ++> a1;
    root spawn VerdictAuditor(verdict="audit");

    # B3 wins: it becomes current, its elders go gray, A-lineage goes red
    b3.is_current = True;
    b3.stable_red = False;
    b3.stable_gray = False;
    b1.stable_red = False; b1.stable_gray = True;
    b2.stable_red = False; b2.stable_gray = True;
    auditor = VerdictAuditor(verdict="oppose-wins");
    root spawn auditor;
    print("post-swap audit complete; append-only history intact");
}

"""Change Controller: blast-radius analysis over artifact dependency graphs.

Nodes are artifacts and candidate changes; typed edges carry dependencies.
A BlastRadius walker traverses dependency edges to compute direct and
transitive dependents, keeps an explicit visited set (Jac walkers do not
dedupe, so shared-model cycles must be guarded here), and reports coupled
companion changes it discovers along the way.
"""

node Artifact {
    has name: str = "";
    has kind: str = "";              # "model" | "tokenizer" | "schema" | ...
    has active: bool = True;         # actively referenced by fleet inventory?
    has domain: str = "";            # data / locality domain touched
    has paired_with: str = "";       # companion-coupled artifact name
    has companion_reason: str = "";
}

node Change {
    has title: str = "";
    has change_id: str = "";
}

edge Touches { }                                 # change modifies artifact
edge DependsOn { has required: bool = True; }    # artifact dependency (forward)
edge CompanionWith { }                           # required companion coupling

walker BlastRadius {
    has visited: dict = {};
    has dependents: list = [];
    has unresolved: list = [];
    has companions: list = [];
    has depth: int = 0;
    has max_depth: int = 32;

    can start with Root entry {
        visit [->:Touches:->];
    }

    can analyze with Artifact entry {
        # Cycle policy: explicit guard set + depth cap (domain logic kept).
        if here.name in self.visited {
            print(f"cycle guarded at {here.name}");
            self.depth -= 1;
            return;
        }
        if self.depth > self.max_depth {
            print("depth cap exceeded");
            disengage;
        }
        self.visited[here.name] = True;
        self.depth += 1;
        if here.active {
            self.dependents.append(here.name);
        } else {
            self.unresolved.append(f"{here.name} (stale inventory)");
        }
        # Companion couplings are required changes, not optional suggestions.
        if here.companion_reason != "" {
            self.companions.append(f"{here.name} <-> {here.paired_with}: {here.companion_reason}");
        }
        # Traverse forward dependents; else-branch ends dead-end walks.
        visit [->:DependsOn:->] else {
            self.depth -= 1;
        }
        self.depth -= 1;
    }

    can summarize with Change exit {
        print(f"ImpactReport for {here.change_id}:");
        print(f"  dependents: {self.dependents}");
        print(f"  companions required: {self.companions}");
        print(f"  unresolved/stale: {self.unresolved}");
        risk = "elevated" if len(self.unresolved) > 0 else "normal";
        print(f"  conservative risk: {risk}");
        report self.dependents;
    }
}

