    has seen: list[str] = [];
    has lights: list[str] = [];
    has shadow_casters: list[str] = [];
    has renderables: list[str] = [];
    has hidden_subtrees: int = 0;

    def seen_name(n: str) -> bool {
        for s in self.seen {
            if s == n {
                return True;
            }
        }
        return False;
    }

    def in_group(names: list[str], n: str) -> bool {
        for s in names {
            if s == n {
                return True;
            }
        }
        return False;
    }

    def visit_ok() -> bool {
        if self.depth >= self.max_depth {
            print(f"[capped] depth limit {self.max_depth} reached");
            return False;
        }
        if self.seen_name(here.name) {
            print(f"[cycle] revisiting {here.name}, skipping");
            return False;
        }
        self.seen.append(here.name);
        return True;
    }

    def kind_of(obj: WorldObject) -> str {
        if obj is Light {
            return "light";
        }
        if obj is Mesh {
            return "mesh";
        }
        return "group";
    }

    can start with Root entry {
        visit [->:ChildOf:->];
    }

    can traverse with Group entry {
        if not self.visit_ok() {
            disengage;
        }
        self.depth += 1;
        if here.dirty {
            print(f"[rebuild] group {here.name} (order={here.group_order}) was dirty");
            here.dirty = False;
        } else {
            print(f"[cache] group {here.name} already indexed");
        }
        if here.show() {
            visit [->:ChildOf:->];
        } else {
            self.hidden_subtrees += 1;
        }
        self.depth -= 1;
    }

    def collect(obj: WorldObject) {
        if not obj.show() {
            self.hidden_subtrees += 1;
            return;
        }
        kind = self.kind_of(obj);
        if kind == "light" {
            self.lights.append(obj.name);
            if obj.cast_shadow {
                self.shadow_casters.append(obj.name);
            }
        } else {
            self.renderables.append(obj.name);
            if obj.cast_shadow {
                self.shadow_casters.append(obj.name);
            }
        }
        print(f"[flat] {kind}: {obj.name}");
    }

    can collect_light with Light entry {
        self.collect(here);
    }

    can collect_mesh with Mesh entry {
        self.collect(here);
    }
}

with entry {
    world = Group(name="world", group_order=0);
    rig = Group(name="rig", group_order=1);
    deep = Group(name="deep", group_order=2);
    world +>:ChildOf(order=0):+> rig;
    world +>:ChildOf(order=1):+> deep;
