}

"""Dependency-graph engine: derived fields recompute downstream, overridden fields go stale."""

node Field {
    has name: str = "";
    has value: float = 0.0;
    has source: str = "auto";  # "auto" | "user_override"
    has stale: bool = False;

    def present_value() -> float {
        # An override presents its old (possibly stale) value.
        return self.value;
    }
}

# Typed edge: this field's value is derived from the source field(s).
edge DerivedFrom {
    has op: str = "sum";  # how inputs combine
}

walker ChangeField {
    has target: str = "";
    has new_value: float = 0.0;
    has changed: bool = False;
    has visited: list[str] = [];
    has stale_fields: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can apply with Field entry {
        # First hit: locate and mutate the changed upstream field.
        if (not self.changed) and here.name == self.target {
            here.value = self.new_value;
            self.changed = True;
            print(f"changed {here.name} -> {here.value}");
            visit [here->:DerivedFrom:->] else { disengage; }
        }
        # Cycle guard: explicit visited set (jac walkers do not dedupe).
        if here.name in self.visited {
            print(f"cycle detected at {here.name}");
            disengage;
        }
        self.visited.append(here.name);

        fresh = 0.0;
        for upstream in [here->:DerivedFrom:->] {
            fresh += upstream.value;
        }

        if here.source == "user_override" {
            # Preserve the user's value; mark stale, record for presentation.
            here.stale = True;
            self.stale_fields.append(here.name);
            print(f"OVERRIDE kept: {here.name}={here.present_value()} "
                  f"(newly derived would be {fresh}); choice required");
        } else {
            # Auto: recompute silently from declared inputs.
            here.value = fresh;
            here.stale = False;
            print(f"auto recomputed {here.name} = {here.value}");
        }
        visit [here->:DerivedFrom:->] else { disengage; }
    }
}

walker Audit {
    can start with Root entry {
        visit [-->];
    }

    can sweep with Field entry {
        flag = "STALE" if here.stale else "ok";
        print(f"[{flag}] {here.name} = {here.value} ({here.source})");
    }
}

with entry {
    # plume_volume_cm3 is derived from raw inputs; so2_initial_pptv is
    # derived from plume_volume_cm3 (chained resolution, dependency order).
    w = Field(name="wind_mps", value=4.0);
    d = Field(name="duct_m", value=2.0);
    plume = Field(name="plume_volume_cm3", value=6.0);  # auto
    so2 = Field(name="so2_initial_pptv", value=6.0);    # auto
    vents = Field(name="vents_open", value=3.0, source="user_override");

    # Declared derivations: value = sum of declared inputs.
    plume +>:DerivedFrom:+> w;
    plume +>:DerivedFrom:+> d;
    so2 +>:DerivedFrom:+> plume;
    so2 +>:DerivedFrom:+> vents;

    root ++> w;
    root ++> d;
    root ++> plume;
    root ++> so2;
    root ++> vents;

    # Change an upstream field: downstream closure recomputes exactly;
    # the override (vents_open) is preserved but marked stale.
    root spawn ChangeField(target="wind_mps", new_value=8.0);
    print("--- audit ---");
    root spawn Audit();
}

"""Content-addressed nominal type identity: digest computation and transitive
invalidation over the semantic dependency graph, with explicit cycle guards."""

node Decl {
    has name: str = "";
    has kind: str = "struct";       # "struct" | "method" | "helper"
    has digest: str = "";
    has invalidated: bool = False;

    def label() -> str {
        return f"{self.kind}:{self.name}";
    }
}

edge DependsOn { }        # decl -> semantic dependency
edge ImplementedBy { }    # struct -> its methods

walker DigestAuditor {
    has seen: dict = {};
    has order: list = [];
    has invalidations: int = 0;
    has depth: int = 0;
    has max_depth: int = 64;

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    # Cycle policy: explicit guard set plus depth cap (walkers do not dedupe
    # visitation). A changed helper invalidates dependents transitively;
    # recursion through an already-invalidated node stops (fixed point).
    can audit with Decl entry {
        if here.name in self.seen {
            return;
        }
        if self.depth > self.max_depth {
            print(f"[ERROR] cycle exceeded depth limit at {here.label()}");
            disengage;
        }
        self.seen[here.name] = True;
        self.depth += 1;

        fresh = "sha256:v1:" + here.label();
        if fresh != here.digest {
            here.digest = fresh;
            here.invalidated = True;
            self.invalidations += 1;
            print(f"[INVALIDATED] {here.label()} -> {fresh}");
        } else {
            print(f"[stable] {here.label()} digest unchanged");
        }

        visit [-->] else { self.depth -= 1; return; };
        self.depth -= 1;
    }

    can summarize with Root exit {
        print(f"audited {len(self.seen)} decls, {self.invalidations} invalidations");
    }
}

walker DependencyOrderer {
    has seen: dict = {};
    has order: list = [];

    # Post-order walk: dependencies (leaves) are recorded before dependents,
    # matching "hash components in dependency order".
    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can record with Decl entry {
        if here.name in self.seen {
            return;
        }
        self.seen[here.name] = True;
        visit [-->] else { self.order.append(here.label()); return; };
        self.order.append(here.label());
    }

    can report with Root exit {
        print(f"hash order (dependents last): {self.order}");
    }
}

with entry {
    # Two independently declared copies of an identical Config struct:
    # same content digest, i.e. same identity despite separate declarations.
    config_a = Decl(name="Config", kind="struct", digest="sha256:v1:struct:Config");
    config_b = Decl(name="Config", kind="struct", digest="sha256:v1:struct:Config");

    # Distinct names => distinct identity even with identical shape.
    metres = Decl(name="Metres", kind="struct", digest="sha256:v1:struct:Metres");
    seconds = Decl(name="Seconds", kind="struct", digest="sha256:v1:struct:Seconds");

    # A helper whose body changed: transitive invalidation starts here.
    helper = Decl(name="scaleHelper", kind="helper", digest="stale");
    method_get = Decl(name="getScale", kind="method", digest="sha256:v1:method:getScale");

    root ++> config_a ++> config_b;
    metres +>:DependsOn:+> helper;
    helper +>:DependsOn:+> method_get;
    metres +>:ImplementedBy:+> method_get;
    seconds +>:DependsOn:+> helper;

    root spawn DigestAuditor();
    root spawn DependencyOrderer();
}

"""Knowledge version & opposition protocol: immutable balls, gray/red lineage role swap."""

node Ball {
    has title: str = "";
    has layer: str = "";
    has content: str = "";
    has is_current: bool = False;
    # gray/red are contextual roles relative to the current head, never rewrites of content
    has stable_gray: bool = False;
    has stable_red: bool = False;

    def snapshot() -> str {
        return f"{self.title}({self.layer})";
    }

    def role() -> str {
        if self.is_current {
            return "CURRENT";
        }
        if self.stable_gray {
            return "gray-history";
        }
        if self.stable_red {
            return "red-opposing";
        }
        return "pending";
    }
}

edge VersionOf { }   # linear next-version link within a lineage
edge Opposes { }     # anchors the opposing lineage at a current node

walker Auditor {
    has label: str = "audit";
    has seen: list = [];

    can start with Root entry {
        print(f"--- audit: {self.label} ---");
        visit [-->];
    }

    can audit with Ball entry {
        # explicit visited guard: visit does NOT dedupe on shared graphs
        if here in self.seen {
            disengage;
        }
        self.seen.append(here);
        print(f"[{here.role()}] {here.snapshot()} :: {here.content}");
        visit [->:VersionOf:->] else {
            visit [->:Opposes:->] else {
                disengage;
            }
        }
    }
}

walker ReRole {
    has to_red: bool = False;
    has make_current: bool = False;
    has seen: list = [];

    can start with Root entry {
        visit [-->];
    }

    can apply with Ball entry {
        if here in self.seen {
            disengage;
        }
        self.seen.append(here);
        if self.make_current {
            here.is_current = True;
            here.stable_gray = False;
            here.stable_red = False;
        } elif self.to_red {
            here.is_current = False;
            here.stable_gray = False;
            here.stable_red = True;
        } else {
            here.stable_gray = True;
            here.stable_red = False;
        }
        # walk backwards over the linear history chain
        visit [<--:VersionOf:--] else {
            disengage;
        }
    }
}

with entry {
    # gray history A1 -> A2 -> A3 (current), opposing lineage B1 -> B2 -> B3
    a1 = Ball(title="A1", layer="blue", content="v1", stable_gray=True);
    a2 = Ball(title="A2", layer="blue", content="v2", stable_gray=True);
    a3 = Ball(title="A3", layer="blue", content="v3", is_current=True);
    a1 +>:VersionOf:+> a2 +>:VersionOf:+> a3;

    b1 = Ball(title="B1", layer="green", content="o1", stable_red=True);
    b2 = Ball(title="B2", layer="green", content="o2", stable_red=True);
    b3 = Ball(title="B3", layer="green", content="o3", stable_red=True);
    b1 +>:VersionOf:+> b2 +>:VersionOf:+> b3;
    a3 +>:Opposes:+> b1;

    root ++> a1;
    root spawn Auditor(label="pre-swap");

    # B3 wins the opposition verdict:
    # B3 becomes the sole current node (own layer color),
    # older B nodes become gray history,
    # the entire A lineage becomes the red opposing lineage.
    b3 spawn ReRole(make_current=True);
    a3 spawn ReRole(to_red=True);

    root spawn Auditor(label="post-swap");
    print("swap complete; append-only audit history intact");
}

"""Change Controller: blast-radius analysis over artifact dependency graphs.

Nodes are artifacts and candidate changes; typed edges carry dependencies.
A BlastRadius walker traverses dependency edges to compute direct and
transitive dependents, keeps an explicit visited set (Jac walkers do not
dedupe, so shared-model cycles must be guarded here), and reports an
ImpactReport with companions and unresolved references.
"""

node Artifact {
    has name: str = "";
    has kind: str = "";              # "model" | "tokenizer" | "schema" | ...
    has active: bool = True;         # actively referenced by fleet inventory?
    has domain: str = "";            # data / locality domain touched
    has paired_with: str = "";       # companion-coupled artifact name
    has companion_reason: str = "";
}

node Change {
    has title: str = "";
    has change_id: str = "";
}

edge Touches { }                                 # change modifies artifact
edge DependsOn { has required: bool = True; }    # artifact dependency (forward)
edge CompanionWith { }                           # required companion coupling

walker BlastRadius {
    has visited: dict = {};
    has dependents: list = [];
    has unresolved: list = [];
    has companions: list = [];
    has change_id: str = "CHG-42";
    has depth: int = 0;
    has max_depth: int = 32;
    has reported: bool = False;

    can start with Root entry {
        visit [->:Touches:->] else { disengage; }
    }

    can analyze with Artifact entry {
        # Cycle policy: explicit guard set + depth cap (domain logic kept).
        if here.name in self.visited or self.depth > self.max_depth {
            self.depth -= 1;
            visit [-->] else { disengage; }
        }
        self.visited[here.name] = True;
        self.depth += 1;
        if here.active {
            self.dependents.append(here.name);
        } else {
            self.unresolved.append(f"{here.name} (stale inventory)");
        }
        # Companion couplings are required changes, not optional suggestions.
        if here.companion_reason != "" {
            self.companions.append(f"{here.name} <-> {here.paired_with}: {here.companion_reason}");
        }
        # Traverse forward dependents; else-branch ends dead-end walks.
        visit [->:DependsOn:->] else {
            if self.reported == False {
                self.reported = True;
                risk = "elevated" if len(self.unresolved) > 0 else "normal";
                print(f"ImpactReport for {self.change_id}:");
                print(f"  dependents: {self.dependents}");
                print(f"  companions required: {self.companions}");
                print(f"  unresolved/stale: {self.unresolved}");
                print(f"  conservative risk: {risk}");
                report self.dependents;
            }
            self.depth -= 1;
        }
        self.depth -= 1;
    }
}

with entry {
    tokenizer = Artifact(name="tok-v3", kind="tokenizer", domain="nlp",
                         paired_with="model-v7",
                         companion_reason="tokenizer must match model vocabulary");
    model = Artifact(name="model-v7", kind="model", domain="nlp");
    router_schema = Artifact(name="route-schema-v2", kind="schema", domain="control",
                             paired_with="actuator-in-v1",
