    actuator_schema = Artifact(name="actuator-in-v1", kind="schema", domain="control");
    agent_spec = Artifact(name="orchestrator", kind="agent", domain="nlp");
    offline_device = Artifact(name="drone-9", kind="device", domain="field", active=False);

    model +>:CompanionWith:+> tokenizer;
