"""Team hierarchy walks with explicit depth cap and cycle guard.

Lifts the recursive manager-hierarchy CTEs from team/repository.js:
every traversal carries a depth cap (100) and a visited set so a
manager_id cycle terminates gracefully instead of hanging.
"""

node User {
    has name: str = "";
    has deleted: bool = False;
}

edge ManagerOf { }

walker TeamRoster {
    has max_depth: int = 100;
    has visited: list[str] = [];
    has members: list[str] = [];

    can start with Root entry {
        visit [->:ManagerOf:->] else { disengage; }
    }

    can collect with User entry {
        # Cycle guard: never process a node twice (no built-in dedup).
        if here.name in self.visited {
            print(f"cycle detected at {here.name}, pruning branch");
            disengage;
        } else {
            self.visited.append(here.name);
            if len(self.visited) >= self.max_depth {
                print(f"depth cap {self.max_depth} reached at {here.name}");
                disengage;
            } else {
                if not here.deleted {
                    self.members.append(here.name);
                }
                visit [->:ManagerOf:->] else { disengage; }
            }
        }
    }
}

walker CycleCheck {
    has max_depth: int = 100;
    has seen: list[str] = [];
    has has_cycle: bool = False;

    can start with Root entry {
        visit [->:ManagerOf:->] else { disengage; }
    }

    can probe with User entry {
        if here.name in self.seen {
            self.has_cycle = True;
            print(f"pre-existing cycle found via {here.name}");
            disengage;
        } else {
            self.seen.append(here.name);
            if len(self.seen) >= self.max_depth {
                print(f"cycle check hit depth cap {self.max_depth}");
                disengage;
            } else {
                visit [->:ManagerOf:->] else { disengage; }
            }
        }
    }
}

with entry {
