    root +>:ManagerOf:+> alice;
    alice +>:ManagerOf:+> bob;
    bob +>:ManagerOf:+> carol;
    carol +>:ManagerOf:+> dave;

    roster = root spawn TeamRoster();
    print(f"roster: {roster.members}");

    # Pathological chain with a pre-existing cycle: e1 -> e2 -> e3 -> e1
    e1 = User(name="e1");
