    e3 +>:ManagerOf:+> e1;

    roster2 = root spawn TeamRoster();
    print(f"cyclic roster: {roster2.members}");
    checker = root spawn CycleCheck();
    print(f"cycle check found cycle: {checker.has_cycle}");
}

"""Scene-graph flat-scene build: the per-render traversal the issue complains about.

Groups, lights, and renderables form a scene graph via typed ChildOf edges.
A Render walker rebuilds the flat scene buckets (lights, shadow casters,
renderables) and propagates effective visibility down the hierarchy —
the O(N) walk pygfx does on every frame. An explicit visited set is the
cycle policy; depth is capped as an additional guard.
"""

node WorldObject {
    has name: str = "";
    has visible: bool = True;
    has dirty: bool = True;
}

node Group(WorldObject) {
    has group_order: int = 0;
}

node Light(WorldObject) {
    has intensity: float = 0.0;
    has cast_shadow: bool = False;
}

node Mesh(WorldObject) {
    has cast_shadow: bool = True;
}

edge ChildOf {
    has order: int = 0;
}

walker Render {
    has depth: int = 0;
    has max_depth: int = 64;
    has seen: list[str] = [];
    has lights: list[str] = [];
    has shadow_casters: list[str] = [];
    has renderables: list[str] = [];
    has hidden_subtrees: int = 0;
    has stop: bool = False;

    def seen_name(n: str) -> bool {
        for s in self.seen {
            if s == n {
                return True;
            }
        }
        return False;
    }

    def guard() -> bool {
        if self.stop {
            return False;
        }
        if self.depth >= self.max_depth {
            print(f"[capped] depth limit {self.max_depth} reached at {here.name}");
            self.stop = True;
            return False;
        }
        if self.seen_name(here.name) {
            print(f"[cycle] revisiting {here.name}, skipping");
            return False;
        }
        self.seen.append(here.name);
        return True;
    }

    def enter() {
        if not self.guard() {
            return;
        }
        self.depth += 1;
        if here.dirty {
            print(f"[rebuild] {here.name} was dirty, indexing subtree");
            here.dirty = False;
        } else {
            print(f"[cache] {here.name} already indexed");
        }
        if here.visible {
            visit [->:ChildOf:->];
        } else {
            print(f"[cull] hidden subtree at {here.name}");
            self.hidden_subtrees += 1;
        }
        self.depth -= 1;
    }

    can start with Root entry {
        visit [->:ChildOf:->];
    }

    can traverse with Group entry {
        self.enter();
    }

    can collect_light with Light entry {
        if not self.guard() {
            return;
        }
        if here.visible {
            self.lights.append(here.name);
            if here.cast_shadow {
                self.shadow_casters.append(here.name);
            }
            print(f"[flat] light: {here.name} (intensity={here.intensity})");
        } else {
            self.hidden_subtrees += 1;
        }
    }

    can collect_mesh with Mesh entry {
        if not self.guard() {
            return;
        }
        if here.visible {
            self.renderables.append(here.name);
            if here.cast_shadow {
                self.shadow_casters.append(here.name);
            }
            print(f"[flat] mesh: {here.name}");
        } else {
            self.hidden_subtrees += 1;
        }
    }
}

with entry {
    world = Group(name="world", group_order=0);
    rig = Group(name="rig", group_order=1);
    deep = Group(name="deep", group_order=2);
    world +>:ChildOf(order=0):+> rig;
    world +>:ChildOf(order=1):+> deep;
    rig +>:ChildOf:+> Light(name="sun", intensity=10.0, cast_shadow=True);
    rig +>:ChildOf:+> Mesh(name="line-plot");
    deep +>:ChildOf:+> Mesh(name="hidden-image", visible=False);
    deep +>:ChildOf:+> Mesh(name="cube");
    root ++> world;

    build = Render();
    root spawn build;

    print(f"lights={build.lights}, shadow_casters={build.shadow_casters}, "
          f"renderables={build.renderables}, hidden_subtrees={build.hidden_subtrees}");
}

