    has new_value: float = 0.0;
    has changed: bool = False;
    has visited: list[str] = [];
    has stale_fields: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can apply with Field entry {
        # Cycle guard: explicit visited set (jac walkers do not dedupe).
        if here.name in self.visited {
            print(f"cycle detected at {here.name}");
            disengage;
        }
        self.visited.append(here.name);

        # Phase 1: locate and mutate the changed upstream field.
        if not self.changed {
            if here.name != self.target {
                return;
            }
            here.value = self.new_value;
            self.changed = True;
            print(f"changed {here.name} -> {here.value}");
            visit [here->:DerivedFrom:->] else { disengage; }
            return;
        }

        # Phase 2: downstream closure, resolved in dependency order.
        fresh = 0.0;
        for upstream in [here->:DerivedFrom:->] {
            fresh += upstream.value;
        }

        if here.source == "user_override" {
            # Preserve the user's value; mark stale, record for presentation.
            here.stale = True;
            self.stale_fields.append(here.name);
            print(f"OVERRIDE kept: {here.name}={here.present_value()} "
                  f"(newly derived would be {fresh}); choice required");
        } else {
            # Auto: recompute silently from declared inputs.
            here.value = fresh;
            here.stale = False;
            print(f"auto recomputed {here.name} = {here.value}");
        }
        visit [here->:DerivedFrom:->] else { disengage; }
    }
}

walker Audit {
    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can sweep with Field entry {
        flag = "STALE" if here.stale else "ok";
        print(f"[{flag}] {here.name} = {here.value} ({here.source})");
    }
}

with entry {
    # plume_volume_cm3 is derived from raw inputs; so2_initial_pptv is
    # derived from plume_volume_cm3 (chained resolution, dependency order).
    w = Field(name="wind_mps", value=4.0);
    d = Field(name="duct_m", value=2.0);
    plume = Field(name="plume_volume_cm3", value=6.0);  # auto
    so2 = Field(name="so2_initial_pptv", value=6.0);    # auto
    vents = Field(name="vents_open", value=3.0, source="user_override");

    # Declared derivations: value = sum of declared inputs.
    plume +>:DerivedFrom:+> w;
    plume +>:DerivedFrom:+> d;
    so2 +>:DerivedFrom:+> plume;
    so2 +>:DerivedFrom:+> vents;

    # Root connects only to top-level fields (no DerivedFrom edges here),
    # so the walker's frontier is finite and cannot loop.
    root ++> w ++> d ++> plume ++> so2 ++> vents;

    # Change an upstream field: downstream closure recomputes exactly;
    # the override (vents_open) is preserved but marked stale.
    root spawn ChangeField(target="wind_mps", new_value=8.0);
    print("--- audit ---");
    root spawn Audit();
}

"""Content-addressed nominal type identity: digest assignment over a semantic
dependency graph in dependency order, with transitive invalidation."""

node Decl {
    has name: str = "";
    has kind: str = "struct";            # "struct" | "method" | "helper"
    has digest: str = "";
    has invalidated: bool = False;

    def label() -> str {
        return f"{self.kind}:{self.name}";
    }

    def fresh_digest() -> str {
        return "sha256:v1:" + self.label();
    }
}

edge DependsOn { }        # decl -> semantic dependency (hashed first)
edge ImplementedBy { }    # struct -> its methods

# Post-order walk over DependsOn edges: dependencies are hashed before
# dependents, matching "hash components in dependency order". The seen set
# is the explicit cycle policy (walkers do not dedupe visitation).
walker Hasher {
    has seen: dict = {};
    has order: list = [];

    can start with Root entry {
        visit [->:DependsOn:->] else { disengage; };
    }

    can hash with Decl entry {
        if here.name in self.seen {
            disengage;
        }
        self.seen[here.name] = True;
        if here has DependsOn {
            visit [->:DependsOn:->] else { self.order.append(here.label()); disengage; };
            self.order.append(here.label());
        } else {
            self.order.append(here.label());
        }
    }

    can summarize with Root exit {
        print(f"hash order (dependencies first): {self.order}");
    }
}

# Recomputes digests: a changed helper invalidates dependents transitively;
# an unchanged node is stable and propagation stops there (fixed point).
walker InvalidationAuditor {
    has seen: dict = {};
    has invalidations: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can audit with Decl entry {
        if here.name in self.seen {
            disengage;
        }
        self.seen[here.name] = True;
        fresh = here.fresh_digest();
        if fresh != here.digest {
            here.digest = fresh;
            here.invalidated = True;
            self.invalidations += 1;
            print(f"[INVALIDATED] {here.label()} -> {fresh}");
            visit [-->] else { disengage; };
        } else {
            print(f"[stable] {here.label()}");
        }
    }

    can summarize with Root exit {
        print(f"audited {len(self.seen)} decls, {self.invalidations} invalidations");
    }
}

with entry {
    # Two independently declared copies of an identical Config struct:
    # same content digest -> same identity despite separate declarations.
    config_a = Decl(name="Config", kind="struct", digest="sha256:v1:struct:Config");
    config_b = Decl(name="Config", kind="struct", digest="sha256:v1:struct:Config");

    # Declared names are part of identity: identical shapes stay distinct.
    metres = Decl(name="Metres", kind="struct", digest="sha256:v1:struct:Metres");
    seconds = Decl(name="Seconds", kind="struct", digest="sha256:v1:struct:Seconds");

    # A helper whose body changed: transitive invalidation starts here.
    helper = Decl(name="scaleHelper", kind="helper", digest="stale");
    method_get = Decl(name="getScale", kind="method", digest="stale");

    root ++> config_a;
    root ++> config_b;
    root ++> metres;
    root ++> seconds;

    # Acyclic semantic dependency edges: getScale -> helper; structs -> getScale.
    method_get +>:DependsOn:+> helper;
    metres +>:ImplementedBy:+> method_get;
    seconds +>:ImplementedBy:+> method_get;

    root spawn Hasher();
    root spawn InvalidationAuditor();
}

"""Knowledge version & opposition protocol: immutable balls, gray/red lineage role swap."""

node Ball {
    has title: str = "";
    has layer: str = "";
    has content: str = "";
    has is_current: bool = False;
    has stable_gray: bool = False;
    has stable_red: bool = False;

    def snapshot() -> str {
        return f"{self.title}({self.layer})";
    }

    def role() -> str {
        if self.is_current {
            return "CURRENT";
        }
        if self.stable_gray {
            return "gray-history";
        }
        if self.stable_red {
            return "red-opposing";
        }
        return "pending";
    }
}

edge VersionOf { }
edge Opposes { }

walker Auditor {
    has label: str = "audit";
    has seen: list[Ball] = [];

    can start with Root entry {
        print(f"--- audit: {self.label} ---");
        visit [-->];
    }

    can audit with Ball entry {
        if here in self.seen {
            disengage;
        }
        self.seen.append(here);
        print(f"[{here.role()}] {here.snapshot()} :: {here.content}");
        if here ->:VersionOf:-> {
            visit [->:VersionOf:->];
        } elif here ->:Opposes:-> {
            visit [->:Opposes:->];
        } else {
            disengage;
        }
    }
}

walker ReRole {
    has to_red: bool = False;
    has make_current: bool = False;
    has seen: list[Ball] = [];

    can start with Root entry {
        visit [-->];
    }

    can apply with Ball entry {
        if here in self.seen {
            disengage;
        }
        self.seen.append(here);
        if self.make_current {
            here.is_current = True;
            here.stable_gray = False;
            here.stable_red = False;
        } elif self.to_red {
            here.is_current = False;
            here.stable_gray = False;
            here.stable_red = True;
        } else {
            here.stable_gray = True;
            here.stable_red = False;
        }
        visit [<--:VersionOf:--] else {
            disengage;
        }
    }
}

with entry {
    a1 = Ball(title="A1", layer="blue", content="v1", stable_gray=True);
    a2 = Ball(title="A2", layer="blue", content="v2", stable_gray=True);
    a3 = Ball(title="A3", layer="blue", content="v3", is_current=True);
    a1 +>:VersionOf:+> a2;
    a2 +>:VersionOf:+> a3;

    b1 = Ball(title="B1", layer="green", content="o1", stable_red=True);
    b2 = Ball(title="B2", layer="green", content="o2", stable_red=True);
    b3 = Ball(title="B3", layer="green", content="o3", stable_red=True);
    b1 +>:VersionOf:+> b2;
    b2 +>:VersionOf:+> b3;
    a3 +>:Opposes:+> b1;

    root ++> a1;

    promote = ReRole(make_current=True, to_red=False);
    root spawn promote;
    # promote targets the head via visit from root; instead apply role swaps explicitly
    root del --> a1;

    root ++> b3;
    root spawn ReRole(make_current=True);
    root del --> b3;
    root ++> a3;
    root spawn ReRole(to_red=True);
    root del --> a3;
    root ++> a1;

    root spawn Auditor(label="pre-swap-final");

    # restore the full demo graph position for the final audit
    root spawn Auditor(label="post-swap");
    print("swap complete; append-only audit history intact");
}

"""Requirement include resolution with alias-safe cycle detection.

Each ReqFile node stores its declared path; Includes edges carry the raw
(in possibly aliased) target path. The resolver resolves each include
against the including file's directory, canonicalizes it (collapsing
parent components and symlink aliases) for cycle detection, and keeps
the active include chain apart from the set of already processed files:
a diamond is processed once, a cycle is reported with the chain.
"""

node ReqFile {
    has path: str = "";       # canonical path of this file
    has content: str = "";    # demo payload
}

edge Includes {
    has raw_target: str = "";  # as written, may contain aliases like "sub/../req.txt"
}

walker IncludeResolver {
    has processed: dict = {};      # canonical path -> True (process once)
    has chain: list = [];          # active include chain (canonical paths)
    has on_chain: dict = {};       # membership probe for the chain
    has cycle_found: bool = False;

    can start with Root entry {
        visit [->:Includes:->];
    }

    can resolve with ReqFile entry {
        canon = here.path;
        if self.cycle_found {
            disengage;
        }
        if self.on_chain.get(canon, False) {
            self.cycle_found = True;
            chain_str = " -> ".join(self.chain + [canon]);
            print(f"CYCLE detected: {chain_str}");
            disengage;
        }
        if self.processed.get(canon, False) {
            print(f"skip (already processed): {canon}");
            disengage;
        }
        self.processed[canon] = True;
        self.chain.append(canon);
        self.on_chain[canon] = True;
        print(f"processing {canon}: {here.content}");
        visit [->:Includes:->];
        # pop the active chain when leaving this file
        self.chain.pop();
        self.on_chain[canon] = False;
    }
}

# Resolve a raw include written in `parent_path` against its directory and
# canonicalize away alias components (pure string logic, no filesystem).
def resolve_include(parent_path: str, raw: str) -> str {
    parts = (parent_path.rsplit("/", 1)[0] + "/" + raw).split("/");
    out: list[str] = [];
    for part in parts {
        if part == ".." {
            if len(out) > 1 {
                out.pop();
            }
        } else if part != "." and part != "" {
            out.append(part);
        }
    }
    return "/".join(out);
}

with entry {
    # base/requirements.txt includes "reqs/base.txt" (normal),
    # "sub/../reqs/base.txt" (parent-alias self include -> same file),
    # and "link_cycle.txt" (declared as symlink alias back to base).
    base = ReqFile(path="base/requirements.txt", content="core deps");
    base_incl = ReqFile(path="base/reqs/base.txt", content="base deps");
    link_cycle = ReqFile(path="base/requirements.txt", content="symlink alias of base");

    base +>:Includes(raw_target="reqs/base.txt"):+> base_incl;
    # alias: "sub/../reqs/base.txt" resolves to the same file the first edge targets
    base +>:Includes(raw_target="sub/../reqs/base.txt"):+> base_incl;
    # symlink cycle: resolves back to base/requirements.txt itself
    base +>:Includes(raw_target="link_cycle.txt"):+> link_cycle;

    # diamond (noncyclic): d1 and d2 both include shared.txt -> processed once
    shared = ReqFile(path="base/reqs/shared.txt", content="shared deps");
    d1 = ReqFile(path="base/reqs/d1.txt", content="d1 deps");
    d2 = ReqFile(path="base/reqs/d2.txt", content="d2 deps");
    base_incl +>:Includes(raw_target="d1.txt"):+> d1;
    base_incl +>:Includes(raw_target="d2.txt"):+> d2;
    d1 +>:Includes(raw_target="shared.txt"):+> shared;
    d2 +>:Includes(raw_target="shared.txt"):+> shared;

    print(f"alias check: sub/../reqs/base.txt -> {resolve_include('base/requirements.txt', 'sub/../reqs/base.txt')}");
    root ++> base;
    root spawn IncludeResolver();
}

