"""Recurring bookings live in GnuCash Scheduled Transactions (SX).

Once an SX has booked a payment, an imported bank row is a MATCH to an
existing transaction, not a new one. This demo walks the scheduled set,
simulates the SX booking, then walks imported bank rows: rows whose
source is an SX are matched (no double booking), unknown rows fall
through to creation.
"""

node RecurringPayment {
    has name: str = "";
    has monthly_amount: float = 0.0;
    has booked: bool = False;
}

node BankRow {
    has label: str = "";
    has amount: float = 0.0;
    has matched: bool = False;
}

edge Covers {
    # links an SX to the bank row it anticipates
    has note: str = "";
}

walker SxBooker {
    can start with Root entry {
        visit [-->];
    }

    can book with RecurringPayment entry {
        here.booked = True;
        print(f"SX booked: {here.name} ({here.monthly_amount})");
        visit [->:Covers:->];
    }
}

walker Applier {
    can start with Root entry {
        visit [-->];
    }

    can apply with BankRow entry {
        source = here <--:Covers:--;
        if source {
            here.matched = True;
            print(f"match-to-existing: {here.label} -> {source[0].name}");
        } else {
            print(f"create new transaction: {here.label}");
        }
    }
}

with entry {
    rent = RecurringPayment(name="Rent", monthly_amount=1200.0);
    salary = RecurringPayment(name="Salary", monthly_amount=2500.0);
    insurance = RecurringPayment(name="Insurance", monthly_amount=85.0);
    root ++> rent ++> salary ++> insurance;

    rent +>:Covers:+> BankRow(label="Landlord debit", amount=1200.0);
    salary +>:Covers:+> BankRow(label="Payroll credit", amount=2500.0);
    root ++> BankRow(label="Coffee shop", amount=4.5);

    root spawn SxBooker();
    root spawn Applier();

    matched = [r for r in [-->] if r is BankRow and r.matched];
    print(f"{len(matched)} of the recurring rows were matched, none double-booked");
}

