"""Plan-DAG: replace hand-rolled recursive cycle detection with a walker,
and derive execution order from depends_on edges instead of list order."""

node Task {
    has name: str = "";
    has done: bool = False;
}

edge DependsOn {
    has reason: str = "";
}

walker DagChecker {
    has on_stack: dict = {};
    has ordered: list = [];
    has cycle_found: bool = False;

    def emit_sorted() -> list[str] {
        return [t for t in self.ordered];
    }

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can order with Task entry {
        # Cycle guard is domain logic: explicit stack set (no built-in dedup).
        if self.cycle_found {
            disengage;
        }
        if here.name in self.on_stack {
            print(f"CycleError: {here.name} participates in a cycle");
            self.cycle_found = True;
            disengage;
        }
        self.on_stack[here.name] = True;
        # Visit unvisited dependencies first, then record this task:
        pending = [d for d in [here->:DependsOn:->] if d.name not in self.on_stack];
        if pending {
            visit [here->:DependsOn:->] else { self.on_stack[here.name] = False; disengage; }
        } else {
            self.on_stack[here.name] = False;
            self.ordered.append(here.name);
            visit [-->] else { disengage; }
        }
    }
}

walker Executor {
    has plan_order: list[str] = [];
    has derived_order: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can run with Task entry {
        if here.name not in self.plan_order {
            self.plan_order.append(here.name);
        }
        here.done = True;
        print(f"ran {here.name}");
        visit [-->] else { disengage; }
    }
}

