edge MergedFrom {
    has deduped: int = 0;
}

walker AnimationMerger {
    has visited: dict = {};
    has loader_lookup: dict = {};
    has merged: dict = {};

    can start with Root entry {
        visit [->:SuperModel:->];
    }

    can load_models with MdlModel entry {
        # The Func<string, MdlModel?> loader analogue: index chain roots
        # so parents can be resolved by name during the walk.
        self.loader_lookup[here.name] = here;
        visit [->:SuperModel:->];
    }

    can merge with MdlModel entry {
        # Cycle guard from the source: skip already-visited models.
        if here.name in self.visited {
            print(f"cycle guard: {here.name} already merged, skipping");
            disengage;
        }
        self.visited[here.name] = True;
        # Append parent animations by name, deduping.
        for anim in here.animations {
            if anim not in self.merged {
                self.merged[anim] = here.name;
            }
        }
        visit [->:SuperModel:->] else {
            # Record the merge result on the chain root.
            here +>:MergedFrom(deduped=len(self.merged)):+> here;
            print(f"merged chain of {len(self.visited)} models: "
                  f"{sorted(self.merged.keys())}");
            disengage;
        }
    }
}

