"""TinyChain ORM demo: Class-aware member resolution with bounded mutation checks.

Nodes: TinyClass (Class definitions), Member (classified members), Collection
(backing stores). Typed edges carry ``Extends`` (inheritance/generalization)
and ``BackedBy`` (member -> collection) relationships. The ``Mutator`` walker
resolves a member through the Class resolution order (walking ``Extends``
edges) and dispatches the write only when the resolved member's
classification and backing collection authorize it — prototype presence
alone never grants mutation authority.
"""

edge Extends {
    has ordinal: int = 0;
}

edge BackedBy {
    has path: str = "";
}

node TinyClass {
    has name: str = "";
    has revision: int = 1;
}

node Member {
    has name: str = "";
    # 1=stored-writable 2=bounded-view 3=stored-readonly
    # 4=derived 5=prototype 6=method 7=relationship 8=opaque
    has classification: int = 8;
    has writable: bool = False;
    has value: str = "";
}

node Collection {
    has path: str = "";
    has supports_update: bool = True;
    has version: int = 0;
}

walker Mutator {
    has target_member: str = "";
    has new_value: str = "";
    has found: bool = False;
    has result: str = "member not found";

    can start with Root entry {
        visit [-->];
    }

    can resolve with TinyClass entry {
        """Resolution order: instance-local, then Extends ancestors."""
        for m in [here ->:BackedBy:->] {
            if m.name == self.target_member {
                self.found = True;
                self.dispatch(m);
                disengage;
            }
        }
        visit [->:Extends:->];
    }

    def dispatch(m: Member) {
        if not m.writable {
            self.result = f"'{m.name}' is classified "
                + f"{m.classification}; not assignable";
            return;
        }
        target = [m ->:BackedBy:->];
        if not target {
            self.result = f"'{m.name}' writable but unbacked";
            return;
        }
        col = target[0];
        if not col.supports_update {
            self.result = f"collection '{col.path}' rejects updates";
            return;
        }
        m.value = self.new_value;
        col.version += 1;
        self.result = f"mutated '{m.name}' via '{col.path}' "
            + f"(v{col.version})";
    }
}

walker Auditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Member entry {
        tag = "WRITABLE" if here.writable else "READONLY";
        backings = [here ->:BackedBy:->];
        path = backings[0].path if backings else "none";
        print(f"[{tag}] {here.name} (class {here.classification}) "
              f"backed by {path}");
        visit [-->] else { disengage; }
    }
}

with entry {
    base = TinyClass(name="Entity", revision=2);
    sub = TinyClass(name="Account", revision=1);
    sub +>:Extends(ordinal=0):+> base;

    id_m = Member(name="id", classification=3, writable=False, value="A-1");
    name_m = Member(name="name", classification=1, writable=True, value="Ada");
    derived_m = Member(name="display", classification=4, writable=False);
    sub ++> id_m ++> name_m ++> derived_m;

    accounts = Collection(path="/class/Account", supports_update=True);
    name_m +>:BackedBy(path="/class/Account/name"):+> accounts;

    audit = Auditor();
    root spawn audit;

    mut_name = Mutator(target_member="name", new_value="Grace");
    sub spawn mut_name;
    print(mut_name.result);

    mut_derived = Mutator(target_member="display", new_value="x");
    sub spawn mut_derived;
    print(mut_derived.result);
}

"""SongDNA production gate graph: issues as nodes, dependencies as typed
edges, and a walker that performs dependency-ordered traversal with an
explicit visited guard and depth cap (jac walkers do not dedupe visits)."""

