        # Cycle guard: without it, a dependency cycle loops forever.
        if here.title in self.order {
            print(f"cycle detected at {here.title}; skipping");
        } else {
            here.resolved = True;
            self.order.append(here.title);
            print(f"gate cleared: {here.title} ({here.role})");
            self.steps += 1;
            if self.steps > self.max_steps {
