"""Delegated agent tasks: typed Delegation edges and a cascade walker that
propagates pause/resume/cancel down the task tree (issue #143 mechanics)."""

edge Delegation {
    has mode: str = "async";           # sync | async
    has pause_propagation: str = "cascade";  # cascade | isolate
    has status: str = "pending";       # pending | running | paused | done | canceled
}

node Task {
    has name: str = "";
    has state: str = "running";        # running | paused | done | canceled
    has parent_task_id: str = "";      # public-API compat: kept, edges serve traversal

    def is_active() -> bool {
        return self.state == "running" or self.state == "paused";
    }
    def apply(action: str) -> str {
        """Cancel always wins; pause/resume only touch live tasks."""
        if action == "cancel" {
            self.state = "canceled";
        } elif action == "pause" and self.state == "running" {
            self.state = "paused";
        } elif action == "resume" and self.state == "paused" {
            self.state = "running";
        }
        return self.state;
    }
}

walker Cascade {
    has action: str = "pause";
    has seen: list[str] = [];          # explicit cycle policy (no builtin dedupe)

    def visit_guard(t: Task) -> bool {
        if t.name in self.seen {
            return False;
        }
        self.seen.append(t.name);
        return True;
    }

    can start with Root entry {
        visit [->:Delegation:->] else { disengage; }
    }

    can forward with Task entry {
        if not self.visit_guard(here) {
            disengage;
        }
        new_state = here.apply(self.action);
        print(f"{self.action} -> {here.name}: {new_state} "
              f"(parent={here.parent_task_id or 'none'})");
        # Forward the action to delegation children that cascade.
        for edge_obj in [here->:Delegation:->] {
            if edge_obj.pause_propagation == "cascade" {
                edge_obj.status = new_state if edge_obj.status != "done" else edge_obj.status;
            }
        }
        visit [->:Delegation:->] else { disengage; }
    }
}

walker Delegate {
    has child_name: str = "";
    has mode: str = "async";
    has pause_propagation: str = "cascade";

    can launch with Task entry {
        # Registration while paused: propagate immediately (edge case 2).
        eff_prop = self.pause_propagation;
        if here.state == "paused" and eff_prop == "cascade" {
            print(f"parent {here.name} paused: child starts paused too");
        }
        child = Task(name=self.child_name, parent_task_id=here.name);
        here +>:Delegation(mode=self.mode, pause_propagation=eff_prop):+> child;
        print(f"delegated {here.name} -> {self.child_name} ({self.mode})");
    }
}

walker StatusReport {
    can start with Root entry {
        visit [-->];
    }
    can peek with Task entry {
        print(f"[peek] {here.name}: {here.state}");
        visit [-->];
    }
}

with entry {
    root_task = Task(name="parent");
    root ++> root_task;

    # Fan out two async delegations, one isolated.
    root_task spawn Delegate(child_name="child_a", mode="async");
    root_task spawn Delegate(child_name="child_b", mode="async");
    root_task spawn Delegate(child_name="background", mode="async",
                             pause_propagation="isolate");

    # child_a delegates further: two-level tree.
    child_a_node = [root_task->:Delegation:->][0];
    child_a_node spawn Delegate(child_name="grandchild", mode="async");

    print("--- cascade pause (tree default) ---");
    root_task spawn Cascade(action="pause");

    print("--- resume ---");
    root_task spawn Cascade(action="resume");

    print("--- cancel wins over pause ---");
    root_task spawn Cascade(action="cancel");

    print("--- final status ---");
    root spawn StatusReport();
}

