"""Service dependency graph with cycle detection that guards missing service references."""

node Service {
    has name: str = "";
    # missing: dependency declared but the Service node for it does not exist
}

edge DependsOn { }

walker CycleDetector {
    has missing: list[str] = [];
    has cycles: list[str] = [];
    has visited: dict = {};

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can inspect with Service entry {
        here.report(self);
        visit [->:DependsOn:->] else { disengage; }
    }

    def report(here_node: Service) {
        # Guard: only traverse real Service nodes; dangling deps reported separately.
        return None;
    }
}

walker Auditor {
    has missing: list[str] = [];
    has visited: dict = {};
    has path: list[str] = [];
    has cycles: list[str] = [];

    can start with Root entry {
        self.path = [];
        visit [->:DependsOn:->];
    }

    def record_missing(name: str) {
