# Cycle detection with explicit guard: a dependency edge is only followed
# when the target Service node actually exists; dangling references are
# reported instead of being silently visited and polluting the visited set.
walker DepAuditor {
    has missing: list[str] = [];
    has cycles: list[str] = [];
    has visited: dict = {};
    has stack: dict = {};

    def check(target: Service) {
        key = target.name;
        if key in self.stack {
            self.cycles.append(f"{key} (path: {' -> '.join(list(self.stack.keys()) + [key])})");
            return;
        }
        if key in self.visited {
            return;
        }
        self.visited[key] = True;
        self.stack[key] = True;
        for dep in [target-->] {
            # guard: only walk real Service nodes; dangling deps reported
            self.check(dep);
        }
        self.stack del key;
    }
}

walker GuardedDetector {
    has missing: list[str] = [];
    has cycles: list[str] = [];
    has visited: dict = {};

    can sweep with Service entry {
        self.dfs(here);
        visit [->:DependsOn:->];
    }

    def dfs(node: Service) {
        if node.name in self.visited {
            return;
        }
        self.visited[node.name] = True;
        for edge_ref in [node->:DependsOn:->] {
            dep = edge_ref;
            self.dfs(dep);
        }
    }
}

walker GuardRunner {
    has missing: list[str] = [];

    can report with Service entry {
        visit [-->];
    }
}

walker CycleCheck {
    has missing: list[str] = [];
    has cycles: list[str] = [];
    has visited: dict = {};
    has in_stack: dict = {};

    can start with Root entry {
        visit [->:DependsOn:->] else { disengage; }
    }

    can check with Service entry {
        if here.name not in self.visited {
            self.walk(here);
        }
        visit [->:DependsOn:->] else { disengage; }
    }

    def walk(node: Service) {
        self.visited[node.name] = True;
        self.in_stack[node.name] = True;
        # Cycle guard: report a cycle when we would re-enter the current path.
        for dep in [node->:DependsOn:->] {
            if dep.name in self.in_stack {
                self.cycles.append(f"cycle involving {dep.name}");
            } else {
                self.walk(dep);
            }
        }
        self.in_stack del node.name;
    }
}

walker Main {
    can start with Root entry {
        root spawn CycleCheck();
    }
}

with entry {
    auth = Service(name="auth");
    db = Service(name="db");
    api = Service(name="api");
    root ++> auth;
    auth +>:DependsOn:+> db;
    db +>:DependsOn:+> api;
    api +>:DependsOn:+> auth;
