"""Delegated agent tasks: typed Delegation edges and a cascade walker that
propagates pause/resume/cancel down the task tree (issue #143 mechanics)."""

edge Delegation {
    has mode: str = "async";                 # sync | async
    has pause_propagation: str = "cascade";  # cascade | isolate
    has status: str = "pending";             # pending | paused | running | done | canceled
}

node Task {
    has name: str = "";
    has state: str = "running";  # running | paused | done | canceled
    has parent_task_id: str = "";

    def apply(action: str) -> str {
        """Cancel always wins; pause/resume only touch live tasks."""
        if action == "cancel" {
            self.state = "canceled";
        } elif action == "pause" and self.state == "running" {
            self.state = "paused";
        } elif action == "resume" and self.state == "paused" {
            self.state = "running";
        }
        return self.state;
    }

    def mark_edges(action: str) {
        """Forward the new state onto cascade delegation edges."""
        for e in edges(self) {
            if isinstance(e, Delegation) and e.pause_propagation == "cascade" {
                done = e.status == "done";
                if not done {
                    e.status = action;
                }
            }
        }
    }
}

walker Cascade {
    has action: str = "pause";
    has seen: list[str] = [];  # explicit cycle policy (no builtin dedupe)

    def visit_guard(t: Task) -> bool {
        if t.name in self.seen {
            return False;
        }
        self.seen.append(t.name);
        return True;
    }

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can forward with Task entry {
        if not self.visit_guard(here) {
            disengage;
        }
        new_state = here.apply(self.action);
        here.mark_edges(self.action);
        label = here.parent_task_id if here.parent_task_id else "none";
        print(f"{self.action} -> {here.name}: {new_state} (parent={label})");
        visit [->:Delegation:->] else { disengage; }
    }
}

walker StatusReport {
    can start with Root entry {
        visit [-->];
    }
    can peek with Task entry {
        print(f"[peek] {here.name}: {here.state}");
        visit [-->];
    }
}

with entry {
    parent = Task(name="parent");
    root ++> parent;

    child_a = Task(name="child_a", parent_task_id="parent");
    child_b = Task(name="child_b", parent_task_id="parent");
    background = Task(name="background", parent_task_id="parent");
    grandchild = Task(name="grandchild", parent_task_id="child_a");

    parent +>:Delegation(mode="async"):+> child_a;
    parent +>:Delegation(mode="async"):+> child_b;
    parent +>:Delegation(mode="async", pause_propagation="isolate"):+> background;
    child_a +>:Delegation(mode="async"):+> grandchild;

    print("--- cascade pause (tree default) ---");
    parent spawn Cascade(action="pause");

    print("--- resume ---");
    parent spawn Cascade(action="resume");

    print("--- cancel wins over pause ---");
    parent spawn Cascade(action="cancel");

    print("--- final status ---");
    root spawn StatusReport();
}

"""TinyChain ORM demo: Class-aware member resolution with bounded mutation checks.

Nodes: TinyClass (Class definitions), Member (classified members), Collection
(backing stores). Typed edges carry ``Extends`` (inheritance/generalization)
and ``BackedBy`` (member -> collection) relationships. The ``Mutator`` walker
resolves a member through the Class resolution order (walking ``Extends``
edges) and dispatches the write only when the resolved member's
classification and backing collection authorize it — prototype presence
alone never grants mutation authority.
"""

edge Extends {
    has ordinal: int = 0;
}

edge BackedBy {
    has path: str = "";
}

node TinyClass {
    has name: str = "";
    has revision: int = 1;
}

node Member {
    has name: str = "";
    # 1=stored-writable 2=bounded-view 3=stored-readonly
    # 4=derived 5=prototype 6=method 7=relationship 8=opaque
    has classification: int = 8;
    has writable: bool = False;
    has value: str = "";
}

node Collection {
    has path: str = "";
    has supports_update: bool = True;
    has version: int = 0;
}

walker Mutator {
    has target_member: str = "";
    has new_value: str = "";
    has result: str = "member not found";

    can start with Root entry {
        visit [-->];
    }

    can resolve with TinyClass entry {
        # Resolution order: instance-local, then Extends ancestors.
        for m in [here->:BackedBy:->] {
            if m.name == self.target_member {
                self.dispatch(m);
                disengage;
            }
        }
        visit [->:Extends:->];
    }

    def dispatch(m: Member) {
        if not m.writable {
            cls = str(m.classification);
            self.result = f"'{m.name}' is classified {cls}; not assignable";
            return;
        }
        target = [m->:BackedBy:->];
        if not target {
            self.result = f"'{m.name}' writable but unbacked";
            return;
        }
        col = target[0];
        if not col.supports_update {
            self.result = f"collection '{col.path}' rejects updates";
            return;
        }
        m.value = self.new_value;
        col.version += 1;
        ver = str(col.version);
        self.result = f"mutated '{m.name}' via '{col.path}' (v{ver})";
    }
}

walker Auditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Member entry {
        tag = "WRITABLE" if here.writable else "READONLY";
        backings = [here->:BackedBy:->];
        path = backings[0].path if backings else "none";
        cls = str(here.classification);
        print(f"[{tag}] {here.name} (class {cls}) backed by {path}");
        visit [-->] else { disengage; }
    }
}

with entry {
    base = TinyClass(name="Entity", revision=2);
    sub = TinyClass(name="Account", revision=1);
    sub +>:Extends(ordinal=0):+> base;

    id_m = Member(name="id", classification=3, writable=False, value="A-1");
    name_m = Member(name="name", classification=1, writable=True, value="Ada");
    derived_m = Member(name="display", classification=4, writable=False);
    sub ++> id_m ++> name_m ++> derived_m;

    accounts = Collection(path="/class/Account", supports_update=True);
    name_m +>:BackedBy(path="/class/Account/name"):+> accounts;

    root spawn Auditor();

    mut_name = Mutator(target_member="name", new_value="Grace");
    root spawn mut_name;
    print(mut_name.result);

    mut_derived = Mutator(target_member="display", new_value="x");
    root spawn mut_derived;
    print(mut_derived.result);
}

"""Shared supermodel animation merge: one walker walks the SuperModel chain,
guards cycles with a visited set, and appends parent animations by name.
Quartermaster and Reliquary both reuse this single implementation."""

node MdlModel {
    has name: str = "";
    has animations: list[str] = [];
}

edge SuperModel { }

walker AnimationMerger {
    has visited: dict = {};
    has merged: list[str] = [];
    has chain: list[str] = [];

    can start with Root entry {
        visit [->:SuperModel:->] else { disengage; }
    }

    can merge with MdlModel entry {
        # Cycle guard from the source: skip already-visited models.
        if here.name in self.visited {
            print(f"cycle guard: {here.name} already merged, skipping");
            disengage;
        }
        self.visited[here.name] = True;
        self.chain.append(here.name);
        # Append parent animations by name, deduping.
        for anim in here.animations {
            if anim not in self.merged {
                self.merged.append(anim);
            }
        }
        visit [->:SuperModel:->] else {
            print(f"merged chain of {len(self.chain)} models "
                  f"({', '.join(self.chain)}): {self.merged}");
            disengage;
        }
    }
}

with entry {
    # Child -> parent -> grandparent supermodel chain, starting at root.
    child = MdlModel(name="child", animations=["idle", "walk"]);
    parent = MdlModel(name="parent", animations=["idle", "attack", "walk"]);
    grandparent = MdlModel(name="grandparent", animations=["cast", "idle"]);

    root +>:SuperModel:+> child;
    child +>:SuperModel:+> parent;
    parent +>:SuperModel:+> grandparent;

    # Duplicate merge logic must NOT exist: one shared walker serves
    # both the Quartermaster and Reliquary consumers.
    root spawn AnimationMerger();
}

