"""Cycle detection over a service dependency graph.

Guards against the issue in transformToGraph: a dependency that references
a missing service is reported separately and never enters the visited set
or the recursion stack, so it cannot mask real cycles or produce misleading
paths.
"""

node Service {
    has name: str = "";
}

# A dependency that is referenced but has no real service behind it.
node Ghost {
    has name: str = "";
}

edge DependsOn { }

walker CycleDetector {
    has visited: dict = {};
    has in_stack: dict = {};
    has cycles: list[str] = [];
    has missing: list[str] = [];
    has path: list[str] = [];

    can start with Root entry {
        visit [->:DependsOn:->] else { disengage; }
    }

    # A missing service is reported but NOT added to visited/in_stack,
    # exactly the guard the issue asks for.
    can skip_missing with Ghost entry {
        if here.name not in self.missing {
            self.missing.append(here.name);
            print(f"[missing] dependency '{here.name}' does not exist; skipped");
        }
    }

    can check with Service entry {
        if here.name not in self.visited {
            self.dfs(here);
        }
        visit [->:DependsOn:->] else { disengage; }
    }

    def dfs(node: Service) {
        self.visited[node.name] = True;
        self.in_stack[node.name] = True;
        self.path.append(node.name);
        for dep in [node->:DependsOn:->] {
            if dep.name in self.in_stack {
                start_at = self.path.index(dep.name);
                loop = self.path[start_at:] + [dep.name];
                self.cycles.append(" -> ".join(loop));
            } else if dep.name not in self.visited {
                self.dfs(dep);
            }
        }
        self.path.pop();
        self.in_stack del node.name;
    }
}

with entry {
    auth = Service(name="auth");
    db = Service(name="db");
    api = Service(name="api");
    root ++> auth;
    auth +>:DependsOn:+> db;
    db +>:DependsOn:+> api;
    api +>:DependsOn:+> auth;
    # dangling dependency: "cache" is referenced but no Service exists for it
    api +>:DependsOn:+> Ghost(name="cache");

    detector = CycleDetector();
    root spawn detector;

    print(f"cycles found: {detector.cycles}");
    print(f"missing services: {detector.missing}");
    print(f"visited set: {sorted(list(detector.visited.keys()))}");
}

"""Incremental index updates: hash sections, detect changes, rebuild only affected branches."""

node Section {
    has title: str = "";
    has content_hash: str = "";
    has summary: str = "";
    has version: int = 1;
}

node Document {
    has doc_name: str = "";
}

edge Contains {
    has order: int = 0;
}

edge Impact {
    has note: str = "";
}

walker HashAuditor {
    has changed_hashes: dict = {};
    has rebuilt: int = 0;

    can start with Document entry {
        print(f"Auditing document: {here.doc_name}");
        visit [->:Contains:->];
    }

    # Detect changed sections by content hash; rebuild only affected branches.
    can audit with Section entry {
        new_hash = self.changed_hashes.get(here.title, here.content_hash);
        if new_hash != here.content_hash {
            here.content_hash = new_hash;
            here.version += 1;
            self.rebuilt += 1;
            print(f"[CHANGED] {here.title} -> rebuild subtree, bump to v{here.version}");
            # touch impacted ancestors so summaries recompute along the path
            for parent in here<--:Contains:--; (pare) {
                parent.summary = f"summary({here.title}) v{here.version}";
                print(f"[INVALIDATED] summary of '{parent.title}' refreshed");
            }
        } else {
            print(f"[CLEAN] {here.title} (v{here.version})");
        }
        visit [->:Contains:->];
    }
}

walker Rebuilder {
    # Cascade rebuild: walk and refresh summaries down impacted edges only.
    has touched: list = [];

    can start with Document entry {
        visit [->:Contains:->];
    }

    can rebuild with Section entry {
        if here.summary == "" {
            here.summary = f"auto summary for {here.title}";
            self.touched.append(here.title);
        }
        visit [->:Impact:->];
        visit [->:Contains:->];
    }
}

with entry {
    doc = Document(doc_name="Policy Manual");
    root ++> doc;

    ch1 = Section(title="Chapter 1", content_hash="aaa");
    s1a = Section(title="1.1 Scope", content_hash="b1");
    s1b = Section(title="1.2 Policy", content_hash="b2");
    ch2 = Section(title="Chapter 2", content_hash="ccc");
    s2a = Section(title="2.1 Compliance", content_hash="d1");

    doc +>:Contains(order=1):+> ch1;
    ch1 +>:Contains(order=1):+> s1a;
    ch1 +>:Contains(order=2):+> s1b;
    doc +>:Contains(order=2):+> ch2;
    ch2 +>:Contains(order=1):+> s2a;

    # an impact link: changing 1.1 affects the chapter summary path
    s1a +>:Impact(note="summary propagation"):+> ch1;

    root spawn Rebuilder();
    print("--- applying revision: 1.1 Scope changed ---");
    root spawn HashAuditor(changed_hashes={"1.1 Scope": "b1-revised"});
    print(f"rebuilt {HashAuditor.rebuilt} sections");
}

"""Final retirement gate: audit legacy Chat stack deletion while preserving
commit-linked source/evidence history and enforcing the deletion lock."""

node Source {
    has label: str = "";
    has retained: bool = True;
}

node Conversation {
    has title: str = "";
    has legacy: bool = False;
    has deletion_locked: bool = False;
    has writes_retired: bool = False;

    def accept_write() -> bool {
        if self.deletion_locked {
            return False;
        }
        return not (self.legacy and self.writes_retired);
    }
}

node Commit {
    has message: str = "";
    has legacy_layout: bool = False;
    has yops_log_id: str = "";

    def renders_honestly(evidence_gone: bool) -> str {
        if evidence_gone {
            return "PARTIAL (assurance weakened)";
        }
        return "full";
    }
}

edge Cites { }
edge Contains { }
edge Locked { }

walker RetireAuditor {
    has ok_commits: int = 0;
    has blocked_writes: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Commit entry {
        missing = 0;
        for src in [here ->:Cites:->] {
            if not src.retained {
                missing += 1;
            }
        }
        verdict = here.renders_honestly(missing > 0);
        if missing > 0 {
            print(f"BROKEN: commit '{here.message}' lost source evidence");
        } else {
            self.ok_commits += 1;
            print(f"commit '{here.message}' ({verdict} history, yops={here.yops_log_id}) resolves sources");
        }
        visit [-->];
    }

    can enforce with Conversation entry {
        allowed = here.accept_write();
        if allowed {
            print(f"conversation '{here.title}' still writable");
        } else {
            self.blocked_writes += 1;
            print(f"write REJECTED to '{here.title}' (retired legacy storage / lock)");
        }
        visit [->:Contains:->];
    }

    can check_turn with Turn entry {
        print(f"immutable turn preserved: '{here.text}'");
        visit [-->];
    }
}

node Turn {
    has text: str = "";
}

with entry {
    s1 = Source(label="doc.md@abc123");
    s2 = Source(label="notes.txt@def456");
    conv = Conversation(title="design chat", deletion_locked=True);
    legacy_conv = Conversation(title="old workbench thread", legacy=True, writes_retired=True);
    turn = Turn(text="why not storage-first?");

    c1 = Commit(message="add docs", yops_log_id="y-1");
    c2 = Commit(message="legacy import", legacy_layout=True, yops_log_id="y-2");
    c1 +>:Cites:+> s1;
    c2 +>:Cites:+> s1;
    c2 +>:Cites:+> s2;
    conv +>:Contains:+> turn;
    conv +>:Locked:+> turn;

    root ++> c1 ++> c2 ++> conv ++> legacy_conv;
    root spawn RetireAuditor();
    print(f"audited {RetireAuditor.ok_commits} clean commits; blocked {RetireAuditor.blocked_writes} legacy writes");
}

