"""Delegated agent tasks: typed Delegation edges and a cascade walker that
propagates pause/resume/cancel down the task tree (issue #143 mechanics)."""

edge Delegation { }

node Task {
    has name: str = "";
    has state: str = "running";   # running | paused | done | canceled
    has parent_task_id: str = "";
    has isolate: bool = False;    # pause_propagation="isolate" children run independently

    def apply(action: str) -> str {
        """Cancel always wins; pause/resume only touch live tasks."""
        if action == "cancel" {
            self.state = "canceled";
        } else {
            if action == "pause" and self.state == "running" {
                self.state = "paused";
            }
            if action == "resume" and self.state == "paused" {
                self.state = "running";
            }
        }
        return self.state;
    }
}

walker Cascade {
    has action: str = "pause";
    has seen: list[str] = [];  # explicit cycle policy (no builtin dedupe)

    def visit_guard(t: Task) -> bool {
        if t.name in self.seen {
            return False;
        }
        self.seen.append(t.name);
        return True;
    }

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can forward with Task entry {
        if not self.visit_guard(here) {
            disengage;
        }
        new_state = here.apply(self.action);
        label = here.parent_task_id if here.parent_task_id else "none";
        print(f"{self.action} -> {here.name}: {new_state} (parent={label})");
        # cancel always wins regardless of pause state; isolated children
        # are simply not visited (no propagation along their edges)
        if here.isolate and self.action != "cancel" {
            disengage;
        }
        visit [->:Delegation:->] else { disengage; }
    }
}

walker StatusReport {
    can start with Root entry {
        visit [-->];
    }
    can peek with Task entry {
        print(f"[peek] {here.name}: {here.state}");
        visit [-->];
    }
}

with entry {
    parent = Task(name="parent");
    root ++> parent;

    child_a = Task(name="child_a", parent_task_id="parent");
    child_b = Task(name="child_b", parent_task_id="parent");
    background = Task(name="background", parent_task_id="parent", isolate=True);
    grandchild = Task(name="grandchild", parent_task_id="child_a");

    parent +>:Delegation:+> child_a;
    parent +>:Delegation:+> child_b;
    parent +>:Delegation:+> background;
    child_a +>:Delegation:+> grandchild;

    print("--- cascade pause (tree default) ---");
    parent spawn Cascade(action="pause");

    print("--- resume ---");
    parent spawn Cascade(action="resume");

    print("--- cancel wins over pause ---");
    parent spawn Cascade(action="cancel");

    print("--- final status ---");
    root spawn StatusReport();
}

