"""Cycle detection over a service dependency graph.

Guards against the issue in transformToGraph: a dependency that references
a missing service is reported separately and never enters the visited set
or the recursion stack, so it cannot mask real cycles or produce misleading
paths.
"""

node Service {
    has name: str = "";
}

# A dependency that is referenced but has no real service behind it.
node Ghost {
    has name: str = "";
}

edge DependsOn { }

walker CycleDetector {
    has visited: dict = {};
    has in_stack: dict = {};
    has cycles: list[str] = [];
    has missing: list[str] = [];
    has path: list[str] = [];

    can start with Root entry {
        visit [->:DependsOn:->] else { disengage; }
    }

    # A missing service is reported but NOT added to visited/in_stack,
    # exactly the guard the issue asks for.
    can skip_missing with Ghost entry {
        if here.name not in self.missing {
            self.missing.append(here.name);
            print(f"[missing] dependency '{here.name}' does not exist; skipped");
        }
    }

    can check with Service entry {
        if here.name not in self.visited {
            self.dfs(here);
        }
        visit [->:DependsOn:->] else { disengage; }
    }

    def dfs(srv: Service) {
        self.visited[srv.name] = True;
        self.in_stack[srv.name] = True;
        self.path.append(srv.name);
        for dep in [srv->:DependsOn:->] {
            if dep.name in self.in_stack {
                start_at = self.path.index(dep.name);
                loop = self.path[start_at:] + [dep.name];
                self.cycles.append(" -> ".join(loop));
            } else if dep.name not in self.visited {
                self.dfs(dep);
            }
        }
        self.path.pop();
        self.in_stack.pop(srv.name);
    }
}

with entry {
    auth = Service(name="auth");
    db = Service(name="db");
    api = Service(name="api");
    root ++> auth;
    auth +>:DependsOn:+> db;
    db +>:DependsOn:+> api;
    api +>:DependsOn:+> auth;
    # dangling dependency: "cache" is referenced but no Service exists for it
    api +>:DependsOn:+> Ghost(name="cache");

    detector = CycleDetector();
    root spawn detector;

    print(f"cycles found: {detector.cycles}");
    print(f"missing services: {detector.missing}");
    print(f"visited set: {sorted(list(detector.visited.keys()))}");
}

