"""Incremental index updates: hash sections, detect changes, rebuild only affected branches."""

node Section {
    has title: str = "";
    has content_hash: str = "";
    has summary: str = "";
    has version: int = 1;
}

node Document {
    has doc_name: str = "";
}

edge Contains {
    has order: int = 0;
}

edge Impact {
    has note: str = "";
}

# Spawned on a changed section; follows impact links to ancestors and
# refreshes their summaries along the impacted path.
walker Invalidator {
    has source_title: str = "";
    has new_version: int = 1;

    can refresh with Section entry {
        here.summary = f"summary({self.source_title}) v{self.new_version}";
        print(f"[INVALIDATED] summary of '{here.title}' refreshed");
        visit [->:Impact:->];
    }
}

walker HashAuditor {
    has changed_hashes: dict = {};
    has rebuilt: int = 0;

    can start with Document entry {
        print(f"Auditing document: {here.doc_name}");
        visit [->:Contains:->];
    }

    # Detect changed sections by content hash; rebuild only affected branches.
    can audit with Section entry {
        new_hash = self.changed_hashes.get(here.title, here.content_hash);
        if new_hash != here.content_hash {
            here.content_hash = new_hash;
            here.version += 1;
            self.rebuilt += 1;
            print(f"[CHANGED] {here.title} -> rebuild subtree, bump to v{here.version}");
            Invalidator(source_title=here.title, new_version=here.version) spawn here;
        } else {
            print(f"[CLEAN] {here.title} (v{here.version})");
        }
        visit [->:Contains:->];
    }
}

walker Rebuilder {
    # Initial build: fill summaries and walk the full document tree.
    has touched: list = [];

    can start with Document entry {
        visit [->:Contains:->];
    }

    can rebuild with Section entry {
        if here.summary == "" {
            here.summary = f"auto summary for {here.title}";
            self.touched.append(here.title);
        }
        visit [->:Contains:->];
    }
}

