"""Kahn's topological sort lifted to Jac: vertices as nodes, dependencies as
typed edges, the BFS frontier as a walker — no list.pop(0), no index arrays,
so sparse vertex IDs are safe by construction."""

node Vertex {
    has vid: int = 0;
    has indegree: int = 0;
    has order_slot: int = -1;
}

edge DependsOn { }

edge Frontier { }

walker TopoSorter {
    has tick: int = 0;
    has visited: dict = {};

    can start with Root entry {
        visit [->:Frontier:->];
    }

    can process with Vertex entry {
        # Cycle policy: each vertex is finalized at most once; the indegree
        # bookkeeping below is the domain logic, not a visited-set crutch.
        if here.vid in self.visited {
            print(f"cycle detected at vertex {here.vid}");
            disengage;
        }
        here.order_slot = self.tick;
        self.tick += 1;
        print(f"slot {here.order_slot}: vertex {here.vid}");
        for kid in [here->:DependsOn:->] {
            kid.indegree -= 1;
        }
        self.visited[here.vid] = True;
        visit [here->:DependsOn:->];
    }
}

