# Spawned on a changed section; follows impact links to ancestors and
# refreshes their summaries along the impacted path.
walker Invalidator {
    has source_title: str = "";
    has new_version: int = 1;

    can refresh with Section entry {
        here.summary = f"summary({self.source_title}) v{self.new_version}";
        print(f"[INVALIDATED] summary of '{here.title}' refreshed");
        visit [->:Impact:->];
    }
}

