    has changed_hashes: dict[str, str] = {};
    has rebuilt: int = 0;

    can start with Document entry {
        print(f"Auditing document: {here.doc_name}");
        visit [->:Contains:->];
    }

    # Detect changed sections by content hash; rebuild only affected branches.
    can audit with Section entry {
        new_hash = self.changed_hashes.get(here.title, here.content_hash);
        if new_hash != here.content_hash {
