"""Package dependency graph: a walker hunts circular imports across layers.

Modules are layered (API -> managers -> stores -> builtins) and connected by
typed ``Imports`` edges. The ``CycleAuditor`` walker performs a DFS with an
explicit on-stack guard set (Jac 0.36 walkers have no built-in once-only
visitation), reporting every cycle it finds — exactly the undefined-import
hazard the issue describes.
"""

node Module {
    has name: str = "";
    has layer: str = "";
}

edge Imports { }

walker CycleAuditor {
    has path: list[str] = [];
    has on_stack: dict = {};
    has cycles_found: int = 0;

    def enter(node_name: str) -> None {
        self.path.append(node_name);
        self.on_stack[node_name] = True;
    }

    def leave(node_name: str) -> None {
        self.path.pop();
        self.on_stack[node_name] = False;
    }

    def report_cycle(node_name: str) -> None {
        start = 0;
        for (i, n) in enumerate(self.path) {
            if n == node_name {
                start = i;
            }
        }
        cycle = [self.path[i] for i in range(start, len(self.path))] + [node_name];
        print(f"CIRCULAR DEP: {" -> ".join(cycle)}");
        self.cycles_found += 1;
    }

    can start with Root entry {
        visit [->:Imports:->];
    }

    can audit with Module entry {
        if here.name in self.on_stack and self.on_stack[here.name] {
            self.report_cycle(here.name);
            self.leave(self.path[-1]);
            disengage;
        }
        self.enter(here.name);
        if [here->:Imports:->] {
            visit [here->:Imports:->];
        } else {
            self.leave(here.name);
            disengage;
        }
        self.leave(here.name);
    }
}

with entry {
    api_auth = Module(name="api/auth", layer="API");
    manager_session = Module(name="managers/session", layer="managers");
    store_user = Module(name="stores/user", layer="stores");
    builtin_fetch = Module(name="builtins/fetch", layer="builtins");

    # Healthy direction: API -> managers -> stores -> builtins
    api_auth +>:Imports:+> manager_session;
    manager_session +>:Imports:+> store_user;
    store_user +>:Imports:+> builtin_fetch;

    # The culprit: builtins imports back from stores, forming a cycle.
    builtin_fetch +>:Imports:+> store_user;

    root ++> api_auth;
    root spawn CycleAuditor();
}

"""Kahn's topological sort lifted to Jac: vertices as nodes, dependencies as
typed edges, the BFS frontier as a walker — no list.pop(0), no index arrays,
so sparse vertex IDs are safe by construction."""

node Vertex {
    has vid: int = 0;
    has indegree: int = 0;
    has order_slot: int = -1;
}

edge DependsOn { }

walker TopoSorter {
    has tick: int = 0;
    has finalized: dict = {};

    can process with Vertex entry {
        # Cycle policy: each vertex is finalized at most once.
        if here.vid in self.finalized {
            print(f"cycle detected at vertex {here.vid}");
            disengage;
        }
        here.order_slot = self.tick;
        self.tick += 1;
        print(f"slot {here.order_slot}: vertex {here.vid}");
        self.finalized[here.vid] = True;
        for kid in [here->:DependsOn:->] {
            kid.indegree -= 1;
        }
        visit [here->:DependsOn:->] else { disengage; }
    }
}

with entry {
    # Sparse, non-contiguous IDs: {10: [20, 30], 20: [40], 30: [40], 40: []}
    v10 = Vertex(vid=10);
    v20 = Vertex(vid=20);
    v30 = Vertex(vid=30);
    v40 = Vertex(vid=40);
