    v10 +>:DependsOn:+> v30;
    v20 +>:DependsOn:+> v40;
    v30 +>:DependsOn:+> v40;
    v10 spawn TopoSorter();
}

"""Matrix crypto-store persistence lifecycle: pending E2EE state must be flushed
before shutdown, not just on a 60s timer, or Olm/Megolm sessions are lost."""

node Session {
    has sender_key: str = "";
    has algorithm: str = "";
    has persisted: bool = False;
}

node KeyBackup {
    has recovery_key_cached: bool = False;
    has persisted: bool = False;
}

node CryptoStore {
    has clean_shutdown: bool = False;
    has dirty: bool = True;

    def mark_persisted() -> bool {
        self.dirty = False;
        return True;
    }
}

edge Holds { }
edge RestoredFrom { }

walker TimerFlush {
    """Defect A: the 60s timer — only visits if the tick happens to fire."""

    can start with Root entry {
        visit [-->];
    }

    can sweep with CryptoStore entry {
        if here.dirty {
            print(f"timer tick: flushing crypto store (clean={here.clean_shutdown})");
            visit [->:Holds:->];
            visit [->:RestoredFrom:->];
        } else {
            disengage;
        }
    }

    can persist with Session | KeyBackup entry {
        here.persisted = True;
        print(f"persisted {here} to disk");
        visit [-->];
    }
}

walker StopAndPersist {
    """Defect B fixed: shutdown walks the full graph and awaits final persist."""

    can start with Root entry {
        visit [-->];
    }

    can finalize with CryptoStore entry {
        print("stop(): initiating final persistence");
        visit [->:Holds:->];
        visit [->:RestoredFrom:->];
        visit [-->];
    }

    can persist with Session | KeyBackup entry {
        if not here.persisted {
            here.persisted = True;
            print(f"final flush wrote {here}");
        }
        visit [-->];
    }

    can seal with CryptoStore exit {
        if here.mark_persisted() {
            here.clean_shutdown = True;
            print(f"final persist awaited: cleanShutdown={here.clean_shutdown}");
        }
    }
}

with entry {
    store = CryptoStore();
    olm = Session(sender_key="curve25519:Zx4...qT", algorithm="m.olm.v1");
    megolm = Session(sender_key="curve25519:Aa9...kL", algorithm="m.megolm.v1");
    backup = KeyBackup(recovery_key_cached=True);

    root ++> store;
    store +>:Holds:+> olm;
    store +>:Holds:+> megolm;
    olm +>:RestoredFrom:+> backup;

    print("--- run 1: process dies before 60s timer (state lost) ---");
    root spawn TimerFlush();

    print("--- run 2: proper stop with awaited final persist ---");
    # re-dirty the store to model newly negotiated sessions since the tick
    store.dirty = True;
    megolm.persisted = False;
    root spawn StopAndPersist();

    print(f"cleanShutdown={store.clean_shutdown}, store dirty={store.dirty}");
}

"""Handover of a sub-task: dials on handover boundaries, not on arbitrary nodes.

Downward dial (hander-owned): shown | hidden | tombstoned — what the handee
sees of the chain above the boundary. Upward dial (handee-owned): whether
time/detail flows back. Visibility is cut at the boundary; inheritance stops
there, one hop.
"""

node User {
    has name: str = "";
}

node Task {
    has title: str = "";
    has effort: float = 0.0;
}

edge SubTask {
    has order: int = 0;
}

edge Handover {
    has downward: str = "tombstoned";  # hander sets: shown / hidden / tombstoned
    has upward: bool = True;           # handee sets: does effort flow back
}

node Tombstone {
    has title: str = "";
}

walker Handee {
    has visible_effort: float = 0.0;

    can start with Root entry {
        visit [->:Handover:->] else { disengage; }
    }

    can cross_boundary with Handover entry {
        # The boundary is where inheritance stops: rewrite the seen chain.
        if here.downward == "hidden" {
            print("handee sees: nothing above the boundary");
        } elif here.downward == "tombstoned" {
            parent = [here <--;
                      here <--];
            print("handee sees tombstoned ancestors above the boundary");
        } else {
            print("handee sees the full chain above");
        }
        visit [->:SubTask:->] else { disengage; }
    }

    can work with Task entry {
        print(f"working on: {here.title} ({here.effort}h)");
        self.visible_effort += here.effort;
        visit [->:SubTask:->] else { disengage; }
    }
}

walker HanderAudit {
    can start with Root entry {
        visit [->:SubTask:->] else { disengage; }
    }

    can audit with Task entry {
        print(f"hander sees own subtree: {here.title} ({here.effort}h) — nothing relocated");
        visit [->:SubTask:->] else { disengage; }
    }

    can audit_edge with Handover entry {
        status = "open" if here.upward else "closed — analysis dark for that subtree";
        print(f"upward dial (handee-owned): {status}");
        visit [->:SubTask:->] else { disengage; }
    }
}

with entry {
    felix = User(name="Felix");
    root ++> felix;

    # Felix's own tree: one tree, one truth — delegated work stays here.
    epic = Task(title="Wayfinder rollout", effort=40.0);
    felix ++> epic;
    epic ++> (design := Task(title="Design ADR", effort=6.0))
        ++> (research := Task(title="Prior-art research", effort=4.0));

