"""Path locks and dependency-aware scheduling over a task DAG.

Tasks are nodes connected by typed Requires edges. A Scheduler walker
walks the DAG, queueing children behind unresolved parents, enforcing
stack-depth limits and cycle detection, and acquiring shared/exclusive
PathLocks on high-contention resources: two tasks with incompatible
lock modes over the same path cannot both enter implementation.
"""

node PathLock {
    has path: str = "";
    has mode: str = "exclusive";       # "exclusive" | "shared"
    has owner: str = "";               # task name currently holding it
    has shared_owners: list[str] = list();

    def compatible_with(requested: str) -> bool {
        if requested == "shared" and self.mode == "shared" {
            return True;
        }
        if self.owner == "" and len(self.shared_owners) == 0 {
            return True;
        }
        return False;
    }

    def acquire(task: str, requested: str) -> bool {
        if not self.compatible_with(requested) {
            return False;
        }
        if requested == "shared" {
            if self.owner == "" and len(self.shared_owners) == 0 {
                self.mode = "shared";
            }
            self.shared_owners.append(task);
            return True;
        }
        self.mode = "exclusive";
        self.owner = task;
        return True;
    }

    def describe() -> str {
        if len(self.shared_owners) > 0 {
            holders = ",".join(self.shared_owners);
            return f"{self.path} [shared: {holders}]";
        }
        holder = self.owner if self.owner != "" else "free";
        return f"{self.path} [exclusive: {holder}]";
    }
}

node Task {
    has name: str = "";
    has risk: float = 0.0;
    has depth: int = 0;
    has status: str = "queued";        # queued | blocked | implementing
    has lock_mode: str = "exclusive";
    has paths: list[str] = list();

    def resolve_locks(here_locks: list[PathLock]) -> str {
        acquired = "";
        for lock in here_locks {
            if lock.acquire(self.name, self.lock_mode) {
                acquired = lock.path if acquired == "" else acquired + "," + lock.path;
            } else {
                self.status = "blocked";
                return lock.path;
            }
        }
        self.status = "implementing";
        return acquired;
    }
}

edge Requires { }

edge Locks { }

walker Scheduler {
    has depth_limit: int = 3;
    has held: dict = dict();
    has blocked_on: dict = dict();
    has visiting: set = set();

    can start with Root entry {
        visit [->:Requires:->];
    }

    can schedule with Task entry {
        # cycle guard: explicit, since visit does not dedupe
        if here.name in self.visiting {
            print(f"DEADLOCK: cycle detected at {here.name}");
            disengage;
        }
        if here.depth > self.depth_limit {
            print(f"FLATTENED: {here.name} exceeds depth {self.depth_limit}");
            disengage;
        }
        self.visiting.add(here.name);

        # children must wait behind unresolved parents: check edges back
        for parent in here <-:Requires:- {
            if parent.status != "implementing" {
                here.status = "blocked";
                self.blocked_on[here.name] = parent.name;
                print(f"{here.name} blocked behind {parent.name}");
                disengage;
            }
        }

        # acquire locks over declared hotspot paths
        here_locks = list[PathLock]();
        for e in here ->:Locks:-> {
            here_locks.append(e->);
        }
        got = here.resolve_locks(here_locks);
        if here.status == "blocked" {
            self.blocked_on[here.name] = got;
            print(f"{here.name} BLOCKED on lock {got}");
            disengage;
        }
        for p in here.paths {
            self.held[here.name + ":" + p] = here.status;
        }
        print(f"{here.name} implementing "
              f"(risk={here.risk:.2f}, depth={here.depth}): "
              f"locked {got}");

        visit [->:Requires:->];
    }
}

with entry {
    # resources (high-contention hotspots) as lockable nodes
    wf = PathLock(path=".github/workflows/ci.yml");
    mig1 = PathLock(path="db/migrations/0001_init.sql");
    mig2 = PathLock(path="db/migrations/0002_idx.sql");
    lockf = PathLock(path="package-lock.json");

    # two tasks predicted to hit the same workflow (incompatible modes)
    t1 = Task(name="ci-cache-fix", risk=0.9, lock_mode="exclusive",
              paths=[".github/workflows/ci.yml"]);
    t2 = Task(name="ci-badge-bot", risk=0.4, lock_mode="shared",
