"""Package dependency graph: an auditor hunts circular imports across layers.

Modules are layered (API -> managers -> stores -> builtins) and connected by
typed ``Imports`` edges. The ``CycleAuditor`` walker collects the module
graph, then performs an explicit DFS with an on-stack guard set (Jac 0.36
walkers have no built-in once-only visitation), reporting every cycle —
the undefined-import hazard the issue describes.
"""

node Module {
    has name: str = "";
    has layer: str = "";
}

edge Imports { }

walker CycleAuditor {
    has adj: dict[str, list[str]] = {};
    has on_stack: dict[str, bool] = {};
    has path: list[str] = [];
    has cycles_found: int = 0;

    can collect with Root entry {
        visit [->:Imports:->];
    }

    can collect with Module entry {
        neighbors = [];
        for (n in [here->:Imports:->]) {
            neighbors.append(n.name);
        }
        self.adj[here.name] = neighbors;
        visit [->:Imports:->] else { disengage; }
    }

    can finish with Root exit {
        for (m in self.adj.keys()) {
            if m not in self.on_stack {
                self.dfs(m);
            }
        }
        if self.cycles_found == 0 {
            print("No circular dependencies found.");
        } else {
            print(f"Audit found {self.cycles_found} circular dependencies.");
        }
    }

    def dfs(name: str) -> None {
        self.on_stack[name] = True;
        self.path.append(name);
        for (nb in self.adj[name]) {
            if nb in self.on_stack and self.on_stack[nb] {
                self.report_cycle(nb);
            } elif nb in self.adj {
                self.dfs(nb);
            }
        }
        self.path.pop();
        self.on_stack[name] = False;
    }

    def report_cycle(node_name: str) -> None {
        start = 0;
        for (i, n) in enumerate(self.path) {
            if n == node_name {
                start = i;
            }
        }
        cycle = self.path[start:] + [node_name];
        sep = " -> ";
        print(f"CIRCULAR DEP: {sep.join(cycle)}");
        self.cycles_found += 1;
    }
}

