}

"""Graph-lite traversal: BFS/DFS over typed edges with filters, depth caps, cycle safety.

Traverser respects node-type and edge-type filters applied as edges are
considered, tracks an explicit visited set (jac walkers do not dedupe), and
reports a `truncated` flag so partial answers are recognisable.
"""

node Symbol {
    has name: str = "";
}

node Module {
    has name: str = "";
    has path: str = "";
}

edge References { has weight: int = 1; }
edge Contains { }

walker Traverser {
    has dfs: bool = False;
    max_depth: int = 3;  # depth bound
    max_results: int = 5;  # result bound
    has edge_type: str = "any";  # "References" | "Contains" | "any"
    has target_kind: str = "any";  # "Symbol" | "Module" | "any"

    has visited: dict = {};
    has frontier: list = [];
    has results: list = [];
    has truncated: bool = False;
    has start: object = None;

    def consider(node_obj: object, depth: int) -> bool {
        # filter applied as the edge is considered, before enqueueing
        if node_obj in self.visited {
            return False;
        }
        if self.target_kind == "Symbol" and node_obj.type != Symbol {
            return False;
        }
        if self.target_kind == "Module" and node_obj.type != Module {
            return False;
        }
        self.visited[node_obj] = True;
        self.frontier.append((node_obj, depth));
        return True;
    }

    def edges_of(here_node: object) -> list {
        out = [];
        if self.edge_type == "any" {
            out = [e._target for e in here_node._out_edges];
        } elif self.edge_type == "References" {
            out = [e._target for e in here_node._out_edges if e.type == References];
        } else {
            out = [e._target for e in here_node._out_edges if e.type == Contains];
        }
        return out;
    }

    can begin with Root entry {
        if self.start is None {
            report {
                "results": self.results,
                "truncated": True,
                "error": "no start node",
            };
            disengage;
        }
        self.visited[self.start] = True;
        self.frontier.append((self.start, 0));
        self.run();
        report {
            "results": self.results,
            "truncated": self.truncated,
            "order": "dfs" if self.dfs else "bfs",
            "edge_filter": self.edge_type,
            "node_filter": self.target_kind,
        };
        disengage;
    }

    def run() {
        while len(self.frontier) > 0 {
            if self.dfs {
                (node_obj, depth) = self.frontier.pop();
            } else {
                (node_obj, depth) = self.frontier.pop(0);
            }
            is_match = (
                (self.target_kind == "Symbol" and node_obj.type == Symbol)
                or (self.target_kind == "Module" and node_obj.type == Module)
                or self.target_kind == "any"
            );
            if is_match {
                self.results.append(node_obj);
                if len(self.results) >= self.max_results {
                    self.truncated = len(self.edges_of(node_obj)) > 0 or len(self.frontier) > 0;
                    return;
                }
            }
            if depth >= self.max_depth {
                continue;
            }
            for nxt in self.edges_of(node_obj) {
                self.consider(nxt, depth + 1);
            }
        }
        self.truncated = False;
    }
}

