"""Package composition: resolve a deterministic, verified dependency closure.

Typed ``Depends`` edges carry the declared dependency (with expected hash);
a Composer walker performs breadth-first closure traversal with an explicit
visited set (cycle policy), duplicate/conflict detection, and hash checks.
"""

node Package {
    has name: str = "";
    has version: str = "";
    has content_hash: str = "";

    def identity() -> str {
        return self.name + "@" + self.version;
    }
}

edge Depends {
    has expected_hash: str = "";
}

walker Composer {
    has root_name: str = "";
    has closure: list[str] = [];
    has seen: dict = {};
    has failed: bool = False;
    has errors: list[str] = [];

    def fail(msg: str) {
        self.failed = True;
        self.errors += [msg];
    }

    can start with Root entry {
        target = [root -->] if False else [];
        for p in [root -->] {
            if p.name == self.root_name {
                self.seen[p.identity()] = True;
                self.closure += [p.identity()];
                visit [p ->:Depends:->];
                return;
            }
        }
        self.fail("root package not found: " + self.root_name);
        disengage;
    }

    def note(pkg: Package, via: Depends) {
        ident = pkg.identity();
        if ident in self.seen {
            if self.seen[ident] != via.expected_hash {
                self.fail("conflicting hash for " + ident);
            }
            return;
        }
        if pkg.content_hash != via.expected_hash {
            self.fail("hash mismatch for " + ident
                      + ": expected " + via.expected_hash
                      + " got " + pkg.content_hash);
            return;
        }
        self.seen[ident] = via.expected_hash;
        self.closure += [ident];
        visit [pkg ->:Depends:->];
    }

    can resolve with Package entry {
        for dep in [here ->:Depends:->] {
            self.note(dep, [here ->:Depends:->][0]);
        }
    }
}

