"""Topological dependency resolution (HARP-style application registry).

App nodes are connected with typed ``DependsOn`` edges.  A ``Surveyor``
walker computes each app's dependency count in O(N+E) by walking the
edges once (the reverse-lookup idea from issue #803), and a ``Resolver``
walker runs Kahn's algorithm natively: resolving an app visits its
dependents via ``visit [<--:DependsOn:--]`` — no nested scans, no
adjacency dicts.
"""

node App {
    has name: str = "";
    # pending = incoming visitations (root + one per dependency edge);
    # an app is resolvable when pending drops to 1.
    has pending: int = 0;
}

edge DependsOn { }

walker Surveyor {
    """Counts dependency edges per app in a single O(N+E) pass."""
    can start with Root entry {
        visit [-->];
    }

    can tally with App entry {
        here.pending += 1;
        visit [->:DependsOn:->];
    }
}

walker Resolver {
    has order: list[str] = [];
    has done: dict[str, bool] = {};
    has total: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can process with App entry {
        if here.name in self.done {
            return;
        }
        if here.pending > 1 {
            here.pending -= 1;
            return;
        }
        self.done[here.name] = True;
        self.order.append(here.name);
        # Reverse lookup: directly reach dependents of the resolved app.
        visit [<--:DependsOn:--];
    }

    can finish with Root exit {
        if len(self.order) < self.total {
            unresolved = "yes";
            print(f"cycle detected: only {len(self.order)}/{self.total} resolved");
        } else {
            unresolved = "no";
        }
        report self.order;
    }
}

with entry {
    auth = App(name="auth");
    api = App(name="api");
    web = App(name="web");
    worker = App(name="worker");

    # api -> auth, web -> auth, web -> api, worker -> api
    api +>:DependsOn:+> auth;
    web +>:DependsOn:+> auth;
    web +>:DependsOn:+> api;
    worker +>:DependsOn:+> api;

    root ++> auth ++> api ++> web ++> worker;

    root spawn Surveyor();
    root spawn Resolver(total=4);
}

"""Incremental rebuild granularity: body-only edits rebuild one unit, public-surface edits fan out.

SourceUnit nodes carry separate public and body hashes; DependsOn edges model
project dependencies. The Rebuilder walker invalidates only dependents whose
required public surface actually changed, and reports why a broad rebuild was forced.
"""

node SourceUnit {
    has name: str = "";
    has public_hash: str = "";
    has body_hash: str = "";
    has stale: bool = False;
}

edge DependsOn {
    # hashes of the dependency's public surface this unit was built against
    has built_against_public: str = "";
}

walker Rebuilder {
    has edited: str = "";
    has new_public: str = "";
    has new_body: str = "";
    has rebuilt: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can apply_edit with SourceUnit entry {
        if here.name == self.edited and not here.stale {
            broad = "public-surface change (dependents invalidated)" if here.public_hash != self.new_public else "body-only change (owner object + link only)";
            here.public_hash = self.new_public;
            here.body_hash = self.new_body;
            here.stale = True;
            self.rebuilt += 1;
            print(f"edit applied to {here.name}: {broad}");
        }
        visit [->:DependsOn:->];
    }

    # Dependents are units that hold a DependsOn edge pointing at a stale unit.
    can check with SourceUnit entry {
        if here.stale {
            return;
        }
        forced_by = "";
        for dep in here -->:DependsOn:--> :SourceUnit {
            if dep.stale and dep.public_hash != (here -->:DependsOn:--> :SourceUnit)[0].built_against_public {
                forced_by = dep.name;
            }
        }
        if forced_by != "" {
            here.stale = True;
            self.rebuilt += 1;
            print(f"FANOUT: {here.name} rebuilt because public hash of {forced_by} changed");
            visit [->:DependsOn:->];
        } else {
            print(f"skip {here.name}: no public-surface change among its dependencies");
        }
    }
}

