"""Path locks and dependency-aware scheduling over a task DAG.

Tasks are nodes connected by typed Requires edges. A Scheduler walker
walks the DAG, queueing children behind unresolved parents, enforcing
stack-depth limits and cycle detection, and acquiring shared/exclusive
PathLocks on high-contention resources: two tasks with incompatible
lock modes over the same path cannot both enter implementation.
"""

node PathLock {
    has path: str = "";
    has mode: str = "exclusive";       # "exclusive" | "shared"
    has owner: str = "";               # task name currently holding it exclusively
    has shared_owners: list[str] = list();

    def compatible_with(requested: str) -> bool {
        if requested == "shared" and self.mode == "shared" {
            return True;
        }
        if self.owner == "" and len(self.shared_owners) == 0 {
            return True;
        }
        return False;
    }

    def acquire(task: str, requested: str) -> bool {
        if not self.compatible_with(requested) {
            return False;
        }
