"""Graph-lite traversal: BFS/DFS over typed edges with filters, depth caps, cycle safety.

Traverser applies node/edge filters as each edge is considered, carries an
explicit visited set (jac walkers do not dedupe), and reports a `truncated`
flag so partial answers are recognisable.
"""

node Entity {
    has kind: str = "any";
}

node Symbol(Entity) {
    has name: str = "";
}

node Module(Entity) {
    has name: str = "";
    has path: str = "";
}

edge References { has weight: int = 1; }
edge Contains { }

walker Traverser {
    has dfs: bool = False;
    has max_depth: int = 3;
    has max_results: int = 5;
    has edge_type: str = "any";
    has target_kind: str = "any";
    has start: Entity | None = None;

    has visited: dict = {};
    has frontier: list = [];
    has results: list = [];
    has truncated: bool = False;

    def kind_of(n: Entity) -> str {
        return n.kind;
    }

    def matches(n: Entity) -> bool {
        if self.target_kind == "any" {
            return True;
        }
        return self.kind_of(n) == self.target_kind;
    }

    def edges_of(here_node: Entity) -> list {
        # filters applied as edges are considered, not after collecting results
        if self.edge_type == "References" {
            return [here_node ->:References:->];
        }
        if self.edge_type == "Contains" {
            return [here_node ->:Contains:->];
        }
        return [here_node -->];
    }

    def consider(nxt: Entity, depth: int) -> None {
        if nxt in self.visited {
            return;
        }
        self.visited[nxt] = True;
        self.frontier.append((nxt, depth));
    }

    def run() -> None {
        while len(self.frontier) > 0 {
            if self.dfs {
                (node_obj, depth) = self.frontier.pop();
            } else {
                (node_obj, depth) = self.frontier.pop(0);
            }
            if self.matches(node_obj) {
                self.results.append(node_obj);
                if len(self.results) >= self.max_results {
                    # partial if unexplored frontier or unexpanded neighbours remain
                    more = len(self.frontier) > 0 or len(self.edges_of(node_obj)) > 0;
                    self.truncated = True if more else False;
                    return;
                }
            }
            if depth < self.max_depth {
                for nxt in self.edges_of(node_obj) {
                    self.consider(nxt, depth + 1);
                }
            }
        }
        self.truncated = False;
    }

    can begin with Root entry {
        if self.start is None {
            report {
                "results": [],
                "truncated": True,
                "error": "no start node",
            };
            disengage;
        }
        start_node = self.start;
        self.visited[start_node] = True;
        self.frontier.append((start_node, 0));
        self.run();
        names = [r.name for r in self.results];
        report {
            "results": names,
            "truncated": self.truncated,
            "order": "dfs" if self.dfs else "bfs",
            "edge_filter": self.edge_type,
            "node_filter": self.target_kind,
            "max_depth": self.max_depth,
        };
        disengage;
    }
}

