"""Package composition: resolve a deterministic, verified dependency closure.

Typed ``Depends`` edges carry the declared dependency (with expected hash);
a Composer walker performs the closure traversal with an explicit visited
set (cycle policy), duplicate/conflict detection, and hash checks.
"""

node Package {
    has name: str = "";
    has version: str = "";
    has content_hash: str = "";

    def identity() -> str {
        return self.name + "@" + self.version;
    }
}

edge Depends {
    has expected_hash: str = "";
}

walker Composer {
    has root_name: str = "";
    has closure: list[str] = [];
    has seen: dict = {};
    has failed: bool = False;
    has errors: list[str] = [];

    def fail(msg: str) {
        self.failed = True;
        self.errors += [msg];
    }

    can start with Root entry {
        for p in [root -->] {
            if p.name == self.root_name {
                visit [p ->:Depends:->];
                return;
            }
        }
        self.fail("root package not found: " + self.root_name);
        disengage;
    }

    can resolve with Package entry {
        ident = here.identity();
        if ident in self.seen {
            return;
        }
        self.seen[ident] = True;
        self.closure += [ident];
        for e in [here ->] {
            for tgt in [e -->] {
                if tgt.content_hash != e.expected_hash {
                    self.fail("hash mismatch for " + tgt.identity()
                              + ": expected " + e.expected_hash
                              + " got " + tgt.content_hash);
                }
            }
        }
        visit [->:Depends:->];
    }
}

