"""Package composition: resolve a deterministic, verified dependency closure.

Typed ``Depends`` edges model declared dependencies; expected content hashes
live on the declaring package (``expects``) so the Composer walker can verify
them during the closure traversal. The walker keeps an explicit visited map
(cycle policy), detects duplicates and hash mismatches, and emits the closure
in deterministic traversal order.
"""

node Package {
    has name: str = "";
    has version: str = "";
    has content_hash: str = "";
    has expects: dict = {};

    def identity() -> str {
        return self.name + "@" + self.version;
    }
}

edge Depends { }

walker Composer {
    has root_name: str = "";
    has closure: list[str] = [];
    has seen: dict = {};
    has hash_of: dict = {};
    has failed: bool = False;
    has errors: list[str] = [];

    def fail(msg: str) {
        self.failed = True;
        self.errors += [msg];
    }

    can start with Root entry {
        # Register every known package so hash lookups resolve by identity.
        for p in [root -->] {
            self.hash_of[p.identity()] = p.content_hash;
        }
        for p in [root -->] {
            if p.name == self.root_name {
                visit [p ->:Depends:->];
                return;
            }
        }
        self.fail("root package not found: " + self.root_name);
        disengage;
    }

    can resolve with Package entry {
        ident = here.identity();
        if ident in self.seen {
            # Duplicate dependency: only a conflicting hash is an error.
            if self.seen[ident] != here.content_hash {
                self.fail("conflicting dependency " + ident + ": "
                          + self.seen[ident] + " vs " + here.content_hash);
            }
            return;
        }
        self.seen[ident] = here.content_hash;
        self.closure += [ident];

        # Verify each declared dependency's expected content hash.
        for dep_name in here.expects {
            expected = here.expects[dep_name];
            for tgt in [here ->:Depends:->] {
                if tgt.name == dep_name {
                    actual = self.hash_of[tgt.identity()];
                    if actual != expected {
                        self.fail("hash mismatch for " + tgt.identity()
                                  + ": expected " + expected
                                  + " got " + actual);
                    }
                }
            }
        }

        visit [->:Depends:->] else { disengage; }
    }
}

with entry {
    core = Package(name="core", version="1.0.0", content_hash="h-core");
    io = Package(name="io", version="1.2.0", content_hash="h-io");
    lang = Package(name="lang", version="0.9.0", content_hash="h-lang");
    app = Package(name="app", version="2.0.0", content_hash="h-app",
                  expects={"core": "h-core", "io": "h-io"});
    core.expects = {"lang": "h-lang"};
    io.expects = {"lang": "h-lang"};

    root ++> app ++> core ++> io ++> lang;

    app +>:Depends:+> core;
    app +>:Depends:+> io;
    core +>:Depends:+> lang;
    io +>:Depends:+> lang;

    composer = Composer(root_name="app");
    root spawn composer;

    if composer.failed {
        print("verification failed:");
        for e in composer.errors {
            print("  " + e);
        }
    } else {
        print("verified closure (deterministic order):");
        for ident in composer.closure {
            print("  " + ident);
        }
    }
}

"""Post-merge Done cascade: completion-blocker check that skips auto-expirable Engineer-message follow-ups.

Root TORQUE:1588 stays stuck when the naive check counts every open
descendant; the blocker query here excludes only engineer-message rows,
matching the fix design.
"""

node Task {
    has title: str = "";
    has status: str = "Open";
    has is_engineer_message: bool = False;
    has is_root: bool = False;

    def is_open() -> bool {
        return self.status != "Done";
    }

    def is_completion_blocker() -> bool {
        return self.is_open() and not self.is_engineer_message;
    }
