        self.visited[here] = True;
        if here.is_completion_blocker() {
            self.blockers += [here.title];
        }
        visit [->:Descendant:->] else { disengage; }
    }

    can report with Root exit {
        if self.blockers {
            print(f"root stays open: blocked by {self.blockers}");
        } else {
