"""Cross-pipeline result cache with change-based cascade invalidation."""

node CacheEntry {
    has key: str = "";
    has file_hash: str = "";
    has commit_sha: str = "";
    has valid: bool = True;

    def fingerprint() -> str {
        return self.file_hash + "@" + self.commit_sha;
    }
}

edge DependsOn { }

walker InvalidationSweep {
    has changed_key: str = "";
    has changed_hash: str = "";
    has invalidated: int = 0;
    has cascading: bool = False;
    has visited_keys: list[str] = [];

    def seen(k: str) -> bool {
        for k2 in self.visited_keys {
            if k2 == k {
                return True;
            }
        }
        return False;
    }

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can check with CacheEntry entry {
        # cycle guard: jac walkers do not dedupe visits on their own
        if self.seen(here.key) {
            disengage;
        }
        self.visited_keys.append(here.key);
        fp = here.fingerprint();
        changed = False;
        if here.key == self.changed_key {
            changed = self.changed_hash != here.file_hash;
        }
        stale = self.cascading and here.valid;
        if changed or stale {
            here.valid = False;
            self.invalidated += 1;
            self.cascading = True;
            print(f"INVALIDATED {here.key} (changed={changed}, stale={stale})");
            visit [->:DependsOn:->];
        } else {
            print(f"CACHE HIT {here.key} ({fp})");
        }
    }
}

with entry {
    intel = CacheEntry(key="intel@abc", file_hash="h1", commit_sha="abc");
    lint = CacheEntry(key="lint@abc", file_hash="h2", commit_sha="abc");
    types = CacheEntry(key="types@abc", file_hash="h2", commit_sha="abc");

    # lint depends on the raw files; type check depends on lint and intel
    root +>:DependsOn:+> intel;
    root +>:DependsOn:+> lint;
    lint +>:DependsOn:+> types;
    intel +>:DependsOn:+> types;

    # files backing the lint entry changed on disk: the sweep must
    # cascade-invalidate dependents
    sweep = InvalidationSweep(changed_key="lint@abc", changed_hash="h2-NEW");
    root spawn sweep;

    report = f"invalidated {sweep.invalidated} entries";
    print(report);
}

"""Incremental rebuild granularity: body-only edits rebuild one unit, public-surface edits fan out.

SourceUnit nodes carry separate public and body hashes plus a snapshot of the
public hash each dependency had at build time. The Rebuilder walker edits one
unit, then walks backwards along DependsOn edges invalidating only dependents
whose recorded public snapshot actually changed, and reports why a broad
rebuild was forced.
"""

node SourceUnit {
    has name: str = "";
    has public_hash: str = "";
    has body_hash: str = "";
    has stale: bool = False;
    # snapshot of each dependency's public hash when this unit was last built
    has built_public: dict = {};
}

edge DependsOn { }

walker Rebuilder {
    has edited: str = "";
    has new_public: str = "";
    has new_body: str = "";
    has rebuilt: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can apply_edit with SourceUnit entry {
        if here.name == self.edited and not here.stale {
            reason = "public-surface change (dependents invalidated)" if here.public_hash != self.new_public else "body-only change (owner object + link only)";
            here.public_hash = self.new_public;
            here.body_hash = self.new_body;
            here.stale = True;
            self.rebuilt += 1;
            print(f"edit applied to {here.name}: {reason}");
        }
    }

    # A dependent rebuilds only if one of its dependencies went stale AND
    # that dependency's public hash no longer matches the snapshot it
    # was compiled against. Body-only staleness never propagates.
    can check with SourceUnit entry {
        if here.name == self.edited {
            visit [<--:DependsOn:--];
        } else {
            forced_by = "";
            for dep in [here ->:DependsOn:->] {
                if dep.stale and here.built_public[dep.name] != dep.public_hash {
                    forced_by = dep.name;
                }
            }
            if forced_by != "" {
                here.stale = True;
                self.rebuilt += 1;
                print(f"FANOUT: {here.name} rebuilt because public hash of {forced_by} changed");
            } else {
                print(f"skip {here.name}: no public-surface change among its dependencies");
            }
        }
    }
}

with entry {
    core = SourceUnit(name="core", public_hash="p1", body_hash="b1");
    tables = SourceUnit(name="tables", public_hash="p1", body_hash="b1");
    parser = SourceUnit(name="parser", public_hash="p1", body_hash="b1");
    main = SourceUnit(name="main", public_hash="p1", body_hash="b1");

    parser +>:DependsOn:+> tables;
    parser +>:DependsOn:+> core;
    main +>:DependsOn:+> parser;
    main +>:DependsOn:+> core;

    # record the public snapshot each unit was built against
    parser.built_public = {"tables": "p1", "core": "p1"};
    main.built_public = {"parser": "p1", "core": "p1"};

    count_stale = 0;

    # Scenario 1: body-only edit in one .phs source unit — owner only, then link.
    print("--- body-only edit in tables ---");
    w = Rebuilder(edited="tables", new_public="p1", new_body="b2");
    tables spawn w;
    for unit in [tables, parser, main] {
        if unit.stale {
            count_stale += 1;
        }
    }
    print(f"objects rebuilt: {count_stale} (expect 1: owner object + link)");

    # reset
    tables.stale = False;
    parser.stale = False;
    main.stale = False;
    count_stale = 0;

    # Scenario 2: public-surface edit — dependents must fan out, reason explicit.
    print("--- public-surface edit in tables ---");
    w2 = Rebuilder(edited="tables", new_public="p2", new_body="b3");
    tables spawn w2;
    for unit in [tables, parser, main] {
        if unit.stale {
            count_stale += 1;
        }
    }
    print(f"objects rebuilt: {count_stale} (expect 2: fanout from public change)");
}

"""Forward change-impact analysis: transitive blast radius from a spec node.

Requirement (FR) nodes link to acceptance criteria (AC), which link to
scenarios, which link to tasks/files. A single-hop `find_refs` misses
downstream consumers; here an ImpactWalker does the multi-hop traversal
over typed edges with an explicit depth cap and a visited set for cycles
(verified: jac walkers do NOT dedupe visits on cyclic graphs).
"""

node SpecNode {
    has sid: str = "";
    has layer: str = "";       # FR | AC | Scenario | Task | File
    has status: str = "not_run";
}

edge refs { }
edge covers { }
edge tested_by { }

walker ImpactAnalyzer {
    has root_id: str = "";
    has max_depth: int = 5;
    has visited: dict = {};
    has by_layer: dict = {};
    has cycles: list = [];
    has affected_specs: list = [];

    can start with Root entry {
        visit [-->];
    }

    def record(n: SpecNode, depth: int) {
        if n.sid in self.visited {
            self.cycles.append(n.sid);
            return;
        }
        if depth > self.max_depth {
            return;
        }
        self.visited[n.sid] = depth;
        if n.layer not in self.by_layer {
            self.by_layer[n.layer] = [];
        }
        self.by_layer[n.layer].append({"id": n.sid, "depth": depth, "status": n.status});
        if n.layer == "FR" and n.sid != self.root_id and n.sid not in self.affected_specs {
            self.affected_specs.append(n.sid);
        }
    }

    can analyze with SpecNode entry {
        here.record(here, 0);
    }

    can expand with SpecNode entry {
        depth = self.visited[here.sid] + 1;
        if depth <= self.max_depth {
            visit [->:refs:->] | [->:covers:->] | [->:tested_by:->];
        }
    }
}

walker ImpactWalker {
    can start with Root entry {
        visit [-->];
    }

    can seed with SpecNode entry {
        # seed = the root whose blast radius we compute
        print(f"impact root: {here.sid} ({here.layer})");
        visitor = ImpactAnalyzer(root_id=here.sid);
        root spawn visitor;
    }
}

with entry {
    fr7 = SpecNode(sid="FR-7", layer="FR", status="passed");
    ac3 = SpecNode(sid="AC-3", layer="AC", status="stale");
    sc1 = SpecNode(sid="SC-1", layer="Scenario", status="pending");
    t2 = SpecNode(sid="TASK-2", layer="Task", status="not_run");
    f1 = SpecNode(sid="src/auth.py", layer="File", status="not_run");
    fr1 = SpecNode(sid="FR-1", layer="FR", status="passed");

    root ++> fr7;
    fr7 +>:covers:+> ac3;
    ac3 +>:covers:+> sc1;
    sc1 +>:tested_by:+> t2;
    t2 +>:refs:+> f1;
    fr1 +>:refs:+> ac3;   # cross-link; cycle guard handles any loop back
    sc1 +>:refs:+> ac3;   # deliberate cycle: AC-3 reachable again

    root spawn ImpactWalker();
    print(f"affected specs: {ImpactWalker().affected_specs}");
}

"""Deterministic multi-repo task queue: eligibility walk with cycle detection.

The issue complains that a planner agent infers dependencies from prose and
can select a blocked task. This demo makes dependencies machine-readable
(typed BlockedBy edges) and eligibility a deterministic graph walk that
refuses tasks in dependency cycles and marks transitively-blocked tasks.
"""

node Task {
    has title: str = "";
    has eligible: bool = True;
    has in_cycle: bool = False;
    has depth: int = 0;
}

node Repo {
    has name: str = "";
    has active: bool = True;
}

edge Contains { }
edge BlockedBy { }

walker Dispatcher {
    has guard: list[str] = [];
    has max_depth: int = 8;

    can start with Repo entry {
        # Begin at a repo only if it is authorized/active.
        if not here.active {
            print(f"repo {here.name} inactive: dispatch refused");
            disengage;
        }
        print(f"dispatching on repo {here.name}");
        visit [-->] else { disengage; }
    }

    can evaluate with Task entry {
        # Deterministic eligibility: DFS over dependencies with cycle guard.
        if here.title in self.guard {
            here.in_cycle = True;
            here.eligible = False;
            print(f"[CYCLE] {here.title} is in a dependency cycle: blocked");
            return;
        }
        if here.depth > self.max_depth {
            here.eligible = False;
            print(f"[LIMIT] {here.title} exceeds depth cap: blocked");
            return;
        }
        self.guard.append(here.title);
        blockers = [here ->:BlockedBy:->];
        if len(blockers) > 0 {
            here.eligible = False;
            print(f"[BLOCKED] {here.title} waits on {len(blockers)} unmet task(s)");
            for b in blockers {
                b.depth = here.depth + 1;
                visit [b];
            }
        } else {
            print(f"[READY] {here.title} is eligible to claim");
        }
        self.guard.remove(here.title);
    }
}

walker Auditor {
    can start with Root entry {
        visit [-->];
    }
    can sweep with Repo entry {
        visit [-->];
    }
    can report with Task entry {
        verdict = "READY" if here.eligible else ("CYCLE" if here.in_cycle else "BLOCKED");
        print(f"audit {here.title}: {verdict}");
    }
}

