"""Location-based encounter proximity queries: ancestor and descendant walks.

Lifts the hand-rolled hierarchy recursion from issue #313 into walkers over
typed edges. ``contains`` edges model parent->child locations; ``At`` edges
tie encounters to locations. ``maxDepth`` caps descendant recursion and a
visited set guards against accidental cycles (jac walkers do not dedupe).
"""

node Location {
    has name: str = "";
}

node Encounter {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Contains { }
edge At { }

walker AncestorScan {
    """Collect encounters at the start location and all its ancestors."""
    has found: list[str] = [];
    has seen: list[Location] = [];

    can start with Root entry {
        visit [->:At:->];
    }

    can gather with Encounter entry {
        status = "IN" if here.available else "OUT";
        self.found.append(f"[{status}] {here.title}");
        disengage;
    }

    can climb with Location entry {
        for loc in self.seen {
            if loc is here {
                print(f"cycle detected at {here.name}; stopping climb");
                disengage;
            }
        }
        self.seen.append(here);
        visit [->:At:->];
        visit [<-:Contains:--] else { disengage; }
    }
}

walker DescendantScan {
    """Collect encounters within maxDepth levels below the start location."""
    has max_depth: int = 5;
    has found: list[str] = [];
    has seen: list[Location] = [];

    can start with Root entry {
        visit [->:At:->];
    }

    can gather with Encounter entry {
        status = "IN" if here.available else "OUT";
        self.found.append(f"[{status}] {here.title}");
        disengage;
    }

    can descend with Location entry {
        for loc in self.seen {
            if loc is here {
                print(f"cycle detected at {here.name}; stopping descent");
                disengage;
            }
        }
        self.seen.append(here);
        if self.seen.size() > self.max_depth {
            print(f"maxDepth {self.max_depth} reached below {here.name}");
            disengage;
        }
        visit [->:At:->];
        visit [->:Contains:->] else { disengage; }
    }
}

