"""Recursive CTE fix demo: model a recursive relation as nodes and iterate it natively.

The Ray runner rejected recursive CTE scans outright; here the recursive
relation is a graph whose steps are walked with a cycle-safe explicit
iteration bound (the domain policy that must survive the lift).
"""

node Relation {
    has name: str = "";
}

node CteStep {
    has value: int = 0;
    has is_base: bool = False;
}

edge Produces { }
edge RecursesTo { }

walker RecursiveCteRunner {
    has limit: int = 4;          # recursive predicate: value < limit
    has max_iterations: int = 16; # explicit cycle/depth policy
    has rows: list[int] = [];
    has iterations: int = 0;

    can start with Root entry {
