    fr7 = SpecNode(sid="FR-7", layer="FR", status="passed");
    ac3 = SpecNode(sid="AC-3", layer="AC", status="stale");
    sc1 = SpecNode(sid="SC-1", layer="Scenario", status="pending");
    t2 = SpecNode(sid="TASK-2", layer="Task", status="not_run");
