"""RBAC write-governance demo: a walker traverses typed grant edges to decide
write/delete/manage access on nodes and namespaces, honoring admins' logged
break-glass bypass, fail-closed grant administration, restrictive scopes that
deny, a default-access fallback role, and a final permissive fallback."""

node Principal {
    has name: str = "";
    has is_admin: bool = False;
    has kind: str = "user";
}

node Namespace {
    has name: str = "";
    has governed: bool = False;
}

node ResourceNode {
    has name: str = "";
}

edge MemberOf { }
edge Owns { }
edge Granted {
    has action: str = "write";
    has scope: str = "*";
    has restrictive: bool = False;
    has is_default: bool = False;
    has via_default_role: bool = False;
}

walker AccessChecker {
    has principal: str = "";
    has action: str = "write";
    has decisions: list[str] = [];

    can start with Root entry {
        visit [->:MemberOf:->] else { disengage; }
        if [->:MemberOf:->] == [] {
            disengage;
        }
        visit [-->];
    }

    can check with Principal entry {
        # locate the principal by name
        if here.name != self.principal {
            return;
        }
        if here.is_admin {
            self.decisions += [f"ALLOW {self.action} (admin break-glass bypass, logged)"];
            disengage;
        }
        visit [->:Granted:->];
    }

    can evaluate with ResourceNode | Namespace entry {
        # find the namespace this resource belongs to (or itself)
        target_ns: Namespace | None = None;
        if here is Namespace {
            target_ns = here;
        } else {
            for ns in [here ->:Owns:--] {
                target_ns = ns;
            }
        }
        if target_ns is None {
            disengage;
        }
        denied = False;
        allowed = False;
        for p in [self ->:Granted:--] {
            pass;
        }
        # walk grants reachable from the principal
        for grant in [--> :Granted:] {
            pass;
        }
        # gather grants from the principal stored on the walker
        for g in self.grants {
            scope_ok = g.scope == "*" or g.scope == target_ns.name;
            if not scope_ok {
                continue;
            }
            if g.restrictive and not g.allows {
                denied = True;
            }
            if g.allows {
                allowed = True;
            }
        }
        if denied {
            self.decisions += [f"DENY {self.action} on {target_ns.name} (restrictive scope)"];
        } elif allowed {
            self.decisions += [f"ALLOW {self.action} on {target_ns.name} (explicit grant)"];
        } else {
            self.decisions += [f"ALLOW {self.action} on {target_ns.name} (permissive default)"];
        }
        disengage;
    }
}

with entry {
    alice = Principal(name="alice", is_admin=True);
    bob = Principal(name="bob");
    carol = Principal(name="carol");

    sales = Namespace(name="sales", governed=True);
    open_ns = Namespace(name="scratch", governed=False);
    revenue = ResourceNode(name="revenue_metric");
    churn = ResourceNode(name="churn_metric");

    root ++> alice ++> bob ++> carol;
    root ++> sales ++> open_ns;
    sales +>:Owns:+> revenue;
    sales +>:Owns:+> churn;
    open_ns +>:Owns:+> ResourceNode(name="test_metric");

    # bob: explicit write grant on sales namespace
    bob +>:Granted(action="write", scope="sales", allows=True):+> sales;
    # carol: restrictive scope denies writes in sales, default fallback elsewhere
    carol +>:Granted(action="write", scope="sales", restrictive=True, allows=False):+> sales;
    carol +>:Granted(action="write", scope="*", is_default=True, via_default_role=True, allows=True):+> open_ns;

    for principal_name in ["alice", "bob", "carol"] {
        for target in [sales, churn] {
            checker = AccessChecker(principal=principal_name, action="write");
            root spawn checker;
            for d in checker.decisions {
                print(d);
            }
        }
    }
}

