"""Recursive CTE fix demo: model a recursive relation as nodes and iterate it natively.

The Ray runner rejected recursive CTE scans outright; here the recursive
relation is a graph whose steps are walked with a cycle-safe explicit
iteration bound (the domain policy that must survive the lift).
"""

edge Produces {
    has since: str = "";
}

edge RecursesTo {
    has depth: int = 0;
}

node Relation {
    has name: str = "";
}

node CteStep {
    has value: int = 0;
    has is_base: bool = False;
}

walker RecursiveCteRunner {
    has limit: int = 4;
    has max_iterations: int = 16;
    has rows: list[int] = [];
    has iterations: int = 0;

    can start with Root entry {
        visit [->:Produces:->];
    }

    can take_base with Relation entry {
        visit [->:Produces:->];
    }

    can take_step with CteStep entry {
        self.rows.append(here.value);
        if self.iterations >= self.max_iterations {
            print("cycle guard: max recursive iterations reached");
            disengage;
        }
        if here.is_base {
            self.iterations += 1;
            visit [->:RecursesTo:->] else { disengage; }
        } else {
            nxt = here.value + 1;
            if nxt < self.limit {
                spawn_of = CteStep(value=nxt, is_base=False);
                here +>:RecursesTo:+> spawn_of;
                visit [->:RecursesTo:->] else { disengage; }
            }
        }
    }
}

with entry {
    rel = Relation(name="numbers");
    root +>:Produces:+> rel;
    rel +>:Produces:+> CteStep(value=1, is_base=True);

    runner = RecursiveCteRunner(limit=4);
    root spawn runner;

    print(f"recursive CTE '{rel.name}' rows: {runner.rows} "
          f"in {runner.iterations} recursive iterations");
}

"""Forward change-impact analysis: transitive blast radius from a spec node.

Requirement (FR) nodes link to acceptance criteria (AC), which link to
scenarios, which link to tasks/files. A single-hop `find_refs` misses
downstream consumers; here an ImpactAnalyzer walker performs the multi-hop
traversal over typed edges with an explicit depth cap and a visited set
for cycles (jac walkers do NOT dedupe visits on cyclic graphs).
"""

node SpecNode {
    has sid: str = "";
    has layer: str = "";       # FR | AC | Scenario | Task | File
    has status: str = "not_run";
}

edge refs { }
edge covers { }
edge tested_by { }

walker ImpactAnalyzer {
    has root_id: str = "";
    has max_depth: int = 5;
    has visited: dict = {};
    has by_layer: dict = {};
    has cycles: list = [];
    has affected_specs: list = [];
    has entries: list = [];

    can start with Root entry {
        visit [-->];
    }

    can analyze with SpecNode entry {
        # Only begin at the requested root.
        if here.sid == self.root_id and self.visited == {} {
            self.visit_node(here, 0);
        }
    }

    def visit_node(n: SpecNode, depth: int) {
        if n.sid in self.visited {
            self.cycles.append(n.sid);
            return;
        }
        if depth > self.max_depth {
            return;
        }
        self.visited[n.sid] = depth;
        if n.layer not in self.by_layer {
            self.by_layer[n.layer] = [];
        }
        self.by_layer[n.layer].append({"id": n.sid, "depth": depth, "status": n.status});
        self.entries.append({"id": n.sid, "layer": n.layer, "depth": depth, "status": n.status});
        if n.layer == "FR" and n.sid != self.root_id and n.sid not in self.affected_specs {
            self.affected_specs.append(n.sid);
        }
        if depth < self.max_depth {
            for t in [->:refs:->] {
                self.visit_node(t, depth + 1);
            }
            for t in [->:covers:->] {
                self.visit_node(t, depth + 1);
            }
            for t in [->:tested_by:->] {
                self.visit_node(t, depth + 1);
            }
        }
    }
}

