walker Resolver {
    has order: list[int] = [];
    has visiting: list[int] = [];
    has done: list[int] = [];

    can start with Root entry {
        visit [->:Blocks:->];
    }

    can sort with Srfi entry {
        # Cycle guard: explicit, since visit does not dedupe in jac 0.36.1.
        if here.number in self.visiting {
            print(f"cycle detected at SRFI {here.number}");
            disengage;
