            disengage;
        }
        self.visiting.append(here.number);
        visit [->:DependsOn:->];
        self.visiting.pop();
        self.done.append(here.number);
        self.order.append(here.number);
        print(f"resolved SRFI {here.number} ({here.name}) "
              f"status={here.status} vendored={here.vendored}");
    }
}

