"""Epic execution-order planner: epics as nodes, dependencies as typed edges.

The issue hand-rolls a dependency chain across phases; here each epic is a
node, each dependency a typed ``Blocks`` edge, and a walker performs the
topological-style traversal by repeatedly visiting epics whose dependencies
are all already scheduled.
"""

node Epic {
    has title: str = "";
    has number: int = 0;
    has phase: int = 0;
    has scheduled: bool = False;
}

edge Blocks {
    # a --Blocks--> b means a must be done before b
}

walker Scheduler {
    has order: list[str] = [];
    has depth_limit: int = 20;

    can start with Root entry {
        visit [-->];
    }

    can plan with Epic entry {
        if here.scheduled {
            disengage;
        }
        # Domain logic kept explicit: an epic is schedulable only once every
        # blocking dependency is scheduled. Otherwise defer via revisit.
        ready = True;
        for dep in [here<--:Blocks:--] {
            if not dep.scheduled {
                ready = False;
            }
        }
        if ready {
            here.scheduled = True;
            self.order.append(f"{here.title} (#{here.number}, phase {here.phase})");
            visit [->:Blocks:->];
        } else {
            # Depth guard prevents infinite revisit on cyclic specs.
            if self.depth_limit <= 0 {
                print(f"cycle suspected around {here.title}; halting");
                disengage;
            }
            self.depth_limit -= 1;
            visit [-->];
        }
    }
}

