"""Outage SLA status derivation: instead of a dead denormalized sla_status
column, the exporter walker joins each Outage to its latest SLAResult over
a typed ComputedFor edge and reports status live."""

node Outage {
    has title: str = "";
    has resolved: bool = False;
}

node SLAResult {
    has status: str = "";
    has is_latest: bool = False;
}

