    has computed_at: str = "";
}

walker Exporter {
    has report: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    # Join outage -> sla_results, take the authoritative latest result.
    can export with Outage entry {
        latest = None;
        for r in [here ->:ComputedFor:->] {
            if r.is_latest {
                latest = r;
            }
        }
        sla_status = latest.status if latest is not None else None;
        sla_label = sla_status if sla_status is not None else "no SLA status";
        self.report.append(f"{here.title}: {sla_label}");
        visit [-->] else { disengage; }
    }

    can finish with SLAResult entry {
        # leaf results end the walk silently; keep traversal alive elsewhere
        visit [-->] else { disengage; }
    }
}

