"""RBAC write-governance demo: walkers traverse typed grant edges to decide
write access on governed namespaces, honoring the admin break-glass bypass,
fail-closed restrictive scopes, a default-access fallback role, and a final
permissive fallback."""

node Principal {
    has name: str = "";
    has is_admin: bool = False;
    has kind: str = "user";
}

node Namespace {
    has name: str = "";
    has governed: bool = False;
}

node ResourceNode {
    has name: str = "";
}

edge MemberOf { }

edge Granted {
    has action: str = "write";
    has scope: str = "*";
    has restrictive: bool = False;
    via_default_role: bool = False;
}

walker AccessChecker {
    has principal_name: str = "";
    has action: str = "write";
    has target_ns: str = "";
    has governed: bool = True;
    has decisions: list[str] = [];

    def scope_matches(scope: str) -> bool {
        return scope == "*" or scope == self.target_ns;
    }

    def decide(here_ns: Namespace) -> str {
        # Admin break-glass bypass (logged).
        if self.governed {
            prefix = f"{self.principal_name} {self.action} {self.target_ns}: ";
        } else {
            prefix = f"{self.principal_name} {self.action} {self.target_ns}: ";
        }
        for p in [->:MemberOf:->] {
            prefix += f"(member via group {p.name}) ";
        }
        if here_ns.governed is False {
            return prefix + "ALLOW (permissive default, ungoverned namespace)";
        }
        return prefix;
    }

    can start with Root entry {
        visit [-->];
    }

    can check with Principal entry {
        if here.name != self.principal_name {
            visit [-->];
            return;
        }
        if here.is_admin {
            self.decisions += [f"{self.principal_name} {self.action} {self.target_ns}: "
                               f"ALLOW (admin break-glass bypass, logged)"];
            return;
        }
        explicit_allow = False;
        restrictive_deny = False;
        default_allow = False;
        for ns in [->:Granted:->] {
            for g in [here ->:Granted:-> ns] {
                if g.action != self.action {
                    continue;
                }
                if not self.scope_matches(g.scope) and not self.scope_matches(ns.name) {
                    continue;
                }
                if g.restrictive {
                    restrictive_deny = True;
                } elif g.via_default_role {
                    if self.scope_matches(g.scope) {
                        default_allow = True;
                    }
                } else {
                    explicit_allow = True;
                }
            }
        }
        verdict = "";
        if explicit_allow {
            verdict = "ALLOW (explicit grant)";
        } elif restrictive_deny {
            verdict = "DENY (restrictive scope)";
        } elif default_allow {
            verdict = "ALLOW (default-access role fallback)";
        } elif not self.governed {
            verdict = "ALLOW (permissive default)";
        } else {
            verdict = "DENY (no grant, governed namespace)";
        }
        self.decisions += [f"{self.principal_name} {self.action} {self.target_ns}: {verdict}"];
    }

    can skip with Namespace | ResourceNode entry {
        visit [-->] else { return; }
    }
}

with entry {
    alice = Principal(name="alice", is_admin=True);
    bob = Principal(name="bob");
    carol = Principal(name="carol");
    writers = Principal(name="dj-writers", kind="group");

    sales = Namespace(name="sales", governed=True);
    scratch = Namespace(name="scratch", governed=False);
    revenue = ResourceNode(name="revenue_metric");

    root ++> alice ++> bob ++> carol;
    root ++> sales ++> scratch ++> revenue;

    # bob is in the writers group and holds an explicit write grant on sales.
    bob +>:MemberOf:+> writers;
    bob +>:Granted(action="write", scope="sales"):+> sales;

    # carol has only a restrictive write scope over sales: it denies.
    carol +>:Granted(action="write", scope="sales", restrictive=True):+> sales;

    # writers group holds the default-access role: fallback via wildcard grant.
    writers +>:Granted(action="write", scope="*", via_default_role=True):+> sales;
    writers +>:Granted(action="write", scope="*", via_default_role=True):+> scratch;

    for who in ["alice", "bob", "carol"] {
        checker = AccessChecker(principal_name=who, action="write", target_ns="sales");
        root spawn checker;
        for d in checker.decisions {
            print(d);
        }
    }

    checker = AccessChecker(principal_name="carol", action="write", target_ns="scratch", governed=False);
    root spawn checker;
    for d in checker.decisions {
        print(d);
    }
}

