"""Reify construct-level addDependency into resource-level depends_on.

A walker performs the CDK-style reification pass: every construct-level
dependency edge is expanded into concrete depends_on edges between all
leaf resources under the source and all leaf resources under the target
(the N x M cross-product AWS CDK ships).
"""

edge Child { }
edge DependsOn { }
edge ReifiedDep { }

node Construct {
    has name: str = "";
    has is_resource: bool = False;

    def dependency_roots() -> list[Construct] {
        roots: list[Construct] = [];
        if self.is_resource {
            roots.append(self);
        }
        for c in [self->:Child:->] {
            roots.extend(c.dependency_roots());
        }
        return roots;
    }
}

walker Reifier {
    has reified: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can scan with Construct entry {
        # DFS preorder over the construct tree (cycle-safe via tree shape).
        for target in [here->:DependsOn:->] {
            for src in here.dependency_roots() {
                for dst in target.dependency_roots() {
                    already = False;
                    for chk in [src->:ReifiedDep:->] {
                        if chk is dst {
                            already = True;
                        }
                    }
                    if not already {
                        src +>:ReifiedDep:+> dst;
                        self.reified += 1;
                    }
                }
            }
        }
        visit [->:Child:->];
    }

    can finish with Construct exit {
        if here.is_resource {
            outs = [d.name for d in [here->:ReifiedDep:->]];
            print(f"resource {here.name} depends_on {outs}");
        }
    }
}

with entry {
    # source construct A with two leaf resources
    a1 = Construct(name="A.bucket", is_resource=True);
    a2 = Construct(name="A.policy", is_resource=True);
    a = Construct(name="A");
    a +>:Child:+> a1;
    a +>:Child:+> a2;

    # target construct B with one leaf resource
    b1 = Construct(name="B.vpc", is_resource=True);
