"""RBAC write-governance demo: a walker traverses typed grant edges to decide
write access on governed namespaces, honoring the admin break-glass bypass,
fail-closed restrictive scopes, a default-access fallback role, and a final
permissive fallback."""

node Principal {
    has name: str = "";
    has is_admin: bool = False;
    has kind: str = "user";
}

node Namespace {
    has name: str = "";
    has governed: bool = True;
}

edge MemberOf { }

edge Granted {
    has action: str = "write";
    has scope: str = "*";
    has namespace_name: str = "";
    has restrictive: bool = False;
    has via_default_role: bool = False;
}

walker AccessChecker {
    has principal_name: str = "";
    has action: str = "write";
    has target_ns: str = "";
    has governed: bool = True;
    has decisions: list[str] = [];

    def scope_matches(scope: str) -> bool {
        return scope == "*" or scope == self.target_ns;
    }

    can start with Root entry {
        visit [-->];
    }

    can check with Principal entry {
        if here.name != self.principal_name {
            visit [-->] else { disengage; }
            return;
        }
        if here.is_admin {
            self.decisions += [f"{self.principal_name} {self.action} {self.target_ns}: "
                               f"ALLOW (admin break-glass bypass, logged)"];
            return;
        }
        explicit_allow = False;
        restrictive_deny = False;
        default_allow = False;
        for g in [here ->:Granted:->] {
            if g.action != self.action {
                continue;
            }
            if not self.scope_matches(g.scope) and not self.scope_matches(g.namespace_name) {
                continue;
            }
            if g.restrictive {
                restrictive_deny = True;
            } elif g.via_default_role {
                default_allow = True;
            } else {
                explicit_allow = True;
            }
        }
        verdict = "";
        if explicit_allow {
            verdict = "ALLOW (explicit grant)";
        } elif restrictive_deny {
            verdict = "DENY (restrictive scope)";
        } elif default_allow {
            verdict = "ALLOW (default-access role fallback)";
        } elif not self.governed {
            verdict = "ALLOW (permissive default)";
        } else {
            verdict = "DENY (no grant, governed namespace)";
        }
        self.decisions += [f"{self.principal_name} {self.action} {self.target_ns}: {verdict}"];
    }

    can skip with Namespace entry {
        visit [-->] else { disengage; }
    }
}

with entry {
    alice = Principal(name="alice", is_admin=True);
    bob = Principal(name="bob");
    carol = Principal(name="carol");
    writers = Principal(name="dj-writers", kind="group");

    sales = Namespace(name="sales", governed=True);
    scratch = Namespace(name="scratch", governed=False);

    root ++> alice ++> bob ++> carol;
    root ++> writers;
    root ++> sales ++> scratch;

    # bob holds an explicit write grant on the sales namespace.
    bob +>:Granted(action="write", scope="sales", namespace_name="sales"):+> sales;

    # carol holds only a restrictive write scope over sales: it denies.
    carol +>:Granted(action="write", scope="sales", namespace_name="sales", restrictive=True):+> sales;

    # writers group holds the default-access role: wildcard fallback grants.
    writers +>:Granted(action="write", scope="*", namespace_name="sales", via_default_role=True):+> sales;
    writers +>:Granted(action="write", scope="*", namespace_name="scratch", via_default_role=True):+> scratch;

    for who in ["alice", "bob", "carol"] {
        checker = AccessChecker(principal_name=who, action="write", target_ns="sales");
        root spawn checker;
        for d in checker.decisions {
            print(d);
        }
    }

    checker = AccessChecker(principal_name="carol", action="write", target_ns="scratch", governed=False);
    root spawn checker;
    for d in checker.decisions {
        print(d);
    }
}

"""Reify construct-level addDependency into resource-level depends_on.

A walker performs the CDK-style reification pass: every construct-level
dependency edge is expanded into concrete depends_on edges between all
leaf resources under the source and all leaf resources under the target
(the N x M cross-product AWS CDK ships).
"""

edge Child { }
edge DependsOn { }
edge ReifiedDep { }

node Construct {
    has name: str = "";
    has is_resource: bool = False;

    def dependency_roots() -> list[Construct] {
        roots: list[Construct] = [];
        if self.is_resource {
            roots.append(self);
        }
        for c in [self -->] {
            roots.extend(c.dependency_roots());
        }
        return roots;
    }

    def depends_on_names() -> list[str] {
        names: list[str] = [];
        for d in [here ->:ReifiedDep:->] {
            names.append(d.name);
        }
        return names;
    }
}

walker Reifier {
    has reified: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can scan with Construct entry {
        # DFS preorder over the construct tree (cycle-safe via tree shape).
        for target in [here ->:DependsOn:->] {
            for src in here.dependency_roots() {
                for dst in target.dependency_roots() {
                    already = False;
                    for chk in [src ->:ReifiedDep:->] {
                        if chk is dst {
                            already = True;
                        }
                    }
                    if not already {
                        src +>:ReifiedDep:+> dst;
                        self.reified += 1;
                    }
                }
            }
        }
        visit [->:Child:->];
    }

    can finish with Construct exit {
        if here.is_resource {
            print(f"resource {here.name} depends_on {here.depends_on_names()}");
        }
    }
}

