    # source construct A with two leaf resources
    a1 = Construct(name="A.bucket", is_resource=True);
    a2 = Construct(name="A.policy", is_resource=True);
    a = Construct(name="A");
    a +>:Child:+> a1;
    a +>:Child:+> a2;

    # target construct B with one leaf resource
    b1 = Construct(name="B.vpc", is_resource=True);
    b = Construct(name="B");
    b +>:Child:+> b1;

    # unrelated leaf with no construct-level dependency: untouched
    c1 = Construct(name="C.table", is_resource=True);
    c = Construct(name="C");
    c +>:Child:+> c1;

    # the silent construct-level dependency: A depends on B
    a +>:DependsOn:+> b;

    root ++> a ++> c;
    r = root spawn Reifier();
    print(f"reified {r.reified} resource-level depends_on edges");
}

"""Minimal immutable prefix checkpoint tree: deepest-match restore and leaf-only GC."""

node Checkpoint {
    has prefix: list[str] = [];
    has frontier_bytes: int = 0;
    has live: bool = True;

    def depth() -> int {
        return len(self.prefix);
    }

    def is_leaf() -> bool {
        return not (-->(?:Checkpoint) or []): ;
    }
}

edge ParentOf { }

walker DeepestMatch {
    has prompt: list[str] = [];
    has best: Checkpoint | None = None;

    can start with Root entry {
        visit [->:ParentOf:->];
    }

    can search with Checkpoint entry {
        # Cycle policy: an immutable tree has one parent per node, so guard
        # depth explicitly against a pathological deeper-than-prompt chain.
        if here.depth() > len(self.prompt) {
            disengage;
        }
        if here.live and self.prompt[:here.depth()] == here.prefix {
            if self.best is None or here.depth() > self.best.depth() {
                self.best = here;
            }
            visit [->:ParentOf:->];
        }
        # Dead end (no compatible children): walker simply stops here.
    }

    can report_best with Root exit {
        found = "none (cold prefill)" if self.best is None else ", ".join(self.best.prefix);
        print(f"deepest reusable prefix for [{', '.join(self.prompt)}]: {found}");
    }
}

walker LeafGC {
    has budget: int = 0;
    has reclaimed: int = 0;

    can start with Root entry {
        visit [->:ParentOf:->];
    }

    can sweep with Checkpoint entry {
        kids = -->(?:Checkpoint);
        if here.is_leaf() and not here.live and self.reclaimed < self.budget {
            self.reclaimed += here.frontier_bytes;
            print(f"GC: durable-deleted leaf [{' '.join(here.prefix)}] freeing {here.frontier_bytes} bytes");
            del here;
            return;
        }
        visit [->:ParentOf:->];
    }

    can done with Root exit {
        print(f"leaf-only GC reclaimed {self.reclaimed} of {self.budget} byte budget");
    }
}

with entry {
    root_cb = Checkpoint(prefix=[], frontier_bytes=0);
    root ++>:ParentOf:+> root_cb;
    sys_cb = Checkpoint(prefix=["SYSTEM"], frontier_bytes=1_000);
    ab_cb = Checkpoint(prefix=["SYSTEM", "A", "B"], frontier_bytes=2_000);
    abc_cb = Checkpoint(prefix=["SYSTEM", "A", "B", "C"], frontier_bytes=3_000);
    abd_cb = Checkpoint(prefix=["SYSTEM", "A", "B", "D"], frontier_bytes=4_000, live=False);
    root_cb +>:ParentOf:+> sys_cb;
    sys_cb +>:ParentOf:+> ab_cb;
    ab_cb +>:ParentOf:+> abc_cb;
    ab_cb +>:ParentOf:+> abd_cb;

    root spawn DeepestMatch(prompt=["SYSTEM", "A", "B", "C", "X"]);
    root spawn LeafGC(budget=10_000);
}

