"""Outage SLA status derivation: instead of a dead denormalized sla_status
column, the exporter walker joins each Outage to its latest SLAResult over
a typed ComputedFor edge and reports status live."""

node Outage {
    has title: str = "";
    has resolved: bool = False;
}

node SLAResult {
    has status: str = "";
    has is_latest: bool = False;
}

edge ComputedFor {
    has computed_at: str = "";
}

walker Exporter {
    has report: list[str] = [];
    has current: str = "";

    can start with Root entry {
        visit [-->];
    }

    # Denormalized copy is gone: derive status live from the join.
    can export with Outage entry {
        self.current = here.title;
        visit [->:ComputedFor:->];
    }

    can note with SLAResult entry {
        status_label = here.status if here.is_latest else None;
        if here.is_latest {
            self.report.append(f"{self.current}: {status_label}");
        } else {
            print(f"skipping stale result for {self.current}: {here.status}");
        }
        visit [-->];
    }

    can done with Root exit {
        for line in self.report {
            print(f"export: {line}");
        }
    }
}

walker Resolver {
    # Resolve/recompute path: the fix lands because SLA results are the
    # single source of truth wired into outages via ComputedFor edges.
    can start with Root entry {
        visit [-->];
    }

    can resolve with Outage entry {
        here.resolved = True;
        print(f"resolved {here.title}");
        visit [-->];
    }

    can compute with SLAResult entry {
        tag = "latest" if here.is_latest else "stale";
        print(f"computed SLA ({tag}): {here.status}");
        visit [-->];
    }
}

