node Tracker {
    has name: str = "";
}

node WorkItem {
    has title: str = "";
    has category: str = "";      # bug | testing | ci | feature | governance
    has done: bool = False;
}

edge DependsOn {
    has reason: str = "";
}

edge Groups {
    has section: str = "";
}

walker ReleaseAuditor {
    has visited: dict = {};
    has ready: list = [];
    has blocked: list = [];

    can start with Root entry {
        visit [->:Groups:->];
    }

    can audit with Tracker entry {
        visit [->:Groups:->];
    }

    can inspect with WorkItem entry {
        # Cycle policy: explicit guard set, since visit does not dedupe.
        if here in self.visited {
            disengage;
        }
        self.visited[here] = True;
        status = "READY" if here.done else "BLOCKED";
        if here.done {
            self.ready.append(here.title);
        } else {
            self.blocked.append(here.title);
        }
        print(f"[{status}] ({here.category}) {here.title}");
        visit [->:DependsOn:->] else {
            report {
                "ready": self.ready,
                "blocked": self.blocked
            };
            disengage;
        }
    }
}

