"""Topological sort with an explicit cycle guard.

Kahn's algorithm lifted to a typed-edge graph: an ``Unlocks`` edge from a
task to each task that depends on it. After the queue drains we compare
the ordered count against the discovered node count; if any node kept a
non-zero in-degree the order is incomplete and a cycle is surfaced
instead of silently truncating the result (issue #81).
"""

node Task {
    has name: str = "";
    has hours: int = 0;
}

edge Unlocks { }

walker TopoSorter {
    has order: list[str] = [];
    has solved: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can solve with Task entry {
        if self.solved {
            visit [-->];
            disengage;
        }
        self.solved = True;

        # Discover the reachable subgraph once (explicit BFS, cycle-safe).
        nodes: list = [];
        indeg: dict = {};
        stack: list = [here];
        seen: set = set();
        while stack {
            n = stack.pop();
            if n in seen { continue; }
            seen.add(n);
            nodes.append(n);
            indeg[n] = 0;
            succs = [n -->];
            for s in succs {
                indeg[s] = indeg.get(s, 0) + 1;
                stack.append(s);
            }
        }

        # Kahn's algorithm.
        ready: list = [n for n in nodes if indeg[n] == 0];
        while ready {
            n = ready.pop(0);
            self.order.append(n.name);
            for s in [n -->] {
                indeg[s] -= 1;
                if indeg[s] == 0 {
                    ready.append(s);
                }
            }
        }

        # Cycle guard: every node must have been marked visited.
        if len(self.order) < len(nodes) {
            stuck = [n.name for n in nodes if n.name not in self.order];
            print(f"CYCLE DETECTED: {len(nodes) - len(self.order)} node(s) "
                  f"never became ready: {stuck}");
            print("topological order is INCOMPLETE");
        } else {
            print("topological order is complete (DAG confirmed)");
        }
        print(f"order = {self.order}");

        visit [-->];
    }

    can pass_through with Task entry {
        visit [-->] else { disengage; }
    }
}

with entry {
    a = Task(name="setup-env", hours=1);
    b = Task(name="install-deps", hours=2);
    c = Task(name="fetch-data", hours=3);
    d = Task(name="build", hours=4);
    e = Task(name="lint", hours=1);
    f = Task(name="format", hours=1);

    # DAG core: a unlocks b and c; b and c unlock d.
    a +>:Unlocks:+> b;
    a +>:Unlocks:+> c;
    b +>:Unlocks:+> d;
    c +>:Unlocks:+> d;

    # A reachable 2-cycle to exercise the guard (not reachable from a).
    e +>:Unlocks:+> f;
    f +>:Unlocks:+> e;

    root ++> a ++> b ++> c ++> d ++> e ++> f;
    root spawn TopoSorter();
}

