"""Editor-intelligence external dependency contract: claims declare exact
external substrate dependencies as typed edges; a walker validates each
dependency's subject/stage relation and composes the claim ceiling."""

node ClaimRow {
    has claim_id: str = "";
    has version: str = "";
    has subject: str = "";
    has checked: bool = False;
    has ceiling: str = "full";

    def can_declare_dependency() -> bool {
        return self.checked;
    }
}

edge DeclaresDependency {
    has dep_id: str = "";
    has dep_version: str = "";
    has disposition: str = "";      # required | conditional | optional | unsupported
    has selector: str = "";         # exact subject selector; empty for conditional is a violation
    has stage_relation: str = "";   # source | package | process | client | platform | root | series
}

node ExternalRow {
    has row_id: str = "";
    has schema: str = "";
    has state: str = "";            # pass | stale | absent | conflicting | invalid
    has landed: bool = True;
}

edge BelongsTo {
    has family: str = "";
}

walker DependencyAuditor {
    has blocked: list[str] = [];
    has eligible: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with ClaimRow entry {
        if not here.can_declare_dependency() {
            print(f"SKIP {here.claim_id}: unchecked claims cannot declare dependencies");
            visit [-->] else { disengage; }
            return;
        }
        deps = [e for e in here -->:DeclaresDependency:-->];
        if len(deps) == 0 {
            print(f"{here.claim_id}: no external dependency, governed by focused evidence");
        }
        ok = True;
        for e in deps {
            row = [e -->][0];
            if e.disposition == "conditional" and e.selector == "" {
                print(f"{here.claim_id}: conditional dep {e.dep_id} missing selector inputs -> blocked, not silently unselected");
                ok = False;
            } else if not row.landed {
                print(f"{here.claim_id}: dep {e.dep_id} on unlanded schema {row.schema} -> unresolved dependency");
                ok = False;
            } else if row.state != "pass" {
                label = "stale source" if row.state == "stale" else f"{row.state} external row";
                print(f"{here.claim_id}: dep {e.dep_id} is {label} -> cannot become current through dependency relation");
                ok = False;
            } else {
                print(f"{here.claim_id}: dep {e.dep_id} (stage={e.stage_relation}, selector={e.selector}) satisfied by {row.row_id}");
            }
        }
        if ok {
            self.eligible.append(here.claim_id);
            here.ceiling = "external-backed";
        } else {
            self.blocked.append(here.claim_id);
            here.ceiling = "blocked";
        }
        visit [-->] else { disengage; }
    }
}

walker SourceShipper {
    can start with Root entry {
        visit [-->];
    }
    can flow with ExternalRow entry {
        print(f"external row {here.row_id} schema={here.schema} state={here.state}");
        visit [-->] else { disengage; }
    }
}

with entry {
