}

"""Coherent current-generation adapter: editor-intelligence and product-health
consumers bind only to the exact join/rail members of one #12438 generation,
with machine compiler-profile status as the dependency source of truth."""

node Generation {
    has gen_id: str = "";
    has is_current: bool = True;
}

node CompilerProfileStatus {
    has profile: str = "";
    has state: str = "";  # pass | failed | stale | not_proven
}

node JoinMember {
    has consumer: str = "";
    has row_subject: str = "";
}

node RailMember {
    has profile: str = "";
    has area: str = "";  # compiler | parser | editor_client | ...
}

edge HasMember {
    has role: str = "";  # status | join | rail
}

edge DependsOn { }

walker GenerationAdapter {
    has validated: bool = False;
    has seen_status: bool = False;
    has status_profile: str = "";
    has status_state: str = "";
    has has_status: bool = False;
    has has_join: bool = False;
    has has_rail: bool = False;

    can start with Root entry {
        visit [->:HasMember:->] else {
            print("no current generation: consumers cannot recompute or infer");
            disengage;
        }
    }

    can pick_generation with Generation entry {
        print(f"generation {here.gen_id} is_current={here.is_current}");
        self.validated = False;
        self.has_status = False;
        self.has_join = False;
        self.has_rail = False;
        visit [->:HasMember:->];
    }

    can read_status with CompilerProfileStatus entry {
        self.has_status = True;
        self.status_profile = here.profile;
        self.status_state = here.state;
        print(f"machine compiler-profile status: {here.profile} = {here.state}");
        visit [->:HasMember:->] else {
            self.finish();
            disengage;
        }
    }

    can read_join with JoinMember entry {
        self.has_join = True;
        print(f"join member: {here.consumer} row '{here.row_subject}'");
        visit [->:HasMember:->] else {
            self.finish();
            disengage;
        }
    }

    can read_rail with RailMember entry {
        self.has_rail = True;
        print(f"rail member: [{here.area}] profile '{here.profile}'");
        visit [->:HasMember:->] else {
            self.finish();
            disengage;
        }
    }

    def finish() {
        if not self.has_status or not self.has_join or not self.has_rail {
            print("missing required current join member -> explicit "
                  "unavailable/not-proven (cannot recompute or infer)");
            return;
        }
        self.validated = True;
        print(f"generation validated: status source "
              f"{self.status_profile}={self.status_state}");
    }

    can bind_join with JoinMember exit {
        blocked = not self.validated;
        for dep in [here ->:DependsOn:->] {
            if dep is CompilerProfileStatus and dep.state != "pass" {
                blocked = True;
            }
        }
        verdict = "blocked" if blocked else "satisfied";
        print(f"editor-intelligence row '{here.row_subject}': "
              f"substrate dep {verdict} (cannot manufacture canonical facts)");
    }

    can bind_rail with RailMember exit {
        src_ok = False;
        for dep in [here ->:DependsOn:->] {
            if dep is CompilerProfileStatus and dep.profile == here.profile
               and dep.state == "pass" {
                src_ok = True;
            }
        }
        state = "ok" if (src_ok and self.validated) else "blocked";
        print(f"rail [{here.area}] profile '{here.profile}': {state} "
              f"(lower/other-area profiles cannot satisfy this rail; "
              f"rail never disappears)");
    }
}

with entry {
    gen = Generation(gen_id="gen-12438", is_current=True);
    root ++> gen;

    status = CompilerProfileStatus(profile="gcc-13", state="pass");
    bad_status = CompilerProfileStatus(profile="clang-17", state="stale");
    gen +>:HasMember(role="status"):+> status;
    gen +>:HasMember(role="status"):+> bad_status;

    join = JoinMember(consumer="editor-intelligence",
                      row_subject="provider-edit-plane");
    rail = RailMember(profile="gcc-13", area="compiler");
    rail_parser = RailMember(profile="parser-core", area="parser");

    gen +>:HasMember(role="join"):+> join;
    gen +>:HasMember(role="rail"):+> rail;
    gen +>:HasMember(role="rail"):+> rail_parser;

    # join row depends on the exact compiler substrate status member
    join +>:DependsOn:+> status;
    # rails validate their exact status source identity
    rail +>:DependsOn:+> status;
    rail_parser +>:DependsOn:+> bad_status;

    root spawn GenerationAdapter();
}

"""QuReddy release roadmap: work items linked by typed `DependsOn` edges.

The issue complains about hand-rolled roadmap machinery (id-keyed maps and
manual recursion over dependencies). Here each checklist item is a node,
dependencies are typed edges, and a ReleaseAuditor walker traverses the
dependency graph with an explicit visited-guard cycle policy (jac walkers
do not dedupe visits on cyclic graphs), reporting items in a safe order.
"""

node Tracker {
    has name: str = "";
}

node WorkItem {
    has title: str = "";
    has category: str = "";
    has done: bool = False;
}

edge DependsOn {
    has reason: str = "";
}

edge Tracks {
    has section: str = "";
}

walker ReleaseAuditor {
    has seen: list[str] = [];
    has ready: list[str] = [];
    has blocked: list[str] = [];

    can start with Root entry {
        visit [->:Tracks:->] else {
            disengage;
        }
    }

    can audit with Tracker entry {
        visit [->:DependsOn:->] else {
            disengage;
        }
    }

    can inspect with WorkItem entry {
        # Cycle policy: explicit guard list, since visit does not dedupe.
        if here.title in self.seen {
            disengage;
        }
        self.seen.append(here.title);
        status = "READY" if here.done else "BLOCKED";
        if here.done {
            self.ready.append(here.title);
        } else {
            self.blocked.append(here.title);
        }
        print(f"[{status}] ({here.category}) {here.title}");
        visit [->:DependsOn:->] else {
            disengage;
        }
    }

    can finish with Root exit {
        print(f"audit done: {len(self.ready)} ready, {len(self.blocked)} blocked");
        report {
            "ready": self.ready,
            "blocked": self.blocked
        };
    }
}

with entry {
    tracker = Tracker(name="qureddy 0.2.x release candidate");

    fix_pqc = WorkItem(title="FIPS 205 missing from PQC table", category="bug");
    fix_excerpt = WorkItem(title="Evidence excerpt integrity mismatch", category="bug");
    cbom_repro = WorkItem(title="Reproducible CBOM output across hash seeds", category="testing");
    coverage = WorkItem(title="Raise coverage floor to 90%", category="testing");
    badge = WorkItem(title="OpenSSF Best Practices passing badge", category="ci");
    sign_releases = WorkItem(title="Sign all release artifacts", category="ci");
    cbom_correlated = WorkItem(title="Emit correlated JSON + CBOM", category="feature");

    root +>:Tracks(section="master roadmap"):+> tracker;

    tracker +>:DependsOn(reason="coverage floor is a badge MUST"):+> coverage;
    coverage +>:DependsOn(reason="fix live bugs before covering them"):+> fix_pqc;
    coverage +>:DependsOn:+> fix_excerpt;
    badge +>:DependsOn(reason="badge requires signed releases"):+> sign_releases;
    cbom_repro +>:DependsOn(reason="reproducible CBOM precedes emission work"):+> cbom_correlated;
    cbom_correlated +>:DependsOn:+> cbom_repro;

    fix_pqc.done = True;
    fix_excerpt.done = True;

    root spawn ReleaseAuditor();
}

"""Durable ETL job replay with immutable lineage.

Terminal (FAILED/CANCELLED) jobs can be replayed into a NEW PENDING job
linked back by a typed DerivedFrom edge. The source row is never mutated;
generation counts are bounded (1..100); a walker walks the lineage
backwards to the root to derive root id and generation, with an explicit
cycle guard (no built-in visitation dedupe exists).
"""

node EtlJob {
    has job_id: str = "";
    has job_status: str = "PENDING";  # PENDING | RUNNING | SUCCEEDED | FAILED | CANCELLED
    has request_digest: str = "";
    has owner: str = "";
    has replay_source_job_record_id: str | None = None;
    has replay_root_job_record_id: str | None = None;
    has replay_generation_count: int | None = None;
}

edge DerivedFrom {
    has provenance: str = "prov:wasDerivedFrom";
}

edge AuthoredBy {
    has principal: str = "";
}

walker Replayer {
    has candidate_payload: str = "";
    has new_digest: str = "";
    has max_generation: int = 100;
    has found_source: EtlJob | None = None;
    has lineage_root: EtlJob | None = None;
    has generation: int = 0;
    has errors: list[str] = [];

    can find_source with EtlJob entry {
        # Owner-safe resolution: only terminal jobs in our scope are visible.
        if here.job_status in {"FAILED", "CANCELLED"} and self.found_source is None {
            self.found_source = here;
        }
        visit [-->];
    }

    can replay with EtlJob entry {
        src = self.found_source;
        if src is None {
            self.errors += ["etl_job_not_found"];
            disengage;
        }
        if src.job_id == here.job_id and self.generation > 0 {
            self.errors += ["etl_job_replay_source_active"];
            disengage;
        }
    }

    can trace_lineage with EtlJob entry {
        # Walk backwards over DerivedFrom edges to the root, with a
        # cycle guard set (jac walkers do not dedupe visitation).
        src = self.found_source;
        if src is None {
            disengage;
        }
        if here.job_id == src.job_id {
            # starting point: begin the backward walk
            visit [<--:DerivedFrom:--] else {
                # first replay: no parent, this job IS the root
                self.lineage_root = src;
                self.generation = 0;
                disengage;
            }
        }
    }
}

walker LineageAuditor {
    has visited_ids: list[str] = [];
    has depth_cap: int = 100;

    can start with Root entry {
        visit [-->];
    }

    can audit with EtlJob entry {
        # Cycle guard: never audit the same row twice along one walk.
        if here.job_id in self.visited_ids {
            self.visited_ids += [f"CYCLE-AT-{here.job_id}"];
            disengage;
        }
        self.visited_ids += [here.job_id];
        if len(self.visited_ids) > self.depth_cap {
            print("generation bound exceeded");
            disengage;
        }
        role = "ROOT" if here.replay_generation_count is None else "REPLAY";
        print(f"[{role}] {here.job_id} status={here.job_status} "
              f"gen={here.replay_generation_count}");
        visit [-->] else {
            disengage;
        }
    }
}

walker ReplayRequester {
    has source_id: str = "";
    has payload_digest: str = "";
    has owner_scope: str = "acme";

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can submit with EtlJob entry {
        if here.job_id != self.source_id {
            visit [-->] else { disengage; }
        }
        # Eligibility: only terminal states replayable.
        if here.job_status in {"PENDING", "RUNNING"} {
            print(f"{here.job_id}: etl_job_replay_source_active");
            disengage;
        }
        if here.job_status == "SUCCEEDED" {
            print(f"{here.job_id}: etl_job_replay_source_succeeded");
            disengage;
        }
        # Payload must match the immutable terminal digest exactly.
        if self.payload_digest != here.request_digest {
            print(f"{here.job_id}: etl_job_replay_payload_mismatch");
            disengage;
        }
        # Derive root and bounded generation by walking the lineage.
        gen = 0;
        cursor: EtlJob = here;
        seen: list[str] = [];
        root_job: EtlJob = here;
        while True {
            if cursor.job_id in seen {
                print("lineage cycle detected; refusing replay");
                disengage;
            }
            seen += [cursor.job_id];
            parents = [cursor -->(DerivedFrom)];
            if len(parents) == 0 {
                break;
            }
            cursor = parents[0];
            root_job = cursor;
            gen += 1;
            if gen >= 100 {
                print(f"{here.job_id}: etl_job_replay_generation_exhausted");
                disengage;
            }
        }
        new_gen = gen + 1;
        # Create a NEW PENDING row; the source is never mutated.
        child = EtlJob(
            job_id=f"{here.job_id}-replay{new_gen}",
            job_status="PENDING",
            request_digest=here.request_digest,
            owner=here.owner,
            replay_source_job_record_id=here.job_id,
            replay_root_job_record_id=root_job.job_id,
            replay_generation_count=new_gen,
        );
        root ++> child;
        child +>:DerivedFrom:+> here;
        print(f"202 accepted: new job {child.job_id} "
              f"(source={here.job_id}, root={root_job.job_id}, gen={new_gen})");
        disengage;
    }
}

with entry {
    # principal scope
    acme = root;

    # lineage root job (terminal, replay fields all null)
    root_job = EtlJob(job_id="job-1", job_status="CANCELLED",
                      request_digest="sha256:abc", owner="acme");
    acme ++> root_job;

    # a prior replay of the root (generation 1)
    gen1 = EtlJob(job_id="job-1-replay1", job_status="FAILED",
                  request_digest="sha256:abc", owner="acme",
                  replay_source_job_record_id="job-1",
                  replay_root_job_record_id="job-1",
                  replay_generation_count=1);
    acme ++> gen1;
    gen1 +>:DerivedFrom:+> root_job;

    # replay the FAILED replay: generation must be exactly 2
    acme spawn ReplayRequester(source_id="job-1-replay1",
                               payload_digest="sha256:abc");

    # audit the whole lineage for immutability and ordering
    root spawn LineageAuditor();
}

"""Observation chain demo: typed Wraps edges replace reflective field walking.

Closes the pain in EpiAware issue #298 by giving observation chains a real
traversal API: a LeadIn walker sums delay lead-in over typed edges (no
fieldnames reflection), a Finder locates components by archetype instead of
brittle deep field paths, and a TreePrinter shows the whole chain rather
than only the outermost wrapper.
"""

node ObsComponent {
    has name: str = "";
    can describe() -> str {
        return self.name;
    }
}

node ErrorModel(ObsComponent) {
    has sigma: float = 0.0;
    override def describe() -> str {
        return f"{self.name}(sigma={self.sigma})";
    }
}

node LatentDelay(ObsComponent) {
    has delay_length: int = 0;
    override def describe() -> str {
        return f"{self.name}(delay={self.delay_length})";
    }
}

node Split(ObsComponent) {
    override def describe() -> str {
        return f"{self.name}(branches)";
    }
}

edge Wraps {
    has branch: str = "";
}

walker LeadIn {
    has total: int = 0;
    has seen: dict = {};

    can start with Root entry {
        visit [->:Wraps:->];
    }

    can accumulate with ObsComponent entry {
        # Explicit cycle guard (no built-in once-per-node visitation).
        key = here.name;
        if key in self.seen {
            disengage;
        }
        self.seen[key] = True;
        if here isa LatentDelay {
            self.total += here.delay_length - 1;
        }
        visit [->:Wraps:->] else { disengage; }
    }
}

walker FindDelays {
    has found: list = [];

    can start with Root entry {
        visit [->:Wraps:->];
    }

    can look with ObsComponent entry {
        if here isa LatentDelay {
            self.found.append(here.describe());
        }
        visit [->:Wraps:->] else { disengage; }
    }

    can report with Root exit {
        report(self.found);
    }
}

walker TreePrinter {
    has depth: int = 0;

    can start with Root entry {
        visit [->:Wraps:->];
    }

    can show with ObsComponent entry {
        indent = "  " * self.depth;
        print(f"{indent}- {here.describe()}");
        self.depth += 1;
        visit [->:Wraps:->] else { disengage; }
        self.depth -= 1;
    }
}

with entry {
    inner = ErrorModel(name="NegBinError", sigma=0.2);
    delay = LatentDelay(name="LatentDelay", delay_length=4);
    branch_a = LatentDelay(name="BranchDelayA", delay_length=3);
    branch_b = ErrorModel(name="BranchError", sigma=0.1);
    split = Split(name="Split");

    # chain: split wraps delay and (branch_a, branch_b); delay wraps inner
    root ++> split;
    split +>:Wraps(branch="main"):+> delay;
    split +>:Wraps(branch="alt"):+> branch_a;
    split +>:Wraps(branch="alt"):+> branch_b;
    delay +>:Wraps:+> inner;

    root spawn LeadIn();
    root spawn FindDelays();
    root spawn TreePrinter();
}

"""Wiki lint demo: find capture files under raw/ that no page cites."""

node Page {
    has title: str = "";
    has sources: list[str] = [];
}

node Capture {
    has path: str = "";
    has bytes: int = 0;
}

edge Cites {
    has resource: str = "";
}

edge Contains { }

walker LintOrphanCaptures {
    has referenced: dict = {};
    has orphans: list = [];

    can start with Root entry {
        visit [->:Contains:->];
    }

    can scan_pages with Page entry {
        for res in here.sources {
            if res not in self.referenced {
                self.referenced[res] = here.title;
            }
        }
        visit [-->];
    }

    can check_captures with Capture entry {
        if here.path not in self.referenced {
            self.orphans += [{"path": here.path, "bytes": here.bytes}];
        }
    }

    can report with Root exit {
        if len(self.orphans) == 0 {
            print("lint: no unreferenced captures under raw/");
        } else {
            for o in self.orphans {
                print(f"[orphan capture] {o['path']} ({o['bytes']} bytes) referenced by nothing");
            }
        }
    }
}

with entry {
    wiki = Page(title="wiki root");
    raw = Capture(path="raw/_dir", bytes=0);
