"""Impact analysis overlay: traverse diagram edges and catalog relations to
highlight transitive upstream/downstream impact, with a depth limit and
explicit cycle detection."""

node Shape {
    has title: str = "";
    has entity_id: str = "";   # link to catalog entity, "" if purely drawn
}

node CatalogEntity {
    has name: str = "";
}

# Drawn edges on the canvas
edge DrawsDependency {
    has label: str = "";
}

# Catalog-level relations (may not appear in this diagram)
edge RelatesTo {
    has kind: str = "depends_on";
}

edge ImpactedBy { }

walker ImpactAnalysis {
    has downstream: bool = True;
    has max_depth: int = 3;
    has use_catalog: bool = False;

    can analyze with Shape entry {
        here +>:ImpactedBy:+> here;  # not needed; marker replaced below
        disengage;
    }
}

walker ImpactWalker {
    has downstream: bool = True;
    has max_depth: int = 3;
    has use_catalog: bool = False;
    has visited: dict = {};
    has impacted: list = [];
    has cycles: list = [];

    can start with Shape entry {
        self.visited[here.title] = 0;
        self.impacted.append(here.title);
        self.depth_visit(here, 0, []);
        print(f"Impact set (downstream={self.downstream}, depth<={self.max_depth}): {self.impacted}");
        if len(self.cycles) {
            print(f"Dependency cycles detected: {self.cycles}");
        } else {
            print("No dependency cycles in scope");
        }
        disengage;
    }

    def depth_visit(cur: Shape, depth: int, path: list) {
        if depth >= self.max_depth {
            return;
        }
        nxt: list[Shape] = [];
        if self.downstream {
            nxt = [e for e in cur -->:Shape];
        } else {
            nxt = [e for e in cur <--:Shape];
        }
        if self.use_catalog and cur.entity_id != "" {
            # follow the catalog relation too (model-aware impact)
            for e in cur -->:Shape {
                if e not in nxt { nxt.append(e); }
            }
            for e in cur <--:Shape {
                if e not in nxt { nxt.append(e); }
            }
        }
        for n in nxt {
            if n.title in path {
                cyc = path[path.index(n.title):] + [n.title];
                if cyc not in self.cycles { self.cycles.append(cyc); }
                continue;
            }
            if n.title in self.visited { continue; }
            self.visited[n.title] = depth + 1;
            self.impacted.append(n.title);
            self.depth_visit(n, depth + 1, path + [n.title]);
        }
    }
}

with entry {
    # Diagram: api -> service -> db, plus a drawn cycle cache <-> service
    api = Shape(title="ApiHandler", entity_id="E1");
    svc = Shape(title="AuthService", entity_id="E2");
    db = Shape(title="UserTable", entity_id="E3");
    cache = Shape(title="CacheLayer", entity_id="");

    root ++> api;
    api +>:DrawsDependency(label="calls"):+> svc;
    svc +>:DrawsDependency(label="reads"):+> db;
    svc +>:DrawsDependency(label="uses"):+> cache;
    cache +>:DrawsDependency(label="invalidates"):+> svc;

    print("--- downstream impact from ApiHandler, depth 3, drawn edges only ---");
    api spawn ImpactWalker(downstream=True, max_depth=3, use_catalog=False);

    print("--- model-aware upstream impact from UserTable, depth 2 ---");
    db spawn ImpactWalker(downstream=False, max_depth=2, use_catalog=True);
}

"""Predicate metadata: sub-property closure expansion and inverse canonicalization.

Models GrEBI issue #48: ``rdfs:subPropertyOf`` edges are walked (with a cycle
guard, since the ontology may contain inconsistent chains) to build a closure
table at ingest, and each inverse pair is normalized to a single canonical
predicate + direction at ingest time rather than query time.
"""

node Predicate {
    has iri: str = "";
    has canonical: bool = True;   # False for the non-canonical member of an inverse pair
}

edge SubPropertyOf { }
edge InverseOf { has canonical_iri: str = ""; }

walker ClosureBuilder {
    has closure: dict = {};      # iri -> list of descendant iris
    has seen: set = set();       # cycle guard (explicit domain policy)

    can start with Root entry {
        visit [->:SubPropertyOf:->];
    }

    can descend with Predicate entry {
        if here.iri in self.seen {
            print(f"[cycle] skipping already-closed predicate {here.iri}");
            disengage;
        }
        self.seen.add(here.iri);
        subs = [e.target for e in [-->:SubPropertyOf:-->]];
        self.closure[here.iri] = subs;
        for s in subs {
            if s.iri not in self.closure {
                self.closure[s.iri] = [t for t in [e.target for e in [s-->:SubPropertyOf:-->]]];
            }
        }
        visit [->:SubPropertyOf:->] else { disengage; }
    }

    can report with Root exit {
        print("Predicate closure table (query-time expansion):");
        for (iri, subs) in self.closure.items() {
            expanded = ", ".join([iri] + [s.iri for s in subs]);
            print(f"  ask {iri} -> match {expanded}");
        }
    }
}

walker InverseNormalizer {
    has canonical_for: dict = {};  # non-canonical iri -> canonical iri

    can start with Root entry {
        visit [-->];
    }

    can normalize with Predicate entry {
        for e in [here-->:InverseOf:-->] {
            if not e.target.canonical {
                self.canonical_for[here.iri] = e.target.iri;
                print(f"[ingest] rewriting {here.iri} as inverse direction of {e.target.iri}");
            }
        }
        visit [-->] else { disengage; }
    }
}

walker QueryExpander {
    has requested: str = "";
    has closure: dict = {};

    can start with Root entry {
        targets = [p for p in [-->(?:Predicate)] if p.iri == self.requested];
        if not targets { print(f"unknown predicate {self.requested}"); disengage; }
        visit [-->];
    }
}

with entry {
    related_to = Predicate(iri="biolink:related_to");
    contributes = Predicate(iri="biolink:contributes_to");
    causes = Predicate(iri="biolink:causes");
    has_pheno = Predicate(iri="biolink:has_phenotype", canonical=True);
    pheno_of = Predicate(iri="biolink:phenotype_of", canonical=False);

    # rdfs:subPropertyOf chain: causes ⊑ contributes_to ⊑ related_to
    causes +>:SubPropertyOf:+> contributes +>:SubPropertyOf:+> related_to;
    # owl:inverseOf pair, canonical direction recorded on the edge
    has_pheno +>:InverseOf(canonical_iri="biolink:has_phenotype"):+> pheno_of;

    root spawn InverseNormalizer();

    expander = QueryExpander(requested="biolink:related_to");
    root spawn expander;

    root ++> related_to;
    root spawn ClosureBuilder();
}

"""Editor-intelligence external dependency contract: checked claim rows declare
exact external substrate dependencies (as dependency nodes on typed edges); an
auditor walker validates subject/stage/selector policy and composes the claim
ceiling; unlanded or non-passing source rows stay explicit unresolved blockers."""

node ClaimRow {
    has claim_id: str = "";
    has version: str = "";
    has subject: str = "";
    has checked: bool = False;
    has ceiling: str = "focused-evidence";

    def can_declare_dependency() -> bool {
        return self.checked;
    }
}

node Dependency {
    has dep_id: str = "";
    has dep_version: str = "";
    has disposition: str = "";      # required | conditional | optional | unsupported | not-applicable
    has selector: str = "";         # exact subject selector; empty on conditional is a violation
    has stage_relation: str = "";   # source | package | process | client | platform | root | series
}

node ExternalRow {
    has row_id: str = "";
    has schema: str = "";
    has state: str = "";            # pass | stale | absent | conflicting | invalid
    has landed: bool = True;
}

edge Declares {
    has family: str = "";
}

edge OnSourceRow { }

walker DependencyAuditor {
    has current_claim: ClaimRow | None = None;
    has ok: bool = True;
    has eligible: list[str] = [];
    has blocked: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can open_claim with ClaimRow entry {
        self.current_claim = here;
        self.ok = True;
        if not here.can_declare_dependency() {
            print(f"SKIP {here.claim_id}: unchecked claims cannot declare dependencies");
            here.ceiling = "blocked";
            self.current_claim = None;
            visit [-->] else { disengage; }
            return;
        }
        print(f"AUDIT {here.claim_id} ({here.version}) subject={here.subject}");
        visit [-->] else {
            print(f"{here.claim_id}: no external dependency, governed by focused evidence");
            self.eligible.append(here.claim_id);
        }
    }

    can close_claim with ClaimRow exit {
        if self.current_claim is not None {
            if self.ok {
                self.current_claim.ceiling = "external-backed";
                self.eligible.append(self.current_claim.claim_id);
            } else {
                self.current_claim.ceiling = "blocked";
                self.blocked.append(self.current_claim.claim_id);
            }
            print(f"CEILING {self.current_claim.claim_id}: {self.current_claim.ceiling}");
            self.current_claim = None;
        }
    }

    can check_dep with Dependency entry {
        if self.current_claim is None {
            visit [-->] else { disengage; }
            return;
        }
        if self.current_claim.claim_id == "" {
            self.ok = False;
        }
        claim_id = self.current_claim.claim_id if self.current_claim is not None else "?";
        if here.disposition == "conditional" and here.selector == "" {
            print(f"  dep {here.dep_id}: conditional with missing selector inputs -> blocked, not silently unselected");
            self.ok = False;
        } else if here.selector == "" {
            print(f"  dep {here.dep_id}: exact policy required, empty selector -> blocked");
            self.ok = False;
        } else {
            print(f"  dep {here.dep_id} (v{here.dep_version}, {here.disposition}, stage={here.stage_relation}, selector='{here.selector}')");
        }
        visit [-->] else {
            print(f"  dep {here.dep_id}: unlanded source schema/row authority is an explicit unresolved dependency");
            self.ok = False;
        }
    }

    can check_row with ExternalRow entry {
        if self.current_claim is None {
            return;
        }
        claim_id = self.current_claim.claim_id;
        if not here.landed {
            print(f"  source {here.row_id} schema={here.schema} not landed -> unresolved dependency for {claim_id}");
            self.ok = False;
        } else if here.state != "pass" {
            label = "stale source" if here.state == "stale" else f"{here.state} external row";
            print(f"  source {here.row_id} is {label} -> cannot become current through the dependency relation for {claim_id}");
            self.ok = False;
        } else {
            print(f"  source {here.row_id} state=pass satisfies dependency for {claim_id}");
        }
    }
}

with entry {
    c1 = ClaimRow(claim_id="clangd.completion", version="v3", subject="repo://lsp-swarm/src/clangd", checked=True);
    c2 = ClaimRow(claim_id="rust-analyzer.inlay", version="v1", subject="repo://lsp-swarm/src/ra", checked=True);
