"""Durable ETL job replay with immutable lineage.

Terminal (FAILED/CANCELLED) jobs are replayed into a NEW PENDING job
linked back by a typed DerivedFrom edge. The source row is never
mutated; generation counts are bounded (1..100). Root and generation
are derived by walking backwards over DerivedFrom edges with an
explicit cycle guard, since jac walkers do not dedupe visitation.
"""

node EtlJob {
    has job_id: str = "";
    has job_status: str = "PENDING";
    has request_digest: str = "";
    has owner: str = "";
    has replay_source_job_record_id: str | None = None;
    has replay_root_job_record_id: str | None = None;
    has replay_generation_count: int | None = None;
}

edge DerivedFrom {
    has provenance: str = "prov:wasDerivedFrom";
}

walker LineageTracer {
    has root_id: str = "";
    has steps: int = 0;
    has cycle: bool = False;

    can trace with EtlJob entry {
        if here.job_id == self.root_id {
            self.cycle = True;
            disengage;
        }
        self.root_id = here.job_id;
        self.steps += 1;
        if self.steps > 100 {
            self.cycle = True;
            disengage;
        }
        visit [<--:DerivedFrom:--] else {
            disengage;
        }
    }
}

walker LineageAuditor {
    has visited_ids: list[str] = [];
    has depth_cap: int = 100;

    can start with Root entry {
        visit [-->];
    }

    can audit with EtlJob entry {
        if here.job_id in self.visited_ids {
            print(f"CYCLE-AT-{here.job_id}: lineage is corrupt");
            disengage;
        }
        self.visited_ids.append(here.job_id);
        if len(self.visited_ids) > self.depth_cap {
            print("generation bound exceeded");
            disengage;
        }
        role = "ROOT" if here.replay_generation_count is None else "REPLAY";
        print(f"[{role}] {here.job_id} status={here.job_status} gen={here.replay_generation_count}");
        visit [-->] else {
            disengage;
        }
    }
}

walker ReplayRequester {
    has source_id: str = "";
    has payload_digest: str = "";
    has owner_scope: str = "acme";
    has max_generation: int = 100;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can submit with EtlJob entry {
        if here.job_id != self.source_id {
            disengage;
        }
        if here.owner != self.owner_scope {
            print(f"{self.source_id}: etl_job_not_found");
            disengage;
        }
        if here.job_status == "PENDING" or here.job_status == "RUNNING" {
            print(f"{here.job_id}: etl_job_replay_source_active");
            disengage;
        }
        if here.job_status == "SUCCEEDED" {
            print(f"{here.job_id}: etl_job_replay_source_succeeded");
            disengage;
        }
        if self.payload_digest != here.request_digest {
            print(f"{here.job_id}: etl_job_replay_payload_mismatch");
            disengage;
        }
        tracer = LineageTracer();
        here spawn tracer;
        if tracer.cycle {
            print(f"{here.job_id}: lineage cycle detected; refusing replay");
            disengage;
        }
        gen = tracer.steps;
        if gen >= self.max_generation {
            print(f"{here.job_id}: etl_job_replay_generation_exhausted");
            disengage;
        }
        new_gen = gen + 1;
        child = EtlJob(
            job_id=f"{here.job_id}-replay{new_gen}",
            job_status="PENDING",
            request_digest=here.request_digest,
            owner=here.owner,
            replay_source_job_record_id=here.job_id,
            replay_root_job_record_id=tracer.root_id,
            replay_generation_count=new_gen,
        );
        root ++> child;
        child +>:DerivedFrom:+> here;
        print(f"202 accepted: new job {child.job_id} source={here.job_id} root={tracer.root_id} gen={new_gen}");
        disengage;
    }
}

with entry {
    root_job = EtlJob(job_id="job-1", job_status="CANCELLED",
