"""Causal-closure deletion: walk the live compact-v2 review lifecycle and
delete every review symbol that is no longer reachable from it (issue #2423)."""

node Symbol {
    has name: str = "";
    has kind: str = "";          # "lifecycle" | "helper" | "legacy"
    has is_live: bool = True;    # flipped False when orphaned and deleted
}

edge Calls { }        # caller -> provider dependency
edge LifecycleStep { }  # edges within the live atomic lifecycle

walker OrphanAuditor {
    has reachable: dict = {};   # cycle guard: name -> True (no built-in dedupe)
    has doomed: list = [];

    can start with Symbol entry {
        self.mark_reachable();
        visit [->:LifecycleStep:->];
    }

    def mark_reachable() -> None {
        if here.name in self.reachable {
            return;
        }
        self.reachable[here.name] = True;
        for target in [here->:Calls:->] {
            # a lifecycle node marks its providers reachable too
            self.reachable[target.name] = True;
        }
    }

    can follow_step with Symbol entry {
        self.mark_reachable();
        visit [->:LifecycleStep:->] else { disengage; }
    }

    can sweep with Symbol entry {
        # second pass: anything not marked reachable is orphaned dead code
        if here.name not in self.reachable {
            print(f"DELETING orphaned {here.kind} symbol: {here.name}");
            here.is_live = False;
            self.doomed.append(here.name);
            del here;   # node deletion auto-purges its edges (causal closure)
            return;
        }
        print(f"RETAINED (live path): {here.kind} {here.name}");
    }
}

with entry {
    # Live atomic compact-v2 lifecycle: consent -> freeze -> lenses -> correction -> burn
    consent = Symbol(name="consent", kind="lifecycle");
    freeze = Symbol(name="freeze", kind="lifecycle");
    lenses = Symbol(name="lenses", kind="lifecycle");
    burn = Symbol(name="burn", kind="lifecycle");
    consent +>:LifecycleStep:+> freeze +>:LifecycleStep:+> lenses +>:LifecycleStep:+> burn;

    # providers with live consumers
    binding = Symbol(name="candidate_binding", kind="helper");
    lenses +>:Calls:+> binding;
    validator = Symbol(name="validator_evidence", kind="helper");
    burn +>:Calls:+> validator;

    # orphaned legacy surface: no live consumer after the clean break
    legacy = Symbol(name="legacy_receipt_reader", kind="legacy");
    compat = Symbol(name="compat_translator", kind="legacy");
    legacy +>:Calls:+> compat;          # dead calling dead
    tombstone = Symbol(name="tombstone_mirror", kind="legacy");
    tombstone +>:Calls:+> burn;         # points INTO the lifecycle, but nobody calls it

    root ++> consent ++> freeze ++> lenses ++> burn
        ++> binding ++> validator ++> legacy ++> compat ++> tombstone;

    root spawn OrphanAuditor();
}

"""Feature flag evaluation: dependency resolution over typed edges with an explicit cycle guard.

Lifts evaluateFlag()'s unguarded depends_on recursion into a walker that
tracks visited flag names and reports a dependency_cycle result instead of
diving into infinite mutual recursion.
"""

node Flag {
    has name: str = "";
    has enabled: bool = False;
    has rollout_percentage: int = 100;

    def is_on() -> bool {
        return self.enabled and self.rollout_percentage > 0;
    }
}

# Relationship: flag depends on another flag.
edge DependsOn { }

walker FlagEvaluator {
    has visited: list[str] = list();
    has result: str = "unknown";
    has evaluated: str = "";

    can start with Root entry {
        visit [-->];
    }

    can resolve with Flag entry {
        if here.name in self.visited {
            self.result = "dependency_cycle";
            print(f"[dependency_cycle] revisited '{here.name}' while resolving "
                  f"'{self.evaluated}' — stopping instead of recursing");
            disengage;
        }
        self.visited.append(here.name);
        if not here.is_on() {
            self.result = "disabled_by_flag";
            disengage;
        }
        # Dependencies first: evaluate each dep before this flag counts as on.
        deps = [here ->:DependsOn:->];
        if deps {
            self.evaluated = here.name;
            visit [here ->:DependsOn:->];
        } else {
            self.result = "enabled";
            print(f"[enabled] '{here.name}' with no dependencies");
        }
    }
}

walker FlagChainAuditor {
    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can audit with Flag entry {
        print(f"flag '{here.name}': enabled={here.enabled}, "
              f"rollout={here.rollout_percentage}%");
        visit [-->] else { disengage; }
    }
}

with entry {
    # Healthy chain: c -> b -> a
    a = Flag(name="a", enabled=True);
    b = Flag(name="b", enabled=True);
    c = Flag(name="c", enabled=True);
    c +>:DependsOn:+> b;
    b +>:DependsOn:+> a;
    root ++> c;

    print("--- healthy chain ---");
    root spawn FlagEvaluator();

    # Circular set: x <-> y (the crash scenario from issue #409)
