"""Predicate metadata: sub-property closure expansion and inverse canonicalization.

Models GrEBI issue #48: ``rdfs:subPropertyOf`` edges are walked (with a cycle
guard, since the ontology may contain inconsistent chains) to build a closure
table at ingest, and each inverse pair is normalized to a single canonical
predicate + direction at ingest time rather than query time.
"""

node Predicate {
    has iri: str = "";
    has canonical: bool = True;   # False for the non-canonical member of an inverse pair
}

edge SubPropertyOf { }
edge InverseOf { }

walker ClosureBuilder {
    has closure: dict = {};      # iri -> list of descendant iris
    has seen: set = set();       # cycle guard (explicit domain policy)

    can start with Root entry {
        visit [->:SubPropertyOf:->];
    }

    can descend with Predicate entry {
        if here.iri in self.seen {
            print(f"[cycle] skipping already-closed predicate {here.iri}");
            disengage;
        }
        self.seen.add(here.iri);
        child_edges = [here->:SubPropertyOf:->];
        subs = [e.target.iri for e in child_edges];
        self.closure[here.iri] = subs;
        for s_iri in subs {
            if s_iri not in self.closure {
                self.closure[s_iri] = [];
            }
        }
        visit [->:SubPropertyOf:->] else {
            disengage;
        }
    }

    can report with Root exit {
        print("Predicate closure table (query-time expansion):");
        for (iri, subs) in self.closure.items() {
            print(f"  ask {iri} -> match {iri} | {' | '.join(subs)}");
        }
    }
}

walker InverseNormalizer {
    has canonical_for: dict = {};  # non-canonical iri -> canonical iri

    can start with Root entry {
        visit [-->];
    }

    can normalize with Predicate entry {
        for e in [here->:InverseOf:->] {
            other = e.target;
            kept = here.iri if here.canonical else other.iri;
            dropped = other.iri if here.canonical else here.iri;
            self.canonical_for[dropped] = kept;
            print(f"[ingest] rewriting {dropped} as inverse direction of {kept}");
        }
        visit [-->] else {
            disengage;
        }
    }
}

walker QueryExpander {
    has requested: str = "";
    has expanded: list = [];

    can start with Root entry {
        self.expanded = [self.requested];
        visit [->:SubPropertyOf:->];
    }

    can collect with Predicate entry {
        if here.iri not in self.expanded {
            self.expanded.append(here.iri);
        }
        visit [->:SubPropertyOf:->] else {
            print(f"query asks {self.requested} -> cypher union: "
                  f"{':T|'.join(['']}{'|:T'.join(self.expanded)}:T");
            disengage;
        }
    }
}

with entry {
    related_to = Predicate(iri="biolink:related_to");
    contributes = Predicate(iri="biolink:contributes_to");
    causes = Predicate(iri="biolink:causes");
    has_pheno = Predicate(iri="biolink:has_phenotype", canonical=True);
    pheno_of = Predicate(iri="biolink:phenotype_of", canonical=False);

    # rdfs:subPropertyOf chain: causes <= contributes_to <= related_to
    causes +>:SubPropertyOf:+> contributes +>:SubPropertyOf:+> related_to;
    # owl:inverseOf pair, normalized at ingest to the canonical direction
    has_pheno +>:InverseOf:+> pheno_of;

    root ++> has_pheno ++> causes;
    root spawn InverseNormalizer();

    builder = ClosureBuilder();
    root spawn builder;

    expander = QueryExpander(requested="biolink:related_to");
    root spawn expander;
}

"""Impact analysis overlay: walk drawn diagram edges (and optional catalog
relations) to surface transitive upstream/downstream impact, with a depth
limit and explicit cycle detection."""

node Shape {
    has title: str = "";
    has entity_id: str = "";   # link to catalog entity, "" if purely drawn
}

edge DrawsDependency {
    has label: str = "";
}

# Catalog-level relation: may carry impact not visible as drawn edges
edge RelatesTo {
    has kind: str = "depends_on";
}

walker ImpactWalker {
    has downstream: bool = True;
    has max_depth: int = 3;
    has use_catalog: bool = False;
    has depth: int = 0;
    has visited: list[str] = [];
    has path: list[str] = [];
    has impacted: list[str] = [];
    has cycles: list[list[str]] = [];

    def record(title: str) {
        if title not in self.impacted {
            self.impacted.append(title);
        }
    }

    can explore with Shape entry {
        # Cycle detection: a node already on the current DFS path is a cycle
        if here.title in self.path {
            cyc = self.path[self.path.index(here.title):] + [here.title];
            if cyc not in self.cycles {
                self.cycles.append(cyc);
            }
            disengage;
        }
        # Depth cap is domain logic: stop descending past max_depth
        if self.depth > self.max_depth {
            disengage;
        }
        self.record(here.title);
        if here.title in self.visited {
            disengage;
        }
        self.visited.append(here.title);
        self.path.append(here.title);
        self.depth += 1;

        if self.downstream {
            visit [->:DrawsDependency:->];
            if self.use_catalog {
                visit [->:RelatesTo:->];
            }
        } else {
            visit [<--:DrawsDependency:--];
            if self.use_catalog {
                visit [<--:RelatesTo:--];
            }
        }
    }

    can leave with Shape exit {
        if here.title in self.path {
            self.path.pop();
        }
        if self.depth > 0 {
            self.depth -= 1;
        }
        # single exit summary once the traversal returns to the origin
        if len(self.impacted) and here.title == self.impacted[0] {
            direction = "downstream" if self.downstream else "upstream";
            print(f"Impact set ({direction}, depth<={self.max_depth}, "
                  f"catalog={self.use_catalog}): {self.impacted}");
            if len(self.cycles) {
                print(f"Dependency cycles detected: {self.cycles}");
            } else {
                print("No dependency cycles in scope");
            }
        }
    }
}

with entry {
    # Diagram: api -> svc -> db, plus a drawn cycle cache <-> svc,
    # and a hidden catalog relation db -> svc not drawn on the canvas.
    api = Shape(title="ApiHandler", entity_id="E1");
    svc = Shape(title="AuthService", entity_id="E2");
    db = Shape(title="UserTable", entity_id="E3");
    cache = Shape(title="CacheLayer", entity_id="");

    root ++> api;
    api +>:DrawsDependency(label="calls"):+> svc;
    svc +>:DrawsDependency(label="reads"):+> db;
    svc +>:DrawsDependency(label="uses"):+> cache;
    cache +>:DrawsDependency(label="invalidates"):+> svc;
    db +>:RelatesTo(kind="depended_on_by"):+> svc;

    print("--- downstream impact from ApiHandler, depth 3, drawn edges only ---");
    api spawn ImpactWalker(downstream=True, max_depth=3, use_catalog=False);

    print("--- model-aware upstream impact from UserTable, depth 2 ---");
    db spawn ImpactWalker(downstream=False, max_depth=2, use_catalog=True);
}

"""Causal-closure deletion: walk the live compact-v2 review lifecycle and
delete every review symbol that is no longer reachable from it (issue #2423)."""

node Symbol {
    has name: str = "";
    has kind: str = "";          # "lifecycle" | "helper" | "legacy"
    has is_live: bool = True;    # flipped False when orphaned and deleted
}

edge Calls { }           # caller -> provider dependency
edge LifecycleStep { }   # edges within the live atomic lifecycle

walker ReachabilityMarker {
    has reachable: dict[str, bool] = {};   # explicit cycle guard (no built-in dedupe)

    can start with Root entry {
        visit [-->];
    }

    can mark with Symbol entry {
        if here.name in self.reachable {
            return;   # cycle guard: already marked, stop descending
        }
        self.reachable[here.name] = True;
        print(f"reachable: {here.kind} {here.name}");
        visit [->:LifecycleStep:->];
        visit [->:Calls:->];
    }
}

walker OrphanSweeper {
    has reachable: dict[str, bool] = {};
    has doomed: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can sweep with Symbol entry {
        if here.name not in self.reachable {
            print(f"DELETING orphaned {here.kind} symbol: {here.name}");
            self.doomed.append(here.name);
            del here;   # node deletion auto-purges its edges (causal closure)
            return;
        }
        print(f"RETAINED (live path): {here.kind} {here.name}");
        visit [-->];
    }
}

