}

"""Corpus map demo: immutable sources feed canonical concepts; a walker
classifies a new fragment as EXISTS / EXTENDS / RELATED / NEW against the
canonical concept registry via typed-edge traversal."""

edge Supports {
    has fragment: str = "";
    has weight: float = 0.0;
}

edge RelatedTo {
    has strength: float = 0.0;
}

node Source {
    has title: str = "";
    has origin: str = "";
    has hash: str = "";
}

node Concept {
    has name: str = "";
    has aliases: list[str] = [];
    has depth: float = 0.0;
}

node Fragment {
    has label: str = "";
    has terms: list[str] = [];
}

walker Classifier {
    has target_terms: list[str] = [];
    has matched: str = "";
    has best_score: float = 0.0;
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    # Skip immutable sources; only concepts are consulted.
    can skip_source with Source entry {
        visit [-->];
    }

    # Score the incoming fragment terms against each canonical concept,
    # including related neighbors — no manual adjacency maps or recursion.
    can classify with Concept entry {
        if here.name in self.seen {
            # explicit cycle guard: jac walkers do not dedupe on their own
            disengage;
        }
        self.seen.append(here.name);
        overlap = 0;
        for term in here.aliases {
            if term in self.target_terms {
                overlap += 1;
            }
        }
        score = overlap / max(1, len(self.target_terms));
        if here.depth < 1.0 {
            coverage = score;
        } else {
            coverage = score * 0.9;
        }
        if coverage > self.best_score {
            self.best_score = coverage;
            self.matched = here.name;
        }
        visit [->:RelatedTo:->];
    }

    can ignore with Fragment entry {
        visit [-->] else { disengage; }
    }
}

walker Registrar {
    has target_terms: list[str] = [];
    has matched: str = "";
    has best_score: float = 0.0;

    can start with Root entry {
        visit [-->];
    }

    can report with Fragment entry {
        if self.best_score >= 0.8 {
            verdict = "EXISTS";
        } elif self.best_score >= 0.5 {
            verdict = "EXTENDS";
        } elif self.best_score > 0.0 {
            verdict = "RELATED";
        } else {
            verdict = "NEW";
        }
        print(f"fragment '{here.label}' vs '{self.matched}': "
              f"score={self.best_score:.2f} verdict={verdict}");
        visit [-->] else { disengage; }
    }

    can skip with Source | Concept entry {
        visit [-->];
    }
}

with entry {
    # Seed corpus: sources are immutable evidence.
    src1 = Source(title="Lecture on Systems", origin="IME611/IME-611", hash="a1b2");
    src2 = Source(title="Notes on Feedback", origin="IME611/IME-611", hash="c3d4");

    # Canonical, deduplicated concepts; one concept may draw on many sources.
    feedback = Concept(name="Feedback Loop", aliases=["feedback", "loop"], depth=0.7);
    emergence = Concept(name="Emergence", aliases=["emergence", "emergent"], depth=0.4);
    src1 +>:Supports(fragment="ch2 p14", weight=0.9):+> feedback;
    src2 +>:Supports(fragment="para 3", weight=0.6):+> feedback;
    src2 +>:Supports(fragment="para 9", weight=0.8):+> emergence;
    feedback +>:RelatedTo(strength=0.5):+> emergence;

    root ++> src1 ++> src2;
    root ++> feedback ++> emergence;

    # A new incoming fragment to classify against the registry.
    frag = Fragment(label="new note", terms=["feedback", "loop"]);
    root ++> frag;

    target = ["feedback", "loop"];
    cls = frag spawn Classifier(target_terms=target);
    frag spawn Registrar(target_terms=target, matched=cls.matched, best_score=cls.best_score);
}

"""Per-kind reflector store with tombstones and atomic swap at InitDone.

Events only mark objects present in the store (level-triggered); the
InitDone pass tombstones everything not seen during the initial list,
replacing edge-triggered delete handling.
"""

edge Watches { }

node Object {
    has name: str = "";
    has kind: str = "";
    has data: str = "";
    has in_store: bool = False;
    has seen_in_init: bool = False;
}

node Store {
    has kind: str = "";
    has initialized: bool = False;
    has dirty: bool = False;

    def snapshot() -> list[str] {
        names = [];
        for obj in [self->:StoredIn:->] {
            if obj.in_store {
                names.append(obj.name);
            }
        }
        return names;
    }
}

edge StoredIn { has applied: bool = True; }

walker Reflector {
    has kind: str = "";
    has init_done: bool = False;

    can start with Root entry {
        visit [->:Watches:->];
    }

    can reach_store with Store entry {
        if here.kind != self.kind {
            disengage;
        }
        visit [->:StoredIn:->];
    }

    # Apply / InitApply / Delete all just update the store — no branching
    # on variant semantics; decisions come from reading the store.
    can apply with Object entry {
        if not self.init_done {
            here.seen_in_init = True;
        }
        here.in_store = True;
        visit [->:StoredIn:->];
    }

    # InitDone: atomically swap staging in and tombstone anything from a
    # previous generation that never appeared in the initial list.
    can init_done with Store entry {
        if here.kind != self.kind or self.init_done {
            disengage;
        }
        self.init_done = True;
        for obj in [here->:StoredIn:->] {
            if not obj.seen_in_init {
                obj.in_store = False;
            }
        }
        here.initialized = True;
        here.dirty = False;
        print(f"{here.kind} store initialized: {here.snapshot()}");
        disengage;
    }
}

with entry {
    gw_store = Store(kind="Gateway");
    rt_store = Store(kind="HTTPRoute");

    root +>:Watches:+> gw_store;
    root +>:Watches:+> rt_store;

    gw1 = Object(name="gw-a", kind="Gateway", data="listen=80");
    gw2 = Object(name="gw-old", kind="Gateway", data="stale");
    rt1 = Object(name="rt-1", kind="HTTPRoute", data="host=foo.example");

    gw_store +>:StoredIn:+> gw1;
    gw_store +>:StoredIn:+> gw2;
    rt_store +>:StoredIn:+> rt1;

    root spawn Reflector(kind="Gateway");
    root spawn Reflector(kind="HTTPRoute");

    print(f"routes visible after swap: {rt_store.snapshot()}");
    print(f"gateways visible after swap: {gw_store.snapshot()}");
}

"""Feature flag evaluation: dependency resolution over typed edges with an explicit cycle guard.

Lifts evaluateFlag()'s unguarded depends_on recursion into a walker that
tracks visited flag names and reports a dependency_cycle result instead of
diving into infinite mutual recursion.
"""

node Flag {
    has name: str = "";
    has enabled: bool = False;
    has rollout_percentage: int = 100;

    def is_on() -> bool {
        return self.enabled and self.rollout_percentage > 0;
    }
}

# Relationship: flag depends on another flag.
edge DependsOn { }

walker FlagEvaluator {
    has visited: list[str] = list();
    has result: str = "unknown";
    has evaluated: str = "";

    can start with Root entry {
        visit [-->];
    }

    can resolve with Flag entry {
        if here.name in self.visited {
            self.result = "dependency_cycle";
            print(f"[dependency_cycle] revisited '{here.name}' while resolving "
                  f"'{self.evaluated}' — stopping instead of recursing");
            disengage;
        }
        self.visited.append(here.name);
        if not here.is_on() {
            self.result = "disabled_by_flag";
            print(f"[disabled_by_flag] '{here.name}'");
            disengage;
        }
        self.evaluated = here.name;
        visit [->:DependsOn:->] else {
            self.result = "enabled";
            print(f"[enabled] '{here.name}' with no dependencies");
        }
    }
}

walker FlagChainAuditor {
    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can audit with Flag entry {
        print(f"flag '{here.name}': enabled={here.enabled}, "
              f"rollout={here.rollout_percentage}%");
        visit [-->] else { disengage; }
    }
}

with entry {
    # Healthy chain: c -> b -> a
    a = Flag(name="a", enabled=True);
    b = Flag(name="b", enabled=True);
    c = Flag(name="c", enabled=True);
    c +>:DependsOn:+> b;
    b +>:DependsOn:+> a;
    root ++> c;

    print("--- healthy chain ---");
