"""Predicate metadata: sub-property closure expansion and inverse canonicalization.

Models GrEBI issue #48: ``rdfs:subPropertyOf`` edges are walked (with a cycle
guard, since the ontology may contain inconsistent chains) to build a closure
table at ingest, and each inverse pair is normalized to a single canonical
predicate + direction at ingest time rather than query time.
"""

node Predicate {
    has iri: str = "";
    has canonical: bool = True;   # False for the non-canonical member of an inverse pair
}

edge SubPropertyOf { }
edge InverseOf { }

walker ClosureBuilder {
    has closure: dict[str, list[str]] = {};  # iri -> list of descendant iris
    has current: str = "";                   # predicate whose closure we are extending
    has seen: set[str] = set();              # cycle guard (explicit domain policy)

    can start with Root entry {
        visit [-->];
    }

    can descend with Predicate entry {
        if here.iri in self.seen {
            print(f"[cycle] skipping already-closed predicate {here.iri}");
            disengage;
        }
        self.seen.add(here.iri);
        if self.current != "" and self.current != here.iri {
            if self.current not in self.closure {
                self.closure[self.current] = [];
            }
            self.closure[self.current].append(here.iri);
        }
        prev = self.current;
        self.current = here.iri;
        visit [->:SubPropertyOf:->] else {
            self.current = prev;
            disengage;
        }
        self.current = prev;
    }

    can report with Root exit {
        print("Predicate closure table (query-time expansion):");
        for (iri, subs) in self.closure.items() {
            print(f"  ask {iri} -> match {iri} | {' | '.join(subs)}");
        }
    }
}

walker InverseNormalizer {
    has canonical_for: dict[str, str] = {};  # non-canonical iri -> canonical iri

    can start with Root entry {
        visit [-->];
    }

    can normalize with Predicate entry {
        for e in [here->:InverseOf:->] {
            other = e.target;
            kept = "";
            dropped = "";
            if here.canonical {
                kept = here.iri;
                dropped = other.iri;
            } else {
                kept = other.iri;
                dropped = here.iri;
            }
            self.canonical_for[dropped] = kept;
            print(f"[ingest] rewriting {dropped} as inverse direction of {kept}");
        }
        visit [-->] else {
            disengage;
        }
    }
}

walker QueryExpander {
    has requested: str = "";
    has expanded: list[str] = [];

    can start with Root entry {
        self.expanded.append(self.requested);
        visit [-->];
    }

    can collect with Predicate entry {
        if here.iri not in self.expanded {
            self.expanded.append(here.iri);
        }
        visit [->:SubPropertyOf:->] else {
            union = "|".join(self.expanded);
            print(f"query asks {self.requested} -> cypher union: {union}");
            disengage;
        }
    }
}

with entry {
    related_to = Predicate(iri="biolink:related_to");
    contributes = Predicate(iri="biolink:contributes_to");
    causes = Predicate(iri="biolink:causes");
    has_pheno = Predicate(iri="biolink:has_phenotype", canonical=True);
    pheno_of = Predicate(iri="biolink:phenotype_of", canonical=False);

    # rdfs:subPropertyOf chain: related_to is expanded down to its sub-predicates
    related_to +>:SubPropertyOf:+> contributes +>:SubPropertyOf:+> causes;
    # owl:inverseOf pair, normalized at ingest to the canonical direction
    has_pheno +>:InverseOf:+> pheno_of;

    root ++> has_pheno ++> related_to;
    root spawn InverseNormalizer();

    builder = ClosureBuilder();
    root spawn builder;

    expander = QueryExpander(requested="biolink:related_to");
    root spawn expander;
}

"""Hierarchical library: reject circular reference insertion and make recursive
operations terminate on pre-existing cycles (issue #297)."""

node Cell {
    has name: str = "";

    def children() -> list {
        return [self ->:Sub:->];
    }

    def path_to(target: Cell, seen: list) -> str | None {
        """Return edge path string from self to target, or None."""
        if target in seen {
            return None;
        }
        seen.append(self);
        for kid in self.children() {
            if kid == target {
                return f"{self.name} -> {kid.name}";
            }
            sub = kid.path_to(target, seen);
            if sub is not None {
                return f"{self.name} -> {sub}";
            }
        }
        return None;
    }
}

edge Sub { }

# Public API: checked reference insertion — atomic, returns error path on cycle.
def safe_link(parent: Cell, child: Cell) -> str | None {
    if parent == child {
        return f"direct cycle: {parent.name} -> {child.name}";
    }
    if child in parent.children() {
        return f"duplicate link: {parent.name} -> {child.name}";
    }
    probe = child.path_to(parent, []);
    if probe is not None {
        return f"would create cycle: {child.name} -> {probe}";
    }
    parent +>:Sub:+> child;
    return None;
}

walker Builder {
    can start with Root entry {
        visit [-->];
    }

    can build with Cell entry {
        visit [->:Sub:->] else { disengage; }
    }
}

# Recursive public operation with cycle guard so it terminates on bad fixtures.
walker Flattener {
    has flattened: list[str] = list();
    has error: str = "";
    has seen: list = list();

    can start with Root entry {
        visit [-->];
    }

    can flatten with Cell entry {
        if here in self.seen {
            self.error = f"circular reference detected at {here.name}";
            disengage;
        }
        self.seen.append(here);
        self.flattened.append(here.name);
        visit [->:Sub:->] else { disengage; }
    }
}

with entry {
    top = Cell(name="TOP");
    mid = Cell(name="MID");
    leaf = Cell(name="LEAF");
    root ++> top;
    top +>:Sub:+> mid;
    mid +>:Sub:+> leaf;

    err = safe_link(leaf, top);
    rej = err if err is not None else "none";
    print(f"rejection: {rej}");
    top_kids = top.children();
    print(f"top still has {len(top_kids)} child edges: library unchanged");

    # Deliberately build a cyclic fixture to prove recursive ops terminate.
    leaf +>:Sub:+> mid;
    fl = Flattener();
    top spawn fl;
    if fl.error != "" {
        print(f"flatten aborted: {fl.error}");
        print(f"visited before abort: {fl.flattened}");
    } else {
        print(f"flattened: {fl.flattened}");
    }

    # A clean library still builds fine with checked insertion.
    ok = safe_link(top, Cell(name="EXTRA"));
    print(f"second insertion error: {ok if ok is not None else 'none'}");
}

"""Directory tree traversal under -Recurse: reparse points are not followed.

Demonstrates Option A from issue #10: a directory marked as a reparse point
(symbolic link, junction, mount point) is surfaced as an ordinary entry but
its target is never descended into. A second walker shows the naive
unconditional-follow behavior looping forever on a link to its own ancestor,
bounded here by an explicit cycle guard — the scaffolding the idiomatic
traversal must carry when reparse semantics are ignored.
"""

node FsEntry {
    has name: str = "";
}

node DirNode(FsEntry) {
    has reparse: bool = False;
}

node FileNode(FsEntry) {
    has size: int = 0;
}

edge Contains { }

edge LinksTo { }

walker SafeInventory {
    has total_files: int = 0;
    has total_bytes: int = 0;
    has skipped_reparse: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can descend with DirNode entry {
        # Option A: never traverse a reparse point's target.
        if here.reparse {
            self.skipped_reparse.append(here.name);
            report f"reparse point (not descended): {here.name}";
        } else {
            visit [->:Contains:->];
        }
    }

    can count with FileNode entry {
        self.total_files += 1;
        self.total_bytes += here.size;
    }
}

walker NaiveInventory {
    has seen: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 20;

    can start with Root entry {
        visit [-->];
    }

    can descend with DirNode entry {
        # The unguarded production behavior, given a cycle guard only so the
        # demo terminates: follow links unconditionally and loop forever.
        if here.name in self.seen or self.depth > self.max_depth {
            report f"cycle/limit hit at: {here.name}";
            disengage;
        }
        self.seen.append(here.name);
        self.depth += 1;
        visit [->:Contains:->];
    }

    can count with FileNode entry {
        report f"counted (possibly out-of-root): {here.name}";
    }
}

with entry {
    root_dir = DirNode(name="proj");
    src = DirNode(name="src");
    docs = DirNode(name="docs");
    link_up = DirNode(name="up_link", reparse=True);

    root_dir +>:Contains:+> src;
    root_dir +>:Contains:+> docs;
    src +>:Contains:+> FileNode(name="a.py", size=100);
    docs +>:Contains:+> FileNode(name="readme.md", size=30);
    docs +>:Contains:+> link_up;
    link_up +>:Contains:+> FileNode(name="outside.txt", size=999);

    # Naive walker's target cycles back to the root directory.
    link_up +>:LinksTo:+> root_dir;

    root spawn SafeInventory();
    root ++> link_up;
    root spawn NaiveInventory();

    inv = SafeInventory();
    root ++> root_dir;
    root spawn inv;
    report f"safe inventory: {inv.total_files} files, "
           f"{inv.total_bytes} bytes, skipped: {inv.skipped_reparse}";
}

