"""CI workflow retirement audit: walk caller/consumer edges and retire only
proven-orphaned workflows; anything uncertain stays 'not_proven'."""

edge CalledBy { has lane: str = ""; }
edge RetiredBy { has reason: str = ""; }
edge EvidenceOf { has location: str = ""; }

node Workflow {
    has name: str = "";
    has kind: str = "workflow";            # workflow | reusable | temp
    has classification: str = "active";   # active | orphaned | expired | duplicate | not_proven
    has live_enabled: bool = True;
    has retired: bool = False;

    def has_callers() -> bool {
        return len([here ->:CalledBy:->]) > 0;
    }
}

node CheckRef {
    has check_name: str = "";
    has stale: bool = False;
}

walker Auditor {
    has visited: dict = {};
    has retirement_reason: str = "orphaned-temporary";
    has retired_count: int = 0;
    has held_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Workflow entry {
        # explicit once-per-node guard: jac walkers do not dedupe visits
        if here.name in self.visited {
            disengage;
        }
        self.visited[here.name] = True;

        if here.retired {
            visit [-->];
        }

        # domain rule: never delete a workflow still called by an
        # authoritative path, even if inventory calls it orphaned
        if here.has_callers() or here.live_enabled and here.classification != "orphaned" and here.classification != "expired" {
            here.classification = "not_proven" if here.has_callers() and here.classification in ("orphaned", "expired") else here.classification;
            self.held_count += 1;
            print(f"HOLD  {here.name}: callers or live enablement present");
            visit [-->];
        }

        if here.classification in ("orphaned", "expired") {
            here.retired = True;
            self.retired_count += 1;
            print(f"RETIRE {here.name}: {self.retirement_reason}");
        } else {
            print(f"KEEP  {here.name}: classification={here.classification}");
            self.held_count += 1;
        }
        visit [-->] else { disengage; }
    }

    can inspect with CheckRef entry {
        status = "STALE" if here.stale else "ok";
        print(f"CHECK {here.check_name}: {status}");
        visit [-->] else { disengage; }
    }
}

