"""Per-kind reflector store with tombstones and atomic swap at InitDone.

Events only mark objects present in the store (level-triggered); the
InitDone pass tombstones everything not seen during the initial list,
replacing edge-triggered delete handling.
"""

edge Watches { }

node Object {
    has name: str = "";
    has kind: str = "";
    has data: str = "";
    has in_store: bool = False;
    has seen_in_init: bool = False;
}

node Store {
    has kind: str = "";
    has initialized: bool = False;
    has dirty: bool = False;

    def snapshot() -> list[str] {
        names = [];
        for obj in [self -->] {
            if obj.in_store {
                names.append(obj.name);
            }
        }
        return names;
    }
}

edge StoredIn { }

walker Reflector {
    has kind: str = "";
    has init_done: bool = False;

    can start with Root entry {
        visit [->:Watches:->] else { disengage; }
    }

    can reach_store with Store entry {
        if here.kind != self.kind {
            disengage;
        }
        here.dirty = True;
        visit [->:StoredIn:->];
    }

    # Apply / InitApply / Delete all just update the store — no branching
    # on variant semantics; decisions come from reading the store.
    can apply with Object entry {
        if not self.init_done {
            here.seen_in_init = True;
        }
        here.in_store = True;
    }
}

# Second pass: the atomic swap. The walker re-enters the store, flips the
# init flag, then tombstones every stored object that never appeared in
# the initial list (the InitDone semantics from kube-rs).
walker Swap {
    has kind: str = "";

    can start with Root entry {
        visit [->:Watches:->] else { disengage; }
    }

    can enter_store with Store entry {
        if here.kind != self.kind {
            disengage;
        }
        visit [->:StoredIn:->];
    }

    can sweep with Object entry {
        if not here.seen_in_init {
            here.in_store = False;
        }
    }

    can leave_store with Store exit {
        if here.kind == self.kind and not here.initialized {
            here.initialized = True;
            here.dirty = False;
            print(f"{here.kind} store initialized: {here.snapshot()}");
        }
    }
}

with entry {
    gw_store = Store(kind="Gateway");
    rt_store = Store(kind="HTTPRoute");

    root +>:Watches:+> gw_store;
    root +>:Watches:+> rt_store;

    gw1 = Object(name="gw-a", kind="Gateway", data="listen=80");
    gw2 = Object(name="gw-old", kind="Gateway", data="stale");
    rt1 = Object(name="rt-1", kind="HTTPRoute", data="host=foo.example");

    gw_store +>:StoredIn:+> gw1;
    gw_store +>:StoredIn:+> gw2;
    rt_store +>:StoredIn:+> rt1;

    # Apply/InitApply stream for both kinds, then the InitDone swap.
    root spawn Reflector(kind="Gateway");
    root spawn Reflector(kind="HTTPRoute");
    root spawn Swap(kind="Gateway");
    root spawn Swap(kind="HTTPRoute");

    print(f"routes visible after swap: {rt_store.snapshot()}");
    print(f"gateways visible after swap: {gw_store.snapshot()}");
}

"""Dense knowledge flow vs declared dependency graph.

Mirrors issue #193: every completed task's answer is forwarded to all
downstream tasks (dense all-to-downstream flow) while the plan declares
a sparse ``DependsOn`` graph.  Two walkers contrast the effective
information flow with the declared one and log per-task handoff size.
"""

node Task {
    has name: str = "";
    has answer: str = "";
    has completed: bool = False;
}

node Plan {
    has name: str = "";
}

edge PartOf { }
edge DependsOn { }

walker Scheduler {
    """Walks only declared DependsOn edges (sparse, proposed behavior)."""
    has knowledge: list[str] = [];

    can start with Root entry {
        visit [->:PartOf:->];
    }

    can schedule with Plan entry {
        visit [->:PartOf:->];
    }

    can announce with Task entry {
        print(f"[declared] {here.name} reads only its depends_on inputs");
        visit [<--:DependsOn:--];
    }
}

walker DenseForwarder {
    """Old behavior: forward every completed answer to every task."""
    has knowledge: list[str] = [];
    has flow_mode: str = "all";

    can start with Root entry {
        visit [->:PartOf:->];
    }

    can enter_plan with Plan entry {
        visit [-->];
    }

    can forward with Task entry {
        if here.completed {
            self.knowledge.append(here.answer);
        }
        handed = 0;
        for ans in self.knowledge {
            handed += len(ans);
        }
        mode = "deps-only" if self.flow_mode == "dependencies" else "all";
        print(f"[effective:{mode}] {here.name} prompt carries "
              f"{len(self.knowledge)} answers ({handed} chars)");
        if self.flow_mode == "all" {
            visit [-->] else { disengage; }
        } else {
            visit [<--:DependsOn:--] else { disengage; }
        }
    }
}

with entry {
    plan = Plan(name="lab-workflow");

    t1 = Task(name="collect", answer="dataset-v2 raw counts", completed=True);
    t2 = Task(name="analyze", answer="cluster k=7 dominant", completed=True);
    t3 = Task(name="hypothesize", answer="signal in cluster-3");
    t4 = Task(name="report");

    root +>:PartOf:+> plan;
    plan +>:PartOf:+> t1;
    plan +>:PartOf:+> t2;
    plan +>:PartOf:+> t3;
    plan +>:PartOf:+> t4;

    t3 +>:DependsOn:+> t2;
    t2 +>:DependsOn:+> t1;
    t4 +>:DependsOn:+> t3;

    root spawn Scheduler();
    root spawn DenseForwarder(flow_mode="all");
    root spawn DenseForwarder(flow_mode="dependencies");
}

"""Directory tree traversal under -Recurse: reparse points are not followed.

Demonstrates Option A from issue #10: a directory marked as a reparse point
(symbolic link, junction, mount point) is surfaced as an ordinary entry but
its target is never descended into. A second walker shows the naive
unconditional-follow behavior, bounded here by an explicit cycle guard —
the stateful scaffolding the idiomatic traversal eliminates.
"""

node DirNode {
    has name: str = "";
    has reparse: bool = False;
}

node FileNode {
    has name: str = "";
    has size: int = 0;
}

edge Contains {
    has kind: str = "child";
}

edge LinksTo {
    has kind: str = "reparse";
}

walker SafeInventory {
    has total_files: int = 0;
    has total_bytes: int = 0;
    has skipped_reparse: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can descend with DirNode entry {
        # Option A: never traverse a reparse point's target.
        if here.reparse {
            self.skipped_reparse.append(here.name);
            print(f"reparse point (not descended): {here.name}");
        } else {
            visit [->:Contains:->];
        }
    }

    can count with FileNode entry {
        self.total_files += 1;
        self.total_bytes += here.size;
    }
}

walker NaiveInventory {
    has seen: list[str] = [];
    has max_depth: int = 20;

    can start with Root entry {
        visit [-->];
    }

    can descend with DirNode entry {
        # The unguarded production behavior, given a cycle guard only so the
        # demo terminates: follow links unconditionally and loop forever.
        if here.name in self.seen or self.max_depth <= 0 {
            print(f"cycle/limit hit at: {here.name}");
            disengage;
        }
        self.seen.append(here.name);
        self.max_depth -= 1;
        visit [->:Contains:->] else {
            visit [->:LinksTo:->];
        }
    }

    can count with FileNode entry {
        print(f"counted (possibly out-of-root): {here.name}");
    }
}

with entry {
    root_dir = DirNode(name="proj");
    src = DirNode(name="src");
    docs = DirNode(name="docs");
    link_up = DirNode(name="up_link", reparse=True);

    root_dir +>:Contains:+> src;
    root_dir +>:Contains:+> docs;
    src +>:Contains:+> FileNode(name="a.py", size=100);
    docs +>:Contains:+> FileNode(name="readme.md", size=30);
    docs +>:Contains:+> link_up;
    link_up +>:Contains:+> FileNode(name="outside.txt", size=999);

    # Naive walker's target cycles back to the root directory.
    link_up +>:LinksTo:+> root_dir;

    print("=== Option A: safe inventory (reparse points not followed) ===");
    safe = SafeInventory();
    root ++> root_dir;
    root spawn safe;
    print(f"safe inventory: {safe.total_files} files, "
          f"{safe.total_bytes} bytes, skipped: {safe.skipped_reparse}");

    print("=== Naive traversal (follows links, needs a cycle guard) ===");
    naive = NaiveInventory();
    root ++> link_up;
    root spawn naive;
}

"""Benchmark registry for the gpytorch-gp-predict baseline.

Models the issue's registry: an applicability gate decides which
benchmark families a baseline supports, and a Cell node records per
(n_nodes, metric) outcomes. An Auditor walker traverses the registry's
support edges into family cells, reproducing the status breakdown and
flagging suspicious cells: accuracy not_supported while timing ran ok,
and timing anomalies where large graphs finish as fast as tiny ones.
"""

edge Supports { }

node Family {
    has name: str = "";
}

node Cell {
    has family: str = "";
    has n_nodes: int = 0;
    has metric: str = "";
    has status: str = "";      # ok | not_supported | timeout
    has seconds: float = 0.0;
}

node Baseline {
    has name: str = "";
    has accuracy_supported: bool = False;
    has supported: list[str] = [];
}

walker Auditor {
    has ok: int = 0;
    has not_supported: int = 0;
    has timeout: int = 0;
    has baseline: str = "";

    can start with Baseline entry {
        self.baseline = here.name;
        gate = "accuracy DISABLED (Gaussian posterior has no samples)" if not here.accuracy_supported else "accuracy enabled";
        print(f"auditing baseline {self.baseline}: {gate}");
        visit [->:Supports:->];
    }

    can audit with Family entry {
        print(f"family {here.name}:");
        visit [->:Supports:->];
    }

    can tally with Cell entry {
        if here.status == "ok" { self.ok += 1; }
        elif here.status == "timeout" { self.timeout += 1; }
        else { self.not_supported += 1; }

        verdict = "OK" if here.status == "ok" else here.status.upper();
        anomaly = "";
        if here.metric == "accuracy" and here.status == "not_supported" {
            anomaly = "  <-- no distributional accuracy: paper has no baseline";
        }
        if here.status == "ok" and here.seconds <= 1.3 and here.n_nodes >= 1000 {
            anomaly = "  <-- timing anomaly: size-independent, GP may not be running";
        }
        print(f"  n={here.n_nodes} {here.metric}: {verdict} ({here.seconds}s){anomaly}");
    }

    can finish with Cell exit {
        visit [-->] else { disengage; }
    }
}

with entry {
    gp = Baseline(
        name="gpytorch-gp-predict",
        accuracy_supported=False,
        supported=["continuous_lg", "continuous_nongauss"],
    );

    clg = Family(name="continuous_lg");
    cng = Family(name="continuous_nongauss");

    gp +>:Supports:+> clg;
    gp +>:Supports:+> cng;

    # continuous_lg: exact GP cost grows cubically, accuracy gated off,
    # timeouts at n>=500.
    clg +>:Supports:+> Cell(family="continuous_lg", n_nodes=10, metric="total_time_s", status="ok", seconds=1.13);
    clg +>:Supports:+> Cell(family="continuous_lg", n_nodes=100, metric="total_time_s", status="ok", seconds=1.61);
    clg +>:Supports:+> Cell(family="continuous_lg", n_nodes=500, metric="total_time_s", status="ok", seconds=2.39);
    clg +>:Supports:+> Cell(family="continuous_lg", n_nodes=1000, metric="total_time_s", status="timeout");
    clg +>:Supports:+> Cell(family="continuous_lg", n_nodes=10, metric="accuracy", status="not_supported");

    # continuous_nongauss: finishes fast at ALL sizes -- suspicious.
    cng +>:Supports:+> Cell(family="continuous_nongauss", n_nodes=10, metric="total_time_s", status="ok", seconds=0.9);
    cng +>:Supports:+> Cell(family="continuous_nongauss", n_nodes=1000, metric="total_time_s", status="ok", seconds=1.26);
    cng +>:Supports:+> Cell(family="continuous_nongauss", n_nodes=1000, metric="accuracy", status="not_supported");

    root spawn gp;
}

"""Cancellation propagation: terminating a parent task walks delegated children via typed edges, applying SIGTERM-then-kill policy with bounded retries and marking unreachable children abandoned."""

node Task {
    has task_id: str = "";
    has skill_id: str = "";
    has status: str = "running";  # running | terminated | abandoned
    has ceiling_secs: int = 900;
}

edge Delegates { }

walker Terminator {
    has parent_task_id: str = "";
    has max_depth: int = 5;
    has propagation_attempts: int = 3;
    has orphan_descendants: int = 0;
    has graph_depth: int = 0;

    can start with Root entry {
        target = [root -->][0];
        if target is None {
            print("no graph to sweep");
            disengage;
        }
        visit [-->];
    }

    # Cascade: terminate the parent, then propagate cancellation to
    # every delegated child, depth-bounded (cycle/depth policy kept explicit).
    can propagate with Task entry {
        depth = self.graph_depth + 1;
        if depth > self.max_depth {
            print(f"[ORPHAN] {here.task_id} beyond propagation depth {self.max_depth}");
            self.orphan_descendants += 1;
            disengage;
        }
        self.graph_depth = depth;
        if here.status == "running" {
            here.status = "terminated";
            print(f"[TERMINATED] {here.task_id} (skill={here.skill_id}, ceiling={here.ceiling_secs}s) "
                  f"at depth {depth}, envelope quality='terminated'");
        } else {
            print(f"[SKIP] {here.task_id} already {here.status}");
        }
        visit [->:Delegates:->] else {
            reason = "leaf" if self.orphan_descendants == 0 else "with orphans";
            print(f"[AUDIT] event_type='task_terminated' terminator={self.parent_task_id} "
                  f"attempts={self.propagation_attempts} orphans={self.orphan_descendants} depth={depth} ({reason})");
        }
    }
}

with entry {
    parent = Task(task_id="t-parent", skill_id="orchestrator", ceiling_secs=900);
    child_a = Task(task_id="t-a", skill_id="summarize", ceiling_secs=24 * 3600);
    child_b = Task(task_id="t-b", skill_id="translate", ceiling_secs=900);
    grandchild = Task(task_id="t-gc", skill_id="index", ceiling_secs=900);

    root ++> parent;
    parent +>:Delegates:+> child_a;
    parent +>:Delegates:+> child_b;
    child_a +>:Delegates:+> grandchild;

    root spawn Terminator(parent_task_id="t-parent", max_depth=5);
}

"""Rag.NET graph store: model relationship traversal and the repeated
unindexed neighbor lookups the issue complains about, with an explicit
cycle guard preserved as domain logic."""

node GraphStore {
    has name: str = "";
    has indexed: bool = False;
}

node Chunk {
    has title: str = "";
    has pagerank_weight: float = 0.0;
}

edge StoredIn { }
edge RelatesTo {
    has rel_type: str = "";
}

walker Ingestor {
    can start with Root entry {
        visit [->:StoredIn:->];
    }

    can seed with Chunk entry {
        visit [->:RelatesTo:->];
    }

    can link with Chunk entry {
        visit [->:RelatesTo:->] else { disengage; }
    }
}

# The traversal the issue complains about: every GetNeighborsAsync call
# from each chunk scans all relationships (no usable index on the filter
# columns), so cost is O(lookups x relationships). Cycle guard is explicit
# because walkers do not dedupe on cyclic graphs.
walker NeighborScan {
    has lookups: int = 0;
    has visited_ids: list = [];
    has reachable: list = [];

    can start with Root entry {
        visit [->:StoredIn:->];
    }

    can measure with GraphStore entry {
        print(f"store {here.name}: indexed={here.indexed}");
        visit [->:StoredIn:->];
    }

    can probe with Chunk entry {
        if here in self.visited_ids {
            disengage;
        }
        self.visited_ids.append(here);
        self.lookups += 1;
        for rel in [here->:RelatesTo:->] {
            self.reachable.append(rel);
        }
        visit [->:RelatesTo:->] else { disengage; }
    }
}

with entry {
    store = GraphStore(name="SqliteGraphStore(:memory:)", indexed=False);
    a = Chunk(title="doc1#0", pagerank_weight=0.0);
    b = Chunk(title="doc1#1", pagerank_weight=0.0);
    c = Chunk(title="doc2#0", pagerank_weight=0.0);
    root +>:StoredIn:+> store;
    store +>:StoredIn:+> a;
    a +>:RelatesTo(rel_type="same_doc"):+> b;
    b +>:RelatesTo(rel_type="citation"):+> c;
    c +>:RelatesTo(rel_type="backref"):+> a;  # cyclic graph

    root spawn Ingestor();
    scan = NeighborScan();
    store spawn scan;
    print(f"lookups={scan.lookups} reachable={len(scan.reachable)} "
          f"(each lookup is a full scan of an unindexed relationships table; "
