}

"""Hierarchical library: reject circular reference insertion and make recursive
operations terminate on pre-existing cycles (issue #297)."""

node Cell {
    has name: str = "";
}

edge Sub { }

# Recursive search walker: does the child's subtree reach `target`?
walker PathFinder {
    has target: str = "";
    has found: str = "";
    has seen: list[str] = list();

    can search with Cell entry {
        if here.name == self.target {
            names = self.seen + [here.name];
            self.found = " -> ".join(names);
            disengage;
        }
        if here.name in self.seen {
            disengage;
        }
        self.seen.append(here.name);
        visit [->:Sub:->];
    }
}

# Public API: checked reference insertion — atomic, returns error path on cycle.
def safe_link(parent: Cell, child: Cell) -> str | None {
    if parent == child {
        return f"direct cycle: {parent.name} -> {child.name}";
    }
    pf = PathFinder(target=parent.name);
    child spawn pf;
    if pf.found != "" {
        return f"would create cycle: {child.name} -> {pf.found}";
    }
    parent +>:Sub:+> child;
    return None;
}

walker Builder {
    can start with Root entry {
        visit [-->];
    }

    can build with Cell entry {
        visit [->:Sub:->];
    }
}

# Recursive public operation with cycle guard so it terminates on bad fixtures.
walker Flattener {
    has flattened: list[str] = list();
    has error: str = "";
    has seen: list[str] = list();

    can start with Root entry {
        visit [-->];
    }

    can flatten with Cell entry {
        if here.name in self.seen {
            self.error = f"circular reference detected at {here.name}";
            disengage;
        }
        self.seen.append(here.name);
        self.flattened.append(here.name);
        visit [->:Sub:->];
    }
}

with entry {
    top = Cell(name="TOP");
    mid = Cell(name="MID");
    leaf = Cell(name="LEAF");
    root ++> top;
    top +>:Sub:+> mid;
    mid +>:Sub:+> leaf;

    # Direct-cycle rejection.
    err_self = safe_link(leaf, leaf);
    print(f"self rejection: {err_self}");

    # Indirect-cycle rejection: leaf -> top would close the loop.
    err = safe_link(leaf, top);
    print(f"rejection: {err}");

    # Library unchanged after rejection: top still has only MID as child.
    kids = PathFinder(target="MID");
    top spawn kids;
    print(f"top still reaches MID: {kids.found != ''} — library unchanged");

    # Deliberately build a cyclic fixture to prove recursive ops terminate.
    leaf +>:Sub:+> mid;
    fl = Flattener();
    top spawn fl;
    if fl.error != "" {
        print(f"flatten aborted: {fl.error}");
        print(f"visited before abort: {fl.flattened}");
    } else {
        print(f"flattened: {fl.flattened}");
    }

    # A clean library still builds fine with checked insertion.
    extra = Cell(name="EXTRA");
    ok = safe_link(top, extra);
    print(f"second insertion error: {ok}");
}

