"""

node Map {
    has name: str = "";
}

node Thread {
    has title: str = "";
    has method: str = "";
    has blast_radius: int = 0;
}

node Decision {
    has question: str = "";
    has resolved: bool = False;
    has outcome: str = "";
}

edge Contains { }
edge Resolves { }
edge Blocks { }

walker Diagnoser {
    has visited: dict = {};
    has unresolved: int = 0;
    has max_depth: int = 10;

    can start with Map entry {
        print(f"Diagnosing map: {here.name}");
        self.visited[here] = True;
        visit [->:Contains:->];
    }

    can assess with Thread entry {
        if self.visited.get(here, False) {
            print(f"cycle guard: already assessed '{here.title}', disengaging");
            disengage;
        }
        self.visited[here] = True;
        print(f"thread '{here.title}' (method: {here.method}, blast radius: {here.blast_radius})");
        if here.blast_radius > 5 {
            print(f"  -> high context cost on '{here.title}': blast radius is a plausible creep cause");
        }
        visit [->:Resolves:->];
    }

    can check with Decision entry {
        if self.visited.get(here, False) {
            disengage;
        }
        self.visited[here] = True;
        status = "RESOLVED" if here.resolved else "BLOCKED";
        print(f"  decision [{status}] {here.question} -> {here.outcome}");
        if not here.resolved {
            self.unresolved += 1;
            visit [->:Blocks:->];
        }
    }

    can report with Map exit {
        print(f"diagnosis done: {self.unresolved} unresolved decision(s) blocking threads");
    }
}

with entry {
    m = Map(name="blast-radius-diagnosis");
    thread_a = Thread(title="Thread A: blast-radius cause", method="transcript mining + reasoning", blast_radius=8);
    thread_b = Thread(title="Thread B: graph-tool adoption", method="structured research", blast_radius=3);
    d_wiring = Decision(question="how to wire tool into to-spec/to-tickets/implement", resolved=False, outcome="unspecified until both threads resolve");
    d_alt_fix = Decision(question="alternative fix path if cause is not blast radius", resolved=False, outcome="blocked on Thread A outcome");
    d_scope = Decision(question="source-only vs wider graph scope", resolved=False, outcome="settled by Thread B research");
    d_star = Decision(question="trust candidate graph tools", resolved=True, outcome="star counts unreliable; verify provenance first");

    m +>:Contains:+> thread_a;
    m +>:Contains:+> thread_b;
    thread_a +>:Resolves:+> d_wiring;
    thread_a +>:Resolves:+> d_alt_fix;
    thread_b +>:Resolves:+> d_scope;
    thread_b +>:Resolves:+> d_star;
    d_wiring +>:Blocks:+> thread_a;
    d_alt_fix +>:Blocks:+> thread_a;
    d_scope +>:Blocks:+> thread_b;

    root ++> m;
    root spawn Diagnoser(max_depth=10);
}

"""Benchmark registry for the gpytorch-gp-predict baseline.

Models the issue's registry: an applicability gate decides which
benchmark families a baseline supports, and a Cell node records per
(n_nodes, metric) outcomes. An Auditor walker traverses the registry's
support edges into family cells, reproducing the status breakdown and
flagging suspicious cells: accuracy not_supported while timing ran ok,
and timing anomalies where large graphs finish as fast as tiny ones.
"""

edge Supports { }

node Family {
    has name: str = "";
}

node Cell {
    has family: str = "";
    has n_nodes: int = 0;
    has metric: str = "";
    has status: str = "";      # ok | not_supported | timeout
    has seconds: float = 0.0;
}

node Baseline {
    has name: str = "";
    has accuracy_supported: bool = False;
    has supported: list[str] = [];
}

walker Auditor {
    has ok: int = 0;
    has not_supported: int = 0;
    has timeout: int = 0;
    has baseline: str = "";

    can start with Baseline entry {
        self.baseline = here.name;
        gate = "accuracy DISABLED (Gaussian posterior has no samples)" if not here.accuracy_supported else "accuracy enabled";
        print(f"auditing baseline {self.baseline}: {gate}");
        visit [->:Supports:->];
    }

    can audit with Family entry {
        print(f"family {here.name}:");
        visit [->:Supports:->];
    }

    can tally with Cell entry {
        if here.status == "ok" { self.ok += 1; }
        elif here.status == "timeout" { self.timeout += 1; }
        else { self.not_supported += 1; }

        verdict = "OK" if here.status == "ok" else here.status.upper();
        anomaly = "";
        if here.metric == "accuracy" and here.status == "not_supported" {
            anomaly = "  <-- no distributional accuracy: paper has no baseline";
        }
        if here.status == "ok" and here.seconds <= 1.3 and here.n_nodes >= 1000 {
            anomaly = "  <-- timing anomaly: size-independent, GP may not be running";
        }
        print(f"  n={here.n_nodes} {here.metric}: {verdict} ({here.seconds}s){anomaly}");
    }

    can finish with Cell exit {
        visit [-->] else { disengage; }
    }
}

with entry {
    gp = Baseline(
        name="gpytorch-gp-predict",
        accuracy_supported=False,
        supported=["continuous_lg", "continuous_nongauss"],
    );

    clg = Family(name="continuous_lg");
    cng = Family(name="continuous_nongauss");

    gp +>:Supports:+> clg;
    gp +>:Supports:+> cng;

    # continuous_lg: exact GP cost grows cubically, accuracy gated off,
    # timeouts at n>=500.
    clg +>:Supports:+> Cell(family="continuous_lg", n_nodes=10, metric="total_time_s", status="ok", seconds=1.13);
    clg +>:Supports:+> Cell(family="continuous_lg", n_nodes=100, metric="total_time_s", status="ok", seconds=1.61);
    clg +>:Supports:+> Cell(family="continuous_lg", n_nodes=500, metric="total_time_s", status="ok", seconds=2.39);
    clg +>:Supports:+> Cell(family="continuous_lg", n_nodes=1000, metric="total_time_s", status="timeout");
    clg +>:Supports:+> Cell(family="continuous_lg", n_nodes=10, metric="accuracy", status="not_supported");

    # continuous_nongauss: finishes fast at ALL sizes -- suspicious.
    cng +>:Supports:+> Cell(family="continuous_nongauss", n_nodes=10, metric="total_time_s", status="ok", seconds=0.9);
    cng +>:Supports:+> Cell(family="continuous_nongauss", n_nodes=1000, metric="total_time_s", status="ok", seconds=1.26);
    cng +>:Supports:+> Cell(family="continuous_nongauss", n_nodes=1000, metric="accuracy", status="not_supported");

    gp spawn Auditor();
}

"""Cancellation propagation: terminating a parent task walks delegated children via typed edges, applying SIGTERM-then-kill policy with bounded retries and marking unreachable children abandoned."""

node Task {
    has task_id: str = "";
    has skill_id: str = "";
    has status: str = "running";  # running | terminated | abandoned
    has ceiling_secs: int = 900;
    has graph_depth: int = 0;
}

edge Delegates { }

walker Terminator {
    has parent_task_id: str = "";
    has max_depth: int = 5;
    has propagation_attempts: int = 3;
    has orphan_descendants: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can propagate with Task entry {
        depth = here.graph_depth + 1;
        if depth > self.max_depth {
            print(f"[ORPHAN] {here.task_id} beyond propagation depth {self.max_depth}");
            here.status = "abandoned";
            self.orphan_descendants += 1;
            disengage;
        }
        here.graph_depth = depth;
        if here.status == "running" {
            here.status = "terminated";
            print(f"[TERMINATED] {here.task_id} (skill={here.skill_id}, ceiling={here.ceiling_secs}s) at depth {depth}, envelope quality='terminated'");
        } else {
            print(f"[SKIP] {here.task_id} already {here.status}");
        }
        visit [->:Delegates:->];
    }
}

walker Auditor {
    has parent_task_id: str = "";
    has propagation_attempts: int = 3;
    has orphan_descendants: int = 0;
    has total_depth: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Task entry {
        if here.graph_depth > self.total_depth {
            self.total_depth = here.graph_depth;
        }
        self.orphan_descendants += 1 if here.status == "abandoned" else 0;
        visit [->:Delegates:->];
    }

    can finish with Task exit {
        if self.total_depth > 0 and self.orphan_descendants >= 0 {
            print(f"[AUDIT] event_type='task_terminated' terminator={self.parent_task_id} "
                  f"attempts={self.propagation_attempts} orphans={self.orphan_descendants} "
                  f"depth={self.total_depth}");
            disengage;
        }
    }
}

with entry {
    parent = Task(task_id="t-parent", skill_id="orchestrator", ceiling_secs=900);
    child_a = Task(task_id="t-a", skill_id="summarize", ceiling_secs=24 * 3600);
    child_b = Task(task_id="t-b", skill_id="translate", ceiling_secs=900);
    grandchild = Task(task_id="t-gc", skill_id="index", ceiling_secs=900);

    root ++> parent;
    parent +>:Delegates:+> child_a;
    parent +>:Delegates:+> child_b;
    child_a +>:Delegates:+> grandchild;

    root spawn Terminator(parent_task_id="t-parent", max_depth=5);
    root spawn Auditor(parent_task_id="t-parent", propagation_attempts=3);
}

"""Kanban workspace rebind: cards materialize workspace paths from the Project
anchor; after set-primary, a fail-closed rebind walker rewires only
Project-derived paths, refusing running/claimed cards and overrides."""

node Project {
    has name: str = "";
    has primary_root: str = "";
}

node Board {
    has default_workdir: str = "";
}

node Card {
    has task_id: str = "";
    has workspace_path: str = "";
    has status: str = "queued";       # queued | running | done
    has claimed: bool = False;
    has explicit_override: bool = False;  # persisted provenance
    has retries: int = 0;
}

edge BelongsToProject { }
edge BelongsToBoard { }
edge DependsOn { }

walker RebindWorkspaces {
    has old_root: str = "";
    has new_root: str = "";
    has dry_run: bool = True;
    has changed: int = 0;
    has skipped: int = 0;
    has refused: int = 0;
    has seen: dict = {};

    can start with Root entry {
        visit [->:BelongsToProject:->] else { disengage; }
        visit [->:BelongsToProject:->];
    }

    can scan_project with Project entry {
        print(f"Project {here.name}: anchor {self.old_root} -> {self.new_root}");
        visit [-->];
    }

    can scan_board with Board entry {
        visit [-->];
    }

    def rewrite(path: str) -> str | None {
        if not path.startswith(self.old_root + "/") {
            return None;
        }
        suffix = path[len(self.old_root) + 1:];
        return self.new_root + "/" + suffix;
    }

    can rebind with Card entry {
        # explicit cycle guard (walker visitation does not dedupe)
        if here.task_id in self.seen {
            disengage;
        }
        self.seen[here.task_id] = True;

        if here.status == "running" or here.claimed or here.explicit_override {
            reason = "running/claimed" if (here.status == "running" or here.claimed) else "explicit override";
            print(f"REFUSED {here.task_id} ({reason})");
            self.refused += 1;
            return;
        }
        candidate = self.rewrite(here.workspace_path);
        if candidate is None {
            print(f"SKIP {here.task_id}: path {here.workspace_path} not derived from old anchor");
            self.skipped += 1;
            return;
        }
        if self.dry_run {
            print(f"DRY-RUN {here.task_id}: {here.workspace_path} -> {candidate}");
            self.changed += 1;
            return;
        }
        old_path = here.workspace_path;
        here.workspace_path = candidate;
        print(f"REBOUND {here.task_id}: {old_path} -> {here.workspace_path} (event appended)");
        self.changed += 1;
    }
}

walker Auditor {
    can start with Root entry {
        visit [-->];
    }
    can audit with Card entry {
        print(f"card {here.task_id}: {here.workspace_path} [{here.status}] retries={here.retries}");
        visit [->:DependsOn:->];
    }
}

with entry {
    proj = Project(name="hermes-agent", primary_root="C:/repo/wrapper");
    board = Board(default_workdir="C:/repo/wrapper");
    c1 = Card(task_id="T-001", workspace_path="C:/repo/wrapper/.worktrees/T-001");
    c2 = Card(task_id="T-002", workspace_path="C:/repo/wrapper/.worktrees/T-002", status="running");
    c3 = Card(task_id="T-003", workspace_path="C:/repo/wrapper/.worktrees/T-003");
    c4 = Card(task_id="T-004", workspace_path="C:/custom/T-004", explicit_override=True);
    proj +>:BelongsToProject:+> c1;
    proj +>:BelongsToProject:+> c2;
    proj +>:BelongsToProject:+> c3;
    board +>:BelongsToBoard:+> c3;
    board +>:BelongsToBoard:+> c4;
    c1 +>:DependsOn:+> c2;

    print("--- dry run: correct anchor set-primary to C:/repo/actual ---");
    root ++> proj ++> board;
    rb = RebindWorkspaces(old_root="C:/repo/wrapper", new_root="C:/repo/actual", dry_run=True);
    rb spawn proj;

    print("--- apply ---");
    apply = RebindWorkspaces(old_root="C:/repo/wrapper", new_root="C:/repo/actual", dry_run=False);
    apply spawn proj;
    print(f"changed={apply.changed} skipped={apply.skipped} refused={apply.refused}");

    print("--- audit card graph ---");
    root spawn Auditor();
}

"""Post-consolidate access-only recompute: a walker redoes each segment's
accessibility by checking reachability from the consolidated barrier set
downstream, reusing persisted streams instead of a full pipeline rebuild."""

node Segment {
    has seg_id: str = "";
    has habitat_km: float = 0.0;
    has accessible: bool = True;
    has mapping_code: str = "";
}

node Barrier {
    has barrier_id: str = "";
    has blocking: bool = True;
}

node Wsg {
    has wsg_id: str = "";
}

edge FlowsTo { }
edge Contains { }
edge Blocks { }

walker AccessRecomputer {
    has barrier_seen: list[str] = list();
    has recomputed: list[str] = list();

    def is_blocked_here() -> bool {
        for b in [here ->:Blocks:->] {
            if b.blocking { return True; }
        }
        return False;
    }

    can start with Root entry {
        visit [->:Contains:->];
    }

    can enter_wsg with Wsg entry {
        print(f"recomputing WSG {here.wsg_id} (access-only, no pipeline rebuild)");
        visit [->:Contains:->];
    }

    can sweep with Segment entry {
        # access-only recompute: re-derive accessibility from downstream
        # reachability over the consolidated barrier set, reusing the
        # persisted habitat values already on the segment.
        if self.is_blocked_here() {
            here.accessible = False;
            for s in [here ->:FlowsTo:->] {
                s.accessible = False;
            }
        }
        species = "token1" if here.habitat_km > 1.0 else "token2";
        here.mapping_code = species if here.accessible else "";
        self.recomputed.append(here.seg_id);
        visit [->:FlowsTo:->];
    }

    can note_barrier with Barrier entry {
        if here.barrier_id not in self.barrier_seen {
            self.barrier_seen.append(here.barrier_id);
            visit [->:FlowsTo:->];
        }
    }
}

with entry {
    # two WSGs whose pass-1 access was computed against incomplete barriers;
    # after consolidation, a blocking barrier sits downstream in another WSG.
    up = Wsg(wsg_id="FINA");
    down = Wsg(wsg_id="PARA");
    s1 = Segment(seg_id="10.0", habitat_km=2.4);
    s2 = Segment(seg_id="10.1", habitat_km=1.2);
    s3 = Segment(seg_id="20.0", habitat_km=0.8);
    root ++> up ++> s1 ++> s2;
    root ++> down ++> s3;

    # consolidated barrier set: blocking barrier between the two WSGs
    s2 +>:FlowsTo:+> s3;
    b = Barrier(barrier_id="B-77", blocking=True);
    s2 +>:Blocks:+> b;
    b +>:FlowsTo:+> s3;

    root spawn AccessRecomputer();

    print(f"recomputed segments: {AccessRecomputer().recomputed}");
}

"""Blast-radius map: walk threads and their blocked decisions to diagnose cause.

Models the two-decision map as a graph: a Map node connects via Contains
edges to Thread nodes (Thread A / Thread B), which connect via Resolves
edges to Decision nodes. Blocked decisions create Blocks edges back onto
threads, forming the "blast radius" a walker must traverse — with an
explicit visited-list cycle policy, since visit does not dedupe.
"""

node Map {
    has name: str = "";
}

node Thread {
    has title: str = "";
    has method: str = "";
    has blast_radius: int = 0;
}

node Decision {
    has question: str = "";
    has resolved: bool = False;
    has outcome: str = "";
}

edge Contains { }
edge Resolves { }
edge Blocks { }

walker Diagnoser {
    has seen: list = [];
    has unresolved: int = 0;

    def visited(n: object) -> bool {
        return n in self.seen;
    }

    can start with Map entry {
        print(f"Diagnosing map: {here.name}");
        self.seen.append(here);
        visit [->:Contains:->] else { disengage; }
    }

    can assess with Thread entry {
        if self.visited(here) {
            print(f"cycle guard: already assessed '{here.title}', skipping");
            return;
        }
        self.seen.append(here);
        print(f"thread '{here.title}' (method: {here.method}, blast radius: {here.blast_radius})");
        if here.blast_radius > 5 {
            print(f"  -> high context cost on '{here.title}': blast radius is a plausible creep cause");
        }
        visit [->:Resolves:->] else { return; }
    }

    can check with Decision entry {
        if self.visited(here) {
            return;
        }
        self.seen.append(here);
        status = "RESOLVED" if here.resolved else "BLOCKED";
        print(f"  decision [{status}] {here.question} -> {here.outcome}");
        if not here.resolved {
            self.unresolved += 1;
            visit [->:Blocks:->] else { return; }
        }
    }

    can report with Map exit {
        print(f"diagnosis done: {self.unresolved} unresolved decision(s) blocking threads");
    }
}

with entry {
    m = Map(name="blast-radius-diagnosis");
    thread_a = Thread(title="Thread A: blast-radius cause", method="transcript mining + reasoning", blast_radius=8);
    thread_b = Thread(title="Thread B: graph-tool adoption", method="structured research", blast_radius=3);
    d_wiring = Decision(question="how to wire tool into to-spec/to-tickets/implement", resolved=False, outcome="unspecified until both threads resolve");
    d_alt_fix = Decision(question="alternative fix path if cause is not blast radius", resolved=False, outcome="blocked on Thread A outcome");
    d_scope = Decision(question="source-only vs wider graph scope", resolved=False, outcome="settled by Thread B research");
    d_star = Decision(question="trust candidate graph tools", resolved=True, outcome="star counts unreliable; verify provenance first");

    m +>:Contains:+> thread_a;
    m +>:Contains:+> thread_b;
    thread_a +>:Resolves:+> d_wiring;
    thread_a +>:Resolves:+> d_alt_fix;
    thread_b +>:Resolves:+> d_scope;
    thread_b +>:Resolves:+> d_star;
    d_wiring +>:Blocks:+> thread_a;
    d_alt_fix +>:Blocks:+> thread_a;
    d_scope +>:Blocks:+> thread_b;

    root ++> m;
    root spawn Diagnoser();
}

