# The traversal the issue complains about: every GetNeighborsAsync call
# scans relationships with no usable index, so cost is O(lookups x rows).
# Cycle guard is explicit because walkers do not dedupe on cyclic graphs.
walker NeighborScan {
    has lookups: int = 0;
    has visited_ids: list = [];
    has reachable: list = [];

    can start with Root entry {
        visit [->:StoredIn:->];
    }

    can measure with GraphStore entry {
        print(f"store {here.name}: indexed={here.indexed}");
        visit [->:StoredIn:->];
    }

    can probe with Chunk entry {
        if here in self.visited_ids {
            disengage;
        }
        self.visited_ids.append(here);
        self.lookups += 1;
        for rel in [here->:RelatesTo:->] {
            self.reachable.append(rel);
        }
        visit [->:RelatesTo:->] else { disengage; }
    }
}

