"""Blast-radius map: walk threads and their blocked decisions to diagnose cause.

Models the two-decision map as a graph: a Map node connects via Contains
edges to Thread nodes (Thread A / Thread B), which connect via Resolves
edges to Decision nodes. Blocked decisions create Blocks edges back onto
threads, forming the "blast radius" a walker must traverse — with an
explicit visited-list cycle policy, since visit does not dedupe.
"""

node Map {
    has name: str = "";
}

node Thread {
    has title: str = "";
    has method: str = "";
    has blast_radius: int = 0;
}

node Decision {
    has question: str = "";
    has resolved: bool = False;
    has outcome: str = "";
}

edge Contains { }
edge Resolves { }
edge Blocks { }

walker Diagnoser {
    has seen: list = [];
    has unresolved: int = 0;

    def visited(n: object) -> bool {
        return n in self.seen;
    }

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can begin with Map entry {
        if self.visited(here) {
            disengage;
        }
        self.seen.append(here);
        print(f"Diagnosing map: {here.name}");
        visit [->:Contains:->];
    }

    can assess with Thread entry {
        if self.visited(here) {
            print(f"cycle guard: already assessed '{here.title}', skipping");
            disengage;
        }
        self.seen.append(here);
        print(f"thread '{here.title}' (method: {here.method}, blast radius: {here.blast_radius})");
        if here.blast_radius > 5 {
            print(f"  -> high context cost on '{here.title}': blast radius is a plausible creep cause");
        }
        visit [->:Resolves:->];
    }

    can check with Decision entry {
        if self.visited(here) {
            disengage;
        }
        self.seen.append(here);
        status = "RESOLVED" if here.resolved else "BLOCKED";
        print(f"  decision [{status}] {here.question} -> {here.outcome}");
        if not here.resolved {
            self.unresolved += 1;
            visit [->:Blocks:->];
        }
    }

    can report with Thread exit {
        print(f"  thread '{here.title}' finished: {self.unresolved} unresolved decision(s) so far");
    }
}

with entry {
    m = Map(name="blast-radius-diagnosis");
    thread_a = Thread(title="Thread A: blast-radius cause", method="transcript mining + reasoning", blast_radius=8);
    thread_b = Thread(title="Thread B: graph-tool adoption", method="structured research", blast_radius=3);
    d_wiring = Decision(question="how to wire tool into to-spec/to-tickets/implement", resolved=False, outcome="unspecified until both threads resolve");
    d_alt_fix = Decision(question="alternative fix path if cause is not blast radius", resolved=False, outcome="blocked on Thread A outcome");
    d_scope = Decision(question="source-only vs wider graph scope", resolved=False, outcome="settled by Thread B research");
    d_star = Decision(question="trust candidate graph tools", resolved=True, outcome="star counts unreliable; verify provenance first");

    m +>:Contains:+> thread_a;
    m +>:Contains:+> thread_b;
    thread_a +>:Resolves:+> d_wiring;
    thread_a +>:Resolves:+> d_alt_fix;
    thread_b +>:Resolves:+> d_scope;
    thread_b +>:Resolves:+> d_star;
    d_wiring +>:Blocks:+> thread_a;
    d_alt_fix +>:Blocks:+> thread_a;
    d_scope +>:Blocks:+> thread_b;

    root ++> m;
    root spawn Diagnoser();
}

