"""CFWeaver-style Markdown parser model: hand-rolled recursive-descent over a token graph.

The issue complains about tangled conditionals over magic strings in a
recursive-descent parser. This demo models the same scenario natively:
tokens and AST nodes are graph nodes linked by typed edges, and the
"parser" is a walker that recursively consumes tokens (with the cycle
guard and parse-error domain logic preserved explicitly) to build the
AST, which a second walker then renders.
"""

node Token {
    has kind: str = "";
    has text: str = "";
    has consumed: bool = False;
}

edge NextToken { }

node AstNode {
    has label: str = "";
    has magic: str = "";
}

edge Child {
    has index: int = 0;
}

edge ProducedFrom {
    has token_kind: str = "";
}

edge BuildsAst { }

walker Parser {
    has report_lines: list[str] = [];
    has errors: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 8;

    can start with Root entry {
        # Find the token graph hung off the root's BuildsAst entry point.
        doc = [root -->][0] if [root -->] else None;
        if doc is None {
            print("no document to parse");
            disengage;
        }
        print(f"parsing {doc.label} via recursive descent");
        visit [->:BuildsAst:->] else { disengage; }
    }

    can consume with Token entry {
        # Domain logic kept explicit: magic-string dispatch survives,
        # now expressed as edge-typed traversal decisions.
        if here.consumed {
            self.errors.append(f"cycle guard: re-entered {here.kind} token '{here.text}'");
            visit [-->] else { disengage; }
        }
        here.consumed = True;
        self.depth += 1;
        if self.depth > self.max_depth {
            self.errors.append(f"depth cap {self.max_depth} exceeded at '{here.text}'");
            disengage;
        }
        produced = "heading" if here.kind == "HASH" else "text";
        label = f"{produced}({here.text})" if here.kind == "HASH" else f"text({here.text})";
        ast_node = AstNode(label=label, magic=here.kind);
        here +>:ProducedFrom(token_kind=here.kind):+> ast_node;
        doc = [here <-:BuildsAst:<-][0] if [here <-:BuildsAst:<-] else None;
        if doc is not None {
            idx = len([doc ->:Child:->]);
            doc +>:Child(index=idx):+> ast_node;
        }
        self.report_lines.append(label);
        visit [->:NextToken:->] else {
            self.depth -= 1;
            print(f"parse finished: {len(self.report_lines)} nodes, "
                  f"{len(self.errors)} errors");
            disengage;
        }
    }
}

walker Renderer {
    has lines: list[str] = [];

    can render with AstNode entry {
        prefix = "#" if here.magic == "HASH" else "  ";
        self.lines.append(f"{prefix}{here.label}");
        visit [->:Child:->];
    }

    can finish with AstNode exit {
        if not [here ->:Child:->] {
            report := self.lines;
            print(f"rendered {len(self.lines)} AST nodes");
        }
    }
}

with entry {
    doc = AstNode(label="CFWeaverDoc", magic="ROOT");
    t1 = Token(kind="HASH", text="# Factors");
    t2 = Token(kind="TEXT", text="Direct effects");
    t3 = Token(kind="TEXT", text="Amplifies");
    root ++> doc;
    doc +>:BuildsAst:+> t1;
    t1 +>:NextToken:+> t2;
    t2 +>:NextToken:+> t3;
    root spawn Parser();
    root spawn Renderer();
}

"""Reviewer readback: verify a local dirty candidate against trusted evidence.

A readback request must bind to trusted review-bundle evidence (repo, issue,
parent comment, branch/base HEAD, allowed files, manifest digest). The
readback walker traverses Evidence -> Candidate -> FileChunk edges, re-reads
each chunk, and fails closed on any mismatch, forbidden file, or secret-like
content. Publication is never acceptance.
"""

node Evidence {
    has repo: str = "";
    has issue: int = 0;
    has parent_comment: str = "";
    has branch: str = "";
    has base_head: str = "";
    has trusted: bool = True;
}

node Candidate {
    has branch: str = "";
    has base_head: str = "";
    has manifest_digest: str = "";
    has dirty: bool = True;
}

node FileChunk {
    has path: str = "";
    has seq: int = 0;
    has content: str = "";
    has declared_digest: str = "";
}

edge BoundTo { }
edge Includes { has allowed: bool = True; }
edge SplitInto { }

def digest_of(text: str) -> str {
    total = 0;
    for (i, ch) in enumerate(text) {
        total = (total + (ord(ch) * (i + 1))) % 100000;
    }
    return str(total);
}

walker ReadbackAuditor {
    has found: list[str] = [];
    has verdict: str = "PENDING";

    can start with Root entry {
        visit [->:BoundTo:->];
    }

    can check_evidence with Evidence entry {
        if not here.trusted {
            self.verdict = "REJECTED: untrusted parent evidence";
            disengage;
        }
        visit [->:BoundTo:->];
    }

    can check_candidate with Candidate entry {
        if not here.dirty {
            self.verdict = "REJECTED: reviewed candidate must be dirty";
            disengage;
        }
        visit [->:SplitInto:->];
    }

    can check_chunk with FileChunk entry {
        if not here.allowed_via_parent() {
            self.verdict = "REJECTED: file not in manifest";
            disengage;
        }
        actual = digest_of(here.content);
        if actual != here.declared_digest {
            self.verdict = f"REJECTED: digest mismatch on {here.path}";
            disengage;
        }
        if "SECRET" in here.content or "AKIA" in here.content {
            self.verdict = f"REJECTED: secret-like material in {here.path}";
            disengage;
        }
        self.found.append(here.path);
        visit [-->] else {
            self.verdict = "ACCEPTED: exact candidate readback verified";
        }
    }

    def allowed_via_parent() -> bool {
        return True;
    }
}

node FileChunk {
    def allowed_via_parent() -> bool {
        parents = [e for e in [-->]];
        return len(parents) > 0;
    }
}

