    can probe with Chunk entry {
        if here.title in self.visited_ids {
            disengage;
        }
        self.visited_ids.append(here.title);
        self.lookups += 1;
        for rel in [here->:RelatesTo:->] {
            self.reachable.append(rel.rel_type);
        }
        visit [->:RelatesTo:->] else { disengage; }
    }
}

