"""Kanban workspace rebind: cards materialize workspace paths from the Project
anchor; after set-primary, a fail-closed rebind walker rewires only
Project-derived paths, refusing running/claimed cards and explicit overrides."""

edge BelongsToProject {
    has linked: str = "";
}

edge BelongsToBoard {
    has linked: str = "";
}

edge DependsOn {
    has since: str = "";
}

node Project {
    has name: str = "";
    has primary_root: str = "";
}

node Board {
    has default_workdir: str = "";
}

node Card {
    has task_id: str = "";
    has workspace_path: str = "";
    has status: str = "queued";
    has claimed: bool = False;
    has explicit_override: bool = False;
    has retries: int = 0;
}

walker RebindWorkspaces {
    has old_root: str = "";
    has new_root: str = "";
    has dry_run: bool = True;
    has changed: int = 0;
    has skipped: int = 0;
    has refused: int = 0;
    has seen: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can scan_project with Project entry {
        print(f"Project {here.name}: anchor {self.old_root} -> {self.new_root}");
        visit [->:BelongsToProject:->] else { disengage; }
    }

    def rewrite(path: str) -> str | None {
        if not path.startswith(self.old_root + "/") {
            return None;
        }
        suffix = path[len(self.old_root) + 1:];
        return self.new_root + "/" + suffix;
    }

    can rebind with Card entry {
        if here.task_id in self.seen {
            return;
        }
        self.seen[here.task_id] = True;

        if here.status == "running" or here.claimed or here.explicit_override {
            blocked = "running/claimed" if (here.status == "running" or here.claimed) else "explicit override";
            print(f"REFUSED {here.task_id} ({blocked})");
            self.refused += 1;
            return;
        }
        candidate = self.rewrite(here.workspace_path);
        if candidate is None {
            print(f"SKIP {here.task_id}: path {here.workspace_path} not derived from old anchor");
            self.skipped += 1;
            return;
        }
        if self.dry_run {
            print(f"DRY-RUN {here.task_id}: {here.workspace_path} -> {candidate}");
            self.changed += 1;
            return;
        }
        old_path = here.workspace_path;
        here.workspace_path = candidate;
        print(f"REBOUND {here.task_id}: {old_path} -> {here.workspace_path} (event appended)");
        self.changed += 1;
    }
}

walker Auditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Card entry {
        print(f"card {here.task_id}: {here.workspace_path} [{here.status}] retries={here.retries}");
        visit [->:DependsOn:->];
    }
}

with entry {
    proj = Project(name="hermes-agent", primary_root="C:/repo/wrapper");
    board = Board(default_workdir="C:/repo/wrapper");
    c1 = Card(task_id="T-001", workspace_path="C:/repo/wrapper/.worktrees/T-001");
    c2 = Card(task_id="T-002", workspace_path="C:/repo/wrapper/.worktrees/T-002", status="running");
    c3 = Card(task_id="T-003", workspace_path="C:/repo/wrapper/.worktrees/T-003");
    c4 = Card(task_id="T-004", workspace_path="C:/custom/T-004", explicit_override=True);

    proj +>:BelongsToProject:+> c1;
    proj +>:BelongsToProject:+> c2;
    proj +>:BelongsToProject:+> c3;
    board +>:BelongsToBoard:+> c3;
    board +>:BelongsToBoard:+> c4;
    c1 +>:DependsOn:+> c2;

    root ++> proj ++> board;

    print("--- dry run: correct anchor set-primary to C:/repo/actual ---");
    rb = RebindWorkspaces(old_root="C:/repo/wrapper", new_root="C:/repo/actual", dry_run=True);
    rb spawn proj;

    print("--- apply ---");
    apply_pass = RebindWorkspaces(old_root="C:/repo/wrapper", new_root="C:/repo/actual", dry_run=False);
    apply_pass spawn proj;
    print(f"changed={apply_pass.changed} skipped={apply_pass.skipped} refused={apply_pass.refused}");

    print("--- audit card graph ---");
    root spawn Auditor();
}

"""CFWeaver-style Markdown parser model: hand-rolled recursive-descent over a token graph.

The issue complains about tangled conditionals over magic strings in a
recursive-descent parser. This demo models the same scenario natively:
tokens and AST nodes are graph nodes linked by typed edges, and the
"parser" is a walker that recursively consumes tokens (with the cycle
guard and parse-error domain logic preserved explicitly) to build the
AST, which a second walker then renders.
"""

node Token {
    has kind: str = "";
    has text: str = "";
    has consumed: bool = False;
}

edge NextToken { }

node AstNode {
    has label: str = "";
    has magic: str = "";
}

edge Child {
    has index: int = 0;
}

edge ProducedFrom {
    has token_kind: str = "";
}

edge BuildsAst { }

walker Parser {
    has report_lines: list[str] = [];
    has errors: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 8;

    can start with Root entry {
        # Find the token graph hung off the root's BuildsAst entry point.
        docs = [root -->];
        if not docs {
            print("no document to parse");
            disengage;
        }
        doc = docs[0];
        print(f"parsing {doc.label} via recursive descent");
        visit [->:BuildsAst:->] else { disengage; }
    }

    can consume with Token entry {
        # Domain logic kept explicit: magic-string dispatch survives,
        # now expressed as edge-typed traversal decisions.
        if here.consumed {
            self.errors.append(f"cycle guard: re-entered {here.kind} token '{here.text}'");
        } else {
            here.consumed = True;
            self.depth += 1;
            if self.depth > self.max_depth {
                self.errors.append(f"depth cap {self.max_depth} exceeded at '{here.text}'");
                disengage;
            }
            label = f"heading({here.text})" if here.kind == "HASH" else f"text({here.text})";
            ast_node = AstNode(label=label, magic=here.kind);
            here +>:ProducedFrom(token_kind=here.kind):+> ast_node;
            back = [here <-:BuildsAst:<-];
            if back {
                doc = back[0];
                idx = len([doc ->:Child:->]);
                doc +>:Child(index=idx):+> ast_node;
            }
            self.report_lines.append(label);
        }
        visit [->:NextToken:->] else {
            print(f"parse finished: {len(self.report_lines)} nodes, "
                  f"{len(self.errors)} errors");
            disengage;
        }
    }
}

walker Renderer {
    has lines: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can render with AstNode entry {
        prefix = "#" if here.magic == "HASH" else "  ";
        self.lines.append(f"{prefix}{here.label}");
        visit [->:Child:->] else { disengage; }
    }
}

with entry {
    doc = AstNode(label="CFWeaverDoc", magic="ROOT");
    t1 = Token(kind="HASH", text="# Factors");
    t2 = Token(kind="TEXT", text="Direct effects");
    t3 = Token(kind="TEXT", text="Amplifies");
    root ++> doc;
    doc +>:BuildsAst:+> t1;
    t1 +>:NextToken:+> t2;
    t2 +>:NextToken:+> t3;
    root spawn Parser();
    root spawn Renderer();
    print("render complete");
}

"""Reviewer readback: verify a local dirty candidate against trusted evidence.

A readback request must bind to trusted review-bundle evidence (repo, issue,
parent comment, branch/base HEAD, allowed files, manifest digest). The
readback walker traverses Evidence -> Candidate -> FileChunk edges, re-reads
each chunk, and fails closed on any mismatch, forbidden file, or secret-like
content. Publication is never acceptance.
"""

node Evidence {
    has repo: str = "";
    has issue: int = 0;
    has parent_comment: str = "";
    has branch: str = "";
    has base_head: str = "";
    has trusted: bool = True;
}

node Candidate {
    has branch: str = "";
    has base_head: str = "";
    has manifest_digest: str = "";
    has dirty: bool = True;
}

node FileChunk {
    has path: str = "";
    has seq: int = 0;
    has content: str = "";
    has declared_digest: str = "";

    def allowed_via_parent() -> bool {
        return len([-->]) > 0;
    }
}

edge BoundTo { }
edge Includes { has allowed: bool = True; }
edge SplitInto { }

def digest_of(text: str) -> str {
    total = 0;
    for (i, ch) in enumerate(text) {
        total = (total + (ord(ch) * (i + 1))) % 100000;
    }
    return str(total);
}

walker ReadbackAuditor {
    has found: list[str] = [];
    has verdict: str = "PENDING";

    can start with Root entry {
        visit [->:BoundTo:->];
    }

    can check_evidence with Evidence entry {
        if not here.trusted {
            self.verdict = "REJECTED: untrusted parent evidence";
            disengage;
        }
        visit [->:BoundTo:->];
    }

    can check_candidate with Candidate entry {
        if not here.dirty {
            self.verdict = "REJECTED: reviewed candidate must be dirty";
            disengage;
        }
        visit [->:SplitInto:->];
    }

    can check_chunk with FileChunk entry {
        if not here.allowed_via_parent() {
            self.verdict = "REJECTED: file not in manifest";
            disengage;
        }
        actual = digest_of(here.content);
        if actual != here.declared_digest {
            self.verdict = f"REJECTED: digest mismatch on {here.path}";
            disengage;
        }
        if "SECRET" in here.content or "AKIA" in here.content {
            self.verdict = f"REJECTED: secret-like material in {here.path}";
            disengage;
        }
        self.found.append(here.path);
        visit [-->] else {
            self.verdict = "ACCEPTED: exact candidate readback verified";
        }
    }
}

