    # Trusted review-bundle evidence from #284, bound to the dirty candidate.
    ev = Evidence(repo="HarryWhite-TW/local-ai-workbench", issue=284,
                  parent_comment="5394902606", branch="feat/readback",
                  base_head="abc123", trusted=True);
    cand = Candidate(branch="feat/readback", base_head="abc123",
                     manifest_digest="m1");
    f1 = FileChunk(path="bridge.py", seq=0, content="handler glue",
                   declared_digest=digest_of("handler glue"));
    f2 = FileChunk(path="runner.py", seq=1, content="bounded runner patch",
                   declared_digest=digest_of("bounded runner patch"));

    root +>:BoundTo:+> ev;
    ev +>:BoundTo:+> cand;
    cand +>:Includes(allowed=True):+> f1;
    cand +>:Includes(allowed=True):+> f2;
    cand +>:SplitInto:+> f1;
    cand +>:SplitInto:+> f2;

    audit = ReadbackAuditor();
    root spawn audit;
    print(f"readback files={audit.found} verdict={audit.verdict}");

