"""Single-WSG downstream-state guard: fail loud when downstream dams aren't persisted.

Runs a WSG DS-first; before computing access it walks downstream via typed
DrainsTo edges and verifies every downstream group holding a dam barrier is
already persisted. A missing persistence is an error, not a silent wrong answer.
"""

node WSG {
    has name: str = "";
    has persisted: bool = False;
}

node Dam {
    has barrier_id: str = "";
}

edge DrainsTo { }
edge HasBarrier { }

walker DownstreamGuard {
    has target: str = "";
    has visited: dict = {};

    can start with Root entry {
        visit [->:DrainsTo:->];
    }

    can check with WSG entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited[here.name] = True;
        if here.name == self.target {
            print(f"computing access for {here.name}");
        } else if not here.persisted {
            dam_count = 0;
            for d in [here->:HasBarrier:->] {
                dam_count += 1;
            }
            if dam_count > 0 {
                print(f"GUARD FAIL: downstream group {here.name} has {dam_count} "
                      f"dam barrier(s) but is not persisted; access would be wrong");
                disengage;
            } else {
                print(f"downstream {here.name} not persisted but barrier-free, ok");
            }
        } else {
            print(f"downstream {here.name} persisted, ok");
        }
        visit [->:DrainsTo:->] else { disengage; }
    }
}

walker Audit {
    can start with Root entry {
        visit [-->];
    }
    can note with WSG entry {
        state = "persisted" if here.persisted else "NOT persisted";
        print(f"{here.name}: {state}");
        visit [-->] else { disengage; }
    }
}

with entry {
    lske = WSG(name="LSKE", persisted=True);
    kisp = WSG(name="KISP", persisted=False);
    klum = WSG(name="KLUM", persisted=True);
    bulk = WSG(name="BULK", persisted=False);

    # BULK drains to KLUM, KISP, LSKE (DS closure)
    bulk +>:DrainsTo:+> klum;
    klum +>:DrainsTo:+> kisp;
    kisp +>:DrainsTo:+> lske;

    klum +>:HasBarrier(barrier_id="D-101"):+> Dam(barrier_id="D-101");

    root ++> bulk;
    root spawn DownstreamGuard(target="BULK");
    root spawn Audit();
}

