"""Configurable call-graph precision: walk callee edges from roots with an
explicit cycle guard (walkers have no built-in once-per-node visitation),
collect reachable functions, and report soundness/cost per precision level."""

node Function {
    has name: str = "";
    has is_stub: bool = False;  # incomplete code: body unknown
}

edge Calls {
    has through_stub: bool = False;  # approximation: call resolved via stub
}

walker CallGraphAnalyzer {
    has precision: str = "fast";       # "fast" | "precise"
    has visited: dict = {};            # explicit cycle guard (domain logic)
    has reachable: list = [];
    has approximated: list = [];
    has cycle_detected: bool = False;

    def include(node: Function) -> bool {
        # precise: sound, follows even stub-resolved calls
        # fast: cheap, skips approximated edges
        if self.precision == "precise" {
            return True;
        }
        return not node.is_stub;
    }

    can start with Root entry {
        visit [-->];
    }

    can analyze with Function entry {
        if here.name in self.visited {
            self.cycle_detected = True;
            disengage;
        }
        self.visited[here.name] = True;
        self.reachable.append(here.name);
        if here.is_stub {
            self.approximated.append(here.name);
        }
        for edge in here -->:Calls: {
            target = edge -->;
            if target and self.include(target) {
                visit [->:Calls:->];
            }
        }
    }
}

with entry {
    # caller -> callee graph, including a recursion cycle and a stub call
    main = Function(name="main");
    parse = Function(name="parse");
    lookup = Function(name="lookup");
    cache = Function(name="cacheMiss", is_stub=True);
    main ++> parse ++> lookup ++> cache ++> lookup;  # cycle: lookup <-> cache

    for level in ["fast", "precise"] {
        analyzer = CallGraphAnalyzer(precision=level);
        root spawn analyzer;
        mode = "sound (follows stubs)" if level == "precise" else "cheap (skips stubs)";
        print(f"precision={level} [{mode}] reachable={analyzer.reachable} "
              f"approximated={analyzer.approximated} cycle={analyzer.cycle_detected}");
    }
}

"""CFWeaver-style Markdown parser model: recursive descent over a token graph.

The issue complains about tangled conditionals over magic strings in a
recursive-descent parser. This demo models the scenario natively: tokens
and AST nodes are graph nodes linked by typed edges, and the parser is a
walker that recursively consumes tokens (with cycle guard and depth cap
preserved) to build the AST, which a second walker renders.
"""

edge NextToken { }
edge Child {
    has index: int = 0;
}
edge ProducedFrom {
    has token_kind: str = "";
}
edge BuildsAst { }

node Token {
    has kind: str = "";
    has text: str = "";
    has consumed: bool = False;
}

node AstNode {
    has label: str = "";
    has magic: str = "";
}

walker Parser {
    has report_lines: list[str] = [];
    has errors: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 8;

    can start with Root entry {
        docs = [root -->];
        if not docs {
            print("no document to parse");
            disengage;
        }
        doc = docs[0];
        print(f"parsing {doc.label} via recursive descent");
        visit [->:BuildsAst:->] else { disengage; }
    }

    can consume with Token entry {
        if here.consumed {
            self.errors.append(f"cycle guard: re-entered {here.kind} token '{here.text}'");
        } else {
            here.consumed = True;
            self.depth += 1;
            if self.depth > self.max_depth {
                self.errors.append(f"depth cap {self.max_depth} exceeded at '{here.text}'");
                disengage;
            }
            label = f"heading({here.text})" if here.kind == "HASH" else f"text({here.text})";
            ast_node = AstNode(label=label, magic=here.kind);
            here +>:ProducedFrom(token_kind=here.kind):+> ast_node;
            back = [here <-:BuildsAst:<-];
            if back {
                doc = back[0];
                idx = len([doc ->:Child:->]);
                doc +>:Child(index=idx):+> ast_node;
            }
            self.report_lines.append(label);
        }
        visit [->:NextToken:->] else {
            print(f"parse finished: {len(self.report_lines)} nodes, "
                  f"{len(self.errors)} errors");
            disengage;
        }
    }
}

walker Renderer {
    has lines: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can render with AstNode entry {
        prefix = "#" if here.magic == "HASH" else "  ";
        self.lines.append(f"{prefix}{here.label}");
        visit [->:Child:->] else { disengage; }
    }
}

with entry {
    doc = AstNode(label="CFWeaverDoc", magic="ROOT");
    t1 = Token(kind="HASH", text="# Factors");
    t2 = Token(kind="TEXT", text="Direct effects");
    t3 = Token(kind="TEXT", text="Amplifies");
    root ++> doc;
    doc +>:BuildsAst:+> t1;
    t1 +>:NextToken:+> t2;
    t2 +>:NextToken:+> t3;
    root spawn Parser();
    root spawn Renderer();
    print("render complete");
}

"""Reviewer readback: verify a local dirty candidate against trusted evidence.

A readback request must bind to trusted review-bundle evidence (repo, issue,
parent comment, branch/base HEAD, allowed files, manifest digest). The
readback walker traverses Evidence -> Candidate -> FileChunk edges, re-reads
each chunk, and fails closed on any mismatch, forbidden file, or secret-like
content. Publication is never acceptance.
"""

node Evidence {
    has repo: str = "";
    has issue: int = 0;
    has parent_comment: str = "";
    has branch: str = "";
    has base_head: str = "";
    has trusted: bool = True;
}

node Candidate {
    has branch: str = "";
    has base_head: str = "";
    has manifest_digest: str = "";
    has dirty: bool = True;
}

node FileChunk {
    has path: str = "";
    has seq: int = 0;
    has content: str = "";
    has declared_digest: str = "";

    def allowed_via_parent() -> bool {
        return len([<-:Includes:--]) > 0;
    }
}

edge BoundTo { }
edge Includes {
    has allowed: bool = True;
}
edge SplitInto { }

def digest_of(text: str) -> str {
    total = 0;
    for (i, ch) in enumerate(text) {
        total = (total + (ord(ch) * (i + 1))) % 100000;
    }
    return str(total);
}

walker ReadbackAuditor {
    has found: list[str] = [];
    has verdict: str = "PENDING";

    can start with Root entry {
        visit [->:BoundTo:->];
    }

    can check_evidence with Evidence entry {
        if not here.trusted {
            self.verdict = "REJECTED: untrusted parent evidence";
            disengage;
        }
        visit [->:BoundTo:->];
    }

    can check_candidate with Candidate entry {
        if not here.dirty {
            self.verdict = "REJECTED: reviewed candidate must be dirty";
            disengage;
        }
        visit [->:SplitInto:->];
    }

    can check_chunk with FileChunk entry {
        if not here.allowed_via_parent() {
            self.verdict = "REJECTED: file not in manifest";
            disengage;
        }
        actual = digest_of(here.content);
        if actual != here.declared_digest {
            self.verdict = f"REJECTED: digest mismatch on {here.path}";
            disengage;
        }
        if "SECRET" in here.content or "AKIA" in here.content {
            self.verdict = f"REJECTED: secret-like material in {here.path}";
            disengage;
        }
        self.found.append(here.path);
        visit [-->] else {
            self.verdict = "ACCEPTED: exact candidate readback verified";
        }
    }
}

with entry {
    # Trusted review-bundle evidence from #284, bound to the dirty candidate.
    ev = Evidence(repo="HarryWhite-TW/local-ai-workbench", issue=284,
                  parent_comment="5394902606", branch="feat/readback",
                  base_head="abc123", trusted=True);
    cand = Candidate(branch="feat/readback", base_head="abc123",
                     manifest_digest="m1");
    f1 = FileChunk(path="bridge.py", seq=0, content="handler glue",
                   declared_digest=digest_of("handler glue"));
    f2 = FileChunk(path="runner.py", seq=1, content="bounded runner patch",
                   declared_digest=digest_of("bounded runner patch"));

    root +>:BoundTo:+> ev;
    ev +>:BoundTo:+> cand;
    cand +>:Includes(allowed=True):+> f1;
    cand +>:Includes(allowed=True):+> f2;
    cand +>:SplitInto:+> f1;
    cand +>:SplitInto:+> f2;

    audit = ReadbackAuditor();
    root spawn audit;
    print(f"readback files={audit.found} verdict={audit.verdict}");

    # Tampered / untrusted variants must fail closed.
    bad_ev = Evidence(repo="HarryWhite-TW/local-ai-workbench", issue=284,
                      parent_comment="bogus", branch="feat/readback",
                      base_head="abc123", trusted=False);
    bad_cand = Candidate(branch="wrong", base_head="old",
                         manifest_digest="x", dirty=True);
    bad_f = FileChunk(path="secrets.env", seq=0, content="AKIA1234",
                      declared_digest=digest_of("AKIA1234"));
    root +>:BoundTo:+> bad_ev;
    bad_ev +>:BoundTo:+> bad_cand;
    bad_cand +>:Includes(allowed=True):+> bad_f;
    bad_cand +>:SplitInto:+> bad_f;

    audit2 = ReadbackAuditor();
    root spawn audit2;
    print(f"tampered verdict={audit2.verdict}");
}

"""Bundle budget auditor: walk the import graph, flag oversized eagerly-loaded chunks."""

edge Imports { }
edge LazyLoads { }

node Chunk {
    has name: str = "";
    has size_kb: float = 0.0;
    has gzip_kb: float = 0.0;
    has lazy: bool = False;
