"""CaseGraph package indexer: recursively inventory a package folder,
record file metadata, and derive sidecar-linked artifacts while guarding
against directory cycles and stale derivations."""

edge ContainsFolder { }
edge Contains {
    has kind: str = "file";
}
edge DerivedFrom {
    has extractor: str = "";
}

node PackageFolder {
    has name: str = "";
    has managed_writes: bool = False;
}

node FileEntry {
    has rel_path: str = "";
    has media_type: str = "";
    has size: int = 0;
    has sha256: str = "";
    has status: str = "indexed";
}

node DerivedArtifact {
    has name: str = "";
    has source_sha256: str = "";
}

walker Indexer {
    has seen: dict = {};
    has stale_derivations: list = [];
    has artifacts: list = [];
    has depth: int = 0;
    has max_depth: int = 16;
    has pkg_managed: bool = False;

    can start with Root entry {
        visit [->:ContainsFolder:->];
    }

    can enter_folder with PackageFolder entry {
        # Cycle guard: no built-in visitation dedupe, so track explicitly.
        key = here.name;
        if key in self.seen {
            print(f"cycle detected at folder {key}; skipping");
            disengage;
        }
        self.seen[key] = True;
        self.depth += 1;
        if self.depth > self.max_depth {
            print(f"depth cap {self.max_depth} exceeded at {key}");
            disengage;
        }
        if here.managed_writes {
            self.pkg_managed = True;
        }
        print(f"entering package folder {key} (managed={here.managed_writes})");
        visit [->:ContainsFolder:->] else {
            visit [->:Contains:->] else { disengage; }
        }
        visit [->:Contains:->];
        self.depth -= 1;
    }

    can inventory with FileEntry entry {
        if here.media_type == "application/pdf" and here.rel_path.endswith("ruling.pdf") {
            if self.pkg_managed {
                derived = DerivedArtifact(
                    name="ruling.md",
                    source_sha256=here.sha256
                );
                here +>:DerivedFrom(extractor="pdf_md"):+> derived;
                self.artifacts.append(derived.name);
                print(f"[derived] {derived.name} from {here.rel_path} @ {derived.source_sha256}");
            } else {
                print(f"[skipped-derivation] {here.rel_path}: package not managed");
            }
        } elif here.media_type == "" {
            here.status = "unsupported";
            print(f"[unsupported] {here.rel_path}");
        } else {
            print(f"[indexed] {here.rel_path} ({here.media_type}, {here.size}B, {here.sha256[:8]})");
        }
    }

    can inspect_artifact with DerivedArtifact entry {
        # A changed source SHA vs the recorded one flags a stale derivation.
        if here.source_sha256 == "" {
            self.stale_derivations.append(here.name);
            print(f"[stale?] {here.name}: no source hash recorded");
        }
    }

    can report with Root exit {
        print(f"inventory complete: artifacts={self.artifacts}, "
              f"stale={self.stale_derivations}, folders_seen={list(self.seen.keys())}");
    }
}

