"""DAG orchestration: ContextGraphBuilder-style task graph with cycle detection and topological scheduling.

Tasks are nodes, dependencies are typed DependsOn edges pointing from
dependency to dependent. A Probe walker DFS-checks for cycles; a Runner
walker executes nodes once all their dependencies are complete,
releasing dependents as predecessors finish.
"""

node Task {
    has name: str = "";
    has done: bool = False;
    has order: int = -1;

    def ready() -> bool {
        deps = [d for d in [-->:DependsOn:-->]];
        return all(d.done for d in deps);
    }
}

edge DependsOn { }

walker Probe {
    has stack: list[str] = [];
    has seen: set = set();
    has has_cycle: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can dfs with Task entry {
        if here.name in self.stack {
            self.has_cycle = True;
            print(f"CYCLE detected through task '{here.name}'");
            disengage;
        }
        if here.name in self.seen {
            return;
        }
        self.seen.add(here.name);
        self.stack.append(here.name);
        visit [-->:DependsOn:-->];
        self.stack.pop();
    }
}

walker Runner {
    has clock: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can run with Task entry {
        if here.done {
            return;
        }
        if not here.ready() {
            disengage;
        }
        self.clock += 1;
        here.done = True;
        here.order = self.clock;
        print(f"[t{self.clock}] run {here.name}");
        visit [-->];
    }
}

with entry {
    fetch_order = Task(name="fetch_order");
    fetch_customer = Task(name="fetch_customer");
    validate = Task(name="validate");
    save = Task(name="save");

    # dependencies: validate depends on both fetches, save on validate
    fetch_order +>:DependsOn:+> validate;
    fetch_customer +>:DependsOn:+> validate;
    validate +>:DependsOn:+> save;

    root ++> fetch_order ++> fetch_customer ++> validate ++> save;

    root spawn Probe();
    root spawn Runner();

    print("cycle-free: DAG accepted, scheduling completed");
}

"""Single-WSG downstream-state guard: fail loud when downstream dams aren't persisted.

Runs a WSG DS-first; before computing access it walks downstream via typed
DrainsTo edges and verifies every downstream group holding a dam barrier is
already persisted. A missing persistence is an error, not a silent wrong answer.
"""

node WSG {
    has name: str = "";
    has persisted: bool = False;
}

node Dam {
    has barrier_id: str = "";
}

edge DrainsTo { }
edge HasBarrier { }

walker DownstreamGuard {
    has target: str = "";
    has visited: dict[str, bool] = {};

    can start with Root entry {
        visit [->:DrainsTo:->];
    }

    can check with WSG entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited[here.name] = True;
        if here.name == self.target {
            print(f"computing access for {here.name}");
        } elif not here.persisted {
            dams = [here->:HasBarrier:->];
            if len(dams) > 0 {
                print(f"GUARD FAIL: downstream group {here.name} has "
                      f"{len(dams)} dam barrier(s) but is not persisted; "
                      f"access would be wrong");
                disengage;
            } else {
                print(f"downstream {here.name} not persisted but barrier-free, ok");
            }
        } else {
            print(f"downstream {here.name} persisted, ok");
        }
        visit [->:DrainsTo:->] else { disengage; }
    }
}

