"""Recursive call graph resolution with cycle guard: walker traverses Calls
edges but remembers visited callees, so a recursive call terminates instead
of timing out (issue #3704)."""

node FunctionDef {
    has name: str = "";
    has is_nested: bool = False;
}

node CallSite {
    has depth_limit: int = 50;
}

edge Calls { }

edge Resolved {
    has hops: int = 0;
}

walker Resolver {
    has visited: dict = {};
    has hops: int = 0;
    has found: list = [];

    can start with Root entry {
        visit [-->];
    }

    can enter_site with CallSite entry {
        visit [->:Calls:->];
    }

    can resolve with FunctionDef entry {
        key = here.name;
        if key in self.visited {
            print(f"cycle detected at {key}; cutting off recursion");
            return;
        }
        self.visited[key] = True;
        self.hops += 1;
        status = "nested" if here.is_nested else "flat";
        if self.hops > 0 {
            self.found.append(f"{here.name}({status})");
        }
        if self.hops >= 50 {
            print("depth limit reached; disengaging");
            disengage;
        }
        visit [->:Calls:->] else { disengage; }
    }
}

with entry {
    f = FunctionDef(name="factorial");
    g = FunctionDef(name="helper", is_nested=True);
    h = FunctionDef(name="inner", is_nested=True);

    site = CallSite();
    root ++> site;

    # factorial -> helper -> inner -> factorial (recursive cycle)
    site +>:Calls:+> f;
    f +>:Calls:+> g;
    g +>:Calls:+> h;
    h +>:Calls:+> f;

    r = Resolver();
    root spawn r;
    print(f"resolved {len(r.found)} functions in {r.hops} hops without timeout");
}

"""Call graph builder: walks method call edges with a visited-set cycle guard.

Models kirin issue #703: building a call graph must tolerate recursive
call graphs by tracking visited methods, so cycles appear as edges
(detectable recursion) instead of an unbounded descent.
"""

node Method {
    has name: str = "";
    has visited: bool = False;
}

edge Calls { }

walker GraphBuilder {
    has visited_names: list[str] = list();
    has recursive: list[str] = list();
    has edge_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can build with Method entry {
        """Descend over call edges, guarding against cycles with a visited set."""
        if here.visited {
            disengage;
        }
        here.visited = True;
        self.visited_names.append(here.name);
        callees = [here->:Calls:->];
        for callee in callees {
            if callee.visited {
                self.recursive.append(here.name);
            }
            self.edge_count += 1;
        }
        visit [->:Calls:->];
    }
}

walker RecursionChecker {
    has cycle_free: bool = True;

    can start with Root entry {
        visit [-->];
    }

    can check with Method entry {
        if here.visited {
            self.cycle_free = False;
        }
    }
}

with entry {
    # main calls helper and itself; helper calls main (mutual recursion).
    main = Method(name="main");
    helper = Method(name="helper");
    leaf = Method(name="leaf");

    main +>:Calls:+> helper;
    main +>:Calls:+> main;
    helper +>:Calls:+> main;
    helper +>:Calls:+> leaf;

    root ++> main;

    root spawn GraphBuilder();
    checker = RecursionChecker();
    root spawn checker;

    verdict = "recursive" if not checker.cycle_free else "acyclic";
    print(f"graph is {verdict}");
}

