"""Desired-vs-Current Delta planner: deltas become capability requirements,
plan steps with dependency edges, and a walker validates the plan for cycles
while tracing explainability back to desired-state conditions."""

node DeltaItem {
    has condition: str = "";
    has kind: str = "";          # violation | missing_capability | missing_evidence | unresolved_question
    has evidence: str = "";
    has capability: str = "";    # canonical CG-03 capability id, abstract

    def requirement() -> str {
        return f"{self.kind}:{self.capability} for '{self.condition}'";
    }
}

edge RequiresCapability {
    has rationale: str = "";
}

node PlanStep {
    has title: str = "";
    has verification: str = "";
}

edge DependsOn { }

node Plan {
    has name: str = "";
}

edge ContainsPlanStep { }

walker Planner {
    has seen: list[str] = [];
    has trace: str = "DesiredState";
    has depth: int = 0;
    has max_depth: int = 8;

    can start with Root entry {
        visit [-->];
    }

    can enter with Plan entry {
        print(f"Plan '{here.name}' validation walk:");
        self.trace = self.trace + f" -> Plan({here.name})";
        visit [->:ContainsPlanStep:->];
    }

    can enter_step with PlanStep entry {
        if here.title in self.seen {
            print(f"FAIL: cycle detected at '{here.title}' — plan rejected");
            disengage;
        }
        if self.depth > self.max_depth {
            print(f"FAIL: depth limit exceeded at '{here.title}' — plan rejected");
            disengage;
        }
        self.seen.append(here.title);
        self.depth += 1;
        self.trace = self.trace + f" -> {here.title}";
        print(f"STEP {here.title} (verify: {here.verification})");
        visit [->:RequiresCapability:->] else {
            self.depth -= 1;
        }
    }

    can explain with DeltaItem entry {
        print(f"  trace: {self.trace} | {here.requirement()} | evidence: {here.evidence}");
        visit [->:RequiresCapability:->];
    }
}

