    has depth_limit: int = 50;
}

edge Calls { }

walker Resolver {
    has visited: dict = {};
    has hops: int = 0;
    has found: list = [];

    can start with Root entry {
        visit [-->];
    }

    can enter_site with CallSite entry {
        visit [->:Calls:->];
    }

    can resolve with FunctionDef entry {
        key = here.name;
        if key in self.visited {
            print(f"cycle detected at {key}; cutting off recursion");
            disengage;
        }
        self.visited[key] = True;
        self.hops += 1;
        status = "nested" if here.is_nested else "flat";
        self.found.append(f"{here.name}({status})");
        if self.hops >= self.depth_limit {
            print("depth limit reached; disengaging");
            disengage;
        }
        visit [->:Calls:->] else { disengage; }
    }
}

