    # factorial -> helper -> inner -> factorial (recursive cycle)
    site +>:Calls:+> f;
    f +>:Calls:+> g;
    g +>:Calls:+> h;
    h +>:Calls:+> f;

    r = Resolver();
    root spawn r;
    print(f"resolved {len(r.found)} functions in {r.hops} hops without timeout");
}

