"""DAG orchestration: ContextGraphBuilder-style task graph with cycle detection and topological scheduling.

Tasks are nodes, dependencies are typed DependsOn edges pointing from
dependency to dependent. A Probe walker DFS-checks for cycles; a Runner
walker executes nodes once all their dependencies are complete, sweeping
in rounds so independent fetches run before validate, and validate
before save.
"""

node Task {
    has name: str = "";
    has done: bool = False;
    has order: int = -1;

    def ready() -> bool {
        deps_done = True;
        for d in [<--:DependsOn:--] {
            if not d.done {
                deps_done = False;
            }
        }
        return deps_done;
    }
}

edge DependsOn { }

walker Probe {
    has stack: list[str] = [];
    has seen: list[str] = [];
    has has_cycle: bool = False;

    def mark_seen(nm: str) -> bool {
        for s in self.seen {
            if s == nm {
                return False;
            }
        }
        self.seen.append(nm);
        return True;
    }

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can dfs with Task entry {
        for s in self.stack {
            if s == here.name {
                self.has_cycle = True;
                print(f"CYCLE detected through task '{here.name}'");
                disengage;
            }
        }
        if not self.mark_seen(here.name) {
            return;
        }
        self.stack.append(here.name);
        visit [->:DependsOn:->];
        self.stack.pop();
    }
}

walker Runner {
    has clock: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can run with Task entry {
        if here.done or not here.ready() {
            return;
        }
        self.clock += 1;
        here.done = True;
        here.order = self.clock;
        print(f"[t{self.clock}] run {here.name}");
        visit [<--:DependsOn:--];
    }
}

with entry {
    fetch_order = Task(name="fetch_order");
    fetch_customer = Task(name="fetch_customer");
    validate = Task(name="validate");
    save = Task(name="save");

    # dependencies: validate depends on both fetches, save on validate
    fetch_order +>:DependsOn:+> validate;
    fetch_customer +>:DependsOn:+> validate;
    validate +>:DependsOn:+> save;

    root ++> fetch_order ++> fetch_customer ++> validate ++> save;

    root spawn Probe();

    tasks = [fetch_order, fetch_customer, validate, save];
    rounds = 0;
    while rounds < 10 {
        root spawn Runner();
        all_done = True;
        for t in tasks {
            if not t.done {
                all_done = False;
            }
        }
        if all_done {
            break;
        }
        rounds += 1;
    }

    print("cycle-free: DAG accepted, scheduling completed");
}

"""Intra-type call graph analysis: captured state, caller->callee edges, cycle detection, forward-reference risks."""

node Member {
    has name: str = "";
    has kind: str = "function";  # function | val | property
    has captures: list[str] = [];  # captured state names
    is_static: bool = False;
}

