    has visited: dict = {};
    has on_stack: dict = {};
    has order: list[str] = [];
    has cycles: list[list[str]] = [];
    has captured_all: list[str] = [];

    can start with Root entry {
        visit [->:Calls:->];
    }

    can analyze with Member entry {
        # cycle guard: members may recurse or be mutually recursive
        if here.name in self.on_stack {
            cyc = self.order[(list(self.on_stack.keys()).index(here.name)):];
            cyc.append(here.name);
            self.cycles.append(cyc);
        }
        if here.name in self.visited {
            visit [-->] else { disengage; }
        } else {
            self.visited[here.name] = True;
            self.on_stack[here.name] = True;
            self.order.append(here.name);
            for cap in here.captures {
                if cap not in self.captured_all {
                    self.captured_all.append(cap);
                }
            }
            visit [->:Calls:->];
            # dead ends simply terminate
            visit [-->] else { disengage; }
        }
    }
}

