"""Configurable call-graph precision.

Callee relationships are typed edges: Calls for directly resolved calls,
StubCall for approximated calls through unknown bodies. The "fast"
precision walks only Calls (cheap, unsound); the "precise" precision
walks Calls then StubCall (sound, costlier, and it counts approximated
hops). An explicit visited guard is the cycle policy: walkers have no
built-in once-per-node visitation, so the recursion cycle in the demo
is detected and reported.
"""

node Function {
    has name: str = "";
}

edge Calls { }          # directly resolved callee edge
edge StubCall { }       # approximated callee edge (body unknown)

walker CallGraphAnalyzer {
    has precision: str = "fast";       # "fast" | "precise"
    has visited: dict = {};            # explicit cycle guard (domain logic)
    has reachable: list = [];
    has stub_hops: int = 0;            # approximated hops (precise only)
    has cycle_detected: bool = False;

    can start with Root entry {
        if self.precision == "precise" {
            visit [->:Calls:->];
            visit [->:StubCall:->];
        } else {
            visit [->:Calls:->] else { disengage; }
        }
    }

    can analyze with Function entry {
        if here.name in self.visited {
            self.cycle_detected = True;
            disengage;
        }
        self.visited[here.name] = True;
        self.reachable.append(here.name);
        if self.precision == "precise" {
            self.stub_hops += len([here ->:StubCall:->]);
            visit [->:Calls:->];
            visit [->:StubCall:->];
        } else {
            visit [->:Calls:->];
        }
    }
}

with entry {
    # caller -> callee graph, including a recursion cycle and a stub call
    main = Function(name="main");
    parse = Function(name="parse");
    lookup = Function(name="lookup");
    cache = Function(name="cacheMiss");
    root ++> main;
    main +>:Calls:+> parse;
    parse +>:Calls:+> lookup;
    lookup +>:StubCall:+> cache;
    cache +>:Calls:+> lookup;  # cycle: lookup <-> cache

    for level in ["fast", "precise"] {
        mode = "sound (follows stubs)" if level == "precise" else "cheap (skips stubs)";
        analyzer = CallGraphAnalyzer(precision=level);
        root spawn analyzer;
        print(f"precision={level} [{mode}] reachable={analyzer.reachable} "
              f"stub_hops={analyzer.stub_hops} cycle={analyzer.cycle_detected}");
    }
}

