"""Tiered role hierarchy: roles linked by ReportsTo edges, audited by a walker."""

node Role {
    has name: str = "";
    has sort_order: int = 0;
    has system_role: bool = False;
    can depth_limit() -> int { return 10; }
}

edge ReportsTo { }

walker Mover {
    has target: Role | None = None;
    has new_parent: Role | None = None;

    # Cycle prevention: a role may never be moved beneath its own descendant.
    can validate_move with Root entry {
        ok = True;
        if self.target is None or self.new_parent is None {
            ok = False;
        } else {
            frontier: list = [self.target];
            seen: list = [];
            while frontier {
                cur = frontier.pop();
                if cur is self.new_parent {
                    ok = False;
                }
                if cur in seen {
                    continue;
                }
                seen.append(cur);
                kids = [cur -->];
                for k in kids {
                    frontier.append(k);
                }
            }
        }
        verdict = "ALLOWED" if ok else "REJECTED (would create a cycle)";
        print(f"Move '{self.target.name}' under '{self.new_parent.name}': {verdict}");
        if ok {
            self.target +>:ReportsTo:+> self.new_parent;
            print(f"Reparent persisted: '{self.target.name}' -> '{self.new_parent.name}'");
        }
        visit [-->];
    }

    can audit with Role entry {
        indent = "    " * self.path_len(here);
        tag = " (system)" if here.system_role else "";
        print(f"{indent}{here.name}{tag}");
        visit [-->] else { }
    }

    def path_len(n: Role) -> int {
        depth = 0;
        cur: Role | None = n;
        while cur is not None {
            found: Role | None = None;
            for p in [cur <-:ReportsTo:-] {
                found = p;
                break;
            }
            cur = found;
            if cur is not None { depth += 1; }
        }
        return depth;
    }
}

