    has total: int = 0;
    has count: int = 0;
    has seen: dict = {};

    can start with Root entry {
        visit [->:Contains:->];
    }

    can begin with Feed entry {
        print(f"Folding feed '{here.name}'");
        visit [->:Contains:->];
    }

    # Each event's result depends on the accumulated state of all prior
    # events — the fold T[1..n-1] -> T[n] that WITH RECURSIVE performs.
    # Traversal order over the Next chain gives the sequence; a cycle in
    # the feed would revisit a seq, so we guard explicitly.
    can fold with Event entry {
        if here.seq in self.seen {
            print(f"cycle detected at event {here.seq}; stopping");
            disengage;
        }
        self.seen[here.seq] = True;
        self.total += here.payload;
        self.count += 1;
        print(f"event {here.seq}: state total={self.total}");
        visit [->:Next:->] else { disengage; }
    }
}

