Model the essential scenario as an OSP graph: a Module holds Box'd
Functions, each Box exposing element-reference sites. Sites that take
`&(*boxed).field[i]` directly are flagged UNSAFE (the miscompile shape);
sites hoisted into a local first (`var el = (*boxed).field[i]`) are SAFE.
An Auditor walker traverses the typed Box/Ref edges and audits every site,
so no occurrence of the hazard can silently ship.
"""

node Module {
    has name: str = "";
}

edge Boxes { }

node Function {
    has name: str = "";
    has element_count: int = 0;
}

edge Exposes { }

node ElementRef {
    has expr: str = "";
    has hoisted: bool = False;
}

walker Auditor {
    has safe_sites: int = 0;
    has unsafe_sites: int = 0;

    can start with Root entry {
        visit [->:Boxes:->];
    }

    can inspect_fn with Function entry {
        visit [->:Exposes:->];
    }

    can audit with ElementRef entry {
        verdict = "SAFE  " if here.hoisted else "UNSAFE";
        if here.hoisted {
            self.safe_sites += 1;
        } else {
            self.unsafe_sites += 1;
        }
        print(f"[{verdict}] {here.expr}");
    }

    can finish with Root exit {
        report(f"audit: {self.safe_sites} safe, {self.unsafe_sites} unsafe");
    }
}

