    can analyse with ResearchRecord entry {
        # Cycle policy: explicit guard set — a record must never be marked twice.
        for v in self.visited {
            if v == here {
                disengage;
            }
        }
        self.visited.append(here);
        here.state = "REVIEW_REQUIRED";
        self.affected += 1;
        print(f"record '{here.title}' marked REVIEW_REQUIRED");
        visit [->:DependsOn:->] else { disengage; }
    }

    can find_snapshot with AnswerSnapshot entry {
