        # Invariant 5: no UPDATE/DELETE — preserve original, append replacement.
        original = here;
        replacement = AnswerSnapshot(
            question=original.question,
            answer=f"[corrected] {original.answer}",
            correction_state="REVIEW_REQUIRED"
        );
        original ++>:ReplacedBy:++> replacement;
        corr = Correction(reason=self.reason, status="REVIEW_REQUIRED");
        original ++> corr ++> replacement;
        print(f"preserved original, created replacement for '{original.question}'");
    }

    can flag_records with ResearchRecord entry {
        here.state = "REVIEW_REQUIRED";
        print(f"impact: record '{here.title}' flagged");
        visit [-->];
    }
}

