"""Quest prerequisite cycle detection: walks `UnlocksAfter` edges and reports quests stuck in cycles."""

node Quest {
    has title: str = "";
    has qid: str = "";
}

edge UnlocksAfter { }

walker CycleDetector {
    has in_stack: dict[str, bool] = {};
    has visited: dict[str, bool] = {};
    has cycle_quests: list[str] = [];
    has path: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can detect with Quest entry {
        if here.qid in self.in_stack {
            start_idx = 0;
            for (i, q) in enumerate(self.path) {
                if q == here.qid {
                    start_idx = i;
                }
            }
            cycle = self.path[start_idx:] + [here.qid];
            cycle_str = " -> ".join(cycle);
            print(f"CYCLE DETECTED: {cycle_str}");
            for qid in cycle {
                if qid not in self.cycle_quests {
                    self.cycle_quests.append(qid);
                    print(f"flagging quest {qid} as part of a cycle");
                }
            }
            disengage;
        }
        if here.qid in self.visited {
            return;
        }
        self.visited[here.qid] = True;
        self.in_stack[here.qid] = True;
        self.path.append(here.qid);
        visit [->:UnlocksAfter:->] else {
            self.path.pop();
            self.in_stack[here.qid] = False;
        }
        if here.qid in self.path {
            self.path.pop();
            self.in_stack[here.qid] = False;
        }
    }
}

