"""Issue #1678: address-of into a boxed aggregate's array element is a wrong address.

A Module Boxes Functions; each Box exposes element-reference sites. Sites
taking `&(*boxed).field[i]` directly are UNSAFE (the miscompile shape);
sites hoisted into a local first are SAFE. An Auditor walker traverses the
typed edges and audits every site so the hazard cannot silently ship.
"""

edge Boxes { }
edge Exposes { }

node Module {
    has name: str = "";
}

node Function {
    has name: str = "";
    has element_count: int = 0;
}

node ElementRef {
    has expr: str = "";
    has hoisted: bool = False;
}

walker Auditor {
    has safe_sites: int = 0;
    has unsafe_sites: int = 0;

    can start with Root entry {
        visit [->:Boxes:->] else { disengage; };
    }

    can inspect_fn with Function entry {
        visit [->:Exposes:->];
    }

    can audit with ElementRef entry {
        verdict = "SAFE  " if here.hoisted else "UNSAFE";
        if here.hoisted {
            self.safe_sites += 1;
        } else {
            self.unsafe_sites += 1;
        }
        print(f"[{verdict}] {here.expr}");
        visit [->:Exposes:->] else { visit [<--:Exposes:--] else { visit [<--:Boxes:--]; }; };
    }

    can finish with Root exit {
        report(f"audit: {self.safe_sites} safe, {self.unsafe_sites} unsafe");
    }
}

with entry {
    m = Module(name="ir-arena");
    root +>:Boxes:+> m;

    seal = Function(name="ir_module_seal_functions", element_count=7);
    bits = Function(name="ir_float_bits_get", element_count=64);
    m +>:Exposes(via="Box"):+> seal;
    m +>:Exposes(via="Box"):+> bits;

    # the hazard shape: &(*module).functions[i] taken directly
    seal +>:Exposes(via="element ref"):+> ElementRef(
        expr="&(*module).functions[i]",
        hoisted=False
    );
    # the one-line workaround: hoist the element to a local first
    bits +>:Exposes(via="element ref"):+> ElementRef(
        expr="var el = (*module).functions[i]; ir_float_bits_get(&el)",
        hoisted=True
    );

    root spawn Auditor();
}

