"""Tiered role hierarchy: roles linked by ReportsTo edges, audited by a walker."""

node Role {
    has name: str = "";
    has sort_order: int = 0;
    has system_role: bool = False;
}

edge ReportsTo { }

walker Mover {
    has target: Role | None = None;
    has new_parent: Role | None = None;
    has depth: int = 0;

    # Cycle prevention: a role may never be moved beneath its own descendant.
    can validate_move with Root entry {
        t = self.target;
        p = self.new_parent;
        ok = t is not None and p is not None;
        if ok {
            frontier: list = [t];
            seen: list = [];
            while frontier {
                cur = frontier.pop();
                if cur is p {
                    ok = False;
                }
                if cur in seen {
                    continue;
                }
                seen.append(cur);
                for k in [cur -->] {
                    frontier.append(k);
                }
            }
        }
        verdict = "ALLOWED" if ok else "REJECTED (would create a cycle)";
        print(f"Move '{t.name if t is not None else '?'}' under '{p.name if p is not None else '?'}': {verdict}");
        if ok {
            t +>:ReportsTo:+> p;
            print(f"Reparent persisted: '{t.name}' -> '{p.name}'");
        }
        visit [-->];
    }

    can audit with Role entry {
        indent = "    " * self.depth;
        tag = " (system)" if here.system_role else "";
        print(f"{indent}{here.name}{tag}");
        child_depth = self.depth + 1;
        here spawn Auditor(depth=child_depth);
    }
}

walker Auditor {
    has depth: int = 0;

    can audit with Role entry {
        indent = "    " * self.depth;
        tag = " (system)" if here.system_role else "";
        print(f"{indent}{here.name}{tag}");
        child_depth = self.depth + 1;
        here spawn Auditor(depth=child_depth);
    }
}

