"""Knowledge graph: context items as nodes, typed relationship edges, BFS-style walker traversal with depth cap and visited guard."""

node ContextNode {
    has label: str = "";
    has node_type: str = "";
    has context_item_id: str = "";
}

edge RelatedTo { has weight: float = 1.0; }
edge DependsOn { has weight: float = 1.0; }
edge Supports { has weight: float = 1.0; }

walker GraphBuilder {
    can start with Root entry {
        visit [-->];
    }

    can inspect with ContextNode entry {
        print(f"node: {here.label} ({here.node_type})");
    }
}

walker RelatedFinder {
    has max_depth: int = 2;
    has found: list = [];
    has visited: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can search with ContextNode entry {
        """Depth-limited, cycle-guarded traversal over typed edges (both directions)."""
        if here in self.visited {
            disengage;
        }
        self.visited[here] = True;
        if self.visited.len() > 1 {
            self.found.append(here.label);
            print(f"related: {here.label} at depth {self.visited.len() - 1}");
        }
        if self.visited.len() - 1 >= self.max_depth {
            disengage;
        }
        visit [->:RelatedTo:->];
        visit [<--:RelatedTo:--];
        visit [->:DependsOn:->];
        visit [<--:DependsOn:--];
    }
}

