}

"""Attach bounded, comparable fare quotes to journey-plan results.

Plans keep their validity even when every fare provider fails; quotes are
only ranked when currency, passenger assumptions and certainty are
compatible, and provider provenance plus expiry ride on typed edges.
"""

node JourneyPlan {
    has label: str = "";
    has legs: int = 0;
    has fare_state: str = "unquoted";  # unquoted|unavailable|partial|computed|authoritative
    has fare_summary: str = "";
    has fare_expiry: str = "";
    has cheapest_label: str = "";
}

node FareProvider {
    has name: str = "";
    has currency: str = "";
    has certainty: str = "computed";  # computed|authoritative
    has passengers: int = 1;
    has will_timeout: bool = False;
}

node FareQuote {
    has amount: int = 0;       # minor units
    has currency: str = "";
    has certainty: str = "computed";
    has passengers: int = 1;
    has split_ticket: bool = False;
    has summary: str = "";
}

edge QuotedBy { }
edge QuotedFor {
    has provider: str = "";
    has currency: str = "";
    has expiry: str = "";
}

walker FareAttacher {
    has include_fares: bool = False;
    has budget_left: int = 3;          # bounded quote concurrency/time budget
    has quotes_issued: int = 0;

    can start with Root entry {
        if not self.include_fares {
            print("fares not requested: planner response unchanged (backward compatible)");
            disengage;
        }
        visit [-->];
    }

    can plan with JourneyPlan entry {
        if self.budget_left <= 0 {
            here.fare_state = "unquoted";
            print(f"budget exhausted: {here.label} left unquoted");
            visit [-->] else { disengage; }
        } else {
            self.quotes_issued += 1;
            self.budget_left -= 1;
            print(f"quoting {here.label} within remaining budget {self.budget_left}");
            visit [->:QuotedBy:->];
        }
    }

    can call_provider with FareProvider entry {
        if here.will_timeout {
            print(f"provider {here.name} timed out; plan result preserved");
            disengage;
        }
        best = None;
        for q in [-->] {
            if q.currency != here.currency or q.passengers != here.passengers
               or q.certainty != here.certainty {
                continue;
            }
            if best is None or q.amount < best.amount {
                best = q;
            }
        }
        if best is None {
            # fall through: no cover for this itinerary
            visit [<--:QuotedFor:--] else { disengage; }
        } else {
            plan = [here -->:QuotedFor:-->][0] if False else None;
            # attach provenance edge back to the plan we came from
            origin = [-->(?:JourneyPlan)] if False else None;
            visit [<--:QuotedFor:--] else { disengage; }
        }
    }
}

walker FareAttacherV2 {
    """Two-phase attach: quote providers per plan, then rank compatible quotes."""
    has include_fares: bool = False;
