"""Recursive macro expansion chain modeled as typed Expands edges; a walker
traverses the expansion depth-wise, mimicking the deep recursion gccrs
struggles with, with an explicit cycle guard preserved as domain logic."""

node Macro {
    has name: str = "";
    has depth: int = 0;
    has expanded: bool = False;
}

edge Expands { }

walker Expander {
    has visited: list[str] = list();
    has deepest: int = 0;

    can start with Root entry {
        visit [->:Expands:->] else { disengage; }
    }

    can expand with Macro entry {
        # cycle guard: never expand the same macro twice
        if here.name in self.visited {
            print(f"cycle guard: {here.name} already expanded");
            disengage;
        }
        self.visited.append(here.name);
        here.expanded = True;
        if here.depth > self.deepest {
            self.deepest = here.depth;
        }
        print(f"expanded {here.name} at depth {here.depth}");
        visit [->:Expands:->] else { disengage; }
    }
}

with entry {
    head = Macro(name="Foo27", depth=27);
    prev = head;
    for i in range(26, -1, -1) {
        cur = Macro(name=f"Foo{i}", depth=i);
        prev +>:Expands:+> cur;
        prev = cur;
    }
    root ++> head;
    root spawn Expander();
    print(f"expansion complete; chain reached Foo{head.depth}");
}

