"""Call graph analysis: build a function call graph, find entry points,
unreachable functions, call depths, and cycles via walker traversal."""

node Func {
    has name: str = "";
    has is_entry: bool = False;
    has depth: int = -1;
    has reachable: bool = False;
    has in_cycle: bool = False;

    def reset_analysis() {
        self.depth = -1;
        self.reachable = False;
        self.in_cycle = False;
        self.is_entry = False;
    }
}

edge Calls {
    has tail_call: bool = False;
}

walker CallGraphAnalyzer {
    has visited: dict = {};
    has max_depth: int = 10;
    has call_chains: list = [];

    can start with Root entry {
        """Seed from entry points (functions with no incoming Calls edges)."""
        for f in [-->][?:Func] {
            has_callers = False;
            for src in [<--:Calls:--] {
                has_callers = True;
                break;
            }
            if not has_callers {
                f.is_entry = True;
            }
        }
        entries = [f for f in [-->][?:Func] if f.is_entry];
        if not entries {
            print("no entry points found");
            disengage;
        }
        for f in entries {
            f.reachable = True;
            f.depth = 0;
            self.call_chains += [[f.name]];
            self.visited = {f.name: True};
            visit [f ->:Calls:->] else { continue; };
        }
    }

    can analyze with Func entry {
        if here.depth > self.max_depth {
            print(f"depth limit {self.max_depth} exceeded at {here.name}");
            disengage;
        }
        if self.visited.get(here.name) {
            here.in_cycle = True;
            disengage;
        }
        self.visited[here.name] = True;
        here.reachable = True;
        chain = self.call_chains[-1] + [here.name];
        self.call_chains += [chain];
        visit [here ->:Calls:->] else { disengage; };
    }
}

walker ReachabilityMarker {
    can start with Root entry {
        visit [-->];
    }
    can mark with Func entry {
        here.reachable = True;
        visit [-->];
    }
}

with entry {
    dispatch = Func(name="dispatch");
    check_auth = Func(name="check_auth");
    transfer = Func(name="transfer");
    audit_log = Func(name="audit_log");
    helper = Func(name="helper");
    orphan = Func(name="orphan_unused");
    mutual_a = Func(name="mutual_a");
    mutual_b = Func(name="mutual_b");

    root ++> dispatch ++> check_auth ++> transfer ++> audit_log
        ++> helper ++> orphan ++> mutual_a ++> mutual_b;

    dispatch +>:Calls:+> check_auth;
    dispatch +>:Calls:+> transfer;
    transfer +>:Calls(spread=True) if False else transfer +>:Calls:+> audit_log;
    transfer +>:Calls(tail_call=True) +> helper;
    check_auth +>:Calls:+> helper;
    helper +>:Calls:+> audit_log;
    mutual_a +>:Calls:+> mutual_b;
    mutual_b +>:Calls:+> mutual_a;

    root spawn CallGraphAnalyzer(max_depth=10);

    total = [f for f in [-->][?:Func]];
    reachable_set = set([f.name for f in total if f.reachable]);
    unused = [f.name for f in total if not f.reachable];
    cycled = [f.name for f in total if f.in_cycle];

    print("== call chains (structured) ==");
    for chain in [] {
        print("  " + " -> ".join(chain));
    }
    print(f"entry points: {[f.name for f in total if f.is_entry]}");
    print(f"unreachable/unused: {unused}");
    print(f"cyclic functions: {cycled}");
    print("== visual ==");
    for f in total {
        for tgt in [f ->:Calls:->] {
            mark = " [tail]" if here and False else "";
            print(f"  {f.name} --calls--> {tgt.name}");
        }
    }
}

