    has records_hit: int = 0;
    has teams: list[str] = list();

    can start with Root entry {
        visit [-->];
    }

    can propagate with DataSource | Transformation entry {
        if here.contaminated {
            self.systems_hit += 1;
            for t in [here->:OwnedBy:->] {
                if t.team not in self.teams { self.teams.append(t.team); }
            }
        }
        visit [->:FlowsTo:->];
    }

    can assess with Dashboard entry {
        if here.contaminated {
            self.dashboards_hit += 1;
            print(f"[IMPACT] dashboard '{here.name}' is consuming contaminated data");
        }
    }
}

walker RootCauseTracer {
    can start with Root entry {
        visit [-->];
    }

    can trace_back with Dashboard | Transformation entry {
        print(f"tracing root cause through '{here.name}'");
        visit [<--:FlowsTo:--];
    }

    can found_source with DataSource entry {
        verdict = "CONTAMINATED SOURCE" if here.contaminated else "clean source";
        print(f"root cause candidate: source '{here.name}' -> {verdict}");
    }
}

with entry {
    src = DataSource(name="CRM Extract", contaminated=True);
    t1 = Transformation(name="Cleanse", records=1000);
    t2 = Transformation(name="Aggregate", records=950, contaminated=True);
    db = Dashboard(name="Revenue KPI");
    src +>:FlowsTo(label="raw"):+> t1;
    t1 +>:FlowsTo(label="clean"):+> t2;
    t2 +>:FlowsTo(label="agg"):+> db;
    t2 +>:OwnedBy(team="Finance"):+> db;
    root ++> src;

    auditor = root spawn ImpactAuditor();
    print(f"impact report: {auditor.systems_hit} systems, "
          f"{auditor.dashboards_hit} dashboards, teams={auditor.teams}");
    root spawn RootCauseTracer();
}

"""ETL pipeline lineage: stages as nodes, data flows as typed edges, audited by a lineage walker."""

node Stage {
    has name: str = "";
    has kind: str = "";
    has rows: int = 0;
    has quality_passed: bool = True;
}

edge FlowsTo {
    has records: int = 0;
}

edge Produces {
}

walker LineageAuditor {
    has total_rows: int = 0;
    has stage_count: int = 0;
    has has_failures: bool = False;
    has visited: dict = {};

    can start with Root entry {
        visit [->:Produces:->];
    }

    can audit with Stage entry {
        # Explicit visited guard: jac walkers have no built-in dedupe,
        # so a cyclic DAG would otherwise loop forever.
        if here.name in self.visited {
            print(f"cycle detected at {here.name}; stopping this branch");
            disengage;
        }
        self.visited[here.name] = True;
        self.stage_count += 1;
        status = "PASSED ✅" if here.quality_passed else "FAILED ❌";
        if not here.quality_passed {
            self.has_failures = True;
        }
        print(f"[{here.kind}] {here.name}: {here.rows} rows, quality {status}");
        visit [->:FlowsTo:->] else {
            print(f"lineage ends at {here.name}");
        }
    }
}

walker ThroughputMeter {
    has first_rows: int = -1;
    has last_rows: int = -1;

    can start with Root entry {
        visit [->:Produces:->];
    }

    can measure with Stage entry {
        if self.first_rows == -1 {
            self.first_rows = here.rows;
        }
        self.last_rows = here.rows;
        visit [->:FlowsTo:->];
    }

    can report with Stage exit {
        throughput = (self.last_rows - self.first_rows) / 3;
        print(f"pipeline throughput: {throughput} rows/second across 3 stage hops");
    }
}

with entry {
    extract = Stage(name="Extract", kind="CSV", rows=1000);
    validate = Stage(name="Validate", kind="GreatExpectations", rows=1000);
    transform = Stage(name="Transform", kind="Pandas/dbt", rows=950);
    load = Stage(name="Load", kind="PostgreSQL", rows=950);

    root +>:Produces:+> extract;
    extract +>:FlowsTo(records=1000):+> validate;
    validate +>:FlowsTo(records=1000):+> transform;
    transform +>:FlowsTo(records=950):+> load;
    load +>:FlowsTo(records=950):+> extract;  # back-pressure edge exercises cycle guard

    root spawn LineageAuditor();
    root spawn ThroughputMeter();
}
